B.aom=new A.a("926f2aca-8688-416e-b643-eb8bb530b16b","d616a312-1621-4ede-b53d-4d1b7ee1e4b1","\u042d\u0439 \u0444\u0430\u043b\u0430\u043a\u0438 \u0437\u0443\u0434\u0433\u0430\u0440\u0434, \u0432\u043e\u0439 \u0431\u0430\u0440 \u043e\u043d,","\u042d\u0439 \u0444\u0430\u043b\u0430\u043a\u0438 \u0437\u0443\u0434\u0433\u0430\u0440\u0434, \u0432\u043e\u0439 \u0431\u0430\u0440 \u043e\u043d,\n\u041a-\u04ef \u0431\u0430 \u0442\u0443, \u044d\u0439 \u0444\u0438\u0442\u043d\u0430\u04b7\u04ef\u0439, \u043c\u0430\u0444\u0442\u0443\u043d \u0448\u0443\u0434.\n\u04b2\u0430\u0440 \u043a\u04e3 \u0431\u0430 \u0448\u0430\u043c\u044a\u0438 \u0445\u0438\u0440\u0430\u0434 \u043d\u0430\u0434\u0438\u0434 \u0440\u0430\u04b3\u0430\u0442,\n\u041f\u0435\u0448\u0438 \u0442\u0443 \u043c\u0430\u0434\u04b3\u0443\u0448 \u0433\u0430\u0448\u0442\u0443 \u0428\u0430\u043c\u044a\u0443\u043d \u0448\u0443\u0434.\n\u0410\u0437 \u0447\u04e3 \u0434\u0430\u0440 \u043e\u04e3 \u04b3\u0430\u043c\u0435 \u0434\u0430\u0440\u0443\u043d, \u043a\u0438 \u0447\u0443\u043d\u0438\u043d\n\u041c\u0430\u0440\u0434\u0443\u043c\u04e3 \u0430\u0437 \u0445\u0430\u043b\u049b \u04b7\u0443\u043c\u043b\u0430 \u0431\u0435\u0440\u0443\u043d \u0448\u0443\u0434?\n\u0424\u0435\u044a\u043b\u0438 \u04b3\u0430\u043c\u0430 \u04b7\u0430\u0432\u0440 \u0433\u0430\u0448\u0442\u0443 \u043c\u0430\u043a\u0440\u0443 \u04b7\u0430\u0444\u043e,\n\u049a\u0430\u0432\u043b\u0438 \u04b3\u0430\u043c\u0430 \u0437\u0430\u0440\u049b\u0443 \u0432\u0430\u044a\u0434\u0430 \u0430\u0444\u0441\u0443\u043d \u0448\u0443\u0434.\n\u041c\u0443\u043b\u043a\u0438 \u04b7\u0430\u04b3\u043e\u043d \u0433\u0430\u0440 \u0431\u0430 \u0434\u0430\u0441\u0442\u0438 \u0434\u0435\u0432\u043e\u043d \u0431\u0443\u0434,")
B.aad=new A.a("e873cb8e-e546-4963-b2a7-1b4adce32c14","d616a312-1621-4ede-b53d-4d1b7ee1e4b1","\u0411\u043e\u0437 \u043a\u0443\u043d\u0443\u043d \u04b3\u043e\u043b\u04b3\u043e \u04b3\u0430\u043c-\u044d\u0434\u0443\u043d \u0448\u0443\u0434.","\u0411\u043e\u0437 \u043a\u0443\u043d\u0443\u043d \u04b3\u043e\u043b\u04b3\u043e \u04b3\u0430\u043c-\u044d\u0434\u0443\u043d \u0448\u0443\u0434.\n\u0411\u043e\u0437\u0438 \u04b3\u0443\u043c\u043e\u044e\u043d \u0447\u0443 \u04b7\u0443\u0493\u0434 \u0433\u0430\u0448\u0442 \u0445\u0438\u0440\u04e3,\n\u04b6\u0443\u0493\u0434\u0430\u043a\u0438 \u0448\u0443\u043c\u0443 \u0445\u0438\u0440\u04e3 \u04b3\u0443\u043c\u043e\u044e\u043d \u0448\u0443\u0434.\n\u0421\u0430\u0440 \u0431\u0430 \u0444\u0430\u043b\u0430\u043a \u0431\u0430\u0440\u043a\u0430\u0448\u0438\u0434 \u0431\u0435\u0445\u0438\u0440\u0430\u0434\u04e3,\n\u041c\u0430\u0440\u0434\u0443\u043c\u0438\u044e \u0441\u0430\u0440\u0432\u0430\u0440\u04e3 \u0434\u0430\u0440 \u043e\u04b3\u0443\u043d \u0448\u0443\u0434.\n\u0411\u043e\u0434\u0438 \u0444\u0443\u0440\u04ef\u043c\u043e\u044f\u0433\u04e3 \u0432\u0430\u0437\u0438\u0434 \u0430\u0437 \u04ef,\n\u0421\u0443\u0440\u0430\u0442\u0438 \u043d\u0435\u043a\u04e3 \u043d\u0430\u0436\u0430\u043d\u0434\u0443 \u043c\u0430\u04b3\u0437\u0443\u043d \u0448\u0443\u0434.\n\u0425\u043e\u043a\u0438 \u0425\u0443\u0440\u043e\u0441\u043e\u043d \u0447\u0443 \u0431\u0443\u0434 \u04b7\u043e\u0439\u0438 \u0430\u0434\u0430\u0431,\n\u041c\u0430\u044a\u043c\u0430\u043d\u0438 \u0434\u0435\u0432\u043e\u043d\u0438 \u043d\u043e\u043a\u0430\u0441 \u0430\u043a\u043d\u0443\u043d \u0448\u0443\u0434,\n\u04b2\u0438\u043a\u043c\u0430\u0442\u0440\u043e \u0445\u043e\u043d\u0430 \u0431\u0443\u0434 \u0411\u0430\u043b\u0445\u0443 \u043a\u0443\u043d\u0443\u043d\n\u0425\u043e\u043d\u0430-\u0448 \u0432\u0430\u0439\u0440\u043e\u043d\u0443 \u0431\u0430\u0445\u0442 \u0432\u043e\u0440\u0443\u043d \u0448\u0443\u0434.\n\u041c\u0443\u043b\u043a\u0438 \u0421\u0443\u043b\u0430\u0439\u043c\u043e\u043d \u0430\u0433\u0430\u0440 \u0425\u0443\u0440\u043e\u0441\u043e\u043d \u0431\u0443\u0434,\n\u0427\u0443\u043d\u043a\u0438 \u043a\u0443\u043d\u0443\u043d \u043c\u0443\u043b\u043a\u0438 \u0434\u0435\u0432\u0438 \u043c\u0430\u043b\u044a\u0443\u043d \u0448\u0443\u0434?...\n\u0411\u0430\u043d\u0434\u0430\u0438 \u044d\u0448\u043e\u043d \u0431\u0443\u0434\u0430\u043d\u0434 \u0442\u0443\u0440\u043a\u043e\u043d, \u043f\u0430\u0441\n\u04b2\u043e\u043b \u0433\u0430\u04b3 \u044d\u0434\u0443\u043d\u0443 \u0433\u043e\u04b3 \u044d\u0434\u0443\u043d \u0448\u0443\u0434.\n\u0411\u0430\u043d\u0434\u0430\u0438 \u0442\u0443\u0440\u043a\u043e\u043d \u0448\u0443\u0434\u0430\u043d\u0434 \u0431\u043e\u0437 \u043c\u0430\u0433\u0430\u0440\n\u041d\u0430\u04b7\u043c\u0438 \u0425\u0443\u0440\u043e\u0441\u043e\u043d \u043d\u0430\u04b3\u0441\u0443 \u043c\u0430\u0445\u0431\u0443\u043d \u0448\u0443\u0434.\n\u0427\u043e\u043a\u0430\u0440\u0438 \u049b\u0438\u0431\u04b7\u043e\u049b \u0448\u0443\u0434 \u0448\u0430\u0440\u0438\u0444 \u0437\u0438 \u0434\u0438\u043b\n\u04b2\u0443\u0440\u0440\u0430\u0438 \u04ef \u043f\u0435\u0448\u043a\u043e\u0440\u0438 \u0445\u043e\u0442\u0443\u043d \u0448\u0443\u0434.\n\u041b\u043e\u04b7\u0430\u0440\u0430\u043c, \u0430\u0440 \u043d\u043e\u049b\u0438\u0441\u043e\u043d \u0430\u043c\u0438\u0440 \u0448\u0443\u0434\u0430\u043d\u0434,\n\u0424\u0430\u0437\u043b \u0431\u0430 \u043d\u0443\u049b\u0441\u043e\u043d\u0443 \u043d\u0430\u049b\u0441 \u0431-\u0430\u0444\u0437\u0443\u043d \u0448\u0443\u0434.\n\u0428\u043e\u0438\u0440 \u0431\u0430 \u0445\u0443\u043b\u043e\u0441\u0430\u0435 \u043e\u043c\u0430\u0434\u0430\u0430\u0441\u0442, \u043a\u0438 \u0434\u0430\u0440 \u04b3\u0430\u0440 \u0437\u0430\u043c\u0438\u043d\u0435, \u043a\u0438 \u049b\u0430\u0434\u0430\u043c\u0438")
B.agN=new A.a("85c9b2ae-a46c-43c1-b0a4-b87901bd6545","d616a312-1621-4ede-b53d-4d1b7ee1e4b1","\u0411\u0430\u043b\u043e \u0440\u04ef\u044f\u0434 \u043d\u0430\u0431\u043e\u0442 \u0430\u043d\u0434\u0430\u0440 \u0437\u0430\u043c\u0438\u043d\u0435,","\u0411\u0430\u043b\u043e \u0440\u04ef\u044f\u0434 \u043d\u0430\u0431\u043e\u0442 \u0430\u043d\u0434\u0430\u0440 \u0437\u0430\u043c\u0438\u043d\u0435,\n\u041a\u0438 \u0430\u04b3\u043b\u0430\u0448 \u049b\u0430\u0432\u043c\u0438 \u04b2\u043e\u043c\u043e\u043d\u0430\u043d\u0434\u0443 \u049a\u043e\u0440\u0443\u043d.\n\u041d\u0430\u0431\u043e\u0442\u0438 \u043f\u0443\u0440\u0431\u0430\u043b\u043e \u0493\u0443\u0437\u0437\u0430\u0441\u0442\u0443 \u049b\u0438\u0431\u0447\u043e\u049b,\n\u041a\u0438 \u0440\u0443\u0441\u0442\u0430\u0441\u0442\u0430\u043d\u0434 \u0431\u0430\u0440 \u0430\u0442\u0440\u043e\u0444\u0438 \u04b6\u0430\u0439\u04b3\u0443\u043d.\n\u041d\u043e\u0441\u0438\u0440\u0438 \u0425\u0443\u0441\u0440\u0430\u0432, \u043a\u0438 \u0430\u0437 \xab\u043f\u043e\u043a \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0438 \u043e\u0437\u043e\u0434\u0430\u0433\u043e\u043d\xbb \u2013 \u0430\u0448\u0440\u043e\u0444\u043e\u043d\u0438")
B.aj_=new A.a("fb1e5158-bb77-4545-b440-31c0d68611f0","d616a312-1621-4ede-b53d-4d1b7ee1e4b1","\u0422\u0443\u0440\u043a\u043e\u043d \u0431\u0430 \u043f\u0435\u0448\u0438 \u043c\u0430\u0440\u0434\u043e\u043d \u0437-\u0438\u043d \u043f\u0435\u0448...","\u0422\u0443\u0440\u043a\u043e\u043d \u0431\u0430 \u043f\u0435\u0448\u0438 \u043c\u0430\u0440\u0434\u043e\u043d \u0437-\u0438\u043d \u043f\u0435\u0448 \u0434\u0430\u0440 \u0425\u0443\u0440\u043e\u0441\u043e\u043d\n\u0411\u0443\u0434\u0430\u043d\u0434 \u0445\u043e\u0440\u0443 \u043e\u04b7\u0438\u0437 \u04b3\u0430\u043c\u0447\u0443\u043d \u0437\u0430\u043d\u043e\u043d\u0438 \u0441\u0430\u0440\u043e\u04e3.\n\u0418\u043c\u0440\u04ef\u0437 \u0448\u0430\u0440\u043c \u043d-\u043e\u044f\u0434 \u043e\u0437\u043e\u0434\u0430\u0437\u043e\u0434\u0430\u0433\u043e\u043d\u0440\u043e\n\u041a\u0430\u0440\u0434\u0430\u043d \u0431\u0430 \u043f\u0435\u0448\u0438 \u0442\u0443\u0440\u043a\u043e\u043d \u043f\u0443\u0448\u0442 \u0430\u0437 \u0442\u0430\u043c\u0430\u044a \u0434\u0443\u0442\u043e\u04e3!")
B.ag2=new A.a("8e018425-b89c-4b49-b97f-15a13298321b","d616a312-1621-4ede-b53d-4d1b7ee1e4b1","\u0411\u0430\u0440\u0445\u043e\u0441\u0442\u0430\u043c \u0430\u0437 \u04b7\u043e\u044e \u0441\u0430\u0444\u0430\u0440 \u043f\u0435\u0448 \u0433\u0438\u0440...","\u0411\u0430\u0440\u0445\u043e\u0441\u0442\u0430\u043c \u0430\u0437 \u04b7\u043e\u044e \u0441\u0430\u0444\u0430\u0440 \u043f\u0435\u0448 \u0433\u0438\u0440\u0438\u0444\u0442\u0430\u043c,\n\u041d-\u0430\u0437 \u0445\u043e\u043d\u0430-\u043c \u0451\u0434 \u043e\u043c\u0430\u0434\u0443 \u043d-\u0430\u0437 \u0433\u0443\u043b\u0448\u0430\u043d\u0443 \u043c\u0430\u043d\u0437\u0430\u0440.\n\u0410\u0437 \u043f\u043e\u0440\u0441\u0438\u044e \u0442\u043e\u0437\u0438\u044e \u0430\u0437 \u04b3\u0438\u043d\u0434\u0438\u044e \u0430\u0437 \u0442\u0443\u0440\u043a\n\u0412-\u0430\u0437 \u0441\u0438\u043d\u0434\u0438\u044e \u0440\u0443\u043c\u0438\u044e \u0437\u0438 \u0438\u0431\u0440\u04e3 \u04b3\u0430\u043c\u0430 \u044f\u043a\u0441\u0430\u0440\n\u0412-\u0430\u0437 \u0444\u0430\u043b\u0441\u0430\u0444\u0438\u044e \u043c\u043e\u043d\u0430\u0432\u0438\u044e \u0441\u043e\u0431\u0438\u044e \u0434\u0430\u04b3\u0440\u04e3\n\u0414\u0430\u0440\u0445\u043e\u0441\u0442\u0430\u043c \u0438\u043d \u04b3\u043e\u04b7\u0430\u0442\u0443 \u043f\u0443\u0440\u0441\u0438\u0434\u0430\u043c \u0431\u0435\u043c\u0430\u0440\u2026\n\u041f\u0443\u0440\u0441\u0430\u043d\u0434\u0430 \u04b3\u0430\u043c\u0435\u0440\u0430\u0444\u0442\u0430\u043c \u0430\u0437 \u0438\u043d \u0448\u0430\u04b3\u0440 \u0431\u0430\u0434-\u043e\u043d \u0448\u0430\u04b3\u0440,\n\u04b6\u04ef\u044f\u043d\u0434\u0430 \u04b3\u0430\u043c\u0435\u0433\u0430\u0448\u0442\u0430\u043c \u0430\u0437 \u0438\u043d \u0431\u0430\u04b3\u0440 \u0431\u0430\u0434-\u043e\u043d \u0431\u0430\u0440.")
B.aez=new A.a("b5794007-e034-4ed3-a8c3-5a5dc8ecffb3","d616a312-1621-4ede-b53d-4d1b7ee1e4b1","\u0413\u0443\u0444\u0442\u0430\u043c, \u043a\u0438 \u043c\u0430\u0432\u0437\u0443\u0438 \u0448\u0430\u0440\u0438\u0430\u0442 \u043d\u0430 \u0431\u0430...","\u0413\u0443\u0444\u0442\u0430\u043c, \u043a\u0438 \u043c\u0430\u0432\u0437\u0443\u0438 \u0448\u0430\u0440\u0438\u0430\u0442 \u043d\u0430 \u0431\u0430 \u0430\u049b\u043b \u0430\u0441\u0442,\n\u0417\u0435\u0440\u043e \u043a\u0438 \u0431\u0430 \u0448\u0430\u043c\u0448\u0435\u0440 \u0448\u0443\u0434 \u0438\u0441\u043b\u043e\u043c \u043c\u0443\u049b\u0430\u0440\u0440\u0430\u0440.\n\u0422\u0430\u049b\u043b\u0438\u0434 \u043d\u0430\u043f\u0430\u0437\u0440\u0443\u0444\u0442\u0430\u043c\u0443 \u04b3\u0443\u04b7\u04b7\u0430\u0442 \u043d\u0430\u043d\u0438\u04b3\u0443\u0444\u0442\u0430\u043c,\n\u0417\u0435\u0440\u043e \u043a\u0438 \u043d\u0430\u0448\u0443\u0434 \u04b3\u0430\u049b\u049b \u0431\u0430 \u0442\u0430\u049b\u043b\u0438\u0434 \u043c\u0443\u0448\u0430\u04b3\u04b3\u0430\u0440.")
B.aqZ=new A.a("8104fb38-46f2-400b-ada4-674dc1365e9f","d616a312-1621-4ede-b53d-4d1b7ee1e4b1","\u04b6\u0443\u0437 \u0434\u0430\u0440\u0434\u0443 \u0440\u0430\u043d\u04b7 \u04b3\u0435\u0447 \u043d\u0430\u0433\u0430\u0440\u0434\u0438\u0434 \u04b3\u043e...","\u04b6\u0443\u0437 \u0434\u0430\u0440\u0434\u0443 \u0440\u0430\u043d\u04b7 \u04b3\u0435\u0447 \u043d\u0430\u0433\u0430\u0440\u0434\u0438\u0434 \u04b3\u043e\u0441\u0438\u043b\u0430\u043c\n\u0417-\u043e\u043d \u043a\u0430\u0441, \u043a\u0438 \u0441\u04ef\u0439\u0438 \u04ef \u0431\u0430 \u0443\u043c\u0435\u0434\u0438 \u0448\u0438\u0444\u043e \u0448\u0443\u0434\u0430\u043c.\n\u0412-\u0430\u0437 \u043c\u043e\u043b\u0443 \u0448\u043e\u04b3\u0443 \u043c\u0438\u0440 \u0447\u0443 \u043d\u0430\u0432\u043c\u0435\u0434 \u0448\u0443\u0434 \u0434\u0438\u043b\u0430\u043c,\n\u0417\u04e3 \u0430\u04b3\u043b\u0438 \u0442\u0430\u0439\u043b\u0430\u0441\u043e\u043d\u0443 \u0430\u043c\u043e\u043c\u0430-\u0432 \u0440\u0438\u0434\u043e \u0448\u0443\u0434\u0430\u043c.\n\u0413\u0443\u0444\u0442\u0430\u043c, \u043a\u0438 \u0440\u043e\u04b3\u0438 \u0434\u0438\u043d \u0431\u0438\u043d\u0430\u043c\u043e\u044f\u043d\u0434 \u043c\u0430\u0440 \u043c\u0430\u0440\u043e,\n\u0417\u0435\u0440\u043e \u043a\u0438 \u0437-\u0430\u04b3\u043b\u0438 \u0434\u0443\u043d\u0451 \u0434\u0438\u043b \u043f\u0443\u0440\u04b7\u0430\u0444\u043e \u0448\u0443\u0434\u0430\u043c.\n\u0413\u0443\u0444\u0442\u0430\u043d\u0434: \xab\u0428\u043e\u0434 \u0431\u043e\u0448, \u043a\u0438 \u0440\u0430\u0441\u0442\u04e3 \u0437\u0438 \u04b7\u0430\u0432\u0440\u0438 \u0434\u0430\u04b3\u0440\xbb,\n\u0422\u043e \u0448\u043e\u0434 \u0433\u0430\u0448\u0442 \u04b7\u043e\u043d\u0430\u043c\u0443 \u0430\u043d\u0434\u0430\u0440 \u043d\u0430\u0432\u043e \u0448\u0443\u0434\u0430\u043c\u2026\n\u0413\u0443\u0444\u0442\u0430\u043c: \xab\u0427\u0443 \u043d\u043e\u043c\u0430\u0448\u043e\u043d \u0443\u043b\u0430\u043c\u043e \u0431\u0443\u0434\u0443 \u043a\u043e\u0440 \u04b7\u0430\u0432\u0440,\n\u041a-\u0430\u0437 \u0434\u0430\u0441\u0442\u0438 \u0444\u0430\u049b\u0440\u0438 \u04b7\u0430\u04b3\u043b \u0431\u0430\u0434-\u044d\u0448\u043e\u043d \u0440\u0430\u04b3\u043e \u0448\u0443\u0434\u0430\u043c.\n\u0422\u043e \u0447\u0443\u043d \u0431\u0430 \u049b\u043e\u043b\u0443 \u049b\u0438\u043b\u0438 \u043c\u0430\u049b\u043e\u043c\u043e\u0442\u0438 \u043c\u0443\u0445\u0442\u0430\u043b\u0438\u0444\n\u0410\u0437 \u0443\u043c\u0440 \u0447\u0430\u043d\u0434 \u0441\u043e\u043b \u043c\u0438\u0451\u043d\u0448\u043e\u043d \u0444\u0430\u043d\u043e \u0448\u0443\u0434\u0430\u043c\xbb.\n\u0413\u0443\u0444\u0442\u0430\u043c: \xab\u0427\u0443 \u0440\u0438\u0448\u0432\u0430 \u0431\u0443\u0434\u0443 \u0440\u0438\u0451 \u043c\u043e\u043b\u0443 \u0437\u0443\u04b3\u0434\u0430\u0448\u043e\u043d,\n\u042d\u0439 \u041a\u0438\u0440\u0434\u0433\u043e\u0440, \u0431\u043e\u0437 \u0431\u0430 \u0447\u04e3 \u043c\u0443\u0431\u0442\u0430\u043b\u043e \u0448\u0443\u0434\u0430\u043c?\xbb")
