B.ak8=new A.a("aa39db51-bbff-42a7-b347-a0b85048df89","ef0f434c-c5a7-4cdd-b13a-35f999319fbf","\u0430\u043c\u0438\u043d \u0448\u0443\u0434\u0430\u0430\u0441\u0442.","\u0430\u043c\u0438\u043d \u0448\u0443\u0434\u0430\u0430\u0441\u0442.\n\u0411\u0435\u04b3, \u043a\u0438 \u0444\u0438\u043a\u0440\u0438 \u0444\u0430\u043d\u043e \u043a\u0443\u043d\u0435\u043c \u04ef\u0440\u043e,\n\u0412-\u0430\u0437 \u0441\u0430\u0440\u0438 \u0445\u0430\u043b\u049b \u0432\u043e \u043a\u0443\u043d\u0435\u043c \u04ef\u0440\u043e.\n\u049a\u0430\u0434\u0430\u0440\u0435 \u0437\u0430\u04b3\u0440 \u0434\u0430\u0440 \u0445\u0430\u043c\u0438\u0440 \u043a\u0443\u043d\u0435\u043c,\n\u0411\u0430\u04b3\u0440\u0438 \u04ef \u0447\u0430\u043d\u0434 \u043d\u043e\u043d \u0444\u0430\u0442\u0438\u0440 \u043a\u0443\u043d\u0435\u043c.\n\u0422\u043e \u0445\u04ef\u0440\u0430\u0434 \u0437-\u043e\u043d \u0444\u0430\u0442\u0438\u0440\u0443 \u043c\u0438\u0440\u0430\u0434 \u0437\u043e\u0440,\n\u041d\u0430\u043a\u0443\u043d\u0430\u0434 \u0445\u0430\u043b\u049b\u0440\u043e \u0434\u0438\u0433\u0430\u0440 \u043e\u0437\u043e\u0440\xbb.\n\u04b2\u0430\u0444\u0442 \u043d\u043e\u043d \u0431\u0430\u04b3\u0440\u0438 \u04ef \u0447\u0443\u043d\u043e\u043d \u043a\u0430\u0440\u0434\u0430\u043d\u0434,\n\u041c\u043e\u043d\u0434\u0430 \u043d\u043e\u043d \u0431\u0430\u0440 \u043a\u0430\u0444\u0430\u0448 \u0440\u0430\u0432\u043e\u043d \u043a\u0430\u0440\u0434\u0430\u043d\u0434.\n\u041d\u043e\u043d \u0433\u0438\u0440\u0438\u0444\u0442\u0443 \u0431\u0443\u0440\u0443\u043d \u0448\u0443\u0434 \u043e\u043d \u0434\u0430\u0440\u0432\u0435\u0448,\n\u0422\u043e \u0431\u0430\u0440\u0430\u0434 \u043d\u043e\u043d \u0431\u0430 \u0441\u04ef\u0439\u0438 \u0445\u043e\u043d\u0430\u0438 \u0445\u0435\u0448.\n\u0425\u043e\u043d\u0430\u0430\u0448 \u0434\u0443\u0440 \u0431\u0443\u0434 \u0437-\u043e\u043d \u043c\u0430\u043d\u0437\u0438\u043b,\n\u0411\u0435\u0448\u0430\u0435 \u0431\u0443\u0434 \u0434\u0430\u0440 \u043c\u0438\u0451\u043d \u04b3\u043e\u0438\u043b")
B.ani=new A.a("157ecaa2-bcca-4ff0-882e-475440194db5","ef0f434c-c5a7-4cdd-b13a-35f999319fbf","\u0411\u0443\u0434 \u0431\u0435\u0447\u043e\u0440\u0430 \u0442\u0430\u043a\u0437\u0430\u043d\u043e\u043d \u0434\u0430\u0440 \u0440\u043e\u04b3,","\u0411\u0443\u0434 \u0431\u0435\u0447\u043e\u0440\u0430 \u0442\u0430\u043a\u0437\u0430\u043d\u043e\u043d \u0434\u0430\u0440 \u0440\u043e\u04b3,\n\u041a\u0438 \u0433\u0438\u0440\u0438\u0444\u0442\u0430\u043d\u0434 \u0440\u0430\u04b3 \u0431\u0430\u0434-\u04ef \u043d\u043e\u0433\u043e\u04b3.\n\u04b2\u0430\u0444\u0442 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0438 \u0445\u043e\u0441\u0430\u0438 \u043c\u0435\u04b3\u0442\u0430\u0440,\n\u04b2\u0430\u0440 \u044f\u043a\u0435 \u0431\u0443\u0434 \u0430\u0437 \u043e\u043d \u0434\u0438\u0433\u0430\u0440 \u0431\u0435\u04b3\u0442\u0430\u0440.\n\u0410\u0437 \u0448\u0438\u043a\u043e\u0440 \u043e\u043c\u0430\u0434\u0430 \u04b3\u0430\u043c\u0430 \u0431\u0435\u0442\u043e\u0431,\n\u041d\u0430 \u0434\u0430\u0440 \u043e\u043d \u0440\u043e\u04b3 \u0445\u04ef\u0440\u0434\u0430 \u043d\u043e\u043d, \u043d\u0435 \u043e\u0431.\n\u04b2\u0430\u0444\u0442\u043e \u043d\u043e\u043d \u0437\u0438 \u043f\u0443\u0448\u0442\u0438 \u043e\u043d \u0434\u0430\u0440\u0432\u0435\u0448,\n\u0414\u0430\u0440\u0440\u0430\u0431\u0443\u0434\u0430\u043d\u0434, \u0441\u043e\u0445\u0442 \u0442\u0443\u044a\u043c\u0430\u0438 \u0445\u0435\u0448.\n\u04b2\u0430\u0444\u0442 \u0431\u0430\u0440\u043d\u043e \u0447\u0443 \u04b3\u0430\u0444\u0442 \u043d\u043e\u043d \u0445\u04ef\u0440\u0434\u0430\u043d\u0434,\n\u0411\u043e\u0437 \u0433\u0430\u0448\u0442\u0430\u043d\u0434\u0443 \u0434\u0430\u0440\u0437\u0430\u043c\u043e\u043d \u043c\u0443\u0440\u0434\u0430\u043d\u0434.\n\u041c\u0435\u04b3\u0442\u0430\u0440 \u0430\u0437 \u0444\u0430\u0432\u0442\u0438 \u04b3\u0430\u0444\u0442 \u0441\u0430\u0440 \u0444\u0430\u0440\u0437\u0430\u043d\u0434,\n\u0422\u043e \u0431\u0430 \u044f\u043a \u04b3\u0430\u0444\u0442\u0430 \u0440\u0438\u0448 \u0431\u0430\u0440\u043c\u0435\u043a\u0430\u043d\u0434.\n\u0411\u0430\u044a\u0434\u0438 \u044f\u043a \u04b3\u0430\u0444\u0442\u0430 \u043e\u043c\u0430\u0434 \u043e\u043d \u0434\u0430\u0440\u0432\u0435\u0448,\n\u041a\u0430\u0440\u0434 \u0431\u0430\u0440 \u0434\u0430\u0440 \u04b3\u0430\u043c\u043e\u043d \u043d\u0430\u0441\u0438\u04b3\u0430\u0442\u0438 \u0445\u0435\u0448.\n\u0413\u04ef\u0448 \u0431\u0430\u0440 \u049b\u0430\u0432\u043b\u0438 \u04ef \u0447\u0443 \u0431\u0438\u043d\u04b3\u043e\u0434\u0430\u043d\u0434,\n\u0421\u0430\u0440 \u0431\u0430 \u0441\u0430\u0440 \u0434\u0430\u0440 \u0442\u0430\u0430\u04b7\u04b7\u0443\u0431 \u0430\u0444\u0442\u043e\u0434\u0430\u043d\u0434:\n\u041a-\xab\u0418\u043d \u0433\u0430\u0434\u043e\u043f\u0435\u0448\u0430 \u0437\u0430\u04b3\u0440 \u0434\u0430\u0440 \u043d\u043e\u043d \u0445\u04ef\u0440\u0434.\n\u0421\u0430\u0445\u0442\u04b7\u043e\u043d \u0437\u0430\u04b3\u0440 \u0445\u04ef\u0440\u0434\u0430 \u0447\u0443\u043d \u04b7\u043e\u043d \u0431\u0443\u0440\u0434?\xbb\n\u0413\u0443\u0444\u0442 \u0448\u0430\u0445\u0441\u0435: \xab\u041d\u0430\u0445\u04ef\u0440\u0434\u0430 \u043e\u043d \u043d\u043e\u043d\u0440\u043e,\n\u0412-\u0430\u0440\u043d\u0430 \u043c\u0435\u0434\u043e\u0434 \u0434\u0430\u0440\u0437\u0430\u043c\u043e\u043d \u04b7\u043e\u043d\u0440\u043e\xbb.\n\u041c\u0435\u04b3\u0442\u0430\u0440 \u0430\u0437 \u0445\u043e\u043d\u0430 \u0441\u0430\u0440 \u0431\u0443\u0440\u0443\u043d \u043e\u0432\u0430\u0440\u0434,\n\u0413\u0443\u0444\u0442 \u0434\u0430\u0440\u0432\u0435\u0448\u0440\u043e, \u043a\u0438 \xab\u044d\u0439 \u0441\u0430\u0440\u0430\u043c\u0430\u0440\u0434!\n\u041d\u043e\u043d, \u043a\u0438 \u043e\u043d \u0440\u04ef\u0437 \u0437-\u0438\u043d \u0441\u0430\u0440\u043e \u0431\u0443\u0440\u0434\u04e3,\n\u0411\u0430 \u043a\u0443\u04b7\u043e \u0431\u0443\u0440\u0434\u0438\u0432\u0443 \u043a\u0443\u04b7\u043e \u0445\u04ef\u0440\u0434\u04e3?\xbb.\n\u0413\u0443\u0444\u0442: -\xab\u0411\u0443\u0434\u0430\u043c \u0431\u0430 \u0440\u043e\u04b3\u0438 \u0445\u043e\u043d\u0430\u0438 \u0445\u0435\u0448,\n\u041f\u0438\u0441\u0430\u0440\u043e\u043d\u0438 \u0442\u0443 \u043e\u043c\u0430\u0434\u0430\u043d\u0434 \u0431\u0430 \u043f\u0435\u0448.\n\u04b2\u0430\u0444\u0442 \u0442\u0430\u043d \u04b3\u0430\u0444\u0442 \u043d\u043e\u043d\u0438 \u043c\u0430\u043d \u0431\u0443\u0440\u0434\u0430\u043d\u0434,\n\u0492\u0430\u0441\u0431 \u043a\u0430\u0440\u0434\u0430\u043d\u0434\u0443 \u043d\u043e\u043d\u0438 \u043c\u0430\u043d \u0445\u04ef\u0440\u0434\u0430\u043d\u0434\xbb.\n\u041c\u0435\u04b3\u0442\u0430\u0440 \u0430\u0437 \u0432\u0430\u0439 \u0447\u0443 \u0438\u043d \u0441\u0443\u0445\u0430\u043d \u0431\u0438\u0448\u043d\u0438\u0434,\n\u0421\u04ef\u0445\u0442 \u04b7\u043e\u043d\u0430\u0448 \u0437\u0438 \u04b3\u0430\u04b7\u0440\u0438 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u043e\u043d,\n\u0413\u0430\u0448\u0442 \u0433\u0438\u0440\u0451\u043d \u0447\u0443 \u043e\u0440\u0437\u0443\u043c\u0430\u043d\u0434\u043e\u043d.")
B.adI=new A.a("27b83b75-c62d-4e03-92ed-b1448035a467","ef0f434c-c5a7-4cdd-b13a-35f999319fbf","\u04b2\u0430\u043c \u0434\u0430\u0440 \u043e\u043d \u0447\u0430\u04b3 \u0444\u0438\u0442\u043e\u0434 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0430\u043c...","\u04b2\u0430\u043c \u0434\u0430\u0440 \u043e\u043d \u0447\u0430\u04b3 \u0444\u0438\u0442\u043e\u0434 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0430\u043c\xbb.\n\u0417\u0438\u043d\u04b3\u043e\u0440 \u043e\u043d \u0447\u04e3 \u043d\u043e\u043f\u0438\u0441\u0430\u043d\u0434 \u0431\u0443\u0432\u0430\u0434,\n\u041a\u0438 \u0430\u0437 \u04ef \u0445\u0430\u043b\u049b\u0440\u043e \u0433\u0430\u0437\u0430\u043d\u0434 \u0431\u0443\u0432\u0430\u0434.\n\u0422\u043e \u0442\u0430\u0432\u043e\u043d\u04e3, \u0431\u0430 \u04b3\u0435\u0447  \u043a\u0430\u0441 \u043c\u0430\u043f\u0441\u0430\u043d\u0434!\n\u0413\u0430\u0440 \u043d\u0430\u0445\u043e\u04b3\u04e3, \u043a\u0438 \u0443\u0444\u0442\u04e3 \u0431\u0430 \u0433\u0430\u0437\u0430\u043d\u0434.")
B.aj8=new A.a("d6224e1b-7128-40e3-b60a-c30091fce486","ef0f434c-c5a7-4cdd-b13a-35f999319fbf","\u0431\u043e \u0434\u0438\u043b\u0438 \u043a\u0443\u0448\u043e\u0434\u0443 \u0442\u0430\u0431\u044a\u0438 \u0431\u0430-","\u0431\u043e \u0434\u0438\u043b\u0438 \u043a\u0443\u0448\u043e\u0434\u0443 \u0442\u0430\u0431\u044a\u0438 \u0431\u0430-\n\u043b\u0430\u043d\u0434.")
