B.apJ=new A.a("730a8736-b52b-4a7d-89ac-f78f025ca95a","ef5a57a2-8949-43dd-85eb-8ceaf78335f3","\u0414\u0430\u0440\u044f \u0421\u0443\u0440\u0435\u043d\u043a\u043e, \u043c\u043e\u0434\u0430\u0440\u0438 \u0410\u0440\u0441\u043b\u043e\u043d\u0430\u043b\u04e3...","\u0414\u0430\u0440\u044f \u0421\u0443\u0440\u0435\u043d\u043a\u043e, \u043c\u043e\u0434\u0430\u0440\u0438 \u0410\u0440\u0441\u043b\u043e\u043d\u0430\u043b\u04e3, \u0434\u0443\u0445\u0442\u0443\u0440\n\u041b\u044e\u0431\u043e\u0432 \u0412\u0430\u0441\u0438\u043b\u0435\u0432\u043d\u0430, \u04b2\u0438\u0434\u043e\u044f\u0442, \u04b6\u0430\u043c\u0438\u043b\u0430 \u0441\u0438\u043c\u043e\u04b3\u043e\u0435")
B.adJ=new A.a("683fbe4c-9d75-421a-906f-d341cf7d7495","ef5a57a2-8949-43dd-85eb-8ceaf78335f3","\u0410\u0440\u0441\u043b\u043e\u043d\u0430\u043b\u0438\u0440\u043e \u043c\u0443\u0448\u043e\u04b3\u0438\u0434\u0430 \u043d\u0430\u043c\u0443\u0434, \u04b3\u0443...","\u0410\u0440\u0441\u043b\u043e\u043d\u0430\u043b\u0438\u0440\u043e \u043c\u0443\u0448\u043e\u04b3\u0438\u0434\u0430 \u043d\u0430\u043c\u0443\u0434, \u04b3\u0443\u0448 \u0430\u0437 \u0441\u0430\u0440\u0430\u0448 \u043f\u0430\u0440\u0438\u0434. \u041d\u0430\u0445\u043e\u0434 \u043a\u0438\n\xab\u043f\u0438\u0441\u0430\u0440\u0438 \u049b\u0438\u0440\u0493\u0438\u0437, \u0431\u0430\u0447\u0430\u0438 \u043c\u0443\u044a\u043c\u0438\u043d\u0443 \u043c\u0443\u0441\u0443\u043b\u043c\u043e\u043d \u0431\u0430 \u0443\u0440\u0443\u0441\u0434\u0443\u0445\u0442\u0430\u0440, \u0431\u0430 \u0434\u0443\u0445\xad")
B.aa5=new A.a("9a9a9d7f-c81b-4a9b-84a9-02403b8a750b","ef5a57a2-8949-43dd-85eb-8ceaf78335f3","\u0411\u0430 \u04b3\u0430\u043c\u0438\u043d \u0442\u0430\u0440\u0438\u049b, \u0441\u0430\u0440\u043d\u0430\u0432\u0438\u0448\u0442\u0438 \u0425\u043e\u043b...","\u0411\u0430 \u04b3\u0430\u043c\u0438\u043d \u0442\u0430\u0440\u0438\u049b, \u0441\u0430\u0440\u043d\u0430\u0432\u0438\u0448\u0442\u0438 \u0425\u043e\u043b\u0438 \u0432\u043e\u0440\u0443\u0445\u04e3, \u0414\u0430\u0432\u043b\u0430\u0442 \u041d\u0430\u0437\u0430\u0440\u043e\u0432,\n\u0410\u043a\u0431\u0430\u0440 \u0432\u0430 \u0434\u0438\u0433\u0430\u0440 \u043a\u043e\u0440\u0433\u0430\u0440\u043e\u043d\u0438 \u043a\u043e\u043d\u0438 \u0430\u043d\u0433\u0438\u0448\u0442\u0438 \u0428\u04ef\u0440\u043e\u0431 \u0431\u0430\u0451\u043d\u0433\u0430\u0440\u0438 \u043f\u0430\u0439\u0434\u043e\xad")
