B.a97=new A.a("93cee178-30e8-4c5c-aa6b-e08d47825526","a7feaa09-c83f-44f2-a69e-0a46ba957dbc","\u0423\u0441\u0442\u043e\u0438 \u043d\u0430\u0493\u0437 \u0431\u0443\u0434\u0430\u043d\u0434 \u041e\u049b\u0438\u043b\u0430\u043c\u0430\u043a, \u2013 ...","\u0423\u0441\u0442\u043e\u0438 \u043d\u0430\u0493\u0437 \u0431\u0443\u0434\u0430\u043d\u0434 \u041e\u049b\u0438\u043b\u0430\u043c\u0430\u043a, \u2013 \u0433\u0443\u0444\u0442 \u04b7\u0430\u0432\u043e\u043d\u0435, \u043a\u0438 \u0434\u0430\u0440 \u043f\u0430\u0441\u0438\n\u0410\u0431\u0434\u0443\u0440\u0440\u0430\u0443\u0444\u0430\u043c\u0430\u043a \u043c\u0435\u0438\u0441\u0442\u043e\u0434.")
B.a84=new A.a("9742b1e4-345c-4ac9-bcc4-c8cf7abbb180","a7feaa09-c83f-44f2-a69e-0a46ba957dbc","\u04b2\u0430, \u0443\u0441\u0442\u043e \u0431\u0443\u0434, \u2013 \u0442\u0430\u0441\u0434\u0438\u049b \u043d\u0430\u043c\u0443\u0434 \u0441...","\u04b2\u0430, \u0443\u0441\u0442\u043e \u0431\u0443\u0434, \u2013 \u0442\u0430\u0441\u0434\u0438\u049b \u043d\u0430\u043c\u0443\u0434 \u0441\u0435\u0432\u0443\u043c\u04e3.\n\u0414\u0438\u0433\u0430\u0440 \u043a\u0430\u0441\u0435 \u0447\u0438\u0437\u0435 \u043d\u0430\u0433\u0443\u0444\u0442. \u04b2\u0430\u043c\u0430 \u043f\u0430\u0441\u0443 \u0434\u0443\u043d\u0431\u043e\u043b \u0431\u0430 \u043f\u0430\u0439\u0440\u0430\u04b3\u0430 \u0444\u0443\u0440\u043e\xad")
B.aao=new A.a("8f9b6b37-41f4-42cd-b887-51eb2787815f","a7feaa09-c83f-44f2-a69e-0a46ba957dbc","\u0414\u0430\u0440 \u049b\u0438\u0441\u0441\u0430\u0438 \xab\u041e\u0434\u0430\u043c\u043e\u043d\u0438 \u043a\u0443\u04b3\u043d\u0430\xbb \u0438\u0448\u0442...","\u0414\u0430\u0440 \u049b\u0438\u0441\u0441\u0430\u0438 \xab\u041e\u0434\u0430\u043c\u043e\u043d\u0438 \u043a\u0443\u04b3\u043d\u0430\xbb \u0438\u0448\u0442\u0438\u0440\u043e\u043a\u043a\u0443\u043d\u0430\u043d\u0434\u0430\u0433\u043e\u043d\u0438 \u0430\u0441\u0430\u0440, \u0447\u0438\n\u0417\u0438\u0451\u0431\u043e\u0431\u043e \u0432\u0430 \u0410\u04b3\u0440\u043e\u0440\u0430\u043c\u0430\u043a\u0443 \u0418\u049b\u0431\u043e\u043b\u0445\u043e\u043b\u0430 \u0432\u0430 \u0447\u0438 \u041e\u0438\u0448\u0430\u0445\u043e\u043d\u0443 \u042e\u0441\u0443\u0444 \u0421\u0430\xad")
B.ala=new A.a("ff7463e7-1f42-433a-be54-901c255a7582","a7feaa09-c83f-44f2-a69e-0a46ba957dbc","\u0424. \u041c\u0443\u04b3\u0430\u043c\u043c\u0430\u0434\u0438\u0435\u0432 \u0434\u0430\u0440 \xab\u041f\u0430\u043b\u0430\u0442\u0430\u0438 \u043a\u0443...","\u0424. \u041c\u0443\u04b3\u0430\u043c\u043c\u0430\u0434\u0438\u0435\u0432 \u0434\u0430\u0440 \xab\u041f\u0430\u043b\u0430\u0442\u0430\u0438 \u043a\u0443\u043d\u04b7\u0430\u043a\u04e3\xbb \u0431\u0430 \u0425\u0430\u0439\u0451\u043c\u0443 \u0421\u0430\u044a\u0434\u04e3,\n\u041a\u0430\u043c\u043e\u043b\u0438 \u0425\u0443\u04b7\u0430\u043d\u0434\u0438\u0432\u0443 \u04b6\u0430\u043b\u043e\u043b\u0443\u0434\u0434\u0438\u043d\u0438 \u0420\u0443\u043c\u04e3 \u0432\u0430 \u04b2\u0438\u043b\u043e\u043b\u0438\u0432\u0443 \u0411\u0435\u0434\u0438\u043b")
B.LK=new A.dC()
B.aLA=s([B.LK],t.J)
B.a5w=new A.a("dde1bda7-67e6-4404-8653-4f6bb1f2336b","400b9785-ae80-4957-a653-d65c72cdbf79","\u041a\u0438\u0441\u0442 \u043e\u043d \u0431\u0435 \u0430\u043d\u0438\u0441\u0438 \u0442\u0430\u043d\u04b3\u043e, \u043a\u0438\u0441\u0442?","\u041a\u0438\u0441\u0442 \u043e\u043d \u0431\u0435 \u0430\u043d\u0438\u0441\u0438 \u0442\u0430\u043d\u04b3\u043e, \u043a\u0438\u0441\u0442?\n\u0417\u0438\u043d\u0434\u0430 \u0431\u0435 \u0434\u04ef\u0441\u0442 \u04b3\u0435\u04b7 \u043d\u0430\u0442\u0432\u043e\u043d \u0437\u0438\u0441\u0442.\n\u04b2\u0430\u0440 \u043a\u0438\u0440\u043e \u0451\u0440\u0443 \u0434\u04ef\u0441\u0442 \u0431\u0438\u0441\u0451\u0440 \u0430\u0441\u0442,\n\u04b2\u0430\u0440 \u043a\u0430\u0434\u043e\u043c\u0430\u0448 \u043c\u0443\u043d\u043e\u0441\u0438\u0431 \u0451\u0440 \u0430\u0441\u0442.\n\u04b2\u0430\u0440 \u044f\u043a\u0435\u0440\u043e \u0447\u0443 \u0433\u0430\u0432\u04b3\u0430\u0440\u0438 \u0447\u0430\u0448\u043c\u043e\u043d,\n\u04b2\u0430\u043c\u0447\u0443 \u043b\u0430\u0445\u0442\u0438 \u04b7\u0438\u0433\u0430\u0440, \u0447\u0443 \u0440\u0438\u0448\u0442\u0430\u0438 \u04b7\u043e\u043d.\n\u0425\u043e\u0441\u0438 \u043e\u043d \u0437\u0435\u0431\u0438 \u043e\u043d \u043c\u0430\u049b\u043e\u043c\u0435 \u04b3\u0430\u0441\u0442,\n\u0418\u0437\u0437\u0430\u0442\u0443 \u043d\u043e\u043c\u0443 \u044d\u04b3\u0442\u0438\u0440\u043e\u043c\u0435 \u04b3\u0430\u0441\u0442.\n\u041b\u0435\u043a \u0434\u0430\u0440 \u043e\u043d \u043c\u0438\u0451\u043d \u043d\u0430\u0437\u0430\u0440\u043d\u043e\u0433\u0438\u0440,\n\u0414\u04ef\u0441\u0442\u0435 \u04b3\u0430\u0441\u0442 \u0445\u043e\u043a\u0441\u043e\u0440\u0443 \u0444\u0430\u049b\u0438\u0440.\n\u0421\u0430\u04b3\u043b\u0443 \u0431\u043e\u049b\u0430\u0434\u0440 \u043e\u043d\u0447\u0443\u043d\u043e\u043d \u0430\u0441\u0442 \u043e\u043d,\n\u041e\u0431\u0443 \u043d\u043e\u043d \u0433\u04ef\u0439\u04e3, \u043e\u0431\u0443 \u043d\u043e\u043d \u0430\u0441\u0442 \u043e\u043d.\n\u0414\u0430\u0440 \u0431\u0430\u0440\u0438 \u0442\u0443\u0441\u0442, \u0442\u0443 \u0430\u0437 \u043e\u043d \u0441\u0435\u0440\u04e3,\n\u0413\u0430\u04b3 \u0432\u0430\u0440\u043e \u0434\u0430\u0440 \u043d\u0430\u0437\u0430\u0440 \u043d\u0430\u043c\u0435\u0433\u0438\u0440\u04e3.\n\u041b\u0435\u043a \u0430\u0437 \u043e\u043d \u04b7\u0443\u0434\u043e \u0448\u0430\u0432\u04e3 \u043d\u0430\u0444\u0430\u0441\u0435,\n\u04b6\u043e\u0439\u0438 \u0434\u0438\u0433\u0430\u0440 \u0440\u0430\u0432\u04e3, \u044f\u0433\u043e\u043d\u0430 \u043a\u0430\u0441\u0435,\n\u041a\u0438 \u0431\u0430 \u0451\u0434\u0430\u0442 \u0431\u0438\u0451\u044f\u0434 \u0430\u0437 \u04b3\u0430\u043c\u0430 \u0437\u0443\u0434,\n\u04b6\u043e\u0448 \u0445\u043e\u043b\u04e3 \u0431\u0443\u0431\u0438\u043d\u04e3 \u0434\u0430\u0440 \u0431\u0430\u0440\u0438 \u0445\u0443\u0434-\n\u0414\u04ef\u0441\u0442\u043e\u043d, \u0434\u04ef\u0441\u0442\u043e\u043d, \u04b3\u0430\u043c\u043e\u043d \u0430\u0441\u0442 \u043e\u043d,\n\u0414\u0430\u0440 \u04b3\u0430\u049b\u0438\u049b\u0430\u0442, \u0447\u0443 \u043e\u0431\u0443 \u043d\u043e\u043d \u0430\u0441\u0442 \u043e\u043d.")
B.a5W=new A.a("cfd15745-50d9-414d-b0de-436e6a210b9f","400b9785-ae80-4957-a653-d65c72cdbf79","\u0411\u0430\u04b3\u043e\u0440 \u043e\u043c\u0430\u0434.","\u0411\u0430\u04b3\u043e\u0440 \u043e\u043c\u0430\u0434.\n\u0411\u0430\u04b3\u043e\u0440\u0435 \u0447\u0443\u043d \u0430\u0440\u04ef\u0441\u0438 \u0431\u0435\u043d\u0438\u0451\u0437 \u043e\u043c\u0430\u0434,\n\u0411\u0430\u0441\u043e \u0431\u043e \u043d\u043e\u0437\u0443 \u043d\u0443\u0437 \u043e\u043c\u0430\u0434.\n\u0411\u0430\u0441\u043e \u0433\u0430\u0440\u0434\u0430\u043d\u0430\u0444\u0440\u043e\u0437 \u043e\u043c\u0430\u0434.\n\u0427\u0443 \u0437\u0435\u0431\u043e\u0435, \u043a\u0438 \u0434\u043e\u043d\u0438\u0441\u0442\u0430\u0441\u0442\n\u0437\u0435\u0431\u043e \u0431\u0443\u0434\u0430\u043d\u0438 \u0445\u0443\u0434\u0440\u043e,\n\u041d\u0430\u0437\u0430\u0440 \u0434\u0430\u0440 \u043e\u0441\u043c\u043e\u043d, \u043c\u0430\u0493\u0440\u0443\u0440.\n\u041e\u0434\u0430\u043c\u0448\u0438\u043d\u043e\u0441 \u043e\u043c\u0430\u0434.\n\u0427\u0443 \u043c\u0435\u0433\u04ef\u044f\u043d\u0434, \u0445\u0443\u0434\u0431\u0438\u043d\u0430\u043d\u0434\n\u043e\u043d\u04b3\u043e\u0435, \u043a\u0438 \u0445\u0443\u0448\u0440\u04ef\u044f\u043d\u0434,\n\u04b2\u0430\u043c\u0430 \u043e\u043d \u0433\u0443\u043d\u0430 \u043d\u043e\u0437\u0443\u043a\u0442\u0430\u0431\u044a,\n\u043a-\u0430\u043d\u0434\u0430\u0440 \u044f\u043a \u0441\u0430\u0440\u0438 \u043c\u04ef\u044f\u043d\u0434.\n\u041a\u0430\u043b\u043e\u043c\u0438 \u0442\u0430\u043b\u0445 \u0433\u04ef\u044e\n\u04b3\u043e\u043b\u0438 \u0437\u043e\u0440\u0438 \u043d\u043e\u0437\u0443\u043a\u043e\u043d \u0431\u0438\u043d\u0433\u0430\u0440,\n\u041a\u0438 \u0430\u0437 \u049b\u0430\u04b3\u0440\u0443 \u0493\u0430\u0437\u0430\u0431 \u04b3\u0430\u0440\u0444\u0435,\n\u043d\u0430\u043c\u0435\u0451\u0431\u0430\u043d\u0434, \u0442\u043e \u0433\u04ef\u044f\u043d\u0434.\n\u0421\u0430\u0440\u0438 \u0440\u043e\u04b3\u0430\u0448 \u0433\u0438\u0440\u0438\u0444\u0442\u0430\u043c,\n\u0431\u043e \u0437\u0430\u0431\u043e\u043d\u0438 \u043d\u0435\u0448\u0442\u0430\u0440\u0434\u043e\u0440\u0435,\n\u0411\u0430 \u04ef \u0433\u0443\u0444\u0442\u0430\u043c:\n\u0411\u0430\u04b3\u043e\u0440\u043e, \u0438\u043d \u049b\u0430\u0434\u0430\u0440 \u0442\u0443 \u043a\u0430\u0440\u0440\u0443\u0444\u0430\u0440 \u0434\u043e\u0440\u04e3?\n\u0427\u0430\u0440\u043e \u0431\u0435\u043c\u0430\u0439\u043b \u043c\u0435\u043e\u04e3,\n\u0447\u0430\u0440\u043e \u0434\u0438\u043b\u0441\u0430\u0440\u0434 \u043c\u0435\u0442\u043e\u0431\u04e3?\n\u041c\u0430\u0433\u0430\u0440 \u0442\u0430\u043d\u04b3\u043e \u0442\u0443 \u0437\u0435\u0431\u043e\u04e3,\n\u0442\u0430\u043a\u0430\u0431\u0431\u0443\u0440 \u0438\u043d \u049b\u0430\u0434\u0430\u0440 \u0434\u043e\u0440\u04e3?\n\u0413\u0443\u043c\u043e\u043d \u0434\u043e\u0440\u04e3, \u0444\u0430\u049b\u0430\u0442 \u0430\u0437 \u0442\u0443\u0441\u0442\n\u0441\u0430\u0440\u0441\u0430\u0431\u0437\u0438\u0438 \u043c\u043e,\n\u04b2\u0430\u0437\u043e\u0440 \u043e\u04b3\u0430\u043d\u0433\u0443 \u0440\u0430\u043d\u0433\u0443 \u0431\u04ef,\n\u04b3\u0430\u0432\u043e\u0438 \u043d\u0430\u0448\u044a\u0430\u043d\u043e\u043a\u0438 \u043c\u043e.\n\u0427\u0443\u043d\u043e\u043d \u0441\u0430\u0432\u043b\u0430\u0442\u043a\u0443\u043d\u043e\u043d \u043e\u0439\u04e3,\n\u043a\u0438 \u0433\u04ef\u0451 \u0447\u043e\u043a\u0430\u0440\u0430\u0442 \u0431\u043e\u0448\u0435\u043c,\n\u0424\u0430\u049b\u0430\u0442 \u0430\u0437 \u0442\u0443\u0441\u0442 \u0433\u04ef\u0451\n\u0447\u0430\u0448\u043c\u0438 \u0441\u0435\u0440\u0438 \u043c\u043e, \u0447\u0430\u0440\u043e\u0493\u0438 \u043c\u043e.\n\u0422\u0443 \u04b3\u0430\u0440 \u0441\u043e\u043b\u0435 \u04b7\u0430\u0432\u043e\u043d \u0433\u0430\u0440\u0434\u0438\u0434\u0430\n\u0430\u0437 \u0441\u0430\u0440 \u043a\u043e\u0440 \u0441\u0430\u0440 \u043a\u0430\u0440\u0434\u04e3,\n\u04b2\u0430\u0437\u043e\u0440\u043e\u043d \u0431\u043e\u0440 \u0430\u0437 \u0431\u043e\u043b\u043e\u0438\n\u0438\u043d \u043a\u0438\u0448\u0432\u0430\u0440 \u0433\u0443\u0437\u0430\u0440 \u043a\u0430\u0440\u0434\u04e3.\n\u0412\u0430\u043b\u0435, \u044d\u0439 \u04b7\u043e\u043d\u0438 \u0448\u0438\u0440\u0438\u043d,\n\u0430\u0437 \u04b3\u0438\u0441\u043e\u0431\u0438 \u0438\u0444\u0442\u0438\u0445\u043e\u0440\u0438 \u0445\u0443\u0434\n\u0427\u04e3 \u043a\u0430\u0440\u0434\u04e3, \u0441\u0430\u0434\u044f\u043a\u0438 \u0438\u043d \u0445\u043e\u043a\u0440\u043e\n\u0430\u043d\u0434\u0430\u043a \u0434\u0438\u0433\u0430\u0440 \u043a\u0430\u0440\u0434\u04e3.\n\u0417\u0430\u043c\u0438\u043d\u0435\u0440\u043e, \u043a\u0438 \u0431\u0443\u0434 \u0437\u0438\u043d\u0434\u0430,\n\u043c\u0443\u0441\u0430\u0432\u0432\u0430\u0440 \u043a\u0430\u0440\u0434\u0430 \u043c\u0435\u0440\u0430\u0444\u0442\u04e3,\n\u0411\u0430 \u0441\u0430\u0440 \u0438\u043d \u0445\u0438\u0437\u043c\u0430\u0442\u0430\u0442\u0440\u043e \u043c\u043e\u043d\u0434\u0430\n\u0430\u0444\u0441\u0430\u0440 \u043a\u0430\u0440\u0434\u0430 \u043c\u0435\u0440\u0430\u0444\u0442\u04e3,\n\u0412\u0430\u043b\u0435 \u043f\u0430\u0439\u0432\u0430\u0441\u0442\u0430 \u0430\u0437 \u0440\u04ef\u0439\u0438\n\u0437\u0430\u043c\u0438\u043d\u04b3\u043e\u0435, \u043a\u0438 \u043c\u0435\u043c\u0443\u0440\u0434\u0430\u043d\u0434,\n\u041f\u0430\u0440\u0438\u0434\u0430 \u043c\u0435\u0433\u0443\u0437\u0430\u0448\u0442\u04e3,\n\u0411\u043e\u0437 \u0431\u0430\u0434\u0442\u0430\u0440 \u043a\u0430\u0440\u0434\u0430 \u043c\u0435\u0440\u0430\u0444\u0442\u04e3.\n\u0417\u0430\u043c\u0438\u043d\u0438 \u0437\u0438\u043d\u0434\u0430 \u043a\u0430\u043c \u043c\u0435\u0448\u0443\u0434,\n\u041d\u0430\u0431\u0443\u0434 \u0438\u043d\u0440\u043e \u0434\u0430\u0432\u043e\u0435 \u04b3\u0435\u04b7,\n\u041f\u0430\u0439\u0438 \u0445\u0438\u0437\u043c\u0430\u0442 \u049b\u0430\u0440\u0438\u0431 \u043e\u043c\u0430\u0434\n\u043d\u0430\u0451\u0431\u04e3 \u04b7\u043e\u0432\u0443 \u043f\u043e\u0435 \u04b3\u0435\u04b7.\n\u0410\u0433\u0430\u0440 \u0441\u0435-\u0447\u043e\u0440 \u0441\u043e\u043b\u0438 \u0434\u0438\u0433\u0430\u0440\n\u041e\u043a\u0442\u044f\u0431\u0440 \u0430\u049b\u0438\u0431 \u043c\u0435\u043c\u043e\u043d\u0434,\n\u0411\u0430\u04b3\u043e\u0440\u043e, \u043c\u0435\u0442\u0430\u0432\u043e\u043d\u0438\u0441\u0442\u04e3,\n\u0431\u0430 \u0438\u043d \u043a\u0438\u0448\u0432\u0430\u0440 \u043d\u0430\u043e\u04e3 \u04b3\u0435\u04b7.\n\u041c\u0430\u043a\u0443\u043d \u049b\u0430\u04b3\u0440\u0443 \u0493\u0430\u0437\u0430\u0431,\n\u0433\u0443\u0441\u0442\u043e\u0445\u0438\u0438 \u043c\u0430\u043d \u0441\u0430\u043d\u0433\u0438 \u043d\u043e\u04b3\u0430\u049b \u043d\u0435\u0441\u0442.\n\u0411\u0430 \u044d\u044a\u04b7\u043e\u0437\u0443 \u0431\u0430 \u0437\u0435\u0431\u043e\u0438\u0438 \u0442\u0443,\n\u04b7\u043e\u043d\u0430\u043c, \u044f\u0433\u043e\u043d \u0448\u0430\u043a \u043d\u0435\u0441\u0442.\n\u0412\u0430\u043b\u0435 \u0431\u043e \u043c\u0430\u043d \u0441\u0430\u0451\u04b3\u0430\u0442 \u043a\u0443\u043d\n\u0437\u0430\u043c\u0438\u043d\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d\u0440\u043e,\n\u0411\u0443\u0431\u0438\u043d, \u043a\u0438 \u0434\u0430\u0441\u0442\u0438 \u044d\u044a\u04b7\u043e\u0437\u0443\n\u0440\u0443\u0445\u0438 \u0437\u0435\u0431\u043e\u0442 \u043c\u0443\u0442\u043b\u0430\u049b \u043d\u0435\u0441\u0442.\n\u0411\u0438\u0451, \u0431\u0438\u043d \u0434\u0443\u0445\u0442\u0430\u0440\u043e\u043d\u0435\u0440\u043e,\n\u043a\u0438 \u0430\u0437 \u0442\u0443 \u0445\u0443\u0431\u0442\u0430\u0440 \u04b3\u0430\u0441\u0442\u0430\u043d\u0434,\n\u0422\u0443\u0440\u043e \u0433\u0430\u0440, \u043a\u0438 \u04b3\u0443\u043d\u0430\u0440 \u0431\u043e\u0448\u0430\u0434,\n\u0445\u0443\u0434\u0438 \u043e\u043d\u04b3\u043e \u04b3\u0443\u043d\u0430\u0440 \u04b3\u0430\u0441\u0442\u0430\u043d\u0434.\n\u0411\u0430 \u04b7\u043e\u044f\u0442 \u04b3\u0430\u0440 \u043a\u0430\u0434\u043e\u043c\u0438 \u043e\u043d\n\u0442\u0430\u0432\u043e\u043d\u0430\u0434 \u043c\u0443\u0434\u0434\u0430\u04e3 \u0431\u043e\u0448\u0430\u0434.\n\u0412\u0430\u043b\u0435\u043a\u0438\u043d \u0445\u043e\u043a\u0441\u043e\u0440\u0443 \u0441\u043e\u0434\u0430\u0432\u0443\n\u0431\u0435\u043a\u0430\u0440\u0440\u0443\u0444\u0430\u0440 \u04b3\u0430\u0441\u0442\u0430\u043d\u0434.\n\u0411\u0430 \u043e\u043d \u0447\u0430\u0448\u043c\u043e\u043d\u0438 \u04b3\u0430\u0439\u0440\u043e\u043d\u0430\u0442,\n\u0411\u0430 \u043e\u043d \u043c\u04ef\u0439\u0438 \u043f\u0430\u0440\u0435\u0448\u043e\u043d\u0430\u0442.\n\u0411\u0430 \u043e\u043d \u043f\u043e\u04b3\u043e\u0438 \u0443\u0440\u0451\u043d\u0430\u0442,\n\u0411\u0430 \u04b3\u0430\u0440 \u0430\u043d\u0433\u0443\u0448\u0442\u0438 \u0434\u0430\u0441\u0442\u043e\u043d\u0430\u0442.\n\u049a\u0430\u0441\u0430\u043c, \u043a\u0438 \u0437\u0430\u04b3\u0440 \u043c\u0435\u043d\u04ef\u0448\u0430\u043c,\n\u049a\u0430\u0441\u0430\u043c, \u043a\u0438 \u043c\u0435\u043a\u0443\u0448\u0430\u043c \u0445\u0443\u0434\u0440\u043e\n\u0410\u0433\u0430\u0440 \u043a\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d\u0430\u043c\n\u0442\u0443\u0440\u043e \u043c\u0430\u0444\u0442\u0443\u043d \u043d\u0430\u0433\u0430\u0440\u0434\u043e\u043d\u0430\u0434.")
B.a86=new A.a("60c6df08-0d65-45a5-8ef6-2d2f3cba3466","400b9785-ae80-4957-a653-d65c72cdbf79","\u0411\u0430\u0440 \u0441\u0430\u0440\u0438 \u0433\u0430\u04b3\u0432\u043e\u0440\u0430 \u0434\u0438\u0434\u0430\u043c \u043c\u043e\u0434\u0430\u0440\u0435,","\u0411\u0430\u0440 \u0441\u0430\u0440\u0438 \u0433\u0430\u04b3\u0432\u043e\u0440\u0430 \u0434\u0438\u0434\u0430\u043c \u043c\u043e\u0434\u0430\u0440\u0435,\n\u041c\u043e\u0434\u0430\u0440\u0438 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0438 \u043c\u043e\u043d\u0430\u043d\u0434\u0438 \u043f\u0430\u0440\u04e3.\n\u0422\u0438\u0444\u043b \u0434\u0430\u0440 \u0433\u0430\u04b3\u0432\u043e\u0440\u0430 \u0430\u043d\u0434\u0430\u0440 \u0445\u043e\u0431 \u0431\u0443\u0434,\n\u0401 \u043a\u0438 \u0434\u0430\u0440 \u0433\u0430\u04b3\u0432\u043e\u0440\u0430 \u0448\u0438\u0440\u043c\u0430\u04b3\u0442\u043e\u0431 \u0431\u0443\u0434.\n\u2013\u0422\u0430\u0432\u0431\u0430 \u043a\u0430\u0440\u0434\u0430\u043c, \u2013 \u0433\u0443\u0444\u0442 \u043c\u043e\u0434\u0430\u0440 \u043d\u043e\u0433\u0430\u04b3\u043e\u043d,\n\u0422\u0430\u0432\u0431\u0430 \u043a\u0430\u0440\u0434\u0430\u043c, \u044d\u0439 \u0425\u0443\u0434\u043e\u0438 \u043c\u0435\u04b3\u0440\u0443\u0431\u043e\u043d.\n\u0418\u043d \u049b\u0430\u0434\u0430\u0440 \u0445\u0443\u0440\u0434\u0443 \u0437\u0430\u0438\u0444\u0443 \u0441\u043e\u0434\u0430 \u0430\u0441\u0442,\n\u0418\u043d \u049b\u0430\u0434\u0430\u0440 \u0431\u0430\u0445\u0442\u0443 \u043c\u0430\u0434\u043e\u0440\u0430\u043c \u0434\u043e\u0434\u0430\u0430\u0441\u0442.\n\u042d\u0439 \u0411\u0430\u04b3\u043e\u0440\u0438 \u0430\u0437\u0438\u0437, \u044d\u0439 \u0434\u0438\u043b\u0431\u0430\u0440,\n\u0422\u0443 \u0431\u0430 \u0438\u043d \u0442\u0438\u0444\u043b\u0438 \u043d\u043e\u0437\u0430\u043d\u0438\u043d \u0431\u0438\u043d\u0433\u0430\u0440.\n\u0427\u04ef\u04b7\u0430\u0438 \u043e\u043d \u043a\u0430\u0431\u04ef\u0442\u0430\u0440\u0438 \u0432\u0430\u04b3\u0448\u04e3\n\u0414\u0430\u0440 \u0442\u0443 \u043c\u0438\u0440\u0430\u043c, \u0430\u04b7\u0430\u0431 \u0441\u0430\u0444\u043e\u0431\u0430\u0445\u0448\u04e3.\n\u0425\u0443\u0440\u0434\u0438\u044e \u0430\u0437 \u0442\u0443 \u0433\u0430\u04b3\u0432\u043e\u0440\u0430 \u043f\u0443\u0440 \u0430\u0441\u0442.\n\u0425\u043e\u043d\u0430 \u043f\u0443\u0440, \u043a\u0443\u043d\u04b7 \u043f\u0443\u0440, \u043a\u0430\u043d\u043e\u0440\u0430 \u043f\u0443\u0440 \u0430\u0441\u0442.\n\u0414\u0430\u0448\u0442\u0443 \u0441\u0430\u04b3\u0440\u043e\u0438 \u0431\u0435\u043a\u0430\u0440\u043e\u043d \u043f\u0443\u0440\u0438 \u0442\u0443\u0441\u0442,\n\u0422\u043e \u0444\u0430\u043b\u0430\u043a, \u0442\u043e \u043c\u0430\u043b\u0430\u043a \u04b7\u0430\u04b3\u043e\u043d \u043d\u0443\u0440\u0438 \u0442\u0443\u0441\u0442.\n\u0422\u0443 \u043a\u0430\u043b\u043e\u043d \u0448\u0430\u0432, \u0431\u0430\u0444\u0430\u0437\u043b\u0443 \u0434\u043e\u043d\u043e \u0448\u0430\u0432!\n\u04b2\u0430\u043c \u0431\u0430 \u0434\u0438\u043b, \u04b3\u0430\u043c \u0431\u0430 \u0447\u0435\u04b3\u0440\u0430 \u0437\u0435\u0431\u043e \u0448\u0430\u0432!")
B.LL=new A.dC()
