B.a9h=new A.a("2a7006c7-54e8-47f4-a42f-934ce01c937d","ae798b7c-c753-42d6-afd1-c81540b51e31","\u04b2\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d\u0433\u0438\u0440 \u0440\u04ef\u0441\u0438\u0451\u04b3\u0438 \u0442\u0443\u0441\u0442,","\u04b2\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d\u0433\u0438\u0440 \u0440\u04ef\u0441\u0438\u0451\u04b3\u0438 \u0442\u0443\u0441\u0442,\n\u041a\u0443\u0448\u0442\u0430\u0438 \u043f\u0443\u0440\u0433\u0443\u043d\u043e\u04b3\u0438 \u043e\u04b3\u0438 \u0442\u0443\u0441\u0442.\n\u0418\u043d \u04b7\u0430\u04b3\u043e\u043d \u0437\u0438\u043d\u0434\u0430 \u0434\u0430\u0440 \u043f\u0430\u043d\u043e\u04b3\u0438 \u0442\u0443\u0441\u0442,\n\u041c\u043e\u0434\u0430\u0440\u0430\u043c, \u043c\u043e\u0434\u0430\u0440\u0438 \u04b7\u0430\u04b3\u043e\u043d\u0433\u0438\u0440\u0430\u043c.")
B.ajl=new A.a("0ad147da-a697-4817-b728-ade0dd06f497","ae798b7c-c753-42d6-afd1-c81540b51e31","\u0411\u043e\u0434 \u0440\u0430\u0432\u0448\u0430\u043d \u0441\u0438\u0442\u043e\u0440\u0430\u0438 \u0431\u0430\u0445\u0442\u0430\u0442,","\u0411\u043e\u0434 \u0440\u0430\u0432\u0448\u0430\u043d \u0441\u0438\u0442\u043e\u0440\u0430\u0438 \u0431\u0430\u0445\u0442\u0430\u0442,\n\u041a-\u0430\u0437 \u0442\u0443 \u0440\u0430\u0432\u0448\u0430\u043d \u0441\u0438\u0442\u043e\u0440\u0430\u0438 \u0442\u043e\u04b7\u0438\u043a.\n\u0422\u043e \u0442\u0443 \u04b3\u0430\u0441\u0442\u04e3, \u04b3\u0430\u043c\u043e\u0440\u0430 \u043c\u0435\u04b7\u0443\u043d\u0431\u0430\u0434,\n\u0414\u0430\u0440 \u0437\u0430\u043c\u0438\u043d \u0433\u043e\u04b3\u0432\u043e\u0440\u0430\u0438 \u0442\u043e\u04b7\u0438\u043a.")
