B.a7E=new A.a("2e752478-9f41-40c8-b2e4-96a8ea7656cd","be19709e-c3af-460d-80b9-4c67046e8be3","\u0414\u0438\u043b\u0435 \u0434\u043e\u0440\u0430\u043c \u0445\u0430\u0440\u0438\u0434\u043e\u0440\u0438 \u043c\u0443\u04b3\u0430\u0431\u0431\u0430\u0442,\u2013","\u0414\u0438\u043b\u0435 \u0434\u043e\u0440\u0430\u043c \u0445\u0430\u0440\u0438\u0434\u043e\u0440\u0438 \u043c\u0443\u04b3\u0430\u0431\u0431\u0430\u0442,\u2013\n\u041a-\u0430\u0437 \u04ef \u0433\u0430\u0440\u043c \u0430\u0441\u0442 \u0431\u043e\u0437\u043e\u0440\u0438 \u043c\u0443\u04b3\u0430\u0431\u0431\u0430\u0442.\u2013\n\u041b\u0438\u0431\u043e\u0441\u0435 \u0431\u043e\u0444\u0442\u0430\u043c \u0431\u0430\u0440 \u049b\u043e\u043c\u0430\u0442\u0438 \u0434\u0438\u043b\u2013\n\u0417\u0438 \u043f\u0443\u0434\u0438 \u043c\u0435\u04b3\u043d\u0430\u0442\u0443 \u0442\u043e\u0440\u0438 \u043c\u0443\u04b3\u0430\u0431\u0431\u0430\u0442.\u2013")
B.a6r=new A.a("64068239-7ec6-4731-b48a-e365b1819299","5fc69b51-c38a-4427-a362-5c8a14bca835","\u0413\u0430\u0440 \u044f\u043a \u043d\u0430\u0444\u0430\u0441\u0430\u0442 \u0437\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u043e\u043d\u04e3 \u0433\u0443...","\u0413\u0430\u0440 \u044f\u043a \u043d\u0430\u0444\u0430\u0441\u0430\u0442 \u0437\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u043e\u043d\u04e3 \u0433\u0443\u0437\u0430\u0440\u0430\u0434,\u2013\n\u041c\u0430\u0433\u0437\u043e\u0440, \u043a\u0438 \u04b7\u0443\u0437 \u0431\u0430 \u0448\u043e\u0434\u043c\u043e\u043d\u04e3 \u0433\u0443\u0437\u0430\u0440\u0430\u0434.\u2013\n\u04b2\u0443\u0448 \u0434\u043e\u0440, \u043a\u0438 \u0441\u0430\u0440\u043c\u043e\u044f\u0438 \u0438\u043d \u043c\u0443\u043b\u043a\u0438 \u04b7\u0430\u04b3\u043e\u043d\u2013\n\u0423\u043c\u0440 \u0430\u0441\u0442\u0443 \u0447\u0443\u043d\u043e\u043d\u0430\u0448 \u0433\u0443\u0437\u0430\u0440\u043e\u043d\u04e3, \u0433\u0443\u0437\u0430\u0440\u0430\u0434.\u2013")
B.akh=new A.a("6471051e-e9fe-4622-a010-1fff7757d204","3ec91317-fcfe-4960-9ca0-fd87f3e96875","\u0411\u0430\u043d\u04e3 \u043e\u0434\u0430\u043c \u0430\u044a\u0437\u043e\u0438 \u044f\u043a \u043f\u0430\u0439\u043a\u0430\u0440\u0430\u043d\u0434,\u2013","\u0411\u0430\u043d\u04e3 \u043e\u0434\u0430\u043c \u0430\u044a\u0437\u043e\u0438 \u044f\u043a \u043f\u0430\u0439\u043a\u0430\u0440\u0430\u043d\u0434,\u2013\n\u041a\u0438 \u0434\u0430\u0440 \u043e\u0444\u0430\u0440\u0438\u043d\u0438\u0448 \u0437\u0438 \u044f\u043a \u0433\u0430\u0432\u04b3\u0430\u0440\u0430\u043d\u0434.\u2013\n\u0427\u0443 \u0443\u0437\u0432\u0435 \u0431\u0430 \u0434\u0430\u0440\u0434 \u043e\u0432\u0430\u0440\u0430\u0434 \u0440\u04ef\u0437\u0433\u043e\u0440,\u2013\n\u0414\u0438\u0433\u0430\u0440 \u0443\u0437\u0432\u04b3\u043e\u0440\u043e \u043d\u0430\u043c\u043e\u043d\u0430\u0434 \u049b\u0430\u0440\u043e\u0440.\u2013\n\u0422\u0443, \u043a-\u0430\u0437 \u043c\u0435\u04b3\u043d\u0430\u0442\u0438 \u0434\u0438\u0433\u0430\u0440\u043e\u043d \u0431\u0435\u0493\u0430\u043c\u04e3,\u2013\n\u041d\u0430\u0448\u043e\u044f\u0434, \u043a\u0438 \u043d\u043e\u043c\u0430\u0442 \u043d\u0438\u04b3\u0430\u043d\u0434 \u043e\u0434\u0430\u043c\u04e3.\u2013")
