B.anQ=new A.a("645d96c0-ae39-43f6-8f56-510795473765","5e4a71ac-6093-4ae4-b746-dbcc2abbe7c0","\u0420\u04ef\u0434\u0430\u043a\u04e3 \u043e\u043d \u043a\u0438 \u0434\u0443\u0440 \u04b3\u0430\u043c\u0435\u0441\u0443\u0444\u0442\u04e3,","\u0420\u04ef\u0434\u0430\u043a\u04e3 \u043e\u043d \u043a\u0438 \u0434\u0443\u0440 \u04b3\u0430\u043c\u0435\u0441\u0443\u0444\u0442\u04e3,\n\u041c\u0430\u0434\u04b3\u0438 \u0421\u043e\u043c\u043e\u043d\u0438\u0451\u043d \u04b3\u0430\u043c\u0435\u0433\u0443\u0444\u0442\u04e3...\n\u041d\u043e\u043c\u0438 \u04ef\u0440\u043e, \u043a\u0438 \u043c\u0435\u0431\u0430\u0440\u0430\u043d\u0434 \u0438\u043c\u0440\u04ef\u0437,\n\u04b2\u0430\u0441\u0442 \u0430\u0437 \u043e\u043d \u0448\u0435\u044a\u0440\u0438 \u0430\u043d\u04b7\u0443\u043c\u0430\u043d\u0430\u0444\u0440\u04ef\u0437.\n\u04b2\u0430\u043c\u0447\u0443\u043d\u0438\u043d \u043d\u043e\u043c\u0438 \u041e\u043b\u0438 \u0421\u043e\u043c\u043e\u043d\u0440\u043e \u2013\n\u041d\u0435\u043a\u043a\u043e\u0440\u043e\u043d\u0443 \u043d\u0435\u043a\u043d\u043e\u043c\u043e\u043d\u0440\u043e\n\u0417\u0438\u043d\u0434\u0430 \u0430\u0437 \u043d\u0430\u0437\u043c\u0438 \u0445\u0435\u0448 \u043c\u0435\u0434\u043e\u0440\u0430\u0434\n\u0412-\u0430\u0437 \u043f\u0430\u0441\u0438 \u043f\u0430\u0440\u0434\u0430 \u043f\u0435\u0448 \u043c\u0435\u043e\u0440\u0430\u0434.")
B.a88=new A.a("b6fc454d-7e00-43e1-a40a-54a2e0efd403","5e4a71ac-6093-4ae4-b746-dbcc2abbe7c0","\u0428\u0435\u044a\u0440\u0438 \u04ef\u0440\u043e \u043c\u0430\u043d \u0448\u0443\u043c\u0443\u0440\u0434\u0430\u043c \u0441\u0435\u0437\u0434\u0430\u04b3 ...","\u0428\u0435\u044a\u0440\u0438 \u04ef\u0440\u043e \u043c\u0430\u043d \u0448\u0443\u043c\u0443\u0440\u0434\u0430\u043c \u0441\u0435\u0437\u0434\u0430\u04b3 \u0440\u0430\u04b3 \u0441\u0430\u0434 \u04b3\u0430\u0437\u043e\u0440,\n\u04b2\u0430\u043c \u0444\u0443\u0437\u0443\u043d \u043e\u044f\u0434, \u0430\u0433\u0430\u0440 \u0447\u0443\u043d\u043e\u043d\u043a\u0438 \u0431\u043e\u044f\u0434 \u0431\u0438\u0448\u043c\u0430\u0440\u04e3.")
B.af9=new A.a("25c10cdc-3a89-4a97-a46d-6cc51248a40d","5e4a71ac-6093-4ae4-b746-dbcc2abbe7c0","\u041c\u0443\u0442\u0430\u0430\u0441\u0441\u0438\u0444\u043e\u043d\u0430, \u0430\u0437 \u0438\u043d \u043c\u0435\u0440\u043e\u0441\u0438 \u0444\u0430\u0440...","\u041c\u0443\u0442\u0430\u0430\u0441\u0441\u0438\u0444\u043e\u043d\u0430, \u0430\u0437 \u0438\u043d \u043c\u0435\u0440\u043e\u0441\u0438 \u0444\u0430\u0440\u043e\u0432\u043e\u043d\u0438 \u0448\u043e\u0438\u0440 \u0442\u043e \u0431\u0430 \u0438\u043c\u0440\u04ef\u0437\n\u04b3\u0430\u043c\u0430\u0433\u04e3 \u0434\u0430\u0440 \u04b3\u0443\u0434\u0443\u0434\u0438 \u0434\u0443 \u04b3\u0430\u0437\u043e\u0440 \u0431\u0430\u0439\u0442 \u043c\u043e\u043d\u0434\u0430\u0430\u0441\u0442. \u0420\u04ef\u0434\u0430\u043a\u0438\u0448\u0438\u043d\u043e\u0441\u043e\u043d \u0431\u0430\n\u043c\u0438\u0441\u043b\u0438 \u0431\u043e\u0441\u0442\u043e\u043d\u0448\u0438\u043d\u043e\u0441\u0435, \u043a\u0438 \u0430\u0437 \u043c\u0438\u0451\u043d\u0438 \u0445\u043e\u043a\u0442\u04ef\u0434\u0430\u04b3\u043e\u0438 \u0451\u0434\u0433\u043e\u0440\u0438\u04b3\u043e\u0438 \u0437\u0430\u043c\u043e\u043d\u0438\n\u0433\u0443\u0437\u0430\u0448\u0442\u0430 \u043f\u0430\u0441 \u0430\u0437 \u04b7\u0443\u0441\u0442\u0443\u04b7\u04ef\u04b3\u043e\u0438 \u0437\u0438\u0451\u0434\u0435 \u0441\u0430\u0444\u043e\u043b\u043f\u043e\u0440\u0430\u0435, \u0448\u0438\u0448\u0430\u043f\u043e\u0440\u0430\u0435, \u043f\u043e\u0440\u0430\u0435 \u0430\u0437")
B.asl=new A.a("cd4df811-0401-4945-a4ce-2145f718c61f","5e4a71ac-6093-4ae4-b746-dbcc2abbe7c0","\u0421\u0435 \u043c\u0438\u0441\u0440\u0430\u0438 \u0434\u0438\u0433\u0430\u0440, \u043a\u0438 \u0431\u043e \u043e\u043d\u04b3\u043e, \u0431...","\u0421\u0435 \u043c\u0438\u0441\u0440\u0430\u0438 \u0434\u0438\u0433\u0430\u0440, \u043a\u0438 \u0431\u043e \u043e\u043d\u04b3\u043e, \u0431\u0430 \u043d\u0430\u0437\u0430\u0440\u0438 \u043c\u043e, \u049b\u0438\u0441\u043c\u0438 \u0434\u0443\u044e\u043c\u0438\n\u049b\u0430\u0441\u0438\u0434\u0430 \u043e\u0493\u043e\u0437 \u043c\u0435\u0448\u0430\u0432\u0430\u0434, \u0430\u0437 \u0431\u0430\u0451\u043d\u0438 \u0440\u0430\u0444\u0442\u0438 \u0441\u0430\u0432\u043e\u043b\u0443 \u04b7\u0430\u0432\u043e\u0431\u0438 \u0448\u043e\u0438\u0440 \u0431\u043e\n\u04b3\u0430\u043c\u0441\u0443\u04b3\u0431\u0430\u0442\u0438 \u0442\u0430\u0441\u0430\u0432\u0432\u0443\u0440\u0438\u0430\u0448, \u043a\u0438 \u043a\u0430\u043c\u0435 \u0434\u0435\u0440\u0442\u0430\u0440 \u0431\u0430 \u0443\u043d\u0432\u043e\u043d\u0438 \xab\u043c\u043e\u04b3\u0440\u04ef\u0439\xbb \u0430\u0437 \u04ef\n\u0451\u0434 \u043c\u0435\u0448\u0430\u0432\u0430\u0434, \u0438\u0431\u043e\u0440\u0430\u0442 \u043c\u0435\u0431\u043e\u0448\u0430\u0434.")
B.ag0=new A.a("3f697d0b-cd1d-4dbc-b527-813752b61d45","5e4a71ac-6093-4ae4-b746-dbcc2abbe7c0","\u04b2\u0430\u043c\u0435 \u0447\u04e3 \u0434\u043e\u043d\u04e3, \u044d\u0439 \u043c\u043e\u04b3\u0440\u04ef\u0439\u0438 \u043c\u0443\u0448\u043a\u0438...","\u04b2\u0430\u043c\u0435 \u0447\u04e3 \u0434\u043e\u043d\u04e3, \u044d\u0439 \u043c\u043e\u04b3\u0440\u04ef\u0439\u0438 \u043c\u0443\u0448\u043a\u0438\u043d\u043c\u04ef\u0439,\n\u041a\u0438 \u04b3\u043e\u043b\u0438 \u0431\u0430\u043d\u0434\u0430 \u0430\u0437 \u0438\u043d \u043f\u0435\u0448 \u0431\u0430\u0440 \u0447\u04e3 \u0441\u043e\u043c\u043e\u043d \u0431\u0443\u0434?\n\u0411\u0430 \u0437\u0443\u043b\u0444\u0438 \u0447\u0430\u0432\u0433\u043e\u043d \u043d\u043e\u0437\u0438\u0448 \u04b3\u0430\u043c\u0435\u043a\u0443\u043d\u04e3 \u0442\u0443 \u0431\u0430\u0434-\u04ef,\n\u041d\u0430\u0434\u0438\u0434\u04e3 \u043e\u043d \u0433\u0430\u04b3 \u04ef\u0440\u043e, \u043a\u0438 \u0437\u0443\u043b\u0444\u0447\u0430\u0432\u0433\u043e\u043d \u0431\u0443\u0434!\n\u0428\u0443\u0434 \u043e\u043d \u0437\u0430\u043c\u043e\u043d\u0430, \u043a\u0438 \u0440\u04ef\u044f\u0448 \u0431\u0430 \u0441\u043e\u043d\u0438 \u0434\u0435\u0431\u043e \u0431\u0443\u0434,\n\u0428\u0443\u0434 \u043e\u043d \u0437\u0430\u043c\u043e\u043d\u0430, \u043a\u0438 \u043c\u04ef\u044f\u0448 \u0431\u0430 \u0441\u043e\u043d\u0438 \u049b\u0430\u0442\u0440\u043e\u043d \u0431\u0443\u0434.\n\u0427\u0443\u043d\u043e\u043d\u043a\u0438 \u0445\u0443\u0431\u0438\u0438 \u043c\u0435\u04b3\u043c\u043e\u043d\u0443 \u0434\u04ef\u0441\u0442 \u0431\u0443\u0434 \u0430\u0437\u0438\u0437,\n\u0411\u0438\u0448\u0443\u0434, \u043a\u0438 \u0431\u043e\u0437 \u043d\u0430\u0451\u043c\u0430\u0434, \u0430\u0437\u0438\u0437 \u043c\u0435\u04b3\u043c\u043e\u043d \u0431\u0443\u0434.\n\u0411\u0430\u0441\u043e \u043d\u0438\u0433\u043e\u0440, \u043a\u0438 \u04b3\u0430\u0439\u0440\u043e\u043d \u0431\u0443\u0434\u04e3 \u0431\u0430\u0434-\u04ef-\u0434\u0430\u0440 \u0447\u0430\u0448\u043c,\n\u0411\u0430 \u0440\u04ef\u0439\u0438 \u04ef-\u0434\u0430\u0440 \u0447\u0430\u0448\u043c\u0430\u043c \u04b3\u0430\u043c\u0435\u0448\u0430 \u04b3\u0430\u0439\u0440\u043e\u043d \u0431\u0443\u0434.")
B.aoP=new A.a("95925b51-c8b7-48ad-8280-4543f90c2a22","5e4a71ac-6093-4ae4-b746-dbcc2abbe7c0","\u0410\u0437 \u043a\u0430\u0439\u0444\u0438\u044f\u0442\u0438 \u04b7\u0430\u0432\u043e\u043d\u0438\u0438 \u0448\u043e\u0438\u0440 \u04b3\u0430\u043c\u0447\u0443...","\u0410\u0437 \u043a\u0430\u0439\u0444\u0438\u044f\u0442\u0438 \u04b7\u0430\u0432\u043e\u043d\u0438\u0438 \u0448\u043e\u0438\u0440 \u04b3\u0430\u043c\u0447\u0443\u043d\u0438\u043d \u0434\u0430\u0440 \u0431\u0430\u0439\u0442\u04b3\u043e\u0438 \u0434\u0438\u0433\u0430\u0440\n\u043c\u0443\u043b\u043e\u04b3\u0438\u0437\u0430 \u043c\u0435\u0440\u0430\u0432\u0430\u0434. \u041c\u0443\u0430\u043b\u043b\u0438\u0444 \u0434\u0430\u0440 \u043e\u043d\u04b3\u043e \u0430\u0437 \u04b3\u0430\u043c\u0435\u0448\u0430 \u0448\u043e\u0434\u0443 \u0445\u0443\u0440\u0440\u0430\u043c\n\u0431\u0443\u0434\u0430\u043d\u0443 \u0431\u0435\u0493\u0430\u043c\u0438\u04b3\u043e\u044f\u0448 \u0432\u0430 \u0442\u0430\u043d\u0438 \u043e\u0441\u0443\u0434\u0430 \u0434\u043e\u0448\u0442\u0430\u043d\u0430\u0448 \u0451\u0434 \u043e\u0432\u0430\u0440\u0434\u0430\u0430\u0441\u0442 \u0432\u0430 \u0430\u0437\n\u0433\u0443\u0437\u0430\u0448\u0442\u0438 \u043e\u043d \u0430\u0439\u0451\u043c\u0438 \u0444\u0430\u0440\u0445\u0443\u043d\u0434\u0430 \u0430\u0444\u0441\u04ef\u0441 \u0445\u04ef\u0440\u0434\u0430\u0430\u0441\u0442.")
