B.aeq=new A.a("cc18def4-8b23-4377-ac45-673ac78b3593","e948618d-0c4c-484b-b60b-c1658bc51d57","\u0414\u0430\u0440 \u0441\u0443\u0440\u0430\u0442\u0438 \u043d\u0435\u0440\u0443\u04b3\u043e\u0438 \u043d\u0435\u043a\u04e3 \u0432\u0430 \u0431\u0430\u0434...","\u0414\u0430\u0440 \u0441\u0443\u0440\u0430\u0442\u0438 \u043d\u0435\u0440\u0443\u04b3\u043e\u0438 \u043d\u0435\u043a\u04e3 \u0432\u0430 \u0431\u0430\u0434\u04e3 \u0431\u0430 \u04b3\u0430\u043c \u043c\u0443\u049b\u043e\u0431\u0438\u043b \u0433\u0443\u0437\u043e\u0448\u0442\u0430\u043d\u0438\n\u044d\u0440\u043e\u043d\u0438\u0451\u043d \u0432\u0430 \u0442\u0443\u0440\u043a\u043e\u043d\u0443 \u0447\u0438\u043d\u0438\u0451\u043d \u0430\u0441\u043e\u0441\u04b3\u043e\u0438 \u0442\u0430\u044a\u0440\u0438\u0445\u04e3 \u0434\u043e\u0440\u0430\u0434 \u0432\u0430 \u043c\u0430\u0441\u043d\u0430\u0432\u0438\u0438\n\u0414\u0430\u049b\u0438\u049b\u04e3 \u0431\u043e\u0437\u0442\u043e\u0431\u0438 \u04b3\u0430\u043c\u043e\u043d \u04b3\u0430\u049b\u0438\u049b\u0430\u0442\u04b3\u043e\u0438 \u0442\u0430\u044a\u0440\u0438\u0445\u0438\u0441\u0442.")
B.arB=new A.a("0cba1279-bfac-46c4-93d8-998565eda442","e948618d-0c4c-484b-b60b-c1658bc51d57","\u0410\u0431\u0443\u043b\u049b\u043e\u0441\u0438\u043c\u0438 \u0424\u0438\u0440\u0434\u0430\u0432\u0441\u04e3 \u043f\u0430\u0441 \u0430\u0437 \u043e\u0432\u0430...","\u0410\u0431\u0443\u043b\u049b\u043e\u0441\u0438\u043c\u0438 \u0424\u0438\u0440\u0434\u0430\u0432\u0441\u04e3 \u043f\u0430\u0441 \u0430\u0437 \u043e\u0432\u0430\u0440\u0434\u0430\u043d\u0438 1000 \u0431\u0430\u0439\u0442\u0438 \u0414\u0430\u049b\u0438\u049b\u04e3 \u0432\u0430\n\u043f\u0435\u0448 \u0430\u0437 \u0431\u043e\u0437\u0433\u0430\u0448\u0442\u0430\u043d \u0431\u0430 \u0433\u0443\u0444\u0442\u043e\u0440\u0438 \u0445\u0443\u0434 \u0434\u0430\u0440 \u0440\u0443\u04b7\u0443\u0435 \u0430\u0437 \u043e\u043d \u0451\u0434 \u043c\u0435\u043a\u0443\u043d\u0430\u0434, \u043a\u0438\n\u0437\u0430\u043c\u043e\u043d\u0430 \u043d\u0430\u0433\u0443\u0437\u043e\u0448\u0442, \u043a\u0438 \u0432\u0430\u0439 \u0443\u043c\u0440\u0438 \u0434\u0430\u0440\u043e\u0437 \u0431\u0438\u043d\u0430\u0434, \u0431\u0438\u0441\u0451\u0440 \u0440\u0430\u043d\u04b7 \u0431\u0438\u043d\u043c\u0443\u0434\u0430\u0448,\n\u043d\u0430\u043c\u043e\u043d\u0434, \u043a\u0438 \u043d\u043e\u043c\u0430\u0430\u0448\u0440\u043e \u0431\u0430 \u043e\u0445\u0438\u0440 \u0440\u0430\u0441\u043e\u043d\u0430\u0434. \u0425\u0443\u0441\u0443\u0441\u0430\u043d, \u043c\u0443\u043b\u043e\u04b3\u0438\u0437\u0430\u04b3\u043e\u0438\n\u0424\u0438\u0440\u0434\u0430\u0432\u0441\u04e3 \u0434\u0430\u0440 \u0431\u043e\u0440\u0430\u0438 \u0447\u0438\u0433\u0443\u043d\u0430\u0433\u0438\u0438 \u0448\u0435\u044a\u0440\u0438 \u0414\u0430\u049b\u0438\u049b\u04e3 \u04b7\u043e\u043b\u0438\u0431 \u043c\u0435\u0431\u043e\u0448\u0430\u043d\u0434.")
B.a9Z=new A.a("8be597b9-d0bb-4fb6-88ee-7c9f42b6e142","e948618d-0c4c-484b-b60b-c1658bc51d57","\u0410\u0439 \u0430\u0431\u0440\u0438 \u0431\u0430\u04b3\u043c\u0430\u043d\u04e3, \u043d\u0430 \u0431\u0430 \u0447\u0430\u0448\u043c\u0438 \u043c...","\u0410\u0439 \u0430\u0431\u0440\u0438 \u0431\u0430\u04b3\u043c\u0430\u043d\u04e3, \u043d\u0430 \u0431\u0430 \u0447\u0430\u0448\u043c\u0438 \u043c\u0430\u043d \u0430\u043d\u0434\u0430\u0440\u04e3,\n\u0414\u0430\u043c \u0437\u0430\u043d \u0437\u0430\u043c\u043e\u043d\u0430\u043a\u0435\u044e \u0431\u0430\u0440\u043e\u0441\u043e\u044e \u043a\u0430\u043c \u0433\u0438\u0440\u04e3!\n\u0418\u043d \u0440\u04ef\u0437\u0443 \u0448\u0430\u0431 \u0433\u0438\u0440\u0438\u0441\u0442\u0430\u043d\u0438 \u0437\u043e\u0440 \u0431\u0430\u04b3\u0440\u0438 \u0447\u0438\u0441\u0442?\n\u041d\u0435 \u0447\u0443\u043d \u043c\u0430\u043d\u04e3 \u0493\u0430\u0440\u0438\u0431\u0443 \u0493\u0430\u043c\u0438 \u0438\u0448\u049b \u0431\u0430\u0440 \u0441\u0430\u0440\u04e3.\n\u0414\u0430\u0440\u0434\u043e, \u04b7\u0443\u0434\u043e \u0431\u0438\u043c\u043e\u043d\u0434\u0430\u043c\u0443 \u0434\u0430\u0440 \u0493\u0430\u043c \u0437\u0438 \u0438\u0448\u049b\u0438 \u0451\u0440\n\u041c\u0430\u043d \u0437-\u0438\u043d \u0442\u0430\u0432\u043e\u043d\u0433\u0430\u0440\u0430\u043c, \u043a\u0438 \u043c\u0430\u0431\u043e\u0434 \u0438\u043d \u0442\u0430\u0432\u043e\u043d\u0433\u0430\u0440\u04e3!\n\u0401\u0440\u0435 \u0433\u0443\u0437\u0438\u0434\u0430\u043c \u0430\u0437 \u04b3\u0430\u043c\u0430 \u0445\u0430\u043b\u049b\u043e\u043d \u043f\u0430\u0440\u0438\u043d\u0430\u0436\u043e\u0434,\n\u0417-\u043e\u043d \u0448\u0443\u0434 \u0437\u0438 \u043f\u0435\u0448\u0438 \u0447\u0430\u0448\u043c\u0438 \u043c\u0430\u043d \u0438\u043c\u0440\u04ef\u0437 \u0447\u0443\u043d \u043f\u0430\u0440\u04e3.\n\u041b\u0430\u0448\u043a\u0430\u0440 \u0431\u0438\u0440\u0430\u0444\u0442\u0443 \u043e\u043d \u0431\u0443\u0442\u0438 \u043b\u0430\u0448\u043a\u0430\u0440\u0448\u0438\u043a\u0430\u043d \u0431\u0438\u0440\u0430\u0444\u0442,\n\u04b2\u0430\u0440\u0433\u0438\u0437 \u043c\u0430\u0431\u043e\u0434 \u043a\u0430\u0441, \u043a\u0438 \u0434\u0438\u04b3\u0430\u0434 \u0434\u0438\u043b \u0431\u0430 \u043b\u0430\u0448\u043a\u0430\u0440\u04e3!")
B.asc=new A.a("86d223be-5e7e-4100-ac7e-59c07d499107","e948618d-0c4c-484b-b60b-c1658bc51d57","\u041a\u043e\u0448\u043a\u04e3, \u0430\u043d\u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d \u0448\u0430\u0431 \u043d\u0435\u0441\u0442\u04e3,","\u041a\u043e\u0448\u043a\u04e3, \u0430\u043d\u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d \u0448\u0430\u0431 \u043d\u0435\u0441\u0442\u04e3,\n\u0422\u043e \u043c\u0430\u0440\u043e \u04b3\u0438\u04b7\u0440\u043e\u043d\u0438 \u043e\u043d \u043b\u0430\u0431 \u043d\u0435\u0441\u0442\u04e3.\n\u0417\u0430\u0445\u043c\u0438 \u0430\u049b\u0440\u0430\u0431 \u043d\u0435\u0441\u0442\u04e3 \u0431\u0430\u0440 \u04b7\u043e\u043d\u0438 \u043c\u0430\u043d,\n\u0413\u0430\u0440 \u0432\u0430\u0440\u043e \u0437\u0443\u043b\u0444\u0438 \u043c\u0443\u0430\u049b\u0440\u0430\u0431 \u043d\u0435\u0441\u0442\u04e3.\n\u0412-\u0430\u0440 \u043d\u0430\u0431\u0443\u0434\u04e3 \u043a\u0430\u0432\u043a\u0430\u0431\u0430\u0448 \u0434\u0430\u0440 \u0437\u0435\u0440\u0438 \u043b\u0430\u0431,\n\u041c\u04ef\u043d\u0438\u0441\u0430\u043c \u0442\u043e \u0440\u04ef\u0437 \u043a\u0430\u0432\u043a\u0430\u0431 \u043d\u0435\u0441\u0442\u04e3.\n\u0412-\u0430\u0440 \u043c\u0443\u0440\u0430\u043a\u043a\u0430\u0431 \u043d\u0435\u0441\u0442\u04e3 \u0430\u0437 \u043d\u0435\u043a\u0443\u04e3,\n\u04b6\u043e\u043d\u0430\u043c \u0430\u0437 \u0438\u0448\u049b\u0430\u0448 \u043c\u0443\u0440\u0430\u043a\u043a\u0430\u0431 \u043d\u0435\u0441\u0442\u04e3.\n\u0412-\u0430\u0440 \u043c\u0430\u0440\u043e \u0431\u0435 \u0451\u0440 \u0431\u043e\u044f\u0434 \u0437\u0438\u0441\u0442\u0430\u043d,\n\u0417\u0438\u043d\u0434\u0430\u0433\u043e\u043d\u04e3, \u043a\u043e\u0448, \u0451 \u0440\u0430\u0431, \u043d\u0435\u0441\u0442\u04e3!")
B.ae0=new A.a("ced2976b-0cca-4b3f-b081-b76810dc9c44","e948618d-0c4c-484b-b60b-c1658bc51d57","\u0414\u0430\u049b\u0438\u049b\u04e3, \u043c\u0438\u0441\u043b\u0438 \u04b3\u0430\u043c\u0430\u0438 \u0448\u043e\u0438\u0440\u043e\u043d\u0438 \u04b3\u0430...","\u0414\u0430\u049b\u0438\u049b\u04e3, \u043c\u0438\u0441\u043b\u0438 \u04b3\u0430\u043c\u0430\u0438 \u0448\u043e\u0438\u0440\u043e\u043d\u0438 \u04b3\u0430\u043c\u0437\u0430\u043c\u043e\u043d\u0430\u0448, \u0434\u0430\u0440 \u0433\u0443\u0444\u0442\u0430\u043d\u0438\n\u0431\u0430\u04b3\u043e\u0440\u0438\u044f \u04b3\u0443\u043d\u0430\u0440\u0438 \u0432\u043e\u043b\u043e \u0434\u043e\u0440\u0430\u0434. \u0422\u0430\u0441\u0432\u0438\u0440\u04b3\u043e\u0438 \u04ef, \u0434\u0430\u0440 \u0438\u043d \u0433\u0443\u043d\u0430 \u0448\u0435\u044a\u0440\u04b3\u043e\u044f\u0448\n\u0431\u0430\u0493\u043e\u044f\u0442 \u0433\u04ef\u0451, \u0437\u0438\u043d\u0434\u0430 \u0432\u0430 \u0437\u0435\u0431\u043e \u04b3\u0430\u0441\u0442\u0430\u043d\u0434.")
B.aiG=new A.a("ae3fd3a8-82bf-4dab-9e2a-a96041226efd","e948618d-0c4c-484b-b60b-c1658bc51d57","\u0411\u0430\u0440\u0430\u0444\u0433\u0430\u043d\u0434, \u044d\u0439 \u0441\u0430\u043d\u0430\u043c, \u0430\u0431\u0440\u0438 \u0431\u0438\u04b3\u0438...","\u0411\u0430\u0440\u0430\u0444\u0433\u0430\u043d\u0434, \u044d\u0439 \u0441\u0430\u043d\u0430\u043c, \u0430\u0431\u0440\u0438 \u0431\u0438\u04b3\u0438\u0448\u0442\u04e3\n\u0417\u0430\u043c\u0438\u043d\u0440\u043e \u0445\u0438\u043b\u044a\u0430\u0442\u0438 \u0443\u0440\u0434\u0438\u0431\u0438\u04b3\u0438\u0448\u0442\u04e3.\n\u0411\u0438\u04b3\u0438\u0448\u0442\u0438 \u0430\u0434\u043d\u0440\u043e \u0433\u0443\u043b\u0437\u043e\u0440 \u043c\u043e\u043d\u0430\u0434,\n\u0414\u0430\u0440\u0430\u0445\u0442 - \u043e\u0440\u043e\u0441\u0442\u0430 \u04b3\u0443\u0440\u0438 \u0431\u0438\u04b3\u0438\u0448\u0442\u04e3.")
B.ak0=new A.a("0c923d77-124b-4a24-8083-b99e4051b398","e948618d-0c4c-484b-b60b-c1658bc51d57","\u0417\u0430\u043c\u0438\u043d \u0431\u0430\u0440 \u0441\u043e\u043d\u0438 \u0445\u0443\u043d\u043e\u043b\u0443\u0434\u0430 \u0434\u0435\u0431\u043e,","\u0417\u0430\u043c\u0438\u043d \u0431\u0430\u0440 \u0441\u043e\u043d\u0438 \u0445\u0443\u043d\u043e\u043b\u0443\u0434\u0430 \u0434\u0435\u0431\u043e,\n\u04b2\u0430\u0432\u043e \u0431\u0430\u0440 \u0441\u043e\u043d\u0438 \u043d\u0438\u043b\u0430\u043d\u0434\u0443\u0434\u0430 \u0432\u0430\u0448\u0442\u04e3.\n\u0411\u0430 \u0442\u0430\u044a\u043c\u0438 \u043d\u04ef\u0448 \u0433\u0430\u0448\u0442\u0430 \u0447\u0430\u0448\u043c\u0430\u0438 \u043e\u0431,\n\u0411\u0430 \u0440\u0430\u043d\u0433\u0438 \u0434\u0438\u0434\u0430\u0438 \u043e\u04b3\u0443\u0438 \u0434\u0430\u0448\u0442\u04e3\u2026\n\u04b6\u0430\u04b3\u043e\u043d \u0442\u043e\u0432\u0443\u0441\u0433\u0443\u043d\u0430 \u0433\u0430\u0448\u0442\u0443 \u0434\u0438\u0434\u043e\u0440\n\u0411\u0430 \u04b7\u043e\u0439\u0438 \u043d\u0430\u0440\u043c\u0438\u044e \u04b7\u043e\u0438 \u0434\u0443\u0440\u0443\u0448\u0442\u04e3\n\u0411\u0430\u0434-\u043e\u043d \u043c\u043e\u043d\u0430\u0434, \u043a\u0438 \u0433\u04ef\u0439\u04e3 \u0430\u0437 \u043c\u0430\u044e \u043c\u0443\u0448\u043a\n\u041c\u0438\u0441\u043e\u043b\u0438 \u0434\u04ef\u0441\u0442 \u0431\u0430\u0440 \u0441\u0430\u04b3\u0440\u043e \u043d\u0430\u0432\u0430\u0448\u0442\u04e3.\n\u0417\u0438 \u0433\u0438\u043b \u0431\u04ef\u0439\u0438 \u0433\u0443\u043b\u043e\u0431 \u043e\u044f\u0434 \u0431\u0430\u0434-\u043e\u043d \u0441\u043e\u043d,\n\u041a\u0438 \u043f\u0438\u043d\u0434\u043e\u0440\u04e3 \u0433\u0438\u043b \u0430\u043d\u0434\u0430\u0440 \u0433\u0443\u043b \u0441\u0438\u0440\u0438\u0448\u0442\u04e3.")
