B.abl=new A.a("1c1963b4-838c-40dd-91a4-e0e14aaecd25","ac759bd8-fe4e-4ef3-9e2f-30226a014707","\u0411\u0430\u0441\u0435 \u0440\u0430\u043d\u04b7 \u0431\u0443\u0440\u0434\u0430\u043c, \u0431\u0430\u0441\u0435 \u043d\u043e\u043c\u0430 \u0445\u043e...","\u0411\u0430\u0441\u0435 \u0440\u0430\u043d\u04b7 \u0431\u0443\u0440\u0434\u0430\u043c, \u0431\u0430\u0441\u0435 \u043d\u043e\u043c\u0430 \u0445\u043e\u043d\u0434\u0430\u043c\n\u0417\u0438 \u0433\u0443\u0444\u0442\u043e\u0440\u0438 \u0442\u043e\u0437\u0438\u044e \u0430\u0437 \u043f\u0430\u04b3\u043b\u0430\u0432\u043e\u043d\u04e3.")
B.adb=new A.a("6568320b-7c81-4692-b235-2db8786f1e97","ac759bd8-fe4e-4ef3-9e2f-30226a014707","\u04b2\u0430\u043d\u0433\u043e\u043c\u0435 \u043a\u0438 \u0431\u043e \u0438\u0440\u043e\u0434\u0430 \u0432\u0430 \u043a\u04ef\u0448\u0438\u0448\u0438 ...","\u04b2\u0430\u043d\u0433\u043e\u043c\u0435 \u043a\u0438 \u0431\u043e \u0438\u0440\u043e\u0434\u0430 \u0432\u0430 \u043a\u04ef\u0448\u0438\u0448\u0438 \u0445\u0438\u0440\u0430\u0434\u043c\u0430\u043d\u0434\u0438 \u0434\u0435\u04b3\u049b\u043e\u043d\u043d\u0430\u0436\u043e\u0434\n\u0432\u0430 \u0430\u043c\u0438\u0440\u0438 \u0444\u0430\u0440\u04b3\u0430\u043d\u0433\u0434\u04ef\u0441\u0442 \u0410\u0431\u0443\u043c\u0430\u043d\u0441\u0443\u0440 \u041c\u0443\u04b3\u0430\u043c\u043c\u0430\u0434 \u0438\u0431\u043d\u0438 \u0410\u0431\u0434\u0443\u0440\u0440\u0430\u0437\u0437\u043e\u049b\u0438\n\u0422\u04ef\u0441\u04e3 \u0434\u0430\u0440 \u0441\u043e\u043b\u0438 957 \xab\u0428\u043e\u04b3\u043d\u043e\u043c\u0430\u0438 \u043c\u0430\u043d\u0441\u0443\u0440\xbb \u0444\u0430\u0440\u043e\u04b3\u0430\u043c \u043e\u043c\u0430\u0434, \u0424\u0438\u0440\u0434\u0430\u0432\u0441\u04e3\n\u04b7\u0430\u0432\u043e\u043d\u0438 \u04b3\u0430\u0431\u0434\u0430\u04b3\u0441\u043e\u043b\u0430 \u0431\u0443\u0434. \u041f\u0430\u0441 \u0430\u0437 \u0431\u0438\u0441\u0442 \u0441\u043e\u043b \u043e\u043d\u0440\u043e \u0414\u0430\u049b\u0438\u049b\u04e3 \u0431\u043e \u0444\u0430\u0440\u043c\u043e\u043d\u0438\n\u041d\u0443\u04b3 \u0438\u0431\u043d\u0438 \u041c\u0430\u043d\u0441\u0443\u0440\u0438 \u0421\u043e\u043c\u043e\u043d\u04e3 \u0431\u0430 \u043d\u0430\u0437\u043c \u0434\u0430\u0440\u043e\u0432\u0430\u0440\u0434\u0430\u043d\u04e3 \u043c\u0435\u0448\u0430\u0432\u0430\u0434. \u0413\u0443\u043c\u043e\u043d\u0438\n\u044f\u049b\u0438\u043d \u043e\u043d \u0430\u0441\u0442, \u043a\u0438 \u043e\u0448\u043d\u043e\u04e3 \u0431\u043e \xab\u0428\u043e\u04b3\u043d\u043e\u043c\u0430\xbb-\u0438 \u0410\u0431\u0443\u043c\u0430\u043d\u0441\u0443\u0440\u04e3 \u0432\u0430 \u04b3\u0430\u0437\u043e\u0440 \u0431\u0430\u0439\u0442\u0438\n\u043c\u0430\u0441\u043d\u0430\u0432\u0438\u0438 \u043d\u043e\u0442\u0430\u043c\u043e\u043c\u0438 \u0414\u0430\u049b\u0438\u049b\u04e3, \u043a\u0438 \u04b3\u0430\u0440 \u0434\u0443 \u0434\u0430\u0440 \u0422\u04ef\u0441 \u0430\u043d\u04b7\u043e\u043c \u0433\u0438\u0440\u0438\u0444\u0442\u0430\u0430\u043d\u0434,\n\u0434\u0430\u0440 \u0434\u0438\u043b\u0438 \u0424\u0438\u0440\u0434\u0430\u0432\u0441\u04e3, \u043a\u0438 \u043d\u0438\u0433\u0430\u0440\u043e\u043d\u0438 \u0441\u0430\u0440\u043d\u0430\u0432\u0438\u0448\u0442\u0438 \u042d\u0440\u043e\u043d \u0432\u0430 \u0442\u0430\u044a\u0440\u0438\u0445 \u0432\u0430\n\u0444\u0430\u0440\u04b3\u0430\u043d\u0433\u0438 \u043e\u043d \u0431\u0443\u0434, \u0448\u0430\u0432\u049b\u0438 \u044d\u04b7\u043e\u0434\u0438 \xab\u0428\u043e\u04b3\u043d\u043e\u043c\u0430\xbb-\u0440\u043e \u043f\u0430\u0440\u0432\u0430\u0440\u0438\u0448 \u0434\u043e\u0434\u0430\u043d\u0434.")
B.aer=new A.a("5bae99d0-d2f9-46b3-9b1a-bc3d47178925","ac759bd8-fe4e-4ef3-9e2f-30226a014707","\u0413\u0443\u0448\u043e\u0434\u0430 \u0437\u0430\u0431\u043e\u043d\u0443 \u04b7\u0430\u0432\u043e\u043d\u0438\u0442 \u04b3\u0430\u0441\u0442,","\u0413\u0443\u0448\u043e\u0434\u0430 \u0437\u0430\u0431\u043e\u043d\u0443 \u04b7\u0430\u0432\u043e\u043d\u0438\u0442 \u04b3\u0430\u0441\u0442,\n\u0421\u0443\u0445\u0430\u043d \u0433\u0443\u0444\u0442\u0430\u043d\u0438 \u043f\u0430\u04b3\u043b\u0430\u0432\u043e\u043d\u0438\u0442 \u04b3\u0430\u0441\u0442.")
B.al8=new A.a("fab9a9e1-e38f-4369-b72c-190fe2617c4b","ac759bd8-fe4e-4ef3-9e2f-30226a014707","\u0422\u0430\u04b3\u0440\u0438\u0440\u0438 \u043d\u0430\u0445\u0443\u0441\u0442\u0438\u043d\u0438 \xab\u0428\u043e\u04b3\u043d\u043e\u043c\u0430\xbb-\u0440\u043e...","\u0422\u0430\u04b3\u0440\u0438\u0440\u0438 \u043d\u0430\u0445\u0443\u0441\u0442\u0438\u043d\u0438 \xab\u0428\u043e\u04b3\u043d\u043e\u043c\u0430\xbb-\u0440\u043e \u0424\u0438\u0440\u0434\u0430\u0432\u0441\u04e3 \u0434\u0430\u0440 \u043f\u0430\u043d\u04b7\u043e\u04b3\u0443\xad\n\u043f\u0430\u043d\u04b7\u0441\u043e\u043b\u0430\u0433\u0438\u0430\u0448, \u0434\u0430\u0440 25 \u0438\u0441\u0444\u0430\u043d\u0434\u0438 \u0441\u043e\u043b\u0438 384 \u04b3\u0438\u04b7\u0440\u04e3 \u043c\u0443\u0442\u043e\u0431\u0438\u049b \u0431\u0430\n16-\u0443\u043c\u0438 \u043c\u0430\u0440\u0442\u0438 \u0441\u043e\u043b\u0438 994-995 \u043c\u0438\u043b\u043e\u0434\u04e3 \u0431\u0430 \u043e\u0445\u0438\u0440 \u0440\u0430\u0441\u043e\u043d\u0438\u0434\u0430 \u0431\u0443\u0434\u0430\u0430\u0441\u0442\n\u0432\u0430 \u043e\u043d \u0431\u0435\u0448\u0442\u0430\u0440 \u0434\u043e\u0441\u0442\u043e\u043d\u04b3\u043e\u0438 \u043f\u0430\u04b3\u043b\u0430\u0432\u043e\u043d\u0438\u0440\u043e \u0434\u0430\u0440 \u0431\u0430\u0440 \u0434\u043e\u0448\u0442\u0430, \u049b\u0438\u0441\u043c\u0430\u0442\u0438\n\u0442\u0430\u044a\u0440\u0438\u0445\u04e3 \u0434\u0430\u0440 \u043e\u043d \u0431\u0430 \u0438\u0445\u0442\u0438\u0441\u043e\u0440 \u0431\u0430\u0451\u043d \u0448\u0443\u0434\u0430 \u0431\u0443\u0434. \u0418\u043d \u0442\u0430\u04b3\u0440\u0438\u0440, \u0431\u0430 \u043d\u043e\u043c\u0438\n\u04b3\u0435\u0447 \u043f\u043e\u0434\u0448\u043e\u04b3\u0435 \u0442\u0430\u049b\u0434\u0438\u043c \u043d\u0430\u0448\u0443\u0434\u0430 \u0431\u0443\u0434, \u0437\u0435\u0440\u043e \u043a\u0430\u0441\u0438 \u0441\u0430\u0437\u043e\u0432\u043e\u0440\u0435 \u0451\u0444\u0442 \u043d\u0430\u0448\u0443\u0434,\n\u043a\u0438 \u0448\u043e\u0438\u0440 \u043e\u043d\u0440\u043e \u0431\u0430 \u043d\u043e\u043c\u0438 \u04ef \u043a\u0443\u043d\u0430\u0434.")
