B.ana=new A.a("86dacb08-6b0a-42ac-a4d7-daa2cb99ce3f","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u041a\u0430\u0441 \u0430\u043d\u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d \u04b7\u043e\u0432\u0438\u0434\u043e\u043d\u0430 \u043d\u0430\u043c\u043e\u043d...","\u041a\u0430\u0441 \u0430\u043d\u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d \u04b7\u043e\u0432\u0438\u0434\u043e\u043d\u0430 \u043d\u0430\u043c\u043e\u043d\u0434,\n\u0417\u0438 \u0433\u0430\u0440\u0434\u0443\u043d \u043c\u0430\u0440\u043e \u0445\u0443\u0434 \u0431\u0430\u04b3\u043e\u043d\u0430 \u043d\u0430\u043c\u043e\u043d\u0434...\n\u0410\u0433\u0430\u0440 \u0441\u043e\u043b \u0433\u0430\u0440\u0434\u0430\u0434 \u0444\u0443\u0437\u0443\u043d \u0430\u0437 \u04b3\u0430\u0437\u043e\u0440,\n\u04b2\u0430\u043c\u0438\u043d \u0430\u0441\u0442 \u0440\u043e\u04b3\u0443 \u04b3\u0430\u043c\u0438\u043d \u0430\u0441\u0442 \u043a\u043e\u0440.\n\u041d\u0438\u0433\u0430\u04b3 \u043a\u0443\u043d \u0431\u0430 \u04b6\u0430\u043c\u0448\u0435\u0434\n\u2013\n\u0448\u043e\u04b3\u0438 \u0431\u0430\u043b\u0430\u043d\u0434,\n\u04b2\u0430\u043c\u043e\u043d \u043d\u0438\u0437 \u0422\u0430\u04b3\u043c\u0443\u0440\u0430\u0441\u0438 \u0414\u0435\u0432\u0431\u0430\u043d\u0434.\n\u0411\u0430 \u0433\u0435\u0442\u04e3 \u0447\u0443 \u044d\u0448\u043e\u043d \u043d\u0430\u0431\u0443\u0434 \u0448\u0430\u04b3\u0440\u0451\u0440,\n\u0421\u0430\u0440\u0430\u043d\u04b7\u043e\u043c \u0440\u0430\u0444\u0442\u0430\u043d\u0434 \u0437\u04e3 \u041a\u0438\u0440\u0434\u0433\u043e\u0440.\n\u0427\u0443 \u0433\u0435\u0442\u04e3 \u0431\u0430\u0440 \u044d\u0448\u043e\u043d \u043d\u0430\u043c\u043e\u043d\u0434\u0443 \u0431\u0438\u0433\u0430\u0448\u0442,\n\u041c\u0430\u0440\u043e \u043d\u0438\u0437 \u0431\u0430\u0440 \u0440\u0430\u04b3 \u0431\u0438\u0431\u043e\u044f\u0434 \u0433\u0443\u0437\u0430\u0448\u0442.")
B.al0=new A.a("d4533ca6-4fa8-4324-ab00-87690f4e84e1","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0430\u043d\u0434\u0430\u0440\u0443\u043d \u0434\u0438\u043b \u043d\u0430\u0434\u043e\u0440\u0430\u0434 \u0434\u0438\u0436\u0430\u043c.","\u0430\u043d\u0434\u0430\u0440\u0443\u043d \u0434\u0438\u043b \u043d\u0430\u0434\u043e\u0440\u0430\u0434 \u0434\u0438\u0436\u0430\u043c.\n\u0411\u0430\u0440\u0443 \u043a\u0438\u0442\u0444\u0443 \u0451\u043b\u0430\u0448 \u0431\u0430 \u043c\u043e\u043d\u0430\u043d\u0434\u0438 \u043c\u0430\u043d,\n\u0422\u0443 \u0433\u04ef\u04e3, \u043a\u0438 \u0434\u043e\u043d\u0430\u043d\u0434\u0430 \u0431\u0430\u0440\u0437\u0430\u0434 \u0440\u0430\u0441\u0430\u043d.\n\u0417\u0438 \u043f\u043e\u044e \u0440\u0438\u043a\u0435\u0431\u0430\u0448 \u04b3\u0430\u043c\u0435 \u043c\u0435\u04b3\u0440\u0438 \u043c\u0430\u043d\n\u0411\u0438\u04b7\u0443\u043d\u0431\u0430\u0434, \u0431\u0430 \u0448\u0430\u0440\u043c \u043e\u0432\u0430\u0440\u0430\u0434 \u0447\u0435\u04b3\u0440\u0438 \u043c\u0430\u043d.\n\u041d\u0438\u0448\u043e\u043d\u04b3\u043e\u0438 \u043c\u043e\u0434\u0430\u0440 \u0431\u0438\u0451\u0431\u0430\u043c \u04b3\u0430\u043c\u0435,\n\u0411\u0430 \u0434\u0438\u043b \u043d\u0438\u0437 \u043b\u0430\u0445\u0442\u0435 \u0431\u0438\u0442\u043e\u0431\u0430\u043c \u04b3\u0430\u043c\u0435.\n\u0413\u0443\u043c\u043e\u043d\u0435 \u0431\u0430\u0440\u0430\u043c \u043c\u0430\u043d, \u043a\u0438 \u04ef \u0420\u0443\u0441\u0442\u0430\u043c \u0430\u0441\u0442,\n\u041a\u0438 \u0447\u0443\u043d \u04ef \u043d\u0430\u0431\u0430\u0440\u0434\u0430 \u0431\u0430 \u0433\u0435\u0442\u04e3 \u043a\u0430\u043c \u0430\u0441\u0442.\n\u041d\u0430\u0431\u043e\u044f\u0434, \u043a\u0438 \u043c\u0430\u043d \u0431\u043e \u043f\u0430\u0434\u0430\u0440 \u04b7\u0430\u043d\u0433\u04b7\u04ef\u0439\n\u0428\u0430\u0432\u0430\u043c \u0445\u0438\u0440\u0430, \u0440\u04ef \u0430\u043d\u0434\u0430\u0440\u043e\u0440\u0430\u043c \u0431\u0430\u0440 \u04ef\u0439\n\xbb\n.")
B.ahS=new A.a("14f1a619-d4f3-451d-b39a-59e2f3968804","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0417\u0438 \u0420\u0443\u0441\u0442\u0430\u043c \u0431\u0438\u043f\u0443\u0440\u0441\u0438\u0434 \u0445\u0430\u043d\u0434\u043e\u043d \u0434\u0443 \u043b...","\u0417\u0438 \u0420\u0443\u0441\u0442\u0430\u043c \u0431\u0438\u043f\u0443\u0440\u0441\u0438\u0434 \u0445\u0430\u043d\u0434\u043e\u043d \u0434\u0443 \u043b\u0430\u0431,\n\u0422\u0443 \u0433\u0443\u0444\u0442\u04e3, \u043a\u0438 \u0431\u043e \u04ef \u0431\u0430 \u04b3\u0430\u043c \u0431\u0443\u0434 \u0448\u0430\u0431,\n\u041a\u0438\n\xab\n\u0448\u0430\u0431 \u0447\u0443\u043d \u0431\u0443\u0434\u04e3, \u0440\u04ef\u0437 \u0447\u0443\u043d \u0445\u043e\u0441\u0442\u04e3?\n\u0417\u0438 \u043f\u0430\u0439\u043a\u043e\u0440 \u0434\u0438\u043b \u0431\u0430\u0440 \u0447\u04e3 \u043e\u0440\u043e\u0441\u0442\u04e3?\n\u0417\u0438 \u043a\u0430\u0444 \u0431\u0438\u0444\u0433\u0430\u043d \u0438\u043d \u0442\u0438\u0440\u0443 \u0448\u0430\u043c\u0448\u0435\u0440\u0438 \u043a\u0438\u043d,\n\u0411\u0438\u0437\u0430\u043d \u0447\u0430\u043d\u0433\u0438 \u0431\u0435\u0434\u043e\u0434\u0440\u043e \u0431\u0430\u0440 \u0437\u0430\u043c\u0438\u043d.\n\u041d\u0438\u0448\u0438\u043d\u0435\u043c \u04b3\u0430\u0440 \u0434\u0443 \u043f\u0438\u0451\u0434\u0430 \u0431\u0430 \u04b3\u0430\u043c,\n\u0411\u0430 \u043c\u0430\u0439 \u0442\u043e\u0437\u0430 \u0434\u043e\u0440\u0435\u043c \u0440\u04ef\u0439\u0438 \u0434\u0438\u0436\u0430\u043c.\n\u0411\u0430 \u043f\u0435\u0448\u0438 \u04b7\u0430\u04b3\u043e\u043d\u0434\u043e\u0440 \u043f\u0430\u0439\u043c\u043e\u043d \u043a\u0443\u043d\u0435\u043c,\n\u0414\u0438\u043b \u0430\u0437 \u04b7\u0430\u043d\u0433 \u04b7\u0443\u0441\u0442\u0430\u043d \u043f\u0443\u0448\u0430\u0439\u043c\u043e\u043d \u043a\u0443\u043d\u0435\u043c.\n\u04b2\u0430\u043c\u043e\u043d \u0442\u043e \u043a\u0430\u0441\u0438 \u0434\u0438\u0433\u0430\u0440 \u043e\u044f\u0434 \u0431\u0430 \u0440\u0430\u0437\u043c,\n\u0422\u0443 \u0431\u043e \u043c\u0430\u043d \u0431\u0438\u0441\u043e\u0437\u0443 \u0431\u0438\u0451\u0440\u043e\u0439 \u0431\u0430\u0437\u043c.\n\u0414\u0438\u043b\u0438 \u043c\u0430\u043d \u04b3\u0430\u043c\u0435 \u0431\u0430\u0440 \u0442\u0443 \u043c\u0435\u04b3\u0440 \u043e\u0432\u0430\u0440\u0430\u0434,\n\u04b2\u0430\u043c\u0435 \u043e\u0431\u0438 \u0448\u0430\u0440\u043c\u0430\u043c \u0431\u0430 \u0447\u0435\u04b3\u0440 \u043e\u0432\u0430\u0440\u0430\u0434.\n\u04b2\u0430\u043c\u043e\u043d\u043e, \u043a\u0438 \u0434\u043e\u0440\u04e3 \u0437\u0438 \u0433\u0443\u0440\u0434\u043e\u043d \u043d\u0430\u0436\u043e\u0434,\n\u041a\u0443\u043d\u04e3 \u043f\u0435\u0448\u0438 \u043c\u0430\u043d \u0433\u0430\u0432\u04b3\u0430\u0440\u0438 \u0445\u0435\u0448 \u0451\u0434.\n\u0417\u0438 \u043c\u0430\u043d \u043d\u043e\u043c \u043f\u0438\u043d\u04b3\u043e\u043d \u043d\u0430\u0431\u043e\u044f\u0434-\u0442 \u043a\u0430\u0440\u0434,\n\u0427\u0443 \u0433\u0430\u0448\u0442\u04e3 \u0442\u0443 \u0431\u043e \u043c\u0430\u043d \u043a\u0443\u043d\u0443\u043d \u04b3\u0430\u043c\u043d\u0430\u0431\u0430\u0440\u0434.\n\u041c\u0430\u0433\u0430\u0440 \u043f\u0443\u0440\u0438 \u0414\u0430\u0441\u0442\u043e\u043d\u0438 \u0421\u043e\u043c\u0438 \u044f\u043b\u04e3,\n\u0413\u0443\u0437\u0438\u043d \u043d\u043e\u043c\u0432\u0430\u0440 \u0420\u0443\u0441\u0442\u0430\u043c\u0438 \u0417\u043e\u0431\u0443\u043b\u04e3?\n\xbb")
B.ajX=new A.a("8b13192c-7df3-40cc-905f-9317efbced03","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u041d\u0438\u0448\u043e\u043d \u0434\u043e\u0434 \u043c\u043e\u0434\u0430\u0440 \u043c\u0430\u0440\u043e \u0430\u0437 \u043f\u0430\u0434\u0430\u0440,","\u041d\u0438\u0448\u043e\u043d \u0434\u043e\u0434 \u043c\u043e\u0434\u0430\u0440 \u043c\u0430\u0440\u043e \u0430\u0437 \u043f\u0430\u0434\u0430\u0440,\n\u0417\u0438 \u043c\u0435\u04b3\u0440 \u0430\u043d\u0434\u0430\u0440\u043e\u043c\u0430\u0434 \u0440\u0430\u0432\u043e\u043d\u0430\u043c \u0431\u0430 \u0441\u0430\u0440.\n\u04b2\u0430\u043c\u0435\u04b7\u0443\u0441\u0442\u0430\u043c\u0430\u0448, \u0442\u043e \u0431\u0438\u0431\u0438\u043d\u0430\u043c")
B.apK=new A.a("6fbf142f-66ad-4b78-bbb4-2ab90d473c62","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0438\u043d \u043e\u0440\u0437\u0443\u0439.","\u0438\u043d \u043e\u0440\u0437\u0443\u0439.\n\u0414\u0430\u0440\u0435\u0493\u043e, \u043a\u0438 \u0440\u0430\u043d\u04b7\u0430\u043c \u043d\u0430\u0451\u043c\u0430\u0434 \u0431\u0430 \u0441\u0430\u0440,\n\u041d\u0430\u0434\u0438\u0434\u0430\u043c \u0434\u0430\u0440 \u0438\u043d \u04b3\u0435\u0447 \u0440\u04ef\u0439\u0438 \u043f\u0430\u0434\u0430\u0440.\n\u041a\u0443\u043d\u0443\u043d \u0433\u0430\u0440 \u0442\u0443 \u0434\u0430\u0440 \u043e\u0431 \u043c\u043e\u04b3\u04e3 \u0448\u0430\u0432\u04e3\n\u0412\u0430 \u0451 \u0447\u0443\u043d \u0448\u0430\u0431 \u0430\u043d\u0434\u0430\u0440 \u0441\u0438\u0451\u04b3\u04e3 \u0448\u0430\u0432\u04e3\n\u0412\u0430 \u0451 \u0447\u0443\u043d \u0441\u0438\u0442\u043e\u0440\u0430 \u0448\u0430\u0432\u04e3 \u0431\u0430\u0440 \u0441\u0438\u043f\u0435\u04b3\u0440,\n\u0411\u0438\u0431\u0443\u0440\u0440\u04e3 \u0437\u0438 \u0440\u04ef\u0439\u0438 \u0437\u0430\u043c\u0438\u043d \u043f\u043e\u043a \u043c\u0435\u04b3\u0440,\n\u0411\u0438\u0445\u043e\u04b3\u0430\u0434 \u04b3\u0430\u043c \u0430\u0437 \u0442\u0443 \u043f\u0430\u0434\u0430\u0440 \u043a\u0438\u043d\u0438 \u043c\u0430\u043d,\n\u0427\u0443 \u0431\u0438\u043d\u0430\u0434, \u043a\u0438 \u0445\u0438\u0448\u0442 \u0430\u0441\u0442 \u0431\u043e\u043b\u0438\u043d\u0438 \u043c\u0430\u043d.")
