B.aig=new A.a("0534333d-dee8-46ef-acf1-49a15b97965d","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0410\u0437 \u044d\u0440\u043e\u043d\u0438\u0451\u043d \u0441\u0430\u0440 \u0431\u0438\u0431\u0443\u0440\u0440\u0430\u043c \u04b3\u0430\u0437\u043e\u0440,","\u0410\u0437 \u044d\u0440\u043e\u043d\u0438\u0451\u043d \u0441\u0430\u0440 \u0431\u0438\u0431\u0443\u0440\u0440\u0430\u043c \u04b3\u0430\u0437\u043e\u0440,\n\u041a\u0443\u043d\u0430\u043c \u0437\u0438\u043d\u0434\u0430 \u041a\u043e\u0432\u0443\u0441\u0438 \u043a\u0430\u0439\u0440\u043e \u0431\u0430 \u0434\u043e\u0440\n\xbb\n.\n\u0410\u0433\u0430\u0440 \u043c\u043e\u043d\u0430\u0434 \u04ef \u0437\u0438\u043d\u0434\u0430 \u0430\u043d\u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d,\n\u0411\u0438\u043f\u0435\u0447\u0430\u043d\u0434 \u0430\u0437 \u04ef \u04b3\u0430\u043c \u043c\u0435\u04b3\u043e\u043d\u0443 \u043a\u0435\u04b3\u043e\u043d.\n\u041a\u0430\u0441\u0435 \u0434\u0443\u0448\u043c\u0430\u043d\u0438 \u0445\u0435\u0448\u0442\u0430\u043d \u043f\u0430\u0440\u0432\u0430\u0440\u0430\u0434,\n\u0411\u0430 \u0433\u0435\u0442\u04e3")
B.aiC=new A.a("1013ed3b-2c64-4a21-8969-bf29704db4fe","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u041a\u0438\u0440\u043e \u043e\u043c\u0430\u0434 \u0438\u043d \u043f\u0435\u0448, \u043a-\u043e\u043c\u0430\u0434 \u043c\u0430\u0440\u043e,","\u041a\u0438\u0440\u043e \u043e\u043c\u0430\u0434 \u0438\u043d \u043f\u0435\u0448, \u043a-\u043e\u043c\u0430\u0434 \u043c\u0430\u0440\u043e,\n\u041a\u0438 \u0444\u0430\u0440\u0437\u0430\u043d\u0434 \u043a\u0443\u0448\u0442\u0430\u043c \u0431\u0430 \u043f\u0438\u0440\u043e\u043d\u0441\u0430\u0440\u043e?...\n\u0427\u0443 \u043c\u0430\u043d \u043d\u0435\u0441\u0442 \u0434\u0430\u0440 \u0433\u0438\u0440\u0434\u0438 \u041a\u0430\u0439\u04b3\u043e\u043d \u044f\u043a\u0435,\n\u0411\u0430 \u043c\u0430\u0440\u0434\u04e3 \u0431\u0443\u0434\u0430\u043c \u043f\u0435\u0448\u0438 \u04ef \u043a\u04ef\u0434\u0430\u043a\u0435.\n\u0411\u0443\u0440\u0438\u0434\u0430\u043d \u0434\u0443 \u0434\u0430\u0441\u0442\u0430\u043c \u0441\u0430\u0437\u043e\u0432\u043e\u0440 \u04b3\u0430\u0441\u0442,\n\u04b6\u0443\u0437 \u0430\u0437 \u0445\u043e\u043a\u0438 \u0442\u0438\u0440\u0430 \u043c\u0430\u0431\u043e\u0434\u0430\u043c \u043d\u0438\u0448\u0430\u0441\u0442.\n\u0427\u04e3 \u0433\u04ef\u044f\u043c, \u0447\u0443 \u043e\u0433\u0430\u04b3 \u0448\u0430\u0432\u0430\u0434 \u043c\u043e\u0434\u0430\u0440\u0430\u0448?\n\u0427\u04e3 \u0433\u0443\u043d\u0430 \u0444\u0438\u0440\u0438\u0441\u0442\u0430\u043c \u043a\u0430\u0441\u0435\u0440\u043e \u0431\u0430\u0440\u0430\u0448?\n\u0427\u04e3 \u0433\u04ef\u044f\u043c, \u0447\u0430\u0440\u043e \u043a\u0443\u0448\u0442\u0430\u043c\u0430\u0448 \u0431\u0435\u0433\u0443\u043d\u043e\u04b3,\n\u0427\u0430\u0440\u043e \u0440\u04ef\u0437 \u043a\u0430\u0440\u0434\u0430\u043c \u0431\u0430\u0440 \u04ef-\u0431\u0430\u0440 \u0441\u0438\u0451\u04b3?\n\u041a\u0430\u0434\u043e\u043c\u0438\u043d \u043f\u0430\u0434\u0430\u0440 \u04b3\u0430\u0440\u0433\u0438\u0437 \u0438\u043d \u043a\u043e\u0440 \u043a\u0430\u0440\u0434?\n\u0421\u0430\u0437\u043e\u0432\u043e\u0440\u0430\u043c \u0430\u043a\u043d\u0443\u043d \u0431\u0430 \u0433\u0443\u0444\u0442\u043e\u0440\u0438 \u0441\u0430\u0440\u0434.\n\u0411\u0430 \u0433\u0435\u0442\u04e3 \u043a\u04e3 \u043a\u0443\u0448\u0442\u0430\u0441\u0442 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0440\u043e,\n\u0414\u0430\u043b\u0435\u0440\u0443 \u04b7\u0430\u0432\u043e\u043d\u0443 \u0445\u0438\u0440\u0430\u0434\u043c\u0430\u043d\u0434\u0440\u043e?!\n\u041f\u0430\u0434\u0430\u0440-\u0448, \u043e\u043d \u0433\u0430\u0440\u043e\u043d\u043c\u043e\u044f\u0442\u0430\u0440 \u043f\u0430\u04b3\u043b\u0430\u0432\u043e\u043d,\n\u0427\u04e3 \u0433\u04ef\u044f\u0434 \u0431\u0430\u0434")
B.alU=new A.a("bbb6f7f8-fb3e-4202-981d-22191690bad4","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u043e\u043d \u0434\u0443\u0445\u0442\u0438 \u043f\u043e\u043a\u0438 \u04b7\u0430\u0432\u043e\u043d?","\u043e\u043d \u0434\u0443\u0445\u0442\u0438 \u043f\u043e\u043a\u0438 \u04b7\u0430\u0432\u043e\u043d?\n\u0411\u0430\u0440 \u0438\u043d \u0442\u0443\u0445\u043c\u0430\u0438 \u0421\u043e\u043c \u043d\u0430\u0444\u0440\u0438\u043d \u043a\u0443\u043d\u0430\u0434,\n\u041c\u0430\u0440\u043e \u043d\u043e\u043c \u0431\u0435\u043c\u0435\u04b3\u0440\u0443 \u0431\u0435\u0434\u0438\u043d \u043a\u0443\u043d\u0430\u0434.\n\u041a\u04e3 \u0434\u043e\u043d\u0438\u0441\u0442, \u043a-\u0438\u043d \u043a\u04ef\u0434\u0430\u043a\u0438 \u0430\u0440\u04b7\u043c\u0430\u043d\u0434\n\u0411\u0430\u0434-\u0438\u043d \u0441\u043e\u043b \u0433\u0430\u0440\u0434\u0430\u0434 \u0447\u0443 \u0441\u0430\u0440\u0432\u0438 \u0431\u0430\u043b\u0430\u043d\u0434?!\n\u0411\u0430 \u04b7\u0430\u043d\u0433 \u043e\u044f\u0434\u0430\u0448 \u0440\u043e\u044e \u0441\u043e\u0437\u0430\u0434 \u0441\u0438\u043f\u043e\u04b3,\n\u0411\u0430 \u043c\u0430\u043d-\u0431\u0430\u0440 \u043a\u0443\u043d\u0430\u0434 \u0440\u04ef\u0437\u0438 \u0440\u0430\u0432\u0448\u0430\u043d \u0441\u0438\u0451\u04b3?")
B.a7I=new A.a("43eb3d2c-1342-4c37-871e-26a2377a911f","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u04b6\u0430\u04b3\u043e\u043d \u0447\u0443\u043d \u0442\u0443 \u0434\u0438\u0433\u0430\u0440 \u043d\u0430\u0431\u0438\u043d\u0430\u0434 \u0441\u0430\u0432...","\u04b6\u0430\u04b3\u043e\u043d \u0447\u0443\u043d \u0442\u0443 \u0434\u0438\u0433\u0430\u0440 \u043d\u0430\u0431\u0438\u043d\u0430\u0434 \u0441\u0430\u0432\u043e\u0440\n\u0411\u0430 \u043c\u0430\u0440\u0434\u0438\u044e \u0433\u0443\u0440\u0434\u04e3 \u0433\u0430\u04b3\u0438 \u043a\u043e\u0440\u0437\u043e\u0440.\n\u0414\u0430\u0440\u0435\u0493 \u043e\u043d \u04b3\u0430\u043c\u0430 \u043c\u0430\u0440\u0434\u0438\u044e \u0440\u043e\u0439\u0438 \u0442\u0443,\n\u0414\u0430\u0440\u0435\u0493 \u043e\u043d \u0440\u0443\u0445\u0443 \u0431\u0443\u0440\u0437\u0443 \u0431\u043e\u043b\u043e\u0438 \u0442\u0443!\n\u0414\u0430\u0440\u0435\u0493 \u0438\u043d \u0493\u0430\u043c\u0443 \u04b3\u0430\u0441\u0440\u0430\u0442\u0438 \u04b7\u043e\u043d\u0433\u0443\u0441\u0438\u043b,\n\u0417\u0438 \u043c\u043e\u0434\u0430\u0440 \u04b7\u0443\u0434\u043e \u0432")
