B.ar6=new A.a("f8239d99-1962-4b91-8644-b10082cd0c7b","bcb9a591-92bb-405b-bcf5-f58a6aaa65cc","\u04b2\u0430\u0440 \u0431\u043e\u0434, \u043a\u0438 \u0430\u0437 \u0441\u04ef\u0439\u0438 \u0411\u0443\u0445\u043e\u0440\u043e \u0431\u0430 ...","\u04b2\u0430\u0440 \u0431\u043e\u0434, \u043a\u0438 \u0430\u0437 \u0441\u04ef\u0439\u0438 \u0411\u0443\u0445\u043e\u0440\u043e \u0431\u0430 \u043c\u0430\u043d \u043e\u044f\u0434,\n\u0411\u043e \u0431\u04ef\u0439\u0438 \u0433\u0443\u043b\u0443 \u043c\u0443\u0448\u043a\u0443 \u043d\u0430\u0441\u0438\u043c\u0438 \u0441\u0443\u043c\u0430\u043d \u043e\u044f\u0434.\n\u0411\u0430\u0440 \u04b3\u0430\u0440 \u0437\u0430\u043d\u0443 \u04b3\u0430\u0440 \u043c\u0430\u0440\u0434 \u043a\u0443\u04b7\u043e \u0431\u0430\u0440\u0432\u0430\u0437\u0430\u0434 \u0438\u043d \u0431\u043e\u0434?\n\u0413\u04ef\u0439\u04e3, \u043c\u0430\u0433\u0430\u0440 \u043e\u043d \u0431\u043e\u0434 \u04b3\u0430\u043c\u0435 \u0430\u0437 \u0425\u0443\u0442\u0430\u043d \u043e\u044f\u0434.\n\u041d\u0435, \u043d\u0435, \u0437\u0438 \u0425\u0443\u0442\u0430\u043d \u0431\u043e\u0434 \u0447\u0443\u043d\u0438\u043d \u0445\u0443\u0448 \u043d\u0430\u0432\u0430\u0437\u0430\u0434 \u04b3\u0435\u0447,\n\u041a-\u043e\u043d \u0431\u043e\u0434 \u04b3\u0430\u043c\u0435 \u0430\u0437 \u0431\u0430\u0440\u0438 \u043c\u0430\u044a\u0448\u0443\u049b\u0438 \u043c\u0430\u043d \u043e\u044f\u0434.")
B.aiz=new A.a("ecd29bc8-e26c-43b2-b5f3-f2bc05303ae7","bcb9a591-92bb-405b-bcf5-f58a6aaa65cc","\u0411\u0438\u0445\u0430\u043d\u0434\u0430\u0434 \u043b\u043e\u043b\u0430 \u0434\u0430\u0440 \u0441\u0430\u04b3\u0440\u043e","\u0411\u0438\u0445\u0430\u043d\u0434\u0430\u0434 \u043b\u043e\u043b\u0430 \u0434\u0430\u0440 \u0441\u0430\u04b3\u0440\u043e\n\u0411\u0430 \u0441\u043e\u043d\u0438 \u0447\u0435\u04b3\u0440\u0430\u0438 \u041b\u0430\u0439\u043b\u043e.\n\u0411\u0438\u0433\u0438\u0440\u044f\u0434 \u0430\u0431\u0440 \u0434\u0430\u0440 \u0433\u0430\u0440\u0434\u0443\u043d\n\u0411\u0430 \u0441\u043e\u043d\u0438 \u0434\u0438\u0434\u0430\u0438 \u041c\u0430\u04b7\u043d\u0443\u043d.\n\u0417\u0438 \u043e\u0431\u0438 \u04b7\u04ef\u0439 \u04b3\u0430\u0440 \u0441\u043e\u0430\u0442\n\u04b2\u0430\u043c\u0435 \u0431\u04ef\u0439\u0438 \u0433\u0443\u043b\u043e\u0431 \u043e\u044f\u0434.\n\u0414\u0430\u0440 \u04ef \u0448\u0443\u0441\u0442\u0430\u0441\u0442, \u043f\u0438\u043d\u0434\u043e\u0440\u04e3,\n\u041d\u0438\u0433\u043e\u0440\u0438 \u043c\u0430\u043d \u0440\u0443\u0445\u0438 \u0433\u0443\u043b\u0433\u0443\u043d.")
B.aaQ=new A.a("53bda18f-2535-41d8-a6be-c1e438656d17","bcb9a591-92bb-405b-bcf5-f58a6aaa65cc","\u041e\u043c\u0430\u0434 \u0431\u0430\u04b3\u043e\u0440\u0438 \u0445\u0443\u0440\u0440\u0430\u043c \u0431\u043e \u0440\u0430\u043d\u0433\u0443 \u0431\u04ef...","\u041e\u043c\u0430\u0434 \u0431\u0430\u04b3\u043e\u0440\u0438 \u0445\u0443\u0440\u0440\u0430\u043c \u0431\u043e \u0440\u0430\u043d\u0433\u0443 \u0431\u04ef\u0439\u0438 \u0442\u0438\u0431,\n\u0411\u043e \u0441\u0430\u0434 \u04b3\u0430\u0437\u043e\u0440 \u043d\u0443\u0437\u04b3\u0430\u0442\u0443 \u043e\u0440\u043e\u0438\u0448\u0438 \u0430\u04b7\u0438\u0431.\n\u0428\u043e\u044f\u0434, \u043a\u0438 \u043c\u0430\u0440\u0434\u0438 \u043f\u0438\u0440 \u0431\u0430\u0434-\u0438\u043d \u0433\u0430\u04b3 \u0448\u0430\u0432\u0430\u0434 \u04b7\u0430\u0432\u043e\u043d,\n\u0413\u0435\u0442\u04e3 \u0431\u0430\u0434\u0438\u043b \u0451\u0444\u0442 \u0448\u0443\u0431\u043e\u0431 \u0430\u0437 \u043f\u0430\u0439\u0438 \u043c\u0430\u0448\u0438\u0431.\n\u0427\u0430\u0440\u0445\u0438 \u0431\u0443\u0437\u0443\u0440\u0433\u0432\u043e\u0440 \u044f\u043a\u0435 \u043b\u0430\u0448\u043a\u0430\u0440\u0435 \u0431\u0438\u043a\u0430\u0440\u0434,\n\u041b\u0430\u0448\u043a\u0430\u0440-\u0448 \u0430\u0431\u0440\u0438 \u0442\u0438\u0440\u0430\u0432\u0443 \u0431\u043e\u0434\u0438 \u0441\u0430\u0431\u043e - \u043d\u0430\u049b\u0438\u0431.\n\u041d\u0430\u0444\u0444\u043e\u0442 - \u0431\u0430\u0440\u049b\u0438 \u0440\u0430\u0432\u0448\u0430\u043d\u0443 \u0442\u0443\u043d\u0434\u0430\u0440-\u0448 - \u0442\u0430\u0431\u043b\u0437\u0430\u043d,\n\u0414\u0438\u0434\u0430\u043c \u04b3\u0430\u0437\u043e\u0440 \u0445\u0430\u0439\u043b\u0443 \u043d\u0430\u0434\u0438\u0434\u0430\u043c \u0447\u0443\u043d\u0438\u043d \u043c\u0443\u04b3\u0438\u0431.\n\u041e\u043d \u0430\u0431\u0440 \u0431\u0438\u043d, \u043a\u0438 \u0433\u0438\u0440\u044f\u0434 \u0447\u0443\u043d \u043c\u0430\u0440\u0434\u0438 \u0441\u04ef\u0433\u0432\u043e\u0440\n\u0412-\u043e\u043d \u0440\u0430\u044a\u0434 \u0431\u0438\u043d, \u043a\u0438 \u043d\u043e\u043b\u0430\u0434 \u0447\u0443\u043d \u043e\u0448\u0438\u049b\u0438 \u043a\u0430\u0438\u0431.\n\u0425\u0443\u0440\u0448\u0435\u0434\u0440\u043e \u0437\u0438 \u0430\u0431\u0440 \u0434\u0438\u04b3\u0430\u0434 \u0440\u04ef\u0439 \u0433\u043e\u04b3-\u0433\u043e\u04b3\n\u0427\u0443\u043d \u043e\u043d \u04b3\u0438\u0441\u043e\u0440\u0438\u0435, \u043a\u0438 \u0433\u0443\u0437\u0430\u0440 \u0434\u043e\u0440\u0430\u0434 \u0430\u0437 \u0440\u0430\u049b\u0438\u0431...\n\u041b\u043e\u043b\u0430 \u043c\u0438\u0451\u043d\u0438 \u043a\u0438\u0448\u0442 \u0431\u0438\u0445\u0430\u043d\u0434\u0430\u0434 \u04b3\u0430\u043c\u0435 \u0437\u0438 \u0434\u0443\u0440,\n\u0427\u0443\u043d \u043f\u0430\u043d\u04b7\u0430\u0438 \u0430\u0440\u04ef\u0441 \u0431\u0430 \u04b3\u0438\u043d\u043d\u043e \u0448\u0443\u0434\u0430 \u0445\u0430\u0437\u0438\u0431.\n\u0411\u0443\u043b\u0431\u0443\u043b \u04b3\u0430\u043c\u0435 \u0431\u0438\u0445\u043e\u043d\u0430\u0434 \u0434\u0430\u0440 \u0448\u043e\u0445\u0441\u043e\u0440\u0438 \u0431\u0435\u0434,\n\u0421\u043e\u0440 \u0430\u0437 \u0434\u0430\u0440\u0430\u0445\u0442\u0438 \u0441\u0430\u0440\u0432 \u043c\u0430\u0440-\u04ef\u0440\u043e \u0448\u0443\u0434\u0430 \u043c\u0443\u04b7\u0438\u0431...")
B.aj2=new A.a("420d7138-e219-4495-bc1c-0718c17436ba","bcb9a591-92bb-405b-bcf5-f58a6aaa65cc","\u0411\u04ef\u0439\u0438 \u04b6\u04ef\u0439\u0438 \u041c\u0443\u043b\u0438\u0451\u043d \u043e\u044f\u0434 \u04b3\u0430\u043c\u0435,","\u0411\u04ef\u0439\u0438 \u04b6\u04ef\u0439\u0438 \u041c\u0443\u043b\u0438\u0451\u043d \u043e\u044f\u0434 \u04b3\u0430\u043c\u0435,\n\u0401\u0434\u0438 \u0451\u0440\u0438 \u043c\u0435\u04b3\u0440\u0431\u043e\u043d \u043e\u044f\u0434 \u04b3\u0430\u043c\u0435.\n\u0420\u0435\u0433\u0438 \u041e\u043c\u0443\u0432\u0443 \u0434\u0443\u0440\u0443\u0448\u0442\u04e3 \u0440\u043e\u04b3\u0438 \u04ef\n\u0417\u0435\u0440\u0438 \u043f\u043e\u044f\u043c \u043f\u0430\u0440\u043d\u0438\u0451\u043d \u043e\u044f\u0434 \u04b3\u0430\u043c\u0435.\n\u041e\u0431\u0438 \u04b6\u0430\u0439\u04b3\u0443\u043d \u0430\u0437 \u043d\u0438\u0448\u043e\u0442\u0438 \u0440\u04ef\u0439\u0438 \u0434\u04ef\u0441\u0442\n\u0425\u0438\u043d\u0433\u0438 \u043c\u043e\u0440\u043e \u0442\u043e \u043c\u0438\u0451\u043d \u043e\u044f\u0434 \u04b3\u0430\u043c\u0435.\n\u042d\u0439 \u0411\u0443\u0445\u043e\u0440\u043e, \u0448\u043e\u0434 \u0431\u043e\u0448\u0443 \u0434\u0435\u0440 \u0437\u04e3,\n\u041c\u0438\u0440 \u043d\u0430\u0437\u0434\u0430\u0442 \u0448\u043e\u0434\u043c\u043e\u043d \u043e\u044f\u0434 \u04b3\u0430\u043c\u0435.\n\u041c\u0438\u0440 \u043c\u043e\u04b3 \u0430\u0441\u0442\u0443 \u0411\u0443\u0445\u043e\u0440\u043e \u043e\u0441\u043c\u043e\u043d,\n\u041c\u043e\u04b3 \u0441\u04ef\u0439\u0438 \u043e\u0441\u043c\u043e\u043d \u043e\u044f\u0434 \u04b3\u0430\u043c\u0435.\n\u041c\u0438\u0440 \u0441\u0430\u0440\u0432 \u0430\u0441\u0442\u0443 \u0411\u0443\u0445\u043e\u0440\u043e \u0431\u04ef\u0441\u0442\u043e\u043d,\n\u0421\u0430\u0440\u0432 \u0441\u04ef\u0439\u0438 \u0431\u04ef\u0441\u0442\u043e\u043d \u043e\u044f\u0434 \u04b3\u0430\u043c\u0435.")
B.akK=new A.a("d6496a17-c4d8-48dc-af12-8b1135414e5a","a6b5eb18-39e9-4fdf-b492-e5956a553436","\u0411\u0430 \u0441\u0443\u0445\u0430\u043d \u043c\u043e\u043d\u0430\u0434 \u0448\u0435\u044a\u0440\u0438 \u0448\u0443\u0430\u0440\u043e,","\u0411\u0430 \u0441\u0443\u0445\u0430\u043d \u043c\u043e\u043d\u0430\u0434 \u0448\u0435\u044a\u0440\u0438 \u0448\u0443\u0430\u0440\u043e,\n\u0420\u04ef\u0434\u0430\u043a\u0438\u0440\u043e \u0441\u0443\u0445\u0430\u043d\u0430\u0448 \u0442\u0430\u043b\u0432\u0438\u043d\u043e\u0441\u0442.\n\u0428\u043e\u0438\u0440\u043e\u043d\u0440\u043e \u0445\u0430\u0432\u0443 \u0430\u04b3\u0441\u0430\u043d\u0442 \u043c\u0430\u0434\u0435\u04b3,\n\u0420\u04ef\u0434\u0430\u043a\u0438\u0440\u043e \u0445\u0430\u0432\u0443 \u0430\u04b3\u0441\u0430\u043d\u0442 \u04b3\u0438\u04b7\u043e\u0441\u0442.")
