B.alc=new A.a("c6e83f5c-8dc5-45a8-974b-6048564659b5","d48ec80f-951d-4dfd-b65a-6e409561a712","\u0492\u0430\u0437\u0430\u043b \u0420\u04ef\u0434\u0430\u043a\u0438\u0432\u043e\u0440 \u043d\u0435\u043a\u0443 \u0431\u0443\u0432\u0430\u0434,","\u0492\u0430\u0437\u0430\u043b \u0420\u04ef\u0434\u0430\u043a\u0438\u0432\u043e\u0440 \u043d\u0435\u043a\u0443 \u0431\u0443\u0432\u0430\u0434,\n\u0492\u0430\u0437\u0430\u043b\u04b3\u043e\u0438 \u043c\u0430\u043d \u0420\u04ef\u0434\u0430\u043a\u0438\u0432\u043e\u0440 \u043d\u0435\u0441\u0442.")
B.a5y=new A.a("babee999-8b75-459a-96c7-b1ca450c5c60","d5abab06-07e9-4247-b8a8-f4801b6a5be4","\u0411\u0430 \u04b3\u0430\u0440 \u043a\u043e\u0440\u0435, \u043a\u0438 \u04b3\u0438\u043c\u043c\u0430\u0442 \u0431\u0430\u0441\u0442\u0430 \u0433...","\u0411\u0430 \u04b3\u0430\u0440 \u043a\u043e\u0440\u0435, \u043a\u0438 \u04b3\u0438\u043c\u043c\u0430\u0442 \u0431\u0430\u0441\u0442\u0430 \u0433\u0430\u0440\u0434\u0430\u0434,\n\u0410\u0433\u0430\u0440 \u0445\u043e\u0440\u0435 \u0431\u0443\u0432\u0430\u0434, \u0433\u0443\u043b\u0434\u0430\u0441\u0442\u0430 \u0433\u0430\u0440\u0434\u0430\u0434.")
B.acY=new A.a("7e839ff0-1cc1-4ded-b6b5-d12bf1101bc7","3d5d70c0-6294-4b7d-b830-79db08edd6b8","\u0424\u0438\u0448\u043e\u043d\u0434 \u0430\u0437 \u0441\u0430\u0432\u0441\u0430\u043d\u0443 \u0433\u0443\u043b \u0441\u0438\u043c\u0443 \u0437\u0430\u0440...","\u0424\u0438\u0448\u043e\u043d\u0434 \u0430\u0437 \u0441\u0430\u0432\u0441\u0430\u043d\u0443 \u0433\u0443\u043b \u0441\u0438\u043c\u0443 \u0437\u0430\u0440 \u0431\u043e\u0434.\n\u0417\u0438\u04b3\u04e3 \u0431\u043e\u0434\u0435, \u043a\u0438 \u0440\u0430\u04b3\u043c\u0430\u0442 \u0431\u043e\u0434 \u0431\u0430\u0440 \u0431\u043e\u0434!\n\u0411\u0438\u0434\u043e\u0434 \u0430\u0437 \u043d\u0430\u049b\u0448\u0438 \u043e\u0437\u0430\u0440 \u0441\u0430\u0434 \u043d\u0438\u0448\u043e\u043d \u043e\u0431,\n\u041d\u0430\u043c\u0443\u0434 \u0430\u0437 \u0441\u0435\u04b3\u0440\u0438 \u043c\u043e\u043d\u04e3 \u0441\u0430\u0434 \u0430\u0441\u0430\u0440 \u0431\u043e\u0434.\n\u041c\u0438\u0441\u043e\u043b\u0438 \u0447\u0430\u0448\u043c\u0438 \u041e\u0434\u0430\u043c \u0448\u0443\u0434 \u043c\u0430\u0433\u0430\u0440 \u0430\u0431\u0440.\n\u0414\u0430\u043b\u0435\u043b\u0438 \u043b\u0443\u0442\u0444\u0438 \u0418\u0441\u043e \u0448\u0443\u0434 \u043c\u0430\u0433\u0430\u0440 \u0431\u043e\u0434,\n\u041a\u0438 \u0434\u0443\u0440 \u0431\u043e\u0440\u0438\u0434 \u04b3\u0430\u0440 \u0434\u0430\u043c \u0434\u0430\u0440 \u0447\u0430\u043c\u0430\u043d \u0430\u0431\u0440,\n\u041a\u0438 \u04b7\u043e\u043d \u0430\u0444\u0437\u0443\u0434 \u0445\u0443\u0448-\u0445\u0443\u0448 \u0434\u0430\u0440 \u0448\u0430\u04b7\u0430\u0440 \u0431\u043e\u0434.\n\u0410\u0433\u0430\u0440 \u0434\u0435\u0432\u043e\u043d\u0430 \u0430\u0431\u0440 \u043e\u043c\u0430\u0434, \u0447\u0438\u0440\u043e \u043f\u0430\u0441,\n\u041a\u0443\u043d\u0430\u0434 \u0430\u0440\u0437\u0430 \u0441\u0430\u0431\u04ef\u04b3\u04e3 \u04b7\u043e\u043c\u0438 \u0437\u0430\u0440 \u0431\u043e\u0434?\n\u0413\u0443\u043b\u0438 \u0445\u0443\u0448\u0431\u04ef\u0439, \u0442\u0430\u0440\u0441\u0430\u043c, \u043e\u0432\u0430\u0440\u0430\u0434 \u0440\u0430\u043d\u0433\n\u0410\u0437 \u0438\u043d \u0493\u0430\u043c\u043c\u043e\u0437\u0438 \u0441\u0443\u0431\u04b3\u0438 \u043f\u0430\u0440\u0434\u0430\u0434\u0430\u0440 \u0431\u043e\u0434.\n\u0411\u0430\u0440\u043e\u0438 \u0447\u0430\u0448\u043c\u0438 \u04b3\u0430\u0440 \u043d\u043e\u0430\u04b3\u043b, \u0433\u04ef\u0439\u04e3,\n\u0410\u0440\u04ef\u0441\u0438 \u0431\u043e\u0493\u0440\u043e \u0448\u0443\u0434 \u04b7\u0438\u043b\u0432\u0430\u0433\u0430\u0440 \u0431\u043e\u0434.\n\u0410\u04b7\u0430\u0431 \u0447\u0443\u043d \u0441\u0443\u0431\u04b3 \u0445\u0443\u0448\u0442\u0430\u0440 \u043c\u0435\u0431\u0430\u0440\u0430\u0434 \u0445\u043e\u0431,\n\u0427\u0430\u0440\u043e \u0430\u0444\u043a\u0430\u043d\u0434 \u0433\u0443\u043b\u0440\u043e \u0434\u0430\u0440 \u0441\u0430\u04b3\u0430\u0440 \u0431\u043e\u0434?")
B.aoj=new A.a("e3fb85c9-9df7-44d8-b5e3-449929f1b0a3","bb00bac5-e207-4cc7-9539-a2af92b71281","\u0418\u043c\u0440\u04ef\u0437 \u0431\u0438\u043a\u0443\u043d \u0447\u0443 \u043c\u0435\u0442\u0430\u0432\u043e\u043d\u04e3 \u043a\u043e\u0440\u0435,","\u0418\u043c\u0440\u04ef\u0437 \u0431\u0438\u043a\u0443\u043d \u0447\u0443 \u043c\u0435\u0442\u0430\u0432\u043e\u043d\u04e3 \u043a\u043e\u0440\u0435,\n\u0424\u0430\u0440\u0434\u043e \u0447\u04e3 \u043a\u0443\u043d\u04e3 \u0447\u0443 \u04b3\u0435\u0447 \u043d\u0430\u0442\u0432\u043e\u043d\u04e3 \u043a\u0430\u0440\u0434.")
B.aey=new A.a("16f6f929-1bbe-45c8-8780-bb4c9ed4419b","bb00bac5-e207-4cc7-9539-a2af92b71281","\u0410\u0437 \u049b\u0430\u044a\u0440\u0438 \u0433\u0438\u043b\u0438 \u0441\u0438\u0451\u04b3 \u0442\u043e \u0430\u0432\u04b7\u0438 \u0417\u0443\u04b3...","\u0410\u0437 \u049b\u0430\u044a\u0440\u0438 \u0433\u0438\u043b\u0438 \u0441\u0438\u0451\u04b3 \u0442\u043e \u0430\u0432\u04b7\u0438 \u0417\u0443\u04b3\u0430\u043b,\n\u041a\u0430\u0440\u0434\u0430\u043c \u04b3\u0430\u043c\u0430 \u043c\u0443\u0448\u043a\u0438\u043b\u043e\u0442\u0438 \u0433\u0435\u0442\u0438\u0440\u043e \u04b3\u0430\u043b.\n\u0411\u0435\u0440\u0443\u043d \u04b7\u0430\u0441\u0442\u0430\u043c \u0437\u0438 \u0431\u0430\u043d\u0434\u0438 \u04b3\u0430\u0440 \u043c\u0430\u043a\u0440\u0443 \u04b3\u0438\u044f\u043b,\n\u04b2\u0430\u0440 \u0431\u0430\u043d\u0434 \u043a\u0443\u0448\u043e\u0434\u0430 \u0448\u0443\u0434, \u043c\u0430\u0433\u0430\u0440 \u0431\u0430\u043d\u0434\u0438 \u0430\u04b7\u0430\u043b.")
B.a9W=new A.a("68dd66f4-464f-4862-ad2d-34c8614da69c","bb00bac5-e207-4cc7-9539-a2af92b71281","\u041a\u0443\u0444\u0440\u0438 \u0447\u0443 \u043c\u0430\u043d\u0435 \u0433\u0430\u0437\u043e\u0444\u0443 \u043e\u0441\u043e\u043d \u043d\u0430\u0431\u0443...","\u041a\u0443\u0444\u0440\u0438 \u0447\u0443 \u043c\u0430\u043d\u0435 \u0433\u0430\u0437\u043e\u0444\u0443 \u043e\u0441\u043e\u043d \u043d\u0430\u0431\u0443\u0432\u0430\u0434,\n\u041c\u0430\u04b3\u043a\u0430\u043c\u0442\u0430\u0440 \u0430\u0437 \u0438\u043c\u043e\u043d\u0438 \u043c\u0430\u043d \u0438\u043c\u043e\u043d \u043d\u0430\u0431\u0443\u0432\u0430\u0434.\n\u0414\u0430\u0440 \u0434\u0430\u04b3\u0440 \u0447\u0443 \u043c\u0430\u043d \u044f\u043a\u0435\u0432\u0443 \u043e\u043d \u04b3\u0430\u043c \u043a\u043e\u0444\u0438\u0440?!\n\u041f\u0430\u0441 \u0434\u0430\u0440 \u04b3\u0430\u043c\u0430 \u0434\u0430\u04b3\u0440 \u044f\u043a \u043c\u0443\u0441\u0430\u043b\u043c\u043e\u043d \u043d\u0430\u0431\u0443\u0432\u0430\u0434!")
B.anB=new A.a("3bca1383-a3b8-4c5a-8b5d-9e064e8f435f","bb00bac5-e207-4cc7-9539-a2af92b71281","\u0411\u043e \u0434\u0443\u0448\u043c\u0430\u043d\u0438 \u043c\u0430\u043d \u0447\u0443 \u0434\u04ef\u0441\u0442 \u0431\u0438\u0441\u0451\u0440 \u043d...","\u0411\u043e \u0434\u0443\u0448\u043c\u0430\u043d\u0438 \u043c\u0430\u043d \u0447\u0443 \u0434\u04ef\u0441\u0442 \u0431\u0438\u0441\u0451\u0440 \u043d\u0438\u0448\u0430\u0441\u0442,\n\u0411\u043e \u0434\u04ef\u0441\u0442 \u043d\u0430\u0431\u043e\u044f\u0434\u0430\u043c \u0434\u0438\u0433\u0430\u0440 \u0431\u043e\u0440 \u043d\u0438\u0448\u0430\u0441\u0442.\n\u041f\u0430\u0440\u04b3\u0435\u0437 \u0430\u0437 \u043e\u043d \u0448\u0430\u043a\u0430\u0440, \u043a\u0438 \u0431\u043e \u0437\u0430\u04b3\u0440 \u043e\u043c\u0435\u0445\u0442,\n\u0411\u0438\u0433\u0440\u0435\u0437 \u0430\u0437 \u043e\u043d \u043c\u0430\u0433\u0430\u0441, \u043a\u0438 \u0431\u0430\u0440 \u043c\u043e\u0440 \u043d\u0438\u0448\u0430\u0441\u0442.")
B.aox=new A.a("a2095ff6-db8b-4dbd-bd3d-eeb3d2bec53a","bb00bac5-e207-4cc7-9539-a2af92b71281","\u0411\u043e \u0438\u043d \u0434\u0443-\u0441\u0435 \u043d\u043e\u0434\u043e\u043d, \u043a\u0438 \u0447\u0443\u043d\u043e\u043d \u043c\u0435...","\u0411\u043e \u0438\u043d \u0434\u0443-\u0441\u0435 \u043d\u043e\u0434\u043e\u043d, \u043a\u0438 \u0447\u0443\u043d\u043e\u043d \u043c\u0435\u0434\u043e\u043d\u0430\u043d\u0434\n\u0410\u0437 \u04b7\u0430\u04b3\u043b, \u043a\u0438 \u0434\u043e\u043d\u043e\u0438 \u04b7\u0430\u04b3\u043e\u043d \u044d\u0448\u043e\u043d\u0430\u043d\u0434.\n\u0425\u0430\u0440 \u0431\u043e\u0448, \u043a\u0438 \u0438\u043d \u04b7\u0430\u043c\u043e\u0430\u0442 \u0430\u0437 \u0444\u0430\u0440\u0442\u0438 \u0445\u0430\u0440\u04e3\n\u04b2\u0430\u0440 \u043a-\u04ef \u043d\u0430 \u0445\u0430\u0440 \u0430\u0441\u0442, \u043a\u043e\u0444\u0438\u0440\u0430\u0448 \u043c\u0435\u0445\u043e\u043d\u0430\u043d\u0434.")
B.ai7=new A.a("de8a3072-ad79-4ce0-bf39-0b8173323aa7","a4b182d3-1c06-4c82-9858-0e71d95edeb3","\u041c\u0430\u043a\u0443\u043d, \u043a\u0438 \u043e\u04b3\u0438 \u0444\u0430\u049b\u0438\u0440\u0435 \u0448\u0430\u0431\u0435 \u0431\u0443\u0440\u0443...","\u041c\u0430\u043a\u0443\u043d, \u043a\u0438 \u043e\u04b3\u0438 \u0444\u0430\u049b\u0438\u0440\u0435 \u0448\u0430\u0431\u0435 \u0431\u0443\u0440\u0443\u043d \u043e\u044f\u0434,\n\u04b2\u0430\u0437\u043e\u0440 \u04b3\u0430\u043c\u0447\u0443 \u0442\u0443 \u0430\u0437 \u0445\u043e\u043d\u0443\u043c\u043e\u043d \u0431\u0430\u0440\u0430\u043d\u0434\u043e\u0437\u0430\u0434.\n\u0417\u0438 \u0442\u0438\u0440\u0438 \u043e\u04b3\u0438 \u044f\u0442\u0438\u043c\u043e\u043d \u043c\u0430\u0433\u0430\u0440 \u043d\u0430\u043c\u0435\u0442\u0430\u0440\u0441\u04e3?\n\u0424\u0438\u0493\u043e\u043d\u0443 \u043d\u043e\u043b\u0430 \u0431\u0430 \u0430\u0440\u0448\u0443 \u043c\u0430\u043b\u043e\u0438\u043a \u0430\u043d\u0434\u043e\u0437\u0430\u0434.\n\u04b2\u0430\u0437\u0430\u0440 \u043d\u0430\u043c\u043e\u0439 \u0430\u0437 \u043e\u043d \u043d\u043e\u043b\u0430\u0438 \u0441\u0430\u04b3\u0430\u0440\u0433\u043e\u04b3\u04e3,\n\u041a\u0438 \u0433\u0430\u0440 \u0431\u0430 \u043a\u04ef\u04b3 \u0437\u0430\u043d\u0430\u0434, \u0440\u0430\u0432\u0437\u0430\u043d\u0435 \u0434\u0430\u0440 \u043e\u043d \u0441\u043e\u0437\u0430\u0434.\n\u0411\u0430 \u0432\u0430\u049b\u0442\u0438 \u043d\u0438\u043c\u0438\u0448\u0430\u0431\u04e3 \u0433\u0430\u0440 \u0431\u0438\u0433\u04ef\u044f\u0434: \xab\u042d\u0439 \u0410\u043b\u043b\u043e\u04b3!\xbb,\n\u04b2\u0430\u0437\u043e\u0440 \u04b3\u0430\u043c\u0447\u0443 \u0442\u0443 \u0430\u0437 \u0445\u043e\u043d\u0443\u043c\u043e\u043d \u0431\u0430\u0440\u0430\u043d\u0434\u043e\u0437\u0430\u0434.\n\u04b2\u0430\u0437\u043e\u0440 \u04b7\u0430\u0432\u0448\u0430\u043d\u0438 \u0444\u04ef\u043b\u043e\u0434 \u0433\u0430\u0440 \u0431\u0438\u043f\u04ef\u0448\u04e3 \u0442\u0443,\n\u0417\u0438 \u043e\u04b3\u0438 \u0433\u0430\u0440\u043c\u0438 \u0444\u0430\u049b\u0438\u0440\u0435 \u0447\u0443 \u043c\u0443\u043c \u0431\u0438\u0433\u0434\u043e\u0437\u0430\u0434.\n\u041c\u0430\u0442\u043e\u0437 \u0431\u0430\u0440 \u0441\u0430\u0440\u0438 \u043c\u0430\u0437\u043b\u0443\u043c\u0438 \u0441\u043e\u043a\u0438\u043d, \u044d\u0439 \u0437\u043e\u043b\u0438\u043c,\n\u041a\u0438 \u0434\u0430\u0441\u0442\u0438 \u0444\u0438\u0442\u043d\u0430\u0438 \u0430\u0439\u0451\u043c \u0431\u0430\u0440 \u0441\u0430\u0440\u0430\u0442 \u0442\u043e\u0437\u0430\u0434.\n\u0410\u0433\u0430\u0440 \u0431\u0438\u04b3\u0438\u043b \u043d\u0430\u043a\u0443\u043d\u0430\u0434 \u0441\u043e\u0438\u043b\u0438 \u0441\u0438\u0442\u0430\u043c\u0434\u0438\u0434\u0430,\n\u04b6\u0430\u0437\u043e\u0434\u0438\u04b3\u0430\u043d\u0434\u0430 \u0442\u0443\u0440\u043e \u0434\u0430\u0440 \u04b7\u0430\u04b3\u0430\u043d\u043d\u0430\u043c \u0430\u043d\u0434\u043e\u0437\u0430\u0434.\n\u0417\u0438 \u0431\u0430\u04b3\u0440\u0438 \u04b7\u0430\u0432\u0440\u0438 \u043b\u0430\u0438\u043c\u043e\u043d \u043c\u0430\u043d\u043e\u043b, \u0410\u0431\u0434\u0443\u043b\u043b\u043e\u04b3,\n\u041a\u0438 \u0433\u0430\u0440 \u0445\u0430\u0441\u0435 \u0431\u0438\u0437\u0430\u043d\u0430\u0434, \u041a\u0438\u0440\u0434\u0438\u0433\u043e\u0440 \u0431\u0438\u043d\u0432\u043e\u0437\u0430\u0434.")
B.alu=new A.a("0b66cf58-ceae-43ba-98f4-27466755916d","a4b182d3-1c06-4c82-9858-0e71d95edeb3","\u0425\u0443\u0441\u0440\u0430\u0432\u043e,\u043d\u043e\u0433\u0430\u04b3 \u0445\u0430\u0437\u043e\u043d\u0435 \u0434\u0430\u0440\u0440\u0430\u0441\u0430\u0434 ...","\u0425\u0443\u0441\u0440\u0430\u0432\u043e,\u043d\u043e\u0433\u0430\u04b3 \u0445\u0430\u0437\u043e\u043d\u0435 \u0434\u0430\u0440\u0440\u0430\u0441\u0430\u0434 \u0433\u0443\u043b\u0437\u043e\u0440\u0440\u043e,\n\u04b2\u0430\u043c\u0447\u0443\u043d\u0438\u043d \u0434\u043e\u043d\u0430\u043c \u043d\u0430\u0431\u0438\u043d\u04e3 \u0440\u0430\u0432\u043d\u0430\u049b\u0438 \u0431\u043e\u0437\u043e\u0440\u0440\u043e.\n\u0413\u0430\u0440 \u04b3\u0430\u043c\u0435\u0434\u043e\u043d\u04e3 \u0447\u04e3 \u0433\u0443\u0444\u0442\u0430\u043c, \u04b7\u0430\u04b3\u0434 \u043a\u0443\u043d, \u0434\u0430\u0440 \u0438\u043b\u043c \u043a\u04ef\u0448,\n\u041a\u0438\u043d\u0430\u0440\u043e \u0430\u0437 \u0434\u0438\u043b \u0431\u0430\u0434\u0430\u0440 \u043a\u0443\u043d, \u0431\u0430\u0441 \u043a\u0443\u043d \u0438\u043d \u043e\u0437\u043e\u0440\u0440\u043e.\n\u0414\u0430\u0441\u0442\u0438 \u0437\u0443\u043b\u043c \u0430\u0437 \u043e\u0441\u0442\u0438\u043d\u0438 \u0437\u0443\u043b\u043c \u0431\u0430\u0440 \u043c\u0430\u0440\u0434\u0443\u043c \u043c\u0430\u043a\u0430\u0448!\n\u041e\u04b3\u0438 \u043c\u0430\u0437\u043b\u0443\u043c\u043e\u043d \u0441\u0430\u04b3\u0430\u0440\u0433\u0430\u04b3 \u0431\u0438\u0444\u043a\u0430\u043d\u0430\u0434 \u043a\u04ef\u04b3\u0441\u043e\u0440\u0440\u043e.\n\u0411\u0443\u0434 \u041d\u04ef\u0448\u0435\u0440\u0432\u043e\u043d\u0438 \u041e\u0434\u0438\u043b \u043a\u043e\u0444\u0438\u0440\u0443 \u043e\u0442\u0430\u0448\u043f\u0430\u0440\u0430\u0441\u0442,\n\u041b\u0435\u043a \u04ef \u0438\u049b\u0440\u043e\u0440 \u043a\u0430\u0440\u0434\u0430 \u044d\u0437\u0438\u0434\u0438 \u04b7\u0430\u0431\u0431\u043e\u0440\u0440\u043e.\n\u041d\u043e\u043c\u0438 \u04ef \u043e\u0434\u0438\u043b \u0431\u0430\u0440\u043e\u044f\u0434 \u0432-\u043e\u043d\u0438 \u0442\u0443 \u0437\u043e\u043b\u0438\u043c \u0431\u0430 \u04b3\u0430\u0448\u0440,\n\u041c\u0443\u044a\u043c\u0438\u043d\u043e, \u0431\u0430\u0440\u0433\u04ef, \u043a\u0438 \u0431\u0430\u0440 \u0445\u0443\u0434 \u0447\u0443\u043d \u043a\u0430\u0448\u04e3 \u0438\u043d \u043e\u0440\u0440\u043e?\n\u042d\u0439, \u043a\u0438 \u0442\u0443 \u043c\u0430\u0493\u0440\u0443\u0440\u0438 \u0431\u0430\u0445\u0442\u0443 \u0434\u0430\u0432\u043b\u0430\u0442\u0438 \u0444\u0430\u0440\u0445\u0443\u043d\u0434\u0430\u04e3,\n\u0425\u043e\u04b7\u0430\u0438 \u0441\u043e\u04b3\u0438\u0431\u0441\u0430\u0440\u0438\u0440\u0438 \u043c\u0430\u0444\u0440\u0430\u0448\u0438 \u043e\u0433\u0430\u043d\u0434\u0430\u04e3.\n\u0401 \u043a\u0438 \u0445\u0443\u0440\u0448\u0435\u0434\u04e3 \u0431\u0430 \u0441\u0443\u0440\u0430\u0442, \u0451 \u043a\u0438 \u04b6\u0430\u043c\u0448\u0435\u0434\u04e3 \u0431\u0430 \u04b3\u0443\u0441\u043d,\n\u0401 \u043a\u0438 \u0437\u0443\u04b3\u0440\u0430\u0447\u0435\u04b3\u0440\u0430 \u0434\u043e\u0440\u04e3, \u0451 \u0447\u0443 \u043c\u0430\u04b3 \u0442\u043e\u0431\u0430\u043d\u0434\u0430\u04e3.\n\u0413\u0430\u0440\u0447\u04e3 \u0428\u0430\u0434\u0434\u043e\u0434\u04e3, \u0432\u0430\u043b\u0435\u043a\u0438\u043d \u043d\u0435\u0441\u0442\u04e3 \u044d\u043c\u0438\u043d \u0437\u0438 \u043c\u0430\u0440\u0433.\n\u04b2\u0435\u0447 \u043a\u0430\u0441 \u0433\u0443\u0444\u0442\u0430\u0430\u0441\u0442 \u0431\u0430\u0440 \u0442\u0443: \u201c\u0422\u043e \u0430\u0431\u0430\u0434 \u043f\u043e\u044f\u043d\u0434\u0430\u04e3\u201d?,\n\u0413\u0430\u0440 \u0430\u043c\u0438\u0440\u04e3 \u04b3\u0430\u043c \u0431\u0438\u043c\u0438\u0440\u04e3, \u043f\u0438\u0440\u0438 \u0410\u043d\u0441\u043e\u0440\u04e3 \u0431\u0438\u0434\u043e\u043d!\n\u0425\u043e\u04b7\u0430\u0433\u04e3 \u0430\u0437 \u0442\u0443 \u043d\u0430\u0437\u0435\u0431\u0430\u0434, \u0441\u0430\u0440 \u0431\u0438\u043d\u0435\u04b3 \u0447\u0443\u043d \u0431\u0430\u043d\u0434\u0430\u04e3!")
