B.amd=new A.a("4d7881cd-6d76-4712-a70d-e083b9b7e900","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0442\u0430\u0432\u0430\u04b7\u04b7\u0443\u04b3\u0438 \u041a\u0430\u0440\u0438\u043c\u04b7\u043e\u043d\u0430\u043a\u0430\u0440\u043e \u0431\u0430 \u043d\u0443\u0441...","\u0442\u0430\u0432\u0430\u04b7\u04b7\u0443\u04b3\u0438 \u041a\u0430\u0440\u0438\u043c\u04b7\u043e\u043d\u0430\u043a\u0430\u0440\u043e \u0431\u0430 \u043d\u0443\u0441\u0445\u0430\u0438 \u0430\u0441\u043b\u0438\u0438 \xab\u0428\u043e\u04b3\u043d\u043e\u043c\u0430\xbb \u04b7\u0430\u043b\u0431 \u043c\u0435\xad\n\u043d\u0430\u043c\u043e\u044f\u0434. \u041a\u0430\u0440\u0438\u043c\u04b7\u043e\u043d\u0430\u043a\u0430 \u043d\u0443\u0441\u0445\u0430\u0438 \u0430\u0441\u043b\u0438\u0438 \u0438\u043d \u0430\u0441\u0430\u0440\u0440\u043e \u0431\u0430 \u0432\u043e\u0441\u0438\u0442\u0430\u0438 \u043f\u0438\u0441\u0430\xad\n\u0440\u0430\u0448 \u0434\u0430\u0441\u0442\u0440\u0430\u0441 \u043c\u0435\u043a\u0443\u043d\u0430\u0434. \u041e\u04b3\u0438\u0441\u0442\u0430-\u043e\u04b3\u0438\u0441\u0442\u0430 \u0430\u0437 \u0445\u043e\u043d\u0438\u0448\u0438 \u043e\u043d \u0431\u0430 \u0432\u0430\u04b7\u0434 \u043c\u0435\u043e\xad\n\u044f\u0434. \xab\u041a\u0430\u0440\u0438\u043c\u04b7\u043e\u043d\u0430\u043a\u0430 \u0434\u0430\u0441\u0442\u0438 \u043e\u0437\u043e\u0434\u0430\u0448\u0440\u043e \u0434\u0430\u0440 \u04b3\u0430\u0432\u043e \u0430\u043b\u0432\u043e\u043d\u04b7 \u0434\u043e\u0434\u0430, \u0447\u0443\u043d\u043e\u043d\n\u0441\u0430\u0440\u0433\u0430\u0440\u043c\u0438 \u0448\u0435\u044a\u0440\u0445\u043e\u043d\u04e3 \u0431\u0443\u0434, \u043a\u0438 \u0431\u0430 \u043f\u0430\u04b3\u043b\u0443\u044f\u0448 \u043e\u043c\u0430\u0434\u0430\u043d\u0438 \u0434\u0443\u0445\u0442\u0443\u0440\u0440\u043e, \u04b3\u0430\u0442\u0442\u043e\n\u0430\u049b\u0430\u043b\u043b\u0430\u043d \u044f\u043a\u0442\u0430\u04b3\u0438 \u0441\u0430\u0444\u0435\u0434\u0438 \u04ef\u0440\u043e \u043f\u0430\u0439 \u043d\u0430\u0431\u0443\u0440\u0434:")
B.akc=new A.a("582cc7f9-4ae8-4967-b944-a672f0f561fc","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0414\u0443 \u043b\u0430\u0448\u043a\u0430\u0440 \u0431\u0430 \u0441\u043e\u043d\u0438 \u0434\u0443 \u0434\u0430\u0440\u0451\u0438 \u0427\u0438\u043d...","\u0414\u0443 \u043b\u0430\u0448\u043a\u0430\u0440 \u0431\u0430 \u0441\u043e\u043d\u0438 \u0434\u0443 \u0434\u0430\u0440\u0451\u0438 \u0427\u0438\u043d,\n\u0422\u0443 \u0433\u04ef\u0439\u04e3, \u043a\u0438 \u0448\u0443\u0434 \u04b7\u0443\u043d\u0431-\u04b7\u0443\u043d\u0431\u043e\u043d \u0437\u0430\u043c\u0438\u043d.\n\u0411\u0438\u0451\u043c\u0430\u0434 \u0434\u0430\u043c\u043e\u043d \u049a\u043e\u0440\u0430\u043d\u0438 \u0420\u0430\u0437\u043c\u0437\u0430\u043d\n\u0412-\u0430\u0437 \u043e\u043d \u0441\u04ef\u0439 \u0413\u0430\u0440\u0441\u0435\u0432\u0430\u0437\u0438 \u043f\u0438\u043b\u0442\u0430\u043d.")
B.adp=new A.a("cbfecf2d-e0a7-4418-9065-8d92a04b2ac4","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0417\u0438 \u043e\u0432\u043e\u0437\u0438 \u0430\u0441\u043f\u043e\u043d\u0443 \u0433\u0430\u0440\u0434\u0438 \u0441\u0438\u043f\u043e\u04b3","\u0417\u0438 \u043e\u0432\u043e\u0437\u0438 \u0430\u0441\u043f\u043e\u043d\u0443 \u0433\u0430\u0440\u0434\u0438 \u0441\u0438\u043f\u043e\u04b3\n\u041d\u0430 \u0445\u0443\u0440\u0448\u0435\u0434 \u043f\u0430\u0439\u0434\u043e, \u043d\u0430 \u0442\u043e\u0431\u0430\u043d\u0434\u0430 \u043c\u043e\u04b3.\n\u0414\u0443\u0440\u0430\u0445\u0448\u0438\u0434\u0430\u043d\u0438 \u0442\u0435\u0493\u0438 \u0430\u043b\u043c\u043e\u0441\u0433\u0443\u043d,\n\u0421\u0438\u043d\u043e\u043d\u04b3\u043e\u0438 \u043e\u04b3\u043e\u0440\u0434\u0438\u0434\u0430 \u0431\u0430 \u0445\u0443\u043d...")
B.a90=new A.a("70583e1a-04bf-4678-8e2f-ca229962a01a","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0414\u0430\u0440 \u04b3\u0430\u049b\u0438\u049b\u0430\u0442, \u044f\u0433\u043e\u043d \u043d\u0443\u0441\u0445\u0430\u0438 \u0444\u0430\u0440\u044a","\u0414\u0430\u0440 \u04b3\u0430\u049b\u0438\u049b\u0430\u0442, \u044f\u0433\u043e\u043d \u043d\u0443\u0441\u0445\u0430\u0438 \u0444\u0430\u0440\u044a\n1\n, \u044f\u0433\u043e\u043d \u0442\u0430\u0440\u04b7\u0443\u043c\u0430 \u04b7\u043e\u0439\u0438 \u0430\u0441\u043b\u0440\u043e \u0433\u0438\xad\n\u0440\u0438\u0444\u0442\u0430 \u043d\u0430\u043c\u0435\u0442\u0430\u0432\u043e\u043d\u0430\u0434 \u0432\u0430 \u0445\u043e\u043d\u0430\u043d\u0434\u0430\u0433\u043e\u043d\u0440\u043e \u0437\u0430\u0440\u0443\u0440 \u0430\u0441\u0442, \u043a\u0438 \u0431\u0430\u0440\u043e\u0438 \u0441\u0430\u0439\u049b\u0430\u043b\n\u0434\u043e\u0434\u0430\u043d\u0438 \u0442\u0430\u0431\u044a\u0443 \u0437\u0430\u0432\u049b \u0431\u0430 \u0430\u0441\u043b\u0438 \xab\u0428\u043e\u04b3\u043d\u043e\u043c\u0430\xbb \u0442\u0430\u0432\u0430\u04b7\u04b7\u0443\u04b3 \u0434\u043e\u0448\u0442\u0430 \u0431\u043e\u0448\u0430\u043d\u0434.")
B.a7Z=new A.a("3ec038f0-e4e5-494c-bccc-ab2726fb7e25","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0425\u0430\u0442\u0442\u0438","\u0425\u0430\u0442\u0442\u0438\n\u0434\u0443\u0432\u0443\u043c\u0438\n\u0441\u0443\u0436\u0435\u0442\n\u0431\u0430\n\u0441\u0430\u0440\u043d\u0430\u0432\u0438\u0448\u0442\u0438\n\u0418\u0431\u0440\u043e\u04b3\u0438\u043c\u04b7\u043e\u043d \u0432\u0430 \u0425\u0438\u0440\u043e\u043c\u043e\u043d \u0438\u0440\u0442\u0438\u0431\u043e\u0442 \u0434\u043e\u0440\u0430\u0434.\n\u0418\u0431\u0440\u043e\u04b3\u0438\u043c \u041e\u043b\u0438\u043c\u04e3, \u043a\u0438 \u043a\u0430\u0441\u0431\u0438 \u0444\u0438\u043b\u043c\u0431\u0430\u0440\u0434\u043e\u0440\u04e3 \u0434\u043e\xad\n\u0440\u0430\u0434, \u0430\u0437 \u0430\u0432\u0432\u0430\u043b \u0442\u043e \u043e\u0445\u0438\u0440 \u0432\u043e\u049b\u0435\u0430\u04b3\u043e\u0438 \u0440\u043e\u043c\u0430\u043d\u0440\u043e \u0431\u0430\n\u043c\u0443\u0448\u043e\u04b3\u0438\u0434\u0430 \u043c\u0435\u0433\u0438\u0440\u0430\u0434. \u0418\u043d \u04b7\u043e \u0448\u043e\u0445\u0430\u0435 \u0430\u0437 \u0444\u0430\u044a\u043e\u043b\u0438\u044f\u0442\u0438 \u043a\u0430\u0441\u0431\u0438\u0438 \u0430\u0434\u0438\u0431, \u043a\u0438\n\u0441\u043e\u043b\u0438\u0451\u043d\u0438 \u0437\u0438\u0451\u0434 \u0431\u043e \u0438\u0434\u043e\u0440\u0430\u0438 \u0444\u0438\u043b\u043c\u0441\u043e\u0437\u0438\u0438 \u0442\u043e\u04b7\u0438\u043a \u04b3\u0430\u043c\u043a\u043e\u0440\u04e3 \u0434\u043e\u0448\u0442, \u0434\u0438\u0434\u0430 \u043c\u0435\xad\n\u0448\u0430\u0432\u0430\u0434.")
B.ag_=new A.a("b3bf04c1-d997-4654-816a-8a5b8526ac98","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0418\u0431\u0440\u043e\u04b3\u0438\u043c\u04b7\u043e\u043d \u0432\u0430 \u0425\u0438\u0440\u043e\u043c\u043e\u043d \u0442\u043e \u04b7\u043e\u0435 \u0430...","\u0418\u0431\u0440\u043e\u04b3\u0438\u043c\u04b7\u043e\u043d \u0432\u0430 \u0425\u0438\u0440\u043e\u043c\u043e\u043d \u0442\u043e \u04b7\u043e\u0435 \u0430\u0437 \u0442\u0430\u04b7\u0440\u0438\u0431\u0430\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u04e3 \u0431\u0430\u0440\xad\n\u0445\u0443\u0440\u0434\u043e\u0440\u0430\u043d\u0434, \u0432\u0430\u043b\u0435 \u04b3\u0430\u0440 \u0434\u0443 \u0431\u0430 \u0448\u0438\u043a\u0430\u0441\u0442\u0443 \u0440\u0435\u0445\u0442\u0438 \u0440\u04ef\u0437\u0433\u043e\u0440 \u0433\u0438\u0440\u0438\u0444\u0442\u043e\u0440 \u0448\u0443\u0434\u0430\xad\n\u0430\u043d\u0434. \u0425\u0438\u0440\u043e\u043c\u043e\u043d \u043d\u0430\u043c\u043e\u044f\u043d\u0434\u0430\u0438 \u0437\u0430\u043d\u043e\u043d\u0438 \u0441\u043e\u043b\u04b3\u043e\u0438 70-\u0443\u043c\u0438 \u0442\u043e\u04b7\u0438\u043a \u0430\u0441\u0442, \u043a\u0438 \u0434\u0430\u0440\n\u0441\u043e\u0445\u0442\xad\u043c\u043e\u043d\u0435 \u0432\u0430\u0437\u0438\u0444\u0430\u0438 \u0440\u043e\u043d\u0430\u043d\u0434\u0430\u0433\u0438\u0438 \u043a\u0440\u0430\u043d\u0440\u043e \u0430\u0434\u043e \u043c\u0435\u043a\u0443\u043d\u0430\u0434. \u0428\u0430\u0432\u04b3\u0430\u0440\u0430\u0448\u0440\u043e\n\u043d\u043e\u04b7\u0430\u0432\u043e\u043d\u043c\u0430\u0440\u0434\u043e\u043d \u043a\u0443\u0448\u0442\u0430\u0430\u043d\u0434, \u0430\u0437 \u0438\u043d \u0440\u04ef, \u0431\u0430 \u043c\u0430\u0440\u0434\u043e\u043d \u043d\u0430\u0444\u0440\u0430\u0442 \u0434\u043e\u0440\u0430\u0434.")
B.a7a=new A.a("7d70232e-dc5a-4b10-9304-fde15df44a6d","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0418\u0431\u0440\u043e\u04b3\u0438\u043c\u04b7\u043e\u043d \u0432\u043e\u0431\u0430\u0441\u0442\u0430 \u0431\u0430 \u043a\u0430\u0441\u0431\u0438 \u0444\u0438...","\u0418\u0431\u0440\u043e\u04b3\u0438\u043c\u04b7\u043e\u043d \u0432\u043e\u0431\u0430\u0441\u0442\u0430 \u0431\u0430 \u043a\u0430\u0441\u0431\u0438 \u0444\u0438\u043b\u043c\u0441\u043e\u0437\u0438\u0430\u0448 \u0431\u0430 \u0425\u0438\u0440\u043e\u043c\u043e\u043d \u0448\u0438\xad\n\u043d\u043e\u0441 \u043c\u0435\u0448\u0430\u0432\u0430\u0434 \u0432\u0430 \u0438\u043d \u0448\u0438\u043d\u043e\u0441\u043e\u04e3 \u0440\u0430\u0444\u0442\u0430-\u0440\u0430\u0444\u0442\u0430 \u0442\u0430\u049b\u0434\u0438\u0440\u0438 \u043e\u043d\u04b3\u043e\u0440\u043e \u0431\u0430 \u04b3\u0430\u043c\n\u043c\u0435\u043f\u0430\u0439\u0432\u0430\u043d\u0434\u0430\u0434. \u0425\u0438\u0440\u043e\u043c\u043e\u043d \u0434\u0430\u0440 \u0430\u0432\u0432\u0430\u043b \u0418\u0431\u0440\u043e\u04b3\u0438\u043c\u04b7\u043e\u043d\u0440\u043e \u0430\u0437 \u049b\u0430\u0431\u0438\u043b\u0438 \u043c\u0430\u0440\xad\n\u0434\u043e\u043d\u0438 \u043d\u043e\u0448\u0443\u0434 \u043c\u0435\u0434\u043e\u043d\u0438\u0441\u0442, \u0431\u0430\u044a\u0434\u04b3\u043e \u0430\u049b\u0438\u0434\u0430\u0430\u0448\u0440\u043e \u0442\u0430\u0493\u0439\u0438\u0440 \u0434\u043e\u0434\u0430, \u0431\u0430 \u04ef \u0443\u043d\u0441\n\u043c\u0435\u0433\u0438\u0440\u0430\u0434. \u0412\u043e\u049b\u0435\u0430 \u0447\u0443\u043d\u0438\u043d \u04b7\u0430\u0440\u0430\u0451\u043d \u043c\u0435\u0433\u0438\u0440\u0430\u0434, \u043a\u0438 \u0425\u0438\u0440\u043e\u043c\u043e\u043d\u0438 \u0434\u0430\u0440 \u0431\u0430\u043b\u0430\u043d\xad\n\u0434\u0438\u0438 \u043a\u0440\u0430\u043d \u049b\u0430\u0440\u043e\u0440\u0434\u043e\u0448\u0442\u0430 \u0431\u043e \u0433\u0443\u043d\u043e\u04b3\u0438 \u044f\u043a \u043c\u0430\u0440\u0434\u0438 \u043d\u043e\u0431\u0430\u043a\u043e\u0440 \u0430\u0437 \u043a\u0440\u0430\u043d \u0447\u0430\u043f\u043f\u0430\n\u043c\u0435\u0448\u0430\u0432\u0430\u0434. \u04ee \u043d\u0438\u043c\u0438\u0448\u0430\u0431\u04e3 \u0431\u0430 \u04b3\u0443\u0448 \u043e\u043c\u0430\u0434\u0430, \u0445\u0443\u0434\u0440\u043e \u0434\u0430\u0440 \u0431\u0435\u043c\u043e\u0440\u0445\u043e\u043d\u0430 \u043c\u0435\xad\n\u0431\u0438\u043d\u0430\u0434. \u0418\u0431\u0440\u043e\u04b3\u0438\u043c\u04b7\u043e\u043d \u0438\u043d \u0445\u0430\u0431\u0430\u0440\u0438 \u043c\u0443\u0434\u04b3\u0438\u0448\u0440\u043e \u0448\u0443\u043d\u0438\u0434\u0430, \u0431\u0430 \u0431\u0435\u043c\u043e\u0440\u0445\u043e\u043d\u0430\n\u043c\u0435\u0448\u0438\u0442\u043e\u0431\u0430\u0434. \u0412\u0430\u049b\u0442\u0438 \u0441\u0443\u04b3\u0431\u0430\u0442 \u0431\u043e \u0425\u0438\u0440\u043e\u043c\u043e\u043d \u0430\u0437 \u04b7\u0430\u0439\u0431\u0438 \u0418\u0431\u0440\u043e\u04b3\u0438\u043c\u04b7\u043e\u043d \u0434\u0430\u044a\xad\n\u0432\u0430\u0442\u043d\u043e\u043c\u0430\u0438 \u0442\u04ef\u0439\u0438 \u0430\u0440\u04ef\u0441\u0438\u0438 \u043e\u043d\u04b3\u043e \u043d\u0430\u043c\u043e\u0451\u043d \u0431\u0443\u0434. \u0418\u043d \u0442\u0430\u0441\u0432\u0438\u0440 \u0430\u0437 \u043e\u043d \u0448\u0430\u04b3\u043e\u0434\u0430\u0442\n\u043c\u0435\u0434\u0438\u04b3\u0430\u0434, \u043a\u0438 \u0418\u0431\u0440\u043e\u04b3\u0438\u043c\u04b7\u043e\u043d\u0443 \u0425\u0438\u0440\u043e\u043c\u043e\u043d \u0442\u0430\u049b\u0434\u0438\u0440\u0430\u0448\u043e\u043d\u0440\u043e \u0431\u0430 \u04b3\u0430\u043c \u043f\u0430\u0439\xad\n\u0432\u0430\u043d\u0434 \u043c\u0435\u0441\u043e\u0437\u0430\u043d\u0434.")
B.apS=new A.a("37bb1daa-0010-4c8f-b42e-e60b65e8f708","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u04b6\u043e\u043b\u0438\u0431 \u0430\u0441\u0442, \u043a\u0438 \u043e\u0493\u043e\u0437\u0443 \u0430\u043d\u04b7\u043e\u043c\u0438 \u0441\u0443\u0436...","\u04b6\u043e\u043b\u0438\u0431 \u0430\u0441\u0442, \u043a\u0438 \u043e\u0493\u043e\u0437\u0443 \u0430\u043d\u04b7\u043e\u043c\u0438 \u0441\u0443\u0436\u0435\u0442\u0438 \u0440\u043e\u043c\u0430\u043d \u0431\u0430 \u043f\u0430\u043b\u0430\u0442\u0430\u0438 \u043a\u0443\u043d\u04b7\u0430\u043a\u04e3\n\u043f\u0430\u0439\u0432\u0430\u0441\u0442\u0430\u0433\u04e3 \u0434\u043e\u0440\u0430\u0434. \u0418\u043d \u04b3\u0430\u043c\u043e\u043d \u043f\u0430\u043b\u0430\u0442\u0430 \u2013 \u04b3\u0443\u04b7\u0440\u0430\u0435\u0441\u0442, \u043a\u0438 \u0434\u0430\u0440 \u0433\u04ef\u0448\u0430\u0438\n\u0431\u043e\u0493\u0438 \u0438\u0441\u0442\u0438\u0440\u043e\u04b3\u0430\u0442\u0438\u0438 \u0448\u0430\u04b3\u0440\u0438 \u0414\u0443\u0448\u0430\u043d\u0431\u0435 \u04b7\u043e\u0439\u0433\u0438\u0440 \u0448\u0443\u0434\u0430 \u0431\u0443\u0434 \u0432\u0430 \u044f\u043a \u0432\u0430\u049b\u0442\u04b3\u043e\n\u0445\u0443\u0434\u0438 \u043d\u0430\u0432\u0438\u0441\u0430\u043d\u0434\u0430 \u0431\u0430\u0440 \u0430\u0441\u0430\u0440\u0438 \u0431\u0435\u043c\u043e\u0440\u0438\u0438 \u049b\u0430\u043b\u0431 \u0434\u0430\u0440 \u04b3\u0430\u043c\u0438\u043d \u0445\u0443\u04b7\u0440\u0430 \u0442\u0430\u0431\u043e\u0431\u0430\u0442\n\u043c\u0435\u0433\u0438\u0440\u0438\u0444\u0442. \u041c\u0435\u0442\u0430\u0432\u043e\u043d \u0433\u0443\u0444\u0442, \u043a\u0438 \u0430\u0441\u0430\u0440\u0438 \u043c\u0430\u0437\u043a\u0443\u0440 \u0442\u043e \u04b7\u043e\u0435 \u0431\u0430 \u0441\u0430\u04b3\u0438\u0444\u0430\u04b3\u043e\u0438\n\u0440\u04ef\u0437\u0433\u043e\u0440\u0438 \u043d\u0430\u0432\u0438\u0441\u0430\u043d\u0434\u0430\u0438 \u043e\u043d \u0434\u0430\u043b\u043e\u043b\u0430\u0442 \u043c\u0435\u043a\u0443\u043d\u0430\u0434.")
B.afD=new A.a("9dd0acbd-cf2c-44e8-90b0-cd70c610507d","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0424. \u041c\u0443\u04b3\u0430\u043c\u043c\u0430\u0434\u0438\u0435\u0432 \u0434\u0430\u0440 \xab\u041f\u0430\u043b\u0430\u0442\u0430\u0438 \u043a\u0443...","\u0424. \u041c\u0443\u04b3\u0430\u043c\u043c\u0430\u0434\u0438\u0435\u0432 \u0434\u0430\u0440 \xab\u041f\u0430\u043b\u0430\u0442\u0430\u0438 \u043a\u0443\u043d\u04b7\u0430\u043a\u04e3\xbb \u043c\u0430\u0441\u044a\u0430\u043b\u0430\u04b3\u043e\u0438 \u0438\u043d\u0441\u043e\xad\n\u043d\u0443 \u0438\u043d\u0441\u043e\u043d\u0433\u0430\u0440\u043e\u0438\u0440\u043e \u0442\u0430\u0440\u0493\u0438\u0431\u0443 \u0442\u0430\u0448\u0432\u0438\u049b \u043a\u0430\u0440\u0434\u0430\u0430\u0441\u0442. \u049a\u0438\u0441\u0441\u0430\u04b3\u043e\u0438 \xab\u041e\u0434\u0430\u043c\u043e\u043d\u0438\n\u043a\u0443\u04b3\u043d\u0430\xbb \u0432\u0430 \xab\u0414\u0430\u0440 \u043e\u043d \u0434\u0443\u043d\u0451\xbb \u04b3\u0430\u043c \u0441\u0430\u0440\u0438 \u04b3\u0430\u043c\u0438\u043d \u043c\u0430\u0432\u0437\u04ef\u044a \u0431\u0430\u04b3\u0441 \u043a\u0430\u0440\u0434\u0430\u0430\u043d\u0434.")
B.aem=new A.a("d6d3c8fc-973a-4d40-813e-c1c5ca449776","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0420\u0435\u0430\u043b\u0438\u0437\u043c (\u043a\u0430\u043b\u0438\u043c\u0430\u0438 \u043b\u043e\u0442\u0438\u043d\u04e3, \u043c\u0430\u044a\u043d\u043e...","\u0420\u0435\u0430\u043b\u0438\u0437\u043c (\u043a\u0430\u043b\u0438\u043c\u0430\u0438 \u043b\u043e\u0442\u0438\u043d\u04e3, \u043c\u0430\u044a\u043d\u043e\u044f\u0448 \u04b3\u0430\u049b\u0438\u049b\u04e3,\n\u0432\u043e\u049b\u0435\u04e3) \u043c\u0435\u0442\u043e\u0434\u0438 \u044d\u04b7\u043e\u0434\u04e3 \u0431\u0443\u0434\u0430, \u0434\u0430\u0440 \u0430\u0434\u0430\u0431\u0438\u0451\u0442\u0438 \u0431\u0430\u0434\u0435\u04e3\n\u0431\u0430 \u0442\u0430\u0432\u0440\u0438 \u04b3\u0430\u049b\u049b\u043e\u043d\u04e3 \u0438\u043d\u044a\u0438\u043a\u043e\u0441 \u043d\u0430\u043c\u0443\u0434\u0430\u043d\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u04e3\n\u0432\u0430\n\u04b3\u0430\u0451\u0442\u0438\n\u043e\u0434\u0430\u043c\u043e\u043d\u0440\u043e\n\u0434\u0430\u0440\n\u043d\u0430\u0437\u0430\u0440\n\u0434\u043e\u0440\u0430\u0434.\n\u041c\u0443\u04b3\u0438\u043c\u0442\u0430\u0440\u0438\u043d \u0445\u0443\u0441\u0443\u0441\u0438\u044f\u0442\u0438 \u043c\u0435\u0442\u043e\u0434\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c \u0438\u043d\u044a\u0438\u043a\u043e\u0441\u0438 \u04b3\u0430\u049b\u0438\u049b\u0438\u0438\n\u0432\u043e\u049b\u0435\u044a\u0438\u044f\u0442 \u043c\u0435\u0431\u043e\u0448\u0430\u0434. \u041c\u0435\u0442\u043e\u0434\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c\u0440\u043e \u0431\u0438\u0441\u0451\u0440 \u043e\u043b\u0438\u043c\u043e\u043d \u0448\u0430\u0440\u04b3 \u0434\u043e\u0434\u0430\xad\n\u0430\u043d\u0434, \u043a\u0438 \u0434\u0430\u0440 \u0431\u0430\u0439\u043d\u0438 \u043e\u043d\u04b3\u043e \u0442\u0430\u0432\u0441\u0438\u0444\u0438 \u0444\u0430\u0439\u043b\u0430\u0441\u0443\u0444\u0438 \u043d\u0435\u043c\u0438\u0441 \u0424. \u042d\u043d\u0433\u0435\u043b\u0441\n(1820\u20141895) \u043c\u0443\u043a\u0430\u043c\u043c\u0430\u043b \u0432\u0430 \u0444\u0430\u0440\u043e\u0433\u0438\u0440 \u0430\u0441\u0442: \xab\u0420\u0435\u0430\u043b\u0438\u0437\u043c \u0434\u0430\u0440 \u0431\u0430\u0440\u043e\u0431\u0430\u0440\u0438\n\u04b3\u0430\u049b\u049b\u043e\u043d\u0438\u044f\u0442\u0438 \u04b7\u0443\u0437\u044a\u0438\u0451\u0442 \u0442\u0430\u0441\u0432\u0438\u0440\u0438 \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440\u04b3\u043e\u0438 \u0442\u0438\u043f\u0438\u0440\u043e \u0434\u0430\u0440 \u0448\u0430\u0440\u043e\u0438\u0442\u04b3\u043e\u0438\n\u0442\u0438\u043f\u04e3 \u0434\u0430\u0440 \u043d\u0430\u0437\u0430\u0440 \u0434\u043e\u0440\u0430\u0434\xbb.")
B.aml=new A.a("b635b7f6-b89c-484c-9bce-0e272dd659d0","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u041c\u0443\u0432\u043e\u0444\u0438\u049b\u0438 \u0438\u043d \u0442\u0430\u0432\u0441\u0438\u0444 \u0431\u0430\u0440\u043e\u0438 \u043c\u0435\u0442\u043e\u0434...","\u041c\u0443\u0432\u043e\u0444\u0438\u049b\u0438 \u0438\u043d \u0442\u0430\u0432\u0441\u0438\u0444 \u0431\u0430\u0440\u043e\u0438 \u043c\u0435\u0442\u043e\u0434\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c \u0447\u0430\u043d\u0434 \u043d\u0443\u043a\u0442\u0430 \u043c\u0443\u04b3\u0438\u043c\n\u043c\u0435\u0431\u043e\u0448\u0430\u0434:")
B.ae7=new A.a("f919858d-2093-484f-a113-e92794df435f","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0422\u0430\u043b\u0430\u0431\u043e\u0442\u0438 \u0434\u0438\u0433\u0430\u0440\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c \u0431\u0430 \u0448\u0430\u0440...","\u0422\u0430\u043b\u0430\u0431\u043e\u0442\u0438 \u0434\u0438\u0433\u0430\u0440\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c \u0431\u0430 \u0448\u0430\u0440\u043e\u0438\u0442\u04b3\u043e\u0438 \u0442\u0438\u043f\u04e3 \u043c\u0443\u0432\u043e\u0444\u0438\u049b\u0430\u0442 \u043a\u0430\u0440\xad\n\u0434\u0430\u043d\u0438 \u0432\u0430\u0437\u044a\u0438\u044f\u0442\u04b3\u043e\u0438 \u0442\u0438\u043f\u04e3 \u043c\u0435\u0431\u043e\u0448\u0430\u0434. \u041e\u0431\u0440\u0430\u0437\u0438 \u0440\u0435\u0430\u043b\u0438\u0441\u0442\u04e3 \u0432\u043e\u0431\u0430\u0441\u0442\u0430 \u0431\u0430 \u0437\u0430\xad\n\u043c\u043e\u043d\u0443 \u043c\u0430\u043a\u043e\u043d \u0432\u0430 \u0432\u0430\u0437\u044a\u0438\u044f\u0442\u0435, \u043a\u0438 \u0434\u0430\u0440 \u043e\u043d \u0430\u043c\u0430\u043b \u043c\u0435\u043a\u0443\u043d\u0430\u0434, \u043e\u0444\u0430\u0440\u0438\u0434\u0430 \u043c\u0435\u0448\u0430\xad\n\u0432\u0430\u0434. \u049a\u0430\u04b3\u0440\u0430\u043c\u043e\u043d\u0438 \u049b\u0438\u0441\u0441\u0430\u0438 \xab\u041e\u0434\u0438\u043d\u0430\xbb-\u0438 \u0421.\u0410\u0439\u043d\u04e3 \u043d\u0430\u043c\u043e\u044f\u043d\u0434\u0430\u0438 \u04b7\u0430\u0432\u043e\u043d\u043e\u043d\u0438\n\u043a\u0430\u043c\u0431\u0438\u0437\u043e\u0430\u0442\u0438 \u043a\u04ef\u04b3\u0438\u0441\u0442\u043e\u043d\u0438 \u049a\u0430\u0440\u043e\u0442\u0435\u0433\u0438\u043d\u0438 \u0438\u0431\u0442\u0438\u0434\u043e\u0438 \u0430\u0441\u0440\u0438 \u0425\u0425 \u043c\u0435\u0431\u043e\u0448\u0430\u0434, \u043a\u0438\n\u043c\u0430\u0440\u0434\u0443\u043c\u0438 \u043e\u043d \u04b7\u043e \u0430\u0437 \u04b3\u0430\u0440\u0430\u043a\u0430\u0442\u04b3\u043e\u0438 \u0445\u0443\u0434\u0448\u0438\u043d\u043e\u0441\u0438\u0438 \u0434\u0430\u0432\u0440 \u0431\u0435\u0445\u0430\u0431\u0430\u0440 \u0431\u0443\u0434\u0430\u043d\u0434.\n\u041d\u0430\u0432\u0438\u0441\u0430\u043d\u0434\u0430 \u043c\u0443\u04b3\u0438\u0442\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u04e3, \u0432\u0430\u0437\u044a\u0438 \u0442\u0430\u044a\u0440\u0438\u0445\u0438\u0438 \u04b7\u043e\u043c\u0435\u0430 \u0432\u0430 \u0441\u0438\u043d\u043d\u0443 \u0441\u043e\u043b\u0438\n\u049b\u0430\u04b3\u0440\u0430\u043c\u043e\u043d\u0440\u043e \u0431\u0430 \u044d\u044a\u0442\u0438\u0431\u043e\u0440 \u0433\u0438\u0440\u0438\u0444\u0442\u0430, \u04ef\u0440\u043e \u0431\u0435\u04b7\u0443\u0440\u044a\u0430\u0442 \u0432\u0430 \u043a\u0430\u043c\u04b3\u0430\u0440\u0430\u043a\u0430\u0442 \u0431\u0430\n\u049b\u0430\u043b\u0430\u043c \u0434\u043e\u0434\u0430\u0430\u0441\u0442. \u042f\u044a\u043d\u0435, \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440\u0438 \u041e\u0434\u0438\u043d\u0430 \u0431\u0430 \u043c\u0430\u043a\u043e\u043d\u0443 \u0437\u0430\u043c\u043e\u043d \u0432\u0430 \u043c\u0443\u04b3\u0438\u0442\u0438\n\u0437\u0438\u043d\u0434\u0430\u0433\u0438\u0438 \u04ef \u043c\u0443\u0432\u043e\u0444\u0438\u049b\u0430\u0442 \u0434\u043e\u0440\u0430\u0434.")
B.a7Q=new A.a("18e424ef-c4bc-4d9d-8513-a94955fedd24","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0428\u0430\u0440\u0442\u0438 \u0434\u0438\u0433\u0430\u0440\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c \u0438\u0441\u0442\u0438\u0444\u043e\u0434\u0430\u0438...","\u0428\u0430\u0440\u0442\u0438 \u0434\u0438\u0433\u0430\u0440\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c \u0438\u0441\u0442\u0438\u0444\u043e\u0434\u0430\u0438 \u043c\u043e\u04b3\u0438\xad\n\u0440\u043e\u043d\u0430\u0438 \u04b7\u0443\u0437\u044a\u0438\u0451\u0442\u0438 \u0431\u0430\u0434\u0435\u04e3 \u043c\u0435\u0431\u043e\u0448\u0430\u0434. \u0414\u0430\u0440 \u0442\u0430\u0441\u0432\u0438\u0440\u0438\n\u0440\u0435\u0430\u043b\u0438\u0441\u0442\u04e3 \u04b7\u0443\u0437\u044a\u04b3\u043e\u0438 \u0431\u0430\u0434\u0435\u04e3 \u043c\u0430\u0432\u049b\u0435\u0438 \u04b3\u0430\u043b\u043a\u0443\u043d\u0430\u043d\u0434\u0430\n\u0434\u043e\u0440\u0430\u043d\u0434. \u0410\u0437 \u04b7\u0443\u043c\u043b\u0430, \u043e\u0444\u0430\u0440\u0438\u0434\u0430\u043d\u0438 \u0441\u0438\u043c\u043e\u0438 \u049b\u0430\u04b3\u0440\u0430\u043c\u043e\u043d,\n\u0444\u0430\u0440\u0434\u0438\u043a\u0443\u043d\u043e\u043d\u0438\u0438 \u0437\u0430\u0431\u043e\u043d \u0432\u0430 \u0442\u0430\u0441\u0432\u0438\u0440\u0438 \u043c\u0430\u043d\u0437\u0430\u0440\u0430\u04b3\u043e\u0438 \u0442\u0430\u0431\u0438\u0430\u0442 \u0431\u0435 \u04b7\u0443\u0437\u044a\u0438\u0451\u0442\u0438\n\u0431\u0430\u0434\u0435\u04e3 \u0438\u043c\u043a\u043e\u043d \u043d\u0430\u0434\u043e\u0440\u0430\u0434. \u0421. \u0410\u0439\u043d\u04e3 \u0434\u0430\u0440 \u0440\u043e\u043c\u0430\u043d\u0438 \xab\u0492\u0443\u043b\u043e\u043c\u043e\u043d\xbb \u04b3\u0430\u043d\u0433\u043e\u043c\u0438")
B.ao6=new A.a("9d011116-398c-40e4-8be0-c03c29a513c8","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0444\u0430\u0440\u0434\u0438\u043a\u0443\u043d\u043e\u043d\u0438\u0438 \u0437\u0430\u0431\u043e\u043d\u0438 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u0436\u04b3\u043e...","\u0444\u0430\u0440\u0434\u0438\u043a\u0443\u043d\u043e\u043d\u0438\u0438 \u0437\u0430\u0431\u043e\u043d\u0438 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u0436\u04b3\u043e \u0430\u0437 \u04b7\u0443\u0437\u044a\u0438\u0451\u0442\u0438 \u0431\u0430\u0434\u0435\u04e3 \u0444\u0430\u0440\u043e\u0432\u043e\u043d \u0438\u0441\xad\n\u0442\u0438\u0444\u043e\u0434\u0430 \u043a\u0430\u0440\u0434\u0430\u0430\u0441\u0442. \u041c\u0430\u0441\u0430\u043b\u0430\u043d, \u0430\u0437 \u0441\u0443\u0445\u0430\u043d\u043e\u043d\u0438 \u049a\u0438\u043b\u0438\u0447\u0445\u0430\u043b\u0438\u0444\u0430\u0438 \u043c\u04ef\u0439\u0441\u0430\u0444\u0435\u0434\n\u0445\u0438\u0441\u043b\u0430\u0442\u04b3\u043e\u0438 \u0434\u0443\u0440\u04ef\u044f\u0433\u04e3, \u0440\u0438\u0451\u043a\u043e\u0440\u04e3 \u0432\u0430 \u0442\u0430\u0431\u0438\u0430\u0442\u0438 \u0437\u043e\u043b\u0438\u043c\u043e\u043d\u0430\u0438 \u04ef \u0440\u0430\u0432\u0448\u0430\u043d \u043e\u0448\xad\n\u043a\u043e\u0440 \u043c\u0435\u0433\u0430\u0440\u0434\u0430\u0434. \u04ee \u04b3\u0430\u043c\u0432\u043e\u0440\u0430 \u0431\u0430 \u0442\u043e\u0430\u0442\u0443 \u0438\u0431\u043e\u0434\u0430\u0442 \u043c\u0430\u0448\u0493\u0443\u043b \u0430\u0441\u0442, \u0432\u0430\u043b\u0435 \u0434\u0430\u0441\xad\u0442\u0430\u0438\n\u0440\u043e\u04b3\u0437\u0430\u043d\u043e\u043d\u0438 \u0410\u0431\u0434\u0443\u0440\u0440\u0430\u04b3\u043c\u043e\u043d\u0441\u0430\u0440\u0434\u043e\u0440\u0440\u043e, \u043a\u0438 \u043d\u0438\u044f\u0442\u0438 \u0493\u043e\u0440\u0430\u0442 \u043d\u0430\u043c\u0443\u0434\u0430\u043d\u0438\n\u04b2\u0438\u0440\u043e\u0442\u0440\u043e \u0434\u043e\u0448\u0442\u0430\u043d\u0434, \u0447\u0443\u043d\u0438\u043d \u0434\u0443\u043e \u043c\u0435\u0434\u0438\u04b3\u0430\u0434: \xab\u0411\u0430 \u0434\u0430\u0441\u0442 \u0434\u0430\u0440\u043e\u0440\u0435\u0434, \u0431\u0430 \u0434\u0430\u0441\u0442\n\u043d\u0430\u0430\u0444\u0442\u0435\u0434, \u043f\u0430\u0445\u0448 \u043a\u0443\u043d\u0435\u0434, \u043f\u0430\u0445\u0448 \u043d\u0430\u0448\u0430\u0432\u0435\u0434, \u0425\u0438\u0437\u0440\u0443 \u0418\u043b\u0451\u0441 \u0451\u0440\u0430\u0442\u043e\u043d, \u0447\u043e\u0440\u0451\u0440\n\u043c\u0430\u0434\u0430\u0434\u0433\u043e\u0440\u0430\u0442\u043e\u043d \u0431\u043e\u0434!\xbb")
B.a5k=new A.a("1ff7fa92-3aca-4ac6-9cc1-f2572778c199","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0414\u0430\u0440 \u043e\u0445\u0438\u0440\u0438 \u0430\u0441\u0440\u0438 XIX \u0434\u0430\u0440 \u0410\u0432\u0440\u0443\u043f\u043e ...","\u0414\u0430\u0440 \u043e\u0445\u0438\u0440\u0438 \u0430\u0441\u0440\u0438 XIX \u0434\u0430\u0440 \u0410\u0432\u0440\u0443\u043f\u043e \u0432\u0430 \u0418\u041c\u0410 \u043c\u0435\xad\n\u0442\u043e\u0434\u0438 \u044d\u04b7\u043e\u0434\u0438\u0438 \u043d\u0430\u0442\u0443\u0440\u0430\u043b\u0438\u0437\u043c (\u0430\u0437 \u043a\u0430\u043b\u0438\u043c\u0430\u0438 \u043b\u043e\u0442\u0438\u043d\u04e3,\n\u043c\u0430\u044a\u043d\u043e\u044f\u0448")
B.aaI=new A.a("7ff1f1c4-be7e-4bba-aa8c-6d5f44939f7d","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0411\u043e\u044f\u0434 \u0433\u0443\u0444\u0442, \u043a\u0438 \u0442\u0430\u0441\u0432\u0438\u0440\u0438 \u0430\u0439\u043d\u0430\u043d\u0438 \u04b3...","\u0411\u043e\u044f\u0434 \u0433\u0443\u0444\u0442, \u043a\u0438 \u0442\u0430\u0441\u0432\u0438\u0440\u0438 \u0430\u0439\u043d\u0430\u043d\u0438 \u04b3\u0430\u0451\u0442\u0438 \u0432\u043e\u049b\u0435\u04e3 \u0431\u043e\u0438\u0441\u0438 \u0434\u0430\u0440 \u0430\u0441\u0430\u0440\u0438\n\u0431\u0430\u0434\u0435\u04e3 \u0440\u043e\u04b3 \u0451\u0444\u0442\u0430\u043d\u0438 \u04b3\u043e\u0434\u0438\u0441\u0430\u04b3\u043e\u0438 \u043e\u0434\u0438\u0432\u0443 \u0434\u0443\u0432\u0443\u043c\u0434\u0430\u0440\u0430\u04b7\u0430\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u04e3 \u043c\u0435\u0433\u0430\u0440\xad\n\u0434\u0430\u0434 \u0432\u0430 \u0438\u043d \u04b3\u043e\u043b\u0430\u0442 \u0431\u0430 \u043f\u0430\u0441\u0442\u0448\u0430\u0432\u0438\u0438 \u0430\u0440\u0437\u0438\u0448\u04b3\u043e\u0438 \u044d\u0441\u0442\u0435\u0442\u0438\u043a\u04e3, \u043c\u0430\u044a\u0440\u0438\u0444\u0430\u0442\u04e3\n\u0432\u0430 \u0430\u0445\u043b\u043e\u049b\u0438\u0438 \u044d\u04b7\u043e\u0434\u0438 \u0430\u0434\u0438\u0431\u043e\u043d \u0441\u0430\u0431\u0430\u0431 \u043c\u0435\u0448\u0430\u0432\u0430\u0434. \u0422\u0430\u0441\u0432\u0438\u0440\u0438 \u043d\u0430\u0442\u0443\u0440\u0430\u043b\u0438\u0441\u0442\u04e3\n\u0434\u0430\u0440 \u0441\u043e\u043b\u04b3\u043e\u0438 20 \u0432\u0430 30 \u0430\u0441\u0440\u0438 \u0425\u0425 \u0434\u0430\u0440 \u044d\u04b7\u043e\u0434\u0438\u0451\u0442\u0438 \u043d\u0430\u0432\u0438\u0441\u0430\u043d\u0434\u0430\u0433\u043e\u043d\u0438 \u04b7\u0430\u0432\u043e\u043d\u0438\n\u0442\u043e\u04b7\u0438\u043a \u043c\u0443\u0448\u043e\u04b3\u0438\u0434\u0430 \u043c\u0435\u0448\u0430\u0432\u0430\u0434.")
B.afa=new A.a("9b544232-904e-4166-92d1-7e8a417b16d1","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0423\u043d\u0441\u0443\u0440\u04b3\u043e\u0438 \u0430\u0432\u0432\u0430\u043b\u0438\u043d\u0438 \u043c\u0435\u0442\u043e\u0434\u0438 \u0440\u0435\u0430\u043b\u0438...","\u0423\u043d\u0441\u0443\u0440\u04b3\u043e\u0438 \u0430\u0432\u0432\u0430\u043b\u0438\u043d\u0438 \u043c\u0435\u0442\u043e\u0434\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c \u0434\u0430\u0440 \u0430\u0434\u0430\u0431\u0438\u0451\u0442\u0438 \u0442\u043e\u04b7\u0438\u043a \u0434\u0430\u0440\n\u043e\u0441\u043e\u0440\u0438 \u0430\u0434\u0438\u0431\u043e\u043d\u0438 \u0430\u04b3\u0434\u0438 \u04b7\u0430\u0434\u0438\u0434\u0438\u044f \u043f\u0430\u0439\u0434\u043e \u0448\u0443\u0434. \u0411\u0430\u044a\u0434\u0442\u0430\u0440 \u0438\u043d \u043c\u0435\u0442\u043e\u0434 \u0434\u0430\u0440\n\u044d\u04b7\u043e\u0434\u0438\u0451\u0442\u0438 \u0430\u0434\u0438\u0431\u043e\u043d\u0438 \u0442\u043e\u04b7\u0438\u043a\u0438 \u0430\u04b3\u0434\u0438 \u0448\u04ef\u0440\u0430\u0432\u04e3, \u0447\u0443\u043d \u0421. \u0410\u0439\u043d\u04e3, \u0421. \u0423\u043b\u0443\u0493\u0437\u043e\u0434\u0430,\n\u041c. \u0422\u0443\u0440\u0441\u0443\u043d\u0437\u043e\u0434\u0430, \u04b6. \u0418\u043a\u0440\u043e\u043c\u04e3, \u0420. \u04b6\u0430\u043b\u0438\u043b, \u041f. \u0422\u043e\u043b\u0438\u0441, \u0424. \u041c\u0443\u04b3\u0430\u043c\u043c\u0430\u0434\u0438\u0435\u0432,\n\u041c. \u049a\u0430\u043d\u043e\u0430\u0442, \u041b. \u0428\u0435\u0440\u0430\u043b\u04e3, \u04ee. \u041a\u04ef\u04b3\u0437\u043e\u0434, \u0421\u043e\u0440\u0431\u043e\u043d, \u0421. \u0422\u0443\u0440\u0441\u0443\u043d, \u0410. \u0421\u0430\u043c\u0430\u0434 \u0432\u0430\n\u0434\u0438\u0433\u0430\u0440\u043e\u043d \u0438\u043d\u043a\u0438\u0448\u043e\u0444 \u0451\u0444\u0442\u0430, \u043f\u0430\u04b3\u043b\u0443\u04b3\u043e\u0438 \u0433\u0443\u043d\u043e\u0433\u0443\u043d\u0438 \u0443\u0441\u043b\u0443\u0431\u0438\u0438 \u043e\u043d \u043c\u0443\u0441\u0442\u0430\u04b3\u043a\u0430\u043c\n\u0433\u0430\u0440\u0434\u0438\u0434. \u0410\u043b\u04b3\u043e\u043b \u043c\u0435\u0442\u043e\u0434\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c \u043c\u0435\u0442\u043e\u0434\u0438 \u0430\u0441\u043e\u0441\u0438\u0438 \u0442\u0430\u0441\u0432\u0438\u0440 \u0434\u0430\u0440 \u0430\u0434\u0430\u0431\u0438\u0451\xad\n\u0442\u0438 \u0434\u0430\u0432\u0440\u0430\u0438 \u043d\u0430\u0432\u0438 \u0442\u043e\u04b7\u0438\u043a \u043c\u0435\u0431\u043e\u0448\u0430\u0434.")
B.abF=new A.a("985d862c-2040-46f5-a327-bef590eb5ba8","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u041c\u0435\u0442\u043e\u0434\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c \u0442\u0430\u0441\u0432\u0438\u0440\u04b3\u043e\u0438 \u043f\u0443\u0440\u043e\u0431...","\u041c\u0435\u0442\u043e\u0434\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c \u0442\u0430\u0441\u0432\u0438\u0440\u04b3\u043e\u0438 \u043f\u0443\u0440\u043e\u0431\u0443\u0440\u0430\u043d\u0433\u0438\n\u043c\u0443\u0431\u043e\u043b\u0438\u0493\u0430\u0432\u04e3, \u0440\u043e\u043c\u0430\u043d\u0442\u0438\u043a\u04e3, \u0440\u0430\u043c\u0437\u04e3, \u0430\u0441\u043e\u0442\u0438\u0440\u04e3,\n\u0440\u0438\u0432\u043e\u044f\u0442\u04e3, \u0430\u0444\u0441\u043e\u043d\u0430\u0432\u04e3, \u0442\u0430\u043c\u0441\u0438\u043b\u04e3, \u04b3\u0443\u0437\u043d\u0430\u043d\u0433\u0435\u0437 \u0432\u0430\n\u0493\u0430\u0439\u0440\u0430\u0440\u043e \u0438\u043d\u043a\u043e\u0440 \u043d\u0430\u043c\u0435\u043a\u0443\u043d\u0430\u0434. \u0410\u0437 \u04b7\u0443\u043c\u043b\u0430, \u0434\u0430\u0440\n\u0430\u0441\u0430\u0440\u04b3\u043e\u0438 \xab\u041e\u0434\u0438\u043d\u0430\xbb, \xab\u0414\u043e\u0445\u0443\u043d\u0434\u0430\xbb, \xab\u0401\u0434\u0434\u043e\u0448\u0442\u04b3\u043e\xbb-\u0438 \u0421. \u0410\u0439\u043d\u04e3, \xab\u0412\u0430\u0442\u0430\xad\u043d\u0438\n\u0428\u043e\u0434\u04e3\xbb, \xab\u0414\u0443 \u043d\u0438\u0448\u043e\u043d\xbb, \xab\u0422\u043e\u04b7 \u0432\u0430 \u0431\u0430\u0439\u0440\u0430\u049b\xbb, \xab\u041f\u0430\u0440\u0438\u0438 \u0411\u0430\u0445\u0442\xbb-\u0438 \u0410. \u041b\u043e\xad\u04b3\u0443\xad\n\u0442\u04e3, \xab\u0422\u0430\u0445\u0442\u0438 \u0445\u0443\u043d\u0438\u043d\xbb, \xab\u0411\u0430\u04b3\u043e\u0440\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u0432\u0430 \u043d\u043e\u043b\u0430\u0438 \u0447\u04ef\u043f\u043e\u043d\u04e3\xbb, \xab\u041c\u0430\xad\n\u043d\u043e\u0440\u0430\u0438 \u041c\u0430\u0440\u0433\xbb-\u0438 \u041f. \u0421\u0443\u043b\u0430\u0439\u043c\u043e\u043d\u04e3, \xab\u0425\u0430\u0437\u043e\u043d \u0432\u0430 \u0431\u0430\u04b3\u043e\u0440\xbb, \xab\u041f\u0438\u0441\u0430\u0440\u0438")
B.aq2=new A.a("19b037aa-1f7b-4368-8618-44a1d9409f81","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0412\u0430\u0442\u0430\u043d\xbb-\u0438 \u041c. \u0422\u0443\u0440\u0441\u0443\u043d\u0437\u043e\u0434\u0430, \xab\u049a\u0438\u0448\u043b\u043e...","\u0412\u0430\u0442\u0430\u043d\xbb-\u0438 \u041c. \u0422\u0443\u0440\u0441\u0443\u043d\u0437\u043e\u0434\u0430, \xab\u049a\u0438\u0448\u043b\u043e\u049b\u0438 \u0442\u0438\u043b\u043b\u043e\u04e3\xbb, \xab\u041f\u0430\u043d\u04b7\u0438 \u043d\u043e\u043e\u0440\u043e\u043c\xbb-\u0438\n\u041c. \u041c\u0438\u0440\u0448\u0430\u043a\u0430\u0440, \xab\u0420\u0443\u0441\u0442\u0430\u043c \u0432\u0430 \u0421\u0443\u04b3\u0440\u043e\u0431\xbb, \xab\u04b2\u0443\u0440\u0440\u0438\u044f\u0442\xbb-\u0438 \u0492. \u0410\u0431\u0434\u0443\u043b\u043b\u043e,\n\xab\u0422\u043e\u04b7\u0438 \u0434\u0430\u0432\u043b\u0430\u0442\xbb-\u0438 \u0492. \u041c\u0438\u0440\u0437\u043e, \xab\u0414\u043e\u0441\u0442\u043e\u043d\u0438 \u043e\u0442\u0430\u0448\xbb-\u0438 \u041c. \u049a\u0430\u043d\u043e\u0430\u0442, \u0431\u0430\u044a\u0437\u0435\n\u0430\u0441\u0430\u0440\u04b3\u043e\u0438 \u04b6. \u0418\u043a\u0440\u043e\u043c\u04e3, \u0424. \u041c\u0443\u04b3\u0430\u043c\u043c\u0430\u0434\u0438\u0435\u0432, \u04ee. \u041a\u04ef\u04b3\u0437\u043e\u0434, \u041c. \u0411\u0430\u0445\u0442\u04e3, \u0421\u043e\u0440\xad\n\u0431\u043e\u043d, \u0410. \u0421\u0430\u043c\u0430\u0434 \u0432\u0430 \u0434\u0438\u0433\u0430\u0440\u043e\u043d \u0442\u0430\u0441\u0432\u0438\u0440\u04b3\u043e\u0438 \u043d\u043e\u043c\u0431\u0443\u0440\u0434\u0430\u0440\u043e \u043c\u0443\u0448\u043e\u04b3\u0438\u0434\u0430 \u043a\u0430\u0440\xad\n\u0434\u0430\u043d \u043c\u0443\u043c\u043a\u0438\u043d \u0430\u0441\u0442.")
B.ab8=new A.a("b3674c8f-4189-45b0-adc1-073293c7e19d","afc28bbb-ebba-4669-9715-a10cbbe7400a","\xab\u0411\u0430\u04b3\u043e\u0440\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u0432\u0430 \u043d\u043e\u043b\u0430\u0438 \u0447\u04ef...","\xab\u0411\u0430\u04b3\u043e\u0440\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u0432\u0430 \u043d\u043e\u043b\u0430\u0438 \u0447\u04ef\u043f\u043e\u043d\u04e3\xbb \u043d\u043e\u043c \u0448\u0435\u044a\u0440\u0438 \u041f\u0430\u0439\u0440\u0430\u0432\n\u04b3\u0430\u043c\u0430\u0433\u04e3 \u0430\u0437 \u0447\u043e\u0440 \u0431\u0430\u043d\u0434\u0438 \u0447\u0430\u04b3\u043e\u0440\u043c\u0438\u0441\u0440\u0430\u04e3 \u0438\u0431\u043e\u0440\u0430\u0442 \u043c\u0435\u0431\u043e\u0448\u0430\u0434. \u0421\u0435 \u0431\u0430\u043d\u0434\u0438 \u0430\u0432\xad\n\u0432\u0430\u043b \u049b\u043e\u0444\u0438\u044f\u0438")
B.adT=new A.a("ab0ec31c-6fbd-466d-8f6c-857df1a3132d","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0414\u0430\u0448\u0442\u0438 \u0432\u0430\u0441\u0435\u0432\u0443 \u0431\u043e\u0493\u0438 \u043b\u0430\u0442\u0438\u0444\u0443 \u04b3\u0430\u0432\u043e\u0438...","\u0414\u0430\u0448\u0442\u0438 \u0432\u0430\u0441\u0435\u0432\u0443 \u0431\u043e\u0493\u0438 \u043b\u0430\u0442\u0438\u0444\u0443 \u04b3\u0430\u0432\u043e\u0438 \u0445\u0443\u0448,\n\u0421\u0430\u04b3\u0440\u043e\u0432\u0443 \u04b7\u0430\u043d\u0433\u0430\u043b\u0443 \u0447\u0430\u043c\u0430\u043d\u0443 \u043a\u04ef\u04b3\u0443 \u043b\u043e\u043b\u0430\u0437\u043e\u0440;\n\u0410\u0437 \u04b3\u0430\u0440 \u043a\u0430\u043d\u043e\u0440 \u0447\u0430\u0448\u043c\u0430 \u0440\u0430\u0432\u043e\u043d \u0430\u0441\u0442\u0443 \u043e\u0431\u0448\u043e\u0440,\n\u04b2\u0430\u0440 \u0441\u04ef \u0431\u0430\u043b\u0430\u043d\u0434 \u0437\u0430\u043c\u0437\u0430\u043c\u0430\u0432\u0443 \u043d\u043e\u043b\u0430\u0432\u0443 \u0445\u0443\u0440\u04ef\u0448...")
B.abf=new A.a("1d1b4216-4f27-4362-aad7-3eb12b315c1b","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0414\u0430\u0440 \u0431\u0430\u043d\u0434\u0438 \u0430\u0432\u0432\u0430\u043b \u0442\u0430\u0441\u0432\u0438\u0440 \u0431\u0430 \u0432\u043e\u0441\u0438...","\u0414\u0430\u0440 \u0431\u0430\u043d\u0434\u0438 \u0430\u0432\u0432\u0430\u043b \u0442\u0430\u0441\u0432\u0438\u0440 \u0431\u0430 \u0432\u043e\u0441\u0438\u0442\u0430\u0438 \u0441\u0430\u043d\u044a\u0430\u0442\u04b3\u043e\u0438 \u0441\u0438\u0444\u0430\u0442\u0447\u0438\u043d\u04e3\n(\u0438\u0441\u043c\u04b3\u043e\u0438")
B.ass=new A.a("3a2d7731-f13e-42b3-9288-ff320306be88","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0414\u0430\u0440 \u0431\u0430\u043d\u0434\u0438 \u0434\u0443\u0432\u0443\u043c \u0442\u0430\u0441\u0432\u0438\u0440 \u0430\u0437 \u043a\u0443\u043b\u043b...","\u0414\u0430\u0440 \u0431\u0430\u043d\u0434\u0438 \u0434\u0443\u0432\u0443\u043c \u0442\u0430\u0441\u0432\u0438\u0440 \u0430\u0437 \u043a\u0443\u043b\u043b \u0431\u0430 \u04b7\u0443\u0437\u044a \u043c\u0435\u0433\u0443\u0437\u0430\u0440\u0430\u0434. \u041c\u0430\u043d\u0437\u0430\u0440\u0430\u0438\n\u0431\u0430\u04b3\u043e\u0440\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u0434\u0430\u0440 \u043c\u0438\u0441\u043e\u043b\u0438 \u0433\u0443\u043b\u04b3\u043e\u0438 \u04b3\u0430\u0440\u0440\u0430\u043d\u0433\u0430 \u0431\u0430 \u0431\u0430\u0440 \u043a\u0430\u0440\u0434\u0430\u043d\u0438\n\u0434\u0430\u0440\u0430\u0445\u0442\u043e\u043d\u0438 \u04b7\u0430\u0432\u043e\u043d \u0442\u0430\u044a\u043a\u0438\u0434 \u043c\u0435\u0448\u0430\u0432\u0430\u0434. \u0421\u0430\u043d\u044a\u0430\u0442\u04b3\u043e\u0438 \u0431\u0430\u0434\u0435\u0438\u0438 \u0442\u0430\u0448\u0431\u0435\u04b3\u0443 \u0438\u0441\xad\n\u0442\u0438\u043e\u0440\u0430 \u0432\u0430 \u0442\u0430\u0432\u0441\u0438\u0444\u0443 \u0441\u0438\u0444\u0430\u0442\u0447\u0438\u043d\u04e3 \u0445\u043e\u0442\u0438\u0440\u0438 \u0445\u043e\u043d\u0430\u043d\u0434\u0430\u0440\u043e \u0431\u043e\u043b\u0438\u0434\u0430 \u0434\u043e\u0448\u0442\u0430,\n\u04ef\u0440\u043e \u0431\u0430 \u0432\u0430\u0437\u044a\u0438\u044f\u0442 \u0432\u0430 \u04b3\u043e\u043b\u0430\u0442\u0438 \u0440\u04ef\u04b3\u0438\u0438 \u0447\u04ef\u043f\u043e\u043d\u0438 \u043d\u0430\u0439\u043d\u0430\u0432\u043e\u0437 \u043c\u0443\u0442\u0430\u0432\u0430\u04b7\u04b7\u0435\u04b3 \u043c\u0435\xad\n\u0441\u043e\u0437\u0430\u0434. \u041c\u0430\u0442\u043b\u0430\u0431\u0438 \u0448\u043e\u0438\u0440 \u0434\u0430\u0440 \u0434\u0443 \u0431\u0430\u043d\u0434\u0438 \u043e\u0445\u0438\u0440 \u0447\u0443\u043d\u0438\u043d \u0438\u0444\u043e\u0434\u0430 \u0451\u0444\u0442\u0430\u0430\u0441\u0442:")
B.am_=new A.a("e8fb6051-b953-444b-948b-80ca30a9079d","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u0411\u0438\u043d\u0448\u0430\u0441\u0442\u0430 \u0431\u0443\u0434 \u0448\u0443\u0431\u043e\u043d\u043f\u0438\u0441\u0430\u0440\u0435 \u043d\u043e\u0439 \u0434...","\u0411\u0438\u043d\u0448\u0430\u0441\u0442\u0430 \u0431\u0443\u0434 \u0448\u0443\u0431\u043e\u043d\u043f\u0438\u0441\u0430\u0440\u0435 \u043d\u043e\u0439 \u0434\u0430\u0440 \u0434\u0430\u04b3\u043e\u043d\n\u0417\u0435\u0440\u0438 \u0434\u0430\u0440\u0430\u0445\u0442\u0438 \u0431\u0435\u0434, \u043b\u0430\u0431\u0438 \u04b7\u04ef\u0439\u0438 \u0431\u043e\u0441\u0430\u0444\u043e.\n\u041e\u0437\u043e\u0434\u0430 \u0433\u0438\u0440\u0434\u0438 \u04ef \u0431\u0430\u0440\u0430\u0435 \u0447\u0430\u043d\u0434 \u0434\u0430\u0440 \u0447\u0430\u0440\u043e,\n\u0411\u043e \u0441\u04ef\u0437\u0438 \u0434\u0438\u043b \u0445\u0443\u0440\u04ef\u0448 \u04b3\u0430\u043c\u0435\u043a\u0430\u0440\u0434 \u043d\u0430\u0439, \u043a\u0438 \u04b3\u043e\u043d\u2013\n\u0423\u0441\u0442\u043e\u0434\u0438 \u0437\u0443\u0444\u0443\u043d\u0443\u043d\u0438\n1\n\u0437\u0430\u0431\u0430\u0440\u0434\u0430\u0441\u0442\u0438 \u0440\u04ef\u0437\u0433\u043e\u0440,\n\u042f\u044a\u043d\u0435 \u0442\u0430\u0431\u0438\u0430\u0442 \u0430\u0437 \u043d\u0430\u0445\u0438 \u0430\u0431\u0440\u0435\u0448\u0438\u043c\u0438 \u0431\u0430\u04b3\u043e\u0440,")
B.aka=new A.a("43424103-af65-4ab0-95a0-2bc5ff050723","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u041d\u043e\u0437\u0443\u043a \u0438\u0451\u0440","\u041d\u043e\u0437\u0443\u043a \u0438\u0451\u0440\n1\n\u0431\u043e\u0444\u0442\u0430 \u049b\u043e\u043b\u0438\u043d\u0438 \u043c\u0430\u0445\u043c\u0430\u043b\u0438\u043d\n\u0413\u0443\u0441\u0442\u0430\u0440\u0434\u0430, \u0442\u043e \u043a\u0438 \u0451\u0440 \u043d\u0438\u04b3\u0430\u0434 \u043f\u043e\u0439 \u0431\u0430\u0440 \u0437\u0430\u043c\u0438\u043d...")
B.abk=new A.a("8268e39c-1a31-4623-94bd-54018a543085","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u041c\u0430\u043d\u0437\u0430\u0440\u0430\u0438 \u0442\u0430\u0431\u0438\u0430\u0442 \u0432\u043e\u0441\u0438\u0442\u0430\u0438 \u043c\u0443\u04b3\u0438\u043c\u043c...","\u041c\u0430\u043d\u0437\u0430\u0440\u0430\u0438 \u0442\u0430\u0431\u0438\u0430\u0442 \u0432\u043e\u0441\u0438\u0442\u0430\u0438 \u043c\u0443\u04b3\u0438\u043c\u043c\u0438 \u0442\u0430\u0441\u0432\u0438\u0440\u0438 \u0432\u0430\u0437\u044a\u0438\u044f\u0442, \u043e\u0440\u0437\u0443\u044e\n\u043e\u043c\u043e\u043b \u0432\u0430 \u0430\u043d\u0434\u0435\u0448\u0430\u04b3\u043e\u0438 \u0448\u0438\u0440\u0438\u043d\u0438 \u043e\u0431\u0440\u0430\u0437\u0438 \u0447\u04ef\u043f\u043e\u043d\u043f\u0438\u0441\u0430\u0440 \u0431\u0430 \u0448\u0443\u043c\u043e\u0440 \u043c\u0435\u0440\u0430\xad\n\u0432\u0430\u0434. \u041d\u0430\u0439\u0438 \u0447\u04ef\u043f\u043e\u043d\u04e3 \u0430\u0437 \u044d\u04b7\u043e\u0437\u043a\u043e\u0440\u0438\u04b3\u043e\u0438 \xab\u0443\u0441\u0442\u043e\u0434\u0438 \u0437\u0443\u0444\u0443\u043d\u0443\u043d\u0438 \u0437\u0430\xad\u0431\u0430\u0440\u0434\u0430\u0441\u0442\u0438\n\u0440\u04ef\u0437\u0433\u043e\u0440\xbb \u0431\u0430\u0448\u043e\u0440\u0430\u0442 \u043c\u0435\u0434\u0438\u04b3\u0430\u0434. \u0422\u0430\u0431\u0438\u0430\u0442 \u0431\u0430 \u04b3\u043e\u043b\u0430\u0442\u0438 \u0440\u04ef\u04b3\u0438\u0438 \u049b\u0430\u04b3\u0440\u0430\u043c\u043e\u043d \u0447\u0443\xad\n\u043d\u043e\u043d \u0441\u043e\u0437\u0433\u043e\u0440 \u0432\u0430 \u043c\u0443\u0432\u043e\u0444\u0438\u049b \u0430\u0441\u0442, \u043a\u0438 \u0433\u04ef\u0451 \u0431\u0430 \u0445\u043e\u0442\u0438\u0440\u0438 \u0442\u0430\u0448\u0440\u0438\u0444\u0438 \u043c\u0430\u04b3\u0431\u0443\u0431\u0430\u0438\n\u0447\u04ef\u043f\u043e\u043d\u043f\u0438\u0441\u0430\u0440 \u0430\u0437 \u0441\u0430\u0431\u0437\u0430 \u043f\u043e\u044f\u043d\u0434\u043e\u0437 \u0433\u0443\u0441\u0442\u0430\u0440\u0434\u0430\u0430\u0441\u0442. \u0418\u043d \u0441\u043e\u0437\u0433\u043e\u0440\u0438\u0438 \u043c\u0430\u043d\u0437\u0430\u0440\u0430\u0438\n\u0442\u0430\u0431\u0438\u0430\u0442 \u0431\u0430 \u0432\u0430\u0437\u044a\u0438\u044f\u0442\u0438 \u0443\u043c\u0435\u0434\u0432\u043e\u0440\u043e\u043d\u0430\u0438 \u0447\u04ef\u043f\u043e\u043d\u043f\u0438\u0441\u0430\u0440, \u0431\u0430 \u0437\u0430\u043c\u0438\u043d\u0430\u0438 \u0440\u0435\u0430\u043b\u0438\u0441\xad\n\u0442\u0438\u0438 \u0442\u0430\u0441\u0432\u0438\u0440 \u0438\u0448\u043e\u0440\u0430 \u043a\u0430\u0440\u0434\u0430, \u0430\u0437 \u049b\u0430\u0434\u0440\u0443 \u043c\u0430\u043d\u0437\u0430\u043b\u0430\u0442 \u0432\u0430 \u043c\u0443\u04b3\u0430\u0431\u0431\u0430\u0442\u0438 \u043f\u043e\u043a\u0438\n\u0438\u043d\u0441\u043e\u043d\u0438 \u043c\u0435\u04b3\u043d\u0430\u0442\u04e3 \u0434\u0430\u0440\u0430\u043a \u043c\u0435\u0434\u0438\u04b3\u0430\u0434.")
B.afs=new A.a("2e297168-bcba-4fbd-96dc-7b9b4b11ebd7","afc28bbb-ebba-4669-9715-a10cbbe7400a","\u04b2\u0430\u043c\u0438\u043d \u0442\u0430\u0440\u0438\u049b, \u043c\u0435\u0442\u043e\u0434\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c \u0430\u0437...","\u04b2\u0430\u043c\u0438\u043d \u0442\u0430\u0440\u0438\u049b, \u043c\u0435\u0442\u043e\u0434\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u043c \u0430\u0437 \u043d\u0430\u0432\u0438\u0441\u0430\u043d\u0434\u0430\u0433\u043e\u043d \u0442\u0430\u043b\u0430\u0431 \u0434\u043e\u0440\u0430\u0434,\n\u043a\u0438 \u043e\u043d\u04b3\u043e \u0432\u043e\u049b\u0435\u0430\u04b3\u043e\u0438 \u043c\u0443\u04b3\u0438\u043c \u0432\u0430 \u0430\u0432\u0432\u0430\u043b\u0434\u0430\u0440\u0430\u04b7\u0430\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u0438\u0440\u043e \u0438\u043d\u0442\u0438\u0445\u043e\u0431\n\u043a\u0430\u0440\u0434\u0430, \u0431\u0430 \u0432\u043e\u0441\u0438\u0442\u0430\u0438 \u043e\u0431\u0440\u0430\u0437\u04b3\u043e\u0438 \u044d\u044a\u0442\u0438\u043c\u043e\u0434\u0431\u0430\u0445\u0448 \u04b3\u0430\u049b\u0438\u049b\u0430\u0442\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u0438\u0440\u043e \u0431\u0430\n\u04b3\u0430\u049b\u0438\u049b\u0430\u0442\u0438 \u0431\u0430\u0434\u0435\u04e3 \u0442\u0430\u0431\u0434\u0438\u043b \u0434\u0438\u04b3\u0430\u043d\u0434.")
B.aiX=new A.a("f2cedc1e-3773-4e55-9c51-8ebde06b76eb","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0428\u043e\u0438\u0440\u0438 \u0445\u0430\u043b\u049b\u0438\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u041c\u0443\u044a\u043c\u0438\u043d...","\u0428\u043e\u0438\u0440\u0438 \u0445\u0430\u043b\u049b\u0438\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u041c\u0443\u044a\u043c\u0438\u043d \u049a\u0430\xad\n\u043d\u043e\u0430\u0442 20 \u043c\u0430\u0439\u0438 \u0441\u043e\u043b\u0438 1932 \u0434\u0430\u0440 \u0434\u0435\u04b3\u0430\u0438 \u041a\u0443\u0440\u0433\u043e\u0432\u0430\u0434\u0438\n\u043d\u043e\u04b3\u0438\u044f\u0438 \u0414\u0430\u0440\u0432\u043e\u0437\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u0431\u0430 \u0434\u0443\u043d\u0451 \u043e\u043c\u0430\u0434\u0430\xad\n\u0430\u0441\u0442. \u041f\u0430\u0434\u0430\u0440\u0438 \u0448\u043e\u0438\u0440 \u2013 \u049a\u0430\u043d\u043e\u0430\u0442\u0448\u043e\u04b3 \u0432\u0430 \u043c\u043e\u0434\u0430\u0440\u0430\u0448 \u2013\n\u0411\u0435\u0433\u0438\u043c\u043c\u043e\u04b3 \u0448\u0430\u0445\u0441\u043e\u043d\u0438 \u043f\u043e\u043a\u0443 \u043f\u043e\u0440\u0441\u043e \u0432\u0430 \u0437\u0430\u04b3\u043c\u0430\u0442\u043a\u0430\u0448\u0443 \u043c\u0435\u04b3\u0440\u0443\u0431\u043e\u043d \u0431\u0443\u0434\u0430, \u0434\u0430\u0440\n\u0442\u0430\u044a\u043b\u0438\u043c\u0443 \u0442\u0430\u0440\u0431\u0438\u044f\u0438 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u043e\u043d \u043a\u04ef\u0448\u0438\u0448\u0438 \u0437\u0438\u0451\u0434 \u043d\u0430\u043c\u0443\u0434\u0430\u0430\u043d\u0434.")
B.afZ=new A.a("ec3bde54-6a9c-458f-8685-faf03a19e88d","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u041c\u0443\u044a\u043c\u0438\u043d \u049a\u0430\u043d\u043e\u0430\u0442 \u0442\u0430\u04b3\u0441\u0438\u043b\u0438 \u0438\u0431\u0442\u0438\u0434\u043e\u0438\u0440...","\u041c\u0443\u044a\u043c\u0438\u043d \u049a\u0430\u043d\u043e\u0430\u0442 \u0442\u0430\u04b3\u0441\u0438\u043b\u0438 \u0438\u0431\u0442\u0438\u0434\u043e\u0438\u0440\u043e \u0434\u0430\u0440 \u0434\u0435\u04b3\u0430\u0438 \u041a\u0443\u0440\u0433\u043e\u0432\u0430\u0434 \u043c\u0435\xad\n\u0433\u0438\u0440\u0430\u0434. \u0411\u0430\u044a\u0434\u0442\u0430\u0440 \u0442\u0430\u04b3\u0441\u0438\u043b\u0440\u043e \u0434\u0430\u0440 \u0448\u0430\u04b3\u0440\u0430\u043a\u0438 \u0492\u0430\u0440\u043c \u0438\u0434\u043e\u043c\u0430 \u0434\u043e\u0434\u0430, \u043c\u0430\u043a\u0442\u0430\u0431\u0438\n\u043c\u0438\u0451\u043d\u0430\u0440\u043e \u0441\u043e\u043b\u0438 1951 \u0445\u0430\u0442\u043c \u043c\u0435\u043a\u0443\u043d\u0430\u0434. \u041f\u0430\u0441 \u0430\u0437 \u043e\u043d \u0431\u0430 \u0448\u0443\u044a\u0431\u0430\u0438 \u0437\u0430\u0431\u043e\u043d \u0432\u0430\n\u0430\u0434\u0430\u0431\u0438\u0451\u0442\u0438 \u0442\u043e\u04b7\u0438\u043a\u0438 \u0414\u043e\u043d\u0438\u0448\u0433\u043e\u04b3\u0438 \u0434\u0430\u0432\u043b\u0430\u0442\u0438\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u0434\u043e\u0445\u0438\u043b \u0448\u0443\u0434\u0430,\n\u043e\u043d\u0440\u043e \u0441\u043e\u043b\u0438 1956 \u0431\u0430 \u043f\u043e\u0451\u043d \u043c\u0435\u0440\u0430\u0441\u043e\u043d\u0430\u0434.")
B.ajK=new A.a("12ad6690-453f-46a8-bfff-318c640d4004","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u04b2\u0430\u043d\u0433\u043e\u043c\u0438 \u0442\u0430\u04b3\u0441\u0438\u043b \u0434\u0430\u0440 \u043c\u0430\u043a\u0442\u0430\u0431\u04b3\u043e\u0438 \u043c...","\u04b2\u0430\u043d\u0433\u043e\u043c\u0438 \u0442\u0430\u04b3\u0441\u0438\u043b \u0434\u0430\u0440 \u043c\u0430\u043a\u0442\u0430\u0431\u04b3\u043e\u0438 \u043c\u0438\u0451\u043d\u0430 \u0432\u0430 \u043e\u043b\u04e3 \u041c\u0443\u044a\u043c\u0438\u043d\n\u049a\u0430\u043d\u043e\u0430\u0442 \u0431\u0430 \u043e\u043c\u04ef\u0437\u0438\u0448\u0438 \u0442\u0430\u044a\u0440\u0438\u0445\u0438 \u0430\u0434\u0430\u0431\u0438\u0451\u0442\u0438 \u0442\u043e\u04b7\u0438\u043a \u0432\u0430 \u043d\u0430\u0437\u0430\u0440\u0438\u044f\u0438 \u0430\u0434\u0430\u0431\u0438\u0451\u0442\n\u0442\u0430\u0432\u0430\u04b7\u04b7\u0443\u04b3 \u0437\u043e\u04b3\u0438\u0440 \u043d\u0430\u043c\u0443\u0434\u0430, \u0447\u0443\u043d \u043c\u0443\u0442\u0430\u0445\u0430\u0441\u0441\u0438\u0441\u0438 \u0432\u0430\u0440\u0437\u0438\u0434\u0430 \u0431\u0430 \u043a\u0430\u043c\u043e\u043b \u0440\u0430\u0441\u0438\u0434.\n\u0428\u0430\u0432\u049b\u0443 \u04b3\u0430\u0432\u0430\u0441 \u0431\u0430 \u0448\u0435\u044a\u0440 \u04ef\u0440\u043e \u0431\u0430 \u0434\u043e\u0438\u0440\u0430\u0438 \u0430\u0434\u0430\u0431\u0438\u0438 \u0421\u0442\u0430\u043b\u0438\u043d\u043e\u0431\u043e\u0434 \u0432\u043e\u0440\u0438\u0434\n\u043d\u0430\u043c\u0443\u0434. \u041c\u0443\u044a\u043c\u0438\u043d \u049a\u0430\u043d\u043e\u0430\u0442 \u0441\u043e\u043b\u04b3\u043e\u0438 1956\u20131966 \u0434\u0430\u0440 \u0438\u0434\u043e\u0440\u0430\u0438 \u043c\u0430\u04b7\u0430\u043b\u043b\u0430\u0438\n\xab\u0428\u0430\u0440\u049b\u0438 \u0441\u0443\u0440\u0445\xbb \u043a\u043e\u0440 \u043c\u0435\u043a\u0443\u043d\u0430\u0434 \u0432\u0430 \u044f\u043a \u043c\u0443\u0434\u0434\u0430\u0442 \u043c\u0443\u04b3\u0430\u0440\u0440\u0438\u0440\u0438 \u043a\u0430\u043b\u043e\u043d\u0438 \u043d\u0430\u0448\xad\n\u0440\u0438\u0451\u0442\u0438 \xab\u0418\u0440\u0444\u043e\u043d\xbb \u0431\u0443\u0434. \u0410\u0437 \u0441\u043e\u043b\u0438 1968 \u0442\u043e \u0441\u043e\u043b\u0438 1991 \u0431\u0430 \u0441\u0438\u0444\u0430\u0442\u0438 \u043a\u043e\u0442\u0438\u0431 \u0432\u0430\n\u043a\u043e\u0442\u0438\u0431\u0438 \u0430\u0432\u0432\u0430\u043b\u0438 \u0418\u0442\u0442\u0438\u0444\u043e\u049b\u0438 \u043d\u0430\u0432\u0438\u0441\u0430\u043d\u0434\u0430\u0433\u043e\u043d\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u0444\u0430\u044a\u043e\u043b\u0438\u044f\u0442\n\u043d\u0430\u043c\u0443\u0434.")
B.ac8=new A.a("a560b0a3-c0fc-4b86-82d4-c9f75928de1a","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u041c\u0443\u044a\u043c\u0438\u043d \u049a\u0430\u043d\u043e\u0430\u0442 \u0447\u0443\u043d \u043d\u0430\u043c\u043e\u044f\u043d\u0434\u0430\u0438 \u043e\u043b...","\u041c\u0443\u044a\u043c\u0438\u043d \u049a\u0430\u043d\u043e\u0430\u0442 \u0447\u0443\u043d \u043d\u0430\u043c\u043e\u044f\u043d\u0434\u0430\u0438 \u043e\u043b\u0438\u043c\u0430\u0440\u0442\u0430\u0431\u0430\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d\n\u0431\u0430 \u049b\u0438\u0442\u044a\u0430\u04b3\u043e\u0438 \u0433\u0443\u043d\u043e\u0433\u0443\u043d\u0438 \u043e\u043b\u0430\u043c, \u0430\u0437 \u04b7\u0443\u043c\u043b\u0430 \u0431\u0430 \u0448\u0430\u04b3\u0440\u0443 \u043a\u0438\u0448\u0432\u0430\u0440\u04b3\u043e\u0438 \u041a\u043e\xad\n\u0431\u0443\u043b, \u0423\u043b\u0430\u043d\u0431\u0430\u0442\u043e\u0440, \u041b\u0438\u0431\u0438\u044f, \u042f\u043c\u0430\u043d, \u041f\u043e\u043a\u0438\u0441\u0442\u043e\u043d, \u04b2\u0438\u043d\u0434\u0443\u0441\u0442\u043e\u043d, \u0427\u0438\u043d, \u042d\u0440\u043e\u043d,\n\u0410\u043c\u043e\u0440\u0430\u0442\u0438 \u041c\u0443\u0442\u0442\u0430\u04b3\u0438\u0434\u0430\u0438 \u0410\u0440\u0430\u0431,\n\u042f\u043f\u043e\u043d\u0438\u044f, \u0424\u0430\u0440\u043e\u043d\u0441\u0430, \u041a\u0443\u0431\u0430 \u0441\u0430\u0444\u0430\u0440\n\u043a\u0430\u0440\u0434\u0430,\n\u0441\u0443\u043b\u04b3\u0443 \u0434\u04ef\u0441\u0442\u0438\u0438 \u0445\u0430\u043b\u049b\u04b3\u043e\u0440\u043e \u0442\u0430\u0440\u0493\u0438\u0431 \u043d\u0430\u043c\u0443\u0434\u0430\u0430\u0441\u0442. \u0423\u0441\u0442\u043e\u0434 \u049a\u0430\u043d\u043e\u0430\u0442 \u0430\u0437 \u0441\u043e\u043b\u0438\n1997 \u043c\u0443\u043e\u0432\u0438\u043d\u0438 \u0440\u0430\u0438\u0441\u0438 \u04b2\u0430\u0440\u0430\u043a\u0430\u0442\u0438 \u0432\u0430\u04b3\u0434\u0430\u0442\u0438 \u043c\u0438\u043b\u043b\u04e3 \u0432\u0430 \u044d\u04b3\u0451\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d\n\u0431\u0443\u0434. \u042f\u043a \u043c\u0443\u0434\u0434\u0430\u0442 \u0431\u0430 \u043a\u043e\u0440\u0438 \u044d\u04b7\u043e\u0434\u04e3 \u043c\u0430\u0448\u0493\u0443\u043b \u0431\u0443\u0434.  \u0423\u0441\u0442\u043e\u0434 \u041c\u0443\u044a\u043c\u0438\u043d \u049a\u0430\u043d\u043e\u0430\u0442\n18-\u0443\u043c\u0438 \u043c\u0430\u0439\u0438 \u0441\u043e\u043b\u0438 2018 \u0430\u0437 \u043e\u043b\u0430\u043c \u0434\u0430\u0440\u0433\u0443\u0437\u0430\u0448\u0442 \u0432\u0430 \u0434\u0430\u0440 \u043c\u0430\u0437\u043e\u0440\u0438 \u041b\u0443\u0447\u043e\u0431 \u0431\u0430\n\u0445\u043e\u043a \u0441\u0443\u043f\u0443\u0440\u0434\u0430 \u0448\u0443\u0434.")
B.a98=new A.a("05d83ee1-5189-42ba-b952-4ec9f4874d08","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u041c\u0443\u044a\u043c\u0438\u043d\u0448\u043e\u04b3 \u0430\u0432\u0432\u0430\u043b \u0431\u0430 \u04b3\u0443\u043d\u0430\u0440\u0438 \u043d\u0430\u0432\u043e...","\u041c\u0443\u044a\u043c\u0438\u043d\u0448\u043e\u04b3 \u0430\u0432\u0432\u0430\u043b \u0431\u0430 \u04b3\u0443\u043d\u0430\u0440\u0438 \u043d\u0430\u0432\u043e\u0437\u0430\u043d\u0434\u0430\u0433\u04e3 \u0432\u0430\n\u0441\u0430\u0440\u043e\u044f\u043d\u0434\u0430\u0433\u04e3 \u043c\u0430\u0439\u043b \u0434\u043e\u0448\u0442\u0430\u0430\u0441\u0442. \u0412\u0430\u043b\u0435 \u0431\u0430\u044a\u0434\u0442\u0430\u0440 \u0434\u0430\u0440 \u04ef\n\u04b3\u0430\u0432\u0430\u0441\u0438 \u0448\u043e\u0438\u0440 \u0448\u0443\u0434\u0430\u043d \u043f\u0430\u0439\u0434\u043e \u043c\u0435\u0433\u0430\u0440\u0434\u0430\u0434 \u0432\u0430 \u043d\u0430\u0445\u0443\u0441\xad\n\u0442\u0438\u043d \u0448\u0435\u044a\u0440\u0430\u0448 \u0434\u0430\u0440 \u0441\u0438\u043d\u043d\u0438 17-\u0441\u043e\u043b\u0430\u0433\u04e3 \u0434\u0430\u0440 \u0432\u0430\u0441\u0444\u0438\n\u0440\u04ef\u0434\u0438 \u041f\u0430\u043d\u04b7 \u044d\u04b7\u043e\u0434 \u0448\u0443\u0434\u0430\u0430\u0441\u0442. \u041d\u0430\u043c\u0443\u043d\u0430\u0438 \u0448\u0435\u044a\u0440\u04b3\u043e\u0438 \u0448\u043e\u0433\u0438\u0440\u0434\u043e\u043d\u0430\u0438 \u0448\u043e\u0438\u0440\n\u04b3\u0430\u043d\u0433\u043e\u043c\u0438 \u0442\u0430\u04b3\u0441\u0438\u043b \u0434\u0430\u0440 \u043c\u0430\u043a\u0442\u0430\u0431\u04b3\u043e\u0438 \u043c\u0438\u0451\u043d\u0430 \u0432\u0430 \u043e\u043b\u04e3 \u0434\u0430\u0440 \u0440\u04ef\u0437\u043d\u043e\u043c\u0430\u0438 \u043d\u043e\u04b3\u0438\u044f\u0432\u0438\u0438\n\xab\u04b2\u0430\u0451\u0442\u0438 \u043d\u0430\u0432\xbb \u0432\u0430 \u043c\u0430\u04b7\u0430\u043b\u043b\u0430\u0438 \xab\u0428\u0430\u0440\u049b\u0438 \u0441\u0443\u0440\u0445\xbb \u0431\u0430 \u0442\u0430\u0431\u044a \u0440\u0430\u0441\u0438\u0434\u0430\u0430\u043d\u0434. \u0410\u0432\u0432\u0430\xad\n\u043b\u0438\u043d \u043c\u0430\u04b7\u043c\u04ef\u0430\u0438 \u0448\u043e\u0438\u0440 \u0431\u0430 \u043d\u043e\u043c\u0438 \xab\u0428\u0430\u0440\u043e\u0440\u0430\xbb \u0441\u043e\u043b\u0438 1960 \u0447\u043e\u043f \u0433\u0430\u0440\u0434\u0438\u0434.")
B.agX=new A.a("7cec8ee4-f65e-4832-8e75-120f91a1aad3","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0411\u0430\u044a\u0434\u04b3\u043e \xab\u0421\u0438\u0442\u043e\u0440\u0430\u04b3\u043e\u0438 \u0437\u0430\u043c\u0438\u043d\xbb (1963...","\u0411\u0430\u044a\u0434\u04b3\u043e \xab\u0421\u0438\u0442\u043e\u0440\u0430\u04b3\u043e\u0438 \u0437\u0430\u043c\u0438\u043d\xbb (1963), \xab\u041c\u0430\u0432\u04b7\u04b3\u043e\u0438 \u0414\u043d\u0435\u043f\u0440\xbb (1964),\n\xab\u0414\u043e\u0441\u0442\u043e\u043d\u0438 \u043e\u0442\u0430\u0448\xbb (1967), \xab\u041a\u043e\u0440\u0432\u043e\u043d\u0438 \u043d\u0443\u0440\xbb (1970), \xab\u0421\u0443\u0440\u04ef\u0448\u0438 \u0421\u0442\u0430\xad\n\u043b\u0438\u043d\u0433\u0440\u0430\u0434\xbb (1972, 2010), \xab\u0421\u0430\u0440\u04b7\u04ef\u0439\u0438 \u0441\u0430\u0431\u0437\xbb (1975), \xab\u041f\u0430\u0434\u0430\u0440\xbb (1977),\n\xab\u0413\u0430\u04b3\u0432\u043e\u0440\u0430\u0438 \u0421\u0438\u043d\u043e\xbb (1980), \xab\u0421\u0438\u0442\u043e\u0440\u0430\u0438 \u0418\u0441\u043c\u0430\u0442\xbb (1990), \xab\u0410\u0437 \u0411\u0435\u0441\u0443\u0442\u0443\u043d\n\u0442\u043e \u043a\u0443\u043d\u0443\u043d\xbb (1993), \xab\u04b2\u0430\u043c\u043e\u0441\u0430\u0438 \u0434\u043e\u0434\xbb (2002), \xab\u041e\u0438\u043d\u0430\u0438 \u0431\u0435\u0493\u0443\u0431\u043e\u0440\u0438 \u043c\u0430\u043d\xbb\n(2002), \xab\u041c\u0435\u04b3\u0440\u0438 \u0441\u0438\u043f\u0435\u04b3\u0440\xbb (2007) \u043d\u043e\u043c \u043c\u0430\u04b7\u043c\u04ef\u0430\u04b3\u043e \u0432\u0430 \u0434\u043e\u0441\u0442\u043e\u043d\u04b3\u043e\u0438 \u041c. \u049a\u0430\xad\n\u043d\u043e\u0430\u0442 \u043f\u0430\u0439\u0434\u0430\u0440\u043f\u0430\u0439 \u0431\u0430 \u0442\u0430\u0431\u044a \u0440\u0430\u0441\u0438\u0434\u0430\u0430\u043d\u0434.")
B.asn=new A.a("476f624c-686a-4e29-99a7-ff92621b0cb7","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u041c. \u049a\u0430\u043d\u043e\u0430\u0442 \u0441\u0438\u043b\u0441\u0438\u043b\u0430\u0438 \u0448\u0435\u044a\u0440\u04b3\u043e \u043d\u0438\u0437 ...","\u041c. \u049a\u0430\u043d\u043e\u0430\u0442 \u0441\u0438\u043b\u0441\u0438\u043b\u0430\u0438 \u0448\u0435\u044a\u0440\u04b3\u043e \u043d\u0438\u0437 \u044d\u04b7\u043e\u0434 \u043a\u0430\u0440\u0434\u0430\u0430\u0441\u0442. \u0421\u0438\u043b\u0441\u0438\xad\n\u043b\u0430\u0438 \u0448\u0435\u044a\u0440\u04b3\u043e\u0438 \xab\u0421\u043e\u0437\u04b3\u043e\u0438 \u0428\u0435\u0440\u043e\u0437\xbb \u0430\u0437 \u0448\u0435\u044a\u0440\u04b3\u043e\u0438 \xab\u0422\u0430\u0445\u0442\u0438 \u04b6\u0430\u043c\u0448\u0435\u0434\xbb,\n\xab\u0417\u043e\u0438\u043d\u0434\u0430\u0440\u04ef\u0434\xbb, \xab\u0421\u0430\u04b3\u0430\u0440 \u0430\u0437 \u0445\u0438\u043b\u0432\u0430\u0442\u0438 \u0445\u0443\u0434\xbb, \xab\u0427\u04e3 \u043c\u0430\u0441\u0442 \u043c\u0435\u0433\u0443\u0437\u0430\u0440\u04e3\xbb, \xab\u041c\u0430\u0440\u043e\n\u0433\u0443\u0444\u0442\u04e3\xbb, \xab\u041d\u0430\u0434\u043e\u043d\u0430\u043c\xbb \u0444\u0430\u0440\u043e\u04b3\u0430\u043c \u043e\u043c\u0430\u0434\u0430\u0430\u0441\u0442. \u0421\u0438\u043b\u0441\u0438\u043b\u0430\u0438 \u0448\u0435\u044a\u0440\u04b3\u043e\u0438 \u041f\u043e\u043a\u0438\u0441\xad\n\u0442\u043e\u043d \u0430\u0437 \u0441\u0435 \u0448\u0435\u044a\u0440 (\xab\u0425\u0438\u0451\u0431\u043e\u043d\u0438 \u0418\u049b\u0431\u043e\u043b\xbb, \xab\u0421\u0430\u0444\u0430\u0440 \u0431\u0430 \u041c\u0430\u04b3\u0438\u043d\u04b7\u0430\u0434\u0430\u0440\u0430\xbb,\n\xab\u041c\u0435\u0440\u0430\u0432\u0430\u043c\xbb) \u0432\u0430 \u0441\u0438\u043b\u0441\u0438\u043b\u0430\u0438 \u0448\u0435\u044a\u0440\u04b3\u043e\u0438 \u0410\u0444\u0493\u043e\u043d\u0438\u0441\u0442\u043e\u043d \u0430\u0437 \u0447\u043e\u0440 \u0448\u0435\u044a\u0440\n(\xab\u0418\u043d\u049b\u0438\u043b\u043e\u0431\u0438 \u0421\u0430\u0432\u0440\xbb, \xab\u0420\u04ef\u0437\u0433\u043e\u0440\u043e\u043d\u0438 \u0431\u0430\u043b\u0430\u043d\u0434\xbb, \xab\u0421\u0443\u0431\u04b3\u0438 \u043c\u0443\u0440\u043e\u0434\xbb, \xab\u0421\u0430\u0440\xad\n\u0432\u0430\u0440\u0435\xbb) \u0438\u0431\u043e\u0440\u0430\u0442 \u043c\u0435\u0431\u043e\u0448\u0430\u043d\u0434. \u0421\u043e\u043b\u0438 2005 \u0434\u0430\u0440 \u0440\u04ef\u0437\u043d\u043e\u043c\u0430\u0438 \xab\u0410\u0434\u0430\u0431\u0438\u0451\u0442 \u0432\u0430\n\u0441\u0430\u043d\u044a\u0430\u0442\xbb \u0441\u0438\u043b\u0441\u0438\u043b\u0430\u0438 \u0440\u0443\u0431\u043e\u0438\u0451\u0442\u0438 \u0430\u0434\u0438\u0431 \u0431\u043e \u043d\u043e\u043c\u0438 \xab\u0420\u043e\u04b3\u0438 \u0430\u0431\u0440\u0435\u0448\u0438\u043c\xbb \u0447\u043e\u043f\n\u0433\u0430\u0440\u0434\u0438\u0434, \u043a\u0438 \u0434\u0430\u0440 \u043e\u043d \u043c\u0430\u0441\u044a\u0430\u043b\u0430\u0438 \u0440\u043e\u04b3\u0441\u043e\u0437\u0438\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u043c\u0430\u0432\u0440\u0438\u0434\u0438 \u0442\u0430\u0441\u0432\u0438\xad\n\u0440\u0438 \u0431\u0430\u0434\u0435\u04e3 \u049b\u0430\u0440\u043e\u0440 \u0433\u0438\u0440\u0438\u0444\u0442\u0430\u0430\u0441\u0442:")
B.a8W=new A.a("759ec51e-511c-4a62-9953-d25f9bb7d3b8","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u041c\u043e\u0435\u043c \u043d\u0438\u04b3\u043e\u0434\u0430 \u0441\u0438\u043d\u0430 \u0431\u0430\u0440 \u0441\u0438\u043d\u0430\u0438 \u0441\u0430\u043d...","\u041c\u043e\u0435\u043c \u043d\u0438\u04b3\u043e\u0434\u0430 \u0441\u0438\u043d\u0430 \u0431\u0430\u0440 \u0441\u0438\u043d\u0430\u0438 \u0441\u0430\u043d\u0433,\n\u04b6\u04ef\u0435\u043c \u0442\u0430\u04b7\u0430\u043b\u043b\u0438\u0435 \u0437\u0438 \u043e\u0438\u043d\u0430\u0438 \u0441\u0430\u043d\u0433.\n\u041c\u043e \u0441\u0430\u043d\u0433 \u0448\u0443\u0434\u0435\u043c\u0443 \u0441\u0430\u043d\u0433\u0438 \u043c\u043e \u043e\u0431 \u043d\u0430\u0448\u0443\u0434,\n\u0410\u0437 \u043c\u0435\u04b3\u0440\u0438 \u0433\u0438\u044f\u04b3 \u0430\u043c\u043e\u043d\u0443 \u0430\u0437 \u043a\u0438\u043d\u0430\u0438 \u0441\u0430\u043d\u0433.")
B.a8M=new A.a("26b51a30-6e2d-4e59-b5b6-05373da94e01","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0421\u043e\u043b\u0438 1977 \u0448\u043e\u0438\u0440 \u0431\u0430\u0440\u043e\u0438 \u0434\u043e\u0441\u0442\u043e\u043d\u04b3\u043e\u0438...","\u0421\u043e\u043b\u0438 1977 \u0448\u043e\u0438\u0440 \u0431\u0430\u0440\u043e\u0438 \u0434\u043e\u0441\u0442\u043e\u043d\u04b3\u043e\u0438 \xab\u0421\u0443\u0440\u04ef\u0448\u0438 \u0421\u0442\u0430\u043b\u0438\u043d\u0433\u0440\u0430\u0434\xbb \u0432\u0430\n\xab\u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u2013 \u0438\u0441\u043c\u0438 \u043c\u0430\u043d\xbb \u0441\u0430\u0437\u043e\u0432\u043e\u0440\u0438 \u04b6\u043e\u0438\u0437\u0430\u0438 \u0434\u0430\u0432\u043b\u0430\u0442\u0438\u0438 \u0418\u0442\u0442\u0438\u04b3\u043e\u0434\u0438\n\u0428\u04ef\u0440\u0430\u0432\u04e3 \u0433\u0430\u0440\u0434\u0438\u0434. \u0421\u043e\u043b\u0438 1980 \u041c. \u049a\u0430\u043d\u043e\u0430\u0442 \u0431\u0430\u0440\u043e\u0438 \u0434\u043e\u0441\u0442\u043e\u043d\u0438 \xab\u0413\u0430\u04b3\u0432\u043e\u0440\u0430\u0438\n\u0421\u0438\u043d\u043e\xbb \u0431\u043e \u041c\u0443\u043a\u043e\u0444\u043e\u0442\u0438 \u04b7\u0443\u043c\u04b3\u0443\u0440\u0438\u044f\u0432\u0438\u0438 \u0431\u0430 \u043d\u043e\u043c\u0438 \u0420\u04ef\u0434\u0430\u043a\u04e3 \u049b\u0430\u0434\u0440 \u043a\u0430\u0440\u0434\u0430\n\u0448\u0443\u0434.")
B.ahX=new A.a("1c2915cd-90d4-4727-bf85-2971847dcec6","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0421\u043e\u043b\u0438 1982 \xab\u041e\u0441\u043e\u0440\u0438 \u043c\u0443\u043d\u0442\u0430\u0445\u0430\u0431\xbb-\u0438 \u041c...","\u0421\u043e\u043b\u0438 1982 \xab\u041e\u0441\u043e\u0440\u0438 \u043c\u0443\u043d\u0442\u0430\u0445\u0430\u0431\xbb-\u0438 \u041c. \u049a\u0430\u043d\u043e\u0430\u0442 \u0434\u0430\u0440 \u0434\u0443 \u04b7\u0438\u043b\u0434 \u0434\u0430\u0441\u0442\u0440\u0430\xad\n\u0441\u0438 \u0445\u043e\u043d\u0430\u043d\u0434\u0430 \u0433\u0430\u0440\u0434\u0438\u0434, \u043a\u0438 \u043e\u043d \u0448\u0435\u044a\u0440\u04b3\u043e \u0432\u0430 \u0442\u0430\u0440\u04b7\u0443\u043c\u0430\u04b3\u043e\u0438 \u0448\u043e\u0438\u0440\u0440\u043e \u0434\u0430\u0440 \u0431\u0430\u0440")
B.aoS=new A.a("49a51db8-c30f-4fed-a5fc-57321fd4abf7","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u043a\u0430\u0440\u0434\u0430\u0430\u0441\u0442. \u0424\u0430\u044a\u043e\u043b\u0438\u044f\u0442\u0438 \u0442\u0430\u0440\u04b7\u0443\u043c\u043e\u043d\u0438\u0438...","\u043a\u0430\u0440\u0434\u0430\u0430\u0441\u0442. \u0424\u0430\u044a\u043e\u043b\u0438\u044f\u0442\u0438 \u0442\u0430\u0440\u04b7\u0443\u043c\u043e\u043d\u0438\u0438 \u0430\u0434\u0438\u0431 \u0430\u0437 \u0434\u0430\u0432\u0440\u0430\u0438 \u0430\u0432\u0432\u0430\u043b\u0438 \u044d\u04b7\u043e\u0434\u0438\u0451\u0442\u0438\n\u04ef \u043e\u0493\u043e\u0437 \u0433\u0430\u0440\u0434\u0438\u0434\u0430, \u043c\u0443\u043d\u0442\u0430\u0437\u0430\u043c \u0434\u0430\u0432\u043e\u043c \u043c\u0435\u0451\u0431\u0430\u0434. \u0425\u043e\u043d\u0430\u043d\u0434\u0430\u0438 \u0442\u043e\u04b7\u0438\u043a \u044f\u043a \u049b\u0430\u0442\u043e\u0440\n\u0430\u0441\u0430\u0440\u04b3\u043e\u0438 \u0410. \u0421. \u041f\u0443\u0448\u043a\u0438\u043d, \u0412\u0438\u043b\u044f\u043c \u0428\u0435\u043a\u0441\u043f\u0438\u0440, \u0424\u0440\u0438\u0434\xad\u0440\u0438\u0445 \u0428\u0438\u043b\u043b\u0435\u0440, \u0413\u0435\u043d\xad\n\u0440\u0438\u0445 \u0413\u0435\u0439\u043d\u0435, \u0410\u0434\u0430\u043c \u041c\u0438\u0442\u0441\u043a\u0435\u0432\u0438\u0447, \u0420\u043e\u0431\u0438\u043d\u0434\u0440\u043e\u043d\u0430\u0442 \u0422\u0430\u043a\u0443\u0440, \u041c\u04ef\u0441\u043e \u04b6\u0430\u043b\u0438\u043b\n\u0431\u0430\u0440\u0438\u043d \u0430\u0434\u0438\u0431\u043e\u043d\u0438 \u0448\u0438\u043d\u043e\u0445\u0442\u0430\u0438 \u04b7\u0430\u04b3\u043e\u043d\u0438\u0440\u043e \u0434\u0430\u0440 \u0442\u0430\u0440\u04b7\u0443\u043c\u0430\u0438 \u041c. \u049a\u0430\u043d\u043e\u0430\u0442 \u043c\u0443\xad\n\u0442\u043e\u043b\u0438\u0430 \u043a\u0430\u0440\u0434\u0430\u0430\u0441\u0442. \u0422\u0430\u0440\u04b7\u0443\u043c\u0430\u04b3\u043e\u0438 \u0448\u043e\u0438\u0440 \u04b3\u0443\u043d\u0430\u0440\u043c\u0430\u043d\u0434\u043e\u043d\u0430 \u0431\u0443\u0434\u0430, \u0434\u0430\u0440 \u043e\u043d\u04b3\u043e\n\u0445\u0443\u0441\u0443\u0441\u0438\u044f\u0442 \u0432\u0430 \u0442\u0430\u0431\u0438\u0430\u0442\u0438 \u0448\u0435\u044a\u0440\u0443 \u0437\u0430\u0431\u043e\u043d\u0438 \u0442\u043e\u04b7\u0438\u043a\u04e3 \u043d\u0438\u0433\u043e\u04b3 \u0434\u043e\u0448\u0442\u0430 \u0448\u0443\u0434\u0430\u0430\u0441\u0442.\n\u0427\u0430\u043d\u0434 \u043c\u0438\u0441\u0440\u0430\u044a \u0430\u0437 \xab\u0413\u0430\u0440\u0434\u0438 \u0445\u043e\u043a\xbb \u043d\u043e\u043c \u0448\u0435\u044a\u0440\u0438 \u0448\u043e\u0438\u0440\u0438 \u0431\u0430\u0440\u04b7\u0430\u0441\u0442\u0430\u0438 \u04b3\u0438\u043d\u0434\n\u0420\u043e\u0431\u0438\u043d\u0434\u0440\u043e\u043d\u0430\u0442 \u0422\u0430\u043a\u0443\u0440 \u0434\u0430\u0440 \u0442\u0430\u0440\u04b7\u0443\u043c\u0430\u0438 \u041c. \u049a\u0430\u043d\u043e\u0430\u0442:")
B.ah5=new A.a("3c9c745e-2552-4eac-a478-b4f8786b5528","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u04b2\u0430\u043c \u0440\u04ef\u0439\u0438 \u0437\u0430\u043c\u0438\u043d\u0443 \u04b3\u0430\u043c \u0434\u0438\u043b\u0438 \u043a\u04ef\u04b3 \u0437...","\u04b2\u0430\u043c \u0440\u04ef\u0439\u0438 \u0437\u0430\u043c\u0438\u043d\u0443 \u04b3\u0430\u043c \u0434\u0438\u043b\u0438 \u043a\u04ef\u04b3 \u0437\u0435\u0431\u043e\u0441\u0442,\n\u04b2\u0430\u043c \u0445\u043e\u043a\u0438 \u0441\u0438\u044f\u04b3, \u043a\u0438 \u0434\u043e\u044f\u0438 \u043d\u0435\u044a\u043c\u0430\u0442\u04b3\u043e\u0441\u0442.\n\u0417-\u043e\u043d \u043f\u0435\u0448, \u043a\u0438 \u043e\u0442\u0430\u0448\u0430\u043c \u043c\u0438\u0440\u0430\u0434, \u0441\u0430\u0440\u0434 \u0448\u0430\u0432\u0430\u043c,\n\u0414\u0430\u0440 \u043d\u0430\u0437\u0434\u0438 \u0493\u0443\u0431\u043e\u0440\u0438 \u0438\u043d \u0437\u0430\u043c\u0438\u043d \u0433\u0430\u0440\u0434 \u0448\u0430\u0432\u0430\u043c...")
B.alm=new A.a("cf9a02ed-ce03-4f68-a8e1-7f5e5be03848","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0428\u043e\u0434\u0430\u043c, \u043a\u0438 \u0430\u0437 \u0438\u043d \u04b3\u0430\u0451\u0442\u0438 \u0431\u0438\u0433\u0437\u0430\u0448\u0442\u0430...","\u0428\u043e\u0434\u0430\u043c, \u043a\u0438 \u0430\u0437 \u0438\u043d \u04b3\u0430\u0451\u0442\u0438 \u0431\u0438\u0433\u0437\u0430\u0448\u0442\u0430\u0438 \u043c\u0430\u043d\n\u042f\u043a \u04b7\u0430\u0432\u04b3\u0430\u0440\u0438 \u0430\u0441\u043b \u04b7\u043e\u0432\u0438\u0434\u043e\u043d \u043c\u0435\u043c\u043e\u043d\u0430\u0434.\n\u041c\u0430\u043d \u04b7\u0438\u043d\u0441\u0438 \u0430\u0431\u0430\u0434\u0438\u044f\u0442 \u0448\u0430\u0432\u0430\u043c, \u0445\u043e\u043a \u0448\u0430\u0432\u0430\u043c,\n\u042f\u043a \u0433\u0430\u0440\u0434\u0438 \u0437\u0430\u043c\u0438\u043d\u0438 \u04b7\u043e\u0432\u0438\u0434\u0438 \u043f\u043e\u043a \u0448\u0430\u0432\u0430\u043c.")
B.abc=new A.a("1f0f8895-d6fc-44b3-9b39-7b01727b9597","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0410\u043a\u0441\u0430\u0440\u0438 \u0448\u0435\u044a\u0440\u04b3\u043e \u0432\u0430 \u0434\u043e\u0441\u0442\u043e\u043d\u04b3\u043e\u0438 \u041c. ...","\u0410\u043a\u0441\u0430\u0440\u0438 \u0448\u0435\u044a\u0440\u04b3\u043e \u0432\u0430 \u0434\u043e\u0441\u0442\u043e\u043d\u04b3\u043e\u0438 \u041c. \u049a\u0430\u043d\u043e\u0430\u0442 \u0431\u0430 \u0437\u0430\u0431\u043e\u043d\u0438 \u0440\u0443\u0441\u04e3\n\u0442\u0430\u0440\u04b7\u0443\u043c\u0430 \u0448\u0443\u0434\u0430, \u0434\u0430\u0440 \u043d\u0430\u0448\u0440\u0438\u044f\u04b3\u043e\u0438 \u041c\u0430\u0441\u043a\u0430\u0432 \u0431\u0430 \u0442\u0430\u0431\u044a \u0440\u0430\u0441\u0438\u0434\u0430\u0430\u043d\u0434.\n\u04b2\u0430\u043c\u0447\u0443\u043d\u0438\u043d, \u043d\u0430\u043c\u0443\u043d\u0430\u0438 \u0430\u0448\u044a\u043e\u0440\u0438 \u0448\u043e\u0438\u0440 \u0431\u0430 \u044f\u043a \u049b\u0430\u0442\u043e\u0440 \u0437\u0430\u0431\u043e\u043d\u04b3\u043e\u0438 \u0431\u043e\u043d\u0443\u0444\u0443\u0437\u0438\n\u04b7\u0430\u04b3\u043e\u043d, \u0430\u0437 \u04b7\u0443\u043c\u043b\u0430 \u0431\u0430 \u0437\u0430\u0431\u043e\u043d\u04b3\u043e\u0438 \u0430\u043d\u0433\u043b\u0438\u0441\u04e3, \u0444\u0430\u0440\u043e\u043d\u0441\u0430\u0432\u04e3, \u0438\u0441\u043f\u0430\u043d\u04e3, \u0430\u0440\u0430\u0431\u04e3\n\u0442\u0430\u0440\u04b7\u0443\u043c\u0430 \u0448\u0443\u0434\u0430\u0430\u043d\u0434. \u049a\u0438\u0441\u043c\u0430\u0442\u0435 \u0430\u0437 \u0430\u0448\u044a\u043e\u0440\u0438 \u0448\u043e\u0438\u0440 \u0434\u0430\u0440 \u0441\u0430\u04b3\u0438\u0444\u0430\u04b3\u043e\u0438 \u043c\u0430\u0442\xad\n\u0431\u0443\u043e\u0442\u0438 \u04b7\u0443\u043c\u04b3\u0443\u0440\u0438\u04b3\u043e\u0438 \u0438\u0441\u043b\u043e\u043c\u0438\u0438 \u042d\u0440\u043e\u043d \u0432\u0430 \u0410\u0444\u0493\u043e\u043d\u0438\u0441\u0442\u043e\u043d \u0447\u043e\u043f \u0433\u0430\u0440\u0434\u0438\u0434\u0430\u0430\u043d\u0434.\n\u0421\u043e\u043b\u0438 1994 \u043d\u0430\u0448\u0440\u0438\u0451\u0442\u0438 \xab\u0410\u043b\u04b3\u0443\u0434\u043e\xbb-\u0438 \u04b6\u0443\u043c\u04b3\u0443\u0440\u0438\u0438 \u0438\u0441\u043b\u043e\u043c\u0438\u0438 \u042d\u0440\u043e\u043d \u0431\u0430\u0440\u0433\u0443\xad\n\u0437\u0438\u0434\u0430\u0438 \u0430\u0448\u044a\u043e\u0440\u0438 \u041c. \u049a\u0430\u043d\u043e\u0430\u0442\u0440\u043e \u043f\u0435\u0448\u043a\u0430\u0448\u0438 \u0445\u043e\u043d\u0430\u043d\u0434\u0430\u0438 \u0444\u043e\u0440\u0441\u0438\u0437\u0430\u0431\u043e\u043d \u043d\u0430\xad\n\u043c\u0443\u0434.")
B.akp=new A.a("7d1af671-16eb-428b-ad04-bea8ae61ca54","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u04b2\u0430\u043c\u0447\u0443\u043d\u0438\u043d, \u041c\u0443\u044a\u043c\u0438\u043d \u049a\u0430\u043d\u043e\u0430\u0442 \u043e\u0438\u0434 \u0431\u0430...","\u04b2\u0430\u043c\u0447\u0443\u043d\u0438\u043d, \u041c\u0443\u044a\u043c\u0438\u043d \u049a\u0430\u043d\u043e\u0430\u0442 \u043e\u0438\u0434 \u0431\u0430 \u043c\u0430\u0441\u044a\u0430\u043b\u0430\u04b3\u043e\u0438 \u0433\u0443\u043d\u043e\u0433\u0443\u043d\u0438\n\u0430\u0434\u0430\u0431\u04e3 \u043c\u0430\u049b\u043e\u043b\u0430\u0432\u0443 \u0442\u0430\u049b\u0440\u0438\u0437\u04b3\u043e \u043d\u0430\u0432\u0438\u0448\u0442\u0430, \u0434\u0430\u0440 \u04b7\u0430\u043c\u044a\u043e\u043c\u0430\u0434\u04b3\u043e\u0438 \u0431\u043e\u043d\u0443\u0444\u0443\u0437\u0438\n\u0444\u0430\u0440\u04b3\u0430\u043d\u0433\u04e3 \u0441\u0443\u0445\u0430\u043d\u0440\u043e\u043d\u0438\u04b3\u043e\u0438 \u043f\u0443\u0440\u043c\u0443\u04b3\u0442\u0430\u0432\u043e \u043d\u0430\u043c\u0443\u0434\u0430\u0430\u0441\u0442. \u0410\u043b\u04b3\u043e\u043b \u0437\u0438\u0451\u0434\u0430 \u0430\u0437\n\u043f\u0430\u043d\u04b7\u043e\u04b3 \u043c\u0430\u049b\u043e\u043b\u0430\u0438 \u0438\u043b\u043c\u04e3 \u0432\u0430 \u043f\u0443\u0431\u043b\u0438\u0442\u0441\u0438\u0441\u0442\u0438\u0438 \u0430\u0434\u0438\u0431 \u0431\u0430 \u0442\u0430\u0431\u044a \u0440\u0430\u0441\u0438\u0434\u0430\u0430\u043d\u0434.")
