B.ahf=new A.a("697ba6de-1d60-440f-ab3f-f8bcec9ccef8","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0410\u0439\u0451\u043c\u0438 \u0442\u0438\u0444\u043b\u04e3 \u0432\u0430 \u0431\u0430\u0447\u0430\u0433\u0438\u0438 \u041b\u043e\u0438\u049b \u0431\u0430...","\u0410\u0439\u0451\u043c\u0438 \u0442\u0438\u0444\u043b\u04e3 \u0432\u0430 \u0431\u0430\u0447\u0430\u0433\u0438\u0438 \u041b\u043e\u0438\u049b \u0431\u0430 \u0440\u04ef\u0437\u04b3\u043e\u0438 \u0434\u0443\u0448\u0432\u043e\u0440\u0438 \u04b6\u0430\u043d\u0433\u0438 \u0411\u0443\xad\n\u0437\u0443\u0440\u0433\u0438 \u0412\u0430\u0442\u0430\u043d\u04e3 \u0432\u0430 \u0431\u0430\u044a\u0434\u0438\u04b7\u0430\u043d\u0433\u04e3 \u0440\u043e\u0441\u0442 \u043e\u043c\u0430\u0434. \u0422\u0430\u04b3\u0441\u0438\u043b\u0438 \u0438\u0431\u0442\u0438\u0434\u043e\u0438\u0438 \u041b\u043e\u0438\u049b\n\u0434\u0430\u0440 \u0437\u043e\u0434\u0433\u043e\u04b3\u0430\u0448 \u0433\u0443\u0437\u0430\u0448\u0442\u0430\u0430\u0441\u0442. \u0421\u043e\u043b\u0438 1954 \u043c\u0430\u043a\u0442\u0430\u0431\u0438 \u04b3\u0430\u0444\u0442\u0441\u043e\u043b\u0430\u0438 \u0434\u0435\u04b3\u0430\u0438\n\u041c\u0430\u0437\u043e\u0440\u0438 \u0428\u0430\u0440\u0438\u0444 \u0432\u0430 \u0441\u043e\u043b\u0438 1958 \u041e\u043c\u04ef\u0437\u0438\u0448\u0433\u043e\u04b3\u0438 \u043e\u043c\u04ef\u0437\u0433\u043e\u0440\u0438\u0440\u043e \u0431\u0430 \u0438\u0442\xad\n\u043c\u043e\u043c \u043c\u0435\u0440\u0430\u0441\u043e\u043d\u0430\u0434. \u0421\u043e\u043b\u0438 1959 \u0431\u0430 \u0414\u043e\u043d\u0438\u0448\u0433\u043e\u04b3\u0438 \u0434\u0430\u0432\u043b\u0430\u0442\u0438\u0438 \u043e\u043c\u04ef\u0437\u0433\u043e\u0440\u0438\u0438\n\u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u0448\u043e\u043c\u0438\u043b \u043c\u0435\u0448\u0430\u0432\u0430\u0434.")
B.aaE=new A.a("5b654265-2f26-4576-bc41-e3802428e601","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0411\u0430\u044a\u0434\u0438 \u0445\u0430\u0442\u043c\u0438 \u0434\u043e\u043d\u0438\u0448\u0433\u043e\u04b3 \u041b\u043e\u0438\u049b \u0434\u0430\u0440 ...","\u0411\u0430\u044a\u0434\u0438 \u0445\u0430\u0442\u043c\u0438 \u0434\u043e\u043d\u0438\u0448\u0433\u043e\u04b3 \u041b\u043e\u0438\u049b \u0434\u0430\u0440 \u0432\u0430\u0437\u0438\u0444\u0430\u04b3\u043e\u0438 \u0433\u0443\u043d\u043e\u0433\u0443\u043d \u2013\n\u043c\u0443\u04b3\u0430\u0440\u0440\u0438\u0440\u0438 \u0448\u0443\u044a\u0431\u0430\u0438 \u0430\u0434\u0430\u0431\u0438\u0438 \u0440\u0430\u0434\u0438\u043e, \u043a\u043e\u0440\u043c\u0430\u043d\u0434\u0438 \u0430\u0434\u0430\u0431\u0438\u0438 \u0440\u04ef\u0437\u043d\u043e\u043c\u0430\u0438\n\xab\u041a\u043e\u043c\u0441\u043e\u043c\u043e\u043b\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d\xbb (\u04b3\u043e\u043b\u043e \xab\u04b6\u0430\u0432\u043e\u043d\u043e\u043d\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d\xbb), \u043c\u0443\xad\n\u0434\u0438\u0440\u0438 \u0448\u0443\u044a\u0431\u0430\u0438 \u043d\u0430\u0437\u043c \u0432\u0430 \u0441\u0430\u0440\u043c\u0443\u04b3\u0430\u0440\u0440\u0438\u0440\u0438 \u043c\u0430\u04b7\u0430\u043b\u043b\u0430\u0438 \xab\u0421\u0430\u0434\u043e\u0438 \u0428\u0430\u0440\u049b\xbb,\n\u043c\u0443\u0448\u043e\u0432\u0438\u0440\u0438 \u0418\u0442\u0442\u0438\u0444\u043e\u049b\u0438 \u043d\u0430\u0432\u0438\u0441\u0430\u043d\u0434\u0430\u0433\u043e\u043d\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u0444\u0430\u044a\u043e\u043b\u0438\u044f\u0442 \u043c\u0435\u043a\u0443\xad\n\u043d\u0430\u0434. \u0428\u043e\u0438\u0440 \u0430\u0437 \u0441\u043e\u043b\u0438 1991 \u0442\u043e \u043e\u0445\u0438\u0440\u0438 \u0443\u043c\u0440 \u0440\u0430\u0438\u0441\u0438 \u0411\u0443\u043d\u0451\u0434\u0438 \u0431\u0430\u0439\u043d\u0430\u043b\u043c\u0438\u043b\u0430\xad\n\u043b\u0438\u0438 \u0437\u0430\u0431\u043e\u043d\u0438 \u0444\u043e\u0440\u0441\u0438\u0438 \u0442\u043e\u04b7\u0438\u043a\u04e3 \u0431\u0443\u0434.")
B.ajf=new A.a("3449b691-4f46-4c31-80f9-544d0edd1ff9","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u041e\u0432\u043e\u0437\u0430\u0438 \u04b3\u0443\u043d\u0430\u0440\u0438 \u041b\u043e\u0438\u049b \u0437\u0443\u0434 \u0431\u0430 \u04b3\u0430\u0432\u0437...","\u041e\u0432\u043e\u0437\u0430\u0438 \u04b3\u0443\u043d\u0430\u0440\u0438 \u041b\u043e\u0438\u049b \u0437\u0443\u0434 \u0431\u0430 \u04b3\u0430\u0432\u0437\u0430\u04b3\u043e\u0438 \u0430\u0434\u0430\u0431\u0438\u0438 \u0444\u043e\u0440\u0441\u0438\u0437\u0430\u0431\u043e\u043d\u043e\u043d\n\u0440\u0430\u0441\u0438\u0434 \u0432\u0430 \u0434\u0430\u0440 \u0448\u0430\u0445\u0441\u0438 \u041d\u043e\u0434\u0438\u0440\u0438 \u041d\u043e\u0434\u0438\u0440\u043f\u0443\u0440, \u0410\u04b3\u043c\u0430\u0434\u0438 \u0428\u043e\u043c\u043b\u0443, \u0411\u043e\u0440\u0438\u049b\n\u0428\u0430\u0444\u0435\u04e3, \u0410\u043b\u0438\u0430\u0441\u0493\u0430\u0440\u0438 \u0428\u0435\u044a\u0440\u0434\u04ef\u0441\u0442, \u041d\u0443\u0441\u0440\u0430\u0442 \u0420\u0430\u04b3\u043c\u043e\u043d\u04e3 \u0431\u0430\u0440\u0438\u043d \u0441\u0443\u0445\u0430\u043d\u0432\u0430\xad\n\u0440\u043e\u043d\u0438 \u044d\u0440\u043e\u043d\u04e3 \u0432\u0430 \u0430\u0444\u0493\u043e\u043d\u04e3 \u0434\u04ef\u0441\u0442\u043e\u043d \u0432\u0430 \u043c\u0443\u0445\u043b\u0438\u0441\u043e\u043d\u0438 \u0437\u0438\u0451\u0434\u0435 \u043f\u0430\u0439\u0434\u043e \u043d\u0430\u043c\u0443\u0434.\n\u0412\u0430\u0437\u044a\u0438 \u043d\u043e\u0431\u0430\u0441\u043e\u043c\u043e\u043d\u0438 \u0438\u0431\u0442\u0438\u0434\u043e\u0438 \u0441\u043e\u043b\u04b3\u043e\u0438 90-\u0443\u043c\u0438 \u0430\u0441\u0440\u0438 \u0425\u0425 \u0434\u0430\u0440 \u0437\u0438\u043d\u0434\u0430\u0433\u0438\u0438\n\u0443\u0441\u0442\u043e\u0434 \u041b\u043e\u0438\u049b \u043d\u0438\u0437 \u0434\u0443\u0448\u0432\u043e\u0440\u0438\u04b3\u043e \u043e\u0432\u0430\u0440\u0434. 30 \u0438\u044e\u043d\u0438 \u0441\u043e\u043b\u0438 2000- \u0443\u043c \u0443\u0441\u0442\u043e\u0434\n\u041b\u043e\u0438\u049b \u0428\u0435\u0440\u0430\u043b\u04e3 \u0431\u0430\u0440 \u0430\u0441\u0430\u0440\u0438 \u0431\u0435\u043c\u043e\u0440\u0438\u0438 \u0441\u0430\u043a\u0442\u0430\u0438 \u0434\u0438\u043b \u04b7\u0430\u04b3\u043e\u043d\u0440\u043e \u043f\u0430\u0434\u0440\u0443\u0434 \u0433\u0443\u0444\u0442.\n\u041e\u0440\u043e\u043c\u0433\u043e\u04b3\u0438 \u0448\u043e\u0438\u0440 \u0434\u0430\u0440 \u043c\u0430\u0437\u043e\u0440\u0438 \u041b\u0443\u0447\u043e\u0431\u0438 \u0448\u0430\u04b3\u0440\u0438 \u0414\u0443\u0448\u0430\u043d\u0431\u0435 \u049b\u0430\u0440\u043e\u0440 \u0434\u043e\u0440\u0430\u0434.\n\u0428\u0435\u044a\u0440\u0438 \u0431\u0430\u043b\u0430\u043d\u0434\u043f\u043e\u044f\u0430\u0448 \u043d\u043e\u043c\u0438 \u0448\u043e\u0438\u0440\u0440\u043e \u0437\u0438\u043d\u0434\u0430\u0432\u0443 \u04b7\u043e\u0432\u0438\u0434 \u0433\u0430\u0440\u0434\u043e\u043d\u0434\u0430\u0430\u0441\u0442:")
B.abS=new A.a("26372cc1-ccce-4a30-b6b0-7e194ac558b2","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0411\u0430\u044a\u0434\u0438 \u043c\u0443\u0440\u0434\u0430\u043d \u04b3\u0430\u043c \u0434\u0438\u043b\u0430\u043c \u0431\u0435\u0431\u0430\u0440\u0433 ...","\u0411\u0430\u044a\u0434\u0438 \u043c\u0443\u0440\u0434\u0430\u043d \u04b3\u0430\u043c \u0434\u0438\u043b\u0430\u043c \u0431\u0435\u0431\u0430\u0440\u0433 \u043d\u0435\u0441\u0442,\n\u0418\u043d\u0442\u0438\u04b3\u043e\u0438 \u043c\u0430\u043d \u04b3\u0430\u043c\u0438\u043d \u044f\u043a \u043c\u0430\u0440\u0433 \u043d\u0435\u0441\u0442.\n\u041c\u0430\u0440\u0433 \u0430\u0433\u0430\u0440 \u049b\u0430\u0442\u044a\u0438 \u0440\u0430\u0432\u043e\u043d\u0438 \u043c\u0430\u043d \u0431\u0443\u0432\u0430\u0434,\n\u0422\u043e \u043a\u0443\u04b7\u043e \u049b\u0430\u0442\u044a\u0438 \u04b7\u0430\u04b3\u043e\u043d\u0438 \u043c\u0430\u043d \u0431\u0443\u0432\u0430\u0434!?\n\u0418\u0431\u0442\u0438\u0434\u043e\u0438 \u043c\u0430\u043d \u2013 \u0434\u0435\u04b3\u0438 \u0445\u0443\u0440\u0434\u0438 \u041c\u0430\u0437\u043e\u0440\n1\n,\n\u0418\u043d\u0442\u0438\u04b3\u043e\u0438 \u043c\u0430\u043d \u2013 \u04b7\u0430\u04b3\u043e\u043d\u0438 \u0431\u0435\u043a\u0430\u043d\u043e\u0440.")
B.amO=new A.a("7b2384ad-91da-447c-981b-ac4baccd9409","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0410\u0432\u0432\u0430\u043b\u0438\u043d \u043c\u0430\u04b7\u043c\u04ef\u0430\u0438 \u0430\u0448\u044a\u043e\u0440\u0438 \u041b\u043e\u0438\u049b \xab\u0421...","\u0410\u0432\u0432\u0430\u043b\u0438\u043d \u043c\u0430\u04b7\u043c\u04ef\u0430\u0438 \u0430\u0448\u044a\u043e\u0440\u0438 \u041b\u043e\u0438\u049b \xab\u0421\u0430\u0440\u0438\n\u0441\u0430\u0431\u0437\xbb \u0443\u043d\u0432\u043e\u043d \u0434\u043e\u0448\u0442\u0430, \u0441\u043e\u043b\u0438 1966 \u0434\u0430\u0441\u0442\u0440\u0430\u0441\u0438\n\u0430\u043b\u043e\u049b\u0430\u043c\u0430\u043d\u0434\u043e\u043d \u0433\u0430\u0440\u0434\u0438\u0434. \u0411\u0430\u044a\u0434 \u0430\u0437 \u0438\u043d \u0447\u0443\u043d\u0438\u043d\n\u043a\u0438\u0442\u043e\u0431\u04b3\u043e\u0438 \u0448\u043e\u0438\u0440 \u043f\u0430\u0439\u0438 \u04b3\u0430\u043c \u0447\u043e\u043f \u043c\u0435\u0433\u0430\u0440\u0434\u0430\u043d\u0434:\n\xab\u0418\u043b\u04b3\u043e\u043c\xbb (1968), \xab\u041d\u04ef\u0448\u0431\u043e\u0434\xbb (1971), \xab\u0421\u043e\u04b3\u0438\u043b\u04b3\u043e\xbb (1972), \xab\u0425\u043e\u043a\u0438 \u0412\u0430\xad\n\u0442\u0430\u043d\xbb (1975), \xab\u0420\u0435\u0437\u0430\u0431\u043e\u0440\u043e\u043d\xbb (1976), \xab\u041c\u0430\u0440\u0434\u0438 \u0440\u043e\u04b3\xbb (1979), \xab\u0412\u0430\u0440\u0430\u049b\u0438\n\u0441\u0430\u043d\u0433\xbb (1980), \xab\u0425\u043e\u043d\u0430\u0438 \u0447\u0430\u0448\u043c\xbb (1982), \xab\u0420\u04ef\u0437\u0438 \u0441\u0430\u0444\u0435\u0434\xbb (1984), \xab\u0425\u043e\u043d\u0430\u0438\n\u0434\u0438\u043b\xbb (1986), \xab\u041e\u0444\u0442\u043e\u0431\u0431\u043e\u0440\u043e\u043d\xbb (1988), \xab\u041c\u0430\u043d\u0443 \u0434\u0430\u0440\u0451\xbb (1991), \xab\u04b6\u043e\u043c\u0438\n\u0441\u0430\u0440\u0448\u043e\u0440\xbb (1991), \xab\u0414\u0430\u0441\u0442\u0438 \u0434\u0443\u043e\u0438 \u043c\u043e\u0434\u0430\u0440\xbb (1991), \xab\u0410\u0432\u0432\u0430\u043b\u0443 \u043e\u0445\u0438\u0440\u0438 \u0438\u0448\u049b\xbb\n(1994). \xab\u0424\u0430\u0440\u0451\u0434\u0438 \u0431\u0435\u0444\u0430\u0440\u0451\u0434\u0440\u0430\u0441\xbb (1997) \u043e\u0445\u0438\u0440\u0438\u043d \u043c\u0430\u04b7\u043c\u04ef\u0430\u0438 \u0430\u0448\u044a\u043e\u0440\u0438\n\u0443\u0441\u0442\u043e\u0434 \u041b\u043e\u0438\u049b \u0430\u0441\u0442, \u043a\u0438 \u0434\u0430\u0440 \u0434\u0430\u0432\u0440\u0430\u0438 \u0434\u0430\u0440 \u049b\u0430\u0439\u0434\u0438 \u04b3\u0430\u0451\u0442 \u0431\u0443\u0434\u0430\u043d\u0438 \u0448\u043e\u0438\u0440 \u0431\u0430\n\u0442\u0430\u0431\u044a \u0440\u0430\u0441\u0438\u0434\u0430\u0430\u0441\u0442.")
B.a8r=new A.a("bdeff9a5-11ec-4e97-a194-4c5a8c69a371","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u041c\u0430\u04b7\u043c\u04ef\u0430\u0438 \xab\u0412\u0430\u0440\u0430\u049b\u0438 \u0441\u0430\u043d\u0433\xbb \u0434\u0430\u0432\u0440\u0430\u0438 \u0430...","\u041c\u0430\u04b7\u043c\u04ef\u0430\u0438 \xab\u0412\u0430\u0440\u0430\u049b\u0438 \u0441\u0430\u043d\u0433\xbb \u0434\u0430\u0432\u0440\u0430\u0438 \u0430\u0432\u0432\u0430\u043b\u0438 \u044d\u04b7\u043e\u0434\u0438\u0451\u0442\u0438 \u041b\u043e\u0438\u049b\u0440\u043e\n\u04b7\u0430\u043c\u044a\u0431\u0430\u0441\u0442 \u043c\u0435\u043d\u0430\u043c\u043e\u044f\u0434. \u0414\u0430\u0432\u0440\u0430\u0438 \u0434\u0443\u0432\u0443\u043c\u0438 \u0444\u0430\u044a\u043e\u043b\u0438\u044f\u0442\u0438 \u044d\u04b7\u043e\u0434\u0438\u0438 \u0448\u043e\u0438\u0440 \u0430\u0437\n\u043c\u0430\u04b7\u043c\u04ef\u0430\u0438 \xab\u0425\u043e\u043d\u0430\u0438 \u0447\u0430\u0448\u043c\xbb \u043e\u0493\u043e\u0437 \u0448\u0443\u0434\u0430\u0430\u0441\u0442. \xab\u0424\u0430\u0440\u0451\u0434\u0438 \u0431\u0435\u0444\u0430\u0440\u0451\u0434\u0440\u0430\u0441\xbb \u0444\u0430\xad\n\u0440\u043e\u0433\u0438\u0440\u0438 \u043c\u0430\u0440\u04b3\u0430\u043b\u0430\u0438 \u0441\u0435\u044e\u043c \u0432\u0430 \u043d\u0438\u04b3\u043e\u0438\u0438 \u044d\u04b7\u043e\u0434\u0438\u0451\u0442\u0438 \u0443\u0441\u0442\u043e\u0434 \u041b\u043e\u0438\u049b \u043c\u0435\u0431\u043e\u0448\u0430\u0434.")
B.aeO=new A.a("1686c280-40ee-4749-bfbf-eb1883bcdf40","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0411\u0430\u044a\u0434\u0438 \u0432\u0430\u0444\u043e\u0442\u0438 \u041b\u043e\u0438\u049b \u043c\u0430\u04b7\u043c\u04ef\u0430\u0438 \xab\u0410\u043d\u0433...","\u0411\u0430\u044a\u0434\u0438 \u0432\u0430\u0444\u043e\u0442\u0438 \u041b\u043e\u0438\u049b \u043c\u0430\u04b7\u043c\u04ef\u0430\u0438 \xab\u0410\u043d\u0433\u043e\u0440\u0430\u04b3\u043e\xbb (2001), \xab\u0414\u0435\u0432\u043e\u043d\u0438\n\u0434\u0438\u043b\xbb (2006), \xab\u0414\u0435\u0432\u043e\u043d\u0438 \u0437\u0430\u043c\u043e\u043d\xbb (2011), \xab\u0414\u0430\u0441\u0442\u0438 \u0434\u0443\u043e\u0438 \u043c\u043e\u0434\u0430\u0440\xbb (2018) \u0432\u0430\n\u04b7\u0438\u043b\u0434\u0438 \u0430\u0432\u0432\u0430\u043b\u0438 \u041a\u0443\u043b\u043b\u0438\u0451\u0442\u0438 \u0434\u0443\u04b7\u0438\u043b\u0434\u0430\u0438 \u0448\u043e\u0438\u0440 \u0447\u043e\u043f \u0433\u0430\u0440\u0434\u0438\u0434. \u0414\u0430\u0440 \u04b7\u0438\u043b\u0434\u0438\n\u0430\u0432\u0432\u0430\u043b\u0438 \u041a\u0443\u043b\u043b\u0438\u0451\u0442 (2001, 2008) \u0442\u0430\u043d\u04b3\u043e \u0448\u0435\u044a\u0440\u04b3\u043e\n2\n\u0444\u0430\u0440\u043e\u04b3\u0430\u043c \u043e\u043c\u0430\u0434\u0430\u0430\u043d\u0434.")
B.afy=new A.a("155c7264-2454-43b6-9c67-4edc3c802fda","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u041c\u0430\u04b7\u043c\u04ef\u0430\u04b3\u043e\u0438 \u041b\u043e\u0438\u049b \xab\u0425\u043e\u043a\u0438 \u0412\u0430\u0442\u0430\u043d\xbb \u0432\u0430...","\u041c\u0430\u04b7\u043c\u04ef\u0430\u04b3\u043e\u0438 \u041b\u043e\u0438\u049b \xab\u0425\u043e\u043a\u0438 \u0412\u0430\u0442\u0430\u043d\xbb \u0432\u0430 \xab\u0418\u043b\u04b3\u043e\u043c\xbb \u0431\u043e \u04b3\u0443\u0440\u0443\u0444\u0438 \u0430\u0440\u0430\xad\n\u0431\u0438\u0430\u0441\u043e\u0441\u0438 \u0444\u043e\u0440\u0441\u0438\u0438 \u0442\u043e\u04b7\u0438\u043a\u04e3 \u0447\u043e\u043f \u0433\u0430\u0440\u0434\u0438\u0434\u0430\u0430\u043d\u0434. \u0421\u043e\u043b\u0438 1993 \u043d\u0430\u0448\u0440\u0438\u044f\u0438\n\xab\u0410\u043b\u04b3\u0443\u0434\u043e\xbb-\u0438 \u042d\u0440\u043e\u043d \u043a\u0438\u0442\u043e\u0431\u0435\u0440\u043e \u0431\u043e \u043d\u043e\u043c\u0438 \xab\u0413\u0443\u043b\u0447\u0438\u043d\u0435 \u0430\u0437 \u0430\u0448\u044a\u043e\u0440\u0438 \u0443\u0441\u0442\u043e\u0434\n\u041b\u043e\u0438\u049b \u0428\u0435\u0440\u0430\u043b\u04e3\xbb \u0432\u0430 \u0441\u043e\u043b\u0438 1994 \u043d\u0430\u0448\u0440\u0438\u044f\u0438 \u0414\u043e\u043d\u0438\u0448\u0433\u043e\u04b3\u0438 \u0418\u0441\u0444\u0430\u04b3\u043e\u043d\n\u043c\u0430\u04b7\u043c\u04ef\u0430\u0435\u0440\u043e \u0442\u0430\u04b3\u0442\u0438 \u0443\u043d\u0432\u043e\u043d\u0438 \xab\u0414\u0430\u0441\u0442\u0438 \u0434\u0443\u043e\u0438 \u043c\u043e\u0434\u0430\u0440\xbb \u0447\u043e\u043f \u043a\u0430\u0440\u0434\u0430\u043d\u0434.\n\u04b2\u0430\u043c\u0447\u0443\u043d\u0438\u043d, \u0434\u0430\u0440 \u043d\u0430\u0448\u0440\u0438\u044f\u04b3\u043e\u0438 \u0430\u0434\u0430\u0431\u0438\u0438 \u041c\u0430\u0441\u043a\u0430\u0432 \u0432\u0430 \u0434\u0438\u0433\u0430\u0440 \u043c\u0430\u0440\u043a\u0430\u0437\u04b3\u043e\u0438\n\u0444\u0430\u0440\u04b3\u0430\u043d\u0433\u0438\u0438 \u0441\u043e\u0431\u0438\u049b \u0448\u04ef\u0440\u0430\u0432\u04e3 \u0441\u0438\u043b\u0441\u0438\u043b\u0430\u0438 \u0448\u0435\u044a\u0440\u04b3\u043e\u0438 \u041b\u043e\u0438\u049b \u0431\u043e \u0437\u0430\u0431\u043e\u043d\u04b3\u043e\u0438\n\u0433\u0443\u043d\u043e\u0433\u0443\u043d \u0440\u04ef\u0439\u0438 \u0447\u043e\u043f\u0440\u043e \u0434\u0438\u0434\u0430\u0430\u043d\u0434.")
B.a7m=new A.a("ae96e9ca-efdc-4a95-a603-dab6eb7d3690","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0414\u0430\u0440 \u0444\u0430\u044a\u043e\u043b\u0438\u044f\u0442\u0438 \u044d\u04b7\u043e\u0434\u0438\u0438 \u0443\u0441\u0442\u043e\u0434 \u041b\u043e\u0438...","\u0414\u0430\u0440 \u0444\u0430\u044a\u043e\u043b\u0438\u044f\u0442\u0438 \u044d\u04b7\u043e\u0434\u0438\u0438 \u0443\u0441\u0442\u043e\u0434 \u041b\u043e\u0438\u049b \u0442\u0430\u0440\u04b7\u0443\u043c\u0430 \u043c\u0430\u0432\u049b\u0435\u0438 \u0430\u0440\u0437\u0430\u043d\u0434\u0430\n\u0434\u043e\u0440\u0430\u0434. \u0428\u043e\u0438\u0440 \u0448\u0435\u044a\u0440\u04b3\u043e\u0438 \u0421\u0435\u0440\u0433\u0435\u0439 \u0415\u0441\u0435\u043d\u0438\u043d, \u0418. \u0413\u0451\u0442\u0435, \u0410. \u041f\u0443\u0448\u043a\u0438\u043d, \u0413.\n\u0413\u0435\u0439\u043d\u0435, \u0412. \u0413\u044e\u0433\u043e, \u041f. \u041d\u0435\u0440\u0443\u0434\u0430, \u049a. \u049a\u0443\u043b\u0438\u0435\u0432, \u042d. \u041c\u0435\u0436\u0435\u043b\u0430\u0439\u0442\u0438\u0441, \u041c. \u0421\u0432\u0435\u0442\xad\n\u043b\u043e\u0432, \u0420. \u0492\u0430\u043c\u0437\u0430\u0442\u043e\u0432, \u0415. \u0415\u0432\u0442\u0443\u0448\u0435\u043d\u043a\u043e, \u0410. \u041a\u043e\u0432\u0443\u0441\u043e\u0432, \u042d. \u0412\u043e\u04b3\u0438\u0434\u043e\u0432 \u0432\u0430 \u0430\u043c\u0441\u043e\xad\n\u043b\u0438 \u043e\u043d\u043e\u043d\u0440\u043e \u0431\u0430 \u0437\u0430\u0431\u043e\u043d\u0438 \u0442\u043e\u04b7\u0438\u043a\u04e3 \u0442\u0430\u0440\u04b7\u0443\u043c\u0430 \u043a\u0430\u0440\u0434\u0430\u0430\u0441\u0442.")
B.ame=new A.a("a8ea08bc-303a-4fee-9c1e-fd83e7c280df","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0428\u0435\u044a\u0440\u0438 \u041b\u043e\u0438\u049b \u0428\u0435\u0440\u0430\u043b\u04e3 \u04b3\u0430\u043c \u0434\u0430\u0440 \u049b\u043e\u043b\u0430...","\u0428\u0435\u044a\u0440\u0438 \u041b\u043e\u0438\u049b \u0428\u0435\u0440\u0430\u043b\u04e3 \u04b3\u0430\u043c \u0434\u0430\u0440 \u049b\u043e\u043b\u0430\u0431\u04b3\u043e\u0438 \u0441\u0443\u043d\u043d\u0430\u0442\u04e3, \u0447\u0443\u043d \u0493\u0430\u0437\u0430\u043b,\n\u049b\u0430\u0441\u0438\u0434\u0430, \u043c\u0430\u0441\u043d\u0430\u0432\u04e3, \u049b\u0438\u0442\u044a\u0430, \u0440\u0443\u0431\u043e\u04e3, \u0434\u0443\u0431\u0430\u0439\u0442\u04e3, \u0442\u0430\u0440\u04b7\u0435\u044a\u0431\u0430\u043d\u0434, \u0442\u0430\u0440\u043a\u0438\u0431\u0431\u0430\u043d\u0434,\n\u043c\u0443\u0441\u0430\u043b\u043b\u0430\u0441, \u0444\u0430\u0440\u0434 \u0432\u0430 \u04b3\u0430\u043c \u0434\u0430\u0440 \u0448\u0430\u043a\u043b\u04b3\u043e\u0438 \u043d\u0430\u0432\u0438 \u0448\u0435\u044a\u0440\u04e3, \u043c\u0438\u0441\u043b\u0438 \u0447\u0430\u04b3\u043e\u0440\u043f\u043e\u0440\u0430,\n\u0448\u0435\u044a\u0440\u0438 \u043e\u0437\u043e\u0434, \u0448\u0435\u044a\u0440\u0438 \u0441\u0430\u0444\u0435\u0434 \u0441\u0443\u0440\u0443\u0434\u0430 \u0448\u0443\u0434\u0430\u0430\u0441\u0442.")
B.aaT=new A.a("612702db-be47-4bb9-a1a0-973de5cf34ca","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0410\u0437 \u043d\u0430\u0432\u044a\u04b3\u043e\u0438 \u0441\u0443\u043d\u043d\u0430\u0442\u04e3 \u0434\u0430\u0440 \u044d\u04b7\u043e\u0434\u0438\u0451\u0442...","\u0410\u0437 \u043d\u0430\u0432\u044a\u04b3\u043e\u0438 \u0441\u0443\u043d\u043d\u0430\u0442\u04e3 \u0434\u0430\u0440 \u044d\u04b7\u043e\u0434\u0438\u0451\u0442\u0438 \u041b\u043e\u0438\u049b \u0436\u0430\u043d\xad\n\u0440\u0438 \u0493\u0430\u0437\u0430\u043b \u043c\u0430\u0432\u049b\u0435\u0438 \u0430\u0432\u0432\u0430\u043b\u0434\u0430\u0440\u0430\u04b7\u0430 \u0434\u043e\u0440\u0430\u0434 \u0432\u0430 \u043c\u0438\u049b\u0434\u043e\u0440\u0438\n\u0443\u043c\u0443\u043c\u0438\u0438 \u043e\u043d \u0434\u0430\u0440 \u0430\u0448\u044a\u043e\u0440\u0438 \u0448\u043e\u0438\u0440 \u0431\u0430 406 \u043c\u0435\u0440\u0430\u0441\u0430\u0434.\n\u041b\u043e\u0438\u049b \u0428\u0435\u0440\u0430\u043b\u04e3 \u0434\u0430\u0440 \u0438\u0441\u0442\u0438\u0444\u043e\u0434\u0430\u0438 \u0448\u0430\u043a\u043b\u0438 \u0493\u0430\u0437\u0430\u043b \u0431\u0430\n\u043a\u043e\u043c\u0451\u0431\u0438\u04b3\u043e\u0438 \u044d\u04b7\u043e\u0434\u04e3 \u043d\u043e\u0438\u043b \u0433\u0430\u0440\u0434\u0438\u0434. \u0492\u0430\u0437\u0430\u043b\u0438\u0451\u0442\u0438 \u041b\u043e\u0438\u049b \u0430\u0437 \u04b7\u0438\u04b3\u0430\u0442\u0438 \u04b3\u0430\u04b7\u043c \u0433\u0443\xad\n\u043d\u043e\u0433\u0443\u043d \u0431\u0443\u0434\u0430, \u0430\u0437 \u0447\u043e\u0440 \u0442\u043e \u0441\u0438\u044e \u0448\u0430\u0448 \u0431\u0430\u0439\u0442\u0440\u043e \u0444\u0430\u0440\u043e \u0433\u0438\u0440\u0438\u0444\u0442\u0430\u0430\u043d\u0434, \u0432\u0430\u043b\u0435 \u0430\u043a\u0441\u0430\xad\n\u0440\u0438 \u0493\u0430\u0437\u0430\u043b\u0438\u0451\u0442\u0438 \u0448\u043e\u0438\u0440 \u0430\u0437 \u0448\u0430\u0448 \u0451 \u04b3\u0430\u0444\u0442 \u0431\u0430\u0439\u0442 \u0438\u0431\u043e\u0440\u0430\u0442 \u043c\u0435\u0431\u043e\u0448\u0430\u043d\u0434:")
B.amq=new A.a("1136765d-f98d-4cf3-a794-e0345dd1d82f","713d15a2-3b5c-4d6a-9973-42e8eeae9950","\u0418\u0448\u049b \u0434\u0430\u0440 \u0434\u0438\u043b \u0448\u0443\u044a\u043b\u0430\u0438 \u0441\u0443\u0431\u04b3\u0438 \u0441\u0430\u043e\u0434\u0430...","\u0418\u0448\u049b \u0434\u0430\u0440 \u0434\u0438\u043b \u0448\u0443\u044a\u043b\u0430\u0438 \u0441\u0443\u0431\u04b3\u0438 \u0441\u0430\u043e\u0434\u0430\u0442 \u0431\u0443\u0434\u0430\u0430\u0441\u0442,\n\u041e\u0448\u0438\u049b\u04e3 \u044d\u04b3\u0441\u043e\u0441\u0438 \u0431\u0430\u0445\u0448\u0438\u0448\u04b3\u043e\u0438 \u049b\u0438\u0441\u043c\u0430\u0442 \u0431\u0443\u0434\u0430\u0430\u0441\u0442.\n\u0414\u0430\u0440 \u04b7\u0430\u0432\u043e\u043d\u04e3 \u0438\u0448\u049b \u0431\u0443\u0434\u0443 \u0434\u0430\u0432\u043b\u0430\u0442\u0438 \u0434\u0443\u043d\u0451 \u043d\u0430\u0431\u0443\u0434,\n\u041e\u043d \u04b3\u0430\u043c\u0430 \u0431\u0435\u0434\u0430\u0432\u043b\u0430\u0442\u0438\u04b3\u043e \u0445\u0443\u0431 \u0434\u0430\u0432\u043b\u0430\u0442 \u0431\u0443\u0434\u0430\u0430\u0441\u0442.\n\u0411\u0430\u0441\u043a\u0438 \u0430\u0437 \u043f\u043e\u0439\u0438 \u0440\u0430\u0432\u043e\u043d \u043c\u043e\u043d\u0434\u0435\u043c, \u04b3\u0430\u0441\u0440\u0430\u0442 \u043c\u0435\u043a\u0443\u043d\u0435\u043c,\n\u0410\u0437 \u043f\u0430\u0439\u0438 \u0445\u0443\u0431\u043e\u043d \u0434\u0430\u0432\u0438\u0434\u0430\u043d \u04b3\u0430\u043c \u0493\u0430\u043d\u0438\u043c\u0430\u0442 \u0431\u0443\u0434\u0430\u0430\u0441\u0442.\n\u0414\u0430\u0440 \u0444\u0430\u043b\u0430\u043a \u04b7\u0443\u0441\u0442\u0430\u043d \u0441\u0438\u0442\u043e\u0440\u0430 \u0441\u0430\u043d\u044a\u0430\u0442 \u0430\u0441\u0442\u0443 \u0434\u0430\u0440 \u0437\u0430\u043c\u0438\u043d\n\u0425\u0435\u0448\u0442\u0430\u043d\u0440\u043e \u0433\u0443\u043c \u043d\u0430\u043a\u0430\u0440\u0434\u0430\u043d \u04b3\u0430\u043c \u0441\u0430\u043d\u044a\u0430\u0442 \u0431\u0443\u0434\u0430\u0430\u0441\u0442.\n\u041e\u0434\u0430\u043c\u04e3 \u0431\u0430\u044a\u0434 \u0430\u0437 \u0437\u0430\u0432\u043e\u043b\u0438 \u0443\u043c\u0440 \u043c\u0435\u0444\u0430\u04b3\u043c\u0430\u0434, \u043a\u0438 \u0443\u043c\u0440,\n\u042f\u043a \u043d\u0430\u0437\u0430\u0440 \u0431\u0430\u0440 \u043e\u0441\u043c\u043e\u043d \u0431\u043e \u0447\u0430\u0448\u043c\u0438 \u04b3\u0430\u0439\u0440\u0430\u0442 \u0431\u0443\u0434\u0430\u0430\u0441\u0442.\n\u0411\u0435\u04b3\u0442\u0430\u0440\u0438\u043d \u0433\u0430\u043d\u04b7\u0435, \u043a\u0438 \u043e\u0434\u0430\u043c \u0451\u0444\u0442, \u0433\u0430\u0440 \u0441\u0438\u043c\u0443 \u0437\u0430\u0440 \u0430\u0441\u0442,\n\u0411\u0435\u04b3\u0442\u0430\u0440\u0438\u043d \u0433\u0430\u043d\u04b7\u0435, \u043a\u0438 \u0433\u0443\u043c \u043a\u0430\u0440\u0434 \u04ef, \u043c\u0443\u04b3\u0430\u0431\u0431\u0430\u0442 \u0431\u0443\u0434\u0430\u0430\u0441\u0442.")
