B.a7Y=new A.a("ced5b8b5-12a3-4df3-b0e3-ff9d0aa41a62","315b0945-c657-4c32-8b46-abb5f148482b","\u0412\u0430\u0442\u0430\u043d \u0441\u0430\u0440 \u043c\u0435\u0448\u0430\u0432\u0430\u0434 \u0430\u0437 \u0433\u043e\u04b3\u0432\u043e\u0440\u0430,","\u0412\u0430\u0442\u0430\u043d \u0441\u0430\u0440 \u043c\u0435\u0448\u0430\u0432\u0430\u0434 \u0430\u0437 \u0433\u043e\u04b3\u0432\u043e\u0440\u0430,\n\u0417\u0438 \u0448\u0438\u0440\u0438 \u043f\u043e\u043a\u0443 \u0430\u0437 \u043f\u0438\u0441\u0442\u043e\u043d\u0438 \u043c\u043e\u0434\u0430\u0440.\n\u0412\u0430\u0442\u0430\u043d \u0441\u0430\u0440 \u043c\u0435\u0448\u0430\u0432\u0430\u0434 \u0430\u0437 \u043e\u043d \u0442\u0430\u0432\u043e\u0440\u0430,\n1\n\u041a\u0438 \u043e\u043d\u0440\u043e \u0441\u043e\u0445\u0442\u0430 \u0434\u0430\u0441\u0442\u043e\u043d\u0438 \u043c\u043e\u0434\u0430\u0440...")
B.a7d=new A.a("de729e3e-ec67-4553-9936-1c3b056eaf01","315b0945-c657-4c32-8b46-abb5f148482b","\u0414\u0430\u0440 \u0438\u043d \u0448\u0435\u044a\u0440 \u0448\u043e\u0438\u0440 \u043a\u04ef\u0448\u0438\u0434\u0430\u0430\u0441\u0442, \u043a\u0438...","\u0414\u0430\u0440 \u0438\u043d \u0448\u0435\u044a\u0440 \u0448\u043e\u0438\u0440 \u043a\u04ef\u0448\u0438\u0434\u0430\u0430\u0441\u0442, \u043a\u0438 \u0431\u0430 \u0441\u0430\u0432\u043e\u043b\u0438 \xab\u0427\u0430\u0440\u043e \u0412\u0430\u0442\u0430\u043d \u0431\u0430\xad\n\u0440\u043e\u0438 \u04b3\u0430\u0440 \u044f\u043a \u0432\u0430\u0442\u0430\u043d\u0434\u043e\u0440 \u0430\u0437\u0438\u0437 \u0430\u0441\u0442?\xbb \u04b7\u0430\u0432\u043e\u0431 \u0433\u04ef\u044f\u0434. \u0412\u0430\u0442\u0430\u043d \u04b7\u043e\u0439\u0435\u0441\u0442, \u043a\u0438 \u0445\u0443\u043d\u0438\n\u043d\u043e\u0444\u0438 \u043d\u0430\u0432\u0437\u043e\u0434 \u043e\u043d \u04b7\u043e \u043c\u0435\u0440\u0435\u0437\u0430\u0434 \u0432\u0430 \u0442\u0438\u0444\u043b\u0440\u043e \u0431\u0430\u0440\u043e\u0431\u0430\u0440\u0438 \u043c\u043e\u0434\u0430\u0440 \u0434\u0430\u0440 \u043e\u0493\u04ef\u0448\n\u043c\u0435\u0433\u0438\u0440\u0430\u0434. \u0412\u0430\u0442\u0430\u043d\u0434\u043e\u0440 \u0431\u043e \u04b3\u0430\u0437\u043e\u0440 \u0440\u0438\u0448\u0442\u0430\u0438 \u0430\u0451\u043d\u0443 \u043d\u043e\u0430\u0451\u043d \u0431\u0430 \u0412\u0430\u0442\u0430\u043d \u043f\u0430\u0439\u0432\u0430\u0441\u0442\n\u043c\u0435\u0448\u0430\u0432\u0430\u0434, \u0431\u0430 \u0434\u0430\u0440\u0430\u04b7\u0430\u0435 \u043a\u0438 \u0445\u0443\u0434\u0440\u043e \u0431\u0435 \u0438\u043d \u043c\u0430\u043a\u043e\u043d\u0438 \u043c\u0443\u049b\u0430\u0434\u0434\u0430\u0441 \u0442\u0430\u0441\u0430\u0432\u0432\u0443\u0440\n\u043a\u0430\u0440\u0434\u0430 \u043d\u0430\u043c\u0435\u0442\u0430\u0432\u043e\u043d\u0430\u0434.")
B.agB=new A.a("e1e07a49-6128-49f9-bcec-858a3ef3482d","315b0945-c657-4c32-8b46-abb5f148482b","\u049a\u0430\u04b3\u0440\u0430\u043c\u043e\u043d\u0438 \u043b\u0438\u0440\u0438\u043a\u0438\u0438 \xab\u0425\u043e\u043a\u0438 \u0412\u0430\u0442\u0430\u043d\xbb...","\u049a\u0430\u04b3\u0440\u0430\u043c\u043e\u043d\u0438 \u043b\u0438\u0440\u0438\u043a\u0438\u0438 \xab\u0425\u043e\u043a\u0438 \u0412\u0430\u0442\u0430\u043d\xbb \u0442\u0430\u049b\u0434\u0438\u0440\u0438 \u0445\u0443\u0434\u0440\u043e \u0431\u0430 \u0442\u0430\u049b\u0434\u0438\u0440\u0438\n\u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d\u0438 \u043a\u0430\u043c\u0437\u0430\u043c\u0438\u043d \u043f\u0430\u0439\u0432\u0430\u0441\u0442\u0430\u0430\u0441\u0442 \u0432\u0430 \u0442\u0430\u044a\u0440\u0438\u0445\u0438 \u0433\u0443\u0437\u0430\u0448\u0442\u0430\u0438 \u043e\u043d\u0440\u043e \u0431\u043e\n\u0434\u0430\u0440\u0434\u0443 \u0430\u043b\u0430\u043c \u044d\u04b3\u0441\u043e\u0441 \u043c\u0435\u043d\u0430\u043c\u043e\u044f\u0434:")
B.arm=new A.a("78b18392-56a2-47b2-97c6-d292c0881989","315b0945-c657-4c32-8b46-abb5f148482b","\u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u2013 \u043c\u0430\u04b3\u0437\u0430\u0440\u0438","\u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u2013 \u043c\u0430\u04b3\u0437\u0430\u0440\u0438\n2\n\u043c\u0430\u043d,\n\u0421\u0430\u0440\u0437\u0430\u043c\u0438\u043d\u0438 \u043a\u0430\u043c\u0437\u0430\u043c\u0438\u043d.\n\u0422\u0443 \u0441\u0430\u0440\u043e\u0441\u0430\u0440 \u043a\u04ef\u04b3\u0441\u043e\u0440\u04e3,\n\u0422\u0443 \u0441\u0430\u0440\u043e\u0441\u0430\u0440 \u0441\u0430\u043d\u0433\u0437\u043e\u0440\u04e3,\n\u0427\u0443\u043d\u043a\u0438 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u043e\u043d\u0438 \u0442\u0443 \u0434\u0430\u0440 \u0442\u04ef\u043b\u0438 \u0442\u0430\u044a\u0440\u0438\u0445\u0438 \u0434\u0430\u0440\u043e\u0437\n\u04b2\u0430\u0440 \u043a\u0443\u04b7\u043e \u0440\u0430\u0444\u0442\u0430\u043d\u0434, \u043c\u0443\u0448\u0442\u0435 \u0445\u043e\u043a \u0431\u043e \u0445\u0443\u0434 \u0431\u0443\u0440\u0434\u0430\u0430\u043d\u0434,\n\u0427\u0443\u043d\u043a\u0438 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u043e\u043d\u0438 \u0442\u0443 \u0434\u0430\u0440 \u04b7\u0443\u0441\u0442\u0443\u04b7\u04ef\u0439\u0438 \u0431\u0430\u0445\u0442\u0438 \u0445\u0443\u0434\n\u0414\u0430\u0440 \u0431\u0438\u0451\u0431\u043e\u043d\u04b3\u043e\u0438 \u0442\u0430\u0444\u0441\u043e\u043d \u0434\u0443\u0440 \u0430\u0437 \u0442\u0443 \u043c\u0443\u0440\u0434\u0430\u0430\u043d\u0434.")
B.ag8=new A.a("94db940f-04dd-4285-975b-efd4d1f3290b","315b0945-c657-4c32-8b46-abb5f148482b","\u041d\u0438\u0451\u0433\u043e\u043d\u0438 \u043c\u043e \u04b3\u0430\u043d\u0433\u043e\u043c\u0438 \u04b3\u0430\u04b7 \u0432\u0430 \u0434\u0438\u0433\u0430...","\u041d\u0438\u0451\u0433\u043e\u043d\u0438 \u043c\u043e \u04b3\u0430\u043d\u0433\u043e\u043c\u0438 \u04b3\u0430\u04b7 \u0432\u0430 \u0434\u0438\u0433\u0430\u0440 \u0441\u0430\u0444\u0430\u0440\u04b3\u043e\u0438 \u0442\u04ef\u043b\u043e\u043d\u04e3 \u0431\u0430 \u0445\u043e\u0440\u0438\u04b7\u0438\n\u043a\u0438\u0448\u0432\u0430\u0440 \u043c\u0443\u0448\u0442\u0435 \u0445\u043e\u043a\u0440\u043e \u0431\u043e \u0445\u0443\u0434 \u043c\u0435\u0433\u0438\u0440\u0438\u0444\u0442\u0430\u043d\u0434. \u041b\u043e\u0438\u049b \u0434\u0430\u0440 \u0438\u043d \u0448\u0435\u044a\u0440\u0438\n64-\u043c\u0438\u0441\u0440\u0430\u04e3 \u0430\u0437 \u043a\u0430\u043c\u0437\u0430\u043c\u0438\u043d\u0438\u0438 \u0441\u0430\u0440\u0437\u0430\u043c\u0438\u043d\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u043c\u0430\u044a\u043d\u0438\u04b3\u043e\u0438 \u0430\u043c\u0438\u049b\u0438")
B.a8c=new A.a("64f14d90-5419-4eb7-b589-747749d65e6b","315b0945-c657-4c32-8b46-abb5f148482b","1   \u0422\u0430\u0432\u043e\u0440\u0430 \u2014 \u0447\u0430\u043f\u0430\u0440\u0430\u043a, \u0434\u0435\u0432\u043e\u0440\u0438 \u0430...","1   \u0422\u0430\u0432\u043e\u0440\u0430 \u2014 \u0447\u0430\u043f\u0430\u0440\u0430\u043a, \u0434\u0435\u0432\u043e\u0440\u0438 \u0430\u0437 \u0448\u043e\u0445\u04b3\u043e \u0431\u0443\u043d\u0451\u0434\u0433\u0430\u0440\u0434\u0438\u0434\u0430.\n2   \u041c\u0430\u04b3\u0437\u0430\u0440 \u2014 \u04b7\u043e\u0439\u0438 \u04b3\u043e\u0437\u0438\u0440\u0448\u0430\u0432\u04e3, \u043c\u0430\u043a\u043e\u043d.")
B.ac3=new A.a("805f0693-77e6-43e7-9c67-0b36ad15f5a7","315b0945-c657-4c32-8b46-abb5f148482b","\u0432\u0430\u0442\u0430\u043d\u0445\u043e\u04b3\u04e3 \u0431\u0430\u0440\u0434\u043e\u0448\u0442\u0430\u0430\u0441\u0442. \u0411\u0430 \u049b\u0430\u0432\u043b...","\u0432\u0430\u0442\u0430\u043d\u0445\u043e\u04b3\u04e3 \u0431\u0430\u0440\u0434\u043e\u0448\u0442\u0430\u0430\u0441\u0442. \u0411\u0430 \u049b\u0430\u0432\u043b\u0438 \u0448\u043e\u0438\u0440, \u0441\u0430\u0440\u0437\u0430\u043c\u0438\u043d\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d\n\u043a\u04ef\u0447\u0430\u043a \u0431\u043e\u0448\u0430\u0434 \u04b3\u0430\u043c, \u0445\u043e\u043a\u0438 \u043e\u043d \u0431\u0430 \u0432\u043e\u0441\u0438\u0442\u0430\u0438 \u0448\u0430\u0445\u0441\u0438\u044f\u0442\u04b3\u043e\u0438 \u0431\u0430\u0440\u04b7\u0430\u0441\u0442\u0430\u0435, \u0447\u0443\u043d\n\u0414\u0435\u0432\u0430\u0448\u0442\u0438\u0447, \u0420\u0443\u0445\u0448\u043e\u043d\u0430, \u0411\u0435\u0434\u0438\u043b, \u0418\u0431\u043d\u0438 \u0421\u0438\u043d\u043e \u0431\u0430 \u0442\u0430\u043c\u043e\u043c\u0438 \u04b7\u0430\u04b3\u043e\u043d \u043f\u0430\u04b3\u043d\n\u0448\u0443\u0434\u0430\u0430\u0441\u0442, \u043a\u0438 \u0438\u043d \u0431\u043e\u0438\u0441\u0438 \u0438\u0444\u0442\u0438\u0445\u043e\u0440 \u0430\u0441\u0442. \u0421\u0430\u0440\u043e\u0441\u0430\u0440 \u043a\u04ef\u04b3\u0441\u043e\u0440\u0443 \u0441\u0430\u043d\u0433\u0437\u043e\u0440 \u0431\u0443\xad\n\u0434\u0430\u043d\u0438 \u0422\u043e\u04b7\u0438\u043a\u0438\u0441\u0442\u043e\u043d \u043c\u0430\u0440\u0434\u0443\u043c\u0438 \u0442\u043e\u04b7\u0438\u043a\u0440\u043e \u0432\u043e\u0434\u043e\u0440 \u043c\u0435\u043a\u0443\u043d\u0430\u0434, \u043a\u0438 \u043c\u0430\u0441\u044a\u0443\u043b\u0438\u044f\xad\n\u0442\u0438 \u0431\u0430\u043b\u0430\u043d\u0434\u0438 \u0432\u0430\u0442\u0430\u043d\u0434\u043e\u0440\u04e3 \u0431\u0430 \u0434\u04ef\u0448 \u0434\u043e\u0448\u0442\u0430 \u0431\u043e\u0448\u0430\u043d\u0434 \u0432\u0430 \u0431\u0430\u04b3\u0440\u0438 \u0430\u04b7\u0434\u043e\u0434\u043e\u043d\u0438\n\u04b7\u043e\u043d\u0441\u0443\u043f\u043e\u0440\u0438 \u0445\u0443\u0434 \u0430\u0437 \u0441\u0430\u043d\u0433\u0438 \u0412\u0430\u0442\u0430\u043d \u043f\u0430\u0439\u043a\u0430\u0440\u0430\u04b3\u043e \u0441\u043e\u0445\u0442\u0430, \u043e\u0431\u043e\u0434\u0438\u044e \u0437\u0435\u0431\u043e\u0438\u0438\n\u0434\u0438\u0451\u0440\u0438 \u04b3\u0430\u043c\u0435\u0448\u0430\u0431\u0430\u04b3\u043e\u0440\u0438 \u0445\u0443\u0434\u0440\u043e \u0442\u0430\u044a\u043c\u0438\u043d \u043d\u0430\u043c\u043e\u044f\u043d\u0434.")
B.ajE=new A.a("c8b3ea43-32fe-4ff6-a072-13df173bc05d","315b0945-c657-4c32-8b46-abb5f148482b","\u0414\u0430\u0440 \u04b3\u0430\u0440 \u0448\u0435\u044a\u0440\u0438 \u0431\u0430 \u0412\u0430\u0442\u0430\u043d \u0431\u0430\u0445\u0448\u0438\u0434\u0430...","\u0414\u0430\u0440 \u04b3\u0430\u0440 \u0448\u0435\u044a\u0440\u0438 \u0431\u0430 \u0412\u0430\u0442\u0430\u043d \u0431\u0430\u0445\u0448\u0438\u0434\u0430\u0438 \u041b\u043e\u0438\u049b \u0428\u0435\u0440\u0430\u043b\u04e3, \u0430\u0437 \u04b7\u0443\u043c\u043b\u0430 \u0434\u0430\u0440\n\xab\u0421\u0443\u0440\u0443\u0434\u0438 \u043c\u0430\u0432\u04b7\u0434\u043e\u0440\u0438 \u0440\u04ef\u0434\u0438 \u0412\u0430\u0440\u0437\u043e\u0431\xbb, \xab\u0414\u0443\u0448\u0430\u043d\u0431\u0435\xbb, \xab\u0424\u0430\u0440\u0434\u043e\u0438 \u0414\u0443\u0448\u0430\u043d\xad\n\u0431\u0435\xbb, \xab\u0414\u0435\u04b3\u0438 \u043a\u04ef\u0447\u0438\u0434\u0430\xbb, \xab\u041a\u04ef\u04b3\u0438\u0441\u0442\u043e\u043d\xbb, \xab\u0418\u0444\u0442\u0438\u0445\u043e\u0440\xbb, \xab\u0413\u0430\u043d\u04b7\u0438 \u043a\u04ef\u04b3\u0438\u0441\u0442\u043e\u043d\xbb\n\u044f\u0433\u043e\u043d \u043c\u0430\u0441\u044a\u0430\u043b\u0430\u0438 \u043c\u0430\u0440\u0431\u0443\u0442 \u0431\u0430 \u0434\u0438\u0451\u0440 \u0432\u0430 \u0442\u0430\u0431\u0438\u0430\u0442\u0438 \u043f\u0443\u0440\u0441\u0430\u0445\u043e\u0438 \u043e\u043d \u043c\u0430\u0432\u0440\u0438\u0434\u0438\n\u0431\u0430\u0440\u0440\u0430\u0441\u0438\u0438 \u0431\u0430\u0434\u0435\u04e3 \u049b\u0430\u0440\u043e\u0440 \u043c\u0435\u0433\u0438\u0440\u0430\u0434..")
B.aff=new A.a("14410e1b-55d4-4ee5-a7de-f4d325cbdb24","315b0945-c657-4c32-8b46-abb5f148482b","\u0414\u0430\u0440 \u0430\u0448\u044a\u043e\u0440\u0438 \u0448\u043e\u0438\u0440 \u043c\u0430\u0437\u043c\u0443\u043d\u04b3\u043e\u0438 \u0444\u0430\u043b\u0441...","\u0414\u0430\u0440 \u0430\u0448\u044a\u043e\u0440\u0438 \u0448\u043e\u0438\u0440 \u043c\u0430\u0437\u043c\u0443\u043d\u04b3\u043e\u0438 \u0444\u0430\u043b\u0441\u0430\u0444\u0438\u044e \u04b3\u0438\u043a\u043c\u0430\u0442\u043e\u043c\u0435\u0437 \u043c\u0430\u0432\u049b\u0435\u0438\n\u043c\u0443\u043d\u043e\u0441\u0438\u0431 \u0434\u043e\u0440\u0430\u043d\u0434. \u049a\u0430\u04b3\u0440\u0430\u043c\u043e\u043d\u0438 \u043b\u0438\u0440\u0438\u043a\u04e3 \u0431\u0430 \u0441\u043e\u04b3\u0430\u04b3\u043e\u0438 \u0433\u0443\u043d\u043e\u0433\u0443\u043d\u0438\n\u0437\u0438\u043d\u0434\u0430\u0433\u04e3 \u04b7\u0438\u0434\u0434\u0430\u043d \u0434\u0430\u0445\u043e\u043b\u0430\u0442 \u043d\u0430\u043c\u0443\u0434\u0430, \u0430\u0437 \u043c\u0443\u0448\u043e\u04b3\u0438\u0434\u0430\u04b3\u043e \u0445\u0443\u043b\u043e\u0441\u0430\u04b3\u043e\u0438 \u0430\u043c\u0438\u049b\u0438\n\u043f\u0430\u043d\u0434\u0443\u0430\u0445\u043b\u043e\u049b\u04e3 \u043c\u0435\u0431\u0430\u0440\u043e\u0440\u0430\u0434. \u0410\u0437 \u04b7\u0443\u043c\u043b\u0430, \u04ef \u043e\u0434\u0430\u043c\u043e\u043d\u0440\u043e \u04b3\u0443\u0448\u0434\u043e\u0440 \u043c\u0435\u0434\u0438\u04b3\u0430\u0434,\n\u043a\u0438 \u0430\u0437 \u04b3\u0430\u0440 \u044f\u043a \u043b\u0430\u04b3\u0437\u0430\u0438 \u0443\u043c\u0440 \u0441\u0430\u043c\u0430\u0440\u0430\u043d\u043e\u043a \u0438\u0441\u0442\u0438\u0444\u043e\u0434\u0430 \u0431\u0430\u0440\u0430\u043d\u0434, \u0437\u0435\u0440\u043e \u0437\u0438\u043d\u0434\u0430\u0433\u04e3\n\u044f\u043a\u0441\u043e\u043d \u043d\u0430\u043c\u0435\u043c\u043e\u043d\u0430\u0434. \u0411\u0435\u04b3\u0443\u0434\u0430 \u0433\u0443\u0437\u0430\u0440\u043e\u043d\u0438\u0434\u0430\u043d\u0438 \u0443\u043c\u0440 \u043d\u0430\u0442\u0438\u04b7\u0430\u04b3\u043e\u0438 \u043d\u043e\u043c\u0430\u0442\xad\n\u043b\u0443\u0431 \u0431\u0430 \u0431\u043e\u0440 \u043c\u0435\u043e\u0440\u0430\u0434 \u0432\u0430 \u043f\u0443\u0448\u0430\u0439\u043c\u043e\u043d\u04e3 \u0441\u0443\u0434\u0435 \u043d\u0430\u0445\u043e\u04b3\u0430\u0434 \u0434\u043e\u0448\u0442. \u0414\u0430\u0440 \u0448\u0435\u044a\u0440\u0438\n\xab\u0410\u043b\u043e, \u0448\u043e\u0434\u043e\u0431 \u0441\u043e\u04b3\u0438\u043b\u04b3\u043e\xbb \u0438\u043d \u043c\u0443\u0430\u043c\u043c\u043e \u0431\u0430\u0441\u043e \u04b7\u043e\u043b\u0438\u0431 \u043c\u0430\u0432\u0440\u0438\u0434\u0438 \u0431\u0430\u04b3\u0441 \u049b\u0430\u0440\u043e\u0440\n\u0433\u0438\u0440\u0438\u0444\u0442\u0430\u0430\u0441\u0442:")
B.any=new A.a("e6286f04-8544-45e8-8052-09d066ff9c8f","315b0945-c657-4c32-8b46-abb5f148482b","\u0410\u043b\u043e, \u0448\u043e\u0434\u043e\u0431 \u0441\u043e\u04b3\u0438\u043b\u04b3\u043e,","\u0410\u043b\u043e, \u0448\u043e\u0434\u043e\u0431 \u0441\u043e\u04b3\u0438\u043b\u04b3\u043e,\n\u0411\u0430 \u049b\u0430\u0434\u0440\u0438 \u043e\u0431\u04b3\u043e\u0438 \u04b7\u043e\u0440\u04e3 \u043c\u0435\u0431\u043e\u044f\u0434 \u0440\u0430\u0441\u0438\u0434 \u0438\u043c\u0440\u04ef\u0437,\n\u041a\u0438 \u0440\u04ef\u0437\u0435 \u0445\u0443\u0448\u043a \u0445\u043e\u04b3\u0430\u0434 \u0448\u0443\u0434.\n\u0410\u043b\u043e, \u0437\u0435\u0431\u043e\u0438 \u043c\u0430\u04b3\u0444\u0438\u043b\u04b3\u043e,\n\u0411\u0430 \u049b\u0430\u0434\u0440\u0438 \u04b3\u0430\u0440 \u0447\u0430\u0440\u043e\u0493\u0438 \u0434\u0430\u0432\u0440\u0430 \u043c\u0435\u0431\u043e\u044f\u0434 \u0440\u0430\u0441\u0438\u0434 \u0438\u043c\u0440\u04ef\u0437,\n\u041a\u0438 \u0440\u04ef\u0437\u0435 \u0430\u0437 \u0448\u0430\u043c\u043e\u043b\u0438 \u04b3\u043e\u0434\u0438\u0441\u0430 \u0445\u043e\u043c\u04ef\u0448 \u0445\u043e\u04b3\u0430\u0434 \u0448\u0443\u0434...\n\u0410\u043b\u043e, \u044d\u0439 \u0441\u043e\u04b3\u0438\u0431\u043e\u043d\u0438 \u0432\u0430\u049b\u0442,\n\u0412\u0430\u049b\u0442\u0438 \u0445\u0435\u0448 \u0434\u0430\u0440\u0451\u0431\u0435\u0434,\n\u0428\u0443\u043c\u043e \u04b3\u043e\u043b\u043e \u04b7\u0430\u0432\u043e\u043d\u0443 \u043a\u043e\u043c\u0440\u043e\u043d\u0443 \u0448\u043e\u0434\u043c\u043e\u043d\u0443 \u0437\u0438\u043d\u0434\u0430\u0435\u0434 \u043e\u0445\u0438\u0440!...")
B.agt=new A.a("dc7a0bf3-1bf3-463b-863a-cec7570b6342","315b0945-c657-4c32-8b46-abb5f148482b","\u041c\u0430\u0432\u0437\u04ef\u044a\u04b3\u043e\u0438 \u043f\u0430\u043d\u0434\u0443\u0430\u0445\u043b\u043e\u049b\u04e3, \u043c\u0430\u0445\u0441\u0443\u0441\u0430...","\u041c\u0430\u0432\u0437\u04ef\u044a\u04b3\u043e\u0438 \u043f\u0430\u043d\u0434\u0443\u0430\u0445\u043b\u043e\u049b\u04e3, \u043c\u0430\u0445\u0441\u0443\u0441\u0430\u043d \u0434\u0430\u0440 \u049b\u0438\u0441\u043c\u0430\u0442\u04b3\u043e\u0438 \xab\u0421\u0443\u0445\u0430\u043d\xad\n\u0440\u0435\u0437\u0430\xbb \u0432\u0430 \xab\u0425\u0443\u0440\u0434\u0430\u04b3\u043e \u0432\u0430 \u0442\u0430\u043a\u0431\u0430\u0439\u0442\u0438\u04b3\u043e\xbb, \u043a\u0438, \u0430\u0441\u043e\u0441\u0430\u043d, \u0431\u0430\u0439\u0442\u04b3\u043e\u0438 \u0448\u043e\u0438\u0440\u0440\u043e\n\u0434\u0430\u0440 \u0431\u0430\u0440 \u043c\u0435\u0433\u0438\u0440\u0430\u043d\u0434, \u0431\u0435\u0448\u0442\u0430\u0440 \u0431\u0430 \u043c\u0443\u0448\u043e\u04b3\u0438\u0434\u0430 \u043c\u0435\u0440\u0430\u0441\u0430\u043d\u0434. \u0418\u043d \u0431\u0430\u0439\u0442\u04b3\u043e,\n\u043a\u0438 \u0447\u0443\u043d \u043c\u0430\u04b3\u0441\u0443\u043b\u0438 \u043d\u0430\u0442\u0438\u04b7\u0430\u0433\u0438\u0440\u0438\u04b3\u043e\u0438 \u0448\u043e\u0438\u0440 \u0430\u0437 \u043f\u0430\u04b3\u043b\u0443\u04b3\u043e\u0438 \u04b3\u0430\u0437\u043e\u0440\u0440\u0430\u043d\u0433\u0438\n\u0437\u0438\u043d\u0434\u0430\u0433\u04e3 \u0431\u0430\u0434\u0435\u04b3\u0430\u0442\u0430\u043d\n1\n\u0433\u0443\u0444\u0442\u0430 \u0448\u0443\u0434\u0430\u0430\u043d\u0434, \u0430\u043a\u0441\u0430\u0440\u0430\u043d \u04b3\u0443\u043a\u043c\u0438 \u043f\u0430\u043d\u0434\u0443 \u0430\u043d\u0434\u0430\u0440\u0437\n\u0432\u0430 \u0441\u0443\u0445\u0430\u043d\u04b3\u043e\u0438 \u04b3\u0438\u043a\u043c\u0430\u0442\u043d\u043e\u043a\u0440\u043e \u0434\u043e\u0440\u0430\u043d\u0434:")
B.alC=new A.a("cf97da55-6f35-4cc3-88f9-04d869f95764","315b0945-c657-4c32-8b46-abb5f148482b","\u042d\u0439 \u043f\u0438\u0441\u0430\u0440, \u0445\u043e\u04b3\u04e3 \u0430\u0433\u0430\u0440 \u0440\u04ef\u04b3\u0438 \u043f\u0430\u0434\u0430\u0440...","\u042d\u0439 \u043f\u0438\u0441\u0430\u0440, \u0445\u043e\u04b3\u04e3 \u0430\u0433\u0430\u0440 \u0440\u04ef\u04b3\u0438 \u043f\u0430\u0434\u0430\u0440 \u0448\u043e\u0434 \u043a\u0443\u043d\u04e3,\n\u0425\u043e\u043d\u0430\u0432\u0430\u0439\u0440\u043e\u043d \u0448\u0430\u0432\u04e3 \u04b3\u0430\u043c, \u0433\u04ef\u0440\u0438 \u0432\u0430\u0439 \u043e\u0431\u043e\u0434 \u043a\u0443\u043d\u04e3.")
B.aay=new A.a("8a13b8d4-1126-4663-8516-dc50cf851853","315b0945-c657-4c32-8b46-abb5f148482b","\u0423\u0441\u0442\u043e\u0434 \u041b\u043e\u0438\u049b \u0428\u0435\u0440\u0430\u043b\u04e3 \u0430\u0437 \u043d\u0430\u0445\u0443\u0441\u0442\u0438\u043d ...","\u0423\u0441\u0442\u043e\u0434 \u041b\u043e\u0438\u049b \u0428\u0435\u0440\u0430\u043b\u04e3 \u0430\u0437 \u043d\u0430\u0445\u0443\u0441\u0442\u0438\u043d \u049b\u0430\u0434\u0430\u043c\u04b3\u043e\u0438\n\u044d\u04b7\u043e\u0434\u0438\u044f\u0448 \u0431\u0430 \u043c\u0430\u0432\u0437\u04ef\u0438 \u043c\u043e\u0434\u0430\u0440 \u0442\u0430\u0432\u0430\u04b7\u04b7\u0443\u04b3 \u043f\u0430\u0439\u0434\u043e \u043a\u0430\u0440\xad\n\u0434\u0430\u0430\u0441\u0442. \u042f\u043a\u0435 \u0430\u0437 \u0430\u0432\u0432\u0430\u043b\u0438\u043d \u0448\u0435\u044a\u0440\u04b3\u043e\u0438 \u0448\u043e\u0438\u0440 \xab\u0411\u0430 \u043c\u043e\xad\n\u0434\u0430\u0440\u0430\u043c\xbb \u043d\u043e\u043c \u0434\u043e\u0440\u0430\u0434, \u043a\u0438 \u0431\u043e\u0440\u0438 \u043d\u0430\u0445\u0443\u0441\u0442 \u0438\u0431\u0442\u0438\u0434\u043e\u0438\n\u0441\u043e\u043b\u0438 1965 \u0431\u0430 \u0442\u0430\u0431\u044a \u0440\u0430\u0441\u0438\u0434\u0430\u0430\u0441\u0442. \u0411\u0430\u044a\u0434\u04b3\u043e \u0438\u043d \u043c\u0430\u0432\u0437\u04ef\u044a \u0434\u0430\u0440 \u0442\u0430\u043c\u043e\u043c\u0438\n\u044d\u04b7\u043e\u0434\u0438\u0451\u0442\u0438 \u0448\u043e\u0438\u0440 \u043c\u0430\u0432\u049b\u0435\u0438 \u0430\u0432\u0432\u0430\u043b\u0434\u0430\u0440\u0430\u04b7\u0430 \u043f\u0430\u0439\u0434\u043e \u043d\u0430\u043c\u0443\u0434. \u0412\u0430\u049b\u0442\u0435 \u043a\u0438 \xab\u0414\u0430\u0441\xad\n\u0442\u0438 \u0434\u0443\u043e\u0438 \u043c\u043e\u0434\u0430\u0440\xbb \u043d\u043e\u043c \u043c\u0430\u04b7\u043c\u04ef\u0430\u0438 \u0448\u043e\u0438\u0440\u0440\u043e \u0432\u0430\u0440\u0430\u049b \u043c\u0435\u0437\u0430\u043d\u0435\u043c, \u0431\u0430 \u043f\u0430\u043d\u04b7\u043e\u04b3\u0443\n\u043f\u0430\u043d\u04b7 \u0448\u0435\u044a\u0440\u0438 \u0431\u0430 \u043c\u043e\u0434\u0430\u0440 \u0432\u0430 \u0437\u0430\u043d \u0431\u0430\u0445\u0448\u0438\u0434\u0430 \u0434\u0443\u0447\u043e\u0440 \u043c\u0435\u043e\u0435\u043c.")
B.ahk=new A.a("741a22cd-8db9-4b69-89bd-53c226d6ab3d","315b0945-c657-4c32-8b46-abb5f148482b","\u04b2\u0430\u043c\u0430\u0438 \u0430\u0448\u044a\u043e\u0440\u0438 \u0431\u0430 \u043c\u043e\u0434\u0430\u0440 \u0431\u0430\u0445\u0448\u0438\u0434\u0430\u0438...","\u04b2\u0430\u043c\u0430\u0438 \u0430\u0448\u044a\u043e\u0440\u0438 \u0431\u0430 \u043c\u043e\u0434\u0430\u0440 \u0431\u0430\u0445\u0448\u0438\u0434\u0430\u0438 \u041b\u043e\u0438\u049b, \u0430\u0437 \u04b7\u0443\u043c\u043b\u0430 \u0448\u0435\u044a\u0440\u04b3\u043e\u0438\n\xab\u041c\u043e\u0434\u0430\u0440\xbb, \xab\u0421\u0443\u0440\u0443\u0434\u0438 \u043c\u043e\u0434\u0430\u0440\xbb, \xab\u049a\u0430\u0440\u0437\xbb, \xab\u049a\u0430\u0441\u0438\u0434\u0430\u0438 \u043c\u043e\u0434\u0430\u0440\xbb, \xab\u04b6\u043e\u043c\u0430\u0438\n\u0433\u0430\u0434\u043e\u04e3\xbb, \xab\u0427\u043e\u0440\u0434\u0430\u0440\u0434\xbb, \xab\u0422\u0443 \u043c\u043e\u043d\u0430\u043d\u0434\u0438 \u0437\u0430\u043c\u0438\u043d \u0442\u0430\u043d\u04b3\u043e\u04e3, \u043c\u043e\u0434\u0430\u0440\xbb, \xab\u0414\u0430\u0440\n\u0441\u0430\u0440\u0438 \u0433\u04ef\u0440\xbb, \xab\u04b2\u0430\u0441\u0440\u0430\u0442\xbb, \xab\u041c\u0443\u043d\u043e\u04b7\u043e\u0442 \u0431\u0430 \u043c\u043e\u0434\u0430\u0440\xbb \u0432\u0430 \u0440\u0443\u0431\u043e\u0438\u0432\u0443 \u0434\u0443\u0431\u0430\u0439\u0442\u0438\u04b3\u043e\u0438\n\u043c\u0430\u04b7\u043c\u04ef\u0430\u0438 \xab\u0414\u0430\u0441\u0442\u0438 \u0434\u0443\u043e\u0438 \u043c\u043e\u0434\u0430\u0440\xbb, \u04b7\u043e\u0432\u0438\u0434\u043e\u043d\u0430\u0430\u043d\u0434. \u0414\u0430\u0440 \u0438\u043d \u0448\u0435\u044a\u0440\u04b3\u043e \u0445\u0443\u0441\u0443\xad\n\u0441\u0438\u044f\u0442\u0438 \u043c\u0438\u043b\u043b\u0438\u044e \u0448\u0430\u0440\u049b\u0438\u0438 \u043c\u043e\u0434\u0430\u0440\u0438 \u043e\u0434\u0438\u0438 \u0442\u043e\u04b7\u0438\u043a, \u0431\u043e\u0442\u0438\u043d\u0438 \u043f\u043e\u043a\u0443 \u0431\u0435\u043e\u043b\u043e\u0438\u0448\n\u0432\u0430 \u04b7\u0430\u04b3\u043e\u043d\u0438 \u043e\u0440\u0437\u0443\u0432\u0443 \u04b3\u0430\u0432\u0430\u0441\u04b3\u043e\u0438 \u043c\u043e\u0434\u0430\u0440\u0438 \u0440\u0443\u0441\u0442\u043e\u04e3 \u043c\u0430\u0432\u0440\u0438\u0434\u0438 \u0442\u0430\u0441\u0432\u0438\u0440 \u049b\u0430\u0440\u043e\u0440\n\u0433\u0438\u0440\u0438\u0444\u0442\u0430\u0430\u0441\u0442. \u0422\u0430\u0441\u0432\u0438\u0440\u04b3\u043e \u0447\u0443\u043d\u043e\u043d \u0441\u043e\u0434\u0430\u0432\u0443 \u0441\u0430\u043c\u0438\u043c\u04e3 \u0432\u0430 \u0438\u0444\u043e\u0434\u0430\u04b3\u043e \u0447\u0443\u043d\u043e\u043d\n\u043c\u043e\u04b3\u0438\u0440\u043e\u043d\u0430 \u0431\u0430 \u04b3\u0430\u043c \u043e\u043c\u0430\u0434\u0430\u0430\u043d\u0434, \u043a\u0438 \u0445\u043e\u043d\u0430\u043d\u0434\u0430 \u0431\u0435\u0438\u0445\u0442\u0438\u0451\u0440 \u04b7\u0430\u0432\u04b3\u0430\u0440\u0438 \u04b3\u0430\u0441\u0442\u0438\u0438\n\u0438\u043d\u0441\u043e\u043d\u0440\u043e \u043f\u0435\u0448\u0438 \u043d\u0430\u0437\u0430\u0440 \u043c\u0435\u043e\u0440\u0430\u0434:")
B.afz=new A.a("61b785a2-f342-4e82-a3d0-0ae3c523483b","315b0945-c657-4c32-8b46-abb5f148482b","\u041d\u0430\u0451\u0431\u0430\u0434 \u0447\u0430\u0448\u043c\u0438 \u043a\u0430\u043c\u0431\u0438\u043d\u0430\u0442 \u0431\u0430 \u04b7\u0443\u0441\u0442\u0430...","\u041d\u0430\u0451\u0431\u0430\u0434 \u0447\u0430\u0448\u043c\u0438 \u043a\u0430\u043c\u0431\u0438\u043d\u0430\u0442 \u0431\u0430 \u04b7\u0443\u0441\u0442\u0430\u043d \u0447\u0430\u0448\u043c\u0438 \u0441\u04ef\u0437\u0430\u043d\u0440\u043e,\n\u0411\u0438\u043b\u0430\u0440\u0437\u0430\u0434 \u0434\u0430\u0441\u0442\u0438 \u043f\u0443\u0440\u044d\u044a\u04b7\u043e\u0437\u0438 \u0442\u0443 \u0434\u0430\u0440 \u049b\u0430\u0431\u0437\u0430\u0438 \u043f\u0438\u0440\u04e3.\n\u0412\u0430\u043b\u0435\u043a\u0438\u043d \u0431\u043e\u0437 \u043c\u0435\u0434\u04ef\u0437\u04e3 \u0442\u0443 \u0434\u0430\u0441\u0442\u0443\u0440\u0445\u043e\u043d\u0438 \u0433\u0443\u043b\u0434\u04ef\u0437\u04e3,\n\u041a\u0438 \u0440\u04ef\u0437\u0438 \u043c\u0430\u044a\u0440\u0430\u043a\u0430 \u0434\u0430\u0440 \u0431\u0430\u0439\u043d\u0438 \u043c\u0430\u0440\u0434\u0443\u043c \u043e\u0431\u0440\u04ef \u0433\u0438\u0440\u04e3.\n\u0427\u04e3 \u0434\u0443\u043d\u0451\u0435\u0441\u0442 \u0434\u0443\u043d\u0451\u0438 \u0443\u043c\u0435\u0434\u0438 \u0442\u0443,\n\u0410\u0451 \u043c\u043e\u0434\u0430\u0440, \u0430\u0451 \u043c\u043e\u0434\u0430\u0440!\n(\xab\u0411\u0430 \u043c\u043e\u0434\u0430\u0440\u0430\u043c\xbb)")
B.adO=new A.a("12e57afd-daa6-4fa0-94d3-36b2327a8af0","315b0945-c657-4c32-8b46-abb5f148482b","\u0414\u0430\u0440 \u041c\u043e\u0434\u0430\u0440\u043d\u043e\u043c\u0430\u0438 \u041b\u043e\u0438\u049b \u0440\u04ef\u04b3\u0438 \u0445\u0430\u043b\u049b\u0438...","\u0414\u0430\u0440 \u041c\u043e\u0434\u0430\u0440\u043d\u043e\u043c\u0430\u0438 \u041b\u043e\u0438\u049b \u0440\u04ef\u04b3\u0438 \u0445\u0430\u043b\u049b\u0438\u0438 \u0442\u0430\u0441\u0432\u0438\u0440 \u043f\u0443\u0440\u049b\u0443\u0432\u0432\u0430\u0442 \u0430\u0441\u0442.\n\u0428\u043e\u0438\u0440 \u0434\u0430\u0440 \u0442\u0430\u0441\u0432\u0438\u0440\u0438 \u04b3\u0430\u0441\u0442\u0438\u0438 \u043c\u043e\u0434\u0430\u0440 \u0430\u0437 \u0443\u0440\u0444\u0443 \u043e\u0434\u0430\u0442 \u0432\u0430 \u0430\u043d\u044a\u0430\u043d\u0430\u04b3\u043e\u0438\n\u049b\u0430\u0434\u0438\u043c\u0438\u0438 \u043c\u0430\u0440\u0434\u0443\u043c\u0438 \u0442\u043e\u04b7\u0438\u043a \u0443\u0441\u0442\u043e\u0434\u043e\u043d\u0430 \u0438\u0441\u0442\u0438\u0444\u043e\u0434\u0430 \u043a\u0430\u0440\u0434\u0430\u0430\u0441\u0442. \u0414\u0430\u0440 \u0448\u0435\u044a\xad\n\u0440\u0438 \xab\u04b6\u043e\u043c\u0430\u0438 \u0433\u0430\u0434\u043e\u04e3\xbb \u043c\u043e\u0434\u0430\u0440 \u0431\u043e \u043d\u0438\u044f\u0442 \u0431\u0430 \u0434\u0430\u0440\u0438 \u0445\u043e\u043d\u0430\u0438 \u0437\u0430\u043d\u043e\u043d\u0438 \u0441\u0435\u0440\u0444\u0430\u0440\xad\n\u0437\u0430\u043d\u0434, \u043f\u0438\u0440\u043e\u043d\u0438 \u0431\u043e\u0442\u0430\u0434\u0431\u0438\u0440\u0443 \u0441\u043e\u043b\u043e\u0440, \u043e\u0434\u0430\u043c\u043e\u043d\u0438 \u0431\u043e\u0434\u0430\u0432\u043b\u0430\u0442\u0443 \u0431\u043e\u043d\u0430\u043d\u0433 \u0432\u0430\n\u0430\u0440\u04ef\u0441\u043e\u043d\u0438 \u0445\u0443\u0448\u0431\u0430\u0445\u0442 \u0433\u0430\u0448\u0442\u0443\u0433\u0443\u0437\u043e\u0440 \u043a\u0430\u0440\u0434\u0430, \u043f\u043e\u0440\u0430\u04b3\u043e\u0438 \u043c\u0430\u0442\u043e\u044a \u04b7\u0430\u043c\u044a \u043c\u0435\u0441\u043e\u0437\u0430\u0434\n\u0432\u0430 \u0430\u0437 \u0438\u043d \u043f\u043e\u0440\u0430\u04b3\u043e \u04b3\u0430\u043c\u0440\u043e\u04b3\u0438 \u043f\u0438\u0440\u0430\u0437\u0430\u043d\u04b3\u043e\u0438 \u0445\u0443\u0434\u043e\u04b7\u04ef \u04b7\u043e\u043c\u0430\u0438 \u0441\u0430\u0434\u043f\u043e\u0440\u0430\u0432\u0443 \u0441\u0430\u0434\xad\n\u0440\u0430\u043d\u0433 \u0434\u04ef\u0445\u0442\u0430 \u0431\u0430 \u043a\u04ef\u0434\u0430\u043a\u0430\u0448 \u043c\u0435\u043f\u04ef\u0448\u043e\u043d\u0430\u0434. \u0418\u043d \u04b7\u043e\u043c\u0430 \u043c\u0443\u0432\u043e\u0444\u0438\u049b\u0438 \u043e\u0434\u0430\u0442\u04b3\u043e\u0438\n\u043c\u0430\u0440\u0434\u0443\u043c\u04e3 \u0431\u0430\u0445\u043e\u0441\u0438\u044f\u0442 \u0431\u0443\u0434:")
