B.a6M=new A.a("f10dc124-345a-4169-8e85-6c57b9481021","da5e2975-a8e2-44ce-a30c-0e5d98f73844","\u0492\u0430\u0437\u0430\u043b","\u041c\u0430\u0439\u0438 \u0441\u043e\u0444\u0435 \u0431\u0438\u0451\u0440, \u0430\u0439 \u0431\u0443\u0442, \u043a\u0438 \u0441\u043e\u0444\u0438\u0441\u0442,\n\u04b6\u0430\u04b3\u043e\u043d \u0430\u0437 \u043c\u043e\u04b3 \u0442\u043e \u043e\u043d \u04b7\u043e, \u043a\u0438 \u043c\u043e\u04b3\u0438\u0441\u0442.\n\u0427\u0443 \u0430\u0437 \u043a\u043e\u0445 \u043e\u043c\u0430\u0434\u04e3 \u0431\u0435\u0440\u0443\u043d \u0431\u0430 \u0441\u0430\u04b3\u0440\u043e,\n\u041a\u0443\u04b7\u043e \u0447\u0430\u0448\u043c \u0430\u0444\u043a\u0430\u043d\u04e3 \u0434\u0435\u0431\u043e\u0438 \u0448\u043e\u04b3\u0438\u0441\u0442.\n\u0411\u0438\u0451 \u0442\u043e \u043c\u0430\u0439 \u0445\u04ef\u0440\u0435\u043c\u0443 \u0448\u043e\u0434 \u0431\u043e\u0448\u0435\u043c,\n\u041a\u0438 \u04b3\u0430\u043d\u0433\u043e\u043c\u0438 \u043c\u0430\u044e \u0440\u04ef\u0437\u0438 \u043c\u0430\u043d\u043e\u04b3\u0438\u0441\u0442.")
B.apE=new A.a("e673f57a-53b7-4814-9d60-0839a5054c35","b5252e27-e6c6-401e-aca9-5fec3da36b65","\u0414\u043e\u0441\u0442\u043e\u043d","\u0411\u0430 \u043a\u0430\u0436\u0433\u0443\u0444\u0442\u0430\u043d\u0438\u04b3\u043e \u0448\u0443\u043d\u0430\u0432 \u0440\u043e\u0441\u0442\u043e\u043d,\n\u041a\u0443\u043d\u0430\u043c \u0430\u0437 \u0414\u0430\u049b\u0438\u049b\u04e3 \u044f\u043a\u0435 \u0434\u043e\u0441\u0442\u043e\u043d.\n\u0427\u0443 \u0430\u0437 \u0434\u0430\u0444\u0442\u0430\u0440 \u0438\u043d \u0434\u043e\u0441\u0442\u043e\u043d\u04b3\u043e \u0431\u0430\u0441\u0435\n\u04b2\u0430\u043c\u0435\u0445\u043e\u043d\u0434 \u0445\u043e\u043d\u0430\u043d\u0434\u0430 \u0431\u0430\u0440 \u04b3\u0430\u0440 \u043a\u0430\u0441\u0435,\n\u04b6\u0430\u04b3\u043e\u043d \u0434\u0438\u043b \u043d\u0438\u04b3\u043e\u0434\u0430 \u0431\u0430\u0440 \u0438\u043d \u0434\u043e\u0441\u0442\u043e\u043d,\n\u04b2\u0430\u043c\u0430 \u0431\u0438\u0445\u0440\u0430\u0434\u043e\u043d \u043d\u0438\u0437\u0443 \u04b3\u0430\u043c \u0440\u043e\u0441\u0442\u043e\u043d.\n\u04b6\u0430\u0432\u043e\u043d\u0435 \u0431\u0438\u0451\u043c\u0430\u0434 \u043a\u0443\u0448\u043e\u0434\u0430\u0437\u0430\u0431\u043e\u043d,\n\u0421\u0443\u0445\u0430\u043d \u0433\u0443\u0444\u0442\u0430\u043d\u0438 \u0445\u0443\u0431\u0443 \u0440\u0430\u0432\u0448\u0430\u043d \u0440\u0430\u0432\u043e\u043d\n\xab\u0411\u0430 \u043d\u0430\u0437\u043c \u043e\u0440\u0430\u043c \u0438\u043d \u043d\u043e\u043c\u0430\u0440\u043e, \u0433\u0443\u0444\u0442, \u043c\u0430\u043d,\n\u041a-\u0430\u0437 \u043e\u043d \u0448\u043e\u0434 \u0433\u0430\u0440\u0434\u0430\u0434 \u0434\u0438\u043b\u0438 \u0430\u043d\u04b7\u0443\u043c\u0430\u043d\xbb.\n\u04b6\u0430\u0432\u043e\u043d\u0438\u0448\u0440\u043e \u0445\u04ef\u0438 \u0431\u0430\u0434 \u0451\u0440 \u0431\u0443\u0434,\n\u0410\u0431\u043e \u0431\u0430\u0434 \u04b3\u0430\u043c\u0435\u0448\u0430 \u0431\u0430 \u043f\u0430\u0439\u043a\u043e\u0440 \u0431\u0443\u0434.\n\u0411\u0430\u0440 \u04ef \u0442\u043e\u0445\u0442\u0430\u043d \u043a\u0430\u0440\u0434 \u043d\u043e\u0433\u043e\u04b3 \u043c\u0430\u0440\u0433,\n\u0411\u0430 cap \u0431\u0430\u0440\u043d\u0438\u04b3\u043e\u0434\u0430\u0448 \u044f\u043a\u0435 \u0442\u0438\u0440\u0430 \u0442\u0430\u0440\u0433.\n\u0411\u0430\u0434-\u043e\u043d \u0445\u04ef\u0438 \u0431\u0430\u0434 \u04b7\u043e\u043d\u0438 \u0448\u0438\u0440\u0438\u043d \u0431\u0438\u0434\u043e\u0434,\n\u041d\u0430\u0431\u0443\u0434 \u0430\u0437 \u04b7\u0430\u04b3\u043e\u043d \u0434\u0438\u043b-\u0448 \u044f\u043a \u0440\u04ef\u0437 \u0448\u043e\u0434.\n\u042f\u043a\u043e\u044f\u043a \u0430\u0437 \u04ef \u0431\u0430\u0445\u0442 \u0431\u0430\u0440\u0433\u0430\u0448\u0442\u0430 \u0431\u0443\u0434,\n\u0411\u0430 \u0434\u0430\u0441\u0442\u0438 \u044f\u043a\u0435 \u0431\u0430\u043d\u0434\u0430 - \u0431\u0430\u0440 \u043a\u0443\u0448\u0442\u0430 \u0448\u0443\u0434.\n\u0411\u0438\u0440\u0430\u0444\u0442 \u04ef\u0432\u0443 \u0438\u043d \u043d\u043e\u043c\u0430 \u043d\u043e\u0433\u0443\u0444\u0442\u0430 \u043c\u043e\u043d\u0434,\n\u0427\u0443\u043d\u0438\u043d \u0431\u0430\u0445\u0442\u0438 \u0431\u0435\u0434\u043e\u0440\u0438 \u04ef \u0445\u0443\u0444\u0442\u0430 \u043c\u043e\u043d\u0434.\n\u0425\u0443\u0434\u043e\u0451, \u0431\u0443\u0431\u0430\u0445\u0448\u043e \u0433\u0443\u043d\u043e\u04b3\u0438 \u0432\u0430\u0440\u043e,\n\u0411\u0438\u044f\u0444\u0437\u043e\u0439 \u0434\u0430\u0440 \u04b3\u0430\u0448\u0440 \u04b7\u043e\u04b3\u0438 \u0432\u0430\u0440\u043e.\n\u041a\u0443\u043d\u0443\u043d \u043f\u0430\u0440\u0434\u0430 \u0431\u0430\u0440\u0434\u043e\u0440\u0430\u043c \u0430\u0437 \u049b\u0438\u0441\u0441\u0430\u0430\u0448,\n\u0411\u0430 \u043e\u043b\u0430\u043c \u0431\u0438\u043c\u043e\u043d\u0430\u043c \u044f\u043a\u0435 \u04b3\u0438\u0441\u0441\u0430\u0430\u0448.")
B.ad2=new A.a("46882bcb-983e-4277-b9f8-ba3ec141ef90","bcb9a591-92bb-405b-bcf5-f58a6aaa65cc","\u0420\u0443\u0431\u043e\u04e3",u.v)
B.akD=new A.a("4388b41f-a6cf-4210-a1eb-16364de089a8","5fc69b51-c38a-4427-a362-5c8a14bca835","\u0420\u0443\u0431\u043e\u04e3","\u0411\u0430\u0440 \u043a\u04ef\u0437\u0430\u0433\u0430\u0440\u0435 \u043f\u0430\u0440\u0435\u0440 \u043a\u0430\u0440\u0434\u0430\u043c \u0433\u0443\u0437\u0430\u0440\u0435,\n\u0410\u0437 \u0445\u043e\u043a \u04b3\u0430\u043c\u0435\u043d\u0430\u043c\u0443\u0434 \u04b3\u0430\u0440 \u0434\u0430\u043c \u04b3\u0443\u043d\u0430\u0440\u0435.\n\u041c\u0430\u043d \u0434\u0438\u0434\u0430\u043c, \u0430\u0433\u0430\u0440 \u043d\u0430\u0434\u0438\u0434 \u04b3\u0430\u0440 \u0431\u0435\u0431\u0430\u0441\u0430\u0440\u0435,\n\u0425\u043e\u043a\u0438 \u043f\u0430\u0434\u0430\u0440\u043e\u043d \u0434\u0430\u0440 \u043a\u0430\u0444\u0438 \u04b3\u0430\u0440 \u043a\u04ef\u0437\u0430\u0433\u0430\u0440\u0435.")
B.ag5=new A.a("1e67d4d0-db17-44d7-91d4-4c997f36b902","1e198617-8771-4891-8f1e-521ce20c7a53","\u0492\u0430\u0437\u0430\u043b","\u0414\u0438\u043b \u043c\u0443\u049b\u0438\u043c\u0438 \u043a\u04ef\u0439\u0438 \u04b7\u043e\u043d\u043e\u043d \u0430\u0441\u0442\u0443 \u043c\u0430\u043d \u0438\u043d \u04b7\u043e \u0493\u0430\u0440\u0438\u0431,\n\u0427\u0443\u043d \u043a\u0443\u043d\u0430\u0434 \u0431\u0435\u0447\u043e\u0440\u0430\u0438 \u043c\u0438\u0441\u043a\u0438\u043d \u0442\u0430\u043d\u0438 \u0442\u0430\u043d\u04b3\u043e \u0493\u0430\u0440\u0438\u0431...\n\u0414\u0430\u0440 \u0493\u0430\u0440\u0438\u0431\u04e3 \u04b7\u043e\u043d \u0431\u0430 \u0441\u0430\u0445\u0442\u04e3 \u043c\u0435\u0434\u0438\u04b3\u0430\u0434 \u043c\u0438\u0441\u043a\u0438\u043d \u041a\u0430\u043c\u043e\u043b,\n\u0412\u043e \u0493\u0430\u0440\u0438\u0431\u04e3, \u0432\u043e \u0493\u0430\u0440\u0438\u0431\u04e3, \u0432\u043e \u0493\u0430\u0440\u0438\u0431\u043e, \u0432\u043e \u0493\u0430\u0440\u0438\u0431.")
B.a9d=new A.a("a027ed91-0abe-45c7-a938-b9bd8eaae97d","dea74b1e-32da-4afc-862f-4a08fd22f8f5","\u0428\u0435\u044a\u0440","\u0410\u0433\u0430\u0440 \u0434\u04ef\u0441\u0442 \u043c\u0435\u04b3\u043c\u043e\u043d \u0431\u0443\u0432\u0430\u0434 \u0451 \u043d\u0430 \u0434\u04ef\u0441\u0442,\n\u0428\u0430\u0431\u0443 \u0440\u04ef\u0437 \u0442\u0435\u043c\u043e\u0440\u0438 \u043c\u0435\u04b3\u043c\u043e\u043d \u043d\u0430\u043a\u0443\u0441\u0442.")
B.aro=new A.a("423039a2-aaa2-440a-9457-7cf5c5019187","11c85433-4042-4e24-95fb-ccc37ef0d2ea","\u0422\u0430\u0440\u04b7\u0435\u044a\u0431\u0430\u043d\u0434","\u04b2\u0430\u043c\u0435\u0433\u0443\u0444\u0442\u0430\u043c, \u043a\u0438 \u043a\u0430\u0439 \u0431\u043e\u0448\u0430\u0434, \u043a\u0438 \u0445\u0443\u0440\u0440\u0430\u043c \u0440\u04ef\u0437\u0433\u043e\u0440 \u043e\u044f\u0434,\n\u04b6\u0430\u04b3\u043e\u043d \u0430\u0437 cap \u04b7\u0430\u0432\u043e\u043d \u0433\u0430\u0440\u0434\u0430\u0434, \u0431\u0430\u04b3\u043e\u0440\u0438 \u0493\u0430\u043c\u0433\u0443\u0441\u043e\u0440 \u043e\u044f\u0434.\n\u0411\u0430\u04b3\u043e\u0440\u0438 \u0493\u0430\u043c\u0433\u0443\u0441\u043e\u0440 \u043e\u044f\u0434, \u043a\u0438 \u04b3\u0430\u0440 \u043a\u0430\u0441\u0440\u043e \u0431\u0430 \u043a\u043e\u0440 \u043e\u044f\u0434,\n\u0411\u0430\u04b3\u043e\u0440\u0435, \u043a-\u0430\u043d\u0434\u0430\u0440 \u04ef \u04b3\u0430\u0440 \u0440\u04ef\u0437 \u043c\u0430\u0439\u0440\u043e \u0445\u043e\u0441\u0442\u043e\u0440\n\u043e\u044f\u0434.\n\u0417\u0438 \u04b3\u0430\u0440 \u0431\u043e\u0434\u0435, \u043a\u0438 \u0431\u0430\u0440\u0445\u0435\u0437\u0430\u0434, \u043a\u0443\u043d\u0443\u043d \u0431\u04ef\u0438 \u0431\u0430\u04b3\u043e\u0440 \u043e\u044f\u0434,\n\u041a\u0443\u043d\u0443\u043d \u043c\u043e\u0440\u043e \u0437\u0438 \u0431\u043e\u0434\u0438 \u0431\u043e\u043c\u0434\u043e\u0434\u04e3 \u0431\u04ef\u0438 \u0451\u0440 \u043e\u044f\u0434.\n\u0427\u0443 \u0440\u04ef\u0439\u0438 \u043a\u04ef\u0434\u0430\u043a\u043e\u043d\u0438 \u043c\u043e \u0434\u0430\u0440\u0430\u0445\u0442\u0438 \u0433\u0443\u043b \u0431\u0430 \u0431\u043e\u0440 \u043e\u044f\u0434,\n\u041d\u0438\u0433\u043e\u0440\u0438 \u043b\u043e\u043b\u0430\u0440\u0443\u0445 \u0431\u043e \u043c\u043e \u0431\u0430 \u0445\u0443\u0440\u0440\u0430\u043c \u043b\u043e\u043b\u0430\u0437\u043e\u0440 \u043e\u044f\u0434.\n\u041c\u0430\u0439\u0438 \u043c\u0443\u0448\u043a\u0438\u043d \u0433\u0443\u0441\u043e\u0440\u0430\u0434 \u0442\u043e \u0433\u0430\u04b3\u0438 \u0431\u04ef\u0441\u0443 \u043a\u0430\u043d\u043e\u0440 \u043e\u044f\u0434,\n\u0427\u0430\u0440\u043e \u0445\u0443\u0448 \u0433\u0430\u0440\u0434\u0430\u0434\u0443 \u0431\u043e \u0442\u0430\u0431\u044a\u0438 \u0445\u0443\u0441\u0440\u0430\u0432 \u0441\u043e\u0437\u0433\u043e\u0440 \u043e\u044f\u0434...\n\u041a\u0438\u0440\u043e \u043c\u0430\u0439 \u0445\u04ef\u0440\u0434\u0430\u043d \u043e\u0439\u0438\u043d \u0430\u0441\u0442, \u043c\u0430\u0439 \u0445\u04ef\u0440\u0434\u0430\u043d \u043a\u0443\u043d\u0443\u043d \u0431\u043e\u044f\u0434,\n\u0411\u0438\u043f\u0443\u0440\u0441 \u0430\u0437 \u043c\u0430\u043d, \u043a\u0438 \u043c\u0430\u0439 \u0445\u04ef\u0440\u0434\u0430\u043d \u0434\u0430\u0440 \u0438\u043d \u0430\u0439\u0451\u043c \u0447\u0443\u043d \u0431\u043e\u044f\u0434?\n\u041d\u0430\u0445\u0443\u0441\u0442 \u0430\u043d\u0434\u0430\u0440 \u043c\u0438\u0451\u043d \u0431\u043e\u0440\u0435 \u043c\u0430\u0439\u0438 \u0431\u0435\u04b7\u043e\u0434\u0430\u0433\u0443\u043d\n\u0431\u043e\u044f\u0434,\n\u041f\u0430\u0441 \u043e\u043d \u0433\u0430\u04b3 \u0441\u043e\u049b\u0438\u0438 \u043f\u043e\u043a\u0438\u0437\u0430 \u0447\u0443\u043d \u0441\u0438\u043c\u0438\u043d\u0441\u0443\u0442\u0443\u043d \u0431\u043e\u044f\u0434.\n\u0414\u0443-\u0441\u0435 \u0440\u04ef\u0437\u0435 \u0431\u0430 \u044f\u043a \u04b7\u043e \u0441\u043e\u0445\u0442\u0430 \u0447\u0443\u043d \u0430\u0440\u0493\u0443\u043d\u0443\u043d\n\u0431\u043e\u044f\u0434,\n\u0445\u043e\u04b3\u0438\u0448, \u043c\u0430\u0439\u043b.\n\u0441\u0443\u0440\u0445\u0440\u0430\u043d\u0433.\n\u043d\u043e\u043c\u0438 \u0430\u0441\u0431\u043e\u0431\u0438 \u043c\u0443\u0441\u0438\u049b\u04e3.\n\u0421\u0443\u0440\u0443\u0434\u0438 \u043c\u0443\u0442\u0440\u0438\u0431\u0438 \u0441\u043e\u0434\u0430 \u04b3\u0430\u043c\u043e\u0440\u0430\n\u0440\u0430\u04b3\u043d\u0430\u043c\u0443\u043d \u0431\u043e\u044f\u0434.\n\u0411\u0430 \u04b3\u0430\u0440 \u0440\u04ef\u0437\u0435, \u043a\u0438 \u043c\u0430\u0439 \u0445\u04ef\u0440\u0434\u04e3, \u0442\u0430\u0440\u0430\u0431 \u043a\u0430\u0440\u0434\u0430\u043d \u0444\u0443\u0437\u0443\u043d \u043e\u044f\u0434,\n\u041c\u0443\u0432\u043e\u0444\u0438\u049b \u0434\u04ef\u0441\u0442\u043e\u043d \u044f\u043a \u0434\u0438\u043b \u04b3\u0430\u043c\u0435 \u043d\u0435\u043a\u043e\u0437\u043c\u0443\u043d \u0431\u043e\u044f\u0434.\n\u0414\u0438\u043b \u0430\u043d\u0434\u0430\u0440 \u0448\u043e\u0434\u0438\u044e \u0440\u043e\u043c\u0438\u0448 \u0431\u0430 \u043e\u0440\u043e\u043c\u0443 \u0441\u0443\u043a\u0443\u043d \u0431\u043e\u044f\u0434,\n\u0417\u0438 \u043c\u0430\u04b7\u043b\u0438\u0441 \u0434\u0443\u0448\u043c\u0430\u043d\u0438 \u0445\u0443\u0441\u0440\u0430\u0432 \u0431\u0430 \u04b3\u0430\u0440 \u04b3\u043e\u043b\u0435 \u0431\u0443\u0440\u0443\u043d \u043e\u044f\u0434...\n\u0411\u0430\u04b3\u043e\u0440 \u043e\u043c\u0430\u0434 \u04b3\u0430\u043c\u0435\u0433\u04ef\u04e3 \u0431\u0438\u0440\u0430\u0432 \u0442\u043e \u0433\u0443\u043b \u0431\u0430 \u0431\u043e\u0440 \u043e\u044f\u0434,\n\u04b2\u0430\u043c\u0435 \u043d\u0430\u0432\u043c\u0435\u0434\u0438\u044f\u043c \u0437-\u0438\u043d \u0432\u0430\u044a\u0434\u0430\u0438 \u043d\u0430\u0432\u043c\u0435\u0434\u0432\u043e\u0440 \u043e\u044f\u0434.\n\u0422\u0443\u0440\u043e \u0437-\u0438\u043d \u0432\u0430\u044a\u0434\u0430 \u0430\u043d\u0434\u0430\u0440 \u0434\u0438\u043b \u0431\u0430 \u0440\u04ef\u0437\u0435 \u0441\u0430\u0434 \u04b3\u0430\u0437\u043e\u0440 \u043e\u044f\u0434,\n\u041c\u0430\u0440\u043e, \u043e\u0440\u0435, \u0431\u0430\u0434-\u0438\u043d \u0433\u0443\u0444\u0442\u043e\u0440\u0430\u0442, \u044d\u0439 \u04b7\u043e\u043d, \u0443\u0441\u0442\u0443\u0432\u043e\u0440 \u043e\u044f\u0434.\n\u0427\u0443 \u0447\u0438\u0437\u0435 \u0430\u0437 \u0442\u0443 \u0431\u0438\u0448\u043d\u0438\u0434\u0430\u043c \u0434\u0438\u043b \u043e\u043d\u0440\u043e \u0445\u043e\u0441\u0442\u043e\u0440 \u043e\u044f\u0434,\n\u0413\u0430\u0440 \u0430\u043d\u0434\u0430\u0440 \u0434\u0438\u043b \u043d\u0430\u0434\u043e\u0440\u04e3 \u0431\u043e\u0434 \u043f\u0430\u0439\u043c\u0443\u0434\u0430\u043d\n\u0447\u04e3 \u043a\u043e\u0440 \u043e\u044f\u0434?\n\u0422\u0443\u0440\u043e \u0442\u0430\u0440\u0441\u0430\u043c, \u043a\u0438 \u0431\u04ef\u0441\u0438 \u043c\u0430\u043d \u04b3\u0430\u043c\u0435 \u0431\u0430\u0440 \u0447\u0430\u0448\u043c \u0445\u043e\u0440 \u043e\u044f\u0434,\n\u041d\u0430\u0434\u043e\u043d\u04e3, \u043a-\u0438\u043d \u043b\u0430\u0431\u0438 \u043c\u0430\u043d \u0431\u0430\u0440 \u0431\u0438\u0441\u043e\u0442\u0438 \u0448\u0430\u04b3\u0440\u0438\u0451\u0440 \u043e\u044f\u0434...")
B.adE=new A.a("1d4842bb-aa2a-47b4-9164-9f3085c292df","11c85433-4042-4e24-95fb-ccc37ef0d2ea","\u041d\u0430\u043c\u0443\u043d\u0430\u04b3\u043e \u0430\u0437 \u049b\u0430\u0441\u0438\u0434\u0430\u04b3\u043e","\u0411\u0430\u0434-\u0438\u043d \u0445\u0443\u0440\u0440\u0430\u043c\u04e3 \u04b7\u0430\u04b3\u043e\u043d, \u0431\u0430\u0434-\u0438\u043d \u0442\u043e\u0437\u0430\u0433\u04e3 \u0431\u0430\u04b3\u043e\u0440,\n\u0411\u0430\u0434-\u0438\u043d \u0440\u0430\u0432\u0448\u0430\u043d\u04e3 \u0448\u0430\u0440\u043e\u0431, \u0431\u0430\u0434-\u0438\u043d \u043d\u0430\u043a\u0443\u04e3 \u043d\u0438\u0433\u043e\u0440.\n\u042f\u043a\u0435 \u0447\u0443\u043d \u0431\u0438\u04b3\u0438\u0448\u0442\u0438 \u0430\u0434\u043d\n\u044f\u043a\u0435 \u0447\u0443\u043d \u04b3\u0430\u0432\u043e\u0438 \u0434\u04ef\u0441\u0442,\n\u042f\u043a\u0435 \u0447\u0443\u043d \u0433\u0443\u043b\u043e\u0431\u0438 \u0411\u0430\u043b\u0445, \u044f\u043a\u0435 \u0447\u0443\u043d \u0431\u0443\u0442\u0438 \u0411\u0430\u04b3\u043e\u0440.\n\u0417\u0430\u043c\u0438\u043d \u0430\u0437 \u0441\u0438\u0440\u0438\u0448\u043a\u0438 \u0430\u0431\u0440, \u04b3\u0430\u0432\u043e \u0430\u0437 \u043d\u0430\u0441\u0438\u043c\u0438 \u0433\u0443\u043b,\n\u0414\u0430\u0440\u0430\u0445\u0442 \u0430\u0437 \u04b7\u0430\u043c\u043e\u043b\u0438 \u0431\u0430\u0440\u0433, \u0441\u0430\u0440\u0438 \u043a\u04ef\u04b3 \u0437\u0438 \u043b\u043e\u043b\u0430\u0437\u043e\u0440.\n\u042f\u043a\u0435 \u0447\u0443\u043d \u043f\u0430\u0440\u0430\u043d\u0434\u0438\n\u0441\u0430\u0431\u0437, \u044f\u043a\u0435 \u0447\u0443\u043d \u0430\u0431\u0438\u0440\u0438\n\u0445\u0443\u0448,\n\u042f\u043a\u0435 \u0447\u0443\u043d \u0430\u0440\u04ef\u0441\u0438 \u0445\u0443\u0431, \u044f\u043a\u0435 \u0447\u0443\u043d \u0440\u0443\u0445\u043e\u043d\u0438 \u0451\u0440.\n\u04b3\u0430\u043c\u0432\u043e\u0440\u0430, \u0434\u043e\u0438\u043c, \u04b3\u0430\u043c\u0435\u0448\u0430.\n\u04b7\u0443\u0441\u0442\u0443\u04b7\u04ef, \u043a\u043e\u0444\u0442\u0430\u043d \u0432\u0430 \u0438\u043d \u04b7\u043e \u0431\u043e\u0434 \u043f\u0430\u0439\u043c\u0443\u0434\u0430\u043d \u0431\u0430 \u043c\u0430\u044a\u043d\u0438\u0438 \u043a\u043e\u0440\u0438\n\u0431\u0435\u04b3\u0443\u0434\u0430 \u043e\u043c\u0430\u0434\u0430\u0430\u0441\u0442.\n\u0431\u043e\u0493\u0438 \u0431\u0438\u04b3\u0438\u0448\u0442, \u0424\u0438\u0440\u0434\u0430\u0432\u0441.\n\u044f\u043a \u043d\u0430\u0432\u044a \u043c\u0430\u0442\u043e\u0438 \u0430\u0431\u0440\u0435\u0448\u0438\u043c\u04e3; \u04b3\u0430\u0440\u0438\u0440, \u043d\u0430\u0440\u043c.\n\u043d\u0430\u0432\u044a\u0435 \u0430\u0437 \u0445\u0443\u0448\u0431\u04ef\u0438\u04b3\u043e.\n\u0422\u0430\u0437\u0430\u0440\u0432\u0438 \u0430\u049b\u0438\u049b\u0440\u04ef\u0439, \u043a\u0443\u043b\u0430\u043d\u0433\u0438 \u0441\u0430\u043f\u0435\u0434\u0440\u0443\u0445,\n\u0413\u0430\u0432\u0430\u0437\u043d\u0438 \u0441\u0438\u0451\u04b3\u0447\u0430\u0448\u043c, \u043f\u0430\u043b\u0430\u043d\u0433\u0438 \u0441\u0438\u0442\u0435\u0437\u0430\u043a\u043e\u0440.\n\u042f\u043a\u0435 \u0445\u0443\u0444\u0442\u0430 \u0431\u0430\u0440 \u043f\u0430\u0440\u0430\u043d\u0434, \u044f\u043a\u0435 \u0445\u0443\u0444\u0442\u0430 \u0431\u0430\u0440 \u04b3\u0430\u0440\u0438\u0440,\n\u042f\u043a\u0435 \u0440\u0430\u0441\u0442\u0430 \u0430\u0437 \u043d\u0443\u04b3\u0443\u0444\u0442, \u044f\u043a\u0435 \u04b7\u0430\u0441\u0442\u0430 \u0430\u0437 \u04b3\u0438\u0441\u043e\u0440.\n\u0417\u0438 \u0431\u0443\u043b\u0431\u0443\u043b \u0441\u0443\u0440\u0443\u0434\u0438 \u0445\u0443\u0448, \u0437\u0438 \u0441\u0443\u043b\u0441\u0443\u043b\n\u043d\u0430\u0432\u043e\u0438 \u043d\u0430\u0493\u0437,\n\u0417\u0438 \u0441\u043e\u0440\u04e3 \u04b3\u0430\u0434\u0438\u0441\u0438 \u0445\u0443\u0431, \u0437\u0438 \u049b\u0443\u043c\u0440\u04e3 \u0445\u0443\u0440\u04ef\u0448\u0438 \u0437\u043e\u0440.\n\u042f\u043a\u0435 \u0431\u0430\u0440 \u043a\u0430\u043d\u043e\u0440\u0438 \u0433\u0443\u043b, \u044f\u043a\u0435 \u0434\u0430\u0440 \u043c\u0438\u0451\u043d\u0438 \u0431\u0435\u0434,\n\u042f\u043a\u0435 \u0437\u0435\u0440\u0438 \u0448\u043e\u0445\u0438 \u0441\u0430\u0440\u0432, \u044f\u043a\u0435 \u0431\u0430\u0440 \u0441\u0430\u0440\u0438 \u0447\u0430\u043d\u043e\u0440.\n\u04b2\u0430\u0432\u043e \u0445\u0443\u0440\u0440\u0430\u043c \u0430\u0437 \u043d\u0430\u0441\u0438\u043c, \u0437\u0430\u043c\u0438\u043d \u0445\u0443\u0440\u0440\u0430\u043c \u0430\u0437 \u043b\u0438\u0431\u043e\u0441,\n\u04b6\u0430\u04b3\u043e\u043d \u0445\u0443\u0440\u0440\u0430\u043c \u0430\u0437 \u04b7\u0430\u043c\u043e\u043b, \u043c\u0430\u043b\u0438\u043a \u0445\u0443\u0440\u0440\u0430\u043c \u0430\u0437 \u0448\u0438\u043a\u043e\u0440.\n\u042f\u043a\u0435 \u043c\u0443\u0448\u043a \u0434\u0430\u0440 \u0434\u0430\u04b3\u043e\u043d, \u044f\u043a\u0435 \u04b3\u0443\u043b\u043b\u0430 \u0431\u0430\u0440 \u043a\u0430\u0442\u0430\u0444\n\u042f\u043a\u0435 \u043e\u0440\u0437\u0443 \u0431\u0430 \u0434\u0430\u0441\u0442, \u044f\u043a\u0435 \u0434\u04ef\u0441\u0442 \u0434\u0430\u0440 \u043a\u0430\u043d\u043e\u0440...")
B.a65=new A.a("fd38e241-d0ca-43b0-bae7-2ca70aedfc65","11c85433-4042-4e24-95fb-ccc37ef0d2ea","\u0411\u0430\u04b3\u043e\u0440\u0438\u044f","\u0418\u043c\u0441\u043e\u043b \u0442\u043e\u0437\u0430\u0440\u04ef\u0439\u0442\u0430\u0440 \u043e\u043c\u0430\u0434 \u04b3\u0430\u043c\u0435 \u0431\u0430\u04b3\u043e\u0440,\n\u04b2\u0430\u043d\u0433\u043e\u043c\u0438 \u043e\u043c\u0430\u0434\u0430\u043d \u043d\u0430 \u0431\u0430\u0434\u2013\u0438\u043d \u0433\u0443\u043d\u0430 \u0431\u0443\u0434 \u043f\u043e\u0440\n.\n\u041f\u043e\u0440 \u0430\u0437 \u0440\u0430\u04b3 \u0430\u043d\u0434\u0430\u0440 \u043e\u043c\u0430\u0434 \u0447\u0443\u043d \u043c\u0443\u0444\u043b\u0438\u0441\u0438 \u0493\u0430\u0440\u0438\u0431,\n\u0411\u0435\u0444\u0430\u0440\u0448\u0443 \u0431\u0435\u0442\u0430\u04b7\u0430\u043c\u043c\u0443\u043b\u0443 \u0431\u0435\u0440\u0430\u043d\u0433\u0443 \u0431\u0435\u043d\u0438\u0433\u043e\u0440.\n\u0412-\u0438\u043c\u0441\u043e\u043b \u043f\u0435\u0448 \u0430\u0437 \u043e\u043d \u043a\u0438 \u0434\u0430\u0440 \u043c\u0430\u043d\u0437\u0438\u043b\u0435 \u0440\u0430\u0441\u0430\u0434,\n\u0410\u043d\u0434\u0430\u0440 \u043a\u0430\u0448\u0438\u0434 \u04b3\u0443\u043b\u043b\u0430 \u0431\u0430 \u0434\u0430\u0448\u0442\u0443 \u0431\u0430 \u043a\u04ef\u04b3\u0441\u043e\u0440.\n\u0411\u0430\u0440 \u0434\u0430\u0441\u0442\u0438 \u0431\u0435\u0434 \u0431\u0430\u0441\u0442 \u0437\u0438 \u043f\u0438\u0440\u04ef\u0437\u0430 \u0434\u0430\u0441\u0442\u0431\u0430\u043d\u0434,\n\u0414\u0430\u0440 \u0433\u04ef\u0448\u0438 \u0433\u0443\u043b \u0444\u0438\u0433\u0430\u043d\u0434 \u0437\u0438 \u0431\u0435\u04b7\u043e\u0434\u0430 \u0433\u04ef\u0448\u0432\u043e\u0440.\n\u0410\u0437 \u043a\u04ef\u04b3 \u0442\u043e \u0431\u0430 \u043a\u04ef\u04b3 \u0431\u0443\u043d\u0430\u0444\u0448\u0430\u0441\u0442\u0443 \u0448\u0430\u043d\u0431\u0430\u043b\u0438\u0434\n,\n\u0410\u0437 \u043f\u0443\u0448\u0442\u0430 \u0442\u043e \u0431\u0430 \u043f\u0443\u0448\u0442\u0430 \u0441\u0443\u043c\u0430\u043d\u0437\u043e\u0440\u0443 \u043b\u043e\u043b\u0430\u0437\u043e\u0440.\n\u0413\u04ef\u0439\u04e3, \u043a\u0438 \u0440\u0438\u0448\u0442\u0430\u04b3\u043e\u0438 \u0430\u049b\u0438\u049b \u0430\u0441\u0442\u0443 \u043b\u043e\u0436\u0432\u0430\u0440\u0434\n,\n\u0410\u0437 \u043b\u043e\u043b\u0430\u0432\u0443 \u0431\u0443\u043d\u0430\u0444\u0448\u0430 \u04b3\u0430\u043c\u0435 \u0440\u04ef\u0439\u0438 \u043c\u0430\u0440\u0493\u0437\u043e\u0440...\n\u0413\u0443\u043b\u0431\u0443\u043d \u043f\u0430\u0440\u0430\u043d\u0434\u0438 \u043b\u0430\u044a\u043b \u04b3\u0430\u043c\u0435 \u0431\u0430\u0440\u043a\u0443\u043d\u0430\u0434 \u0431\u0430 cap,\n\u0411\u043e\u0440\u043e\u043d\u0438 \u0433\u0443\u043b\u043f\u0430\u0440\u0430\u0441\u0442 \u04b3\u0430\u043c\u0435 \u0433\u0443\u0441\u0442\u0430\u0440\u0430\u0434 \u043d\u0438\u0441\u043e\u0440...\n\u0418\u043d \u0441\u043e\u0437\u04b3\u043e, \u043a\u0438 \u0441\u043e\u0445\u0442 \u0431\u0430\u04b3\u043e\u0440, \u0430\u0437 \u043f\u0430\u0439\u0438 \u0447\u04e3 \u0441\u043e\u0445\u0442?\n\u0418\u043c\u0441\u043e\u043b \u0447\u0443\u043d \u0437\u0438 \u043f\u043e\u0440 \u0444\u0443\u0437\u0443\u043d \u0441\u043e\u0445\u0442\u0430 \u043d\u0438\u0433\u043e\u0440.\n\u0420\u043e\u0437\u0435\u0441\u0442 \u0438\u043d \u043c\u0438\u0451\u043d\u0438 \u0431\u0430\u04b3\u043e\u0440\u0443 \u043c\u0438\u0451\u043d\u0438 \u043c\u0430\u043d,\n\u0425\u0435\u0437\u0430\u043c \u0431\u0430 \u043f\u0435\u0448\u0438 \u0445\u043e\u04b7\u0430 \u043a\u0443\u043d\u0430\u043c \u0440\u043e\u0437\u0430\u0448 \u043e\u0448\u043a\u043e\u0440.\n\u043d\u0430\u0432\u044a\u0438 \u043f\u0430\u0440\u0430\u043d\u0434\u0430.\n\u0431\u043e\u0437\u0443, \u043a\u0438\u0442\u0444.\n\u043f\u043e\u0440\u0441\u043e\u043b, \u0441\u043e\u043b\u0438 \u0433\u0443\u0437\u0430\u0448\u0442\u0430.\n\u043d\u043e\u043c\u0438 \u0433\u0438\u0451\u04b3.\n\u043b\u043e\u04b7\u0443\u0432\u0430\u0440\u0434.\n\u04b2\u0430\u0440\u0441\u043e\u043b\u0430 \u0447\u0443\u043d \u0431\u0430\u04b3\u043e\u0440 \u0437\u0438 \u0440\u043e\u04b3 \u0430\u043d\u0434\u0430\u0440 \u043e\u043c\u0430\u0434\u04e3,\n\u04b6\u043e\u0439\u0435 \u043d\u0430\u0451\u0444\u0442\u04e3, \u043a\u0438 \u0434\u0430\u0440 \u04ef \u0451\u0431\u0430\u0434\u04e3 \u049b\u0430\u0440\u043e\u0440.\n\u0411\u0430\u0440 \u0441\u0430\u043d\u0433\u043b\u043e\u0445\u0443 \u0434\u0430\u0448\u0442 \u0444\u0443\u0440\u0443\u0434 \u043e\u043c\u0430\u0434\u04e3 \u0445\u0438\u04b7\u0438\u043b,\n\u0410\u043d\u0434\u0430\u0440 \u043c\u0438\u0451\u043d\u0438 \u0445\u043e\u0440\u0430\u0432\u0443 \u0430\u043d\u0434\u0430\u0440 \u043c\u0438\u0451\u043d\u0438 \u0445\u043e\u0440.\n\u041f\u0438\u043d\u0434\u043e\u0448\u0442\u04e3, \u043a\u0438 \u0445\u043e\u0440 \u0448\u0443\u0434\u0430\u0441\u0442\u04e3 \u043c\u0438\u0451\u043d\u0438 \u0445\u0430\u043b\u049b,\n\u0411\u0435\u0434\u0438\u043b \u0448\u0430\u0432\u0430\u0434 \u0430\u0437\u0438\u0437, \u043a\u0438 \u0433\u0430\u0440\u0434\u0430\u0434 \u0437\u0430\u043b\u0438\u043b\u0443 \u0445\u043e\u0440.\n\u0418\u043c\u0441\u043e\u043b \u043d\u043e\u043c\u0430 \u043a\u0430\u0440\u0434 \u0441\u04ef\u0439\u0438 \u04ef \u0448\u0430\u043c\u043e\u043b\u0443 \u0433\u0443\u0444\u0442:\n\u041c\u0443\u0436\u0434\u0430 \u0442\u0443\u0440\u043e, \u043a\u0438 \u0445\u043e\u04b7\u0430 \u0442\u0443\u0440\u043e \u0433\u0430\u0448\u0442 \u0445\u043e\u0441\u0442\u043e\u0440.\n\u0411\u043e\u0493\u0435, \u0437\u0438 \u0431\u0430\u04b3\u0440\u0438 \u0442\u0443 \u0437\u0438 \u043d\u0430\u0432 \u0430\u0444\u0433\u0430\u043d\u0434 \u0447\u0443\u043d \u0431\u0438\u04b3\u0438\u0448\u0442,\n\u0414\u0430\u0440 \u043f\u0435\u0448\u0438 \u04ef \u0431\u0430 \u0441\u043e\u043d\u0438 \u0441\u0438\u043f\u0435\u04b3\u0440\u0435 \u044f\u043a\u0435 \u04b3\u0438\u0441\u043e\u0440.\n\u0411\u043e\u0493\u0435, \u0447\u0443 \u0445\u04ef\u0438 \u0445\u0435\u0448 \u043f\u0438\u0441\u0430\u043d\u0434\u0438\u0434\u0430\u0432\u0443 \u0431\u0430\u0434\u0435\u044a,\n\u041a\u043e\u0445\u0435, \u0447\u0443 \u0440\u043e\u0439\u0438 \u0445\u0435\u0448 \u043c\u0443\u04b3\u0430\u0439\u0451\u0432\u0443 \u0443\u0441\u0442\u0443\u0432\u043e\u0440.\n\u0411\u043e\u0493\u0435, \u043a-\u0430\u0437 \u04ef \u0431\u0443\u0440\u0438\u0434\u0430 \u0431\u0443\u0432\u0430\u0434 \u0434\u0430\u0441\u0442\u0438 \u04b3\u043e\u0434\u0438\u0441\u043e\u0442,\n\u041a\u043e\u0445\u0435, \u043a-\u0430\u0437 \u04ef \u043a\u0430\u0448\u0438\u0434\u0430 \u0431\u0443\u0432\u0430\u0434 \u0434\u0430\u0441\u0442\u0438 \u0440\u04ef\u0437\u0433\u043e\u0440.\n\u0411\u043e\u0493\u0435, \u0447\u0443 \u043d\u0435\u044a\u043c\u0430\u0442\u0438 \u043c\u0430\u043b\u0438\u043a\u043e\u043d \u043d\u043e\u043c\u0434\u043e\u0440\u0443 \u0445\u0443\u0448,\n\u041a\u043e\u0445\u0435, \u0447\u0443 \u0440\u04ef\u0437\u0433\u043e\u0440\u0438 \u04b7\u0430\u0432\u043e\u043d\u043e\u043d \u0443\u043c\u0435\u0434\u0432\u043e\u0440.\n\u0411\u043e\u0493\u0435, \u043a\u0438 \u043d\u0438\u043c\u0430\u0435 \u043d\u0430\u0442\u0430\u0432\u043e\u043d \u0433\u0430\u0448\u0442 \u0437-\u04ef \u0442\u0430\u043c\u043e\u043c,\n\u0413\u0430\u0440 \u044f\u043a \u043c\u0430\u04b3\u0435 \u0442\u0430\u043c\u043e\u043c \u043a\u0443\u043d\u04e3 \u0430\u043d\u0434\u0430\u0440 \u04ef \u0433\u0443\u0437\u043e\u0440.\n\u04b2\u0430\u0440 \u0442\u0430\u0445\u0442\u0430\u0435, \u0430\u0437 \u04ef \u0447\u0443 \u0441\u0438\u043f\u0435\u04b3\u0440 \u0430\u0441\u0442 \u0431\u0435\u043a\u0430\u0440\u043e\u043d,\n\u04b2\u0430\u0440 \u0434\u0430\u0441\u0442\u0430\u0435 \u0430\u0437 \u04ef \u0447\u0443 \u0431\u0438\u04b3\u0438\u0448\u0442 \u0430\u0441\u0442 \u0431\u0435\u043a\u0430\u043d\u043e\u0440.\n\u0421\u0435\u0441\u0430\u0434 \u04b3\u0430\u0437\u043e\u0440 \u0433\u0443\u043d\u0430 \u0431\u0443\u0442 \u0430\u0441\u0442 \u0430\u043d\u0434\u0430\u0440 \u04ef \u0431\u0430 \u043f\u043e\u0439,\n\u04b2\u0430\u0440 \u044f\u043a \u0447\u0443\u043d\u043e\u043d, \u043a\u0438 \u0445\u0438\u0440\u0430 \u0448\u0430\u0432\u0430\u0434 \u0437-\u04ef \u0431\u0443\u0442\u0438 \u0431\u0430\u04b3\u043e\u0440.\n\u0410\u0437 \u0430\u0440\u0493\u0430\u0432\u043e\u043d\u0443 \u0451\u0441\u0443\u043c\u0430\u043d\u0443 \u0445\u0430\u0439\u0440\u0438\u044e \u0441\u0443\u043c\u0430\u043d,\n\u0412-\u0430\u0437 \u0441\u0430\u0440\u0432\u0438 \u043d\u0430\u0432\u0440\u0430\u0441\u0438\u0434\u0430\u0432\u0443 \u0433\u0443\u043b\u04b3\u043e\u0438 \u043a\u043e\u043c\u0433\u043e\u0440...\n\u0414\u0430\u0440 \u0437\u0435\u0440\u0438 \u04b3\u0430\u0440 \u043d\u0438\u04b3\u043e\u043b\u0435 \u0430\u0437 \u043e\u043d \u043c\u0430\u04b7\u043b\u0438\u0441\u0435 \u043a\u0443\u043d\u0435\u043c,\n\u0411\u0430\u0440 \u0451\u0434\u043a\u0430\u0440\u0434\u0438 \u0445\u043e\u04b7\u0430\u0432\u0443 \u0431\u0430\u0440 \u0434\u0438\u0434\u0430\u043d\u0438 \u0431\u0430\u04b3\u043e\u0440...")
B.apy=new A.a("f2991a5c-96dd-4d3a-a81a-0a33b7c0f8e2","d5abab06-07e9-4247-b8a8-f4801b6a5be4","\u041e\u043d \u0440\u04ef\u0437, \u043a\u0438 \u04b3\u0430\u0444\u0442\u0441\u043e\u043b\u0430 \u0431\u0443\u0434\u04e3","\u041e\u043d \u0440\u04ef\u0437, \u043a\u0438 \u04b3\u0430\u0444\u0442\u0441\u043e\u043b\u0430 \u0431\u0443\u0434\u04e3\n\u0427\u0443\u043d \u0433\u0443\u043b \u0431\u0430 \u0447\u0430\u043c\u0430\u043d \u04b3\u0430\u0432\u043e\u043b\u0430 \u0431\u0443\u0434\u04e3.\n\u0412-\u0430\u043a\u043d\u0443\u043d, \u043a\u0438 \u0431\u0430 \u0447\u043e\u0440\u0434\u0430\u04b3 \u0440\u0430\u0441\u0438\u0434\u04e3,\n\u0427\u0443\u043d cap\u0432 \u0431\u0430 \u0430\u0432\u04b7 cap \u043a\u0430\u0448\u0438\u0434\u04e3.\n\u0492\u043e\u0444\u0438\u043b \u043c\u0430\u043d\u0438\u0448\u0438\u043d, \u043d\u0430 \u0432\u0430\u049b\u0442\u0438 \u0431\u043e\u0437\u0438\u0441\u0442,\n\u0412\u0430\u049b\u0442\u0438 \u04b3\u0443\u043d\u0430\u0440 \u0430\u0441\u0442\u0443 \u0441\u0430\u0440\u0444\u0430\u0440\u043e\u0437\u0438\u0441\u0442,\n\u0414\u043e\u043d\u0438\u0448 \u0442\u0430\u043b\u0430\u0431\u0443 \u0431\u0443\u0437\u0443\u0440\u0433\u04e3 \u043e\u043c\u04ef\u0437,\n\u0422\u043e \u0431\u0435\u04b3 \u043d\u0438\u0433\u0430\u0440\u0430\u043d\u0434 \u0440\u04ef\u0437\u0430\u0442 \u0430\u0437 \u0440\u04ef\u0437...")
B.arW=new A.a("1acc9626-c06d-43ab-93cb-b1aad972d4e8","d5abab06-07e9-4247-b8a8-f4801b6a5be4","\u041f\u043e\u0434\u0448\u043e\u04b3\u0438 \u0437\u043e\u043b\u0438\u043c \u0432\u0430 \u04b7\u0430\u0432\u043e\u043d\u0438 \u0441\u0430\u0445\u043e\u0432\u0430\u0442\u043f\u0435\u0448\u0430","\u0414\u0430\u0440 \u049b\u0438\u0441\u0441\u0430 \u0448\u0443\u043d\u0438\u0434\u0430\u0430\u043c, \u043a\u0438 \u0431\u043e\u0440\u0435\n\u0411\u0443\u0434\u0430\u0441\u0442 \u0431\u0430 \u043c\u0430\u0440\u0432 \u0442\u043e\u04b7\u0434\u043e\u0440\u0435.\n\u0414\u0430\u0440 \u0441\u0438\u043b\u0441\u0438\u043b\u0430\n\u0434\u043e\u0448\u0442\u04e3 \u0441\u0430\u0433\u0435 \u0447\u0430\u043d\u0434,\n\u0414\u0435\u0432\u043e\u043d\u0430\u0432\u0430\u0448\u0443 \u0447\u0443 \u0434\u0435\u0432\u0438 \u0434\u0430\u0440 \u0431\u0430\u043d\u0434.\n\u04b2\u0430\u0440 \u044f\u043a \u0431\u0430 \u0441\u0430\u043b\u043e\u0431\u0430\u0442\u0438\n\u0433\u0443\u0440\u043e\u0437\u0435,\n\u0411\u0443\u0440\u0434\u0430 \u0441\u0430\u0440\u0438 \u0443\u0448\u0442\u0443\u0440\u0435 \u0431\u0430 \u0433\u043e\u0437\u0435.\n\u0428\u0430\u04b3 \u0447\u0443\u043d \u0448\u0443\u0434\u04e3 \u0430\u0437 \u043a\u0430\u0441\u0435 \u0431\u0430\u0440 \u043e\u0437\u043e\u0440,\n\u0414\u043e\u0434\u0435\u0448 \u0431\u0430\u0434-\u043e\u043d \u0441\u0430\u0433\u043e\u043d\u0438 \u0445\u0443\u043d\u0445\u043e\u0440.\n\u04b2\u0430\u0440 \u043a\u0430\u0441, \u043a\u0438 \u0437\u0438 \u0448\u043e\u04b3 \u0431\u0435\u0430\u043c\u043e\u043d \u0431\u0443\u0434,\n\u041e\u0432\u0430\u0440\u0434\u0430\u043d\u0443 \u0445\u04ef\u0440\u0434\u0430\u043d\u0430\u0448 \u04b3\u0430\u043c\u043e\u043d \u0431\u0443\u0434.\n\u0411\u0443\u0434 \u0430\u0437 \u043d\u0443\u0434\u0430\u043c\u043e\u0438\n\u0448\u0430\u04b3 \u04b7\u0430\u0432\u043e\u043d\u0435,\n\u0414\u0430\u0440 \u04b3\u0430\u0440 \u04b3\u0443\u043d\u0430\u0440\u0435 \u0442\u0430\u043c\u043e\u043c\u0434\u043e\u043d\u0435.\n\u0422\u0430\u0440\u0441\u0438\u0434, \u043a\u0438 \u0448\u043e\u04b3\u0438 \u043e\u0448\u043d\u043e\u0441\u04ef\u0437,\n\u0411\u0435\u0433\u043e\u043d\u0430 \u0448\u0430\u0432\u0430\u0434 \u0431\u0430 \u04ef \u044f\u043a\u0435 \u0440\u04ef\u0437.\n\u041e\u04b3\u0443\u0438 \u0432\u0430\u0440\u043e \u0431\u0430 \u0441\u0430\u0433 \u043d\u0430\u043c\u043e\u044f\u0434,\n\u0414\u0430\u0440 \u043f\u0435\u0448\u0438 \u0441\u0430\u0433\u043e\u043d\u0430\u0448 \u043e\u0437\u043c\u043e\u044f\u0434.\n\u0410\u0437 \u0431\u0438\u043c\u0438 \u0441\u0430\u0433\u043e\u043d \u0431\u0438\u0440\u0430\u0444\u0442 \u043f\u0435\u0448\u04e3,\n\u0411\u043e \u0441\u0430\u0433\u0431\u043e\u043d\u043e\u043d \u0431\u0438\u043a\u0430\u0440\u0434 \u0445\u0435\u0448\u04e3.\n\u04b2\u0430\u0440 \u0440\u04ef\u0437 \u0448\u0443\u0434\u0438\u044e \u0433\u04ef\u0441\u0444\u0430\u043d\u0434\u0435,\n\u0414\u0430\u0440 \u043c\u0430\u0442\u0440\u0430\u04b3\u0438\n\u043e\u043d \u0441\u0430\u0433\u043e\u043d \u0444\u0438\u043a\u0430\u043d\u0434\u04e3.\n\u0427\u0430\u043d\u0434\u043e\u043d \u0431\u0438\u043d\u0432\u043e\u0445\u0442\u0430\u0448\u043e\u043d \u0431\u0430\u0434-\u043e\u043d \u0441\u043e\u043d,\n\u041a-\u043e\u043d \u0434\u0443\u0448\u0432\u043e\u0440\u04e3 \u0431\u0430\u0434-\u04ef \u0448\u0443\u0434 \u043e\u0441\u043e\u043d.\n\u0410\u0437 \u043c\u0438\u043d\u043d\u0430\u0442\u0438 \u0434\u0430\u0441\u0442 \u0437\u0435\u0440\u0438 \u043f\u043e\u044f\u0448\n\u0413\u0430\u0448\u0442\u0430\u043d\u0434 \u0441\u0430\u0433\u043e\u043d \u043c\u0443\u0442\u0435\u0438 \u0440\u043e\u044f\u0448.\n\u0420\u04ef\u0437\u0435 \u0431\u0430 \u0442\u0430\u0440\u0438\u049b\u0438 \u0445\u0430\u0448\u043c\u043d\u043e\u043a\u04e3,\n\u0428\u0430\u04b3 \u0434\u0438\u0434 \u0434\u0430\u0440 \u043e\u043d \u04b7\u0430\u0432\u043e\u043d\u0438 \u0445\u043e\u043a\u04e3.\n\u0424\u0430\u0440\u043c\u0443\u0434 \u0431\u0430 \u0441\u0430\u0433\u0434\u0438\u043b\u043e\u043d\u0438 \u0434\u0430\u0440\u0433\u043e\u04b3,\n\u0437\u0430\u043d\u04b7\u0438\u0440\u0438 \u043e\u04b3\u0430\u043d\u04e3.\n\u0430\u043d\u0434\u043e\u043c.\n\u043d\u0430\u0434\u0438\u043c\u043e\u043d.\n\u04b7\u043e\u0439\u0438 \u0445\u04ef\u0440\u043e\u043a\u0445\u04ef\u0440\u04e3, \u0441\u0430\u0433\u043a\u043e\u0441\u0430.\n\u0422\u043e \u043f\u0435\u0448\u0438 \u0441\u0430\u0433\u043e\u043d \u0431\u0430\u0440\u0430\u043d\u0434\u0430\u0448 \u0430\u0437 \u0440\u043e\u04b3.\n\u0412-\u043e\u043d \u0441\u0430\u0433\u043c\u0430\u043d\u0438\u0448\u043e\u043d \u0441\u0430\u0433\u04e3 \u043d\u0430\u043c\u0443\u0434\u0430\u043d\u0434,\n\u0427\u0443\u043d \u0441\u0430\u0433 \u0431\u0430 \u0442\u0430\u0431\u0430\u0440\u0440\u0443\u043a\u0430\u0448 \u0440\u0430\u0431\u0443\u0434\u0430\u043d\u0434.\n\u0411\u0430\u0441\u0442\u0430\u043d\u0434\u0443 \u0431\u0430\u0434-\u043e\u043d \u0441\u0430\u0433\u043e\u043d-\u0448 \u0434\u043e\u0434\u0430\u043d\u0434,\n\u0425\u0443\u0434 \u0434\u0443\u0440 \u0448\u0443\u0434\u0430\u043d\u0434\u0443 \u0438\u0441\u0442\u043e\u0434\u0430\u043d\u0434.\n\u0412-\u043e\u043d \u0448\u0435\u0440\u0441\u0430\u0433\u043e\u043d\u0438 \u043e\u04b3\u0430\u043d\u0438\u043d\u0447\u0430\u043d\u0433,\n\u041a\u0430\u0440\u0434\u0430\u0430\u043d\u0434 \u043d\u0430\u0445\u0443\u0441\u0442 \u0431\u0430\u0440 \u0432\u0430\u0439 \u043e\u04b3\u0430\u043d\u0433.\n\u0427\u0443\u043d \u043c\u0443\u043d\u044a\u0438\u043c\u0438\n\u0445\u0443\u0434 \u0448\u0438\u043d\u043e\u0445\u0442\u0430\u043d\u0434\u0430\u0448,\n\u0414\u0443\u043c\u0431\u043e\u043b\u0430\u043a\u0443\u043d\u043e\u043d \u043d\u0430\u0432\u043e\u0445\u0442\u0430\u043d\u0434\u0430\u0448.\n\u0413\u0438\u0440\u0434\u0430\u0448 \u04b3\u0430\u043c\u0430 \u0434\u0430\u0441\u0442\u0431\u0430\u043d\u0434 \u0431\u0430\u0441\u0442\u0430\u043d\u0434,\n\u0421\u0430\u0440 \u0431\u0430\u0440 \u0441\u0430\u0440\u0438 \u0434\u0430\u0441\u0442\u04b3\u043e \u043d\u0438\u0448\u0430\u0441\u0442\u0430\u043d\u0434.\n\u0411\u0443\u0434\u0430\u043d\u0434 \u0431\u0430\u0440 \u04ef \u0447\u0443 \u0434\u043e\u044f \u0434\u0438\u043b\u0441\u04ef\u0437,\n\u0422\u043e \u0440\u0430\u0444\u0442 \u0431\u0430\u0440 \u0438\u043d \u044f\u043a\u0435 \u0448\u0430\u0431\u043e\u043d\u0440\u04ef\u0437.\n\u0427\u0443\u043d \u0440\u04ef\u0437\u0438 \u0441\u0430\u043f\u0435\u0434 \u0440\u04ef\u0439 \u0431\u0438\u043d\u043c\u0443\u0434,\n\u0421\u0430\u0439\u0444\u0443\u0440\u0438 \u0441\u0438\u0451\u04b3\n\u0448\u0443\u0434 \u0437\u0430\u0440\u0430\u043d\u0434\u0443\u0434.\n\u0428\u0443\u0434 \u0448\u043e\u04b3 \u0437\u0438 \u043a\u043e\u0440\u0438 \u0445\u0443\u0434 \u043f\u0443\u0448\u0430\u0439\u043c\u043e\u043d,\n\u0492\u0430\u043c\u0433\u0438\u043d \u0448\u0443\u0434\u0443 \u0433\u0443\u0444\u0442 \u0431\u043e \u043d\u0430\u0434\u0438\u043c\u043e\u043d:\n\xab\u041a-\u043e\u043d \u043e\u04b3\u0443\u0438 \u0431\u0435\u0433\u0443\u043d\u043e\u04b3\u0440\u043e \u0434\u04ef\u0448,\n\u0414\u043e\u0434\u0430\u043c \u0431\u0430 \u0441\u0430\u0433, \u0438\u043d\u0442\u0438\u0445\u043e\u0431\u0438 \u0445\u0430\u0440\u0433\u04ef\u0448.\n\u0411\u0438\u043d\u0435\u0434, \u043a\u0438 \u043e\u043d \u0441\u0430\u0433\u043e\u043d \u0447\u04e3 \u043a\u0430\u0440\u0434\u0430\u043d\u0434?\n\u0410\u043d\u0434\u043e\u043c\u0438 \u0432\u0430\u0440\u043e \u0447\u04e3 \u0433\u0443\u043d\u0430 \u0445(\u0432)\u0430\u0440\u0434\u0430\u043d\u0434\n?\xbb\n\u0421\u0430\u0433\u0431\u043e\u043d \u0447\u0443 \u0430\u0437 \u0438\u043d \u0441\u0443\u0445\u0430\u043d \u0448\u0443\u0434 \u043e\u0433\u043e\u04b3,\n\u041e\u043c\u0430\u0434 \u0431\u0430\u0440\u0438 \u0448\u043e\u04b3\u0443 \u0433\u0443\u0444\u0442: \xab \u041a-\u044d\u0439 \u0448\u043e\u04b3,\n\u0418\u043d \u0448\u0430\u0445\u0441 \u043d\u0430 \u043e\u0434\u0430\u043c\u04e3, \u0444\u0430\u0440\u0438\u0448\u0442\u0430\u0441\u0442.\n\u041a-\u044d\u0437\u0438\u0434\n\u0437\u0438 \u043a\u0430\u0440\u043e\u043c\u0430\u0442\u0430\u0448 \u0441\u0438\u0440\u0438\u0448\u0442\u0430\u0441\u0442.\n\u0411\u0430\u0440\u0445\u0435\u0437\u0443 \u0431\u0438\u0451, \u0431\u0443\u0431\u0438\u043d \u0434\u0430\u0440 \u043e\u043d \u043d\u0443\u0440,\n\u0422\u043e \u0441\u0443\u043d\u044a\u0438 \u0425\u0443\u0434\u043e\u0439 \u0431\u0438\u043d\u04e3 \u0430\u0437 \u0434\u0443\u0440.\n\u04ee \u0434\u0430\u0440 \u0434\u0430\u04b3\u0430\u043d\u0438 \u0441\u0430\u0433\u043e\u043d \u043d\u0438\u0448\u0430\u0441\u0442\u0430,\n\u0414\u0430\u043d\u0434\u043e\u043d\u0438 \u0441\u0430\u0433\u043e\u043d \u0431\u0430 \u043c\u0443\u04b3\u0440 \u0431\u0430\u0441\u0442\u0430.\n\u0417-\u043e\u043d \u0433\u0443\u0440\u0433\u0441\u0430\u0433\u043e\u043d\u0438 \u0430\u0436\u0434\u0430\u04b3\u043e\u0440\u04ef\u0439,\n\u041d-\u043e\u0437\u0443\u0440\u0434\u0430 \u0431\u0430\u0440 \u04ef \u044f\u043a\u0435 \u0441\u0430\u0440\u0438 \u043c\u04ef\u0439\xbb.\n\u0428\u0430\u04b3 \u043a\u0430\u0440\u0434\u0430 \u0448\u0438\u0442\u043e\u0431, \u0442\u043e \u0448\u0438\u0442\u043e\u0431\u0430\u043d\u0434,\n\u041e\u043d \u0433\u0443\u043c\u0448\u0443\u0434\u0430\u0440\u043e \u043c\u0430\u0433\u0430\u0440 \u0431\u0438\u0451\u0431\u0430\u043d\u0434.\n\u0434\u04ef\u0441\u0442.\n\u043a\u0438\u043d\u043e\u044f \u0430\u0437 \u0448\u0430\u0431\u0438 \u0441\u0438\u044f\u04b3\u04b7\u043e\u043c\u0430.\n\u0445\u04ef\u0440\u0434\u0430\u043d\u0434.\n\u0425\u0443\u0434\u043e.\n\u0411\u0443\u0440\u0434\u0430\u043d\u0434 \u043c\u0443\u0432\u0430\u043a\u043a\u0438\u043b\u043e\u043d\u0438 \u0440\u043e\u04b3\u0430\u0448,\n\u0410\u0437 \u0441\u0438\u043b\u043a\u0438 \u0441\u0430\u0433\u043e\u043d\n\u0431\u0430 \u0441\u0430\u0434\u0440\u0438 \u0448\u043e\u04b3\u0430\u0448\n.\n\u0428\u0430\u04b3 \u043c\u043e\u043d\u0434 \u0448\u0438\u0433\u0438\u0444\u0442, \u043a\u0438 \u043e\u043d \u04b7\u0430\u0432\u043e\u043d\u043c\u0430\u0440\u0434,\n\u0427\u0443\u043d \u0431\u0443\u0434, \u043a-\u0430\u0437 \u0441\u0430\u0433\u043e\u043d \u043d\u0430\u0451\u0437\u0430\u0440\u0434?\n\u0413\u0438\u0440\u0451\u043d\u2013\u0433\u0438\u0440\u0451\u043d \u0431\u0430 \u043f\u043e\u0439 \u0431\u0430\u0440\u0445\u043e\u0441\u0442,\n\u0421\u0430\u0434 \u0443\u0437\u0440 \u0431\u0430 \u043e\u0431\u0438 \u0447\u0430\u0448\u043c \u0430\u0437 \u04ef \u0445\u043e\u0441\u0442.\n\u0413\u0443\u0444\u0442\u043e: \xab\u0421\u0430\u0431\u0430\u0431 \u0447\u04e3 \u0431\u0443\u0434, \u0431\u0438\u043d\u043c\u043e\u0439,\n\u041a-\u0438\u043d \u044f\u043a \u043d\u0430\u0444\u0430\u0441\u0438 \u0442\u0443 \u043c\u043e\u043d\u0434 \u0431\u0430\u0440 \u04b7\u043e\u0439?\xbb\n\u0413\u0443\u0444\u0442\u043e: \xab\u0421\u0430\u0431\u0430\u0431 \u043e\u043d, \u043a\u0438 \u043f\u0435\u0448 \u0430\u0437 \u0438\u043d \u0431\u0430\u043d\u0434\n\u0414\u043e\u0434\u0430\u043c \u0431\u0430 \u0441\u0430\u0433\u043e\u043d \u043d\u0430\u0432\u043e\u043b\u0430\u0435 \u0447\u0430\u043d\u0434.\n\u042d\u0448\u043e\u043d \u0431\u0430 \u043d\u0430\u0432\u043e\u043b\u0430\u0435, \u043a\u0438 \u0445\u04ef\u0440\u0434\u0430\u043d\u0434,\n\u0411\u043e \u043c\u0430\u043d \u043b\u0430\u0431\u0438 \u0445\u0443\u0434 \u0431\u0430\u043c\u0443\u04b3\u0440 \u043a\u0430\u0440\u0434\u0430\u043d\u0434.\n\u0414\u0430\u04b3 \u0441\u043e\u043b \u0493\u0443\u043b\u043e\u043c\u0438\u0438 \u0442\u0443 \u043a\u0430\u0440\u0434\u0430\u043c,\n\u0418\u043d \u0431\u0443\u0434 \u0431\u0430\u0440\u0435\n, \u043a\u0438 \u0430\u0437 \u0442\u0443 \u0445\u04ef\u0440\u0434\u0430\u043c.\n\u0414\u043e\u0434\u04e3 \u0431\u0430 \u0441\u0430\u0433\u043e\u043d\u0430\u043c \u0430\u0437 \u044f\u043a \u043e\u0437\u043e\u0440,\n\u0412-\u0438\u043d \u0431\u0443\u0434, \u043a\u0438 \u043d\u0430\u0431\u0443\u0434 \u0441\u0430\u0433 \u043e\u0448\u043d\u043e\u0445\u043e\u0440.\n\u0421\u0430\u0433 \u0434\u04ef\u0441\u0442 \u0448\u0443\u0434\u0443 \u0442\u0443 \u043e\u0448\u043d\u043e \u043d\u0430,\n\u0421\u0430\u0433\u0440\u043e \u04b3\u0430\u049b\u049b\u0438 \u04b3\u0443\u0440\u043c\u0430\u0442\u0443 \u0442\u0443\u0440\u043e \u043d\u0430.\n\u0421\u0430\u0433 \u0441\u0443\u043b\u04b3 \u043a\u0443\u043d\u0430\u0434 \u0431\u0430 \u0443\u0441\u0442\u0443\u0445\u043e\u043d\u0435,\n\u041d\u043e\u043a\u0430\u0441 \u043d\u0430\u043a\u0443\u043d\u0430\u0434 \u0432\u0430\u0444\u043e \u0431\u0430 \u04b7\u043e\u043d\u0435\xbb.\n\u0427\u0443\u043d \u0434\u0438\u0434 \u0448\u0430\u04b3 \u043e\u043d \u0448\u0438\u0433\u0438\u0444\u0442\u043a\u043e\u0440\u04e3,\n\u041a-\u0430\u0437 \u043c\u0430\u0440\u0434\u0443\u043c\u04e3 \u0430\u0441\u0442 \u0440\u0430\u0441\u0442\u0430\u0433\u043e\u0440\u04e3\n.\n\u04b2\u0443\u0448\u0451\u0440 \u0448\u0443\u0434 \u0430\u0437 \u0445\u0443\u043c\u043e\u0440\u0438 \u043c\u0430\u0441\u0442\u04e3,\n\u0411\u0438\u0433\u0437\u043e\u0448\u0442 \u0441\u0430\u0433\u0438\u044e \u0441\u0430\u0433\u043f\u0430\u0440\u0430\u0441\u0442\u04e3.\n\u041c\u0430\u049b\u0441\u0443\u0434\u0430\u043c \u0430\u0437 \u0438\u043d \u04b3\u0438\u043a\u043e\u044f\u0442 \u043e\u043d \u0430\u0441\u0442,\n\u041a-\u044d\u04b3\u0441\u043e\u043d\u0443 \u0434\u0435\u04b3\u0438\u0448\n\u04b3\u0438\u0441\u043e\u0440\u0438 \u04b7\u043e\u043d\n\u0430\u0441\u0442.")
B.amV=new A.a("872832da-62f9-4625-9554-0fb9e1c03815","d5abab06-07e9-4247-b8a8-f4801b6a5be4","\u0414\u043e\u0441\u0442\u043e\u043d\u0438 \xab\u0425\u0430\u0439\u0440 \u0432\u0430 \u0428\u0430\u0440\xbb","\u0427\u0443\u043d \u0448\u043e\u04b3 \u0411\u0430\u04b3\u0440\u043e\u043c \u0438\u043d \u043d\u0430\u0432\u0431\u0430\u0442 \u043c\u0435\u04b3\u043c\u043e\u043d\u0438 \u0431\u043e\u043d\u0443\u0438 \u0427\u0438\u043d \u043c\u0435\u0448\u0430\u0432\u0430\u0434,\n\u0431\u043e\u043d\u0443\u0438 \u0427\u0438\u043d \u0430\u0437 \u0448\u043e\u0434\u0438\u0432\u0443 \u043d\u0438\u0448\u043e\u0442 \u0431\u043e \u0447\u0435\u04b3\u0440\u0430\u0438 \u043a\u0443\u0448\u043e\u0434\u0430, \u044f\u044a\u043d\u0435 \u0447\u0438\u043d \u0430\u0437\n\u04b7\u0430\u0431\u0438\u043d \u0431\u0430\u0440\u0434\u043e\u0448\u0442\u0430 \u0431\u0430 \u043d\u0430\u0440\u043c\u04e3 \u0441\u0443\u0445\u0430\u043d \u043c\u0435\u0433\u04ef\u044f\u0434.\n\u0411\u043e\u043d\u0443\u0438 \u0427\u0438\u043d \u0437\u0438 \u0447\u0435\u04b3\u0440\u0430 \u0447\u0438\u043d \u0431\u0438\u043a\u0448\u043e\u0434\n\u0412-\u0430\u0437 \u0440\u0443\u0442\u0430\u0431\n\u04b7\u04ef\u0438 \u0430\u043d\u0433\u0443\u0431\u0438\u043d\n\u0431\u0438\u043a\u0448\u043e\u0434...\n\u0413\u0443\u0444\u0442: \u0412\u0430\u049b\u0442\u0435 \u0437\u0438 \u0448\u0430\u04b3\u0440\u0438 \u0445\u0443\u0434 \u0434\u0443 \u04b7\u0430\u0432\u043e\u043d,\n\u0421\u04ef\u0438 \u0448\u0430\u04b3\u0440\u0438 \u0434\u0438\u0433\u0430\u0440 \u0448\u0443\u0434\u0430\u043d\u0434 \u0440\u0430\u0432\u043e\u043d.\n\u04b2\u0430\u0440 \u044f\u043a\u0435 \u0434\u0430\u0440 \u04b7\u0430\u0432\u043e\u043b\u0433\u04ef\u0448\u0430\u0438\n\u0445\u0443\u0434\n\u041a\u0430\u0440\u0434\u0430 \u0430\u0441\u0431\u043e\u0431\u0438 \u0440\u043e\u04b3 \u0442\u04ef\u0448\u0430\u0438 \u0445\u0443\u0434.\n\u041d\u043e\u043c\u0438 \u0438\u043d \u0425\u0430\u0439\u0440\u0443\n\u043d\u043e\u043c\u0438 \u043e\u043d \u0428\u0430\u0440\n\u0431\u0443\u0434,\n\u0424\u0435\u044a\u043b\u0438 \u04b3\u0430\u0440 \u044f\u043a \u0431\u0430 \u043d\u043e\u043c \u0434\u0430\u0440\u0445\u0432\u0430\u0440\n\u0431\u0443\u0434.\n\u0427\u0443\u043d \u0431\u0443\u0440\u0438\u0434\u0430\u043d\u0434 \u0440\u04ef\u0437\u0430\u043a\u0435 \u0434\u0443-\u0441\u0435 \u0440\u043e\u04b3,\n\u0422\u04ef\u0448\u0430\u0435\u0440\u043e, \u043a\u0438 \u0434\u043e\u0448\u0442\u0430\u043d\u0434 \u043d\u0438\u0433\u043e\u04b3\n\u0425\u0430\u0439\u0440 \u043c\u0435\u0445\u04ef\u0440\u0434\u0443 \u0428\u0430\u0440 \u043d\u0438\u0433\u043e\u04b3 \u043c\u0435\u0434\u043e\u0448\u0442,\n\u0418\u043d \u0493\u0430\u043b\u043b\u0430 \u043c\u0435\u0434\u0443\u0440\u0443\u0434\n, \u043e\u043d \u043c\u0435\u043a\u043e\u0448\u0442.\n\u0422\u043e \u0440\u0430\u0441\u0438\u0434\u0430\u043d\u0434 \u04b3\u0430\u0440 \u0434\u0443 \u0434\u04ef\u0448\u043e\u0434\u04ef\u0448\n,\n\u0414\u0430\u0440 \u0431\u0438\u0451\u0431\u043e\u043d\u0435 \u0430\u0437 \u0431\u0443\u0445\u043e\u0440\n\u0431\u0430 \u04b7\u04ef\u0448.\n\u041a\u04ef\u0440\u0430\u0435 \u0447\u0443\u043d \u0442\u0430\u043d\u04ef\u0440\u0438 \u043e\u0442\u0430\u0448 \u0433\u0430\u0440\u043c,\n\u041a-\u043e\u04b3\u0430\u043d \u0430\u0437 \u0432\u0430\u0439 \u0447\u0443 \u043c\u0443\u043c \u0433\u0430\u0448\u0442\u04e3 \u043d\u0430\u0440\u043c!\n\u043a\u0438\u043d\u043e\u044f \u0430\u0437 \u043b\u0430\u0431.\n\u0441\u0443\u0445\u0430\u043d\u0438 \u0448\u0438\u0440\u0438\u043d.\n\u043a\u0443\u043b\u0431\u043e\u0440.\n\u043d\u0435\u043a, \u043d\u0430\u0493\u0437, \u0445\u0443\u0431.\n\u0431\u0430\u0434, \u0437\u0438\u0448\u0442.\n\u043c\u0443\u0432\u043e\u0444\u0438\u049b.\n\u0434\u0430\u0440\u0430\u0432 \u043c\u0435\u043a\u0430\u0440\u0434.\n\u0434\u04ef\u0448 \u0431\u0430 \u0434\u04ef\u0448, \u043f\u0430\u04b3\u043b\u0443 \u0431\u0430 \u043f\u0430\u04b3\u043b\u0443.\n\u0431\u0443\u0493.\n\u0413\u0430\u0440\u043c\u0441\u0435\u043b\u0438\u044e \u0445\u0443\u0448\u043a\u0441\u043e\u0440\u0438\u0438 \u0431\u0443\u043c\n,\n\u041a\u0430\u0440\u0434\u0430 \u0431\u043e\u0434\u0438 \u0448\u0438\u043c\u043e\u043b\u0440\u043e\n\u0447\u0443 \u0441\u0430\u043c\u0443\u043c\n.\n\u0425\u0430\u0439\u0440 \u0444\u043e\u0440\u0438\u0493, \u043a\u0438 \u043e\u0431 \u0434\u0430\u0440 \u0440\u043e\u04b3 \u0430\u0441\u0442,\n\u0411\u0435\u0445\u0430\u0431\u0430\u0440, \u043a-\u043e\u0431 \u043d\u0435\u0441\u0442, \u043e\u043d \u0447\u043e\u04b3 \u0430\u0441\u0442.\n\u0428\u0430\u0440 \u0445\u0430\u0431\u0430\u0440 \u0434\u043e\u0448\u0442 \u043a-\u043e\u043d \u0437\u0430\u043c\u0438\u043d\u0438 \u0445\u0430\u0440\u043e\u0431,\n\u0414\u0443\u0440\u0438\u0435 \u0434\u043e\u0440\u0430\u0434\u0443 \u043d\u0430\u0434\u043e\u0440\u0430\u0434 \u043e\u0431.\n\u041c\u0430\u0448\u043a\u0435 \u0430\u0437 \u043e\u0431 \u043a\u0430\u0440\u0434\u0430 \u043f\u0438\u043d\u04b3\u043e\u043d \u043f\u0443\u0440,\n\u0414\u0430\u0440 \u0445\u0430\u0440\u0438\u0442\u0430\n\u043d\u0438\u0433\u043e\u04b3 \u0434\u043e\u0448\u0442 \u0447\u0443 \u0434\u0443\u0440.\n\u0414\u0430\u0440 \u0431\u0438\u0451\u0431\u043e\u043d\u0438 \u0433\u0430\u0440\u043c\u0443 \u0440\u043e\u04b3\u0438 \u0434\u0430\u0440\u043e\u0437,\n\u04b2\u0430\u0440 \u0434\u0443 \u043c\u0435\u0442\u043e\u0445\u0442\u0430\u043d\u0434 \u0431\u043e \u0442\u0430\u043a\u0443\u0442\u043e\u0437.\n\u0427\u0443\u043d \u0431\u0430 \u0433\u0430\u0440\u043c\u04e3 \u0448\u0443\u0434\u0430\u043d\u0434 \u0440\u04ef\u0437\u0435 \u04b3\u0430\u0444\u0442,\n\u041e\u0431\u0438 \u0428\u0430\u0440 \u043c\u043e\u043d\u0434\u0443 \u043e\u0431\u0438 \u0425\u0430\u0439\u0440 \u0431\u0438\u0440\u0430\u0444\u0442.\n\u0428\u0430\u0440, \u043a\u0438 \u043e\u043d \u043e\u0431\u0440\u043e \u0437\u0438 \u0425\u0430\u0439\u0440 \u043d\u0443\u04b3\u0443\u0444\u0442\n,\n\u0411\u0430\u0440 \u0432\u0430\u0439 \u0430\u0437 \u0445\u0430\u0439\u0440\u0443 \u0448\u0430\u0440 \u04b3\u0430\u0434\u0438\u0441\n\u043d\u0430\u0433\u0443\u0444\u0442.\n\u0425\u0430\u0439\u0440 \u0447\u0443\u043d \u0434\u0438\u0434 \u04ef \u0437\u0438 \u0433\u0430\u0432\u04b3\u0430\u0440\u0438 \u0431\u0430\u0434\n,\n\u0414\u043e\u0440\u0430\u0434 \u043e\u0431\u0435 \u0434\u0430\u0440 \u043e\u0431\u0433\u0438\u043d\u0430\u0438\n\u0445\u0443\u0434.\n\u0412\u0430\u049b\u0442-\u0432\u0430\u049b\u0442 \u043e\u043d \u0440\u0430\u0444\u0438\u049b \u043f\u0438\u043d\u04b3\u043e\u043d\u04e3,\n\u041c\u0435\u0445\u04ef\u0440\u0430\u0434 \u0447\u0443\u043d \u0440\u0430\u04b3\u0438\u049b\u0438 \u0440\u0430\u0439\u04b3\u043e\u043d\u04e3\n.\n\u0413\u0430\u0440\u0447\u0438 \u0434\u0430\u0440 \u0442\u043e\u0431\u0438 \u0442\u0430\u0448\u043d\u0430\u0433\u04e3 \u043c\u0435\u0441\u04ef\u0445\u0442,\n\u041b\u0430\u0431 \u0431\u0430 \u0434\u0430\u043d\u0434\u043e\u043d \u0437\u0438 \u043b\u043e\u0431\u0430\n\u0431\u0430\u0440\u043c\u0435\u0434\u04ef\u0445\u0442\n\u0422\u0430\u0448\u043d\u0430 \u0434\u0430\u0440 \u043e\u0431\u0438 \u04ef \u043d\u0430\u0437\u0430\u0440 \u043c\u0435\u043a\u0430\u0440\u0434,\n\u041e\u0431\u0438 \u0434\u0430\u043d\u0434\u043e\u043d \u0430\u0437 \u04b7\u0438\u0433\u0430\u0440 \u043c\u0435\u043a\u0430\u0440\u0434\n.\n\u0422\u043e \u0431\u0430 \u04b3\u0430\u0434\u0434\u0435, \u043a\u0438 \u0445\u0443\u0448\u043a \u0448\u0443\u0434 \u04b7\u0438\u0433\u0430\u0440\u0430\u0448,\n\u0411\u043e\u0437 \u043c\u043e\u043d\u0434 \u0430\u0437 \u043a\u0443\u0448\u043e\u0434\u0430\u0433\u04e3 \u043d\u0430\u0437\u0430\u0440\u0430\u0448\n.\n\u0437\u0430\u043c\u0438\u043d.\n\u0431\u043e\u0434\u0438 \u0442\u0430\u0440\u0430\u0444\u0438 \u0448\u0438\u043c\u043e\u043b, \u043a\u0438 \u0441\u0430\u043b\u049b\u0438\u043d \u0430\u0441\u0442.\n\u0431\u043e\u0434\u0438 \u0433\u0430\u0440\u043c\u0438 \u0431\u0435\u043c\u043e\u0440\u0438\u043e\u0432\u0430\u0440.\n\u0445\u0430\u043b\u0442\u0430.\n\u043f\u0438\u043d\u04b3\u043e\u043d \u0434\u043e\u0448\u0442.\n\u0441\u0443\u0445\u0430\u043d, \u0433a\u043f.\n\u043c\u0430\u04b7\u043e\u0437\u0430\u043d \u0431\u0430\u0434\u0442\u0438\u043d\u0430\u0442.\n\u0437\u0430\u0440\u0444\u0438 \u043e\u0431\u0433\u0438\u0440\u04e3.\n\u043c\u0430\u0439\u0438 \u0445\u0443\u0448\u0431\u04ef\u0439, \u0441\u043e\u0444.\n\u0437\u043e\u0440\u04e3, \u043c\u0430\u0437\u043c\u0443\u043d\u0438 \u0431\u0430\u0439\u0442: \u0434\u0430\u043d\u0434\u043e\u043d \u0431\u0430 \u0434\u0430\u043d\u0434\u043e\u043d \u043c\u043e\u043d\u0434\u0430 \u0430\u0437 \u0438\u043b\u0442\u0438\u04b7\u043e\u0432\u0443 \u0437\u043e\u0440\u04e3\n\u0445\u0443\u0434\u0434\u043e\u0440\u04e3 \u043c\u0435\u043a\u0430\u0440\u0434.\n\u044f\u044a\u043d\u0435 \u0445\u0443\u043d\u0438 \u04b7\u0438\u0433\u0430\u0440 \u043c\u0435\u0445\u04ef\u0440\u0434.\n\u043f\u0435\u0448\u0438 \u0447\u0430\u0448\u043c\u043e\u043d\u0430\u0448 \u0442\u0438\u0440\u0430 \u0448\u0443\u0434, \u0447\u0430\u0448\u043c\u0430\u0448\n\u0441\u0438\u0451\u04b3 \u0437\u0430\u0434.\n\u0414\u043e\u0448\u0442 \u0431\u043e \u0445\u0443\u0434 \u0434\u0443 \u043b\u0430\u044a\u043b\u0438 \u043e\u0442\u0430\u0448\u0440\u0430\u043d\u0433,\n\u041e\u0431\u0434\u043e\u0440\u0430\u043d\u0434\u0430 \u0432-\u043e\u0431\u0430\u0448\u043e\u043d \u0431\u0430\u0440 \u0441\u0430\u043d\u0433.\n\u04b2\u043e\u043b\u04e3\n\u043e\u043d \u043b\u0430\u044a\u043b \u043e\u0431\u0434\u043e\u0440\n\u043a\u0443\u0448\u043e\u0434,\n\u041f\u0435\u0448\u0438 \u043e\u043d \u0441\u0430\u043d\u0433\u0438 \u043e\u0431\u0434\u043e\u0440\n\u043d\u0438\u04b3\u043e\u0434.\n\u0413\u0443\u0444\u0442:\xab\u041c\u0443\u0440\u0434\u0430\u043c \u0430\u0437 \u0442\u0430\u0448\u043d\u0430\u0433\u04e3, \u0434\u0430\u0440\u0451\u0431!\n\u041e\u0442\u0430\u0448\u0430\u043c\u0440\u043e \u0431\u0438\u043a\u0443\u0448 \u0431\u0430 \u049b\u0430\u0442\u0440\u0430\u0438 \u043e\u0431\n!\n\u0428\u0430\u0440\u0431\u0430\u0442\u0435 \u043e\u0431 \u0430\u0437 \u043e\u043d \u0437\u0443\u043b\u043e\u043b\u0438\n\u0447\u0443 \u043d\u04ef\u0448,\n\u0401 \u0431\u0430 \u04b3\u0438\u043c\u043c\u0430\u0442 \u0431\u0438\u0431\u0430\u0445\u0448, \u0451 \u0431\u0438\u0444\u0443\u0440\u04ef\u0448!\n\u0418\u043d \u0434\u0443 \u0433\u0430\u0432\u04b3\u0430\u0440 \u0434\u0430\u0440 \u043e\u0431\u0438 \u0445\u0435\u0448 \u0430\u043d\u0434\u043e\u0437,\n\u0413\u0430\u0432\u04b3\u0430\u0440\u0430\u043c\u0440\u043e\n\u0431\u0430 \u043e\u0431\u0438 \u0445\u0443\u0434 \u0431\u0438\u043d\u0432\u043e\u0437!\xbb\n\u0428\u0430\u0440, \u043a\u0438 \u0445\u0430\u0448\u043c\u0438 \u0425\u0443\u0434\u043e\u0439 \u0431\u043e\u0434 \u0431\u0430\u0440 \u04ef,\n\u041d\u043e\u043c\u0438 \u0445\u0443\u0434\u0440\u043e \u0432\u0430\u0440\u0430\u049b \u043a\u0443\u0448\u043e\u0434 \u0431\u0430\u0440 \u04ef!\n\u0413\u0443\u0444\u0442:\xab\u0410\u0437 \u0441\u0430\u043d\u0433 \u0447\u0430\u0448\u043c\u0430\u0435 \u043c\u0430\u0442\u0430\u0440\u043e\u0448,\n\u0424\u043e\u0440\u0438\u0493\u0430\u043c \u0437-\u0438\u043d \u0444\u0438\u0440\u0435\u0431, \u0444\u043e\u0440\u0438\u0493 \u0431\u043e\u0448!\n\u041c\u0435\u0434\u0438\u04b3\u04e3 \u0433\u0430\u0432\u04b3\u0430\u0440\u0430\u043c \u0431\u0430 \u0432\u0430\u0439\u0440\u043e\u043d\u04e3,\n\u0422\u043e \u0431\u0430 \u043e\u0431\u043e\u0434\u0431\u0443\u043c \u0431\u0438\u0441\u0442\u043e\u043d\u04e3\n?!\n\u0427\u04e3 \u04b3\u0430\u0440\u0438\u0444\u0430\u043c, \u043a\u0438 \u0438\u043d \u0444\u0438\u0440\u0435\u0431 \u0445\u04ef\u0440\u0430\u043c?\n\u041c\u0430\u043d \u0437\u0438 \u0434\u0435\u0432\u043e\u0434\u0430\u043c\u04e3\n\u0444\u0438\u0440\u0435\u0431\u0442\u0430\u0440\u0430\u043c!...\n\u041d\u0430\u0433\u0443\u0437\u043e\u0440\u0430\u043c, \u043a\u0438 \u043e\u0431\u0438 \u043c\u0430\u043d \u0431\u0438\u0445\u04ef\u0440\u04e3,\n\u0427\u0443\u043d \u0431\u0430 \u0448\u0430\u04b3\u0440 \u043e\u0439\u04e3, \u043e\u0431\u0438 \u043c\u0430\u043d\n\u0431\u0438\u0431\u0430\u0440\u04e3!\n\u041e\u043d \u0433\u0443\u04b3\u0430\u0440 \u0447\u0443\u043d \u0441\u0438\u0442\u043e\u043d\u0430\u043c \u0430\u0437 \u0442\u0443 \u0431\u0430 \u0440\u043e\u0437,\n\u041a-\u0430\u0437 \u043c\u0430\u043d\u0430\u0448 \u043e\u049b\u0438\u0431\u0430\u0442 \u0441\u0438\u0442\u043e\u043d\u04e3 \u0431\u043e\u0437?\n\u0413\u0430\u0432\u04b3\u0430\u0440\u0435 \u0431\u043e\u044f\u0434\u0430\u043c, \u043a\u0438 \u043d\u0430\u0442\u0432\u043e\u043d\u04e3,\n\u041a-\u0430\u0437 \u043c\u0430\u043d\u0430\u0448 \u04b3\u0435\u04b7 \u0433\u0443\u043d\u0430 \u0431\u0438\u0441\u0442\u043e\u043d\u04e3!\xbb\n\u0413\u0443\u0444\u0442 \u0425\u0430\u0439\u0440: \xab\u041e\u043d \u0447\u04e3 \u0433\u0430\u0432\u04b3\u0430\u0440 \u0430\u0441\u0442?-\u0411\u0438\u0433\u04ef\u0439,\n\u0422\u043e \u0441\u0443\u043f\u043e\u0440\u0430\u043c \u0431\u0430 \u0434\u0430\u0441\u0442\u0438 \u0433\u0430\u0432\u04b3\u0430\u0440\u04b7\u04ef\u0439!\xbb\n\u0413\u0443\u0444\u0442 \u0428\u0430\u0440: \xab\u041e\u043d \u0434\u0443 \u0433\u0430\u0432\u04b3\u0430\u0440\u0438 \u0431\u0430\u0441\u0430\u0440 \u0430\u0441\u0442,\n\u041a-\u0438\u043d \u0430\u0437 \u043e\u043d, \u043e\u043d \u0430\u0437 \u0438\u043d \u0430\u0437\u0438\u0437\u0442\u0430\u0440 \u0430\u0441\u0442!\n\u04b3\u0430\u043c\u043e\u043d \u0437\u0430\u043c\u043e\u043d, \u0437\u0443\u0434.\n\u043b\u0430\u044a\u043b\u0438 \u0430\u0441\u0438\u043b, \u0442\u043e\u0437\u0430, \u043f\u0443\u0440\u049b\u0438\u043c\u0430\u0442.\n\u043a\u0438\u043d\u043e\u044f \u0430\u0437 \u0428\u0430\u0440\u0438 \u0431\u0430\u0434\u0434\u0438\u043b, \u043a\u0438 \u0431\u043e \u0445\u0443\u0434 \u043e\u0431 \u0434\u043e\u0448\u0442.\n\u044f\u044a\u043d\u0435 \u043e\u0431 \u0434\u0435\u04b3, \u0442\u043e \u0442\u0430\u0448\u043d\u0430\u0433\u04e3 \u0431\u0438\u0448\u043a\u0430\u043d\u0430\u043c, \u043a\u0438\n\u043c\u0435\u043c\u0438\u0440\u0430\u043c.\n\u043e\u0431\u0438 \u0447\u0443\u043d \u0430\u0441\u0430\u043b \u0448\u0438\u0440\u0438\u043d.\n\u04b7\u0430\u0432\u04b3\u0430\u0440, \u0438\u043d \u04b7\u043e \u043c\u0430\u04b7\u043e\u0437\u0430\u043d \u04b7\u043e\u043d, \u04b7\u043e\u043d\u0443 \u0442\u0430\u043d.\n\u0441\u0438\u0442\u043e\u043d\u0438\u0434\u0430\u043d, \u0431\u043e\u0437 \u0433\u0438\u0440\u0438\u0444\u0442\u0430\u043d.\n\u043d\u0430\u0432\u044a\u0435 \u0430\u0437 \u04b3\u0430\u0439\u0432\u043e\u043d, \u044f\u044a\u043d\u0435 \u043e\u0434\u0430\u043c\u0438 \u0448\u0430\u0440\u0438\u0440 \u0432\u0430 \u043c\u0443\u0444\u0441\u0438\u0434.\n\u043e\u0431\u0440\u04ef\u0438 \u043c\u0430\u043d.\n\u0427\u0430\u0448\u043c\u04b3\u043e\u0440\u043e \u0431\u0430 \u043c\u0430\u043d \u0444\u0443\u0440\u04ef\u0448 \u0431\u0430 \u043e\u0431\n\u0412-\u0430\u0440\u043d\u0430 \u0437\u0438 \u0438\u043d \u043e\u0431\u0445\u04ef\u0440\u0434\n\u0440\u04ef\u0439 \u0431\u0438\u0442\u043e\u0431!\xbb\n\u0425\u0430\u0439\u0440 \u0433\u0443\u0444\u0442: \xab\u0410\u0437 \u0425\u0443\u0434\u043e \u043d\u0430\u0434\u043e\u0440\u04e3 \u0448\u0430\u0440\u043c,\n\u041a-\u043e\u0431\u0438 \u0441\u0430\u0440\u0434\u0430\u043c \u0434\u0438\u04b3\u04e3 \u0431\u0430 \u043e\u0442\u0430\u0448\u0438 \u0433\u0430\u0440\u043c?\n\u0427\u0430\u0448\u043c\u0430 \u0433\u04ef\u044f\u043c, \u043a\u0438 \u0445\u0443\u0448\u0433\u0443\u0432\u043e\u0440\n\u0431\u0443\u0432\u0430\u0434,\n\u0427\u0430\u0448\u043c \u043a\u0430\u043d\u0434\u0430\u043d \u0431\u0438\u0433\u04ef, \u0447\u04e3 \u043a\u043e\u0440 \u0431\u0443\u0432\u0430\u0434?!\n\u0427\u0443 \u043c\u0430\u043d \u0430\u0437 \u0447\u0430\u0448\u043c\u0438 \u0445\u0443\u0434 \u0448\u0430\u0432\u0430\u043c \u0434\u0430\u0440\u0432\u0435\u0448\n,\n\u0427\u0430\u0448\u043c\u0430 \u0433ap cap \u0448\u0430\u0432\u0430\u0434, \u0447\u04e3 \u0441\u0443\u0434 \u0430\u0437 \u043f\u0435\u0448?\n\u041b\u0430\u044a\u043b \u0431\u0438\u0441\u0442\u043e\u043d\u0443 \u043e\u043d \u0447\u04e3 \u0434\u043e\u0440\u0430\u043c \u0447\u0438\u0437,\n\u0411\u0438\u0434\u0438\u04b3\u0430\u043c \u0445\u0430\u0442 \u0431\u0430 \u043e\u043d \u0447\u04e3 \u0434\u043e\u0440\u0430\u043c \u043d\u0438\u0437.\n\u0427\u0430\u0448\u043c \u0431\u0438\u0433\u0437\u043e\u0440 \u0431\u0430\u0440 \u043c\u0430\u043d, \u044d\u0439 \u0441\u0430\u0440\u0430\u043c\u0430\u0440\u0434,\n\u0421\u0430\u0440\u0434\u043c\u0435\u04b3\u0440\u04e3 \u043c\u0430\u043a\u0443\u043d \u0431\u0430 \u043e\u0431\u0438 \u0441\u0430\u0440\u0434!\xbb\n\u0413\u0443\u0444\u0442 \u0428\u0430\u0440: \xab\u0418\u043d \u0441\u0443\u0445\u0430\u043d \u0444\u0430\u0441\u043e\u043d\u0430 \u0431\u0443\u0432\u0430\u0434,\n\u0422\u0430\u0448\u043d\u0430\u0440\u043e \u0437-\u0438\u043d \u0431\u0430\u0441\u0435 \u0431\u0430\u04b3\u043e\u043d\u0430 \u0431\u0443\u0432\u0430\u0434!\n\u0427\u0430\u0448\u043c \u0431\u043e\u044f\u0434, \u0433\u0443\u04b3\u0430\u0440 \u043d\u0430\u0434\u043e\u0440\u0430\u0434 \u0441\u0443\u0434,\n\u041a-\u0438\u043d \u0433\u0443\u04b3\u0430\u0440 \u0431\u0435\u0448 \u0430\u0437 \u0438\u043d \u0442\u0430\u0432\u043e\u043d\u0430\u0434 \u0431\u0443\u0434!\xbb\n\u0425\u0430\u0439\u0440 \u0434\u0430\u0440 \u043a\u043e\u0440\u0438 \u0445\u0435\u0448 \u0445\u0438\u0440\u0430 \u0431\u0438\u043c\u043e\u043d\u0434\n,\n\u041e\u0431\u0438 \u0447\u0430\u0448\u043c\u0435 \u0431\u0430\u0440 \u043e\u0431\u0438 \u0447\u0430\u0448\u043c\u0430 \u0444\u0438\u0448\u043e\u043d\u0434.\n\u0414\u0438\u0434, \u043a-\u0430\u0437 \u0442\u0430\u0448\u043d\u0430\u0433\u04e3 \u0431\u0438\u0445\u043e\u04b3\u0430\u0434 \u043c\u0443\u0440\u0434,\n\u04b6\u043e\u043d \u0430\u0437 \u0438\u043d \u04b7\u043e\u0439\u0433\u0430\u04b3 \u043d\u0430\u0445\u043e\u04b3\u0430\u0434 \u0431\u0443\u0440\u0434\n.\n\u0414\u0438\u043b\u0438 \u0433\u0430\u0440\u043c\u0430\u0448 \u0431\u0430 \u043e\u0431\u0438 \u0441\u0430\u0440\u0434 \u0444\u0438\u0440\u0435\u0444\u0442,\n\u0422\u0430\u0448\u043d\u0430\u0435 \u043a\u0430\u0439 \u0437\u0438 \u043e\u0431\u0438 \u0441\u0430\u0440\u0434 \u0448\u0438\u0433\u0438\u0444\u0442\n\u0413\u0443\u0444\u0442: \xab\u0411\u0430\u0440\u0445\u0435\u0437\u0443 \u0442\u0435\u0493\u0443 \u0434\u0430\u0448\u043d\u0430\n\u0431\u0438\u0451\u0440,\n\u0428\u0430\u0440\u0431\u0430\u0442\u0438 \u043e\u0431 \u0441\u04ef\u0439\u0438 \u0442\u0430\u0448\u043d\u0430 \u0431\u0438\u0451\u0440!\n\u0414\u0438\u0434\u0430\u0438 \u043e\u0442\u0430\u0448\u0438\u043d\u0438 \u043c\u0430\u043d \u0431\u0430\u0440\u043a\u0430\u0448,\n\u041e\u0442\u0430\u0448\u0438 \u043c\u0430\u043d \u0431\u0438\u043a\u0443\u0448 \u0431\u0430 \u043e\u0431\u0438 \u0445\u0432\u0430\u0448!\xbb\n\u0417\u0430\u043d\u043d\n\u0447\u0443\u043d\u043e\u043d \u0431\u0443\u0440\u0434, \u043a-\u0430\u0437 \u0447\u0443\u043d\u043e\u043d \u0442\u0430\u0441\u043b\u0438\u043c,\n\u0401\u0431\u0430\u0434 \u0443\u043c\u0435\u0434\u0432\u043e\u0440\u04e3 \u0430\u0437 \u0441\u0430\u0440\u0438 \u0431\u0438\u043c.\n\u0428\u0430\u0440, \u043a\u0438 \u043e\u043d \u0434\u0438\u0434, \u0434\u0430\u0448\u043d\u0430 \u0431\u043e\u0437\u043a\u0443\u0448\u043e\u0434,\n\u041f\u0435\u0448\u0438 \u043e\u043d \u0445\u043e\u043a\u0438 \u0442\u0430\u0448\u043d\u0430 \u0440\u0430\u0444\u0442 \u0447\u0443 \u0431\u043e\u0434.\n\u043e\u0431\u0445\u04ef\u0440\u04e3.\n\u0445\u0443\u0448\u0442\u0430\u044a\u043c.\n\u0431\u0435\u0447\u0430\u0448\u043c \u043c\u043e\u043d\u0434\u0430\u043d.\n\u04b3\u0430\u0439\u0440\u043e\u043d \u043c\u043e\u043d\u0434.\n\u0441\u0430\u043b\u043e\u043c\u0430\u0442 \u043d\u0430\u043c\u0435\u043c\u043e\u043d\u0430\u0434.\n\u0445\u0443\u0434\u0434\u043e\u0440\u04e3 \u043a\u0430\u0440\u0434.\n\u0445\u0430\u043d\u04b7\u0430\u0440.\n\u0433\u0443\u043c\u043e\u043d.\n\u0414\u0430\u0440 \u0447\u0430\u0440\u043e\u0493\u0438 \u0434\u0443 \u0447\u0430\u0448\u043c\u0438 \u04ef \u0437\u0430\u0434 \u0442\u0435\u0493,\n\u041d-\u043e\u043c\u0430\u0434\u0430\u0448 \u043a\u0443\u0448\u0442\u0430\u043d\u0438 \u0447\u0430\u0440\u043e\u0493 \u0434\u0430\u0440\u0435\u0493!\n\u041d\u0430\u0440\u0433\u0438\u0441\u0430\u0448\u0440\u043e\n\u0431\u0430 \u0442\u0435\u0493 \u0433\u0443\u043b\u0433\u0443\u043d \u043a\u0430\u0440\u0434,\n\u0413\u0430\u0432\u04b3\u0430\u0440\u0430\u0448\u0440\u043e \u0437\u0438 \u0442\u043e\u04b7 \u0431\u0435\u0440\u0443\u043d \u043a\u0430\u0440\u0434!\n\u0427\u0430\u0448\u043c\u0438 \u0442\u0430\u0448\u043d\u0430 \u0447\u0443 \u043a\u0430\u0440\u0434\u0430 \u0431\u0443\u0434 \u0442\u0430\u0431\u043e\u04b3,\n\u041e\u0431 \u043d\u043e\u0434\u043e\u0434\u0430, \u043a\u0430\u0440\u0434 \u04b3\u0438\u043c\u043c\u0430\u0442\u0438 \u0440\u043e\u04b3\n.\n\u04b6\u043e\u043c\u0430\u044e \u0440\u0430\u0445\u0442\u0443 \u0433\u0430\u0432\u04b3\u0430\u0440\u0430\u0448 \u0431\u0430\u0440\u0434\u043e\u0448\u0442,\n\u041c\u0430\u0440\u0434\u0438 \u0431\u0435\u0434\u0438\u043b\u0440\u043e \u0442\u0438\u04b3\u04e3 \u0431\u0438\u0433\u0443\u0437\u043e\u0448\u0442.\n\u0425\u0430\u0439\u0440 \u0447\u0443\u043d \u0440\u0430\u0444\u0442\u0430 \u0434\u0438\u0434 \u0428\u0430\u0440 \u0437\u0438 \u0431\u0430\u0440\u0430\u0448,\n\u041d\u0430\u0448\u0443\u0434 \u043e\u0433\u043e\u04b3\u0438\u0435, \u0437\u0438 \u0445\u0430\u0439\u0440\u0443 \u0448\u0430\u0440\u0430\u0448\n.\n\u0411\u0430\u0440 \u0441\u0430\u0440\u0438 \u0445\u043e\u0440\u0443 \u0445\u043e\u043a \u043c\u0435\u0493\u0430\u043b\u0442\u0438\u0434,\n\u0411\u0435\u04b3, \u043a\u0438 \u0447\u0430\u0448\u043c\u0430\u0448 \u043d\u0430\u0431\u0443\u0434, \u043a\u0438 \u0445\u0443\u0434\u0440\u043e \u0434\u0438\u0434!\n\u04b2\u043e\u043b\u0438 \u0445\u0443\u0434 \u0433\u0430\u0440 \u0431\u0430 \u0447\u0430\u0448\u043c\u0438 \u0445\u0443\u0434 \u0434\u0438\u0434\u04e3,\n\u041c\u0443\u0440\u0434\u04e3 \u0430\u0437 \u0493\u0430\u043c, \u0447\u0443\u043d\u043e\u043d \u0431\u0438\u0442\u0430\u0440\u0441\u0438\u0434\u04e3!")
B.a6p=new A.a("b95fdbaa-9e00-428a-a90b-edbabc442316","38f2044a-792f-46be-8707-90721abe3ea1","\u0425\u0430\u0439\u0440 \u0432\u0430 \u0428\u0430\u0440 (\u0438\u0434\u043e\u043c\u0430)","\u0411\u0443\u0440\u0434\u04e3 \u043e\u0431\u0443 \u043d\u0430\u0434\u043e\u0434\u0438\u044f\u0448 \u043e\u0431\u0435.\n\u0413\u0430\u0432\u04b3\u0430\u0440\u0438 \u0447\u0430\u0448\u043c\u0443 \u0433\u0430\u0432\u04b3\u0430\u0440\u0438 \u043a\u0430\u043c\u0430\u0440\u0430\u0448\n\u04b2\u0430\u0440 \u0434\u0443 \u0431\u0443\u0440\u0434\u0438\u044e \u0441\u04ef\u0445\u0442\u04e3 \u04b7\u0438\u0433\u0430\u0440\u0430\u0448.\n\u041c\u0430\u043d\u0430\u043c \u043e\u043d \u0442\u0430\u0448\u043d\u0430\u0438 \u0433\u0443\u04b3\u0430\u0440\u0431\u0443\u0440\u0434\u0430,\n\u0411\u0430\u0445\u0442\u0438 \u043c\u0430\u043d \u0437\u0438\u043d\u0434\u0430, \u0431\u0430\u0445\u0442\u0438 \u0442\u0443 \u043c\u0443\u0440\u0434\u0430!\xbb\n\u0428\u0430\u0440, \u043a\u0438 \u0434\u0430\u0440 \u0440\u04ef\u0439\u0438 \u0425\u0430\u0439\u0440 \u0434\u0438\u0434, \u0448\u0438\u043d\u043e\u0445\u0442,\n\u0425\u0435\u0448\u0442\u0430\u043d \u0437\u0443\u0434 \u0431\u0430\u0440 \u0437\u0430\u043c\u0438\u043d \u0430\u043d\u0434\u043e\u0445\u0442.\n\u0413\u0443\u0444\u0442: \xab\u0417\u0438\u043d\u04b3\u043e\u0440, \u0430\u0433\u0430\u0440\u0447\u0438 \u0431\u0430\u0434 \u043a\u0430\u0440\u0434\u0430\u043c,\n\u0414\u0430\u0440 \u0431\u0430\u0434\u0438 \u043c\u0430\u043d \u043c\u0430\u0431\u0438\u043d, \u043a\u0438 \u0445(\u0432)\u0430\u0434 \u043a\u0430\u0440\u0434\u0430\u043c.\n\u0413\u0430\u0440 \u043c\u0430\u043d \u043e\u043d \u0431\u043e \u0442\u0443 \u043a\u0430\u0440\u0434\u0430\u0430\u043c \u0437\u0438 \u043d\u0430\u0445\u0443\u0441\u0442,\n\u041a-\u043e\u044f\u0434 \u0430\u0437 \u043d\u043e\u043c\u0438 \u0447\u0443\u043d \u043c\u0430\u043d\u0435 \u0431\u0430 \u0434\u0443\u0440\u0443\u0441\u0442.\n\u0411\u043e \u043c\u0430\u043d \u043e\u043d \u043a\u0443\u043d, \u0442\u0443 \u0434\u0430\u0440 \u0447\u0443\u043d\u043e\u043d \u0445\u0430\u0442\u0430\u0440\u0435,\n\u041a-\u043e\u044f\u0434 \u0430\u0437 \u043d\u043e\u043c\u0438 \u0447\u0443\u043d \u0442\u0443 \u043d\u043e\u043c\u0432\u0430\u0440\u0435\xbb.\n\u0425\u0430\u0439\u0440, \u043a-\u043e\u043d \u043d\u0443\u043a\u0442\u0430 \u0440\u0430\u0444\u0442 \u0431\u0430\u0440 \u0451\u0434\u0430\u0448,\n\u041a\u0430\u0440\u0434 \u04b3\u043e\u043b\u04e3 \u0437\u0438 \u043a\u0443\u0448\u0442\u0430\u043d \u043e\u0437\u043e\u0434\u0430\u0448.\n\u0428\u0430\u0440 \u0447\u0443 \u0430\u0437 \u0442\u0435\u0493 \u0451\u0444\u0442 \u043e\u0437\u043e\u0434\u04e3,\n\u041c\u0435\u0448\u0443\u0434\u0443 \u043c\u0435\u043f\u0430\u0440\u0438\u0434 \u0430\u0437 \u0448\u043e\u0434\u04e3.\n\u041a\u0443\u0440\u0434\u0438 \u0445\u0443\u043d\u0445\u043e\u0440 \u0440\u0430\u0444\u0442 \u0431\u0430\u0440 \u0430\u0441\u0430\u0440\u0430\u0448,\n\u0422\u0435\u0493 \u0437\u0430\u0434 \u0432\u0430 \u0430\u0437 \u049b\u0430\u0444\u043e, \u0431\u0443\u0440\u0438\u0434 \u0441\u0430\u0440\u0430\u0448.\n\u0413\u0443\u0444\u0442: \xab\u0410\u0433\u0430\u0440 \u0425\u0430\u0439\u0440 \u04b3\u0430\u0441\u0442 \u0445\u0430\u0439\u0440\u0430\u043d\u0434\u0435\u0448,\n\u0422\u0443 \u0428\u0430\u0440\u04e3, \u04b7\u0443\u0437 \u0448\u0430\u0440\u0430\u0442 \u043d\u0430\u0451\u044f\u0434 \u043f\u0435\u0448\xbb.\n\u0414\u0430\u0440 \u0442\u0430\u043d\u0430\u0448 \u04b7\u0443\u0441\u0442\u0443 \u0451\u0444\u0442 \u043e\u043d \u0434\u0443 \u0433\u0443\u04b3\u0430\u0440,\n\u0422\u0430\u044a\u0431\u0438\u044f \u043a\u0430\u0440\u0434\u0430 \u0434\u0430\u0440 \u043c\u0438\u0451\u043d\u0438 \u043a\u0430\u043c\u0430\u0440.\n\u041e\u043c\u0430\u0434, \u043e\u0432\u0430\u0440\u0434 \u043f\u0435\u0448\u0438 \u0425\u0430\u0439\u0440 \u0444\u0430\u0440\u043e\u0437,\n\u0413\u0443\u0444\u0442:\xab\u0413\u0430\u0432\u04b3\u0430\u0440 \u0431\u0430 \u0433\u0430\u0432\u04b3\u0430\u0440 \u043e\u043c\u0430\u0434 \u0431\u043e\u0437\xbb.\n\u0425\u0430\u0439\u0440 \u0431\u04ef\u0441\u0438\u0434\u0443 \u043f\u0435\u0448\u0438 \u043a\u0443\u0440\u0434 \u0430\u043d\u0434\u043e\u0445\u0442,\n\u0413\u0430\u0432\u04b3\u0430\u0440\u0438\u0440\u043e \u0431\u0430 \u0433\u0430\u0432\u04b3\u0430\u0440\u0435 \u0431\u0438\u043d\u0430\u0432\u043e\u0445\u0442.\n\u0414\u0430\u0441\u0442 \u0431\u0430\u0440 \u0447\u0430\u0448\u043c\u0438 \u0445\u0443\u0434 \u043d\u0438\u04b3\u043e\u0434\u0443 \u0431\u0438\u0433\u0443\u0444\u0442:\n\xab\u0410\u0437 \u0442\u0443 \u0434\u043e\u0440\u0430\u043c \u043c\u0430\u043d \u0438\u043d \u0434\u0443 \u0433\u0430\u0432\u04b3\u0430\u0440\u0438 \u04b7\u0443\u0444\u0442!\n\u0418\u043d \u0434\u0443 \u0433\u0430\u0432\u04b3\u0430\u0440 \u0431\u0430\u0434-\u043e\u043d \u0448\u0443\u0434 \u0430\u0440\u0437\u043e\u043d\u04e3,\n\u0418\u043d \u0433\u0443\u04b3\u0430\u0440\u04b3\u043e \u0442\u0443\u0440\u043e\u0441\u0442, \u0445\u0443\u0434 \u0434\u043e\u043d\u04e3!\xbb\n\u0427\u0443\u043d\u043a\u0438 \u0448\u0443\u0434 \u043a\u043e\u0440\u04b3\u043e\u0438 \u0425\u0430\u0439\u0440 \u0431\u0430 \u043a\u043e\u043c,\n\u0425\u0430\u043b\u049b \u0430\u0437 \u04ef \u0434\u0438\u0434 \u0445\u0430\u0439\u0440\u0445\u043e\u04b3\u04e3 \u0442\u0430\u043c\u043e\u043c.\n\u0427\u0443\u043d \u0441\u0430\u043e\u0434\u0430\u0442 \u0431\u0430\u0434-\u04ef \u0441\u0443\u043f\u0443\u0440\u0434 \u0441\u0430\u0440\u0438\u0440,\n\u041e\u04b3\u0430\u043d\u0430\u0448 \u0437\u0430\u0440 \u0448\u0443\u0434\u0443 \u043f\u0430\u043b\u043e\u0441 \u04b3\u0430\u0440\u0438\u0440.\n\u0410\u0434\u043b\u0440\u043e \u0443\u0441\u0442\u0443\u0432\u043e\u0440\u043a\u043e\u0440\u04e3 \u0434\u043e\u0434,\n\u041c\u0443\u043b\u043a\u0440\u043e \u0431\u0430\u0440 \u0445\u0443\u0434 \u0443\u0441\u0442\u0443\u0432\u043e\u0440\u04e3 \u0434\u043e\u0434.\n\u0411\u0430\u0440\u0433\u04b3\u043e\u0440\u043e, \u043a-\u0430\u0437 \u043e\u043d \u0434\u0430\u0440\u0430\u0445\u0442 \u043e\u0432\u0430\u0440\u0434,\n\u0420\u043e\u04b3\u0430\u0442\u0438 \u0440\u0430\u043d\u04b7\u04b3\u043e\u0438 \u0441\u0430\u0445\u0442 \u043e\u0432\u0430\u0440\u0434.\n\u0412\u0430\u049b\u0442-\u0432\u0430\u049b\u0442 \u0430\u0437 \u0431\u0430\u0440\u043e\u0438 \u0434\u0430\u0444\u044a\u0438 \u0433\u0430\u0437\u0430\u043d\u0434,\n\u0422\u043e\u0445\u0442\u04e3 \u0441\u04ef\u0439\u0438 \u043e\u043d \u0434\u0430\u0440\u0430\u0445\u0442\u0438 \u0431\u0430\u043b\u0430\u043d\u0434.\n\u041e\u043c\u0430\u0434\u04e3 \u0437\u0435\u0440\u0438 \u043e\u043d \u0434\u0430\u0440\u0430\u0445\u0442 \u0444\u0443\u0440\u0443\u0434,\n\u0414\u043e\u0434\u04e3 \u043e\u043d \u0431\u0443\u043c\u0440\u043e \u0441\u0430\u043b\u043e\u043c\u0443 \u0434\u0443\u0440\u0443\u0434.")
B.acx=new A.a("9ea2d339-2781-41b2-ae6c-2cd9d0a30fd5","38f2044a-792f-46be-8707-90721abe3ea1","\u0421\u0423\u041b\u0422\u041e\u041d \u0421\u0410\u041d\u04b6\u0410\u0420 \u0412\u0410 \u041f\u0418\u0420\u0410\u0417\u0410\u041d","\u041f\u0438\u0440\u0430\u0437\u0430\u043d\u0435\u0440\u043e \u0441\u0438\u0442\u0430\u043c\u0435 \u0434\u0430\u0440\u0433\u0438\u0440\u0438\u0444\u0442,\n\u0414\u0430\u0441\u0442 \u0437\u0430\u0434\u0443 \u0434\u043e\u043c\u0430\u043d\u0438 \u0421\u0430\u043d\u04b7\u0430\u0440 \u0433\u0438\u0440\u0438\u0444\u0442.\n\u041a-\xab\u042d\u0439 \u043c\u0430\u043b\u0438\u043a, \u043e\u0437\u0430\u0440\u043c\u0438 \u0442\u0443 \u043a\u0430\u043c \u0434\u0438\u0434\u0430\u0430\u043c,\n\u0412-\u0430\u0437 \u0442\u0443 \u04b3\u0430\u043c\u0430\u0441\u043e\u043b\u0430 \u0441\u0438\u0442\u0430\u043c \u0434\u0438\u0434\u0430\u0430\u043c.\n\u0428\u0430\u04b3\u043d\u0430\u0438 \u043c\u0430\u0441\u0442 \u043e\u043c\u0430\u0434\u0430 \u0434\u0430\u0440 \u043a\u04ef\u0439\u0438 \u043c\u0430\u043d,\n\u0417\u0430\u0434 \u043b\u0430\u0433\u0430\u0434\u0435 \u0447\u0430\u043d\u0434 \u0444\u0430\u0440\u043e\u0440\u04ef\u0438 \u043c\u0430\u043d.\n\u0411\u0435\u0433\u0443\u043d\u0430\u04b3 \u0430\u0437 \u0445\u043e\u043d\u0430 \u0431\u0430 \u0440\u04ef\u044f\u043c \u043a\u0430\u0448\u0438\u0434,\n\u041c\u04ef\u0439\u043a\u0430\u0448\u043e\u043d \u0431\u0430\u0440 \u0441\u0430\u0440\u0438 \u043a\u04ef\u044f\u043c \u043a\u0430\u0448\u0438\u0434.\n\u0414\u0430\u0440 \u0441\u0438\u0442\u0430\u043c\u043e\u0431\u043e\u0434 \u0437\u0430\u0431\u043e\u043d\u0430\u043c \u043d\u0438\u04b3\u043e\u0434,\n\u041c\u0443\u04b3\u0440\u0438 \u0441\u0438\u0442\u0430\u043c, \u0431\u0430\u0440 \u0434\u0430\u0440\u0438 \u0445\u043e\u043d\u0430\u043c \u043d\u0438\u04b3\u043e\u0434.\n\u0413\u0443\u0444\u0442: \xab\u0424\u0430\u043b\u043e\u043d \u043d\u0438\u043c\u0448\u0430\u0431, \u044d\u0439 \u043a\u04ef\u0437\u043f\u0443\u0448\u0442,\n\u0411\u0430\u0440 \u0441\u0430\u0440\u0438 \u043a\u04ef\u0438 \u0442\u0443 \u0444\u0430\u043b\u043e\u043d\u0440\u043e \u043a\u04e3 \u043a\u0443\u0448\u0442?!\xbb\n\u0425\u043e\u043d\u0430\u0438 \u043c\u0430\u043d \u04b7\u0443\u0441\u0442, \u043a\u0438 \u0445\u0443\u043d\u04e3 \u043a\u0443\u04b7\u043e\u0441\u0442,\n\u042d\u0439 \u0448\u0430\u04b3, \u0430\u0437 \u0438\u043d \u0431\u0435\u0448 \u0437\u0430\u0431\u0443\u043d\u04e3 \u043a\u0443\u04b7\u043e\u0441\u0442?\n\u0428\u0430\u04b3\u043d\u0430 \u0431\u0443\u0432\u0430\u0434 \u043c\u0430\u0441\u0442, \u043a\u0438 \u043e\u043d \u0445\u0443\u043d \u043a\u0443\u043d\u0430\u0434,\n\u0410\u0440\u0431\u0430\u0434\u0430 \u0431\u0430\u0440 \u043f\u0438\u0440\u0430\u0437\u0430\u043d\u0435 \u0447\u0443\u043d \u043a\u0443\u043d\u0430\u0434?\n\u0420\u0430\u0442\u043b\u0437\u0430\u043d\u043e\u043d \u0434\u0430\u0445\u043b\u0438 \u0432\u0438\u043b\u043e\u044f\u0442 \u0431\u0430\u0440\u0430\u043d\u0434,\n\u041f\u0438\u0440\u0430\u0437\u0430\u043d\u043e\u043d\u0440\u043e \u0431\u0430 \u04b7\u0438\u043d\u043e\u044f\u0442 \u0431\u0430\u0440\u0430\u043d\u0434.\n\u041e\u043d \u043a\u0438 \u0434\u0430\u0440 \u0438\u043d \u0437\u0443\u043b\u043c \u043d\u0430\u0437\u0430\u0440 \u0434\u043e\u0448\u0442\u0430\u0441\u0442,\n\u0421\u0438\u0442\u0440\u0438 \u043c\u0430\u043d\u0443 \u0430\u0434\u043b\u0438 \u0442\u0443 \u0431\u0430\u0440\u0434\u043e\u0448\u0442\u0430\u0441\u0442.\n\u041a\u04ef\u0444\u0442\u0430 \u0448\u0443\u0434 \u0441\u0438\u043d\u0430\u0438 \u043c\u0430\u04b7\u0440\u04ef\u04b3\u0438 \u043c\u0430\u043d,\n\u04b2\u0435\u04b7 \u043d\u0430\u043c\u043e\u043d\u0434 \u0430\u0437 \u043c\u0430\u043d\u0443 \u0430\u0437 \u0440\u04ef\u04b3\u0438 \u043c\u0430\u043d.\n\u0413\u0430\u0440 \u043d\u0430\u0434\u0438\u04b3\u04e3 \u0434\u043e\u0434\u0438 \u043c\u0430\u043d, \u044d\u0439 \u0448\u0430\u04b3\u0440\u0438\u0451\u0440,\n\u0411\u043e \u0442\u0443 \u0440\u0430\u0432\u0430\u0434 \u0440\u04ef\u0437\u0438 \u0448\u0443\u043c\u043e\u0440 \u0438\u043d \u0448\u0443\u043c\u043e\u0440.\n\u0414\u043e\u0432\u0430\u0440\u0438\u044e \u0434\u043e\u0434 \u043d\u0430\u043c\u0435\u0431\u0438\u043d\u0430\u043c\u0430\u0442,\n\u0412-\u0430\u0437 \u0441\u0438\u0442\u0430\u043c \u043e\u0437\u043e\u0434 \u043d\u0430\u043c\u0435\u0431\u0438\u043d\u0430\u043c\u0430\u0442.\n\u0410\u0437 \u043c\u0430\u043b\u0438\u043a\u043e\u043d \u049b\u0443\u0432\u0432\u0430\u0442\u0443 \u0451\u0440\u04e3 \u0440\u0430\u0441\u0430\u0434,\n\u0410\u0437 \u0442\u0443 \u0431\u0430 \u043c\u043e \u0431\u0438\u043d, \u043a\u0438 \u0447\u04e3 \u0445\u043e\u0440\u04e3 \u0440\u0430\u0441\u0430\u0434.\n\u041c\u043e\u043b\u0438 \u044f\u0442\u0438\u043c\u043e\u043d \u0441\u0438\u0442\u0443\u0434\u0430\u043d \u043a\u043e\u0440 \u043d\u0435\u0441\u0442,\n\u0411\u0438\u0433\u0437\u043e\u0440, \u043a-\u0438\u043d \u043e\u0434\u0430\u0442\u0438 \u0430\u04b3\u0440\u043e\u0440 \u043d\u0435\u0441\u0442.\n\u0411\u0430\u0440 \u043f\u0430\u043b\u0430\u0438 \u043f\u0438\u0440\u0430\u0437\u0430\u043d\u043e\u043d \u0440\u0430\u04b3 \u043c\u0430\u0437\u0430\u043d,\n\u0428\u0430\u0440\u043c \u0431\u0438\u0434\u043e\u0440 \u0430\u0437 \u043f\u0430\u043b\u0430\u0438 \u043f\u0438\u0440\u0430\u0437\u0430\u043d.\n\u0411\u0430\u043d\u0434\u0430\u0438\u0432\u0443 \u0434\u0430\u044a\u0432\u0438\u0438 \u0448\u043e\u04b3\u04e3 \u043a\u0443\u043d\u04e3,\n\u0428\u043e\u04b3 \u043d\u0430\u04e3, \u0447\u0443\u043d\u043a\u0438 \u0442\u0430\u0431\u043e\u04b3\u04e3 \u043a\u0443\u043d\u04e3.\n\u0428\u043e\u04b3, \u043a\u0438 \u0442\u0430\u0440\u0442\u0438\u0431\u0438 \u0432\u0438\u043b\u043e\u044f\u0442 \u043a\u0443\u043d\u0430\u0434,\n\u04b2\u0443\u043a\u043c\u0438 \u0440\u0430\u0438\u044f\u0442 \u0431\u0430 \u0440\u0438\u043e\u044f\u0442 \u043a\u0443\u043d\u0430\u0434.\n\u0422\u043e \u04b3\u0430\u043c\u0430 cap \u0431\u0430\u0440 \u0445\u0430\u0442\u0438 \u0444\u0430\u0440\u043c\u043e\u043d \u043d\u0438\u04b3\u0430\u043d\u0434,\n\u0414\u04ef\u0441\u0442\u0438\u044f\u0448 \u0434\u0430\u0440 \u0434\u0438\u043b\u0443 \u0434\u0430\u0440 \u04b7\u043e\u043d \u043d\u0438\u04b3\u0430\u043d\u0434.\n\u041e\u043b\u0430\u043c\u0435\u0440\u043e \u0437\u0435\u0440\u0443 \u0437\u0430\u0431\u0430\u0440 \u043a\u0430\u0440\u0434\u0430\u04e3,\n\u0422\u043e \u0442\u0443\u04e3, \u043e\u0445\u0438\u0440 \u0447\u04e3 \u04b3\u0443\u043d\u0430\u0440 \u043a\u0430\u0440\u0434\u0430\u04e3?\n\u0414\u0430\u0432\u043b\u0430\u0442\u0438 \u0442\u0443\u0440\u043a\u043e\u043d, \u043a\u0438 \u0431\u0430\u043b\u0430\u043d\u0434\u04e3 \u0433\u0438\u0440\u0438\u0444\u0442,\n\u041c\u0430\u043c\u043b\u0430\u043a\u0430\u0442 \u0430\u0437 \u0434\u043e\u0434 \u043f\u0438\u0441\u0430\u043d\u0434\u04e3 \u0433\u0438\u0440\u0438\u0444\u0442.\n\u0427\u0443\u043d\u043a\u0438 \u0442\u0443 \u0431\u0435\u0434\u043e\u0434\u0433\u0430\u0440\u04e3 \u043f\u0430\u0440\u0432\u0430\u0440\u04e3,\n\u0422\u0443\u0440\u043a \u043d\u0430\u04e3, \u04b3\u0438\u043d\u0434\u0443\u0438 \u0493\u043e\u0440\u0430\u0442\u0433\u0430\u0440\u04e3!\n\u041c\u0430\u0441\u043a\u0430\u043d\u0438 \u0448\u0430\u04b3\u0440\u04e3 \u0437\u0438 \u0442\u0443 \u0432\u0430\u0439\u0440\u043e\u043d\u0430 \u0448\u0443\u0434,\n\u0425\u0438\u0440\u043c\u0430\u043d\u0438 \u0434\u0435\u04b3\u049b\u043e\u043d \u0437\u0438 \u0442\u0443 \u0431\u0435\u0434\u043e\u043d\u0430 \u0448\u0443\u0434.\n\u0417-\u043e\u043c\u0430\u0434\u0430\u043d\u0438 \u043c\u0430\u0440\u0433 \u0448\u0443\u043c\u043e\u0440\u0435 \u0431\u0438\u043a\u0443\u043d,\n\u041c\u0435\u0440\u0430\u0441\u0430\u0434\u0430\u0442 \u0434\u0430\u0441\u0442, \u04b3\u0438\u0441\u043e\u0440\u0435 \u0431\u0438\u043a\u0443\u043d.\n\u0410\u0434\u043b\u0438 \u0442\u0443 \u049b\u0430\u043d\u0434\u0438\u043b\u0438 \u0448\u0430\u0431\u0430\u0444\u0440\u04ef\u0437\u0438 \u0442\u0443\u0441\u0442,\n\u041c\u0443\u043d\u0438\u0441\u0438 \u0444\u0430\u0440\u0434\u043e\u0438 \u0442\u0443 \u0438\u043c\u0440\u04ef\u0437\u0438 \u0442\u0443\u0441\u0442.\n\u041f\u0438\u0440\u0430\u0437\u0430\u043d\u043e\u043d\u0440\u043e \u0431\u0430 \u0441\u0443\u0445\u0430\u043d \u0448\u043e\u0434 \u0434\u043e\u0440,\n\u0412-\u0438\u043d \u0441\u0443\u0445\u0430\u043d \u0430\u0437 \u043f\u0438\u0440\u0430\u0437\u0430\u043d\u0435 \u0451\u0434 \u0434\u043e\u0440.\n\u0414\u0430\u0441\u0442 \u0431\u0438\u0434\u043e\u0440 \u0430\u0437 \u0441\u0430\u0440\u0438 \u0431\u0435\u0447\u043e\u0440\u0430\u0433\u043e\u043d,\n\u0422\u043e \u043d\u0430\u0445\u04ef\u0440\u04e3 \u0451\u0441\u0438\u04b7\u0438 \u0493\u0430\u043c\u0445\u043e\u0440\u0430\u0433\u043e\u043d.\n\u0427\u0430\u043d\u0434 \u0437\u0430\u043d\u04e3 \u0442\u0438\u0440 \u0431\u0430 \u04b3\u0430\u0440 \u0433\u04ef\u0448\u0430\u0435,\n\u0492\u043e\u0444\u0438\u043b\u04e3 \u0430\u0437 \u0442\u04ef\u0448\u0430\u0438 \u0431\u0435\u0442\u04ef\u0448\u0430\u0435,\n\u0424\u0430\u0442\u04b3\u0438 \u04b7\u0430\u04b3\u043e\u043d\u0440\u043e \u0442\u0443 \u043a\u0430\u043b\u0438\u0434 \u043e\u043c\u0430\u0434\u04e3,\n\u041d-\u0430\u0437 \u043f\u0430\u0439\u0438 \u0431\u0435\u0434\u043e\u0434 \u043f\u0430\u0434\u0438\u0434 \u043e\u043c\u0430\u0434\u04e3.\n\u0420\u0430\u0441\u043c\u0438 \u0437\u0430\u0438\u0444\u043e\u043d \u0431\u0430 \u0442\u0443 \u043d\u043e\u0437\u0438\u0448 \u0431\u0443\u0432\u0430\u0434,\n\u0420\u0430\u0441\u043c\u0438 \u0442\u0443 \u0431\u043e\u044f\u0434, \u043a\u0438 \u043d\u0430\u0432\u043e\u0437\u0438\u0448 \u0431\u0443\u0432\u0430\u0434.\n\u0413\u04ef\u0448 \u0431\u0430 \u0434\u0430\u0440\u044e\u0437\u0430\u0438 \u0430\u043d\u0444\u043e\u0441 \u0434\u043e\u0440,\n\u0413\u04ef\u0448\u0430\u043d\u0438\u0448\u0438\u043d\u0435 \u0434\u0443 \u0441\u0435\u0440\u043e \u043f\u043e\u0441 \u0434\u043e\u0440.\n\u0421\u0430\u043d\u04b7\u0430\u0440, \u043a-\u0438\u049b\u043b\u0438\u043c\u0438 \u0425\u0443\u0440\u043e\u0441\u043e\u043d \u0433\u0438\u0440\u0438\u0444\u0442,\n\u041a\u0430\u0440\u0434 \u0437\u0438\u0451\u043d, \u043a-\u0438\u043d \u0441\u0443\u0445\u0430\u043d \u043e\u0441\u043e\u043d \u0433\u0438\u0440\u0438\u0444\u0442.\n\u0414\u043e\u0434 \u0434\u0430\u0440 \u0438\u043d \u0434\u0430\u0432\u0440 \u0431\u0430\u0440\u0430\u043d\u0434\u043e\u0445\u0442\u0430\u0441\u0442,\n\u0414\u0430\u0440 \u043f\u0430\u0440\u0438 \u0421\u0438\u043c\u0443\u0440\u0493 \u0432\u0430\u0442\u0430\u043d \u0441\u043e\u0445\u0442\u0430\u0441\u0442.\n\u0428\u0430\u0440\u043c \u0434\u0430\u0440 \u0438\u043d \u0442\u043e\u0440\u0430\u043c\u0438 \u0430\u0437\u0440\u0430\u049b \u043d\u0430\u043c\u043e\u043d\u0434,\n\u041e\u0431 \u0434\u0430\u0440 \u0438\u043d \u0445\u043e\u043a\u0438 \u043c\u0443\u0430\u043b\u043b\u0430\u049b \u043d\u0430\u043c\u043e\u043d\u0434.\n\u0425\u0435\u0437, \u041d\u0438\u0437\u043e\u043c\u04e3, \u0437\u0438 \u04b3\u0430\u0434 \u0430\u0444\u0437\u0443\u043d\u0433\u0430\u0440\u04e3,\n\u0411\u0430\u0440 \u0434\u0438\u043b\u0438 \u0445\u0443\u043d\u043e\u0431\u0448\u0443\u0434\u0430 \u0445\u0443\u043d\u0433\u0438\u0440\u04e3.")
B.alw=new A.a("3190c8e4-d976-468a-ad1f-fc49ebf975a9","74ea3b93-4c65-4605-95a7-8c2ec4c382cc","\u0411\u0430\u0439\u0442 1","\u0428\u0443\u0434 \u0445\u0430\u0437\u043e\u043d \u0440\u0443\u0448\u0434\u0438 \u043c\u043e, \u0448\u0443\u0434 \u043a\u0430\u043c\u043e\u043d \u043f\u0443\u0448\u0442\u0438 \u043c\u043e,\n\u0425\u0443\u043d\u0438 \u0434\u0438\u043b \u043c\u0435\u0447\u0430\u043a\u0430\u0434 \u0430\u0437 \u0441\u0430\u0440\u0430\u043d\u0433\u0443\u0448\u0442\u0438 \u043c\u043e.")
B.apj=new A.a("f848dbde-f0a3-4298-9038-f1100faba810","74ea3b93-4c65-4605-95a7-8c2ec4c382cc","\u0411\u0430\u0439\u0442 2","\u0401\u0440 \u0434\u0438\u043b\u0440\u043e \u0441\u0430\u0434\u043e \u043c\u0435\u043a\u0443\u043d\u0430\u0434,\n\u0414\u0438\u043b \u043c\u0430\u0440\u043e \u0447\u0443\u043d \u0440\u0430\u04b3\u043e \u043c\u0435\u043a\u0443\u043d\u0430\u0434.")
B.akP=new A.a("5554b781-59a3-4f22-81d3-2e05adc892a7","19750e0a-7629-436e-9715-a1530d0b1571","\u0411\u0430\u0439\u0442","\u0411\u043e\u043d\u0433\u0438 \u043c\u0443\u0440\u0493\u0438 \u0441\u0430\u04b3\u0430\u0440,\n\u041c\u0435\u0440\u0430\u0441\u043e\u043d\u0430\u0434 \u0445\u0430\u0431\u0430\u0440.")
B.apn=new A.a("c211361b-1153-42dc-ab58-995120252667","44aaf1c8-ce97-4cd1-a21f-7de5db7c615d","\u0411\u0430\u0439\u0442","\u041c\u043e \u0431\u0430 \u04b3\u0430\u043c \u0442\u043e\u0445\u0442\u0435\u043c \u0434\u0430\u0440 \u0440\u0430\u04b3\u0438 \u0438\u043d\u049b\u0438\u043b\u043e\u0431,\n\u041c\u043e \u0437\u0430\u0444\u0430\u0440 \u0451\u0444\u0442\u0435\u043c, \u0431\u043e\u0441\u043c\u0430\u0447\u04e3 \u0448\u0443\u0434 \u0445\u0430\u0440\u043e\u0431.")
B.ap3=new A.a("288768ec-bb2b-4a0b-a4c4-734fcd8e5d20","82f30a4e-f468-4a7d-bf03-bd29d3279fe0","\u0411\u0430\u0439\u0442","\u0427\u0443 \u0440\u0443\u0445\u0430\u0442 \u043d\u0430\u0431\u0443\u0432\u0430\u0434 \u0433\u0443\u043b\u0438 \u0431\u043e\u0493\u0438 \u0418\u0440\u0430\u043c,\n\u0427\u0443 \u049b\u0430\u0434\u0430\u0442 \u043d\u0430\u0431\u0443\u0432\u0430\u0434 \u049b\u0430\u0434\u0438 \u0441\u0430\u0440\u0432\u0438 \u0447\u0430\u043c\u0430\u043d.")
B.alr=new A.a("a1825e4d-4f86-4ab4-8ec5-a2316e8654c7","358dda13-365c-4434-87f0-d404b305adcb","\u0411\u0430\u0439\u0442","\u0422\u043e \u043a\u0430\u0439 \u043c\u043e\u0440\u043e \u0434\u0430\u0440 \u0493\u0430\u043c \u0434\u043e\u0440\u04e3,\n\u0422\u043e \u043a\u0430\u0439 \u043e\u0440\u04e3 \u0431\u0430\u0440 \u043c\u0430\u043d \u0445\u043e\u0440\u04e3.")
B.ang=new A.a("65339408-dcae-4926-884f-2938aea0e66f","cfb751a8-dce3-4553-aef8-bc4574b2b85e","\u0411\u0430\u0439\u0442","\u0411\u0435\u043d\u0430\u0432\u043e\u0435, \u043a\u0438 \u0432\u0430\u0440\u043e \u0434\u0430\u0440 \u04b7\u0438\u0433\u0430\u0440 \u043e\u0431\u0435 \u043d\u0430\u0431\u0443\u0432\u0430\u0434,\n\u04b6\u0430\u04b3\u0434 \u043a\u0443\u043d, \u0433\u0430\u0440 \u043d\u0430\u0434\u0438\u04b3\u04e3, \u0442\u043e \u043d\u0430\u0441\u0438\u0442\u043e\u043d\u04e3 \u043d\u043e\u043d\u0430\u0448.")
B.ahO=new A.a("5f23de82-e83a-4b9c-840c-29200b4cb372","cfb751a8-dce3-4553-aef8-bc4574b2b85e","\u0410\u041d\u0414\u0410\u0420 \u0418\u041d \u0414\u0410\u0412\u0420\u041e\u041d \u041c\u0410\u04b6\u04ee \u0420\u041e\u04b2\u0410\u0422, \u041a\u0418 \u041a\u0410\u0421 \u041e\u0421\u0423\u0414\u0410 \u041d\u0415\u0421\u0422","\u0410\u043d\u0434\u0430\u0440 \u0438\u043d \u0434\u0430\u0432\u0440\u043e\u043d \u043c\u0430\u04b7\u04ef \u0440\u043e\u04b3\u0430\u0442, \u043a\u0438 \u043a\u0430\u0441 \u043e\u0441\u0443\u0434\u0430 \u043d\u0435\u0441\u0442,\n\u0422\u0430\u0431\u044a\u0438 \u0448\u043e\u0434\u0438\u04b7\u04ef\u0439 \u0430\u0437 \u0493\u0430\u043c \u044f\u043a \u043d\u0430\u0444\u0430\u0441 \u043e\u0441\u0443\u0434\u0430 \u043d\u0435\u0441\u0442.\n\u0414\u0430\u0440 \u0437\u0430\u043c\u043e\u043d\u0438 \u043d\u043e\u043a\u0430\u0441\u043e\u043d \u043e\u0441\u0443\u0434\u0430 \u04b3\u0430\u043c \u043d\u043e\u043a\u0430\u0441 \u0431\u0443\u0432\u0430\u0434,\n\u041d\u043e\u043a\u0430\u0441\u0435 \u043d\u0430\u0442\u0432\u043e\u043d \u0448\u0443\u0434\u0430\u043d \u0433\u0430\u0440\u0447\u0430\u043d\u0434 \u043a\u0430\u0441 \u043e\u0441\u0443\u0434\u0430 \u043d\u0435\u0441\u0442.\n\u04b2\u0430\u0440 \u0447\u04e3 \u0434\u0430\u0440 \u0434\u0443\u043d\u0451 \u0432\u0443\u04b7\u0443\u0434\u0435 \u0434\u043e\u0440\u0430\u0434, \u0430\u0440 \u0445\u0443\u0434 \u0437\u0430\u0440\u0440\u0430 \u0430\u0441\u0442,\n\u0410\u0437 \u0445\u0438\u043b\u043e\u0444\u0438 \u0437\u0438\u0434\u0434\u0438 \u0445\u0443\u0434 \u04ef \u043d\u0438\u0437 \u0431\u0430\u0441 \u043e\u0441\u0443\u0434\u0430 \u043d\u0435\u0441\u0442.\n\u0413\u0430\u0440\u0447\u0438 \u0445\u043e\u043a\u0430\u0448 \u0434\u0430\u0440 \u043f\u0430\u043d\u043e\u04b3\u0438 \u0445\u0435\u0448\u0442\u0430\u043d \u0433\u0438\u0440\u0430\u0434 \u0447\u0443 \u043e\u0431,\n\u0417-\u043e\u0442\u0430\u0448 \u0430\u0440 \u044d\u043c\u0438\u043d \u0431\u0443\u0432\u0430\u0434, \u0430\u0437 \u0431\u043e\u0434 \u0445\u0430\u0441 \u043e\u0441\u0443\u0434\u0430 \u043d\u0435\u0441\u0442.\n\u0410\u043d\u0434\u0430\u0440 \u0438\u043d \u0434\u0430\u0432\u043b\u0430\u0442, \u043a\u0438 \u0445\u0430\u043b\u049b\u0435 \u043f\u043e\u0439\u043c\u043e\u043b\u0438 \u043c\u0435\u04b3\u043d\u0430\u0442\u0430\u043d\u0434,\n\u0413\u0430\u0440 \u043a\u0430\u0441\u0435 \u0434\u043e\u0440\u0430\u0434 \u0431\u0430 \u043d\u0435\u044a\u043c\u0430\u0442 \u0434\u0430\u0441\u0442\u0440\u0430\u0441, \u043e\u0441\u0443\u0434\u0430 \u043d\u0435\u0441\u0442.\n\u041e\u0434\u0430\u043c\u0438\u0438 \u0442\u0430\u043b\u0445\u0430\u0439\u0448 \u0430\u0437 \u0437\u043e\u043b\u0438\u043c\u043e\u043d\u0438 \u0442\u0443\u0440\u0448\u0440\u04ef\u0439,\n\u04b2\u0430\u043c\u0447\u0443 \u0448\u0438\u0440\u0438\u043d\u04e3 \u0437\u0438 \u0438\u0431\u0440\u043e\u043c\u0438 \u043c\u0430\u0433\u0430\u0441 \u043e\u0441\u0443\u0434\u0430 \u043d\u0435\u0441\u0442...\n\u0410\u0437 \u0431\u0430\u0440\u043e\u0438 \u043e\u043d, \u043a\u0438 \u043c\u0430\u0440\u0434\u0443\u043c \u0430\u043d\u0434\u0430\u0440 \u04ef \u0448\u0430\u0440 \u043c\u0435\u043a\u0443\u043d\u0430\u043d\u0434,\n\u0428\u0430\u0431 \u0437\u0438 \u0431\u0438\u043c\u0438 \u0440\u04ef\u0437 \u0447\u0443\u043d \u0434\u0443\u0437\u0434 \u0430\u0437 \u0430\u0441\u0430\u0441 \u043e\u0441\u0443\u0434\u0430 \u043d\u0435\u0441\u0442.\n\u041c\u0443\u0440\u0493, \u043a-\u04ef\u0440\u043e \u04b7\u043e\u0439 \u0430\u043d\u0434\u0430\u0440 \u0431\u043e\u0493 \u0431\u043e\u0448\u0430\u0434 \u0447\u0443\u043d \u0434\u0430\u0440\u0430\u0445\u0442,\n\u0413\u0430\u0440 \u0431\u0438\u0433\u0438\u0440\u0438\u044e \u0431\u0438\u0434\u043e\u0440\u04e3 \u0434\u0430\u0440 \u049b\u0430\u0444\u0430\u0441, \u043e\u0441\u0443\u0434\u0430 \u043d\u0435\u0441\u0442.\n\u0410\u0437 \u043f\u0430\u0439\u0438 \u0442\u0430\u04b3\u0441\u0438\u043b\u0438 \u043e\u0441\u043e\u0438\u0448 \u043c\u0430\u0431\u0430\u0440 \u0431\u0438\u0441\u0451\u0440 \u0440\u0430\u043d\u04b7,\n\u04b2\u0430\u0440 \u043a\u04e3 \u04ef \u0434\u043e\u0440\u0430\u0434 \u0431\u0430 \u043e\u0441\u043e\u0438\u0448 \u04b3\u0430\u0432\u0430\u0441, \u043e\u0441\u0443\u0434\u0430 \u043d\u0435\u0441\u0442.")
B.acS=new A.a("05ea9b0a-0d6a-4306-a10b-d0aed4594d62","cfb751a8-dce3-4553-aef8-bc4574b2b85e","\u0410\u0419 \u0421\u0410\u0411\u041e, \u0411\u041e \u0414\u0410\u041c\u0418 \u041c\u0410\u041d \u041a\u0423\u041d \u041d\u0410\u0424\u0410\u0421\u0415 \u04b2\u0410\u041c\u0420\u041e\u04b2\u04e2","\u0410\u0439 \u0441\u0430\u0431\u043e, \u0431\u043e \u0434\u0430\u043c\u0438 \u043c\u0430\u043d \u043a\u0443\u043d \u043d\u0430\u0444\u0430\u0441\u0435 \u04b3\u0430\u043c\u0440\u043e\u04b3\u04e3,\n\u0411\u0430 \u0441\u04ef\u0438 \u0448\u043e\u04b3 \u0431\u0430\u0440 \u0430\u0437 \u043c\u0430\u043d \u0445\u0430\u0431\u0430\u0440\u0435, \u0433\u0430\u0440 \u0445\u043e\u04b3\u04e3...\n\u0413\u04ef\u0439 \u0434\u0430\u0440 \u0438\u043d \u041c\u0438\u0441\u0440, \u043a\u0438 \u0424\u0438\u0440\u044a\u0430\u0432\u043d \u0434\u0430\u0440 \u04ef \u0441\u0430\u0434 \u0431\u0435\u0448 \u0430\u0441\u0442,\n\u041d\u043e\u043d \u0430\u0437\u0438\u0437 \u0430\u0441\u0442, \u043a\u0438 \u0448\u0443\u0434 \u042e\u0441\u0443\u0444\u0438 \u0433\u0430\u043d\u0434\u0443\u043c \u0447\u043e\u04b3\u04e3.\n\u0428\u0435\u0440 \u0447\u0443\u043d \u0433\u0443\u0440\u0431\u0430 \u0434\u0430\u0440 \u0438\u043d \u043c\u0443\u043b\u043a \u043a\u0443\u043d\u0430\u0434 \u043c\u0443\u0448 \u0448\u0438\u043a\u043e\u0440,\n\u0411\u0430\u04b3\u0440\u0438 \u043d\u043e\u043d \u0433\u0430\u0440 \u043d\u0430\u043a\u0443\u043d\u0430\u0434 \u043d\u0430\u0437\u0434\u0438 \u0441\u0430\u0433\u043e\u043d \u0440\u04ef\u0431\u043e\u04b3\u04e3.\n\u0410\u043c\u043d \u0430\u0437 \u0438\u043d \u0445\u043e\u043a \u0447\u0443\u043d\u043e\u043d \u0440\u0430\u0444\u0442\u0430, \u043a\u0438 \u0433\u0430\u0440 \u0451\u0431\u0430\u0434 \u0431\u043e\u0437,\n\u0425\u0430\u0432\u0444\u0438 \u043e\u043d \u0430\u0441\u0442, \u043a\u0438 \u0430\u0437 \u043e\u0431 \u0431\u0438\u0442\u0430\u0440\u0441\u0430\u0434 \u043c\u043e\u04b3\u04e3.\n\u0424\u0438\u0442\u043d\u0430 \u0430\u0437 \u04b3\u0430\u0440 \u0442\u0430\u0440\u0430\u0444\u0435 \u043f\u0435\u0448 \u043d\u0438\u04b3\u0430\u0434 \u043f\u043e\u0439 \u0434\u0430\u0440\u043e\u0437,\n\u0413\u0430\u0440 \u043d\u0430\u0433\u0438\u0440\u0430\u0434 \u043f\u0430\u0441 \u0430\u0437 \u0438\u043d \u0434\u0430\u0441\u0442\u0438 \u0441\u0438\u0442\u0430\u043c \u043a\u04ef\u0442\u043e\u04b3\u04e3.\n\u0422\u0443\u0440\u043a\u043c\u043e\u043d\u0438 \u04b3\u0430\u0448\u0430\u0440\u04e3 \u04b3\u0430\u0440 \u043d\u0430\u0444\u0430\u0441 \u0430\u0437 \u04b3\u0430\u0440 \u0442\u0430\u0440\u0430\u0444\u0435\n\u0411\u0430\u0440 \u0432\u0438\u043b\u043e\u044f\u0442 \u0431\u0438\u0437\u0430\u043d\u0430\u0434 \u0447\u0443\u043d \u0430\u04b7\u0430\u043b\u0438 \u043d\u043e\u0433\u043e\u04b3\u04e3.\n\u0425\u043e\u043d\u0430\u04b3\u043e \u043b\u043e\u043d\u0430\u0438 \u0440\u04ef\u0431\u043e\u04b3 \u0448\u0443\u0434 \u0430\u0437 \u0432\u0430\u0439\u0440\u043e\u043d\u04e3,\n\u0428\u0430\u04b3\u0440\u04b3\u043e \u0445\u043e\u043d\u0430\u0438 \u0448\u0430\u0442\u0440\u0430\u043d\u04b7 \u0448\u0443\u0434 \u0430\u0437 \u0431\u0435\u0448\u043e\u04b3\u04e3.\n\u04b2\u043e\u043a\u0438\u043c\u043e\u043d \u04b3\u0430\u0440 \u0434\u0430\u043c \u0430\u0437 \u04ef \u049b\u0443\u0431\u04b7\u0443\u0440\u0443 \u0442\u0430\u043c\u0493\u043e \u0445\u043e\u04b3\u0430\u043d\u0434,\n\u0410\u043d\u043a\u0430\u0431\u0443\u0442 \u0430\u0440 \u0431\u0438\u043d\u0438\u04b3\u0430\u0434 \u043a\u043e\u0440\u0433\u0430\u04b3\u0438 \u04b7\u04ef\u043b\u043e\u04b3\u04e3.\n\u0425\u0438\u0440\u043c\u0430\u043d\u0438 \u0441\u04ef\u0445\u0442\u0430 \u0448\u0443\u0434 \u043c\u0443\u043b\u043a\u0443 \u0431\u0430\u0440 \u044d\u0448\u043e\u043d \u0431\u0430 \u04b7\u0430\u0432\u0435\n\u0410\u0441\u043f\u0438 \u0448\u0430\u0442\u0440\u0430\u043d\u04b7 \u043a\u0443\u04b7\u043e \u0493\u0430\u043c \u0445\u04ef\u0440\u0430\u0434 \u0430\u0437 \u0431\u0435\u043a\u043e\u04b3\u04e3?!\n\u0411\u0438\u043c\u0438 \u043e\u043d \u0430\u0441\u0442, \u043a\u0438 \u0430\u0431\u0434\u043e\u043b \u0425\u0438\u0437\u0438\u0440\u0440\u043e \u0433\u04ef\u044f\u043d\u0434:\n\u2013 \u0413\u0430\u0440 \u0441\u04ef\u0438 \u0420\u0443\u043c \u0440\u0430\u0432\u04e3, \u043c\u0443\u0440\u0434\u0430\u043d\u0438 \u0445\u0443\u0434 \u043c\u0435\u0445\u043e\u04b3\u04e3.\n\u041c\u0430\u043c\u043b\u0430\u043a\u0430\u0442 \u04b7\u0443\u043c\u043b\u0430 \u043f\u0443\u0440 \u0430\u0437 \u043c\u0443\u043d\u043a\u0430\u0440\u0443 \u043c\u0430\u044a\u0440\u0443\u0444\u0435 \u043d\u0435,\n\u041a\u0438 \u0431\u0430 \u0425\u0430\u0439\u0440 \u0430\u043c\u0440 \u043a\u0443\u043d\u0430\u0434 \u0451 \u0431\u0443\u0432\u0430\u0434 \u0430\u0437 \u0428\u0430\u0440 \u043d\u043e\u04b3\u04e3.\n\u0425\u0430\u043b\u049b \u0431\u0438\u043c \u0430\u0441\u0442, \u043a\u0438 \u0447\u0443\u043d \u0437\u0430\u0440\u0440\u0430 \u043f\u0430\u0440\u043e\u043a\u0430\u043d\u0434\u0430 \u0448\u0430\u0432\u0430\u043d\u0434,\n\u0413\u0430\u0440 \u0431\u0430 \u044d\u0448\u043e\u043d \u043d\u0430\u0440\u0430\u0441\u0430\u0434 \u0441\u043e\u044f\u0438 \u0437\u0438\u043b\u0438\u043b\u043b\u043e\u04b3\u04e3.\n\u0413\u0430\u0440 \u043d\u0430\u0451\u04e3, \u0431\u0438\u0440\u0430\u0432\u0430\u0434 \u0438\u043d \u0440\u0430\u043c\u0430\u049b\u0435 \u043d\u0438\u0437, \u043a\u0438 \u04b3\u0430\u0441\u0442,\n\u0413\u0430\u0440 \u0431\u0438\u0451\u04e3, \u043a\u0443\u043d\u0430\u0434\u0430\u0442 \u0431\u0430\u0445\u0442\u0443 \u0437\u0430\u0444\u0430\u0440 \u04b3\u0430\u043c\u0440\u043e\u04b3\u04e3.")
B.a7q=new A.a("4948ed43-a6b5-4a5b-90fb-762747b0b3c8","01df7214-28b7-44ab-a1f4-898bb7e83950","\u0411\u0430\u0439\u0442","\u0421\u0443\u04b3\u0431\u0430\u0442\u0438 \u0430\u0431\u043b\u0430\u04b3\u043e\u043d \u0447\u0443 \u0434\u0435\u0433\u0438 \u0442\u0438\u04b3\u0438\u0441\u0442,\n\u0410\u043d\u0434\u0430\u0440\u0443\u043d \u0445\u043e\u043b\u0438\u0432\u0443 \u0431\u0443\u0440\u0443\u043d \u0441\u0438\u044f\u04b3\u0438\u0441\u0442.")
