B.asu=new A.a("cb862326-0655-4b3f-8ea5-51c4648b33c0","5ec16ef0-b9c8-44e1-a6fc-4a01ee3f7def","\u0411\u0423\u0417\u0423\u0420\u0413\u04e2 \u0414\u0410\u0420 \u0427\u0418\u0421\u0422?","\u041d\u0430\u0431\u0443\u0432\u0430\u0434 \u043c\u0435\u04b3\u0442\u0430\u0440\u04e3 \u0431\u0430 \u0440\u04ef\u0437\u0443 \u0431\u0430 \u0448\u0430\u0431\n\u0411\u043e\u0434\u0430\u0438 \u0445\u0443\u0448\u0433\u0443\u0432\u043e\u0440 \u043d\u04ef\u0448\u0438\u0434\u0430\u043d,\n\u0401 \u0442\u0430\u043e\u043c\u0438 \u043b\u0430\u0437\u0438\u0437\u0440\u043e \u0445\u04ef\u0440\u0434\u0430\u043d,\n\u0401 \u043b\u0438\u0431\u043e\u0441 \u043b\u0430\u0442\u0438\u0444 \u043f\u04ef\u0448\u0438\u0434\u0430\u043d.\n\u0401 \u0431\u0430\u0434-\u043e\u043d \u043a\u0430\u0441, \u043a\u0438 \u0437\u0435\u0440\u0434\u0430\u0441\u0442 \u0431\u0443\u0432\u0430\u0434\n\u04b2\u0430\u0440 \u0437\u0430\u043c\u043e\u043d \u0431\u0435\u0441\u0430\u0431\u0430\u0431 \u0445\u0443\u0440\u04ef\u0448\u0438\u0434\u0430\u043d.\n\u041c\u0430\u043d \u0431\u0438\u0433\u04ef\u044f\u043c, \u043a\u0438 \u043c\u0435\u04b3\u0442\u0430\u0440\u04e3 \u0447\u04e3 \u0431\u0443\u0432\u0430\u0434,\n\u0413\u0430\u0440 \u0431\u0438\u0445\u043e\u04b3\u04e3 \u0437\u0438 \u043c\u0430\u043d \u043d\u0438\u044e\u0448\u0438\u0434\u0430\u043d?\n\u04b2\u0430\u043c\u0430\u0433\u043e\u043d\u0440\u043e \u0437\u0438 \u0493\u0430\u043c \u0440\u0430\u04b3\u043e\u043d\u0438\u0434\u0430\u043d,\n\u0414\u0430\u0440 \u0440\u0430\u043e\u0451\u0442\u0438 \u0445\u0430\u043b\u049b \u043a\u04ef\u0448\u0438\u0434\u0430\u043d!")
B.a8R=new A.a("aae39e32-0363-4775-b570-3823c87ce6bc","5ec16ef0-b9c8-44e1-a6fc-4a01ee3f7def","\u0414\u04ee\u0421\u0422\u0415 \u0411\u0410 \u0414\u0410\u0421\u0422 \u041e\u0420","\u0414\u0443 \u0434\u04ef\u0441\u0442 \u0431\u043e \u04b3\u0430\u043c \u0430\u0433\u0430\u0440 \u044f\u043a\u0434\u0438\u043b\u0430\u043d\u0434 \u0434\u0430\u0440 \u04b3\u0430\u043c\u0430 \u04b3\u043e\u043b,\n\u04b2\u0430\u0437\u043e\u0440 \u0442\u0430\u044a\u043d\u0430\u0438 \u0434\u0443\u0448\u043c\u0430\u043d \u0431\u0430 \u043d\u0438\u043c\u0438 \u04b7\u0430\u0432 \u043d\u0430\u0445\u0430\u0440\u0430\u043d\u0434.\n\u0412-\u0430\u0440 \u0438\u0442\u0442\u0438\u0444\u043e\u049b \u043d\u0430\u043c\u043e\u044f\u043d\u0434\u0443 \u0430\u0437\u043c\u0438 \u04b7\u0430\u0437\u043c \u043a\u0443\u043d\u0430\u043d\u0434,\n\u0421\u0430\u0437\u0430\u0434, \u043a\u0438 \u043f\u0430\u0440\u0434\u0430\u0438 \u0430\u0444\u043b\u043e\u043a\u0438\u0451\u043d \u0437\u0438 \u04b3\u0430\u043c \u0431\u0438\u0434\u0430\u0440\u0430\u043d\u0434.\n\u041c\u0438\u0441\u043e\u043b\u0438 \u0438\u043d \u0431\u0438\u043d\u0430\u043c\u043e\u044f\u043c \u0442\u0443\u0440\u043e \u0437\u0438 \u043c\u0443\u04b3\u0440\u0430\u0438 \u043d\u0430\u0440\u0434,\n\u042f\u0433\u043e\u043d-\u044f\u0433\u043e\u043d \u0431\u0430 \u0441\u04ef\u0438 \u0445\u043e\u043d\u0430 \u0440\u043e\u04b3 \u043c\u0435\u043d\u0430\u0431\u0430\u0440\u0430\u043d\u0434.\n\u0412\u0430\u043b\u0435 \u0434\u0443 \u043c\u0443\u04b3\u0440\u0430 \u0447\u0443 \u04b3\u0430\u043c\u043f\u0443\u0448\u0442\u0438 \u044f\u043a\u0434\u0438\u0433\u0430\u0440 \u0433\u0430\u0440\u0434\u0430\u043d\u0434,\n\u0414\u0438\u0433\u0430\u0440 \u0442\u0430\u043f\u043e\u043d\u0447\u0430\u0438 \u0434\u0443\u0448\u043c\u0430\u043d \u0431\u0430 \u04b3\u0435\u04b7 \u0440\u04ef \u043d\u0430\u0445(\u0432)\u0430\u0440\u0430\u043d\u0434.\n\u0411\u0438\u043a\u04ef\u0448, \u0418\u0431\u043d\u0438 \u042f\u043c\u0438\u043d, \u0434\u04ef\u0441\u0442\u0435 \u0431\u0430 \u0434\u0430\u0441\u0442 \u043e\u0432\u0430\u0440,\n\u041a\u0438 \u0434\u0443\u0448\u043c\u0430\u043d\u043e\u043d \u0441\u04ef\u0439\u0438 \u044f\u043a \u0442\u0430\u043d \u0431\u0430 \u0441\u0430\u0434 \u043a\u0430\u0436\u04e3 \u043d\u0438\u0433\u0430\u0440\u0430\u043d\u0434.")
B.a70=new A.a("303519ee-e60a-4567-be45-4f258ce774d6","5ec16ef0-b9c8-44e1-a6fc-4a01ee3f7def","\u041f\u0410\u041d\u0414\u041d\u041e\u041c\u0410 (\u043f\u043e\u0440\u0447\u0430 \u0430\u0437 \u043c\u0430\u043d\u0437\u0443\u043c\u0430)","\u041d\u0430\u0445\u0443\u0441\u0442, \u043e\u043d \u043a\u0438 \u0442\u043e \u0440\u04ef\u0437\u0443 \u0448\u0430\u0431\u0440\u043e \u043c\u0430\u0434\u043e\u0440\n\u0411\u0443\u0432\u0430\u0434 \u0430\u0437 \u04b3\u0430\u0432\u043e\u0434\u0438\u0441, \u0448\u0438\u0433\u0438\u0444\u0442\u04e3 \u043c\u0430\u0434\u043e\u0440.\n\u0414\u0438\u0433\u0430\u0440 \u043e\u043d, \u043a\u0438 \u0437\u0438\u043d\u0434\u0430 \u043c\u0430\u0434\u043e\u043d \u0445\u0435\u0448\u0440\u043e,\n\u0427\u0443 \u043c\u0430\u0440\u04b3\u0430\u043c \u043d\u0430\u0451\u0431\u04e3 \u0434\u0438\u043b\u0438 \u0445\u0435\u0448\u0440\u043e.\n\u0414\u0438\u0433\u0430\u0440 \u043e\u043d, \u043a\u0438 \u04b3\u0430\u049b \u0433\u04ef\u04e3 \u0431\u043e \u04b3\u0430\u0440 \u043a\u0430\u0441\u0435,\n\u0412-\u0430\u0433\u0430\u0440\u0447\u0438 \u0431\u0430 \u0442\u0430\u043b\u0445\u04e3 \u0433\u0438\u0440\u043e\u044f\u0434 \u0431\u0430\u0441\u0435.")
B.af7=new A.a("3dfcb018-4df5-4d1b-87ee-48315460484a","3537f811-9658-4f9b-a29b-6311e802e60e","\u0414\u04ef\u0441\u0442\u0435 \u0431\u0430 \u0434\u0430\u0441\u0442 \u043e\u0440","\u0414\u0438\u0433\u0430\u0440 \u043e\u043d, \u043a\u0438 \u0440\u0438\u043d\u0434\u043e\u043d\u0438 \u043a\u0435\u04b3\u0442\u0430\u0440\u043d\u0430\u0432\u043e\u0437,\n\u0411\u0435\u04b3 \u0430\u0437 \u043f\u043e\u0440\u0441\u043e\u0451\u043d\u0438 \u0431\u043e \u043a\u0438\u0431\u0440\u0443 \u043d\u043e\u0437,\n\u0414\u0438\u0433\u0430\u0440 \u043e\u043d, \u043a\u0438 \u0433\u0430\u0440 \u043a\u0435\u04b3\u0442\u0430\u0440\u0435 \u043c\u0435\u04b3 \u0448\u0430\u0432\u0430\u0434,\n\u0417\u0438 \u04b3\u0430\u043c\u0442\u043e\u0438 \u0445\u0443\u0434 \u0434\u0430\u0440 \u04b3\u0443\u043d\u0430\u0440 \u0431\u0435\u04b3 \u0448\u0430\u0432\u0430\u0434.\n\u0414\u0438\u0433\u0430\u0440 \u043e\u043d, \u043a\u0438 \u043c\u0430\u0493\u0440\u0443\u0440\u0442\u0430\u0440 \u043e\u043d \u043a\u0430\u0441 \u0430\u0441\u0442,\n\u041a\u0438 \u0434\u043e\u0434 \u0430\u0437 \u043f\u0430\u0439\u0438 \u043d\u0430\u0441\u044f \u043d\u0430\u049b\u0434\u0435 \u0437\u0438 \u0434\u0430\u0441\u0442.\n\u0414\u0438\u0433\u0430\u0440 \u043e\u043d, \u043a\u0438 \u0433\u0430\u0440 \u043c\u0430\u0440\u0434 \u0434\u043e\u043d\u043e \u0431\u0443\u0432\u0430\u0434.\n\u0411\u0430 \u043c\u0430\u0439\u0434\u043e\u043d\u0438 \u0434\u043e\u043d\u0438\u0448 \u0442\u0430\u0432\u043e\u043d\u043e \u0431\u0443\u0432\u0430\u0434.\n\u0414\u0438\u0433\u0430\u0440 \u0433\u0430\u0440 \u043d\u0430\u0445\u043e\u04b3\u04e3 \u0442\u0443, \u044d\u0439 \u043d\u043e\u043c\u04b7\u04ef\u0439,\n\u041a\u0438 \u0431\u0430\u0434 \u0433\u04ef\u044f\u0434\u0430\u0442 \u043a\u0430\u0441, \u0431\u0430\u0434\u0438 \u043a\u0430\u0441 \u043c\u0430\u0433\u04ef\u0439.\n\u0414\u0438\u0433\u0430\u0440 \u043e\u043d, \u043a\u0438 \u0441\u0430\u0440\u0433\u0430\u0448\u0442\u0430 \u043c\u043e\u043d\u04e3 \u04b3\u0430\u043c\u0435,\n\u041a\u0438 \u043d\u043e\u043a\u0430\u0440\u0434\u0430\u0440\u043e \u043a\u0430\u0440\u0434\u0430 \u0434\u043e\u043d\u04e3 \u04b3\u0430\u043c\u0435.\n\u0414\u0438\u0433\u0430\u0440 \u043e\u043d, \u043a\u0438 \u0447\u0443\u043d \u043f\u0430\u0440\u0434\u0430\u0438 \u043a\u0430\u0441 \u0434\u0430\u0440\u04e3,\n\u041a\u0443\u043d\u0430\u0434 \u0431\u043e \u0442\u0443 \u0433\u0435\u0442\u04e3 \u04b3\u0430\u043c\u043e\u043d \u0434\u043e\u0432\u0430\u0440\u04e3.\n\u0414\u0438\u0433\u0430\u0440 \u043e\u043d, \u043a\u0438 \u0431\u0435 \u0431\u0438\u043c \u0431\u043e\u0448\u0430\u0434 \u043a\u0430\u0441\u0435,\n\u041a\u0438 \u043e\u0437\u043e\u0440\u0438 \u043c\u0430\u0440\u0434\u0443\u043c \u043d\u0430\u04b7\u04ef\u044f\u0434 \u0431\u0430\u0441\u0435.\n\u0414\u0438\u0433\u0430\u0440 \u043e\u043d, \u043a\u0438 \u049b\u0430\u0434\u0440\u0438 \u0431\u0443\u0437\u0443\u0440\u0433\u043e\u043d \u0431\u0438\u0434\u043e\u043d,\n\u0421\u0443\u0445\u0430\u043d \u043f\u0435\u0448\u0438 \u044d\u0448\u043e\u043d \u0431\u0430 \u0430\u043d\u0434\u043e\u0437\u0430 \u0440\u043e\u043d...\n\u041a\u0443\u043d\u0443\u043d \u044d\u0439 \u0445\u0438\u0440\u0430\u0434\u043c\u0430\u043d\u0434\u0438 \u0431\u0438\u0441\u0451\u0440\u04b3\u0443\u0448,\n\u0421\u0443\u0445\u0430\u043d\u04b3\u043e\u0438 \u04b3\u0438\u043a\u043c\u0430\u0442 \u0440\u0430\u0441\u0438\u0434\u0430\u0442 \u0431\u0430 \u0433\u0443\u0448.\n\u0413\u0430\u0440\u0430\u0442 \u04b3\u0430\u0441\u0442 \u0448\u043e\u0438\u0441\u0442\u0430\u044e \u0434\u0438\u043b\u043f\u0430\u0437\u0438\u0440,\n\u0410\u0437 \u0438\u043d \u0434\u043e\u0441\u0442\u043e\u043d \u044f\u043a \u0431\u0430 \u044f\u043a \u0451\u0434 \u0433\u0438\u0440.")
B.ahJ=new A.a("2fb80564-6a33-4f35-a781-968c9ba87365","3537f811-9658-4f9b-a29b-6311e802e60e","\u0414\u0430\u0440 \u0448\u0430\u044a\u043d\u0438 \u0411\u043e\u0431\u043e \u041c\u0430\u04b3\u043c\u0443\u0434","\u04b2\u0430\u043c\u0430 \u0448\u0430\u04b3\u043c\u0438\u0432\u0443 \u043b\u0430\u04b3\u043c, \u044d\u0439 \u043c\u0438\u0440\u0438 \u0430\u044a\u0437\u0430\u043c,\n\u0425\u0443\u0448 \u043e\u043d, \u043a-\u04ef \u0447\u0443\u043d \u0442\u0443 \u043c\u0438\u0440\u0435 \u0431\u0430\u0440\u0433\u0443\u0437\u0438\u043d\u0430\u0434.\n\u0410\u0433\u0430\u0440 \u0430\u0441\u043f\u0438 \u0442\u0443 \u04b3\u0430\u0440\u0433\u0438\u0437 \u043a\u0430\u04b3 \u043d\u0430\u0451\u0431\u0430\u0434,\n\u0417\u0438 \u0437\u0430\u0444\u044a\u0438 \u043b\u043e\u0493\u0430\u0440\u04e3 \u043a\u0430\u0439 \u0440\u0430\u043d\u04b7 \u0431\u0438\u043d\u0430\u0434?\n\u0422\u0443 \u04b3\u0430\u0440 \u0433\u043e\u04b3\u0435, \u043a\u0438 \u0431\u0430\u0440 \u0432\u0430\u0439 \u0431\u0430\u0440\u043d\u0438\u0448\u0438\u043d\u04e3,\n\u0414\u0443\u0441\u0430\u0434 \u043c\u0430\u043d \u0433\u04ef\u0448\u0442 \u0431\u0430\u0440 \u0432\u0430\u0439 \u0431\u0430\u0440\u043d\u0438\u0448\u0438\u043d\u0430\u0434.")
B.aqv=new A.a("9f7b272c-3906-4a44-822f-e4deb66f2039","da1e1d82-ceeb-4a9e-9e42-251b9b05d20c","\u0411\u0435 \u0441\u0430\u0440\u043b\u0430\u0432\u04b3\u0430","\u0411\u0430\u044a\u0434 \u0430\u0437 \u0432\u0430\u0444\u043e\u0442 \u0442\u0443\u0440\u0431\u0430\u0442\u0438 \u043c\u043e \u0434\u0430\u0440 \u0437\u0430\u043c\u0438\u043d \u043c\u0430\u04b7\u04ef\u0439,\n\u0414\u0430\u0440 \u0441\u0438\u043d\u0430\u04b3\u043e\u0438 \u043c\u0430\u0440\u0434\u0443\u043c\u0438 \u043e\u0440\u0438\u0444 \u043c\u0430\u0437\u043e\u0440\u0438 \u043c\u043e.")
B.ao1=new A.a("5a9471d2-513f-42f2-976e-0637fb520e75","da1e1d82-ceeb-4a9e-9e42-251b9b05d20c","\u0411\u0435 \u0441\u0430\u0440\u043b\u0430\u0432\u04b3\u0430","\u0417\u0438 \u0448\u0435\u044a\u0440\u0438 \u04b2\u043e\u0444\u0438\u0437\u0438 \u0428\u0435\u0440\u043e\u0437 \u043c\u0435\u0445\u043e\u043d\u0430\u043d\u0434\u0443 \u043c\u0435\u0440\u0430\u049b\u0441\u0430\u043d\u0434,\n\u0421\u0438\u0451\u04b3\u0447\u0430\u0448\u043c\u043e\u043d\u0438 \u043a\u0430\u0448\u043c\u0438\u0440\u0438\u044e \u0442\u0443\u0440\u043a\u043e\u043d\u0438 \u0441\u0430\u043c\u0430\u0440\u049b\u0430\u043d\u0434\u04e3.")
B.a8i=new A.a("ff8c5b57-06d4-417d-95e6-7fbb645997bd","da1e1d82-ceeb-4a9e-9e42-251b9b05d20c","\u0411\u0435 \u0441\u0430\u0440\u043b\u0430\u0432\u04b3\u0430","\u0428\u0430\u043a\u043a\u0430\u0440\u0448\u0438\u043a\u0430\u043d \u0448\u0430\u0432\u0430\u043d\u0434 \u04b3\u0430\u043c\u0430 \u0442\u04ef\u0442\u0438\u0451\u043d\u0438 \u04b2\u0438\u043d\u0434,\n3-\u0438\u043d \u049b\u0430\u043d\u0434\u0438 \u043f\u043e\u0440\u0441\u04e3, \u043a\u0438 \u0431\u0430 \u0411\u0430\u043d\u0433\u043e\u043b\u0430 \u043c\u0435\u0440\u0430\u0432\u0430\u0434.")
B.ak5=new A.a("ce9de772-03aa-4431-95b1-a79302892d79","da1e1d82-ceeb-4a9e-9e42-251b9b05d20c","\u0411\u0435 \u0441\u0430\u0440\u043b\u0430\u0432\u04b3\u0430","\u0492\u0430\u0437\u0430\u043b \u0433\u0443\u0444\u0442\u0438\u044e \u0434\u0443\u0440 \u0441\u0443\u0444\u0442\u04e3, \u0431\u0438\u0451\u0432\u0443 \u0445\u0443\u0448 \u0431\u0438\u0445\u043e\u043d \u04b2\u043e\u0444\u0438\u0437,\n\u041a\u0438 \u0431\u0430\u0440 \u043d\u0430\u0437\u043c\u0438 \u0442\u0443 \u0430\u0444\u0448\u043e\u043d\u0430\u0434 \u0444\u0430\u043b\u0430\u043a \u0438\u049b\u0434\u0438 \u0421\u0443\u0440\u0430\u0439\u0451\u0440\u043e.")
B.apW=new A.a("c6a91489-091c-4fae-92f5-f34a4faaf55b","da1e1d82-ceeb-4a9e-9e42-251b9b05d20c","\u041a\u0418\u0428\u0422\u0418\u041d\u0418\u0428ACT\u0410\u0413\u041e\u041d\u0415\u041c","\u0414\u0438\u043b \u043c\u0435\u0440\u0430\u0432\u0430\u0434 \u0437\u0438 \u0434\u0430\u0441\u0442\u0430\u043c, \u0441\u043e\u04b3\u0438\u0431\u0434\u0438\u043b\u043e\u043d \u0425\u0443\u0434\u043e\u0440\u043e,\n\u0414\u0430\u0440\u0434\u043e, \u043a\u0438 \u0440\u043e\u0437\u0438 \u043f\u0438\u043d\u04b3\u043e\u043d \u0445\u043e\u04b3\u0430\u0434 \u0448\u0443\u0434 \u043e\u0448\u043a\u043e\u0440\u043e,\n\u041a\u0438\u0448\u0442\u0438\u043d\u0438\u0448\u0430\u0441\u0442\u0430\u0433\u043e\u043d\u0435\u043c, \u044d\u0439 \u0431\u043e\u0434\u0438 \u0448\u04ef\u0440\u0442\u0430, \u0431\u0430\u0440\u0445\u0435\u0437.\n\u0411\u043e\u0448\u0430\u0434, \u043a\u0438 \u0431\u043e\u0437 \u0431\u0438\u043d\u0435\u043c, \u0434\u0438\u0434\u043e\u0440\u0438 \u043e\u0448\u043d\u043e\u0440\u043e.\n\u0414\u0430\u04b3\u0440\u04ef\u0437\u0430 \u043c\u0435\u04b3\u0440\u0438 \u0433\u0430\u0440\u0434\u0443\u043d \u0430\u0444\u0441\u043e\u043d\u0430 \u0430\u0441\u0442\u0443 \u0430\u0444\u0441\u0443\u043d,\n\u041d\u0435\u043a\u04e3 \u0431\u0430 \u04b7\u043e\u0438 \u0451\u0440\u043e\u043d \u0444\u0443\u0440\u0441\u0430\u0442 \u0448\u0443\u043c\u043e\u0440, \u0451\u0440\u043e...\n\u042d\u0439 \u0441\u043e\u04b3\u0438\u0431\u0438 \u043a\u0430\u0440\u043e\u043c\u0430\u0442, \u0448\u0443\u043a\u0440\u043e\u043d\u0430\u0438 \u0441\u0430\u043b\u043e\u043c\u0430\u0442,\n\u0420\u04ef\u0437\u0435 \u0442\u0430\u0444\u0430\u049b\u049b\u0443\u0434\u0435 \u043a\u0443\u043d \u0434\u0430\u0440\u0432\u0435\u0448\u0438 \u0431\u0435\u043d\u0430\u0432\u043e\u0440\u043e.\n\u041e\u0441\u043e\u0438\u0448\u0438 \u0434\u0443 \u0433\u0435\u0442\u04e3 \u0442\u0430\u0444\u0441\u0438\u0440\u0438 \u0438\u043d \u0434\u0443 \u04b3\u0430\u0440\u0444 \u0430\u0441\u0442:\n\u0411\u043e \u0434\u04ef\u0441\u0442\u043e\u043d \u043c\u0443\u0440\u0443\u0432\u0432\u0430\u0442, \u0431\u0430 \u0434\u0443\u0448\u043c\u0430\u043d\u043e\u043d \u043c\u0430\u0434\u043e\u0440\u043e.\n\u04b2\u0430\u043d\u0433\u043e\u043c\u0438 \u0442\u0430\u043d\u0433\u0434\u0430\u0441\u0442\u04e3 \u0434\u0430\u0440 \u0430\u0439\u0448 \u043a\u04ef\u0448\u0443 \u043c\u0430\u0441\u0442\u04e3,\n\u041a-\u0438\u043d \u043a\u0438\u043c\u0438\u0451\u0438 \u04b3\u0430\u0441\u0442\u04e3 \u049a\u043e\u0440\u0443\u043d \u043a\u0443\u043d\u0430\u0434 \u0433\u0430\u0434\u043e\u0440\u043e...\n\u0425\u0443\u0431\u043e\u043d\u0438 \u043f\u043e\u0440\u0441\u0438\u0433\u04ef \u0431\u0430\u0445\u0448\u0430\u043d\u0434\u0430\u0433\u043e\u043d\u0438 \u0443\u043c\u0440\u0430\u043d\u0434,\n\u0421\u043e\u049b\u04e3, \u0431\u0438\u0434\u0435\u04b3 \u0431\u0430\u0448\u043e\u0440\u0430\u0442 \u0440\u0438\u043d\u0434\u043e\u043d\u0438 \u043f\u043e\u0440\u0441\u043e\u0440\u043e.\n\u04b2\u043e\u0444\u0438\u0437 \u0431\u0430 \u0445\u0443\u0434 \u043d\u0430\u043f\u04ef\u0448\u0438\u0434 \u0438\u043d \u0445\u0438\u0440\u049b\u0430\u0438 \u043c\u0430\u0439\u043e\u043b\u0443\u0434,\n\u042d\u0439 \u0448\u0430\u0439\u0445\u0438 \u043f\u043e\u043a\u0434\u043e\u043c\u0430\u043d, \u043c\u0430\u044a\u0437\u0443\u0440 \u0434\u043e\u0440 \u043c\u043e\u0440\u043e.")
B.aoe=new A.a("3b4357e7-4dd0-4c86-ba5a-ff3a421f58c2","da1e1d82-ceeb-4a9e-9e42-251b9b05d20c","\u041f\u0410\u0419\u0492\u041e\u041c\u0418 \u0414\u04ee\u0421\u0422","\u041c\u0430\u0440\u04b3\u0430\u0431\u043e, \u044d\u0439 \u043f\u0430\u0439\u043a\u0438 \u043c\u0443\u0448\u0442\u043e\u049b\u043e\u043d, \u0431\u0438\u0434\u0435\u04b3 \u043f\u0430\u0439\u0493\u043e\u043c\u0438 \u0434\u04ef\u0441\u0442,\n\u0422\u043e \u043a\u0443\u043d\u0430\u0434 \u04b7\u043e\u043d \u0430\u0437 \u0441\u0430\u0440\u0438 \u0440\u0430\u0493\u0431\u0430\u0442 \u0444\u0438\u0434\u043e\u0438 \u043d\u043e\u043c\u0438 \u0434\u04ef\u0441\u0442.\n\u0412\u043e\u043b\u0430\u0432\u0443 \u0448\u0430\u0439\u0434\u043e\u0441\u0442 \u0434\u043e\u0438\u043c \u04b3\u0430\u043c\u0447\u0443 \u0431\u0443\u043b\u0431\u0443\u043b \u0434\u0430\u0440 \u049b\u0430\u0444\u0430\u0441,\n\u0422\u04ef\u0442\u0438\u0438 \u0442\u0430\u0431\u044a\u0430\u043c \u0437\u0438 \u0438\u0448\u049b\u0438 \u0448\u0430\u043a\u043a\u0430\u0440\u0443 \u0431\u043e\u0434\u043e\u043c\u0438 \u0434\u04ef\u0441\u0442.\n\u0417\u0443\u043b\u0444\u0438 \u04ef \u0434\u043e\u043c \u0430\u0441\u0442\u0443 \u0445\u043e\u043b\u0430\u0448 \u0434\u043e\u043d\u0430\u0438 \u043e\u043d \u0434\u043e\u043c\u0443 \u043c\u0430\u043d\n\u0411\u0430\u0440 \u0443\u043c\u0435\u0434\u0438 \u0434\u043e\u043d\u0430\u0435 \u0430\u0444\u0442\u043e\u0434\u0430\u0430\u043c \u0434\u0430\u0440 \u0434\u043e\u043c\u0438 \u0434\u04ef\u0441\u0442!\n\u0421\u0430\u0440 \u0437\u0438 \u043c\u0430\u0441\u0442\u04e3 \u0431\u0430\u0440\u043d\u0430\u0433\u0438\u0440\u0430\u0434 \u0442\u043e \u0431\u0430 \u0441\u0443\u0431\u04b3\u0438 \u0440\u04ef\u0437\u0438 \u04b3\u0430\u0448\u0440,\n\u04b2\u0430\u0440 \u043a\u04e3 \u0447\u0443\u043d \u043c\u0430\u043d \u0434\u0430\u0440 \u0430\u0437\u0430\u043b \u044f\u043a \u04b7\u0443\u0440\u044a\u0430 \u0445\u04ef\u0440\u0434 \u0430\u0437 \u04b7\u043e\u043c\u0438 \u0434\u04ef\u0441\u0442.\n\u0411\u0430\u0441 \u043d\u0430\u0433\u04ef\u044f\u043c \u0448\u0430\u043c\u043c\u0430\u0435 \u0430\u0437 \u0448\u0430\u0440\u04b3\u0438 \u0448\u0430\u0432\u049b\u0438 \u0445\u0443\u0434 \u0430\u0437 \u043e\u043d-\u043a\n\u0414\u0430\u0440\u0434\u0438 cap \u0431\u043e\u0448\u0430\u0434 \u043d\u0430\u043c\u0443\u0434\u0430\u043d \u0431\u0435\u0448 \u0430\u0437 \u0438\u043d \u0438\u0431\u0440\u043e\u043c\u0438 \u0434\u04ef\u0441\u0442.\n\u0413\u0430\u0440 \u0434\u0438\u04b3\u0430\u0434 \u0434\u0430\u0441\u0442\u0430\u043c, \u043a\u0430\u0448\u0430\u043c \u0434\u0430\u0440 \u0434\u0438\u0434\u0430 \u04b3\u0430\u043c\u0447\u0443\u043d \u0442\u04ef\u0442\u0438\u0451,\n\u0425\u043e\u043a\u0438 \u0440\u043e\u04b3\u0435, \u043a-\u043e\u043d \u043c\u0443\u0448\u0430\u0440\u0440\u0430\u0444 \u0433\u0430\u0440\u0434\u0430\u0434 \u0430\u0437 \u0438\u049b\u0434\u043e\u043c\u0438 \u0434\u04ef\u0441\u0442.\n\u041c\u0430\u0439\u043b\u0438 \u043c\u0430\u043d \u0441\u04ef\u0438 \u0432\u0438\u0441\u043e\u043b\u0443 \u049b\u0430\u0441\u0434\u0438 \u04ef \u0441\u04ef\u0438 \u0444\u0438\u0440\u043e\u049b,\n\u0422\u0430\u0440\u043a\u0438 \u043d\u043e\u043c\u0438 \u0445\u0443\u0434 \u0433\u0438\u0440\u0438\u0444\u0442\u0430\u043c, \u0442\u043e \u0431\u0430\u0440\u043e\u044f\u0434 \u043a\u043e\u043c\u0438 \u0434\u04ef\u0441\u0442.\n\u04b2\u043e\u0444\u0438\u0437, \u0430\u043d\u0434\u0430\u0440 \u0434\u0430\u0440\u0434\u0438 \u04ef \u043c\u0435\u0441\u04ef\u0437\u0443 \u0431\u0435\u0434\u0430\u0440\u043c\u043e\u043d \u0431\u0438\u0441\u043e\u0437,\n\u0417-\u043e\u043d, \u043a\u0438 \u0434\u0430\u0440\u043c\u043e\u043d\u0435 \u043d\u0430\u0434\u043e\u0440\u0430\u0434 \u0434\u0430\u0440\u0434\u0438 \u0431\u0435\u043e\u0440\u043e\u043c\u0438 \u0434\u04ef\u0441\u0442.")
B.adw=new A.a("7d0dc007-15d0-4fd2-837b-3b4596f80363","da1e1d82-ceeb-4a9e-9e42-251b9b05d20c","\u0417\u0418 \u0414\u0410\u0421\u0422\u0418 \u041a\u04ee\u0422\u0410\u04b2\u0418 \u0425\u0423\u0414 \u0417\u0415\u0420\u0418 \u0411\u041e\u0420\u0410\u041c","\u0417\u0438 \u0434\u0430\u0441\u0442\u0438 \u043a\u04ef\u0442\u0430\u04b3\u0438 \u0445\u0443\u0434 \u0437\u0435\u0440\u0438 \u0431\u043e\u0440\u0430\u043c,\n\u041a\u0438 \u0430\u0437 \u0431\u043e\u043b\u043e\u0431\u0430\u043b\u0430\u043d\u0434\u043e\u043d \u0448\u0430\u0440\u043c\u0441\u043e\u0440\u0430\u043c.\n\u041c\u0430\u0433\u0430\u0440 \u0437\u0430\u043d\u04b7\u0438\u0440\u0438 \u043c\u04ef\u0435 \u0433\u0438\u0440\u0430\u0434\u0430\u043c \u0434\u0430\u0441\u0442,\n\u0412-\u0430\u0433\u0430\u0440\u043d\u0430 cap \u0431\u0430 \u0448\u0430\u0439\u0434\u043e\u04e3 \u0431\u0430\u0440\u043e\u0440\u0430\u043c.\n\u0417\u0438 \u0447\u0430\u0448\u043c\u0438 \u043c\u0430\u043d \u0431\u0438\u043f\u0443\u0440\u0441 \u0430\u0432\u0437\u043e\u0438 \u0433\u0430\u0440\u0434\u0443\u043d,\n\u041a\u0438 \u0448\u0430\u0431 \u0442\u043e \u0440\u04ef\u0437 \u0430\u0445\u0442\u0430\u0440 \u043c\u0435\u0448\u0443\u043c\u043e\u0440\u0430\u043c\n\u041c\u0430\u043d \u0430\u0437 \u0431\u043e\u0437\u0443\u0438 \u0445\u0443\u0434 \u0434\u043e\u0440\u0430\u043c \u0431\u0430\u0441\u0435 \u0448\u0443\u043a\u0440,\n\u041a\u0438 \u0437\u04ef\u0440\u0438 \u043c\u0430\u0440\u0434\u0443\u043c\u043e\u0437\u043e\u0440\u04e3 \u043d\u0430\u0434\u043e\u0440\u0430\u043c.\n\u0410\u0433\u0430\u0440 \u0433\u0443\u0444\u0442\u0430\u043c \u0434\u0443\u043e\u0438 \u043c\u0430\u0439\u0444\u0443\u0440\u04ef\u0448\u043e\u043d,\n\u0427\u04e3 \u0431\u043e\u0448\u0430\u0434, \u04b3\u0430\u049b\u049b\u0438 \u043d\u0435\u044a\u043c\u0430\u0442 \u043c\u0435\u0433\u0443\u0437\u043e\u0440\u0430\u043c.\n\u0422\u0443 \u0430\u0437 \u0445\u043e\u043a\u0430\u043c \u043d\u0430\u0445\u043e\u04b3\u04e3 \u0431\u0430\u0440\u0433\u0438\u0440\u0438\u0444\u0442\u0430\u043d,\n\u0411\u0430 \u04b7\u043e\u0438 \u0430\u0448\u043a \u0430\u0433\u0430\u0440 \u0433\u0430\u0432\u04b3\u0430\u0440 \u0431\u0438\u0431\u043e\u0440\u0430\u043c.\n\u0421\u0430\u0440\u0435 \u0434\u043e\u0440\u0430\u043c \u0447\u0443 \u04b2\u043e\u0444\u0438\u0437 \u043c\u0430\u0441\u0442, \u043b\u0435\u043a\u0438\u043d\n\u0411\u0430 \u043b\u0443\u0442\u0444\u0438 \u043e\u043d \u0441\u0430\u0440\u0438 \u0443\u043c\u0435\u0434\u0432\u043e\u0440\u0430\u043c.")
B.adt=new A.a("121f55c9-1691-49ac-a78f-98dde7e38dde","da1e1d82-ceeb-4a9e-9e42-251b9b05d20c","\u0414\u041e\u041d\u04e2, \u041a\u0418 \u0427\u0418\u0421\u0422 \u0414\u0410\u0412\u041b\u0410\u0422?","\u0414\u043e\u043d\u04e3, \u043a\u0438 \u0447\u0438\u0441\u0442 \u0434\u0430\u0432\u043b\u0430\u0442? \u2013 \u0414\u0438\u0434\u043e\u0440\u0438 \u0451\u0440 \u0434\u0438\u0434\u0430\u043d,\n\u0414\u0430\u0440 \u043a\u04ef\u0439\u0438 \u04ef \u0433\u0430\u0434\u043e\u04e3 \u0431\u0430\u0440 \u0445\u0443\u0441\u0440\u0430\u0432\u04e3 \u0440\u0430\u0441\u0438\u0434\u0430\u043d.\n\u0410\u0437 \u04b7\u043e\u043d \u0442\u0430\u043c\u0430\u044a \u0431\u0443\u0440\u0438\u0434\u0430\u043d \u043e\u0441\u043e\u043d \u0431\u0443\u0432\u0430\u0434, \u0432\u0430\u043b\u0435\u043a\u0438\u043d\n\u0410\u0437 \u0434\u04ef\u0441\u0442\u043e\u043d\u0438 \u04b7\u043e\u043d\u04e3 \u043c\u0443\u0448\u043a\u0438\u043b \u0442\u0430\u0432\u043e\u043d \u0431\u0443\u0440\u0438\u0434\u0430\u043d.\n\u0425\u043e\u04b3\u0430\u043c \u0448\u0443\u0434\u0430\u043d \u0431\u0430 \u0431\u04ef\u0441\u0442\u043e\u043d \u0447\u0443\u043d \u0493\u0443\u043d\u0447\u0430 \u0431\u043e \u0434\u0438\u043b\u0438 \u0442\u0430\u043d\u0433,\n\u0412-\u043e\u043d \u04b7\u043e \u0431\u0430 \u043d\u0435\u043a\u043d\u043e\u043c\u04e3 \u043f\u0438\u0440\u043e\u04b3\u0430\u043d\u0435 \u0434\u0430\u0440\u0438\u0434\u0430\u043d.\n\u0413\u0430\u04b3 \u0447\u0443\u043d \u043d\u0430\u0441\u0438\u043c \u0431\u043e \u0433\u0443\u043b \u0440\u043e\u0437\u0438 \u043d\u0443\u04b3\u0443\u0444\u0442\u0430 \u0433\u0443\u0444\u0442\u0430\u043d,\n\u0413\u0430\u04b3 \u0441\u0438\u0440\u0440\u0438 \u0438\u0448\u049b\u0431\u043e\u0437\u04e3 \u0430\u0437 \u0431\u0443\u043b\u0431\u0443\u043b\u043e\u043d \u0448\u0443\u043d\u0438\u0434\u0430\u043d...\n\u0424\u0443\u0440\u0441\u0430\u0442 \u0448\u0443\u043c\u043e\u0440 \u0441\u0443\u04b3\u0431\u0430\u0442, \u043a-\u0430\u0437 \u0438\u043d \u0434\u0443\u0440\u043e\u04b3\u0430 \u043c\u0430\u043d\u0437\u0438\u043b,\n\u0427\u0443\u043d \u0431\u0438\u0433\u0437\u0430\u0440\u0435\u043c, \u0434\u0438\u0433\u0430\u0440 \u043d\u0430\u0442\u0432\u043e\u043d \u0431\u0430 \u04b3\u0430\u043c \u0440\u0430\u0441\u0438\u0434\u0430\u043d.\n\u0413\u04ef\u0439\u04e3 \u0431\u0438\u0440\u0430\u0444\u0442 \u04b2\u043e\u0444\u0438\u0437 \u0430\u0437 \u0451\u0434\u0438 \u0448\u043e\u04b3 \u042f\u04b3\u0451,\n\u0401 \u0440\u0430\u0431, \u0431\u0430 \u0451\u0434\u0430\u0448 \u043e\u0432\u0430\u0440, \u0434\u0430\u0440\u0432\u0435\u0448 \u043f\u0430\u0440\u0432\u0430\u0440\u0438\u0434\u0430\u043d!")
B.a7j=new A.a("6d70c347-ac63-4b6d-a1d0-3a12beb4e073","da1e1d82-ceeb-4a9e-9e42-251b9b05d20c","\u0492\u0410\u041c \u041c\u0410\u0425\u04ee\u0420","\u042e\u0441\u0443\u0444\u0438 \u0433\u0443\u043c\u0433\u0430\u0448\u0442\u0430 \u0431\u043e\u0437 \u043e\u044f\u0434 \u0431\u0430 \u041a\u0430\u043d\u044a\u043e\u043d, \u0493\u0430\u043c \u043c\u0430\u0445\u04ef\u0440,\n\u041a\u0443\u043b\u0431\u0430\u0438 \u044d\u04b3\u0437\u043e\u043d \u0448\u0430\u0432\u0430\u0434 \u0440\u04ef\u0437\u0435 \u0433\u0443\u043b\u0438\u0441\u0442\u043e\u043d, \u0493\u0430\u043c \u043c\u0430\u0445\u04ef\u0440!\n\u042d\u0439 \u0434\u0438\u043b\u0438 \u0493\u0430\u043c\u0434\u0438\u0434\u0430, \u04b3\u043e\u043b\u0430\u0442 \u0431\u0435\u04b3 \u0448\u0430\u0432\u0430\u0434, \u0434\u0438\u043b \u0431\u0430\u0434 \u043c\u0430\u043a\u0443\u043d\n\u0412-\u0438\u043d \u0441\u0430\u0440\u0438 \u0448\u04ef\u0440\u0438\u0434\u0430 \u0431\u043e\u0437 \u043e\u044f\u0434 \u0431\u0430 \u0441\u043e\u043c\u043e\u043d, \u0493\u0430\u043c \u043c\u0430\u0445\u04ef\u0440!\n\u0413\u0430\u0440 \u0431\u0430\u04b3\u043e\u0440\u0438 \u0443\u043c\u0440 \u0431\u043e\u0448\u0430\u0434, \u0431\u043e\u0437 \u0431\u0430\u0440 \u0442\u0430\u0440\u0444\u0438 \u0447\u0430\u043c\u0430\u043d\n\u0427\u0430\u0442\u0440\u0438 \u0433\u0443\u043b \u0434\u0430\u0440 cap \u043a\u0430\u0448\u04e3, \u044d\u0439 \u043c\u0443\u0440\u0493\u0438 \u0445\u0443\u0448\u0445\u043e\u043d, \u0493\u0430\u043c \u043c\u0430\u0445\u04ef\u0440!\n\u0414\u0430\u0432\u0440\u0438 \u0433\u0430\u0440\u0434\u0443\u043d \u0433\u0430\u0440 \u0434\u0443 \u0440\u04ef\u0437\u0435 \u0431\u0430\u0440 \u043c\u0443\u0440\u043e\u0434\u0438 \u043c\u043e \u043d\u0430\u0440\u0430\u0444\u0442,\n\u0414\u043e\u0438\u043c\u0430\u043d \u044f\u043a\u0441\u043e\u043d \u043d\u0430\u043c\u043e\u043d\u0430\u0434 \u04b3\u043e\u043b\u0438 \u0434\u0430\u0432\u0440\u043e\u043d, \u0493\u0430\u043c \u043c\u0430\u0445\u04ef\u0440!\n\u04b2\u043e\u043d, \u043c\u0430\u0448\u0430\u0432 \u043d\u0430\u0432\u043c\u0435\u0434, \u0447\u0443\u043d \u0432\u043e\u049b\u0438\u0444 \u043d\u0430\u04e3 \u0430\u0437 \u0441\u0438\u0440\u0440\u0438 \u0493\u0430\u0439\u0431,\n\u0411\u043e\u0448\u0430\u0434 \u0430\u043d\u0434\u0430\u0440 \u043f\u0430\u0440\u0434\u0430 \u0431\u043e\u0437\u0438\u04b3\u043e\u0438 \u043f\u0438\u043d\u04b3\u043e\u043d, \u0493\u0430\u043c \u043c\u0430\u0445\u04ef\u0440!\n\u0413\u0430\u0440\u0447\u0438 \u043c\u0430\u043d\u0437\u0438\u043b \u0431\u0430\u0441 \u0445\u0430\u0442\u0430\u0440\u043d\u043e\u043a \u0430\u0441\u0442\u0443 \u043c\u0430\u049b\u0441\u0430\u0434 \u0431\u0430\u0441 \u0431\u0430\u0438\u0434,\n\u04b2\u0435\u04b7 \u0440\u043e\u04b3\u0435 \u043d\u0435\u0441\u0442, \u043a-\u043e\u043d\u0440\u043e \u043d\u0435\u0441\u0442 \u043f\u043e\u0451\u043d, \u0493\u0430\u043c \u043c\u0430\u0445\u04ef\u0440!\n\u04b2\u043e\u0444\u0438\u0437\u043e, \u0434\u0430\u0440 \u043a\u0443\u043d\u04b7\u0438 \u0444\u0430\u049b\u0440\u0443 \u0445\u0438\u043b\u0432\u0430\u0442\u0438 \u0448\u0430\u0431\u04b3\u043e\u0438 \u0442\u043e\u0440,\n\u0422\u043e \u0431\u0443\u0432\u0430\u0434 \u0432\u0438\u0440\u0434\u0430\u0442 \u0434\u0443\u043e\u0432\u0443 \u0434\u0430\u0440\u0441\u0438 \u049a\u0443\u0440\u044a\u043e\u043d, \u0493\u0430\u043c \u043c\u0430\u0445\u04ef\u0440!")
B.ajS=new A.a("99cc4e1f-e9d3-440e-94d5-6b5d13d2a132","da1e1d82-ceeb-4a9e-9e42-251b9b05d20c","\u0425\u0423\u0428 \u041d\u0410\u0411\u041e\u0428\u0410\u0414","\u0413\u0443\u043b \u0431\u0435 \u0440\u0443\u0445\u0438 \u0451\u0440 \u0445\u0443\u0448 \u043d\u0430\u0431\u043e\u0448\u0430\u0434,\n\u0411\u0435 \u0431\u043e\u0434\u0430 \u0431\u0430\u04b3\u043e\u0440 \u0445\u0443\u0448 \u043d\u0430\u0431\u043e\u0448\u0430\u0434.\n\u0422\u0430\u0440\u0444\u0438 \u0447\u0430\u043c\u0430\u043d\u0443 \u0442\u0430\u0432\u043e\u0444\u0438 \u0431\u04ef\u0441\u0442\u043e\u043d\n\u0411\u0435 \u043b\u043e\u043b\u0430\u0443\u0437\u043e\u0440 \u0445\u0443\u0448 \u043d\u0430\u0431\u043e\u0448\u0430\u0434.\n\u0420\u0430\u049b\u0441\u0438\u0434\u0430\u043d\u0438 \u0441\u0430\u0440\u0432\u0443 \u04b3\u043e\u043b\u0430\u0442\u0438 \u0433\u0443\u043b\n\u0411\u0435 \u0441\u0430\u0432\u0442\u0438 \u04b3\u0430\u0437\u043e\u0440 \u0445\u0443\u0448 \u043d\u0430\u0431\u043e\u0448\u0430\u0434...\n\u04b2\u0430\u0440 \u043d\u0430\u049b\u0448, \u043a\u0438 \u0434\u0430\u0441\u0442\u0438 \u0430\u049b\u043b \u0431\u0430\u043d\u0434\u0430\u0434,\n\u04b6\u0443\u0437 \u043d\u0430\u049b\u0448\u0438 \u043d\u0438\u0433\u043e\u0440 \u0445\u0443\u0448 \u043d\u0430\u0431\u043e\u0448\u0430\u0434.\n\u04b6\u043e\u043d \u043d\u0430\u049b\u0434\u0438 \u043c\u0443\u04b3\u0430\u049b\u049b\u0438\u0440 \u0430\u0441\u0442, \u04b2\u043e\u0444\u0438\u0437,\n\u0410\u0437 \u0431\u0430\u04b3\u0440\u0438 \u043d\u0438\u0441\u043e\u0440 \u0445\u0443\u0448 \u043d\u0430\u0431\u043e\u0448\u0430\u0434.")
B.ao5=new A.a("42475979-fe23-4d19-910d-f6f62e7b83cb","da1e1d82-ceeb-4a9e-9e42-251b9b05d20c","\u0401\u0414 \u0411\u041e\u0414","\u0420\u04ef\u0437\u0438 \u0432\u0430\u0441\u043b\u0438 \u0434\u04ef\u0441\u0442\u0434\u043e\u0440\u043e\u043d \u0451\u0434 \u0431\u043e\u0434,\n\u0401\u0434 \u0431\u043e\u0434 \u043e\u043d \u0440\u04ef\u0437\u0433\u043e\u0440\u043e\u043d, \u0451\u0434 \u0431\u043e\u0434!\n\u0418\u043d \u0437\u0430\u043c\u043e\u043d \u0431\u0430\u0440 \u043a\u0430\u0441 \u0432\u0430\u0444\u043e\u0434\u043e\u0440\u04e3 \u043d\u0430\u043c\u043e\u043d\u0434,\n\u041e\u043d \u0432\u0430\u0444\u043e\u0434\u043e\u0440\u043e\u043d\u0443 \u0451\u0440\u043e\u043d \u0451\u0434 \u0431\u043e\u0434!\n\u041a\u043e\u043c\u0430\u043c \u0430\u0437 \u0442\u0430\u043b\u0445\u0438\u0438 \u0493\u0430\u043c \u0447\u0443\u043d \u0437\u0430\u04b3\u0440 \u0433\u0430\u0448\u0442,\n\u0411\u043e\u043d\u0433\u0438 \u043d\u04ef\u0448\u0438 \u0431\u043e\u0434\u0430\u0445\u043e\u0440\u043e\u043d \u0451\u0434 \u0431\u043e\u0434!\n\u0413\u0430\u0440\u0447\u0438 \u0451\u0440\u043e\u043d \u0444\u043e\u0440\u0438\u0493\u0430\u043d\u0434 \u0430\u0437 \u0451\u0434\u0438 \u043c\u0430\u043d,\n\u0410\u0437 \u043c\u0430\u043d \u044d\u0448\u043e\u043d\u0440\u043e \u04b3\u0430\u0437\u043e\u0440\u043e\u043d \u0451\u0434 \u0431\u043e\u0434!\n\u041c\u0443\u0431\u0442\u0430\u043b\u043e \u0433\u0430\u0448\u0442\u0430\u043c \u0434\u0430\u0440 \u0438\u043d \u0431\u0430\u043d\u0434\u0443 \u0431\u0430\u043b\u043e,\n\u041a\u04ef\u0448\u0438\u0448\u0438 \u043e\u043d \u04b3\u0430\u049b\u0433\u0443\u0437\u043e\u0440\u043e\u043d \u0451\u0434 \u0431\u043e\u0434!\n\u0413\u0430\u0440\u0447\u0438 \u0441\u0430\u0434 \u0440\u04ef\u0434 \u0430\u0441\u0442 \u0434\u0430\u0440 \u0447\u0430\u0448\u043c\u0430\u043c \u043c\u0443\u0434\u043e\u043c,\n\u0417\u0438\u043d\u0434\u0430\u0440\u04ef\u0434\u0438 \u0431\u043e\u0493\u043a\u043e\u0440\u043e\u043d \u0451\u0434 \u0431\u043e\u0434!\n\u0420\u043e\u0437\u0438 \u04b2\u043e\u0444\u0438\u0437 \u0431\u0430\u044a\u0434 \u0430\u0437 \u0438\u043d \u043d\u043e\u0433\u0443\u0444\u0442\u0430 \u043c\u043e\u043d\u0434,\n\u042d\u0439 \u0434\u0430\u0440\u0435\u0493\u043e, \u0440\u043e\u0437\u0434\u043e\u0440\u043e\u043d \u0451\u0434 \u0431\u043e\u0434!")
B.abT=new A.a("4a706396-a364-4602-a971-5d7d2b014ef6","337370dd-7731-490b-9e92-b7f9be6ba695","\u0411\u0435 \u0441\u0430\u0440\u043b\u0430\u0432\u04b3\u0430","\u041d\u043e\u0441\u0438\u0440, \u0425\u0443\u0440\u043e\u0441\u043e\u043d\u0440\u043e \u0434\u0438\u0433\u0430\u0440 \u0431\u043e \u041c\u0438\u0441\u0440 \u043d\u0430\u0431\u0432\u0430\u0434 \u04b3\u043e\u04b7\u0430\u0442\u0435,\n\u041a-\u0430\u0437 \u0445\u043e\u043c\u0430\u0438 \u0447\u0443\u043d \u043d\u0430\u0439\u0448\u0430\u043a\u0430\u0440 \u0448\u0430\u043a\u043a\u0430\u0440 \u0444\u0430\u0440\u043e\u0432\u043e\u043d \u043a\u0430\u0440\u0434\u0430\u04e3.")
B.adX=new A.a("903dc3fe-3f7f-42bf-969a-5a2a9fbe852a","337370dd-7731-490b-9e92-b7f9be6ba695","\u0420\u0410\u0424\u0422\u0415\u041c \u0410\u0417 \u0414\u0418\u0401\u0420\u0418 \u0422\u0423 \u0411\u041e \u0414\u0418\u0414\u0410\u0418 \u041f\u0423\u0420\u041e\u0411","\u0420\u0430\u0444\u0442\u0435\u043c \u0430\u0437 \u0434\u0438\u0451\u0440\u0438 \u0442\u0443 \u0431\u043e \u0434\u0438\u0434\u0430\u0438 \u043f\u0443\u0440\u043e\u0431,\n\u0427\u0443\u043d \u0437\u0443\u043b\u0444\u0438 \u0442\u0443 \u043c\u0443\u0448\u0430\u0432\u0432\u0430\u0448\u0443 \u0447\u0443\u043d \u04b7\u0438\u0441\u043c\u0438 \u0442\u0443 \u0445\u0430\u0440\u043e\u0431.\n\u041c\u0430\u04b3\u043c\u0438\u043b \u043c\u0430\u0431\u0430\u043d\u0434 \u0431\u0430\u0440 \u0448\u0443\u0442\u0443\u0440, \u044d\u0439 \u0441\u043e\u0440\u0431\u043e\u043d, \u043a\u0438 \u043c\u043e\n\u041c\u0430\u04b3\u043c\u0438\u043b \u0431\u0430\u0440 \u043e\u0431\u0438 \u0434\u0438\u0434\u0430 \u0431\u0438\u0431\u0430\u0441\u0442\u0435\u043c \u0447\u0443\u043d \u04b3\u0443\u0431\u043e\u0431.\n\u0410\u0448\u043a\u0430\u043c \u0434\u0430\u0440 \u043e\u0441\u0442\u0438\u043d \u0448\u0443\u0434\u0443 \u043c\u0435\u0433\u0438\u0440\u0430\u0434\u0430\u043c \u0438\u043d\u043e\u043d,\n\u041a\u043e\u0440\u0430\u043c \u0431\u0430 \u04ef \u0444\u0438\u0442\u043e\u0434\u0443 \u0433\u0430\u0440\u043e\u043d \u043c\u0435\u043a\u0443\u043d\u0430\u0434 \u0440\u0438\u043a\u043e\u0431.\n\u042d\u0439 \u0434\u0438\u0434\u0430, \u0434\u0430\u0440\u0434\u0438 cap \u043c\u0430\u0434\u0435\u04b3\u0443 \u043e\u0431\u0438 \u043c\u043e \u043c\u0430\u0440\u0435\u0437,\n\u04b2\u0438\u04b7\u0440\u043e\u043d \u043d\u0430 \u043e\u0442\u0430\u0448\u0435\u0441\u0442, \u043a\u0438 \u0441\u043e\u043a\u0438\u043d \u0448\u0430\u0432\u0430\u0434 \u0431\u0430 \u043e\u0431.\n\u042d\u043c\u0438\u043d \u043d\u0430\u044f\u043c \u0437\u0438 \u0444\u0438\u0442\u043d\u0430\u0438 \u0447\u0430\u0448\u043c\u0430\u0442, \u043a\u0438 \u043c\u0435\u043a\u0443\u043d\u0430\u0434,\n\u042f\u043a \u0438\u043d\u049b\u0438\u043b\u043e\u0431\u0438 \u0447\u0430\u0448\u043c\u0438 \u0442\u0443 \u0441\u0430\u0434\u0433\u0443\u043d\u0430 \u0438\u043d\u049b\u0438\u043b\u043e\u0431.\n\u0422\u043e \u0437\u0430\u04b3\u0440\u0438 \u0444\u0443\u0440\u049b\u0430\u0442\u0438 \u0442\u0443 \u0447\u0430\u0448\u0438\u0434\u0430\u043c \u0431\u0430 \u04b7\u043e\u0439\u0438 \u043c\u0430\u0439,\n\u0421\u04ef\u0437\u0435\u0441\u0442 \u0434\u0430\u0440 \u0434\u0438\u043b\u0430\u043c, \u043a\u0438 \u04b7\u0438\u0433\u0430\u0440 \u043c\u0435\u0448\u0430\u0432\u0430\u0434 \u043a\u0430\u0431\u043e\u0431.\n\u0427\u0443\u043d \u0440\u04ef\u0437\u0438 \u04b3\u0430\u04b7\u0440 \u0451\u0434\u0438 \u0444\u0438\u0440\u043e\u049b\u0438 \u0442\u0443 \u043c\u0435\u043a\u0443\u043d\u0430\u043c,\n\u0413\u04ef\u0451, \u043a\u0438 \u0434\u0438\u0434\u0430\u0435\u043c \u043c\u0430\u0433\u0430\u0440 \u0434\u0430\u0432\u043b\u0430\u0442\u0435 \u0431\u0430 \u0445\u043e\u0431.\n\u041d\u043e\u0441\u0438\u0440, \u0434\u0443\u043e\u0438 \u0445\u0430\u0441\u0442\u0430 \u043c\u0430\u0433\u0430\u0440 \u0434\u0430\u0440 \u0442\u0443 \u043a\u043e\u0440\u0430 \u043a\u0430\u0440\u0434,\n\u04b2\u0430\u0440\u0433\u0438\u0437 \u043c\u0430\u0431\u043e\u0434 \u0434\u0430\u044a\u0432\u0430\u0442\u0438 \u0431\u0430\u0434\u0445\u043e\u04b3 \u043c\u0443\u0441\u0442\u0430\u04b7\u043e\u0431.")
B.aq8=new A.a("07cd5f3f-177c-48f9-a5af-df1dbfd8f2c1","337370dd-7731-490b-9e92-b7f9be6ba695","\u0411\u0418\u0413\u0417\u0410\u0420 \u042d\u0419 \u041e\u049a\u0418\u041b\u0423 \u0411\u0418\u0413\u0417\u041e\u0420 \u041c\u0410\u0420\u041e \u041b\u041e\u042f\u042a\u049a\u0418\u041b","\u0411\u0438\u0433\u0437\u0430\u0440 \u044d\u0439 \u043e\u049b\u0438\u043b\u0443 \u0431\u0438\u0433\u0437\u043e\u0440 \u043c\u0430\u0440\u043e \u043b\u043e\u044f\u044a\u049b\u0438\u043b,\n\u0411\u0430 \u0441\u0430\u0440\u0438 \u043a\u04ef\u0439\u0438 \u0431\u0443\u0442\u043e\u043d \u043f\u043e\u0439 \u0431\u0430 \u0433\u0438\u043b, \u0434\u0430\u0441\u0442 \u0431\u0430 \u0434\u0438\u043b.\n\u0414\u0438\u0434\u0430\u0440\u043e \u0434\u0430\u0432\u043b\u0430\u0442\u0438 \u0434\u0438\u0434\u043e\u0440 \u0431\u0443\u0432\u0430\u0434, \u0433\u0430\u0440 \u043d\u0430\u0431\u0443\u0432\u0430\u0434\n\u041f\u0430\u0440\u0434\u0430\u0438 \u0434\u0438\u0434\u0430 \u043c\u0438\u0451\u043d\u0438 \u0434\u0438\u043b\u0443 \u0434\u0438\u043b\u0431\u0430\u0440 \u04b3\u043e\u0439\u0438\u043b.\n\u0410\u0448\u043a \u0431\u043e\u0440\u043e\u043d \u0448\u0443\u0434\u0443 \u0442\u043e \u0447\u0430\u0448\u043c \u0437\u0430\u0434\u0430\u043c \u0441\u043e\u0438\u043b \u0431\u0443\u0434,\n\u041d\u0430\u0442\u0430\u0432\u043e\u043d \u0431\u0430\u0441\u0442 \u0434\u0430\u0440\u0438 \u0445\u043e\u043d\u0430 \u0431\u0430 \u0440\u04ef\u0439\u0438 \u0441\u043e\u0438\u043b.\n\u0411\u0438\u0433\u0437\u0430\u0440, \u044d\u0439 \u043c\u0430\u04b3, \u0431\u0430 \u0441\u0430\u043e\u0434\u0430\u0442 \u0431\u0430 \u0441\u0430\u0440\u0430\u043c \u04b3\u0430\u0440 \u043c\u043e\u04b3\u0435,\n\u041a\u0438 \u0434\u0430\u0440 \u043e\u0444\u043e\u049b \u043d\u0430\u0431\u043e\u0448\u0430\u0434 \u0431\u0435\u04b3 \u0430\u0437 \u0438\u043d \u0441\u0430\u0440\u043c\u0430\u043d\u0437\u0438\u043b.\n\u04b2\u0438\u043d\u0434\u0443\u0438 \u0445\u043e\u043b\u0438 \u043c\u0443\u0431\u043e\u0440\u0430\u043a \u0431\u0430 \u0433\u0443\u043b\u0438\u0441\u0442\u043e\u043d\u0438 \u0440\u0443\u0445\u0430\u0442,\n\u0413\u0430\u0448\u0442 \u043c\u0430\u049b\u0431\u0443\u043b, \u043a\u0438 \u04ef \u04b3\u0430\u0441\u0442 \u0441\u0438\u0451\u04b3\u0438 \u043c\u0443\u049b\u0431\u0438\u043b,\n\u041c\u0430\u04b3 \u0430\u0433\u0430\u0440 \u0440\u04ef\u0439 \u0431\u0438\u043f\u04ef\u0448\u0430\u0434 \u0437\u0438 \u0442\u0443 \u043c\u0435\u0434\u043e\u0440\u0430\u043c \u0448\u0430\u0440\u043c,\n\u0413\u0443\u043b \u0430\u0433\u0430\u0440 \u0441\u0443\u0440\u0445 \u0431\u0430\u0440\u043e\u044f\u0434, \u0437\u0438 \u0440\u0443\u0445\u0438 \u0442\u0443\u0441\u0442 \u0445\u0438\u04b7\u0438\u043b.\n\u0421\u043e\u049b\u0438\u0451, \u04b3\u043e\u0441\u0438\u043b\u0438 \u0443\u043c\u0440\u0430\u043c \u043c\u0430\u0439\u0438 \u043d\u043e\u0431 \u0430\u0441\u0442, \u0431\u0438\u0451\u0440,\n\u0417\u0438 \u0434\u0438\u043b\u0438 \u043f\u043e\u043a \u0431\u0438\u0448\u04ef\u044f\u043c \u04b3\u0430\u0432\u0430\u0441\u0438 \u0431\u0435\u04b3\u043e\u0441\u0438\u043b.\n\u041e\u049b\u0438\u043b\u043e\u043d\u0440\u043e \u0447\u0443 \u0431\u0430\u0440\u0430\u0434 \u0493\u0443\u043b\u0438 \u0493\u0430\u043c\u0438 \u0434\u0430\u04b3\u0440 \u0437\u0438 \u0440\u043e\u04b3,\n\u0492\u0430\u0439\u0440\u0438 \u0434\u0435\u0432\u043e\u043d\u0430 \u0434\u0430\u0440 \u0438\u043d \u0434\u0430\u0432\u0440 \u043d\u0430\u0434\u0438\u0434\u0435\u043c \u043e\u049b\u0438\u043b.\n\u041d\u043e\u0441\u0438\u0440, \u0430\u0437 \u0432\u0430\u044a\u0434\u0430\u0438 \u04ef \u0431\u04ef\u0439\u0438 \u0432\u0430\u0444\u043e\u0435 \u043c\u0430\u0442\u0430\u043b\u0430\u0431,\n\u0421\u0430\u0440\u0432\u0438 \u043e\u0437\u043e\u0434\u0430 \u0431\u0430 \u04b3\u0430\u0440 \u0431\u043e\u0434 \u043d\u0430\u0433\u0430\u0440\u0434\u0430\u0434 \u043c\u043e\u0438\u043b.")
B.ahm=new A.a("9bd9617e-d0f4-47fd-977a-871dad8e63c7","337370dd-7731-490b-9e92-b7f9be6ba695","\u041e\u041c\u0410\u0414 \u0411\u0410\u04b2\u041e\u0420\u0423 \u041c\u0410\u0412\u0421\u0418\u041c\u0418 \u0413\u0423\u041b\u04b2\u041e \u0420\u0410\u0421\u0418\u0414\u0410\u0410\u0421\u0422","\u041e\u043c\u0430\u0434 \u0431\u0430\u04b3\u043e\u0440\u0443 \u043c\u0430\u0432\u0441\u0438\u043c\u0438 \u0433\u0443\u043b\u04b3\u043e \u0440\u0430\u0441\u0438\u0434\u0430\u0430\u0441\u0442,\n\u041b\u043e\u043b\u0430 \u0430\u043b\u0430\u043c \u0431\u0430 \u043a\u04ef\u04b3\u0443 \u0431\u0430 \u0441\u0430\u04b3\u0440\u043e \u043a\u0430\u0448\u0438\u0434\u0430\u0430\u0441\u0442.\n\u0411\u0443\u043b\u0431\u0443\u043b \u0441\u0443\u0440\u0443\u0434 \u0433\u0443\u0444\u0442\u0430, \u0441\u0430\u0440\u0430\u043d\u0434\u043e\u0437 \u0433\u0430\u0448\u0442\u0430 \u0441\u0430\u0440\u0432,\n\u0492\u0443\u043d\u0447\u0430 \u0437\u0438 \u0448\u0430\u0432\u049b \u04b7\u0443\u0431\u0431\u0430\u0438 \u0445\u0430\u0437\u0440\u043e \u0434\u0430\u0440\u0438\u0434\u0430\u0430\u0441\u0442.\n\u0414\u0430\u0440 \u0447\u0430\u0448\u043c\u0438 \u0448\u04ef\u0445\u0438 \u043d\u0430\u0440\u0433\u0438\u0441\u0438 \u0442\u0443 \u04b3\u0435\u0447 \u0448\u0430\u0440\u043c \u043d\u0435\u0441\u0442,\n\u041a\u04ef\u0440 \u0430\u0441\u0442 \u043e\u043d \u0434\u0443 \u043d\u0430\u0440\u0433\u0438\u0441\u0438 \u0440\u0430\u044a\u043d\u043e \u043d\u0430\u0434\u0438\u0434\u0430\u0430\u0441\u0442.\n\u0421\u0430\u0431\u0437\u0430 \u0441\u0438\u043d\u043e\u043d \u043a\u0430\u0448\u0438\u0434\u0430 \u04b3\u0430\u043c\u0435\u0433\u04ef\u044f\u0434 \u043e\u0431\u0440\u043e,\n\u041d\u043e\u0434\u0438\u0434\u0430 \u043c\u0430\u0433\u0437\u0430\u0440\u0435\u0434, \u043a\u0438 \u0433\u0443\u043b\u04b3\u043e \u0434\u0430\u043c\u0438\u0434\u0430\u0430\u0441\u0442.\n\u0414\u043e\u0493\u0435, \u043a\u0438 \u04b3\u0430\u04b7\u0440 \u043a\u0430\u0440\u0434 \u043c\u0430\u0440\u043e \u0434\u0443\u0448 \u0431\u0430\u0440 \u04b7\u0438\u0433\u0430\u0440,\n\u04b2\u0430\u0440 \u043d\u0430\u044a\u0440\u0430\u0435 \u0437\u0430\u0434\u0430\u043c, \u043a\u0438 \u0441\u0443\u0440\u0430\u0439\u0451 \u0448\u0443\u043d\u0438\u0434\u0430\u0430\u0441\u0442.\n\u0411\u0430\u0440 \u0431\u043e\u043c\u0438 \u0447\u0430\u0440\u0445 \u0440\u0430\u0444\u0442 \u0434\u0438\u043b\u0443 \u0437\u0435\u0440\u0438 \u0431\u043e\u0440\u0438 \u04ef,\n\u041f\u0443\u0448\u0442\u0438 \u0434\u0443\u0442\u043e\u04e3 \u0433\u0443\u043d\u0431\u0430\u0434\u0438 \u043c\u0438\u043d\u043e \u0445\u0430\u043c\u0438\u0434\u0430\u0430\u0441\u0442.\n\u0414\u0438\u043b \u0433\u0443\u0444\u0442 \u0442\u0430\u0440\u043a\u0438 \u041d\u043e\u0441\u0438\u0440\u0443 \u043e\u043c\u0435\u0445\u0442 \u0431\u043e \u0493\u0430\u043c\u0430\u0448,\n\u04ee \u049b\u0430\u0442\u0440\u0430 \u0431\u0443\u0434\u0443 \u04b7\u043e\u043d\u0438\u0431\u0438 \u0434\u0430\u0440\u0451 \u0434\u0430\u0432\u0438\u0434\u0430\u0430\u0441\u0442.")
B.aji=new A.a("ebbe7aab-48e9-44ea-9a24-176cf5bf9879","337370dd-7731-490b-9e92-b7f9be6ba695","\u0413\u0423\u041b ACT \u041e\u041d, \u041a\u0418 \u0417\u0418 \u04b2\u0423\u0421\u041d\u0410\u0428 \u04b6\u0410\u04b2\u041e\u041d \u0413\u0423\u041b\u0418\u0421\u0422\u041e\u041d ACT","\u0413\u0443\u043b \u0430\u0441\u0442 \u043e\u043d, \u043a\u0438 \u0437\u0438 \u04b3\u0443\u0441\u043d\u0430\u0448 \u04b7\u0430\u04b3\u043e\u043d \u0433\u0443\u043b\u0438\u0441\u0442\u043e\u043d \u0430\u0441\u0442,\n\u0410\u0437 \u04ef \u0431\u0430 \u04b3\u0430\u0440 \u0447\u0430\u043c\u0430\u043d\u0435 \u0441\u0430\u0434 \u04b3\u0430\u0437\u043e\u0440 \u0434\u0430\u0441\u0442\u043e\u043d \u0430\u0441\u0442.\n\u0427\u0443 \u0493\u0443\u043d\u0447\u0430 \u0433\u0430\u0440 \u0434\u0430\u04b3\u0430\u043d\u0438 \u04ef \u0431\u0430 \u0445\u0430\u043d\u0434\u0430 \u043f\u0430\u0439\u0434\u043e \u0448\u0443\u0434,\n\u04b2\u0430\u043d\u04ef\u0437 \u0437\u0435\u0440\u0438 \u043b\u0430\u0431\u0430\u0448 \u0445\u0430\u043d\u0434\u0430\u04b3\u043e\u0438 \u043f\u0438\u043d\u04b3\u043e\u043d \u0430\u0441\u0442.\n\u0414\u0438\u043b\u0438 \u0441\u0430\u043d\u0430\u0432\u0431\u0430\u0440\u0438 \u0431\u0435\u0493\u0443\u043d\u0447\u0430\u0440\u043e \u0441\u0430\u0431\u043e \u0431\u0438\u0440\u0430\u0431\u0443\u0434,\n\u041a\u0438 \u0441\u0430\u0440\u0432 \u0431\u0430 \u0441\u0430\u0440\u0438 \u0433\u0443\u043b \u04b3\u0430\u043c\u0447\u0443 \u0431\u0435\u0434\u0438 \u043b\u0430\u0440\u0437\u043e\u043d \u0430\u0441\u0442.\n\u0411\u0438\u0440\u0435\u0437 \u0445\u0443\u043d\u0438 \u0441\u0443\u0440\u043e\u04b3\u04e3, \u043a\u0438 \u0445\u0443\u043d\u0431\u0430\u04b3\u043e, \u0441\u043e\u049b\u04e3\n\u04b2\u0430\u0437\u043e\u0440 \u04b7\u043e\u043d\u0438 \u0433\u0438\u0440\u043e\u043c\u04e3 \u0434\u0438\u04b3\u0435\u043c\u0443 \u0430\u0440\u0437\u043e\u043d \u0430\u0441\u0442.\n\u041c\u0430\u0440\u043e \u0442\u0443 \u0443\u043c\u0440\u04e3, \u0430\u0433\u0430\u0440 \u0430\u04b3\u0434 \u0431\u0438\u0448\u043a\u0430\u043d\u04e3, \u0447\u04e3 \u0430\u04b7\u0430\u0431,\n\u041a\u0438 \u0430\u04b3\u0434\u0438 \u0443\u043c\u0440 \u0431\u0430 \u043c\u043e \u0441\u0430\u0445\u0442 \u0441\u0443\u0441\u0442\u043f\u0430\u0439\u043c\u043e\u043d \u0430\u0441\u0442.\n\u0414\u0443\u043e\u0441\u0442 \u0440\u04ef\u0439\u0438 \u0442\u0443\u0440\u043e \u0441\u0443\u0440\u0430\u0435, \u043a\u0438 \u0431\u0430\u0440 \u0432\u0430\u0440\u0430\u049b \u0430\u0441\u0442,\n\u0428\u0438\u0444\u043e\u0441\u0442 \u0448\u0430\u04b3\u0434\u0438 \u0442\u0443\u0440\u043e \u043e\u044f\u0442\u0435, \u043a\u0438 \u0434\u0430\u0440\u043c\u043e\u043d \u0430\u0441\u0442.\n\u0427\u0443 \u0431\u043e\u0434\u0438 \u0441\u0443\u0431\u04b3 \u0434\u0430\u043c \u0430\u0437 \u0437\u0443\u043b\u0444\u0438 \u04ef \u043c\u0430\u0437\u0430\u043d, \u041d\u043e\u0441\u0438\u0440,\n\u0414\u0430\u0440 \u0438\u043d \u04b3\u0430\u0434\u0438\u0441, \u043a\u0438 \u043f\u0435\u0447\u0438\u0434\u0430\u0432\u0443 \u043f\u0430\u0440\u0435\u0448\u043e\u043d \u0430\u0441\u0442.")
