B.acZ=new A.a("a77fe8ee-e0d2-469b-a9ec-8bf6cd15ae2f","eb037eb9-ba72-49bd-b009-8f9c84d46105","\u0411\u0435 \u0441\u0430\u0440\u043b\u0430\u0432\u04b3\u0430","\u0413\u0430\u0440 \u0430\u0439\u0431\u0438 \u0445\u043e\u043a\u0438 \u043f\u043e\u043a\u0438 \u0421\u0438\u0438\u0441\u0442\u043e\u043d \u043a\u0443\u043d\u0430\u0434 \u043a\u0430\u0441\u0435,\n\u0414\u0430\u0440\u0451 \u043f\u0430\u043b\u0438\u0434 \u043c\u0435\u043d\u0430\u0448\u0430\u0432\u0430\u0434 \u0430\u0437 \u0434\u0430\u04b3\u043e\u043d\u0438 \u0441\u0430\u0433.")
B.al1=new A.a("76c2a13e-cd63-473a-a6f5-2db89482f152","228feecd-8a97-4aaf-9b92-b9896c3a7d7d","\u0411\u0435 \u0441\u0430\u0440\u043b\u0430\u0432\u04b3\u0430","\u041d\u0430\u049b\u049b\u043e\u0448 \u0430\u04b7\u0430\u0431 \u0441\u0430\u0444\u04b3\u0430 \u043c\u0443\u043d\u0430\u049b\u049b\u0430\u0448 \u043a\u0430\u0440\u0434\u04e3!\n\u042d\u0439 \u0432\u0430\u049b\u0442\u0438 \u0442\u0443 \u0445\u0443\u0448, \u043a\u0438 \u0432\u0430\u049b\u0442\u0438 \u043c\u043e \u0445\u0443\u0448 \u043a\u0430\u0440\u0434\u04e3!")
B.a6R=new A.a("74995550-084b-4bb8-9366-6136c08c0807","7c389f92-ffdc-4f8e-b901-1de71acc34a9","\u0411\u0435 \u0441\u0430\u0440\u043b\u0430\u0432\u04b3\u0430","\u0414\u0430\u0440\u0435\u0493\u0443 \u0434\u0430\u0440\u0434 \u0430\u0437 \u0438\u043d \u043c\u0430\u0440\u0434\u0443\u043c\u043e\u043d, \u043a\u0438 \u0445\u043e\u043a \u0448\u0443\u0434\u0430\u043d\u0434,\n\u0411\u0430 \u0442\u0435\u0493\u0438 \u043c\u0430\u0440\u0433 \u04b7\u0438\u0433\u0430\u0440\u0440\u0435\u0448\u0443 \u0441\u0438\u043d\u0430\u0447\u043e\u043a \u0448\u0443\u0434\u0430\u043d\u0434.")
B.a94=new A.a("45e36115-10d8-4f2a-bc10-d54f7d7406ce","465d3f4a-4924-4ca6-9371-7266ae4393c7","\u0414\u0418\u041b \u0417\u0410\u0411\u041e\u041d\u0418 \u0428\u0418\u041a\u0412\u0410 \u041f\u0415\u0428\u0418 \u041c\u0410\u041d \u0417\u0418 \u0421\u0410\u0425\u0422\u04e2 \u0411\u041e\u0417 \u041a\u0410\u0420\u0414","\u0414\u0438\u043b \u0437\u0430\u0431\u043e\u043d\u0438 \u0448\u0438\u043a\u0432\u0430 \u043f\u0435\u0448\u0438 \u043c\u0430\u043d \u0437\u0438 \u0441\u0430\u0445\u0442\u04e3 \u0431\u043e\u0437 \u043a\u0430\u0440\u0434,\n\u0428\u0438\u0448\u0430 \u0447\u0443\u043d \u0432\u0430\u049b\u0442\u0438 \u0448\u0438\u043a\u0430\u0441\u0442\u0430\u043d \u0448\u0443\u0434, \u043c\u0430\u0440\u043e \u043e\u0432\u043e\u0437 \u043a\u0430\u0440\u0434.\n\u0410\u0437 \u0444\u0438\u0493\u043e\u043d \u0433\u0430\u0440\u0434\u0438\u0434 \u0430\u0444\u0437\u0443\u043d \u0442\u0438\u0440\u0430\u0431\u0430\u0445\u0442\u0438\u04b3\u043e\u0438 \u043c\u0430\u043d,\n\u041a\u0443\u043b\u0431\u0430\u0430\u043c\u0440\u043e \u0442\u0438\u0440\u0430 \u0434\u0443\u0434\u0438 \u0448\u0443\u044a\u043b\u0430\u0438 \u043e\u0432\u043e\u0437 \u043a\u0430\u0440\u0434.\n\u0411\u0435 \u0442\u0443 \u0434\u0443\u0440\u0434\u0438 \u043c\u0430\u0439 \u0431\u0430 \u0445\u043e\u0442\u0438\u0440 \u0448\u0443\u0434 \u043c\u0430\u0440\u043e \u0433\u0430\u0440\u0434\u0438 \u043c\u0430\u043b\u043e\u043b,\n\u0421\u043e\u0444\u0438 \u04ef \u0433\u0430\u0440\u0434\u0438\u0434 \u0440\u0430\u043d\u0433 \u0430\u0437 \u0447\u0435\u04b3\u0440\u0430\u0430\u0448 \u043f\u0430\u0440\u0432\u043e\u0437 \u043a\u0430\u0440\u0434.\n\u041d\u0430\u0493\u043c\u0430\u04b3\u043e\u0438 \u043e\u043d \u0441\u0430\u043d\u0430\u043c \u0442\u043e \u0441\u0443\u0431\u04b3 \u043c\u0435\u043e\u044f\u0434 \u0431\u0430 \u0433\u04ef\u0448,\n\u0413\u04ef\u04e3 \u0438\u043c\u0448\u0430\u0431 \u043c\u0443\u0442\u0440\u0438\u0431 \u0430\u0437 \u0437\u0443\u043d\u043d\u043e\u0440 \u0442\u043e\u0440\u0438 \u0441\u043e\u0437 \u043a\u0430\u0440\u0434.\n\u0427\u0443\u043d \u043d\u0438\u0433\u043e\u04b3\u0435, \u043a-\u04ef \u0437\u0438 \u0447\u0430\u0448\u043c\u0438 \u0441\u0443\u0440\u043c\u0430\u0434\u043e\u0440 \u043e\u044f\u0434 \u0431\u0443\u0440\u0443\u043d,\n\u0428\u0430\u0432\u043a\u0430\u0442 \u0430\u0437 \u0445\u043e\u043a\u0438 \u0421\u0438\u0444\u043e\u04b3\u043e\u043d \u0440\u04ef \u0441\u04ef\u0439\u0438 \u0428\u0435\u0440\u043e\u0437 \u043a\u0430\u0440\u0434!")
B.anT=new A.a("f2694f8e-ae9c-4eb2-a336-8c02bd0620d9","465d3f4a-4924-4ca6-9371-7266ae4393c7","\u041a\u0410\u0412\u0421\u0410\u0420 \u04b2\u0410\u0420\u0418\u0424\u0418 \u0427\u0410\u0428\u041c\u0418 \u0422\u0410\u0420\u0418 \u041c\u0410\u041d \u041d\u0410\u041c\u0415\u0428\u0410\u0412\u0410\u0414","\u041a\u0430\u0432\u0441\u0430\u0440 \u04b3\u0430\u0440\u0438\u0444\u0438 \u0447\u0430\u0448\u043c\u0438 \u0442\u0430\u0440\u0438 \u043c\u0430\u043d \u043d\u0430\u043c\u0435\u0448\u0430\u0432\u0430\u0434,\n\u0414\u04ef\u0437\u0430\u0445 \u0493\u0443\u0431\u043e\u0440\u0438 \u0440\u0430\u04b3\u0433\u0443\u0437\u0430\u0440\u0438 \u043c\u0430\u043d \u043d\u0430\u043c\u0435\u0448\u0430\u0432\u0430\u0434.\n\u0418\u043d\u044a\u043e\u043c\u0438 \u0445\u0430\u043b\u049b \u0447\u0438\u0441\u0442, \u043a\u0438 \u0430\u0441\u0431\u043e\u0431\u0438 \u043a\u043e\u0438\u043d\u043e\u0442,\n\u0421\u0430\u043d\u0434\u0430\u043b \u0431\u0430\u04b3\u043e\u0438 \u0434\u0430\u0440\u0434\u0438 \u0441\u0430\u0440\u0438 \u043c\u0430\u043d \u043d\u0430\u043c\u0435\u0448\u0430\u0432\u0430\u0434.\n\u0413\u0438\u0440\u0430\u043c, \u043a\u0438 \u043e\u0441\u043c\u043e\u043d\u0443 \u0437\u0430\u043c\u0438\u043d \u043e\u0444\u0442\u043e\u0431 \u0448\u0443\u0434,\n\u041e\u0438\u043d\u0430\u0445\u043e\u043d\u0430\u0438 \u043d\u0430\u0437\u0430\u0440\u0438 \u043c\u0430\u043d \u043d\u0430\u043c\u0435\u0448\u0430\u0432\u0430\u0434.\n\u041c\u0438\u043d\u043d\u0430\u0442 \u0437\u0438 \u043e\u0444\u0442\u043e\u0431\u0438 \u049b\u0438\u0451\u043c\u0430\u0442 \u0447\u0430\u0440\u043e \u043a\u0430\u0448\u0430\u043c?!\n\u0418\u043d \u049b\u0443\u0440\u0441 \u0442\u04ef\u0448\u0430\u0438 \u0441\u0430\u0444\u0430\u0440\u0438 \u043c\u0430\u043d \u043d\u0430\u043c\u0435\u0448\u0430\u0432\u0430\u0434!\n\u0428\u0430\u0432\u043a\u0430\u0442 \u0434\u0438\u043b\u0430\u043c \u0437\u0438 \u0448\u0443\u044a\u043b\u0430\u0438 \u0438\u0434\u0440\u043e\u043a \u0440\u0430\u0432\u0448\u0430\u043d \u0430\u0441\u0442,\n\u041e\u0442\u0430\u0448 \u043c\u0443\u049b\u043e\u0431\u0438\u043b\u0438 \u0448\u0430\u0440\u0430\u0440\u0438 \u043c\u0430\u043d \u043d\u0430\u043c\u0435\u0448\u0430\u0432\u0430\u0434!")
B.akS=new A.a("4ad63b77-f418-432a-9bac-2ea66a30aa7d","465d3f4a-4924-4ca6-9371-7266ae4393c7","\u041a\u0410\u0419 \u0422\u0410\u0412\u041e\u041d \u0410\u0417 \u04b2\u0410\u0420\u0424\u0418 \u0421\u0410\u0420\u0414\u0418 \u0414\u0423\u0428\u041c\u0410\u041d\u041e\u041d \u041e\u0421\u0423\u0414\u0410 \u0428\u0423\u0414","\u041a\u0430\u0439 \u0442\u0430\u0432\u043e\u043d \u0430\u0437 \u04b3\u0430\u0440\u0444\u0438 \u0441\u0430\u0440\u0434\u0438 \u0434\u0443\u0448\u043c\u0430\u043d\u043e\u043d \u043e\u0441\u0443\u0434\u0430 \u0448\u0443\u0434,\n\u0411\u0430\u0440\u0433\u0438 \u0433\u0443\u043b \u043d\u0430\u0442\u0432\u043e\u043d\u0430\u0434 \u0430\u0437 \u0431\u043e\u0434\u0438 \u0445\u0430\u0437\u043e\u043d \u043e\u0441\u0443\u0434\u0430 \u0448\u0443\u0434.\n\u0411\u0430\u0441\u043a\u0438 \u0438\u043c\u0448\u0430\u0431 \u0434\u0438\u0434 \u0433\u0435\u0441\u0443\u0438 \u0441\u0438\u0451\u04b3\u0438 \u0445\u0443\u0434 \u0431\u0430 \u0445\u043e\u0431,\n\u0427\u0430\u0448\u043c\u0438 \u043c\u0430\u0441\u0442\u0438 \u04ef \u0437\u0438 \u043d\u043e\u0437\u0438 \u0441\u0443\u0440\u043c\u0430\u0434\u043e\u043d \u043e\u0441\u0443\u0434\u0430 \u0448\u0443\u0434.\n\u0422\u043e \u0431\u0430 \u0448\u04ef\u0445\u0435 \u0434\u043e\u0434\u0430\u0430\u043c \u0434\u0438\u043b, \u0430\u0437 \u0493\u0430\u043c\u0438 \u0434\u0438\u043b \u0444\u043e\u0440\u0438\u0493\u0430\u043c,\n\u0420\u0430\u0444\u0442 \u0447\u0443\u043d \u0433\u0443\u043b \u0430\u0437 \u0433\u0443\u043b\u0438\u0441\u0442\u043e\u043d, \u0431\u043e\u0493\u0431\u043e\u043d \u043e\u0441\u0443\u0434\u0430 \u0448\u0443\u0434.\n\u0420\u043e\u04b3 \u043e\u0442\u0430\u0448\u0445\u0435\u0437\u0443 \u0431\u043e\u0440\u0438 \u043a\u043e\u0440\u0432\u043e\u043d\u0438 \u043c\u043e \u0441\u0438\u043f\u0430\u043d\u0434,\n\u0427\u0443\u043d \u0442\u0430\u0432\u043e\u043d\u0430\u0434 \u0434\u0438\u043b \u0437\u0438 \u0441\u0430\u0432\u0434\u043e\u0438 \u04b7\u0430\u04b3\u043e\u043d \u043e\u0441\u0443\u0434\u0430 \u0448\u0443\u0434?!\n\u0417\u0430\u0445\u043c\u0440\u043e \u0430\u0437 \u043c\u0430\u0440\u04b3\u0430\u043c\u0438 \u043a\u043e\u0444\u0443\u0440 \u043e\u044f\u0434 \u043b\u0430\u0431 \u0431\u0430 \u04b3\u0430\u043c,\n\u0422\u043e \u043d\u0438\u04b3\u043e\u0434\u0430\u043c \u043c\u0443\u04b3\u0440\u0438 \u0445\u043e\u043c\u04ef\u0448\u04e3, \u0434\u0430\u04b3\u043e\u043d \u043e\u0441\u0443\u0434\u0430 \u0448\u0443\u0434.\n\u0428\u0443\u044a\u043b\u0430\u0438 \u043e\u0432\u043e\u0437\u0438 \u043c\u043e\u0440\u043e \u0431\u0430\u0440\u0433\u0438 \u0433\u0443\u043b \u0434\u043e\u043c\u0430\u043d\u0437\u0430\u043d \u0430\u0441\u0442,\n\u0427\u0443\u043d \u0442\u0430\u0432\u043e\u043d\u0430\u0434 \u0431\u0443\u043b\u0431\u0443\u043b\u0438 \u043c\u043e \u0430\u0437 \u0444\u0438\u0493\u043e\u043d \u043e\u0441\u0443\u0434\u0430 \u0448\u0443\u0434?!\n\u0492\u0443\u043d\u0447\u0430\u0438 \u043c\u0438\u043d\u049b\u043e\u0440\u0438 \u043c\u043e \u0442\u043e \u0433\u0430\u0448\u0442 \u0440\u0430\u043d\u0433\u0438 \u043d\u0430\u0493\u043c\u0430\u0440\u0435\u0437,\n\u0413\u04ef\u0448\u0438 \u0433\u0443\u043b\u04b3\u043e \u0430\u0437 \u0444\u0438\u0493\u043e\u043d\u0438 \u0431\u0443\u043b\u0431\u0443\u043b\u043e\u043d \u043e\u0441\u0443\u0434\u0430 \u0448\u0443\u0434.")
B.agS=new A.a("86aa027c-fba7-4a4d-b2fe-e2cfb924e4f8","22097ef5-9ab2-4b03-a971-e62927f2f8c8","\u0411\u0435 \u0441\u0430\u0440\u043b\u0430\u0432\u04b3\u0430","\u041d\u043e\u0437\u0438\u043c\u0438 \u043c\u0430\u0448\u0440\u0438\u049b\u0437\u0430\u043c\u0438\u043d\u0430\u043c, \u043d\u0435\u0441\u0442 \u0433\u0430\u0440 \u0431\u043e\u0432\u0430\u0440 \u0442\u0443\u0440\u043e,\n\u041c\u0435\u0448\u0430\u0432\u0430\u0434 \u043c\u0430\u044a\u043b\u0443\u043c \u0430\u0437 \u043d\u0430\u0437\u043c\u0438 \u04b7\u0430\u04b3\u043e\u043d\u043e\u0440\u043e\u0438 \u043c\u0430\u043d.\n\u0428\u0430\u0440\u0431\u0430\u0442\u0438 \u0430\u0431\u0440\u0435\u0448\u0438\u043c\u0438 \u043c\u0430\u044a\u043d\u04e3 \u043c\u0443\u0440\u0430\u043a\u043a\u0430\u0431 \u043a\u0430\u0440\u0434\u0430\u0430\u0441\u0442,\n\u0411\u0430\u04b3\u0440\u0438 \u0434\u0438\u043b\u04b3\u043e\u0438 \u0437\u0430\u0438\u0444\u043e\u043d \u043a\u0438\u043b\u043a\u0438 \u0430\u043d\u0431\u0430\u0440\u0441\u043e\u0438 \u043c\u0430\u043d.")
