B.a9o=new A.a("de683845-250f-4cd0-b981-e8bc6efa3706","f0b1063a-6315-46b1-84ee-9a7787325a4c","\u04b2\u0430\u0440 \u0431\u0430\u043b\u043e\u0435, \u043a\u0438 \u0437-\u043e\u0441\u043c\u043e\u043d \u043e\u044f\u0434,","\u04b2\u0430\u0440 \u0431\u0430\u043b\u043e\u0435, \u043a\u0438 \u0437-\u043e\u0441\u043c\u043e\u043d \u043e\u044f\u0434,\n\u0413\u0430\u0440\u0447\u0438 \u0431\u0430\u0440 \u0434\u0438\u0433\u0430\u0440\u0435 \u049b\u0430\u0437\u043e \u0431\u043e\u0448\u0430\u0434,\n\u0411\u0430 \u0437\u0430\u043c\u0438\u043d \u043d\u043e\u0440\u0430\u0441\u0438\u0434\u0430 \u043c\u0435\u0433\u04ef\u044f\u0434:\n\xab\u0425\u043e\u043d\u0430\u0438 \u0410\u043d\u0432\u0430\u0440\u04e3 \u043a\u0443\u04b7\u043e \u0431\u043e\u0448\u0430\u0434?\xbb")
B.al2=new A.a("cf1794c5-e541-4678-a89c-36c4b370018d","f0b1063a-6315-46b1-84ee-9a7787325a4c","\u0414\u04e3 \u043c\u0430\u0440\u043e \u043e\u0448\u0438\u049b\u0430\u043a\u0435 \u0433\u0443\u0444\u0442: \xab\u0492\u0430\u0437\u0430\u043b \u043c...","\u0414\u04e3 \u043c\u0430\u0440\u043e \u043e\u0448\u0438\u049b\u0430\u043a\u0435 \u0433\u0443\u0444\u0442: \xab\u0492\u0430\u0437\u0430\u043b \u043c\u0435\u0433\u04ef\u0439\u04e3?\xbb,\n\u0413\u0443\u0444\u0442\u0430\u043c: \xab\u0410\u0437 \u043c\u0430\u0434\u04b3\u0443 \u04b3\u0438\u04b7\u043e \u0434\u0430\u0441\u0442 \u0431\u0438\u044f\u0444\u0448\u043e\u043d\u0434\u0430\u043c \u043c\u0430\u043d\xbb.\n\u0413\u0443\u0444\u0442: \xab\u0427\u0443\u043d?\xbb \u0413\u0443\u0444\u0442\u0430\u043c\u0430\u0448: \xab\u041e\u043d \u04b3\u043e\u043b\u0430\u0442\u0438 \u0433\u0443\u043c\u0440\u043e\u04b3\u04e3 \u0440\u0430\u0444\u0442\xbb,\n\u04b2\u043e\u043b\u0430\u0442\u0438 \u0440\u0430\u0444\u0442\u0430 \u0434\u0438\u0433\u0430\u0440 \u0431\u043e\u0437 \u043d\u0430\u0451\u044f\u0434 \u0437\u0438 \u0430\u0434\u0430\u043c.\n\u0492\u0430\u0437\u0430\u043b\u0443 \u043c\u0430\u0434\u04b3\u0443 \u04b3\u0438\u04b7\u043e \u04b3\u0430\u0440 \u0441\u0435 \u0431\u0430\u0434-\u043e\u043d \u043c\u0435\u0433\u0443\u0444\u0442\u0430\u043c,\n\u041a\u0438 \u043c\u0430\u0440\u043e \u0448\u0430\u04b3\u0432\u0430\u0442\u0443 \u04b3\u0438\u0440\u0441\u0443 \u0493\u0430\u0437\u0430\u0431\u0435 \u0431\u0443\u0434 \u0431\u0430 \u04b3\u0430\u043c\u2026\n\u0492\u0430\u0437\u0430\u043b\u0443 \u043c\u0430\u0434\u04b3\u0443 \u04b3\u0438\u04b7\u043e \u0433\u04ef\u044f\u043c, \u0451 \u0420\u0430\u0431, \u0437\u0438\u043d\u04b3\u043e\u0440,\n\u0411\u0430\u0441 \u043a\u0438 \u0431\u043e \u043d\u0430\u0444\u0441 \u04b7\u0430\u0444\u043e \u043a\u0430\u0440\u0434\u0430\u043c\u0443 \u0431\u043e \u0430\u049b\u043b \u0441\u0438\u0442\u0430\u043c.")
B.aeD=new A.a("62fa8b89-af25-4c5c-8475-91936d724f74","f0b1063a-6315-46b1-84ee-9a7787325a4c","\u0425\u043e\u0442\u0438\u0440\u0435 \u0447\u0443\u043d \u043e\u0442\u0430\u0448\u0430\u043c \u04b3\u0430\u0441\u0442\u0443 \u0437\u0430\u0431\u043e\u043d\u0435...","\u0425\u043e\u0442\u0438\u0440\u0435 \u0447\u0443\u043d \u043e\u0442\u0430\u0448\u0430\u043c \u04b3\u0430\u0441\u0442\u0443 \u0437\u0430\u0431\u043e\u043d\u0435 \u04b3\u0430\u043c\u0447\u0443 \u043e\u0431,\n\u0424\u0438\u043a\u0440\u0430\u0442\u0435 \u0442\u0435\u0437\u0443 \u0437\u0430\u043a\u043e\u0435 \u0440\u043e\u043c\u0443 \u0442\u0430\u0431\u044a\u0435 \u0431\u0435\u0445\u0430\u043b\u0430\u043b.\n\u042d\u0439 \u0434\u0430\u0440\u0435\u0493\u043e, \u043d\u0435\u0441\u0442 \u043c\u0430\u043c\u0434\u0443\u04b3\u0435 \u0441\u0430\u0437\u043e\u0432\u043e\u0440\u0438 \u043c\u0430\u0434\u0435\u04b3\n\u0412-\u044d\u0439 \u0434\u0430\u0440\u0435\u0493\u043e, \u043d\u0435\u0441\u0442 \u043c\u0430\u044a\u0448\u0443\u049b\u0435 \u0441\u0430\u0437\u043e\u0432\u043e\u0440\u0438 \u0493\u0430\u0437\u0430\u043b!")
B.a6f=new A.a("56b09fbc-b97e-4423-a5e9-e656e7690607","f0b1063a-6315-46b1-84ee-9a7787325a4c","\u0420\u0443\u0431\u044a\u0438 \u043c\u0430\u0441\u043a\u0443\u043d \u043e\u0434\u0430\u043c\u0438\u0440\u043e \u0431\u0443\u0434, \u0434\u0435\u0432\u0443...","\u0420\u0443\u0431\u044a\u0438 \u043c\u0430\u0441\u043a\u0443\u043d \u043e\u0434\u0430\u043c\u0438\u0440\u043e \u0431\u0443\u0434, \u0434\u0435\u0432\u0443 \u0434\u0430\u0434 \u0433\u0438\u0440\u0438\u0444\u0442,\n\u041a\u0430\u0441 \u043d\u0430\u043c\u0435\u0434\u043e\u043d\u0430\u0434, \u043a\u0438 \u0434\u0430\u0440 \u043e\u0444\u043e\u049b \u0438\u043d\u0441\u043e\u043d\u0435 \u043a\u0443\u04b7\u043e\u0441\u0442!\n\u0414\u0430\u0432\u0440 \u0434\u0430\u0432\u0440\u0438 \u0445\u0443\u0448\u043a\u0441\u043e\u043b\u0438 \u0434\u0438\u043d\u0443 \u049b\u0430\u04b3\u0442\u0438 \u0434\u043e\u043d\u0438\u0448 \u0430\u0441\u0442,\n\u0427\u0430\u043d\u0434 \u0433\u04ef\u0439\u04e3 \u0444\u0430\u0442\u04b3\u0438 \u0431\u043e\u0431\u0435 \u043a\u0443\u0432\u0443 \u0431\u043e\u0440\u043e\u043d\u0435 \u043a\u0443\u04b7\u043e\u0441\u0442?\n\u041c\u0430\u043d \u0442\u0443\u0440\u043e \u0431\u0438\u043d\u043c\u043e\u044f\u043c \u0430\u043d\u0434\u0430\u0440 \u04b3\u043e\u043b \u0441\u0430\u0434 \u0411\u04ef\u04b7\u0430\u04b3\u043b\u0438 \u04b7\u0430\u04b3\u043b,\n\u0413\u0430\u0440 \u043c\u0443\u0441\u0443\u043b\u043c\u043e\u043d\u04e3 \u0442\u0443, \u0442\u0430\u044a\u0439\u0438\u043d \u043a\u0443\u043d, \u043a\u0438 \u0421\u0430\u043b\u043c\u043e\u043d\u0435 \u043a\u0443\u04b7\u043e\u0441\u0442?\n\u041e\u0441\u043c\u043e\u043d \u0431\u0435\u0445\u0438 \u043a\u0430\u043c\u043e\u043b \u0430\u0437 \u0445\u043e\u043a\u0438 \u043e\u043b\u0430\u043c \u0431\u0430\u0440\u043a\u0430\u0448\u0438\u0434,\n\u0422\u0443 \u0437\u0430\u043d\u0430\u0445 \u043c\u0435\u0437\u0430\u043d, \u043a\u0438 \u0434\u0430\u0440 \u043c\u0430\u043d \u0433\u0430\u043d\u04b7\u0438 \u043f\u0438\u043d\u04b3\u043e\u043d\u0435 \u043a\u0443\u04b7\u043e\u0441\u0442?\n\u0425\u043e\u043a\u0440\u043e \u0442\u04ef\u0444\u043e\u043d \u0430\u0433\u0430\u0440 \u0493\u0443\u0441\u043b\u0435 \u0434\u0438\u04b3\u0430\u0434, \u0432\u0430\u049b\u0442 \u043e\u043c\u0430\u0434\u0430\u0441\u0442,\n\u042d\u0439 \u0434\u0430\u0440\u0435\u0493\u043e, \u0434\u043e\u0438\u0435 \u0447\u0443\u043d \u041d\u0443\u04b3, \u0442\u04ef\u0444\u043e\u043d\u0435 \u043a\u0443\u04b7\u043e\u0441\u0442?")
B.a8b=new A.a("abfed618-6068-4a07-9975-afbdce4b08ee","f0b1063a-6315-46b1-84ee-9a7787325a4c","\u0410\u0433\u0430\u0440 \u043e\u043b\u0430\u043c \u0441\u0430\u0440\u043e\u0441\u0430\u0440 \u0437\u0443\u043b\u043c \u0433\u0438\u0440\u0430\u0434,","\u0410\u0433\u0430\u0440 \u043e\u043b\u0430\u043c \u0441\u0430\u0440\u043e\u0441\u0430\u0440 \u0437\u0443\u043b\u043c \u0433\u0438\u0440\u0430\u0434,\n\u041d\u0430\u0451\u0431\u0430\u0434 \u04b3\u0435\u0447 \u043c\u0430\u0437\u043b\u0443\u043c \u0430\u0437 \u0444\u0430\u043b\u0430\u043a \u0434\u043e\u0434!\n\u04b2\u0430\u043c\u0430 \u0437\u0443\u043b\u043c \u0430\u0437 \u043d\u0443\u04b7\u0443\u043c\u0443 \u0430\u0437 \u0444\u0430\u043b\u0430\u043a \u0434\u043e\u043d,\n\u041a\u0438 \u043b\u0430\u044a\u043d\u0430\u0442 \u0431\u0430\u0440 \u043d\u0443\u04b7\u0443\u043c\u0443 \u0431\u0430\u0440 \u0444\u0430\u043b\u0430\u043a \u0431\u043e\u0434!")
B.aeP=new A.a("9d49c9d6-e91f-4b31-82f5-b8759ebcfd55","f0b1063a-6315-46b1-84ee-9a7787325a4c","\u041a\u0430\u0439 \u0431\u0443\u0432\u0430\u0434 \u0438\u043d \u0441\u0438\u043f\u0435\u04b3\u0440\u0438 \u04b3\u043e\u0434\u0438\u0441\u0430\u0437\u043e\u0439","\u041a\u0430\u0439 \u0431\u0443\u0432\u0430\u0434 \u0438\u043d \u0441\u0438\u043f\u0435\u04b3\u0440\u0438 \u04b3\u043e\u0434\u0438\u0441\u0430\u0437\u043e\u0439\n\u04b6\u0443\u043c\u043b\u0430 \u0430\u0437 \u044f\u043a\u0434\u0438\u0433\u0430\u0440 \u0444\u0443\u0440\u04ef \u0440\u0435\u0437\u0430\u0434?!\n\u0401 \u0447\u0443 \u043f\u0430\u0440\u0432\u0435\u0437\u0430\u043d \u0430\u0441\u0442 \u04ef, \u043a\u0438 \u043c\u0443\u0434\u043e\u043c\n\u0411\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d \u043e\u0442\u0430\u0448\u0438 \u0431\u0430\u043b\u043e \u0431\u0435\u0437\u0430\u0434.\n\u0414\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d \u0431\u04ef\u0439\u0438 \u043e\u0444\u0438\u044f\u0442 \u043d\u0430\u0433\u0437\u043e\u0448\u0442,\n\u0427\u0430\u043d\u0434 \u0430\u0437 \u0438\u043d \u0440\u0430\u043d\u0433 \u0444\u0438\u0442\u043d\u0430 \u043e\u043c\u0435\u0437\u0430\u0434?!\n\u0411\u0430\u0440\u043d\u0430\u0445\u0435\u0437\u0430\u0434 \u043c\u0430\u0433\u0430\u0440 \u0431\u0430 \u0434\u0430\u0441\u0442\u0438 \u0441\u0438\u0442\u0430\u043c,\n\u041c\u0430\u043d \u043d\u0430\u0434\u043e\u043d\u0430\u043c, \u043a-\u0430\u0437 \u0438\u043d \u0447\u04e3 \u0431\u0430\u0440\u0445\u0435\u0437\u0430\u0434!\n\u041c\u0435\u043d\u0430\u0451\u0440\u0430\u043c \u0433\u0443\u0440\u0435\u0445\u0442, \u0433\u0430\u0440\u043d\u0430, \u043d\u0430 \u043c\u0430\u043d,\n\u0414\u0435\u0432 \u0430\u0437 \u0438\u043d \u0440\u04ef\u0437\u0433\u043e\u0440 \u0431\u0438\u0433\u0440\u0435\u0437\u0430\u0434.")
B.acm=new A.a("933433cb-0d12-4648-b527-0ea6966f3145","f0b1063a-6315-46b1-84ee-9a7787325a4c","\u0411\u0430\u0440 \u0421\u0430\u043c\u0430\u0440\u049b\u0430\u043d\u0434 \u0430\u0433\u0430\u0440 \u0431\u0438\u0433\u0437\u0430\u0440\u04e3, \u044d\u0439...","\u0411\u0430\u0440 \u0421\u0430\u043c\u0430\u0440\u049b\u0430\u043d\u0434 \u0430\u0433\u0430\u0440 \u0431\u0438\u0433\u0437\u0430\u0440\u04e3, \u044d\u0439 \u0431\u043e\u0434\u0438 \u0441\u0430\u04b3\u0430\u0440,\n\u041d\u043e\u043c\u0430\u0438 \u0430\u04b3\u043b\u0438 \u0425\u0443\u0440\u043e\u0441\u043e\u043d \u0431\u0430 \u0431\u0430\u0440\u0438 \u0445\u043e\u049b\u043e\u043d \u0431\u0430\u0440!")
B.ahp=new A.a("df64f1fa-e6f0-49f3-be36-05840c41cdc4","f0b1063a-6315-46b1-84ee-9a7787325a4c","\u0425\u0430\u0431\u0430\u0440\u0430\u0442 \u04b3\u0430\u0441\u0442, \u043a-\u0430\u0437 \u0438\u043d \u0437\u0435\u0440\u0443 \u0437\u0430\u0431...","\u0425\u0430\u0431\u0430\u0440\u0430\u0442 \u04b3\u0430\u0441\u0442, \u043a-\u0430\u0437 \u0438\u043d \u0437\u0435\u0440\u0443 \u0437\u0430\u0431\u0430\u0440 \u0448\u0443\u043c\u0493\u0443\u0437\u043e\u043d\n\u041d\u0435\u0441\u0442 \u044f\u043a \u043f\u0430\u0439 \u0437\u0438 \u0425\u0443\u0440\u043e\u0441\u043e\u043d, \u043a\u0438 \u043d\u0430\u0448\u0443\u0434 \u0437\u0435\u0440\u0443 \u0437\u0430\u0431\u0430\u0440?\n\u0425\u0430\u0431\u0430\u0440\u0430\u0442 \u04b3\u0430\u0441\u0442, \u043a\u0438 \u0430\u0437 \u04b3\u0430\u0440 \u0447\u0438 \u0434\u0430\u0440 \u04ef \u0445\u0430\u0439\u0440\u0435 \u0431\u0443\u0434,\n\u0414\u0430\u0440 \u04b3\u0430\u043c\u0430 \u042d\u0440\u043e\u043d \u0438\u043c\u0440\u04ef\u0437 \u043d\u0430\u043c\u043e\u043d\u0434\u0430\u0441\u0442 \u0430\u0441\u0430\u0440?\n\u0411\u0430\u0440 \u0431\u0443\u0437\u0443\u0440\u0433\u043e\u043d\u0438 \u0437\u0430\u043c\u043e\u043d\u0430 \u0448\u0443\u0434\u0430 \u0445\u0443\u0440\u0434\u043e\u043d \u0441\u043e\u043b\u043e\u0440,\n\u0411\u0430\u0440 \u043a\u0430\u0440\u0438\u043c\u043e\u043d\u0438 \u04b7\u0430\u04b3\u043e\u043d \u0433\u0430\u0448\u0442\u0430 \u043b\u0430\u0438\u043c\u043e\u043d \u043c\u0435\u04b3\u0442\u0430\u0440.\n\u0411\u0430\u0440 \u0434\u0430\u0440\u0438 \u0434\u0443\u043d\u043e\u043d \u0430\u04b3\u0440\u043e\u0440 \u04b3\u0430\u0437\u0438\u043d\u0443 \u04b3\u0430\u0439\u0440\u043e\u043d,\n\u0414\u0430\u0440 \u043a\u0430\u0444\u0438 \u0440\u0438\u043d\u0434\u043e\u043d \u0430\u0431\u0440\u043e\u0440 \u0430\u0441\u0438\u0440\u0443 \u043c\u0443\u0437\u0442\u0430\u0440.\n\u0428\u043e\u0434 \u0438\u043b\u043b\u043e \u0431\u0430 \u0434\u0430\u0440\u0438 \u043c\u0430\u0440\u0433 \u043d\u0430\u0431\u0438\u043d\u04e3 \u043c\u0430\u0440\u0434\u0443\u043c,\n\u0411\u0438\u043a\u0440 \u04b7\u0443\u0437 \u0434\u0430\u0440 \u0448\u0438\u043a\u0430\u043c\u0438 \u043c\u043e\u043c \u043d\u0430\u0451\u0431\u04e3 \u0434\u0443\u0445\u0442\u0430\u0440.\n\u041c\u0430\u0441\u04b7\u0438\u0434\u0438 \u04b7\u043e\u043c\u0435\u0438 \u04b3\u0430\u0440 \u0448\u0430\u04b3\u0440 \u0441\u0443\u0442\u0443\u0440\u043e\u043d\u0448\u043e\u043d\u0440\u043e\n\u041f\u043e\u0439\u0433\u043e\u04b3\u0435\u0441\u0442, \u043a\u0438 \u043d\u0430 \u0441\u0430\u049b\u0444\u0430\u0448 \u043f\u0430\u0439\u0434\u043e\u0432\u0443 \u043d\u0430 \u0434\u0430\u0440.\n\u041d\u0430\u043a\u0443\u043d\u0430\u0434 \u0445\u0443\u0442\u0431\u0430 \u0431\u0430 \u04b3\u0430\u0440 \u0448\u0430\u04b3\u0440 \u0431\u0430 \u043d\u043e\u043c\u0438 \u0493\u0443\u0437, \u0430\u0437 \u043e\u043d-\u043a\n\u0414\u0430\u0440 \u0425\u0443\u0440\u043e\u0441\u043e\u043d \u043d\u0430 \u0445\u0430\u0442\u0438\u0431 \u0430\u0441\u0442 \u043a\u0443\u043d\u0443\u043d, \u043d\u0430 \u043c\u0438\u043d\u0431\u0430\u0440.\n\u041a\u0443\u0448\u0442\u0430\u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0438 \u0433\u0438\u0440\u043e\u043c\u0438\u0440\u043e \u0433\u0430\u0440 \u043d\u043e\u0433\u043e\u04b3\u043e\u043d\n\u0411\u0438\u043d\u0430\u0434, \u0430\u0437 \u0431\u0438\u043c \u0445\u0443\u0440\u04ef\u0448\u0438\u0434 \u043d\u0430\u0451\u0440\u0430\u0434 \u043c\u043e\u0434\u0430\u0440.\n\u041e\u043d \u043a\u0438\u0440\u043e \u0441\u0430\u0434 \u0440\u0430\u04b3 \u0493\u0443\u0437 \u0437\u0430\u0440 \u0441\u0438\u0442\u0430\u0434\u0443 \u0431\u043e\u0437 \u0444\u0443\u0440\u04ef\u0445\u0442,\n\u0414\u043e\u0440\u0430\u0434 \u043e\u043d \u043d\u0430\u0432\u044a, \u043a\u0438 \u0433\u04ef\u0439\u0438\u0448 \u0445\u0430\u0440\u0438\u0434\u0430\u0441\u0442 \u0431\u0430 \u0437\u0430\u0440,\n\u0411\u0430\u0440 \u043c\u0443\u0441\u0443\u043b\u043c\u043e\u043d\u043e\u043d \u0437-\u043e\u043d \u0433\u0443\u043d\u0430 \u043a\u0443\u043d\u0430\u043d\u0434 \u0438\u0441\u0442\u0438\u0445\u0444\u043e\u0444,\n\u041a\u0438 \u043c\u0443\u0441\u0443\u043b\u043c\u043e\u043d \u043d\u0430\u043a\u0443\u043d\u0430\u0434 \u0441\u0430\u0434\u044f\u043a\u0438 \u043e\u043d \u0431\u0430\u0440 \u043a\u043e\u0444\u0430\u0440.\n\u04b2\u0430\u0441\u0442 \u0434\u0430\u0440 \u0420\u0443\u043c\u0443 \u0425\u0438\u0442\u043e \u0430\u043c\u043d \u043c\u0443\u0441\u0443\u043b\u043c\u043e\u043d\u043e\u043d\u0440\u043e,\n\u041d\u0435\u0441\u0442 \u044f\u043a \u0437\u0430\u0440\u0440\u0430 \u0441\u0430\u043b\u043e\u043c\u0430\u0442 \u0431\u0430 \u043c\u0443\u0441\u0443\u043b\u043c\u043e\u043d\u04e3-\u0434\u0430\u0440.")
B.a73=new A.a("9ab4add4-af71-4b68-a8f8-25119b6d2214","f0b1063a-6315-46b1-84ee-9a7787325a4c","\u0411\u0435\u0433\u0443\u043c\u043e\u043d, \u0445\u0430\u043b\u049b\u0438 \u04b7\u0438\u0433\u0430\u0440\u0441\u04ef\u0445\u0442\u0430\u0440\u043e \u0434\u0430...","\u0411\u0435\u0433\u0443\u043c\u043e\u043d, \u0445\u0430\u043b\u049b\u0438 \u04b7\u0438\u0433\u0430\u0440\u0441\u04ef\u0445\u0442\u0430\u0440\u043e \u0434\u0430\u0440\u0451\u0431\u0430\u0434,\n\u0427\u0443\u043d \u0437\u0438 \u0434\u0430\u0440\u0434\u0438 \u0434\u0438\u043b\u0430\u0448\u043e\u043d \u0451\u0431\u0430\u0434 \u0430\u0437 \u0438\u043d \u0433\u0443\u043d\u0430 \u0445\u0430\u0431\u0430\u0440.\n\u0422\u043e \u04b7\u0430\u04b3\u043e\u043d\u0440\u043e \u0431\u0438\u0444\u0443\u0440\u04ef\u0437\u0430\u0434 \u0445\u0443\u0440\u0438 \u0433\u0435\u0442\u0438\u043f\u0430\u0439\u043c\u043e\u0439,\n\u0410\u0437 \u04b7\u0430\u04b3\u043e\u043d\u0434\u043e\u0440\u04e3, \u044d\u0439 \u0445\u0443\u0441\u0440\u0430\u0432\u0438 \u043e\u0434\u0438\u043b, \u0431\u0430\u0440 \u0445(\u0432)\u0430\u0440!")
B.ajY=new A.a("3a11ed61-0d79-4aad-9348-3143d29d4eea","f0b1063a-6315-46b1-84ee-9a7787325a4c","\u041e\u0448\u0438\u049b\u04e3 \u0447\u0438\u0441\u0442? \u2013 \u041c\u0443\u0431\u0442\u0430\u043b\u043e \u0431\u0443\u0434\u0430\u043d,","\u041e\u0448\u0438\u049b\u04e3 \u0447\u0438\u0441\u0442? \u2013 \u041c\u0443\u0431\u0442\u0430\u043b\u043e \u0431\u0443\u0434\u0430\u043d,\n\u0411\u043e \u0493\u0430\u043c\u0443 \u043c\u0435\u04b3\u043d\u0430\u0442 \u043e\u0448\u043d\u043e \u0431\u0443\u0434\u0430\u043d.\n\u0421\u0438\u043f\u0430\u0440\u0438 \u0445\u0430\u043d\u04b7\u0430\u0440\u0438 \u0431\u0430\u043b\u043e \u0433\u0430\u0448\u0442\u0430\u043d,\n\u04b2\u0430\u0434\u0430\u0444\u0438 \u043d\u043e\u0432\u0430\u043a\u0438 \u049b\u0430\u0437\u043e \u0431\u0443\u0434\u0430\u043d.\n\u0411\u0430\u043d\u0434\u0438 \u043c\u0430\u044a\u0448\u0443\u049b \u0447\u0443\u043d \u0431\u0438\u0431\u0430\u0441\u0442\u0430\u0442 \u043f\u043e\u0439,\n\u0410\u0437 \u04b3\u0430\u043c\u0430 \u0431\u0430\u043d\u0434\u04b3\u043e \u04b7\u0443\u0434\u043e \u0431\u0443\u0434\u0430\u043d,\n\u0417\u0435\u0440\u0438 \u0431\u043e\u0440\u0438 \u0431\u0430\u043b\u043e\u0438 \u04ef \u04b3\u0430\u043c\u0430 \u0443\u043c\u0440\n\u0427\u0443\u043d \u0441\u0430\u0440\u0438 \u0437\u0443\u043b\u0444\u0438 \u04ef \u0434\u0443\u0442\u043e \u0431\u0443\u0434\u0430\u043d.\n\u041e\u0444\u0442\u043e\u0431\u0438 \u0440\u0443\u0445\u0430\u0448 \u0447\u0443 \u0440\u0443\u0445 \u0431\u0438\u043d\u043c\u0443\u0434,\n\u041f\u0435\u0448\u0438 \u04ef \u0437\u0430\u0440\u0440\u0430\u0438 \u04b3\u0430\u0431\u043e \u0431\u0443\u0434\u0430\u043d.\n\u0411\u043e \u04b3\u0430\u043c\u0430 \u043c\u0435\u04b3\u043d\u0430\u0442\u0435 \u0440\u0438\u0437\u043e \u0434\u043e\u0434\u0430\u043d\n\u0412-\u0430\u0437 \u04b3\u0430\u043c\u0430 \u0434\u0430\u0432\u043b\u0430\u0442\u0435 \u04b7\u0443\u0434\u043e \u0431\u0443\u0434\u0430\u043d.\n\u0413\u0430\u0440 \u043b\u0430\u0433\u0430\u0434\u043a\u04ef\u0431\u0438 \u0441\u0430\u0434 \u04b7\u0430\u0444\u043e \u0431\u043e\u0448\u04e3,\n\u04b2\u0430\u043c\u0447\u0443\u043d\u043e\u043d \u0431\u0430\u0440 \u0441\u0430\u0440\u0438 \u0432\u0430\u0444\u043e \u0431\u0443\u0434\u0430\u043d.\n\u0418\u0448\u049b \u0430\u0433\u0430\u0440 \u0443\u0441\u0442\u0443\u0445\u043e\u043d\u0430\u0442 \u043e\u0441 \u043a\u0443\u043d\u0430\u0434,\n\u0421\u0430\u043d\u0433\u0438 \u0437\u0435\u0440\u0438\u043d\u0438 \u043e\u0441\u0438\u0451 \u0431\u0443\u0434\u0430\u043d.")
B.alT=new A.a("21ea1376-9334-4249-aeda-5ddc5e01e88a","f0b1063a-6315-46b1-84ee-9a7787325a4c","\u0411\u0438\u0434\u0438\u0434\u0430\u043c \u04b7\u0430\u04b3\u043e\u043d\u0440\u043e, \u043d\u0430\u0432\u043e\u0435 \u043d\u0430\u0434\u043e\u0440\u0430\u0434...","\u0411\u0438\u0434\u0438\u0434\u0430\u043c \u04b7\u0430\u04b3\u043e\u043d\u0440\u043e, \u043d\u0430\u0432\u043e\u0435 \u043d\u0430\u0434\u043e\u0440\u0430\u0434,\n\u04b6\u0430\u04b3\u043e\u043d \u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d \u043e\u0448\u043d\u043e\u0435 \u043d\u0430\u0434\u043e\u0440\u0430\u0434.\n\u0411\u0430\u0434-\u0438\u043d \u043c\u043e\u04b3\u0438 \u0437\u0430\u0440\u0440\u0438\u043d-\u0448 \u0434\u0430\u0440 \u0445\u0430\u0439\u043c\u0430 \u043c\u0430\u043d\u0433\u0430\u0440,\n\u041a\u0438 \u0434\u0430\u0440 \u0430\u043d\u0434\u0430\u0440\u0443\u043d \u0431\u04ef\u0440\u0438\u0451\u0435 \u043d\u0430\u0434\u043e\u0440\u0430\u0434.\n\u0411\u0430 \u0443\u043c\u0440\u0435 \u0430\u0437 \u043e\u043d \u0445\u0438\u043b\u0432\u0430\u0442\u0435 \u0434\u0430\u0441\u0442 \u043d\u0430\u0434\u04b3\u0430\u0434,\n\u041a\u0438 \u0431\u0435\u0440\u0443\u043d \u0430\u0437 \u0438\u043d \u0445\u0430\u0439\u043c\u0430 \u04b7\u043e\u0435 \u043d\u0430\u0434\u043e\u0440\u0430\u0434.\n\u0411\u0430 \u043d\u043e\u0434\u0438\u0440 \u0430\u0433\u0430\u0440 \u0431\u043e\u0437\u0438\u0438 \u0440\u043e\u0441\u0442 \u0431\u043e\u0437\u0430\u0434,\n\u041d\u0430\u0431\u043e\u0448\u0430\u0434, \u043a\u0438 \u0431\u043e \u043e\u043d \u0434\u0430\u0493\u043e\u0435 \u043d\u0430\u0434\u043e\u0440\u0430\u0434.\n\u041d\u0430\u0451\u044f\u0434 \u0431\u0430 \u0441\u0430\u043d\u0433\u0435-\u0434\u0430\u0440 \u0430\u043d\u0433\u0443\u0448\u0442\u0438 \u043f\u043e\u0435,\n\u041a\u0438 \u0442\u043e \u04ef \u0434\u0430\u0440 \u04ef \u0434\u0430\u0441\u0442\u0443 \u043f\u043e\u0435 \u043d\u0430\u0434\u043e\u0440\u0430\u0434.\n\u0411\u0430 \u043c\u0430\u0448\u044a\u0443\u049b \u043d\u0430\u0442\u0432\u043e\u043d \u0433\u0438\u0440\u0438\u0444\u0442\u0430\u043d \u043a\u0430\u0441\u0435\u0440\u043e,\n\u041a\u0438 \u0442\u043e \u04ef\u0441\u0442 \u0431\u043e \u043a\u0430\u0441, \u0432\u0430\u0444\u043e\u0435 \u043d\u0430\u0434\u043e\u0440\u0430\u0434.\n\u0411\u0438\u043a\u0430\u0448, \u0410\u043d\u0432\u0430\u0440\u04e3, \u0434\u0430\u0441\u0442 \u0430\u0437 \u0445\u043e\u043d\u0438 \u0433\u0435\u0442\u04e3,\n\u0427\u0443\u043d\u0438\u043d \u0447\u0430\u0440\u0431\u0443 \u0448\u0438\u0440\u0438\u043d \u0430\u0431\u043e\u0435 \u043d\u0430\u0434\u043e\u0440\u0430\u0434.")
