B.ak4=new A.a("1dea2524-aa1b-49e0-b3d3-a55e2d1cbeae","e8ec4440-682a-48f1-ba59-54d8a9595c16","\u0428\u043e\u0438\u0440\u0438 \u043c\u0443\u0444\u043b\u0438\u049b \u043c\u0430\u043d\u0430\u043c, \u0445\u043e\u043d\u0438 \u043c\u0430\u043e\u043d\u04e3...","\u0428\u043e\u0438\u0440\u0438 \u043c\u0443\u0444\u043b\u0438\u049b \u043c\u0430\u043d\u0430\u043c, \u0445\u043e\u043d\u0438 \u043c\u0430\u043e\u043d\u04e3 \u043c\u0430\u0440\u043e\u0441\u0442,\n\u0420\u0435\u0437\u0430\u0445\u0443\u0440\u0438 \u0445\u043e\u043d\u0438 \u043c\u0430\u043d \u0423\u043d\u0441\u0443\u0440\u0438\u044e \u0420\u04ef\u0434\u0430\u043a\u04e3.")
B.a7X=new A.a("6306f319-67ad-4c8b-b5cf-baa43a56a234","e8ec4440-682a-48f1-ba59-54d8a9595c16","\u041c\u0438\u0441\u043a\u0438\u043d \u043f\u0430\u0434\u0430\u0440\u0430\u043c \u0437\u0438 \u04b7\u0430\u0432\u0440\u0438 \u0430\u0439\u0451\u043c","\u041c\u0438\u0441\u043a\u0438\u043d \u043f\u0430\u0434\u0430\u0440\u0430\u043c \u0437\u0438 \u04b7\u0430\u0432\u0440\u0438 \u0430\u0439\u0451\u043c\n\u0410\u0444\u043a\u0430\u043d\u0434 \u043c\u0430\u0440\u043e \u0447\u0443 \u0417\u043e\u043b\u0440\u043e \u0421\u043e\u043c.\n\u0421\u0438\u043c\u0443\u0440\u0493 \u043d\u0430\u043c\u0443\u0434 \u04ef \u0447\u0443 \u0434\u0430\u0440\u04b3\u043e\u043b\n\u0414\u0430\u0440 \u0437\u0435\u0440\u0438 \u043f\u0430\u0440\u0430\u043c \u0433\u0438\u0440\u0438\u0444\u0442 \u0447\u0443\u043d \u0417\u043e\u043b.\n\u041e\u0432\u0430\u0440\u0434\u0430 \u0431\u0430 \u043a\u04ef\u04b3\u0438 \u049a\u043e\u0444\u0438 \u0434\u043e\u043d\u0438\u0448,\n\u041f\u0430\u0440\u0432\u0430\u0440\u0434\u0430 \u043c\u0430\u0440\u043e \u0431\u0430 \u043e\u0448\u0451\u043d\u0430\u0448.")
B.a83=new A.a("692fcf7f-b95a-4539-aada-6fd4c64ff970","e8ec4440-682a-48f1-ba59-54d8a9595c16","\u0427\u04e3 \u0441\u0430\u0431\u0430\u0431 \u0441\u04ef\u0439\u0438 \u0425\u0443\u0440\u043e\u0441\u043e\u043d \u0448\u0443\u0434\u0430\u043d\u0430\u043c ...","\u0427\u04e3 \u0441\u0430\u0431\u0430\u0431 \u0441\u04ef\u0439\u0438 \u0425\u0443\u0440\u043e\u0441\u043e\u043d \u0448\u0443\u0434\u0430\u043d\u0430\u043c \u043d\u0430\u0433\u0437\u043e\u0440\u0430\u043d\u0434?\n\u0410\u043d\u0434\u0430\u043b\u0435\u0431\u0430\u043c, \u0431\u0430 \u0433\u0443\u043b\u0438\u0441\u0442\u043e\u043d \u0448\u0443\u0434\u0430\u043d\u0430\u043c \u043d\u0430\u0433\u0437\u043e\u0440\u0430\u043d\u0434?\n\u041d\u0435\u0441\u0442 \u0431\u0443\u0441\u0442\u043e\u043d\u0438 \u0425\u0443\u0440\u043e\u0441\u043e\u043d\u0440\u043e \u0447\u0443\u043d \u043c\u0430\u043d \u043c\u0443\u0440\u0493\u0435,\n\u041c\u0443\u0440\u0493\u0430\u043c, \u043e\u0432\u0430\u0445, \u0441\u0443\u0439\u0438 \u0431\u0443\u0441\u0442\u043e\u043d \u0448\u0443\u0434\u0430\u043d\u0430\u043c \u043d\u0430\u0433\u0437\u043e\u0440\u0430\u043d\u0434...\n\u0410\u0437 \u0445\u0443\u0440\u04ef\u0441\u043e\u043d\u0438 \u0425\u0443\u0440\u043e\u0441\u043e\u043d \u0447\u0443 \u043c\u0430\u043d\u0435 \u043d\u0435\u0441\u0442, \u0447\u04e3 \u0441\u0443\u0434,\n\u041a\u0438 \u0433\u0430\u04b3\u0438 \u0441\u0443\u0431\u04b3 \u0445\u0443\u0440\u04ef\u0448\u043e\u043d \u0448\u0443\u0434\u0430\u043d\u0430\u043c \u043d\u0430\u0433\u0437\u043e\u0440\u0430\u043d\u0434...\n\u0414\u0430\u0440\u0434\u0438 \u0434\u0438\u043b \u0434\u043e\u0440\u0430\u043c\u0443 \u0434\u0430\u0440\u043c\u043e\u043d-\u0448 \u0425\u0443\u0440\u043e\u0441\u043e\u043d, \u0437\u0438 \u0441\u0430\u0440\u043e\u043d\n\u0427\u0443\u043d \u0441\u0430\u0437\u0430\u0434, \u043a-\u0430\u0437 \u043f\u0430\u0439\u0438 \u0434\u0430\u0440\u043c\u043e\u043d \u0448\u0443\u0434\u0430\u043d\u0430\u043c \u043d\u0430\u0433\u0437\u043e\u0440\u0430\u043d\u0434...\n\u0424\u0438\u0442\u043d\u0430 \u0430\u0437 \u043c\u0430\u043d \u0447\u04e3 \u043d\u0430\u0432\u0438\u0441\u0430\u0434, \u043a\u0438 \u043c\u0430\u0440\u043e \u0434\u043e\u043d\u0438\u0448\u0443 \u0434\u0438\u043d\n\u0414\u0443 \u0440\u0430\u049b\u0438\u0431\u0430\u043d\u0434, \u043a\u0438 \u0444\u0430\u0442\u0442\u043e\u043d \u0448\u0443\u0434\u0430\u043d\u0430\u043c \u043d\u0430\u0433\u0437\u043e\u0440\u0430\u043d\u0434.\n\u0422\u0430\u0440\u0441\u0438 \u04b7\u043e\u04b3\u0443 \u0493\u0430\u043c\u0438 \u04b7\u043e\u043d \u0434\u043e\u0440\u0430\u043c\u0443 \u0437-\u0438\u043d \u04b3\u0430\u0440 \u0434\u0443 \u0441\u0430\u0431\u0430\u0431\n\u0411\u0430 \u0425\u0443\u0440\u043e\u0441\u043e\u043d \u0441\u0443\u0439\u0438 \u0438\u0445\u0432\u043e\u043d \u0448\u0443\u0434\u0430\u043d\u0430\u043c \u043d\u0430\u0433\u0437\u043e\u0440\u0430\u043d\u0434.")
B.adA=new A.a("104a8a34-c3a1-4786-a8f8-dd8b1934a153","e8ec4440-682a-48f1-ba59-54d8a9595c16","\u0425\u043e\u049b\u043e\u043d\u0438\u0451, \u0437\u0438 \u043c\u0438\u0434\u04b3\u0430\u0442\u0438 \u0448\u043e\u04b3\u043e\u043d \u043a\u0430\u0440\u043e...","\u0425\u043e\u049b\u043e\u043d\u0438\u0451, \u0437\u0438 \u043c\u0438\u0434\u04b3\u0430\u0442\u0438 \u0448\u043e\u04b3\u043e\u043d \u043a\u0430\u0440\u043e\u043d \u0442\u0430\u043b\u0430\u0431,\n\u0422\u043e \u0430\u0437 \u043c\u0438\u0451\u043d\u0438 \u043c\u0430\u0432\u04b7\u0438 \u0441\u0438\u0451\u0441\u0430\u0442 \u0431\u0443\u0440\u0443\u043d \u0448\u0430\u0432\u04e3!")
B.afW=new A.a("985c6671-dda6-4f68-8bd9-b54c25bb9afe","e8ec4440-682a-48f1-ba59-54d8a9595c16","\u04b2\u043e\u043d, \u044d\u0439 \u0434\u0438\u043b\u0438 \u0438\u0431\u0440\u0430\u0442\u0431\u0438\u043d, \u0430\u0437 \u0434\u0438\u0434\u0430...","\u04b2\u043e\u043d, \u044d\u0439 \u0434\u0438\u043b\u0438 \u0438\u0431\u0440\u0430\u0442\u0431\u0438\u043d, \u0430\u0437 \u0434\u0438\u0434\u0430 \u043d\u0430\u0437\u0430\u0440 \u043a\u0443\u043d, \u04b3\u043e\u043d,\n\u0410\u0439\u0432\u043e\u043d\u0438 \u041c\u0430\u0434\u043e\u0438\u043d\u0440\u043e \u043e\u0438\u043d\u0430\u0438 \u0438\u0431\u0440\u0430\u0442 \u0434\u043e\u043d.")
B.a7g=new A.a("cf7bf443-c331-4e64-a9bb-1891dfa25bb3","e8ec4440-682a-48f1-ba59-54d8a9595c16","\u042f\u043a \u0440\u0430\u04b3 \u0437\u0438 \u0440\u0430\u04b3\u0438 \u0414\u0430\u04b7\u043b\u0430 \u043c\u0430\u043d\u0437\u0438\u043b \u0431\u0430...","\u042f\u043a \u0440\u0430\u04b3 \u0437\u0438 \u0440\u0430\u04b3\u0438 \u0414\u0430\u04b7\u043b\u0430 \u043c\u0430\u043d\u0437\u0438\u043b \u0431\u0430 \u041c\u0430\u0434\u043e\u0438\u043d \u043a\u0443\u043d\n\u0412-\u0430\u0437 \u0434\u0438\u0434\u0430 \u0434\u0443\u0432\u0443\u043c \u0414\u0430\u04b7\u043b\u0430 \u0431\u0430\u0440 \u0445\u043e\u043a\u0438 \u041c\u0430\u0434\u043e\u0438\u043d \u0440\u043e\u043d!\n\u0425\u0443\u0434 \u0414\u0430\u04b7\u043b\u0430 \u0447\u0443\u043d\u043e\u043d \u0433\u0438\u0440\u044f\u0434, \u0441\u0430\u0434 \u0414\u0430\u04b7\u043b\u0430\u0438 \u0445\u0443\u043d \u0433\u04ef\u0439\u04e3,\n\u041a-\u0430\u0437 \u0433\u0430\u0440\u043c\u0438\u0438 \u0445\u0443\u043d\u043e\u0431\u0430\u0448 \u043e\u0442\u0430\u0448 \u0447\u0430\u043a\u0430\u0434 \u0430\u0437 \u043c\u0438\u0436\u0433\u043e\u043d.\n\u0411\u0438\u043d\u04e3, \u043a\u0438 \u043b\u0430\u0431\u0438 \u0414\u0430\u04b7\u043b\u0430 \u0447\u0443\u043d \u043a\u0430\u0444 \u0431\u0430 \u0434\u0430\u04b3\u043e\u043d \u043e\u0440\u0430\u0434?\n\u0413\u04ef\u0451 \u0437\u0438 \u0442\u0430\u0444\u0438 \u043e\u04b3\u0430\u0448 \u043b\u0430\u0431 \u043e\u0431\u0438\u043b\u0430 \u0437\u0430\u0434 \u0447\u0430\u043d\u0434\u043e\u043d.\n\u0410\u0437 \u043e\u0442\u0430\u0448\u0438 \u04b3\u0430\u0441\u0440\u0430\u0442 \u0431\u0438\u043d \u0431\u0438\u0440\u0451\u043d \u04b7\u0438\u0433\u0430\u0440\u0438 \u0414\u0430\u04b7\u043b\u0430,\n\u0425\u0443\u0434 \u043e\u0431 \u0448\u0443\u043d\u0438\u0434\u0430\u0441\u0442\u04e3, \u043a-\u043e\u0442\u0430\u0448 \u043a\u0443\u043d\u0430\u0434\u0430\u0448 \u0431\u0438\u0440\u0451\u043d?\n\u0411\u0430\u0440 \u0414\u0430\u04b7\u043b\u0430 \u0433\u0438\u0440\u04e3 \u043d\u0430\u0432-\u043d\u0430\u0432 \u0432-\u0430\u0437 \u0434\u0438\u0434\u0430 \u0437\u0430\u043a\u043e\u0442\u0430\u0448 \u0434\u0435\u04b3,\n\u0413\u0430\u0440\u0447\u0438 \u043b\u0430\u0431\u0438 \u0434\u0430\u0440\u0451 \u04b3\u0430\u0441\u0442 \u0430\u0437 \u0414\u0430\u04b7\u043b\u0430 \u0437\u0430\u043a\u043e\u0442\u0438\u0441\u0442\u043e\u043d.\n\u0413\u0430\u0440 \u0414\u0430\u04b7\u043b\u0430 \u0434\u0430\u0440\u043e\u043c\u0435\u0437\u0430\u0434, \u0431\u043e\u0434\u0438 \u043b\u0430\u0431\u0443 \u0441\u04ef\u0437\u0438 \u0434\u0438\u043b\n\u041d\u0438\u043c\u0435 \u0448\u0430\u0432\u0430\u0434 \u0430\u0444\u0441\u0443\u0440\u0434\u0430, \u043d\u0438\u043c\u0435 \u0448\u0430\u0432\u0430\u0434 \u043e\u0442\u0430\u0448\u0434\u043e\u043d.\n\u0422\u043e \u0441\u0438\u043b\u0441\u0438\u043b\u0430\u0438 \u0430\u0439\u0432\u043e\u043d \u0431\u0438\u0433\u0441\u0430\u0441\u0442 \u041c\u0430\u0434\u043e\u0438\u043d\u0440\u043e,\n\u0414\u0430\u0440 \u0441\u0438\u043b\u0441\u0438\u043b\u0430 \u0448\u0443\u0434 \u0414\u0430\u04b7\u043b\u0430, \u0447\u0443\u043d \u0441\u0438\u043b\u0441\u0438\u043b\u0430 \u0448\u0443\u0434 \u043f\u0435\u0447\u043e\u043d.\n\u0413\u0430\u04b3-\u0433\u0430\u04b3 \u0431\u0430 \u0437\u0430\u0431\u043e\u043d\u0438 \u0430\u0448\u043a \u043e\u0432\u043e\u0437 \u0434\u0435\u04b3 \u0430\u0439\u0432\u043e\u043d\u0440\u043e,\n\u0422\u043e \u0431\u0443, \u043a\u0438 \u0431\u0430 \u0433\u04ef\u0448\u0438 \u0434\u0438\u043b \u043f\u043e\u0441\u0443\u0445 \u0448\u0443\u043d\u0430\u0432\u04e3 \u0437-\u0430\u0439\u0432\u043e\u043d.")
B.amg=new A.a("f9a492ed-263a-4b6d-a158-c6cc35d8fd83","e8ec4440-682a-48f1-ba59-54d8a9595c16","\u0414\u0430\u043d\u0434\u043e\u043d\u0430\u0438 \u04b3\u0430\u0440 \u049b\u0430\u0441\u0440\u0435 \u043f\u0430\u043d\u0434\u0435 \u0434\u0438\u04b3\u0430\u0434...","\u0414\u0430\u043d\u0434\u043e\u043d\u0430\u0438 \u04b3\u0430\u0440 \u049b\u0430\u0441\u0440\u0435 \u043f\u0430\u043d\u0434\u0435 \u0434\u0438\u04b3\u0430\u0434\u0430\u0442 \u043d\u0430\u0432-\u043d\u0430\u0432,\n\u041f\u0430\u043d\u0434\u0438 \u0441\u0430\u0440\u0438 \u0434\u0430\u043d\u0434\u043e\u043d\u0430 \u0431\u0438\u0448\u043d\u0430\u0432 \u0437\u0438 \u0431\u0443\u043d\u0438 \u0434\u0430\u043d\u0434\u043e\u043d.\n\u0413\u04ef\u044f\u0434, \u043a\u0438 \u0442\u0443 \u0430\u0437 \u0445\u043e\u043a\u04e3, \u043c\u043e \u0445\u043e\u043a\u0438 \u0442\u0443\u0435\u043c \u0430\u043a\u043d\u0443\u043d,\n\u0413\u043e\u043c\u0435 \u0434\u0443-\u0441\u0435 \u0431\u0430\u0440 \u043c\u043e \u043d\u0435\u04b3 \u0432-\u0430\u0448\u043a\u0435 \u0434\u0443-\u0441\u0435 \u04b3\u0430\u043c \u0431\u0438\u0444\u0448\u043e\u043d.\n\u0410\u0437 \u043d\u0430\u0432\u04b3\u0430\u0438 \u04b7\u0443\u0493\u0434 \u0430\u043b\u04b3\u0430\u049b  \u043c\u043e\u0435\u043c \u0431\u0430 \u0434\u0430\u0440\u0434\u0438 \u0441\u0430\u0440,\n\u0410\u0437 \u0434\u0438\u0434\u0430 \u0433\u0443\u043b\u043e\u0431\u0435 \u043a\u0443\u043d, \u0434\u0430\u0440\u0434\u0438 \u0441\u0430\u0440\u0438 \u043c\u043e \u0431\u0438\u043d\u0448\u043e\u043d.\n\u041e\u0440\u0435, \u043a\u0438 \u0430\u04b7\u0430\u0431 \u0434\u043e\u0440\u04e3, \u043a-\u0430\u043d\u0434\u0430\u0440 \u0447\u0430\u043c\u0430\u043d\u0438 \u0433\u0435\u0442\u04e3\n\u04b6\u0443\u0493\u0434 \u0430\u0441\u0442 \u043f\u0430\u0439\u0438 \u0431\u0443\u043b\u0431\u0443\u043b, \u043d\u0430\u0432\u04b3\u0430-\u0441\u0442 \u043f\u0430\u0439\u0438 \u0430\u043b\u04b3\u043e\u043d.\n\u041c\u043e \u0431\u043e\u0440\u0433\u0430\u04b3\u0438 \u0434\u043e\u0434\u0435\u043c, \u0438\u043d \u0440\u0430\u0444\u0442 \u0441\u0438\u0442\u0430\u043c \u0431\u0430\u0440 \u043c\u043e,\n\u0411\u0430\u0440 \u049b\u0430\u0441\u0440\u0438 \u0441\u0438\u0442\u0430\u043c\u043a\u043e\u0440\u043e\u043d \u0442\u043e \u0445\u0443\u0434 \u0447\u04e3 \u0440\u0430\u0441\u0430\u0434 \u0445\u0430\u0437\u043b\u043e\u043d.\n\u0413\u04ef\u0439\u04e3 \u043a\u04e3 \u043d\u0438\u0433\u0443\u043d \u043a\u0430\u0440\u0434\u0430\u0441\u0442 \u0430\u0439\u0432\u043e\u043d\u0438 \u0444\u0430\u043b\u0430\u043a\u0432\u0430\u0448\u0440\u043e,\n\u04b2\u0443\u043a\u043c\u0438 \u0444\u0430\u043b\u0430\u043a\u0438 \u0433\u0430\u0440\u0434\u043e\u043d \u0451 \u04b3\u0443\u043a\u043c\u0438 \u0444\u0430\u043b\u0430\u043a\u0433\u0430\u0440\u0434\u043e\u043d.\n\u0411\u0430\u0440 \u0434\u0438\u0434\u0430\u0438 \u043c\u043e \u0445\u0430\u043d\u0434\u04e3, \u043a-\u043e\u043d \u04b7\u043e \u0437\u0438 \u0447\u04e3 \u043c\u0435\u0433\u0438\u0440\u044f\u0434?\n\u0413\u0438\u0440\u044f\u043d\u0434 \u0431\u0430\u0440 \u043e\u043d \u0434\u0438\u0434\u0430, \u043a-\u0438\u043d \u04b7\u043e \u043d\u0430\u0448\u0430\u0432\u0430\u0434 \u0433\u0438\u0440\u0451\u043d.")
B.acq=new A.a("d10f8e51-6937-4fce-ab47-5c74e881f4ed","e8ec4440-682a-48f1-ba59-54d8a9595c16","\u041d\u0435 \u0437\u043e\u043b\u0438 \u041c\u0430\u0434\u043e\u0438\u043d \u043a\u0430\u043c \u0430\u0437 \u043f\u0438\u0440\u0437\u0430\u043d\u0438 ...","\u041d\u0435 \u0437\u043e\u043b\u0438 \u041c\u0430\u0434\u043e\u0438\u043d \u043a\u0430\u043c \u0430\u0437 \u043f\u0438\u0440\u0437\u0430\u043d\u0438 \u041a\u0443\u0444\u0430,\n\u041d\u0430 \u04b3\u0443\u04b7\u0440\u0430\u0438 \u0442\u0430\u043d\u0433\u0438 \u0438\u043d \u043a\u0430\u043c\u0442\u0430\u0440 \u0437\u0438 \u0442\u0430\u043d\u04ef\u0440\u0438 \u043e\u043d.\n\u0414\u043e\u043d\u04e3 \u0447\u04e3? \u041c\u0430\u0434\u043e\u0438\u043d\u0440\u043e \u0431\u043e \u041a\u0443\u0444\u0430 \u0431\u0430\u0440\u043e\u0431\u0430\u0440 \u043d\u0435\u04b3,\n\u0410\u0437 \u0441\u0438\u043d\u0430 \u0442\u0430\u043d\u04ef\u0440\u0435 \u043a\u0443\u043d \u0432-\u0430\u0437 \u0434\u0438\u0434\u0430 \u0442\u0430\u043b\u0430\u0431 \u0442\u04ef\u0444\u043e\u043d!")
B.a99=new A.a("46883a10-fe1f-46a0-a174-46aabb1e72b8","e8ec4440-682a-48f1-ba59-54d8a9595c16","\u0418\u043d \u0430\u0441\u0442 \u04b3\u0430\u043c\u043e\u043d \u0430\u0439\u0432\u043e\u043d, \u043a-\u0430\u0448 \u043d\u0430\u049b\u0448\u0438...","\u0418\u043d \u0430\u0441\u0442 \u04b3\u0430\u043c\u043e\u043d \u0430\u0439\u0432\u043e\u043d, \u043a-\u0430\u0448 \u043d\u0430\u049b\u0448\u0438 \u0440\u0443\u0445\u0438 \u043c\u0430\u0440\u0434\u0443\u043c\n\u0425\u043e\u043a\u0438 \u0434\u0430\u0440\u0438 \u04ef \u0431\u0443\u0434\u04e3 \u0434\u0435\u0432\u043e\u0440\u0438 \u041d\u0438\u0433\u043e\u0440\u0438\u0441\u0442\u043e\u043d.\n\u0418\u043d \u04b3\u0430\u0441\u0442 \u04b3\u0430\u043c\u043e\u043d \u0434\u0430\u0440\u0433\u0430\u04b3, \u043a-\u04ef\u0440\u043e \u0437\u0438 \u0448\u0430\u04b3\u043e\u043d \u0431\u0443\u0434\u04e3\n\u0414\u0430\u0439\u043b\u0430\u043c \u043c\u0430\u043b\u0438\u043a\u0438 \u0411\u043e\u0431\u0438\u043b, \u04b3\u0438\u043d\u0434\u0443 \u0448\u0430\u04b3\u0438 \u0422\u0443\u0440\u043a\u0438\u0441\u0442\u043e\u043d.\n\u0418\u043d \u04b3\u0430\u0441\u0442 \u04b3\u0430\u043c\u043e\u043d \u0441\u0443\u0444\u0444\u0430, \u043a-\u0430\u0437 \u04b3\u0430\u0439\u0431\u0430\u0442\u0438 \u04ef \u0431\u0443\u0440\u0434\u04e3\n\u0411\u0430\u0440 \u0448\u0435\u0440\u0438 \u0444\u0430\u043b\u0430\u043a \u04b3\u0430\u043c\u043b\u0430 \u0448\u0435\u0440\u0438\u0442\u0430\u043d\u0438 \u0448\u043e\u0434\u0443\u0440\u0432\u043e\u043d.\n\u041f\u0438\u043d\u0434\u043e\u0440 \u04b3\u0430\u043c\u043e\u043d \u0430\u04b3\u0434 \u0430\u0441\u0442, \u0430\u0437 \u0434\u0438\u0434\u0430\u0438 \u0444\u0438\u043a\u0440\u0430\u0442 \u0431\u0438\u043d\n\u0414\u0430\u0440 \u0441\u0438\u043b\u0441\u0438\u043b\u0430\u0438 \u0434\u0430\u0440\u0433\u0430\u04b3, \u0434\u0430\u0440 \u043a\u0430\u0432\u043a\u0430\u0431\u0430\u0438 \u043c\u0430\u0439\u0434\u043e\u043d.\n\u0410\u0437 \u0430\u0441\u043f \u043f\u0438\u0451\u0434\u0430 \u0448\u0430\u0432, \u0431\u0430\u0440 \u043d\u0430\u044a\u0442\u0438 \u0437\u0430\u043c\u0438\u043d \u0440\u0443\u0445 \u043d\u0435\u04b3,\n\u0417\u0435\u0440\u0438 \u043f\u0430\u0439\u0438 \u043f\u0438\u043b\u0430\u0448 \u0431\u0438\u043d, \u0448\u0430\u04b3\u043c\u043e\u0442 \u0448\u0443\u0434\u0430 \u041d\u0443\u044a\u043c\u043e\u043d.\n\u041d\u0435, \u043d\u0435, \u043a\u0438 \u0447\u0443 \u041d\u0443\u044a\u043c\u043e\u043d \u0431\u0438\u043d \u2013 \u043f\u0438\u043b\u0430\u0444\u043a\u0430\u043d\u0438 \u0448\u043e\u04b3\u043e\u043d\u0440\u043e,\n\u041f\u0438\u043b\u043e\u043d\u0438 \u0448\u0430\u0431\u0443 \u0440\u04ef\u0437\u0430\u0448 \u0433\u0430\u0448\u0442\u0430 \u0431\u0430 \u043f\u0430\u0439\u0438 \u0434\u0430\u0432\u0440\u043e\u043d.\n\u042d\u0439 \u0448\u0430\u04b3, \u043f\u0430\u0441\u0438 \u043f\u0438\u043b \u0430\u0444\u043a\u0430\u043d, \u043a-\u0430\u0444\u043a\u0430\u043d\u0434\u0430 \u0431\u0430 \u0448\u0430\u04b3 \u043f\u0438\u043b\u0435,\n\u0428\u0430\u0442\u0440\u0430\u043d\u04b7\u0438\u0438 \u0442\u0430\u049b\u0434\u0438\u0440\u0430\u0448 \u0434\u0430\u0440 \u043c\u043e\u0442\u0433\u0430\u04b3\u0438 \u04b3\u0438\u0440\u043c\u043e\u043d.")
B.abJ=new A.a("6af3aa37-58a0-42e1-8154-47cc8d582235","e8ec4440-682a-48f1-ba59-54d8a9595c16","\u041c\u0430\u0441\u0442 \u0430\u0441\u0442 \u0437\u0430\u043c\u0438\u043d, \u0437\u0435\u0440\u043e \u0445\u04ef\u0440\u0434\u0430\u0441\u0442 \u0431...","\u041c\u0430\u0441\u0442 \u0430\u0441\u0442 \u0437\u0430\u043c\u0438\u043d, \u0437\u0435\u0440\u043e \u0445\u04ef\u0440\u0434\u0430\u0441\u0442 \u0431\u0430 \u04b7\u043e\u0439\u0438 \u043c\u0430\u0439\n\u0414\u0430\u0440 \u043a\u043e\u0441\u0438 \u0441\u0430\u0440\u0438 \u04b2\u0443\u0440\u043c\u0443\u0437 \u0445\u0443\u043d\u0438 \u0434\u0438\u043b\u0438 \u041d\u04ef\u0448\u0438\u0440\u0432\u043e\u043d.\n\u0411\u0430\u0441 \u043f\u0430\u043d\u0434, \u043a\u0438 \u0431\u0443\u0434 \u043e\u043d \u0433\u0430\u04b3 \u0431\u0430\u0440 \u0442\u043e\u04b7\u0438 \u0441\u0430\u0440\u0430\u0448 \u043f\u0430\u0439\u0434\u043e,\n\u0421\u0430\u0434 \u043f\u0430\u043d\u0434\u0438 \u043d\u0430\u0432 \u0430\u0441\u0442 \u0430\u043a\u043d\u0443\u043d \u0434\u0430\u0440 \u043c\u0430\u0493\u0437\u0438 \u0441\u0430\u0440\u0430\u0448 \u043f\u0438\u043d\u04b3\u043e\u043d.\n\u041a\u0438\u0441\u0440\u043e\u0432\u0443 \u0442\u0443\u0440\u0443\u043d\u04b7\u0438 \u0437\u0430\u0440, \u041f\u0430\u0440\u0432\u0438\u0437\u0443 \u0442\u0430\u0440\u0430\u0439 \u0437\u0430\u0440\u0440\u0438\u043d\n\u0411\u0430\u0440 \u0431\u043e\u0434 \u0448\u0443\u0434\u0430 \u044f\u043a\u0441\u0430\u0440, \u0431\u0430\u0440 \u0445\u043e\u043a \u0448\u0443\u0434\u0430 \u044f\u043a\u0441\u043e\u043d.\n\u041f\u0430\u0440\u0432\u0438\u0437 \u0431\u0430 \u04b3\u0430\u0440 \u0445\u043e\u043d\u0435 \u0437\u0430\u0440\u0440\u0438\u043d\u0442\u0430\u0440\u0430 \u0433\u0443\u0441\u0442\u0430\u0440\u0434\u04e3,\n\u041a\u0430\u0440\u0434\u04e3 \u0437\u0438 \u0431\u0438\u0441\u043e\u0442\u0438 \u0437\u0430\u0440 \u0437\u0430\u0440\u0440\u0438\u043d\u0442\u0430\u0440\u0430\u0440\u043e \u0431\u0443\u0441\u0442\u043e\u043d.\n\u041f\u0430\u0440\u0432\u0438\u0437 \u043a\u0443\u043d\u0443\u043d \u0433\u0443\u043c \u0448\u0443\u0434, \u0437-\u043e\u043d \u0433\u0443\u043c\u0448\u0443\u0434\u0430 \u043a\u0430\u043c\u0442\u0430\u0440 \u0433\u04ef,\n\u0417\u0430\u0440\u0440\u0438\u043d\u0442\u0430\u0440\u0430 \u043a\u0443 \u0431\u0430\u0440 \u0445\u043e\u043d, \u0440\u0430\u0432, \u043a\u0430\u043c \u0442\u0430\u0440\u0430\u043a\u0443 \u0431\u0430\u0440\u0445\u043e\u043d!\n\u0413\u0443\u0444\u0442\u04e3, \u043a\u0438 \u043a\u0443\u04b7\u043e \u0440\u0430\u0444\u0442\u0430\u043d\u0434 \u043e\u043d \u0442\u043e\u04b7\u0432\u0430\u0440\u043e\u043d \u0438\u043d\u0430\u043a,\n\u0417-\u044d\u0448\u043e\u043d \u0448\u0438\u043a\u0430\u043c\u0438 \u0445\u043e\u043a \u0430\u0441\u0442 \u043e\u0431\u0438\u0441\u0442\u0430\u043d\u0438 \u04b7\u043e\u0432\u0438\u0434\u043e\u043d.\n\u0411\u0430\u0441 \u0434\u0435\u0440 \u04b3\u0430\u043c\u0435\u0437\u043e\u044f\u0434 \u043e\u0431\u0438\u0441\u0442\u0430\u043d\u0438 \u0445\u043e\u043a, \u043e\u0440\u0435,\n\u0414\u0443\u0448\u0432\u043e\u0440 \u0431\u0443\u0432\u0430\u0434 \u0437\u043e\u0434\u0430\u043d, \u043d\u0443\u0442\u0444\u0430 \u0441\u0438\u0442\u0430\u0434\u0430\u043d \u043e\u0441\u043e\u043d.\n\u0425\u0443\u043d\u0438 \u0434\u0438\u043b\u0438 \u0428\u0438\u0440\u0438\u043d \u0430\u0441\u0442 \u043e\u043d \u043c\u0430\u0439, \u043a\u0438 \u0434\u0438\u04b3\u0430\u0434 \u0440\u0430\u0437\u0431\u0443\u043d,\n\u0417-\u043e\u0431\u0443 \u0433\u0438\u043b\u0438 \u041f\u0430\u0440\u0432\u0438\u0437 \u0430\u0441\u0442 \u0438\u043d \u0445\u0443\u043c, \u043a\u0438 \u043d\u0438\u04b3\u0430\u0434 \u0434\u0435\u04b3\u049b\u043e\u043d.\n\u0427\u0430\u043d\u0434\u0438\u043d \u0442\u0430\u043d\u0438 \u04b7\u0430\u0431\u0431\u043e\u0440\u043e\u043d, \u043a-\u0438\u043d \u0445\u043e\u043a \u0444\u0443\u0440\u04ef \u0445\u04ef\u0440\u0434\u0430\u0441\u0442,\n\u0418\u043d \u0433\u0443\u0440\u0441\u0443\u043d\u0430\u0447\u0430\u0448\u043c \u043e\u0445\u0438\u0440 \u04b3\u0430\u043c \u0441\u0435\u0440 \u043d\u0430\u0448\u0443\u0434 \u0437-\u044d\u0448\u043e\u043d.\n\u0410\u0437 \u0445\u0443\u043d\u0438 \u0434\u0438\u043b\u0438 \u0442\u0438\u0444\u043b\u043e\u043d \u0441\u0443\u0440\u0445\u043e\u0431\u0438 \u0440\u0443\u0445 \u043e\u043c\u0435\u0437\u0430\u0434\n\u0418\u043d \u0437\u043e\u043b\u0438 \u0441\u0430\u043f\u0435\u0434\u0430\u0431\u0440\u04ef \u0432-\u0438\u043d \u043c\u043e\u043c\u0438 \u0441\u0438\u044f\u04b3\u043f\u0438\u0441\u0442\u043e\u043d.")
B.akn=new A.a("74334dce-3b4c-4cf3-8b77-db510352985d","e8ec4440-682a-48f1-ba59-54d8a9595c16","\u0425\u043e\u049b\u043e\u043d\u04e3, \u0430\u0437 \u0438\u043d \u0434\u0430\u0440\u0433\u0430\u04b3 \u0434\u0430\u0440\u044e\u0437\u0430\u0438 \u0438...","\u0425\u043e\u049b\u043e\u043d\u04e3, \u0430\u0437 \u0438\u043d \u0434\u0430\u0440\u0433\u0430\u04b3 \u0434\u0430\u0440\u044e\u0437\u0430\u0438 \u0438\u0431\u0440\u0430\u0442 \u043a\u0443\u043d,\n\u0422\u043e \u0430\u0437 \u0434\u0430\u0440\u0438 \u0442\u0443 \u0437-\u0438\u043d \u043f\u0430\u0441 \u0434\u0430\u0440\u044e\u0437\u0430 \u043a\u0443\u043d\u0430\u0434 \u0445\u043e\u049b\u043e\u043d.\n\u0418\u043c\u0440\u04ef\u0437 \u0433\u0430\u0440 \u0430\u0437 \u0441\u0443\u043b\u0442\u043e\u043d \u0440\u0438\u043d\u0434\u0435 \u0442\u0430\u043b\u0430\u0431\u0430\u0434 \u0442\u04ef\u0448\u0430,\n\u0424\u0430\u0440\u0434\u043e \u0437\u0438 \u0434\u0430\u0440\u0438 \u0440\u0438\u043d\u0434\u0435 \u0442\u04ef\u0448\u0430 \u0442\u0430\u043b\u0430\u0431\u0430\u0434 \u0441\u0443\u043b\u0442\u043e\u043d.\n\u0413\u0430\u0440 \u0437\u043e\u0434\u0438 \u0440\u0430\u04b3\u0438 \u041c\u0430\u043a\u043a\u0430 \u0442\u0443\u04b3\u0444\u0430-\u0441\u0442 \u0431\u0430 \u04b3\u0430\u0440 \u0448\u0430\u04b3\u0440\u0435,\n\u0422\u0443 \u0437\u043e\u0434\u0438 \u041c\u0430\u0434\u043e\u0438\u043d \u0431\u0430\u0440 \u0442\u0443\u04b3\u0444\u0430 \u0437\u0438 \u043f\u0430\u0439\u0438 \u0428\u0430\u0440\u0432\u043e\u043d.\n\u04b2\u0430\u0440 \u043a\u0430\u0441 \u0431\u0430\u0440\u0430\u0434 \u0430\u0437 \u041c\u0430\u043a\u043a\u0430 \u0441\u0443\u0431\u04b3\u0430 \u0437\u0438 \u0433\u0438\u043b\u0438 \u04b2\u0430\u043c\u0437\u0430,\n\u041f\u0430\u0441, \u0442\u0443 \u0437\u0438 \u041c\u0430\u0434\u043e\u0438\u043d \u0431\u0430\u0440 \u0441\u0443\u0431\u04b3\u0430 \u0437\u0438 \u0433\u0438\u043b\u0438 \u0421\u0430\u043b\u043c\u043e\u043d.\n\u0418\u043d \u0431\u0430\u04b3\u0440\u0438 \u0431\u0430\u0441\u0438\u0440\u0430\u0442 \u0431\u0438\u043d, \u0431\u0435 \u0448\u0430\u0440\u0431\u0430\u0442 \u0430\u0437 \u04ef \u043c\u0430\u0433\u0437\u0430\u0440,\n\u041a-\u0430\u0437 \u0448\u0430\u0442\u0442\u0438 \u0447\u0443\u043d\u0438\u043d \u0431\u0430\u04b3\u0440\u0435 \u043b\u0430\u0431\u0442\u0430\u0448\u043d\u0430 \u0448\u0443\u0434\u0430\u043d \u043d\u0430\u0442\u0432\u043e\u043d.\n\u0418\u0445\u0432\u043e\u043d, \u043a\u0438 \u0437\u0438 \u0440\u0430\u04b3 \u043e\u044f\u043d\u0434, \u043e\u0440\u0430\u043d\u0434 \u0440\u0430\u04b3\u043e\u0432\u0430\u0440\u0434\u0435,\n\u0418\u043d \u049b\u0438\u0442\u044a\u0430 \u0440\u0430\u04b3\u043e\u0432\u0430\u0440\u0434 \u0430\u0441\u0442 \u0430\u0437 \u0431\u0430\u04b3\u0440\u0438 \u0434\u0438\u043b\u0438 \u0438\u0445\u0432\u043e\u043d.\n\u0411\u0438\u043d\u0433\u0430\u0440, \u043a\u0438 \u0434\u0430\u0440 \u0438\u043d \u049b\u0438\u0442\u044a\u0430 \u0447\u04e3 \u0441\u0435\u04b3\u0440 \u04b3\u0430\u043c\u0435\u0440\u043e\u043d\u0430\u0434\n\u041c\u0430\u04b3\u0442\u0443\u043a\u0438 \u043c\u0443\u0441\u0430\u0431\u0431\u0438\u04b3\u0434\u0438\u043b, \u0434\u0435\u0432\u043e\u043d\u0430\u0438 \u043e\u049b\u0438\u043b\u04b7\u043e\u043d.")
B.a5m=new A.a("ba21f542-d342-47af-980e-95104a086877","d5abab06-07e9-4247-b8a8-f4801b6a5be4","\u04b2\u0430\u043c\u0435\u0433\u0443\u0444\u0442\u0430\u043c, \u043a\u0438 \u0425\u043e\u049b\u043e\u043d\u04e3 \u0434\u0430\u0440\u0435\u0493\u043e\u0433\u04ef...","\u04b2\u0430\u043c\u0435\u0433\u0443\u0444\u0442\u0430\u043c, \u043a\u0438 \u0425\u043e\u049b\u043e\u043d\u04e3 \u0434\u0430\u0440\u0435\u0493\u043e\u0433\u04ef\u0439\u0438 \u043c\u0430\u043d \u0431\u043e\u0448\u0430\u0434,\n\u0414\u0430\u0440\u0435\u0493\u043e, \u043c\u0430\u043d \u0448\u0443\u0434\u0430\u043c \u043e\u0445\u0438\u0440 \u0434\u0430\u0440\u0435\u0493\u043e\u0433\u04ef\u0439\u0438 \u0425\u043e\u049b\u043e\u043d\u04e3.")
B.LD=new A.dC()
B.aLs=s([B.LD],t.J)
B.acA=new A.a("97c47166-87dc-43cd-9a65-3d11d3195c0d","fd212071-6a30-4b8d-870a-ae784002e8f2","\u0420\u0430\u04b3\u0440\u0430\u0432\u0435, \u0440\u0430\u0432\u0448\u0430\u043d\u0434\u0438\u043b\u0435","\u0420\u0430\u04b3\u0440\u0430\u0432\u0435, \u0440\u0430\u0432\u0448\u0430\u043d\u0434\u0438\u043b\u0435\n\u0430\u0437\n\u0411\u043e\u044f\u0437\u0438\u0434 \u043a\u0430\u0440\u0434 \u043f\u0443\u0440\u0441\u0438\u0448:\n\xab\u041a-\u044d\u0439 \u043c\u0443\u0440\u043e\u0434\u0438 \u04b3\u0430\u0440 \u043c\u0443\u0440\u0438\u0434!\n\u0411\u043e\u0437 \u0433\u04ef, \u043e\u0445\u0438\u0440 \u043a\u0443\u04b7\u043e \u0431\u0438\u0448\u0442\u043e\u0444\u0442\u04e3?\n\u041a-\u0438\u043d \u04b3\u0430\u043c\u0430 \u0433\u0430\u043d\u04b7\u0438 \u0441\u0430\u043e\u0434\u0430\u0442 \u0451\u0444\u0442\u04e3?\xbb.\n\u0413\u0443\u0444\u0442: \xab\u0410\u0437 \u044f\u043a \u049b\u0430\u0442\u0440\u0430 \u0430\u0448\u043a\u0438 \u043c\u043e\u0434\u0430\u0440\u0430\u043c,\n\u0428\u043e\u04b3\u0438\u0434\u0438 \u043c\u0430\u049b\u0441\u0443\u0434 \u043e\u043c\u0430\u0434 \u0434\u0430\u0440 \u0431\u0430\u0440\u0430\u043c.\n\u0413\u0430\u043d\u04b7\u04b3\u043e \u0434\u0430\u0440 \u0434\u0438\u0434\u0430\u0438 \u043d\u0430\u043c\u043d\u043e\u043a\u0438 \u04ef\u0441\u0442,\n\u0418\u043d \u0433\u0443\u04b3\u0430\u0440\u04b3\u043e \u0430\u0448\u043a\u04b3\u043e\u0438 \u043f\u043e\u043a\u0438 \u04ef\u0441\u0442.\n\u0428\u043e\u043c\u04b3\u043e \u0447\u0443\u043d \u0431\u043e\u0437 \u0445\u0443\u0444\u0442\u04e3 \u043c\u043e\u0434\u0430\u0440\u0430\u043c,\n\u0411\u0443\u0434 \u0434\u0430\u0440 \u043f\u043e\u0451\u043d\u0438 \u043f\u043e\u044f\u0448 \u0431\u0438\u0441\u0442\u0430\u0440\u0430\u043c.\n\u0422\u043e \u0434\u0438\u043b\u0438 \u0448\u0430\u0431 \u0434\u043e\u0448\u0442 \u0431\u043e \u043c\u0430\u043d \u0440\u043e\u0437\u04b3\u043e,\n\u0413\u0443\u0444\u0442\u0443\u0433\u04ef\u04b3\u043e, \u049b\u0438\u0441\u0441\u0430\u04b3\u043e, \u043e\u0432\u043e\u0437\u04b3\u043e.\n\u049a\u0438\u0441\u0441\u0430\u04b3\u043e \u0448\u0438\u0440\u0438\u043d\u0442\u0430\u0440 \u0430\u0437 \u0448\u0430\u04b3\u0434\u0443 \u0448\u0430\u043a\u0430\u0440,\n\u041d\u0430\u0493\u043c\u0430\u04b3\u043e\u0438 \u04b7\u043e\u043d\u0431\u0430\u0445\u0448 \u0430\u0437 \u0431\u043e\u0434\u0438 \u0441\u0430\u04b3\u0430\u0440.\n\u041d\u043e\u0433\u0430\u04b3\u043e\u043d \u0448\u043e\u043c\u0435 \u04b3\u0430\u0432\u043e \u0431\u0430\u0441 \u0442\u0438\u0440\u0430 \u0448\u0443\u0434\n,\n\u0411\u0430\u0440\u0444 \u0431\u0430\u0440 \u0448\u0430\u04b3\u0440\u0443 \u0434\u0435\u04b3\u0438 \u043c\u043e \u0447\u0438\u0440\u0430 \u0448\u0443\u0434.\n\u0425\u0443\u043d \u0431\u0430 \u0442\u0430\u043d \u0430\u0437 \u0448\u0438\u0434\u0434\u0430\u0442\u0438 \u0441\u0430\u0440\u043c\u043e \u0444\u0438\u0441\u0443\u0440\u0434\n,\n\u0428\u0443\u044a\u043b\u0430 \u0430\u0437 \u0434\u0430\u043c\u0441\u0430\u0440\u0434\u0438\u0438 \u0430\u0439\u0451\u043c \u043c\u0443\u0440\u0434.\n\u041d\u0438\u043c\u0430\u0448\u0430\u0431 \u0448\u0443\u0434, \u043c\u043e\u0434\u0430\u0440\u0430\u043c \u0430\u0437 \u0445\u043e\u0431 \u0445\u0435\u0441\u0442,\n\u0410\u0437 \u043c\u0430\u043d\u0438 \u0430\u0444\u0441\u0443\u0440\u0434\u0430 \u04b7\u043e\u043c\u0438 \u043e\u0431 \u0445\u043e\u0441\u0442.\n\u0422\u043e \u0433\u0438\u0440\u0438\u0444\u0442\u0430\u043c \u043b\u0430\u0440\u0437-\u043b\u0430\u0440\u0437\u043e\u043d \u04b7\u043e\u043c\u0438 \u043e\u0431,\n\u041c\u043e\u0434\u0430\u0440\u0430\u043c\u0440\u043e \u0431\u043e\u0440\u0438 \u0434\u0438\u0433\u0430\u0440 \u0431\u0443\u0440\u0434\u0430 \u0445\u043e\u0431.\n\u041c\u0430\u043d \u0441\u0438\u0442\u043e\u0434\u0430\u043c \u0445\u0443\u0448\u043a \u0431\u0430\u0440 \u04b7\u043e \u0430\u0437 \u0430\u0434\u0430\u0431,\n\u0427\u0430\u0448\u043c \u0431\u0430\u0440 \u0440\u043e\u04b3, \u04b7\u043e\u043c \u0431\u0430\u0440 \u043a\u0430\u0444, \u04b7\u043e\u043d \u0431\u0430 \u043b\u0430\u0431.\n\u041e\u0431\u0440\u043e \u0430\u0437 \u0444\u0430\u0440\u0442\u0438\n\u0441\u0430\u0440\u0434\u04e3 \u0431\u0430\u0441\u0442 \u044f\u0445,\n\u04b6\u043e\u043c\u0440\u043e \u0431\u043e \u0434\u0430\u0441\u0442\u0438 \u043c\u0430\u043d \u043f\u0430\u0439\u0432\u0430\u0441\u0442 \u044f\u0445.\n\u0421\u0443\u0431\u04b3 \u0448\u0443\u0434, \u0447\u0443\u043d \u0431\u043e\u0440\u0433\u043e\u04b3\u0438 \u0444\u0430\u0439\u0437 \u0431\u043e\u0437,\n\u041c\u043e\u0434\u0430\u0440\u0430\u043c \u0431\u0430\u0440\u0445\u0435\u0441\u0442 \u0430\u0437 \u0431\u0430\u04b3\u0440\u0438 \u043d\u0430\u043c\u043e\u0437,\n\u0414\u0438\u0434 \u0441\u04ef\u0439\u0438 \u043c\u0430\u043d, \u043b\u0430\u0440\u0437\u043e\u043d\u0430\u043c \u0447\u0443 \u0431\u0435\u0434,\n\u0413\u0430\u0448\u0442\u0430\u0430\u043c \u0447\u0443\u043d \u0431\u0430\u0440\u0444 \u0441\u0430\u0440 \u0442\u043e \u043f\u043e \u0441\u0430\u0444\u0435\u0434\xbb.\n\u0413\u0443\u0444\u0442: \xab\u0410\u0439 \u0444\u0430\u0440\u0437\u0430\u043d\u0434 \u0431\u0430\u0440 \u043a\u0430\u0444 \u04b7\u043e\u043c \u0447\u0438\u0441\u0442?\n\u0420\u043e\u0441\u0442 \u0433\u04ef \u0438\u043d \u043b\u0430\u0440\u0437\u0430 \u0431\u0430\u0440 \u0430\u043d\u0434\u043e\u043c \u0447\u0438\u0441\u0442?\n\u0410\u0437 \u0447\u04e3 \u0440\u04ef \u0438\u043d \u04b7\u043e\u043c\u0440\u043e \u0431\u0430\u0440\u0434\u043e\u0448\u0442\u04e3,\n\u0425\u0435\u0448\u0440\u043e \u0434\u0430\u0440 \u0440\u0430\u043d\u04b7\u0443 \u043c\u0435\u04b3\u043d\u0430\u0442 \u0434\u043e\u0448\u0442\u04e3\xbb.\n\u0413\u0443\u0444\u0442\u0430\u043c: \xab\u0410\u0439 \u043c\u043e\u0434\u0430\u0440, \u0445\u0430\u0442\u043e \u0431\u0443\u0434, \u0438\u043d \u043a\u0438 \u043c\u0430\u043d,\n\u041c\u0435\u043d\u0438\u04b3\u043e\u0434\u0430\u043c \u04b7\u043e\u043c \u0431\u0430\u04b3\u0440\u0438 \u0445\u0435\u0448\u0442\u0430\u043d.\n\u0422\u0443 \u0437\u0438 \u043c\u0430\u043d \u0433\u0430\u0440 \u043e\u0431 \u043c\u0435\u043a\u0430\u0440\u0434\u04e3 \u0442\u0430\u043b\u0430\u0431,\n\u0425\u0443\u0444\u0442\u0430 \u043c\u0435\u0434\u0438\u0434\u04e3 \u043c\u0430\u0440\u043e \u0434\u0443\u0440 \u0430\u0437 \u0430\u0434\u0430\u0431\xbb.\n\u041c\u043e\u0434\u0430\u0440 \u0430\u0437 \u0433\u0443\u0444\u0442\u043e\u0440\u0438 \u043c\u0430\u043d \u0431\u0435\u0442\u043e\u0431 \u0448\u0443\u0434,\n\u0414\u0430\u0440 \u043c\u0438\u0451\u043d\u0438 \u0441\u0438\u043d\u0430\u0438 \u0432\u0430\u0439 \u043e\u0431 \u0448\u0443\u0434.\n\u0421\u0430\u0440 \u0437\u0430\u0434 \u043e\u04b3\u0435 \u0430\u0437 \u0434\u0438\u043b\u0438 \u0493\u0430\u043c\u0434\u0438\u0434\u0430\u0430\u0448,\n\u049a\u0430\u0442\u0440\u0430\u0438 \u0430\u0448\u043a\u0435 \u0447\u0430\u043a\u0438\u0434 \u0430\u0437 \u0434\u0438\u0434\u0430\u0430\u0448.\n\u0410\u0448\u043a\u0438 \u043c\u043e\u0434\u0430\u0440 \u0433\u0430\u043d\u04b7\u0438 \u0433\u0430\u0432\u04b3\u0430\u0440\u04b3\u043e \u0448\u0430\u0432\u0430\u0434,\n\u041c\u0430\u0440\u0434 \u0430\u0437 \u043e\u043d \u044f\u043a \u049b\u0430\u0442\u0440\u0430 \u0447\u0443\u043d \u0434\u0430\u0440\u0451 \u0448\u0430\u0432\u0430\u0434.")
B.a9B=new A.a("0c88ff5e-8da5-4a7f-bcc4-62d9445ac54e","fd212071-6a30-4b8d-870a-ae784002e8f2","\u041d\u0443\u0440\u0438 \u0447\u0430\u0448\u043c\u0438 \u0412\u0430\u0442\u0430\u043d, \u044d\u0439 \u0431\u0430\u0447\u0430\u0438 \u0430\u0444\u0493...","\u041d\u0443\u0440\u0438 \u0447\u0430\u0448\u043c\u0438 \u0412\u0430\u0442\u0430\u043d, \u044d\u0439 \u0431\u0430\u0447\u0430\u0438 \u0430\u0444\u0493\u043e\u043d, \u0430\u0444\u0441\u04ef\u0441,\n\u0414\u0438\u043b\u0438 \u043c\u0430\u043d \u0434\u043e\u0493 \u0448\u0443\u0434 \u0430\u0437 \u0434\u0430\u0441\u0442\u0438 \u0442\u0443, \u044d\u0439 \u04b7\u043e\u043d, \u0430\u0444\u0441\u04ef\u0441.\n\u0427\u0430\u043d\u0434 \u0433\u04ef\u044f\u043c, \u0431\u0430 \u0442\u0443 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0438 \u043c\u0443\u0441\u0430\u043b\u043c\u043e\u043d, \u0430\u0444\u0441\u04ef\u0441,\n\u0411\u0430 \u0442\u0443 \u044d\u0439 \u0443\u043d\u0441\u0443\u0440\u0438 \u0430\u0444\u0441\u0443\u0440\u0434\u0430\u0438, \u0431\u0430\u04b7\u043e\u043d \u0430\u0444\u0441\u04ef\u0441.\n\u041a\u0438\u0441\u0442 \u04b7\u0443\u0437 \u0442\u0443, \u043a\u0438 \u043a\u0443\u043d\u0430\u0434 \u0433\u0438\u0440\u044f \u0431\u0430 \u0432\u0430\u0439\u0440\u043e\u043d\u0438\u0438 \u0442\u0443,\n\u041e\u0432\u0430\u04b3\n, \u0430\u0444\u0441\u04ef\u0441 \u0431\u0430 \u0438\u043d \u0440\u04ef\u0437\u0438 \u043f\u0430\u0440\u0435\u0448\u043e\u043d\u0438\u0438 \u0442\u0443.\n\u04b2\u0430\u043c\u0430 \u0431\u0435\u0434\u043e\u0440, \u0442\u0443 \u0434\u0430\u0440 \u0445\u043e\u0431\u0438 \u0433\u0430\u0440\u043e\u043d\u04e3, \u0442\u043e \u043a\u0430\u0439?\n\u0492\u043e\u0444\u0438\u043b \u0430\u0437 \u0441\u0438\u0440\u0440\u0438 \u0442\u0430\u0440\u0430\u049b\u049b\u0438\u0438 \u04b7\u0430\u04b3\u043e\u043d\u04e3, \u0442\u043e \u043a\u0430\u0439?\n\u0427\u0430\u0448\u043c \u0431\u0430\u0440 \u0440\u043e\u04b3\u0438 \u043a\u0430\u043c\u043e\u043b\u0438 \u0434\u0438\u0433\u0430\u0440\u043e\u043d\u04e3, \u0442\u043e \u043a\u0430\u0439?\n\u0422\u0443 \u0431\u0430 \u0438\u043d \u043f\u0430\u0440\u0434\u0430\u0438 \u0442\u043e\u0440\u0438\u043a  \u043f\u0438\u043d\u04b3\u043e\u043d\u04e3, \u0442\u043e \u043a\u0430\u0439?\n\u04b2\u0430\u043b\u0430\n\u0431\u0430\u0440\u0445\u0435\u0437 \u0437\u0438 \u04b7\u043e, \u0493\u0430\u0444\u043b\u0430\u0442\u0438 \u0431\u0435\u04b7\u043e, \u0442\u043e \u043a\u0430\u0439?\n\u0425\u043e\u0431\u0438 \u043d\u04ef\u0448\u0438\u043d \u0447\u04e3 \u049b\u0430\u0434\u0430\u0440, \u043d\u0430\u0448\u044a\u0430\u0438 \u0441\u0430\u04b3\u0431\u043e\n\u0442\u043e \u043a\u0430\u0439?\n\u0410\u0439 \u043f\u0438\u0441\u0430\u0440, \u0447\u0430\u0448\u043c\u0438 \u0412\u0430\u0442\u0430\u043d \u0441\u04ef\u0439\u0438 \u0442\u0443 \u0431\u043e\u0437 \u0430\u0441\u0442, \u04b3\u0430\u043d\u04ef\u0437,\n\u049a\u0430\u0432\u043c\u0440\u043e \u04b7\u043e\u043d\u0438\u0431\u0438 \u0442\u0443 \u0434\u0430\u0441\u0442 \u0434\u0430\u0440\u043e\u0437 \u0430\u0441\u0442, \u04b3\u0430\u043d\u04ef\u0437.\n\u041c\u0430\u043c\u043b\u0430\u043a\u0430\u0442\u0440\u043e \u0431\u0430 \u0442\u0443 \u0441\u0430\u0434 \u0433\u0443\u043d\u0430 \u043d\u0438\u0451\u0437 \u0430\u0441\u0442, \u04b3\u0430\u043d\u04ef\u0437,\n\u0424\u0443\u0440\u0441\u0430\u0442\u0438 \u0445\u0438\u0434\u043c\u0430\u0442\u0438 \u0442\u0443 \u0434\u0443\u0440\u0443 \u0434\u0430\u0440\u043e\u0437 \u0430\u0441\u0442, \u04b3\u0430\u043d\u04ef\u0437.\n\u0412\u0430\u049b\u0442\u0438 \u0431\u043e\u0437\u04e3 \u043d\u0430\u0431\u0443\u0432\u0430\u0434, \u0444\u0443\u0440\u0441\u0430\u0442\u0438 \u043a\u043e\u0440 \u0430\u0441\u0442, \u0431\u0438\u0451!\n\u0410\u0439 \u043f\u0438\u0441\u0430\u0440, \u043a\u043e\u0440 \u043d\u0430\u043a\u0430\u0440\u0434\u0430\u043d \u0431\u0430 \u0442\u0443 \u043e\u0440 \u0430\u0441\u0442, \u0431\u0438\u0451!")
B.adV=new A.a("5f6314ac-e236-45f6-b16d-8217836820b2","fd212071-6a30-4b8d-870a-ae784002e8f2","\u042d\u0439 \u0433\u0443\u043b\u0438 \u043d\u0430\u0432\u0440\u0443\u0441\u0442\u0430\u0438 \u043e\u043c\u043e\u043b\u0438 \u043c\u043e,","\u042d\u0439 \u0433\u0443\u043b\u0438 \u043d\u0430\u0432\u0440\u0443\u0441\u0442\u0430\u0438 \u043e\u043c\u043e\u043b\u0438 \u043c\u043e,\n\u041c\u0435\u04b3\u0440\u0438 \u0434\u0443\u0440\u0430\u0445\u0448\u0430\u043d\u0434\u0430\u0438 \u0438\u049b\u0431\u043e\u043b\u0438 \u043c\u043e.\n\u0417\u0438\u043d\u0434\u0430 \u0437\u0438 \u0442\u0443 \u043e\u0442\u0438\u044f\u0432\u0443\n\u04b3\u043e\u043b\u0438 \u043c\u043e,\n\u0411\u0430\u0441\u0442\u0430 \u0431\u0430 \u0442\u0443 \u0430\u0437\u043c\u0430\u0442\u0443 \u0438\u04b7\u043b\u043e\u043b\u0438 \u043c\u043e\n.\n\u0427\u0430\u0448\u043c\u0438 \u0412\u0430\u0442\u0430\u043d \u0441\u04ef\u0439\u0438 \u0442\u0443 \u0443\u043c\u0435\u0434\u0432\u043e\u0440,\n\u0428\u0430\u0432\u043a\u0430\u0442\u0438 \u0438\u043d \u049b\u0430\u0432\u043c\u0438 \u0431\u0430 \u0442\u0443 \u0443\u0441\u0442\u0443\u0432\u043e\u0440.\n\u041c\u043e \u0431\u0430 \u0443\u043c\u0435\u0434\u0435, \u043a\u0438 \u0442\u0443 \u0434\u043e\u043d\u043e \u0448\u0430\u0432\u04e3,\n\u041c\u0430\u0440\u0434\u0438 \u04b3\u0443\u043d\u0430\u0440\u043f\u0435\u0448\u0430\u0438 \u0444\u0430\u0440\u0434\u043e \u0448\u0430\u0432\u04e3.\n\u0411\u0430\u04b3\u0440\u0438 \u0412\u0430\u0442\u0430\u043d \u0434\u0430\u0441\u0442\u0438 \u0442\u0430\u0432\u043e\u043d\u043e \u0448\u0430\u0432\u04e3,\n\u0421\u0430\u0444\u0448\u0438\u043a\u0430\u043d\u0438 \u0444\u0438\u0440\u049b\u0430\u0438 \u0430\u044a\u0434\u043e\n\u0448\u0430\u0432\u04e3.\n\u0411\u043e\u0437 \u043a\u0430\u0448\u04e3 \u043d\u043e\u043c \u0431\u0430 \u043d\u043e\u043c \u043e\u0432\u0430\u0440\u04e3,\n\u0417\u0438\u043d\u0434\u0430 \u043a\u0443\u043d\u04e3 \u0434\u0430\u0431\u0434\u0430\u0431\u0430\u0438 \u0441\u0430\u0440\u0432\u0430\u0440\u04e3.\n\u0411\u043e\u0437 \u043a\u0443\u043d\u04e3 \u0442\u043e\u0437\u0430 \u0431\u0430 \u043d\u0435\u043a\u0430\u0445\u0442\u0430\u0440\u04e3,\n\u0414\u0430\u0432\u0440\u0430\u0438 \u0410\u04b3\u043c\u0430\u0434\u0448\u0430\u04b3\u0438\u044e \u0410\u043a\u0431\u0430\u0440\u04e3.\n\u0411\u0430\u0440\u0448\u0438\u043a\u0443 \u0433\u0430\u0440\u0434\u0430\u043d\u0438 \u0430\u0439\u0451\u043c\u0440\u043e!\n\u0420\u043e\u043c \u043a\u0443\u043d\u04e3 \u0442\u0430\u0432\u0441\u0430\u043d\u0438 \u0445\u0443\u0434\u043a\u043e\u043c\u0440\u043e!\n\u0417\u0438\u043d\u0434\u0430\u043a\u0443\u043d\u0438 \u043d\u043e\u043c\u0438 \u043d\u0438\u0451\u0433\u043e\u043d \u0442\u0443\u04e3,\n\u0420\u0430\u0432\u0448\u0430\u043d\u0438\u0438 \u0447\u0430\u0448\u043c\u0438 \u0430\u0437\u0438\u0437\u043e\u043d \u0442\u0443\u04e3.\n\u041c\u043e, \u043a\u0438 \u0433\u0443\u0437\u0430\u0448\u0442\u0435\u043c \u0412\u0430\u0442\u0430\u043d \u043e\u043d\u0438 \u0442\u0443\u0441\u0442,\n\u041a\u0438\u0448\u0432\u0430\u0440\u0438 \u043c\u043e \u04b3\u0438\u0442\u0442\u0430\u0438 \u0444\u0430\u0440\u043c\u043e\u043d\u0438 \u0442\u0443\u0441\u0442.\n\u04b6\u043e\u043d\u0438 \u043c\u0430\u043d, \u0438\u043d \u043c\u0443\u043b\u043a \u0431\u0443\u0432\u0430\u0434 \u04b7\u043e\u0439\u0438 \u0442\u0443,\n\u0425\u043e\u043d\u0430\u0438 \u043e\u0441\u043e\u0438\u0448\u0438 \u043e\u0431\u043e\u0438 \u0442\u0443.\n\u041c\u0435\u0431\u0430\u0440\u0430\u0434 \u0438\u043d \u049b\u0430\u0432\u043c \u0442\u0430\u043c\u0430\u043d\u043d\u043e\u0438 \u0442\u0443,\n\u041e\u0440\u0437\u0443\u0438 \u0434\u0430\u0441\u0442\u0438 \u0442\u0430\u0432\u043e\u043d\u043e\u0438 \u0442\u0443.\n\u0410\u0437 \u0442\u0443 \u0434\u0430\u0440\u0435\u0493 \u0430\u0441\u0442, \u043a\u0438 \u0493\u043e\u0444\u0438\u043b \u0448\u0430\u0432\u04e3,\n\u0428\u043e\u0445\u0430\u0438 \u0431\u0435\u0441\u043e\u044f\u0438 \u04b3\u043e\u0441\u0438\u043b \u0448\u0430\u0432\u04e3.\n\u042d\u0439 \u0433\u0443\u043b\u0438 \u043d\u0430\u0432 \u0445\u043e\u0440 \u0431\u0430 \u0434\u0438\u043b\u04b3\u043e \u043c\u0430\u0448\u0430\u0432,\n\u0428\u043e\u0445\u0438 \u043a\u0430\u04b7\u0438 \u0431\u0435\u0441\u0430\u0440\u0443 \u0431\u0435\u043f\u043e \u043c\u0430\u0448\u0430\u0432.\n\u0428\u0435\u0444\u0442\u0430\u0438 \u0437\u043e\u04b3\u0438\u0440\u0438 \u0434\u0443\u043d\u0451 \u043c\u0430\u0448\u0430\u0432,\n\u041c\u0443\u043d\u04b3\u0430\u0440\u0438\u0444\n\u0430\u0437 \u043c\u0430\u0440\u0434\u0443\u043c\u0438 \u0434\u043e\u043d\u043e \u043c\u0430\u0448\u0430\u0432.\n\u0420\u0430\u0445\u043d\u0430 \u0431\u0430 \u043e\u0441\u043e\u0438\u0448\u0438 \u0430\u0444\u0493\u043e\u043d \u043c\u0430\u0437\u0430\u043d,\n\u0422\u0430\u044a\u043d\u0430 \u0431\u0430 \u043e\u0438\u043d\u0438 \u043d\u0438\u0451\u0433\u043e\u043d \u043c\u0430\u0437\u0430\u043d.")
B.aor=new A.a("82b73807-ade0-4b3e-9ad6-ac70fae9c22a","fd212071-6a30-4b8d-870a-ae784002e8f2","\u0413\u04ef\u0435\u0434 \u0431\u0430 \u041d\u0430\u0432\u0440\u04ef\u0437, \u043a\u0438 \u0438\u043c\u0441\u043e\u043b \u043d\u0430\u043e\u044f\u0434...","\u0413\u04ef\u0435\u0434 \u0431\u0430 \u041d\u0430\u0432\u0440\u04ef\u0437, \u043a\u0438 \u0438\u043c\u0441\u043e\u043b \u043d\u0430\u043e\u044f\u0434,\n\u0414\u0430\u0440 \u043a\u0438\u0448\u0432\u0430\u0440\u0438 \u0445\u0443\u043d\u0438\u043d\u043a\u0430\u0444\u0430\u043a\u043e\u043d \u0440\u0430\u04b3 \u043d\u0430\u043a\u0443\u0448\u043e\u044f\u0434.\n\u0411\u0443\u043b\u0431\u0443\u043b \u0431\u0430 \u0447\u0430\u043c\u0430\u043d \u043d\u0430\u0493\u043c\u0430\u0438 \u0448\u043e\u0434\u04e3 \u043d\u0430\u0441\u0430\u0440\u043e\u044f\u0434,\n\u041c\u043e\u0442\u0430\u043c\u0437\u0430\u0434\u0430\u0433\u043e\u043d\u0440\u043e \u043b\u0430\u0431\u0438 \u043f\u0443\u0440\u0445\u0430\u043d\u0434\u0430 \u043d\u0430\u0448\u043e\u044f\u0434.\n\u0425\u0443\u043d \u043c\u0435\u0434\u0430\u043c\u0430\u0434 \u0430\u0437 \u0445\u043e\u043a\u0438 \u0448\u0430\u04b3\u0438\u0434\u043e\u043d\u0438\n\u0412\u0430\u0442\u0430\u043d, \u0432\u043e\u0439, \u0430\u0439 \u0432\u043e\u0439 \u0412\u0430\u0442\u0430\u043d, \u0432\u043e\u0439!\n\u0413\u0443\u043b\u0433\u0443\u043d\u043a\u0430\u0444\u043e\u043d\u043e\u043d\u0440\u043e \u0447\u04e3 \u0431\u0430\u04b3\u043e\u0440\u0443 \u0447\u04e3 \u0437\u0438\u043c\u0438\u0441\u0442\u043e\u043d,\n\u0425\u0443\u043d\u0438\u043d\u04b7\u0438\u0433\u0430\u0440\u043e\u043d\u0440\u043e \u0447\u04e3 \u0431\u0438\u0451\u0431\u043e\u043d, \u0447\u04e3 \u0433\u0443\u043b\u0438\u0441\u0442\u043e\u043d.\n\u0414\u0430\u0440 \u043a\u0438\u0448\u0432\u0430\u0440\u0438 \u043e\u0442\u0430\u0448\u0437\u0430\u0434\u0430, \u0434\u0430\u0440 \u0445\u043e\u043d\u0430\u0438 \u0432\u0430\u0439\u0440\u043e\u043d,\n\u041a\u0430\u0441 \u043d\u0435\u0441\u0442, \u0437\u0430\u043d\u0430\u0434 \u0431\u04ef\u0441\u0430 \u0431\u0430 \u0440\u0443\u0445\u0441\u043e\u0440\u0438 \u044f\u0442\u0438\u043c\u043e\u043d.\n\u041a\u0430\u0441 \u043d\u0435\u0441\u0442, \u043a\u0438 \u0434\u04ef\u0437\u0430\u0434 \u0431\u0430 \u0442\u0430\u043d\u0438 \u043c\u0443\u0440\u0434\u0430 \u043a\u0430\u0444\u0430\u043d, \u0432\u043e\u0439,\n\u0410\u0439 \u0432\u043e\u0439 \u0412\u0430\u0442\u0430\u043d, \u0432\u043e\u0439!\n\u0410\u0437 \u0441\u0438\u043d\u0430\u0438 \u04b3\u0430\u0440 \u0441\u0430\u043d\u0433\u0438 \u0442\u0443 \u0445\u0443\u043d \u043c\u0435\u0434\u0430\u043c\u0430\u0434 \u0438\u043c\u0440\u04ef\u0437,\n\u0410\u0437 \u0445\u043e\u043a\u0438 \u0442\u0443 \u043c\u0430\u0441\u0442\u0438\u044e \u04b7\u0443\u043d\u0443\u043d \u043c\u0435\u0434\u0430\u043c\u0430\u0434 \u0438\u043c\u0440\u04ef\u0437.\n\u041e\u043d \u043b\u043e\u043b\u0430 \u0447\u04e3 \u0434\u0438\u0434\u0430, \u043a\u0438 \u043d\u0438\u0433\u0443\u043d \u043c\u0435\u0434\u0430\u043c\u0430\u0434 \u0438\u043c\u0440\u04ef\u0437,\n\u0412-\u043e\u043d \u0441\u0430\u0431\u0437\u0430 \u0447\u0430\u0440\u043e \u0437\u0430\u0440\u0434\u0443 \u0437\u0430\u0431\u0443\u043d \u043c\u0435\u0434\u0430\u043c\u0430\u0434 \u0438\u043c\u0440\u04ef\u0437?\n\u0421\u0443\u0440\u0445 \u0430\u0441\u0442 \u0431\u043e \u0445\u0443\u043d \u043f\u043e\u0432\u0443 \u0441\u0430\u0440\u0438 \u0441\u0430\u0440\u0432\u0443 \u0441\u0443\u043c\u0430\u043d, \u0432\u043e\u0439,\n\u0410\u0439 \u0432\u043e\u0439, \u0412\u0430\u0442\u0430\u043d, \u0432\u043e\u0439!\n\u0410\u0439 \u0431\u0430\u0440\u0430\u04b3\u043d\u0430\u043f\u043e, \u0441\u0430\u0440\u0432\u0438 \u0441\u0430\u0440\u0430\u0444\u0440\u043e\u0437 \u0442\u0443\u04e3, \u0442\u0443,\n\u0421\u0430\u0440\u0434\u043e\u0440\u0443 \u0441\u0430\u0437\u043e\u0432\u043e\u0440 \u0431\u0430 \u04b3\u0430\u0440 \u043d\u043e\u0437 \u0442\u0443\u04e3, \u0442\u0443.\n\u0414\u0443\u0448\u043c\u0430\u043d\u0448\u0438\u043a\u0430\u043d\u0443 \u0444\u043e\u0442\u0435\u04b3\u0443 \u0441\u0430\u0440\u0431\u043e\u0437 \u0442\u0443\u04e3, \u0442\u0443,\n\u0424\u0430\u0440\u043c\u043e\u043d\u0434\u0435\u04b3\u0438 \u0438\u043d \u0445\u043e\u043a \u0437\u0438 \u043e\u0493\u043e\u0437 \u0442\u0443\u04e3, \u0442\u0443.\n\u0492\u0430\u0439\u0440 \u0430\u0437 \u0442\u0443 \u043a\u0430\u0441\u0435 \u043d\u0435\u0441\u0442 \u0434\u0430\u0440 \u0438\u043d \u043c\u0430\u0440\u0437\u0438 \u043a\u0443\u0445\u0430\u043d, \u0432\u043e\u0439,\n\u0410\u0439 \u0432\u043e\u0439 \u0412\u0430\u0442\u0430\u043d, \u0432\u043e\u0439!\n\u041d\u0435 \u0442\u043e\u04b7 \u0431\u0430 \u043a\u043e\u0440 \u043e\u044f\u0434\u0430\u0442 \u0438\u043c\u0440\u04ef\u0437, \u043d\u0430 \u0430\u0432\u0440\u0430\u043d\u0433\n,\n\u041d\u0435 \u0441\u043e\u04b3\u0438\u0431\u0438 \u0441\u0430\u0440\u043c\u043e\u044f, \u043a\u0438 \u0431\u043e \u0441\u0443\u0434\u0438 \u0433\u0430\u0440\u043e\u043d\u0441\u0430\u043d\u0433.\n\u0425\u0443\u043d\u0438 \u0434\u0438\u043b\u0438 \u0442\u0443 \u0445\u04ef\u0440\u0434\u0430 \u0431\u0430 \u0441\u0430\u0434 \u04b3\u0438\u043b\u0430\u0432\u0443 \u043d\u0430\u0439\u0440\u0430\u043d\u0433,\n\u041a\u0430\u0441 \u043d\u0435\u0441\u0442, \u043a\u0438 \u043f\u0438\u0440\u04ef\u0437 \u0448\u0430\u0432\u0430\u0434 \u04b7\u0443\u0437 \u0442\u0443 \u0434\u0430\u0440 \u0438\u043d \u04b7\u0430\u043d\u0433.\n\u0410\u0439 \u0431\u043e\u0437\u0443\u0438 \u0440\u0430\u0437\u043c\u0430\u043d\u0434\u0430\u0438 \u0437\u0430\u043d\u04b7\u0438\u0440\u0448\u0438\u043a\u0430\u043d, \u0432\u043e\u0439,\n\u0410\u0439 \u0432\u043e\u0439 \u0412\u0430\u0442\u0430\u043d, \u0432\u043e\u0439!")
B.a6I=new A.a("b0a33278-36e9-4fba-80eb-045db98a77ce","fd212071-6a30-4b8d-870a-ae784002e8f2","\u041c\u0443\u0441\u0443\u043b\u043c\u043e\u043d\u043e\u043d! \u0417\u0438 \u0434\u0443\u0440 \u043e\u044f\u0434 \u0441\u0430\u0434\u043e\u0435,","\u041c\u0443\u0441\u0443\u043b\u043c\u043e\u043d\u043e\u043d! \u0417\u0438 \u0434\u0443\u0440 \u043e\u044f\u0434 \u0441\u0430\u0434\u043e\u0435,\n\u0421\u0430\u0434\u043e\u0438 \u04b7\u043e\u043d\u0433\u0443\u0434\u043e\u0437\u0435, \u0493\u0430\u043c\u0444\u0438\u0437\u043e\u0435.\n\u041d\u0430\u0434\u043e\u043d\u0430\u043c, \u043a\u0443\u04b7\u043e \u0448\u0430\u0431\u0435\u0445\u0443\u043d \u0437\u0430\u0434\u0430 \u0433\u0443\u0440\u0433,\n\u0412\u0430\u043b\u0435 \u0434\u043e\u043d\u0430\u043c, \u043a\u0438 \u043d\u043e\u043b\u0430\u0434 \u043e\u0448\u043d\u043e\u0435.\n\u042f\u0442\u0438\u043c\u0435, \u0434\u0430\u0440\u0434\u043c\u0430\u043d\u0434\u0435, \u0431\u0435\u043d\u0430\u0432\u043e\u0435,\n\u0411\u0430\u0440\u043e\u0432\u0430\u0440\u0434 \u0430\u0437 \u0434\u0438\u043b\u0438 \u0441\u0430\u04b3\u0440\u043e \u0441\u0430\u0434\u043e\u0435:\n\xab\u041c\u0430\u043d\u0435\u04b3 \u0437\u0438\u043d\u04b3\u043e\u0440 \u0430\u0437 \u043a\u0430\u0444 \u0448\u0430\u043c\u044a\u0438 \u0443\u043c\u0435\u0434,\n\u0410\u0433\u0430\u0440 \u0445\u043e\u04b3\u04e3 \u0440\u0430\u0441\u04e3 \u0440\u04ef\u0437\u0435 \u0431\u0430 \u04b7\u043e\u0435\xbb.\n\u0410\u0437 \u0431\u0430\u0441 \u0445\u0443\u0448\u0443 \u043c\u0430\u0441\u0442\u0443 \u0434\u0438\u043b\u0440\u0430\u0431\u043e \u043c\u0435\u043e\u04e3,\n\u0427\u0443\u043d \u0431\u043e\u0434\u0438 \u0431\u0430\u04b3\u043e\u0440 \u04b7\u043e\u043d\u0444\u0430\u0437\u043e \u043c\u0435\u043e\u04e3.\n\u0414\u0438\u043b \u0445\u043e\u043d\u0430\u0438 \u0438\u0448\u049b\u0438 \u0442\u0443\u0441\u0442, \u043e\u0431\u043e\u0434\u0430\u0448 \u0434\u043e\u0440,\n\u0427\u0443\u043d \u0445\u043e\u043d\u0430 \u0445\u0430\u0440\u043e\u0431 \u0448\u0443\u0434, \u043a\u0443\u04b7\u043e \u043c\u0435\u043e\u04e3?\n\u0418\u043d \u043a\u0438\u043d\u0430\u0432\u0430\u0440\u043e\u043d\n\u0431\u043e\u0437 \u0431\u043e \u043d\u0430\u0439\u0440\u0430\u043d\u0433\u0438 \u0434\u0438\u0433\u0430\u0440,\n\u0414\u043e\u0440\u0430\u043d\u0434 \u0441\u0430\u0440\u0438 \u0444\u0438\u0442\u043d\u0430 \u0431\u0430 \u043e\u04b3\u0430\u043d\u0433\u0438 \u0434\u0438\u0433\u0430\u0440.\n\u0424\u0430\u0440\u0451\u0434, \u043a\u0438 \u0438\u043d \u0448\u0443\u044a\u0431\u0430\u0434\u0430\u0431\u043e\u0437\u043e\u043d\n\u04b3\u0430\u0440 \u0440\u04ef\u0437,\n\u0425\u043e\u04b3\u0430\u043d\u0434 \u0431\u0430 \u043d\u043e\u043c\u0438 \u043e\u0448\u0442\u04e3 \u04b7\u0430\u043d\u0433\u0438 \u0434\u0438\u0433\u0430\u0440.\n\u0417\u0435\u0431\u043e \u0412\u0430\u0442\u0430\u043d\u0430\u043c, \u04b7\u0430\u043d\u043d\u0430\u0442\u0438 \u0434\u0443\u043d\u0451 \u0412\u0430\u0442\u0430\u043d\u0430\u043c!\n\u0410\u0439 \u0493\u0430\u0440\u049b\u0430\u0438 \u0445\u0443\u043d\u0443 \u0430\u0448\u043a, \u0442\u0430\u043d\u04b3\u043e \u0412\u0430\u0442\u0430\u043d\u0430\u043c!\n\u041c\u0430\u043d \u04b7\u0443\u0437 \u0442\u0443 \u0434\u0438\u0433\u0430\u0440 \u043d\u043e\u043c \u043d\u0430\u0451\u0440\u0430\u043c \u0431\u0430\u0440 \u043b\u0430\u0431,\n\u0410\u0439 \u0432\u043e \u0412\u0430\u0442\u0430\u043d\u0430\u043c, \u0432\u043e \u0412\u0430\u0442\u0430\u043d\u0430\u043c, \u0432\u043e \u0412\u0430\u0442\u0430\u043d\u0430\u043c.")
B.a6S=new A.a("dfda4360-e416-4d89-a228-c63a0d5b8485","a7feaa09-c83f-44f2-a69e-0a46ba957dbc","\u041c\u0435\u0432\u0430\u0437\u0430\u0434 \u0431\u043e\u0434\u0438 \u0442\u043e\u0437\u0430\u0432\u0443 \u0444\u043e\u0440\u0430\u043c,","\u041c\u0435\u0432\u0430\u0437\u0430\u0434 \u0431\u043e\u0434\u0438 \u0442\u043e\u0437\u0430\u0432\u0443 \u0444\u043e\u0440\u0430\u043c,\n\u0411\u0430\u0440\u0433\u0438 \u0433\u0443\u043b\u04b3\u043e \u0431\u0430 \u04b7\u0443\u043d\u0431\u0438\u0448\u0430\u043d\u0434 \u0430\u0437 \u043e\u043d.\n\u041c\u0435\u0448\u0430\u0432\u0430\u0434 \u043f\u0430\u04b3\u043d \u0434\u0430\u0440 \u0444\u0430\u0437\u043e \u04b3\u0430\u0440 \u0434\u0430\u043c\n\u0418\u043d \u0441\u0443\u0440\u0443\u0434\u0438 \u049b\u0430\u0434\u0438\u043c\u0438 \u043a\u04ef\u04b3\u0438\u0441\u0442\u043e\u043d:\n\xab\u0420\u04ef\u0437\u0443 \u0448\u0430\u0431 \u0440\u04ef\u0434\u0438 \u041f\u0430\u043d\u04b7\u0438 \u043d\u043e\u043e\u0440\u043e\u043c\n\u041c\u0435\u0437\u0430\u043d\u0430\u0434 \u0434\u043e\u0434\u0443 \u043c\u0435\u0437\u0430\u043d\u0430\u0434 \u0444\u0430\u0440\u0451\u0434.\n\u041c\u0435\u0440\u0430\u0432\u0430\u0434 \u0445\u0443\u0434\u0441\u0430\u0440\u043e\u043d\u0430, \u043b\u0435\u043a\u0438\u043d \u0440\u043e\u043c\n\u04b2\u0435\u04b7 \u043a\u0430\u0441\u0440\u043e \u043d\u0430\u043c\u0435\u0448\u0430\u0432\u0430\u0434. \u04b2\u0430\u0439\u04b3\u043e\u0442!\n\u041a\u04ef\u04b3\u0438 \u0445\u043e\u0440\u043e, \u043d\u0438\u0433\u0430\u0440, \u043a\u0438 \u0443\u0448\u0442\u0443\u0440\u0432\u043e\u0440\n\u0411\u0430\u0440 \u0441\u0430\u0440\u0438 \u0433\u0430\u043d\u04b7\u04b3\u043e \u043d\u0430\u043c\u0443\u0434\u0430 \u0445\u043e\u0431.\n\u04b2\u0435\u04b7 \u0433\u043e\u04b3\u0435 \u043d\u0430\u043c\u0435\u0448\u0430\u0432\u0430\u0434 \u0431\u0435\u0434\u043e\u0440,\n\u04ee \u0437\u0438 \u0444\u0430\u0440\u0451\u0434\u0438 \u041f\u0430\u043d\u04b7\u0438 \u0437\u0430\u0440\u0440\u0438\u043d\u043e\u0431\u2026\xbb\n\u041c\u0430\u043d\u0443 \u0441\u0430\u0440\u04b3\u0430\u0434\u0447\u0438\u0438 \u0434\u0438\u043b\u043e\u0432\u0430\u0440\u0438 \u0445\u0430\u043b\u049b,\n\u041b\u0430\u0431-\u043b\u0430\u0431\u0438 \u041f\u0430\u043d\u04b7 \u0431\u043e \u0441\u0443\u0440\u0443\u0434\u0438 \u0431\u0430\u04b3\u043e\u0440\n\u0420\u043e\u04b3 \u0440\u0430\u0444\u0442\u0435\u043c\u0443 \u043e\u0444\u0442\u043e\u0431 \u0430\u0437 \u0428\u0430\u0440\u049b,\n\u0413\u0430\u0448\u0442 \u0440\u0430\u0445\u0448\u0430\u043d\u0434\u0430 \u0431\u0430\u0440 \u0441\u0430\u0440\u0438 \u043a\u04ef\u04b3\u0441\u043e\u0440.\n\u0411\u0430\u0440 \u0441\u0430\u0440\u0438 \u043a\u04ef\u04b3 \u0441\u0438\u0442\u043e\u0434\u0430 \u043c\u0430\u0448\u044a\u0430\u043b\u0441\u043e\u043d,\n\u0414\u0435\u04b3\u0430\u04b3\u043e\u0440\u043e \u043d\u0430\u043c\u0443\u0434 \u0440\u0430\u0445\u0448\u0430\u043d\u0434\u0430.\n\u0413\u04ef\u0438\u0451 \u043a\u0438 \u0431\u0430 \u04b7\u043e\u043d\u0438\u0431\u0438 \u043c\u043e\u0451\u043d\n\u041c\u0435\u043d\u0430\u043c\u043e\u044f\u0434 \u0442\u0430\u0431\u0430\u0441\u0441\u0443\u043c\u0443 \u0445\u0430\u043d\u0434\u0430.\n\u041c\u043e \u043d\u0438\u0448\u0430\u0441\u0442\u0435\u043c \u043d\u0430\u0437\u0434\u0438 \u044f\u043a \u0447\u0430\u0448\u043c\u0430,\n\u0414\u0430\u0441\u0442\u04b3\u043e\u0440\u043e \u043d\u0430\u043c\u0443\u0434\u0430 \u043a\u043e\u0441\u0430, \u0430\u0437 \u043e\u043d\n\u041e\u0431 \u0445\u04ef\u0440\u0434\u0435\u043c \u043f\u0430\u0441 \u04b3\u0430\u0440\u0438\u0441\u043e\u043d\u0430.\n\u041e\u0431 \u043d\u0435, \u0431\u0430\u043b\u043a\u0438 \u0431\u0443\u0434 \u0440\u043e\u04b3\u0430\u0442\u0438 \u04b7\u043e\u043d.\n\u0421\u0443\u043c\u043a\u0430\u04b3\u043e\u0440\u043e \u0431\u0430 \u0437\u0435\u0440\u0438 \u0441\u0430\u0440 \u043c\u043e\u043d\u0434\u0430,\n\u0414\u0430\u043c \u0433\u0438\u0440\u0438\u0444\u0442\u0430, \u0432\u0430\u043b\u0435 \u043d\u0430\u043c\u0435\u0445\u0443\u0444\u0442\u0435\u043c.\n\u0411\u043e \u043c\u0443\u04b3\u0430\u0431\u0431\u0430\u0442 \u043c\u0430\u0445\u043e\u0440\u043a\u0430\n\u043f\u0435\u0447\u043e\u043d\u0434\u0430,\n\u0421\u0430\u0440\u0433\u0443\u0437\u0430\u0448\u0442\u0443 \u04b3\u0438\u043a\u043e\u044f \u043c\u0435\u0433\u0443\u0444\u0442\u0435\u043c.")
B.aqC=new A.a("6c488276-7087-4042-9dba-e0f96305f2c7","a7feaa09-c83f-44f2-a69e-0a46ba957dbc","\u041d\u0435 \u0445\u0443\u0440\u04ef\u0441\u0435 \u04b7\u0435\u0493 \u0437\u0430\u0434 \u0448\u0430\u0431, \u0431\u0435\u043c\u0430\u04b3\u0430\u043b...","\u041d\u0435 \u0445\u0443\u0440\u04ef\u0441\u0435 \u04b7\u0435\u0493 \u0437\u0430\u0434 \u0448\u0430\u0431, \u0431\u0435\u043c\u0430\u04b3\u0430\u043b,\n\u041d\u0435 \u0441\u0438\u0442\u043e\u0440\u0430 \u0431\u0430\u0440 \u0437\u0430\u043c\u0438\u043d \u0430\u0444\u0442\u0438\u0434\u0430 \u0431\u0443\u0434,\n\u041d\u0435 \u0431\u0430 \u0431\u043e\u043c\u0438 \u0445\u043e\u043d\u0430\u0435 \u0447\u0443\u0493\u0437\u0435 \u043d\u0438\u0448\u0430\u0441\u0442,\n\u041d\u0435 \u043a\u0430\u0441\u0435 \u0434\u0430\u0440 \u0445\u043e\u0431 \u043c\u043e\u0440\u0435 \u0434\u0438\u0434\u0430 \u0431\u0443\u0434.\n\u0421\u043e\u043b \u0430\u043c\u043c\u043e \u0441\u043e\u043b\u0438 \u043d\u043e\u043e\u0440\u043e\u043c \u0431\u0443\u0434,\n\u041a\u043e\u0440\u0438 \u043c\u0430\u0440\u0434\u0443\u043c \u0431\u0435\u0441\u0430\u0440\u0443 \u0430\u043d\u04b7\u043e\u043c \u0431\u0443\u0434.\n\u0420\u0430\u04b3\u0433\u0443\u0437\u0430\u0440\u04b3\u043e\u0432\u0443 \u043c\u0443\u0441\u043e\u0444\u0438\u0440\u04b3\u043e\u0438 \u0440\u0430\u04b3\n\u041f\u0430\u04b3\u043d \u043c\u0435\u043a\u0430\u0440\u0434\u0430\u043d\u0434 \u04b3\u0430\u0440 \u0433\u0443\u043d\u0430 \u0445\u0430\u0431\u0430\u0440.\n\u0425\u0443\u0440\u0434\u0430\u043a\u0430\u043a \u0431\u0443\u0434\u0435\u043c, \u0430\u043c\u043c\u043e \u043a\u0443\u043d\u04b7\u043a\u043e\u0432,\n\u0413\u04ef\u0448 \u043c\u0435\u0434\u043e\u0434\u0435\u043c \u0431\u0430\u0440 \u04b3\u0430\u0440 \u0440\u0430\u04b3\u0433\u0443\u0437\u0430\u0440.\n\u0412\u0430\u049b\u0442\u0438 \u0431\u043e\u0437\u04e3 \u0431\u0443\u0434 \u043c\u0430\u0433\u0430\u0440? \u041d\u0435! \u0425\u043e\u0441\u0442\u0435\u043c\n\u0411\u043e\u0445\u0430\u0431\u0430\u0440 \u0431\u043e\u0448\u0435\u043c \u0430\u0437 \u04b3\u0430\u0440 \xab\u043d\u0435\u043a\xbb-\u0443 \xab\u0431\u0430\u0434\xbb,\n\u041c\u0430\u044a\u043d\u0438\u0438 \xab\u0442\u0430\u049b\u0434\u0438\u0440\u0438 \u0431\u0430\u0434\xbb-\u0440\u043e \u0445\u043e\u0441\u0442\u0435\u043c\n\u0411\u0438\u0448\u043d\u0430\u0432\u0435\u043c \u0430\u0437 \u043d\u043e\u0431\u0430\u043b\u0430\u0434\u04b3\u043e \u0451 \u0431\u0430\u043b\u0430\u0434\n.\n\u0425\u0443\u0440\u0434\u0430\u043a\u0430\u043a \u0431\u0443\u0434\u0435\u043c, \u043b\u0435\u043a\u0438\u043d \u0445\u043e\u0441\u0442\u0435\u043c\n\u0411\u043e\u0445\u0430\u0431\u0430\u0440 \u0431\u043e\u0448\u0435\u043c \u0430\u0437 \xab\u043a\u043e\u0440\u0438 \u04b7\u0430\u04b3\u043e\u043d\xbb.\n\u041a\u043e\u0440\u0433\u0430\u0440\u0431\u0430\u0447\u0430, \u043a\u0438 \u0414\u0430\u0432\u0440\u043e\u043d \u043d\u043e\u043c \u0434\u043e\u0448\u0442,\n\u0411\u0430\u0440 \u0441\u0430\u0440\u0438 \u043c\u043e, \u043a\u0443\u043d\u04b7\u043a\u043e\u0432\u043e\u043d, \u0431\u0443\u0434 \u043a\u0430\u043b\u043e\u043d.\n\u0411\u043e \u043f\u0430\u0434\u0430\u0440 \u0434\u0430\u0440 \u0448\u0430\u04b3\u0440 \u0440\u0430\u0444\u0442\u0430 \u0431\u043e\u0440\u04b3\u043e\n\u04b2\u0430\u0440 \u043a\u0430\u0441\u0435\u0440\u043e \u043c\u0430\u0440\u0434\u0438\u043a\u043e\u0440\u04e3 \u043a\u0430\u0440\u0434\u0430\u0430\u0441\u0442.\n\u0421\u0438\u043d\u043d\u0443 \u0441\u043e\u043b\u0430\u0448 \u0445\u0443\u0440\u0434, \u0430\u043c\u043c\u043e \u0430\u043b\u043b\u0430\u043a\u0430\u0439\n\u0417\u0430\u0440\u0431\u0438 \u0447\u04ef\u0431\u0438 \u0431\u0430\u043d\u0434\u0430\u0433\u0438\u0440\u043e \u0445\u04ef\u0440\u0434\u0430\u0430\u0441\u0442.\n\u0425\u0443\u0440\u0434 \u0431\u043e\u0448\u0430\u0434 \u04b3\u0430\u043c, \u0432\u0430\u043b\u0435 \u0444\u0430\u04b3\u043c\u0438\u0434\u0430 \u0431\u0443\u0434\n\u0421\u0435 \u0441\u0443\u0445\u0430\u043d\u0440\u043e: \xab\u0448\u0430\u04b3\u0440\xbb, \xab\u043c\u0435\u04b3\u043d\u0430\u0442\xbb, \xab\u0431\u0430\u043d\u0434\u0430\u0433\u04e3\xbb.\n\u041f\u0430\u0441, \u043a\u0430\u043c\u0430\u0448 \u0441\u0435 \u0431\u043e\u0440 \u0430\u0437 \u043c\u043e \u0431\u0435\u0448\u0442\u0430\u0440\n\u041e\u0448\u043d\u043e \u0432\u0430\u0439 \u0431\u043e \u0442\u0430\u0440\u0438\u049b\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u04e3.\n\u0428\u0430\u04b3\u0440\u0434\u0438\u0434\u0430, \u0437\u0438\u043d\u0434\u0430\u0433\u043e\u043d\u0438\u0440\u043e \u0437\u0438 \u043c\u043e,\n\u0425\u0443\u0431\u0442\u0430\u0440, \u0431\u0438\u0441\u0451\u0440\u0442\u0430\u0440 \u0434\u043e\u043d\u0438\u0441\u0442\u0430 \u0431\u0443\u0434.\n\u04b2\u0430\u0440 \u0447\u0438\u0440\u043e, \u043a\u0438 \u043c\u0435\u0448\u0443\u043d\u0438\u0434 \u04ef \u0430\u0437 \u043f\u0430\u0434\u0430\u0440,\n\u041e\u043c\u0430\u0434\u0430 \u0431\u0430\u0440 \u043c\u043e \u04b3\u0438\u043a\u043e\u044f\u0442 \u043c\u0435\u043d\u0430\u043c\u0443\u0434.\n\u0420\u0430\u04b3\u0433\u0443\u0437\u0430\u0440\u04b3\u043e\u044e \u043c\u0443\u0441\u043e\u0444\u0438\u0440\u04b3\u043e\u0438 \u0440\u0430\u04b3\n\u041f\u0430\u04b3\u043d \u043c\u0435\u043a\u0430\u0440\u0434\u0430\u043d\u0434 \u04b3\u0430\u0440 \u0433\u0443\u043d\u0430 \u0445\u0430\u0431\u0430\u0440.\n\u041c\u0430\u0440\u0434\u0443\u043c\u0438 \u0434\u0435\u04b3-\u043c\u0430\u0440\u0434\u0443 \u0437\u0430\u043d, \u043f\u0438\u0440\u0443 \u04b7\u0430\u0432\u043e\u043d\n\u0413\u04ef\u0448 \u043c\u0435\u0434\u043e\u0434\u0430\u043d\u0434 \u0431\u0430\u0440 \u04b3\u0430\u0440 \u0440\u0430\u04b3\u0433\u0443\u0437\u0430\u0440.\n\u041e\u043d \u044f\u043a\u0435 \u043c\u0435\u0433\u0443\u0444\u0442: \xab\u0413\u04ef\u0451 \u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d,\n\u049a\u0443\u0432\u0432\u0430\u0435 \u043d\u0430\u0432 \u2013 \xab\u0411\u043e\u043b\u0448\u0435\u0432\u043e\u0439\xbb \u043f\u0430\u0439\u0434\u043e \u0448\u0443\u0434\u0430\u0430\u0441\u0442\xbb.\n\u0414\u0438\u0433\u0430\u0440\u0435 \u043c\u0435\u0433\u0443\u0444\u0442: \xab\u041e\u0440\u0435, \u0411\u043e\u043b\u0448\u0435\u0432\u043e\u0439\xbb -\n\u041e\u0434\u0430\u043c \u0430\u0441\u0442\u0443 \u043d\u043e\u043c\u0438 \u0432\u0430\u0439 \u041b\u0435\u043d\u0438\u043d\n\u0431\u0443\u0434\u0430\u0441\u0442.\n\u04ee \u0445\u0443\u0434\u0430\u0448 \u0440\u0443\u0441 \u0430\u0441\u0442\u0443 \u043c\u0435\u0445\u043e\u04b3\u0430\u0434 \u0434\u0438\u04b3\u0430\u0434\n\u041f\u043e\u0434\u0448\u043e\u04b3\u0438 \u0440\u0443\u0441\u0440\u043e, \u0438\u043d\u0430\u043a, \u04b7\u0430\u0437\u043e:\n\u0414\u0430\u0441\u0442\u0438 \u04ef\u0440\u043e \u0431\u0430\u0441\u0442\u0430 \u0442\u0430\u0445\u0442\u0430\u0448 \u0431\u0438\u0448\u043a\u0430\u043d\u0430\u0434.\n\u0411\u043e \u0437\u0430\u043c\u0438\u043d \u044f\u043a\u0441\u043e\u043d \u043d\u0430\u043c\u043e\u044f\u0434 \u0442\u043e\u04b7\u0440\u043e.\n\u0414\u0430\u0440 \u041f\u0435\u0442\u0435\u0440\u0431\u0443\u0440\u0433\u0435, \u043a\u0438 \u04b3\u0430\u0440 \u043c\u0430\u0439\u0434\u043e\u043d\u0438 \u04ef\n\u0410\u0437 \u0434\u0438\u0451\u0440\u0438 \u043c\u043e \u0432\u0430\u0441\u0435\u044e \u043f\u0430\u04b3\u043d\u0442\u0430\u0440,\n\u0414\u0430\u0440 \u041f\u0435\u0442\u0435\u0440\u0431\u0443\u0440\u0433\u0435, \u043a\u0438 \u04b3\u0430\u0440 \u044f\u043a \u0445\u043e\u043d\u0430\u0430\u0448\n\u041c\u0435\u0431\u0430\u0440\u0430\u0434, \u0433\u04ef\u044f\u043d\u0434, \u0442\u043e \u0441\u0435\u0441\u0430\u0434 \u043d\u0430\u0444\u0430\u0440,\n\u0414\u0430\u0432\u043b\u0430\u0442\u0438 \u0448\u043e\u04b3 \u0430\u0441\u0442 \u0434\u0430\u0440 \u0437\u0435\u0440\u0438 \u0445\u0430\u0442\u0430\u0440! \u2026\xbb\n\xab\u2026 \u0411\u0435\u0441\u0430\u0431\u0430\u0431 \u043d\u0435 \u0438\u043d \u0445\u0430\u0431\u0430\u0440\u04b3\u043e!\n\xab\u0411\u043e\u043b\u044c\u0448\u0435\u0432\u043e\u0439\xbb \u0437\u0438\u0434\u0434\u0438 \u0448\u043e\u04b3\u0438 \u0440\u0443\u0441 \u0438\u0441\u0451\u043d \u043a\u0430\u0440\u0434\u0430\u0430\u0441\u0442! \xbb\n\u041e\u043c\u0430\u0434 \u043e\u043d \u0441\u043e\u0430\u0442, - \u0431\u0438\u0433\u0443\u0444\u0442\u043e \u0434\u0438\u0433\u0430\u0440\u0435:\n\xab\u0414\u0430\u0432\u043b\u0430\u0442\u0438 \u043f\u0443\u0440\u0437\u04ef\u0440\u0438 \u0448\u0430\u04b3 \u0451\u0431\u0430\u0434 \u0448\u0438\u043a\u0430\u0441\u0442! \xbb\n\u049a\u043e\u0437\u0438\u0438 \u049b\u0438\u0448\u043b\u043e\u049b\u0438 \u043c\u043e \u043d\u043e\u0433\u0430\u04b3 \u0448\u0430\u0431\u0435\n\u041c\u0435\u0437\u0430\u043d\u0430\u0434 \u0444\u0430\u0440\u0451\u0434, \u043a\u0438:\n\u201c\u042d\u0439 \u0430\u04b3\u043b\u0438 \u0434\u0438\u043d! \u0425\u043e\u0431 \u0434\u0438\u0434\u0430\u043c,\n\xab\u0411\u043e\u043b\u0448\u0435\u0432\u043e\u0439\xbb \u0431\u043e \u043b\u0430\u0448\u043a\u0430\u0440\u0430\u0448\n\u04b2\u0430\u043c\u043b\u0430 \u043e\u0432\u0430\u0440\u0434\u0430\u0441\u0442 \u0431\u0430\u0440 \u0428\u0443\u0493\u043d\u043e\u043d\u0437\u0430\u043c\u0438\u043d.\n\u0410\u043b\u0493\u0430\u0440\u0430\u0437, \u0434\u0430\u0440 \u0445\u043e\u0431\u0443 \u0434\u0430\u0440 \u0431\u0435\u0434\u043e\u0440\u0438\u0430\u0448\n\u0425\u0430\u043b\u049b \u043c\u0430\u0448\u0493\u0443\u043b\u0438 \u0441\u0438\u0451\u0441\u0430\u0442 \u0433\u0430\u0448\u0442\u0430 \u0431\u0443\u0434.\n\u0411\u0443\u0434 \u0440\u0430\u0432\u0448\u0430\u043d, \u043a\u0438 \u044f\u0433\u043e\u043d \u0433\u0430\u043f \u043c\u0435\u0448\u0430\u0432\u0430\u0434,\n\u041e\u0442\u0430\u0448, \u043e\u0445\u0438\u0440, \u0433\u0430\u0440 \u043d\u0430\u0431\u043e\u0448\u0430\u0434, \u043d\u0435\u0441\u0442 \u0434\u0443\u0434.\n\u0411\u0443\u0434 \u0440\u0430\u0432\u0448\u0430\u043d \u04b3\u0430\u0441\u0442 \u043e\u0442\u0430\u0448! \u041b\u0435\u043a\u0438\u043d \u043e\u043d \u2013\n\xab\u0414\u0430\u0440 \u043a\u0443\u04b7\u043e \u04b3\u0430\u0441\u0442\u0443 \u043a\u04e3 \u0448\u0443\u0434 \u04b3\u0435\u0437\u0443\u043c\u043a\u0430\u0448\u0430\u0448?\n\u0425\u043e\u043d\u0430\u0438 \u043a\u04e3 \u2013 \u0434\u04ef\u0441\u0442\u043e\u043d \u0451 \u0434\u0443\u0448\u043c\u0430\u043d\u043e\u043d\n\u0413\u0430\u0440\u043c\u0443 \u0440\u0430\u0432\u0448\u0430\u043d \u043c\u0435\u0448\u0430\u0432\u0430\u0434 \u0430\u0437 \u0448\u04ef\u044a\u043b\u0430\u0430\u0448?\xbb\n\u0414\u0430\u0440 \u0434\u0438\u043b\u0438 \u04b3\u0430\u0440 \u043a\u0430\u0441 \u0441\u0443\u043e\u043b\u0438 \u0431\u0435\u0448\u0443\u043c\u043e\u0440\n\u0412\u0430\u049b\u0442\u0438 \u0445\u043e\u0431\u0443 \u0432\u0430\u049b\u0442\u0438 \u0440\u043e\u04b3\u0430\u0442, \u0432\u0430\u049b\u0442\u0438 \u043a\u043e\u0440\n\u0424\u0438\u043a\u0440 \u043c\u0435\u043a\u0430\u0440\u0434\u0430\u043d\u0434, \u043c\u0435\u0434\u0438\u0434\u0430\u043d\u0434 \u0444\u043e\u043b\n\u041e\u0434\u0430\u043c\u043e\u043d\u0438 \u043e\u0434\u0438\u0438 \u043a\u04ef\u04b3\u0441\u043e\u0440.\n\u0411\u043e \u04b3\u0430\u043c\u0438\u043d \u0440\u0430\u04b3 \u0431\u0430\u0440 \u0441\u0443\u043e\u043b\u0438 \u0431\u0435\u0448\u0443\u043c\u043e\u0440\n\u04b6\u0443\u0441\u0442\u0443\u04b7\u04ef \u043c\u0435\u043a\u0430\u0440\u0434 \u04b3\u0430\u0440 \u044f\u043a \u043a\u0430\u0441 \u04b7\u0430\u0432\u043e\u0431.\n\u0411\u0430\u0439\u043d\u0438 \u043c\u0430\u0440\u0434\u0443\u043c \u0431\u043e\u0437 \u044f\u043a \u0442\u043e\u0437\u0430\u0445\u0430\u0431\u0430\u0440\n\u041f\u0430\u04b3\u043d \u0448\u0443\u0434, \u043a\u0438: \xab\u0414\u0430\u0440 \u041f\u0435\u0442\u0435\u0440\u0431\u0443\u0440\u0433 \u0438\u043d\u049b\u0438\u043b\u043e\u0431! \xbb\n\u0413\u04ef\u0438\u0451, \u043a\u0438 \u0433\u0443\u0440\u0433 \u0434\u0430\u0440 \u0431\u0430\u0439\u043d\u0438 \u0440\u0430\u043c\u0430 \u0433\u0430\u0448\u0442\u0430 \u043f\u0430\u0439\u0434\u043e!\n\u2013 \u0428\u04ef\u0440\u0443 \u0493\u0430\u0432\u0493\u043e \u0448\u0443\u0434 \u0431\u0430\u043b\u0430\u043d\u0434.\n\xab\u0418\u043d\u049b\u0438\u043b\u043e\u0431, \u0438\u0441\u0451\u043d\n\u0431\u0430 \u0437\u0438\u0434\u0434\u0438 \u0448\u043e\u04b3\u0438 \u0440\u0443\u0441\n\u0411\u043e \u0442\u0443\u0444\u0430\u043d\u0433\u0443 \u0434\u043e\u0441\u0443 \u0431\u043e \u043f\u0443\u0442\u043a\u0443 \u043a\u0430\u043b\u0430\u043d\u0434! \xbb\n\u041e\u043d \u043a\u0430\u0441\u0435, \u043a\u0438 \u0438\u043d \u0445\u0430\u0431\u0430\u0440\u0440\u043e \u043f\u0430\u04b3\u043d \u043a\u0430\u0440\u0434,\n\u04b2\u0430\u0431\u0441 \u0448\u0443\u0434 \u043e\u043d \u0440\u04ef\u0437 \u0434\u0430\u0440 \u04b3\u0430\u0432\u043b\u0438\u0438 \u0445\u0443\u0434.\n\u041a\u0430\u0440\u0434\u0430 \u043c\u043e\u0440\u043e \u04b7\u0430\u043c\u044a, \u0414\u0430\u0432\u0440\u043e\u043d \u0438\u043d\u0447\u0443\u043d\u0438\u043d\n\u0421\u0430\u0440\u0433\u0443\u0437\u0430\u0448\u0442\u0438 \u043e\u043d \u04b7\u0430\u0432\u043e\u043d\u0440\u043e \u0433\u0443\u0444\u0442\u0430 \u0431\u0443\u0434:\n\u041c\u0430\u043d \u0448\u0443\u043d\u0438\u0434\u0430\u043c, \u043e\u0434\u0430\u043c\u0438 \u0431\u0435\u0447\u043e\u0440\u0430 \u04ef\u0441\u0442,\n\u0425\u043e\u043a\u0441\u043e\u0440\u0443 \u0437\u0438\u043d\u0434\u0430\u0434\u0438\u043b, \u0441\u0438\u043d\u043d\u0430\u0448 \u04b7\u0430\u0432\u043e\u043d.\n\u0411\u043e \u0437\u0430\u0431\u043e\u043d\u0438 \u043d\u0430\u0440\u043c\u0443 \u0433\u0430\u0440\u043c\u0443 \u0444\u043e\u0440\u0430\u043c\u0430\u0448\n\u0413\u0443\u0444\u0442\u0443\u0433\u04ef \u043c\u0435\u043a\u0430\u0440\u0434 \u0431\u043e \u0431\u0435\u0447\u043e\u0440\u0430\u0433\u043e\u043d.\n\u04ee \u0445\u0443\u0434\u0430\u0448 \u0430\u0437 \u0448\u0430\u04b3\u0440\u0438 \u0425\u043e\u0440\u0443\u0493 \u0431\u0443\u0434\u0430\u0430\u0441\u0442,\n\u0420\u0430\u0444\u0442\u0430 \u0434\u0430\u0440 \u043c\u0443\u043b\u043a\u0438 \u0425\u0443\u04b7\u0430\u043d\u0434\u0443 \u0434\u0443\u0440\u0442\u0430\u0440,\n\u0414\u0430\u0440 \u0437\u0430\u0432\u043e\u0434\u0443 \u0444\u0430\u0431\u0440\u0438\u043a\u0430, \u0434\u0430\u0440 \u043a\u043e\u043d\u04b3\u043e\n\u041a\u043e\u0440 \u043c\u0435\u043a\u0430\u0440\u0434\u0430\u0441\u0442, \u043c\u0430\u0440\u0434\u0438 \u043a\u043e\u0440\u0433\u0430\u0440.\n\u0414\u0430\u0440 \u0493\u0430\u0440\u0438\u0431\u04e3 \u0433\u0430\u0448\u0442\u0430-\u0433\u0430\u0448\u0442\u0430 \u043e\u043c\u0430\u0434\u0430\u0441\u0442\n\u04ee \u0431\u0430 \u043d\u0430\u0437\u0434\u0438 \u0431\u0430\u0447\u0447\u0430\u0433\u043e\u043d\u0430\u0448,\n\u041d\u043e\u0433\u0430\u04b3\u043e\u043d \u2013 \u04b2\u0430\u0431\u0441 \u0448\u0443\u0434,\n\u04ee \u0434\u0443\u0437\u0434 \u043d\u0435, \u04b7\u0430\u043b\u043b\u043e\u0434 \u043d\u0435!\n\xab\u0411\u043e\u043b\u0448\u0435\u0432\u043e\u0439\xbb-\u0440\u043e \u0451\u0432\u0430\u0440\u0443 \u0451\u0440\u0438\u0440\u0430\u0441\u043e\u043d\n\u049a\u0438\u0441\u043c\u0430\u0442\u0430\u0448\u0440\u043e \u043c\u0443\u04b3\u0440\u0438 \u049b\u043e\u0437\u04e3 \u04b3\u0430\u043b \u043d\u0430\u043c\u0443\u0434:\n\u0417\u0438\u043d\u0434\u0430 \u0433\u04ef\u0440\u043e\u043d\u0430\u043d\u0434 \u043e\u043d \u0431\u0435\u0447\u043e\u0440\u0430\u0440\u043e.\n\u0411\u043e\u0439\u04b3\u043e\u044e \u043f\u0438\u0440\u04b3\u043e\n\u0440\u043e\u0437\u04e3 \u0448\u0443\u0434\u0430\u043d\u0434\n\u0411\u0430\u0440 \u0447\u0443\u043d\u0438\u043d \u044f\u043a \u04b3\u0443\u043a\u043c\u0438 \u043e\u043d \u0433\u0443\u0440\u0433\u0438 \u0434\u0443\u043f\u043e.\n\u0414\u0430\u04b3\u0448\u0430\u0442\u043e\u0432\u0430\u0440 \u0431\u0443\u0434 \u0447\u0443\u043d\u0438\u043d \u0441\u043e\u0430\u0442, \u0432\u0430\u043b\u0435\n\u041a\u0430\u0440\u0434 \u0432\u0430\u0439 \u0431\u0435\u0434\u043e\u0440 \u043c\u0430\u0440\u0434\u0443\u043c\u0440\u043e \u0437\u0438 \u0445\u043e\u0431.\n\u0411\u0430\u0440 \u0441\u0443\u043e\u043b\u0438 \u0445\u0435\u0448 \u0434\u0430\u0440 \u043e\u043d \u0442\u0438\u0440\u0430\u0440\u04ef\u0437\n\u0401\u0444\u0442 \u043c\u0430\u0440\u0434\u0443\u043c \u043f\u0443\u0440\u0440\u0430\u0432\u0443 \u0440\u0430\u0432\u0448\u0430\u043d \u04b7\u0430\u0432\u043e\u0431.\n\u0414\u0438\u0434 \u0431\u043e \u0447\u0430\u0448\u043c\u0438 \u0442\u0430\u0440\u0438 \u0445\u0443\u0434 \u04b3\u0430\u0440 \u044f\u043a\u0435,\n\u041a\u0438 \u0434\u0430\u0440 \u043e\u043d \u0441\u043e\u0430\u0442 \u0431\u0430\u0440\u043e\u0438 \xab\u0411\u043e\u043b\u0448\u0435\u0432\u043e\u0439\xbb\n\u041a\u0430\u043c\u0431\u0430\u0493\u0430\u043b\u04b3\u043e \u0430\u0448\u043a\u0438 \u0445\u0443\u0434 \u043c\u0435\u0440\u0435\u0445\u0442\u0430\u043d\u0434,\n\u041b\u0435\u043a \u0445\u0430\u043d\u0434\u0438\u0434\u0430\u043d\u0434 \u043f\u0438\u0440\u0443 \u043c\u0438\u0440\u0443 \u0431\u043e\u0439.\n\u041c\u0430\u044a\u043d\u0438\u0438 \u0431\u0438\u0441\u0451\u0440\u0438\u0438 \xab\u041b\u0435\u043d\u0438\u043d\xbb, \xab\u0411\u043e\u043b\u0448\u0435\u0432\u043e\u0439\xbb\n\u0413\u0430\u0448\u0442 \u0440\u0430\u0432\u0448\u0430\u043d \u0434\u0430\u0440 \u0434\u0438\u043b\u0438 \u0431\u0435\u0447\u043e\u0440\u0430\u0433\u043e\u043d,\n\u04b2\u0430\u0440 \u043a\u04e3 \u0448\u0443\u0434 \u0431\u0435\u0434\u043e\u0440, \u0451\u0440\u0443 \u0445\u0435\u0448\u0440\u043e\n\u041c\u0435\u043a\u0443\u043d\u0430\u0434 \u0431\u0435\u0434\u043e\u0440 \u0430\u0437 \u0445\u043e\u0431\u0438 \u0433\u0430\u0440\u043e\u043d.\n\u0420\u0430\u0444\u0442 \u043e\u043d \u0444\u0443\u0440\u0441\u0430\u0442, \u043a\u0438 \u0431\u043e \u0437\u0430\u0432\u049b\u0438 \u043a\u0430\u043b\u043e\u043d\n\u0413\u04ef\u0448 \u043c\u0435\u0434\u043e\u0434\u0435\u043c \u0431\u0430\u0440 \u0430\u0444\u0441\u043e\u043d\u0430\u04b3\u043e,\n\u0411\u0430\u04b3\u0440\u0438 \u043c\u043e \u0434\u0430\u0432\u0440\u043e\u043d \u04b3\u0438\u043a\u043e\u044f\u0442 \u043c\u0435\u043d\u0430\u043c\u0443\u0434.\n\u0418\u043d\u0447\u0443\u043d\u0438\u043d \u043f\u0443\u0440\u0432\u0430\u04b3\u043c\u0443 \u043c\u0443\u0434\u04b3\u0438\u0448 \u049b\u0438\u0441\u0441\u0430\u04b3\u043e\n\u0413\u04ef\u0448 \u043c\u0435\u0434\u043e\u0434\u0435\u043c\u0443 \u043c\u0435\u043f\u0438\u043d\u0434\u043e\u0448\u0442\u0435\u043c:\n\u0411\u0430\u0447\u0447\u0430 \u043c\u043e \u043d\u0435, \u04b3\u0430\u0440 \u044f\u043a\u0435 \u043c\u0430\u0440\u0434\u0438 \u043a\u0430\u043b\u043e\u043d,\n\u0410\u049b\u043b\u0438 \u043c\u043e \u04b3\u0430\u043c, \u0433\u04ef\u0438\u0451, \u043a\u0438 \u043c\u0435\u0444\u0443\u0437\u0443\u0434.\n\u041c\u0430\u044a\u043d\u0438\u0438 \u0448\u043e\u0434\u0438\u044e \u0493\u0430\u043c \u04b3\u0430\u043c \u0448\u0443\u0434 \u0430\u0451\u043d\u2026")
B.a9N=new A.a("6a83b06f-731b-4092-a204-1ad4f1bbea2d","a7feaa09-c83f-44f2-a69e-0a46ba957dbc","\u041c\u04ef\u0441\u0430\u0444\u0435\u0434\u0435 \u0431\u0443\u0434 \u0434\u0430\u0440 \u049b\u0438\u0448\u043b\u043e\u049b\u0438 \u043c\u043e,","\u041c\u04ef\u0441\u0430\u0444\u0435\u0434\u0435 \u0431\u0443\u0434 \u0434\u0430\u0440 \u049b\u0438\u0448\u043b\u043e\u049b\u0438 \u043c\u043e,\n\u0421\u0438\u043d\u043d\u0443 \u0441\u043e\u043b\u0430\u0448 \u0431\u0435\u0448\u0442\u0430\u0440 \u0430\u0437 \u0448\u0430\u0441\u0442 \u0431\u0443\u0434.\n\u0420\u04ef\u0437\u0443 \u0448\u0430\u0431 \u0434\u0430\u0440 \u0445\u043e\u043d\u0430\u0438 \u0431\u043e\u0451\u043d\u0438 \u0434\u0435\u04b3\n\u041d\u0438\u043c\u0441\u0435\u0440\u0443 \u0433\u0443\u0448\u043d\u0430 \u043c\u0435\u04b3\u043d\u0430\u0442 \u043c\u0435\u043d\u0430\u043c\u0443\u0434.\n\u041d\u043e\u043c\u0438 \u04ef \u0430\u0441\u043b\u0430\u043d \u0410\u0442\u043e\u0431\u0435\u043a \u0431\u0443\u0434\u0430\u0430\u0441\u0442.\n\u049a\u043e\u0437\u0438\u0435, \u043a\u0438 \u0432\u0430\u0439 \u0431\u0430 \u04ef \u043c\u0435\u043a\u0430\u0440\u0434 \u043a\u043e\u0440\n\xab\u0411\u0435\u043a\xbb \u043b\u043e\u0437\u0438\u043c \u043d\u0435\u0441\u0442, \u0431\u0430\u0440 \u0442\u0443 \u0431\u0430\u0441 \xab\u0410\u0442\u043e\xbb!\n\u0413\u0443\u0444\u0442\u0430 \u043d\u043e\u043c\u0430\u0448\u0440\u043e \u043d\u0430\u043c\u0443\u0434\u0430\u0441\u0442 \u0438\u0445\u0442\u0438\u0441\u043e\u0440.\n\u0413\u0430\u0448\u0442 \u0432\u043e\u049b\u0438\u0444 \u0447\u0443\u043d \u0430\u0437 \u0438\u043d \u043a\u0438\u0440\u0434\u043e\u0440\u0438 \u0432\u0430\u0439,\n\u0417\u0430\u0432\u049b \u043a\u0430\u0440\u0434\u0430 \u043c\u0438\u0440\u04b3\u0430\u0437\u043e\u0440\u0438 \u043e\u043d \u0434\u0438\u0451\u0440,\n\xab\u0410\xbb \u0431\u0430\u0440\u043e\u0438 \u0442\u0443 \u0447\u04e3 \u043b\u043e\u0437\u0438\u043c, \xab\u0422\u043e\xbb \u0431\u0430\u0441 \u0430\u0441\u0442! \xbb\n\u0413\u0443\u0444\u0442\u0430 \u043d\u043e\u043c\u0430\u0448\u0440\u043e \u043d\u0430\u043c\u0443\u0434\u0430\u0441\u0442 \u0438\u0445\u0442\u0438\u0441\u043e\u0440.\n\u0425\u0430\u043d\u0434\u0430\u043e\u0432\u0430\u0440 \u0438\u043d \u0441\u0443\u0445\u0430\u043d\u04b3\u043e, \u043b\u0435\u043a \u0422\u043e:\n\xab\u041c\u0430\u0439\u043b\u0430\u0442\u043e\u043d, \u2013 \u0433\u0443\u0444\u0442\u0430\u0441\u0442, - \u044f\u043a \u043d\u043e\u043c\u0438 \u0434\u0438\u0433\u0430\u0440\n\u041d\u0438\u0437 \u0434\u043e\u0440\u0430\u043c \u2013\u041a\u0430\u043c\u0431\u0430\u0493\u0430\u043b, - \u043e\u043d \u043d\u043e\u043c\u0438 \u043c\u0430\u043d,\n\u04ee \u0431\u0430 \u043c\u0430\u043d \u043c\u0435\u0440\u043e\u0441 \u043c\u043e\u043d\u0434\u0430\u0441\u0442 \u0430\u0437 \u043f\u0430\u0434\u0430\u0440,\n\u041a\u0430\u043c\u0431\u0430\u0493\u0430\u043b! \u0418\u043d \u043d\u043e\u043c\u0438 \u043c\u043e\u0440\u043e \u04b3\u0435\u04b7 \u043a\u0430\u0441\n\u041d\u0435\u0441\u0442 \u049b\u043e\u0434\u0438\u0440, \u043a\u0438 \u043d\u0430\u043c\u043e\u044f\u0434 \u0438\u0445\u0442\u0438\u0441\u043e\u0440!\n\u0411\u043e \u04b3\u0430\u043c\u0438\u043d \u044f\u043a \u043d\u043e\u043c\u0438 \u043c\u0435\u0440\u043e\u0441\u04e3 \u043c\u0430\u0440\u043e\n\u041c\u0435\u0448\u0438\u043d\u043e\u0441\u0430\u043d\u0434 \u043e\u0434\u0430\u043c\u043e\u043d\u0438 \u04b3\u0430\u0440 \u0434\u0438\u0451\u0440\u2026\xbb")
B.acE=new A.a("bb89a79f-e0b5-4c73-a4ed-74c3da1d832d","e9eed14e-8d54-4182-8d4e-731896fb30e0","\u0414\u0430\u043c\u0435 \u043a\u0438 \u0434\u0430\u0440 \u0434\u0438\u043b\u0430\u0442 \u043c\u0435\u04b3\u0440\u0438 \u0412\u0430\u0442\u0430\u043d ...","\u0414\u0430\u043c\u0435 \u043a\u0438 \u0434\u0430\u0440 \u0434\u0438\u043b\u0430\u0442 \u043c\u0435\u04b3\u0440\u0438 \u0412\u0430\u0442\u0430\u043d \u0445\u0443\u0440\u0448\u0435\u0434 \u043c\u0435\u043f\u0430\u0440\u0432\u0430\u0440\u0434,\n\u0414\u0430\u043c\u0435 \u043a\u0438 \u04b7\u043e\u043d\u0438 \u0434\u0430\u0440 \u043b\u0430\u0431 \u043e\u043b\u0430\u043c\u0438 \u04b7\u043e\u0432\u0438\u0434 \u043c\u0435\u043f\u0430\u0440\u0432\u0430\u0440\u0434,\n\u0414\u0430\u043c\u0435 \u043a\u0438 \u0431\u043e\u0440\u0438 \u043e\u0445\u0438\u0440 \u0451\u0434 \u043a\u0430\u0440\u0434\u04e3 \u0451\u0440\u0438 \u04b7\u043e\u043d\u0430\u0442\u0440\u043e,\n\u0427\u0430\u0440\u043e \u0431\u043e \u0445\u0443\u043d \u043d\u0430\u043a\u0430\u0440\u0434\u04e3 \u0441\u0430\u0431\u0442 \u043d\u043e\u043c\u0430\u0442\u0440\u043e \u0431\u0430 \u0440\u04ef\u0439\u0438 \u0441\u0430\u043d\u0433,\n\u041a\u0438 \u0442\u043e \u0441\u0430\u0440\u043b\u0430\u0432\u04b3\u0430\u0438 \u0448\u0435\u044a\u0440\u0430\u043c \u043a\u0443\u043d\u0430\u043c \u0438\u043c\u0440\u04ef\u0437 \u043d\u043e\u043c\u0430\u0442\u0440\u043e?\n\u041d\u0430\u0434\u043e\u043d\u0430\u043c \u0430\u0437 \u043a\u0443\u04b7\u043e\u04e3,\u043f\u043e\u0440\u0430\u0438 \u049b\u0430\u043b\u0431\u0438 \u043a\u04e3 \u04b3\u0430\u0441\u0442\u04e3 \u0442\u0443?\n\u0427\u0430\u0440\u043e\u0493\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u043e\u043d\u0438\u0438 \u043a\u0430\u0434\u043e\u043c\u0438\u043d \u043c\u043e\u0434\u0430\u0440 \u0430\u0441\u0442\u04e3 \u0442\u0443?\n\u041a\u0430\u0434\u043e\u043c\u0438\u043d \u0445\u043e\u043c\u0430\u043a\u0430\u0448\u0440\u043e \u0448\u043e\u04b3\u0431\u0430\u0439\u0442\u0438 \u0434\u043e\u0441\u0442\u043e\u043d\u04e3 \u0442\u0443?\n\u041d\u0430\u0434\u043e\u043d\u0430\u043c \u0430\u0437 \u043a\u0443\u04b7\u043e \u043e\u043c\u04ef\u0445\u0442\u04e3 \u0438\u043d \u0441\u043e\u043d \u0431\u0443\u0437\u0443\u0440\u0433\u0438\u0440\u043e,\n\u041a\u0438 \u0431\u043e \u0438\u043d \u0437\u0430\u0440\u0440\u0430\u0433\u04e3 \u0434\u0430\u0440 \u043f\u0435\u0448\u0438 \u0447\u0430\u0448\u043c\u043e\u043d\u0430\u043c \u04b7\u0430\u04b3\u043e\u043d\u04e3 \u0442\u0443?")
B.aqp=new A.a("1be10361-7743-4fd1-8443-2d567aed07c2","e9eed14e-8d54-4182-8d4e-731896fb30e0","\u041e\u04b3, \u043c\u043e\u0434\u0430\u0440!","\u041e\u04b3, \u043c\u043e\u0434\u0430\u0440!\n\u0413\u0430\u0440\u0447\u0438 \u043e\u04b3\u0438 \u0441\u0430\u0440\u0434 \u049b\u0430\u043b\u0431\u0438 \u0433\u0430\u0440\u043c\u0440\u043e \u0431\u0435\u0433\u043e\u043d\u0430 \u0431\u0443\u0434,\n\u0418\u043d \u0441\u0430\u0444\u0430\u0440 \u0431\u043e \u043e\u04b3 \u0434\u043e\u0434\u0430\u043c \u0448\u0435\u044a\u0440\u0438 \u0445\u0443\u0434\u0440\u043e \u0438\u0431\u0442\u0438\u0434\u043e.\n\u041e\u04b3 \u0441\u0430\u0440\u0434 \u0430\u0441\u0442\u0443 \u0432\u0430\u043b\u0435 \u0443\u043c\u043c\u0435\u0434 \u0434\u043e\u0440\u0430\u043c \u0434\u0430\u0440 \u0434\u0438\u043b\u0430\u043c\n\u041c\u0435\u04b3\u0440\u0438 \u0442\u0443 \u0431\u0430\u0445\u0448\u0430\u0434 \u0431\u0430 \u0448\u0435\u044a\u0440\u0430\u043c \u0433\u0430\u0440\u043c\u0438\u0438 \u0445\u0443\u0440\u0448\u0435\u0434\u0440\u043e.\n\u0412\u0430\u049b\u0442\u0438 \u0442\u0438\u0444\u043b\u0438\u044f\u043c \u0447\u0443 \u0434\u0438\u043b \u0440\u04ef\u0439\u0438 \u043a\u0430\u0444\u0430\u0442 \u0431\u0430\u0440\u0434\u043e\u0448\u0442\u0430,\n\u0417\u0438\u043d\u0434\u0430\u0433\u043e\u043d\u04e3 \u0434\u043e\u0434\u0438\u044f\u043c \u0431\u043e \u049b\u0430\u0442\u0440\u0430\u0438 \u0448\u0438\u0440\u0438 \u0441\u0430\u0444\u0435\u0434.\n\u041b\u0435\u043a \u0438\u043d \u0434\u0430\u043c \u043c\u0430\u043d \u0442\u0443\u0440\u043e \u0440\u04ef\u0439\u0438 \u043a\u0430\u0444\u0430\u043c \u0431\u0430\u0440\u0434\u043e\u0448\u0442\u0430,\n\u041c\u0435\u0431\u0430\u0440\u0430\u043c \u0431\u043e \u043e\u043d \u0440\u0430\u04b3\u0435, \u043a\u0438 \u043e\u043d \u043d\u0430\u0434\u043e\u0440\u0430\u0434 \u0431\u043e\u0437\u0434\u0438\u0434.\n\u041c\u0430\u043d \u0433\u0443\u0441\u0435\u043b\u0430\u0442 \u043c\u0435\u043a\u0443\u043d\u0430\u043c, \u0430\u043c\u043c\u043e \u043d\u0430\u0434\u043e\u0440\u0430\u043c \u0431\u043e\u0432\u0430\u0440\u04e3,\n\u041a-\u0430\u0437 \u0431\u0430\u0440\u0430\u043c \u0442\u0443 \u043c\u0435\u0440\u0430\u0432\u04e3, \u0434\u0438\u0433\u0430\u0440 \u043d\u0430\u043c\u0435\u0431\u0438\u043d\u0430\u043c \u0442\u0443\u0440\u043e.\n\u041c\u0435\u0440\u0430\u0432\u04e3 \u0447\u0443\u043d \u043d\u0443\u0440\u04b3\u043e\u0438 \u043e\u0444\u0442\u043e\u0431\u0438 \u0434\u0430\u0440 \u0493\u0443\u0440\u0443\u0431,\n\u041d\u0435\u0441\u0442 \u0437\u04ef\u0440\u0435 \u0431\u043e\u0437 \u0434\u043e\u0440\u0430\u043c, \u0434\u0430\u0440 \u0434\u0438\u043b\u0438 \u0445\u0443\u0434 \u04b7\u043e \u043a\u0443\u043d\u0430\u043c.\n\u0414\u0430\u0440 \u0430\u0434\u043e\u0438 \u049b\u0430\u0440\u0437\u0438 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u04e3, \u0430\u0451 \u043c\u043e\u0434\u0430\u0440, \u0434\u0430\u043c\u0435\n\u0411\u0430\u0445\u0448 \u0437\u04ef\u0440\u0430\u043c, \u0442\u043e \u0442\u0443\u0440\u043e \u0434\u0430\u0440 \u0448\u0435\u044a\u0440\u0438 \u0445\u0443\u0434 \u044d\u04b3\u0451 \u043a\u0443\u043d\u0430\u043c.")
B.anS=new A.a("6928cdd4-c5ad-4603-a801-58804a3e4a62","e9eed14e-8d54-4182-8d4e-731896fb30e0","\u0411\u0430 \u043a\u0443\u043d\u04b7\u0435 \u04b7\u0430\u043c\u044a \u0433\u0430\u0448\u0442\u0430 \u043c\u04ef\u0441\u0430\u0444\u0435\u0434\u043e\u043d,","\u0411\u0430 \u043a\u0443\u043d\u04b7\u0435 \u04b7\u0430\u043c\u044a \u0433\u0430\u0448\u0442\u0430 \u043c\u04ef\u0441\u0430\u0444\u0435\u0434\u043e\u043d,\n\u04b2\u0430\u043b\u043e\u0432\u0430\u0442 \u043c\u0435\u0431\u0430\u0440\u0430\u043d\u0434 \u0430\u0437 \u043d\u0443\u0440\u0438 \u0445\u0443\u0440\u0448\u0435\u0434.\n(\u0410\u04b7\u0430\u0431 \u0434\u0443\u043d\u0451\u0441\u0442 \u043f\u0443\u0440\u0441\u0430\u0432\u0434\u043e\u0432\u0443 \u043f\u0443\u0440\u0448\u04ef\u0440,\n\u0410\u04b7\u0430\u0431 \u0434\u0443\u043d\u0451\u0441\u0442 \u0437\u0435\u0431\u043e\u0432\u0443 \u043f\u0443\u0440\u0443\u043c\u0435\u0434.)\n\u0413\u0443\u0437\u0430\u0448\u0442\u0438 \u0443\u043c\u0440\u0438 \u0448\u0438\u0440\u0438\u043d \u0431\u0435\u043d\u0438\u0448\u043e\u043d \u043d\u0435\u0441\u0442,\n\u041a\u0438 \u04b3\u0430\u0440 \u043e\u0436\u0430\u043d\u0433 \u0440\u0430\u043c\u0437\u0438 \u049b\u0430\u04b3\u0440\u0430\u043c\u043e\u043d\u0438\u0441\u0442,\n\u0421\u0430\u0444\u0435\u0434\u0438\u04b3\u043e\u0438 \u043c\u04ef\u0439\u0438 \u043c\u04ef\u0441\u0430\u0444\u0435\u0434\u043e\u043d\n\u0417\u0438 \u0438\u0448\u049b\u0438 \u0440\u04ef\u0437\u0433\u043e\u0440\u043e\u043d \u0434\u043e\u0441\u0442\u043e\u043d\u0435\u0441\u0442.\n\n\u0414\u0443 \u0447\u0430\u0448\u043c\u0438 \u0445\u0430\u0441\u0442\u0430\u0432\u0443 \u0431\u0435\u043d\u0443\u0440\u0438 \u043e\u043d\u04b3\u043e\n\u0414\u0443 \u0447\u0430\u0448\u043c\u0438 \u0440\u0430\u0432\u0448\u0430\u043d\u0438 \u041c\u043e\u0434\u0430\u0440-\u0412\u0430\u0442\u0430\u043d \u0431\u0443\u0434,\n\u0417\u0430\u043c\u043e\u043d\u0435 \u0434\u0430\u0441\u0442\u04b3\u043e\u0438 \u0441\u0430\u0440\u0434\u0443 \u043b\u0430\u0440\u0437\u043e\u043d\n\u0414\u0430\u0440 \u0438\u043d \u043a\u04ef\u04b3\u0441\u043e\u0440 \u043f\u0430\u043d\u0434\u0438 \u041a\u04ef\u04b3\u043a\u0430\u043d \u0431\u0443\u0434.\n\n\u0411\u0438\u0434\u0438\u0434\u0430 \u0431\u0435\u0432\u0430\u0444\u043e\u0438\u04b3\u043e\u0438 \u043e\u043b\u0430\u043c,\n\u0424\u0430\u049b\u0430\u0442 \u0430\u0437 \u04b7\u043e\u043d \u0432\u0430\u0444\u043e \u043a\u0430\u0440\u0434\u0430\u043d\u0434 \u043c\u043e\u0440\u043e,\n\u0410\u0433\u0430\u0440\u0447\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u04e3 \u0441\u0430\u0445\u0442\u0443 \u0433\u0430\u0440\u043e\u043d \u0431\u0443\u0434,\n\u0411\u0430 \u043f\u0430\u0439\u0440\u043e\u04b3\u0438 \u0448\u0430\u0440\u0430\u0444 \u0431\u0443\u0440\u0434\u0430\u043d\u0434 \u043c\u043e\u0440\u043e.\n\n\u0424\u0443\u0440\u04ef \u0431\u0443\u0440\u0434\u0430 \u0493\u0430\u043c\u0443 \u0430\u043d\u0434\u04ef\u04b3\u0438 \u0430\u0439\u0451\u043c,\n\u0411\u0430 \u0440\u04ef\u0439\u0438 \u0434\u0443\u0448\u043c\u0430\u043d\u0438 \u0434\u0443\u043d \u0445\u0430\u043d\u0434\u0430 \u043a\u0430\u0440\u0434\u0430\u043d\u0434.\n\u0411\u0430 \u0434\u0443\u043d\u0451 \u0434\u043e\u0434\u0430 \u0434\u0430\u0440\u0441\u0438 \u0441\u0430\u0440\u0431\u0430\u043b\u0430\u043d\u0434\u04e3,\n\u0417\u0438 \u0431\u043e\u0440\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u04e3 \u0441\u0430\u0440 \u0445\u0430\u043c \u043d\u0430\u043a\u0430\u0440\u0434\u0430\u043d\u0434.\n\n\u0411\u0430 \u043c\u043e\u043b\u0443 \u043c\u0443\u043b\u043a\u0438 \u043e\u043b\u0430\u043c \u0434\u0438\u043b \u043d\u0430\u0434\u043e\u0434\u0430,\n\u0492\u0430\u043d\u04e3 \u0431\u0443\u0434\u0430\u043d\u0434 \u0430\u0437 \u044f\u043a \u0431\u0430\u0439\u0442\u0438 \u04b2\u043e\u0444\u0438\u0437,\n\u0411\u0430 \u0438\u043d \u0441\u0435\u04b3\u0440\u0443 \u0431\u0430 \u0438\u043d \u044d\u044a\u04b7\u043e\u0437\u0438 \u04b3\u0430\u0441\u0442\u04e3\n\u041a\u0443\u043d\u0443\u043d \u0434\u0430\u0440 \u043d\u0430\u0437\u0434\u0438 \u043f\u0438\u0440\u04e3 \u043c\u043e\u043d\u0434\u0430 \u043e\u04b7\u0438\u0437.\n\n\u0412\u0430\u043b\u0435 \u0430\u0437 \u0443\u043c\u0440\u0443 \u0430\u0437 \u0434\u0443\u043d\u0451 \u0440\u0438\u0437\u043e\u044f\u043d\u0434,\n\u0424\u0438\u0434\u043e\u0438 \u0440\u04ef\u0437\u0433\u043e\u0440\u0438 \u0431\u0435\u0431\u0430\u04b3\u043e\u044f\u043d\u0434.\n\u0414\u0443\u043e \u0433\u04ef\u044f\u043d\u0434 \u0441\u0443\u0431\u04b3\u0438 \u0431\u043e\u0441\u0430\u0444\u043e\u0440\u043e,\n\u0421\u0430\u043d\u043e \u0445\u043e\u043d\u0430\u043d\u0434 \u0434\u0430\u0432\u0440\u0438 \u0434\u0438\u043b\u043a\u0443\u0448\u043e\u0440\u043e.\n\n\u0411\u0430 \u043a\u04ef\u04b3\u0438 \u0431\u0430\u0440\u0444\u043f\u04ef\u0448\u0438 \u049b\u0443\u0440\u0441\u0438 \u0445\u0443\u0440\u0448\u0435\u0434\n\u041d\u0430\u0437\u0430\u0440 \u0441\u043e\u0437\u0430\u043d\u0434 \u0431\u043e \u043c\u0435\u04b3\u0440\u0443 \u043c\u0443\u04b3\u0430\u0431\u0431\u0430\u0442.\n\u0492\u0430\u043d\u0438\u043c\u0430\u0442 \u0431\u043e\u0448\u0430\u0434 \u0438\u043d \u0434\u0443\u043d\u0451 \u0431\u0430 \u043e\u043d\u04b3\u043e,\n\u04b2\u0430\u043c \u043e\u043d\u04b3\u043e\u044f\u043d\u0434 \u0434\u0430\u0440 \u0434\u0443\u043d\u0451 \u0493\u0430\u043d\u0438\u043c\u0430\u0442...")
