B.aaw=new A.a("cad89632-518f-41de-b728-8f9d0d5f9f6b","9cc6b7f2-3aa2-4ecf-abec-17eec77b198b","\u0428\u043e\u04b3\u043e, \u0437\u0438 \u043c\u0430\u043d \u0433\u0430\u0440\u043e\u043d \u0447\u04e3 \u0431\u0430\u0440 \u0445\u043e\u04b3\u0430...","\u0428\u043e\u04b3\u043e, \u0437\u0438 \u043c\u0430\u043d \u0433\u0430\u0440\u043e\u043d \u0447\u04e3 \u0431\u0430\u0440 \u0445\u043e\u04b3\u0430\u0434 \u0445\u043e\u0441\u0442?\n\u0412-\u0430\u0437 \u043c\u0430\u0441\u0442\u0438\u0438 \u0431\u0435\u043a\u0430\u0440\u043e\u043d \u0447\u04e3 \u0431\u0430\u0440 \u0445\u043e\u04b3\u0430\u0434 \u0445\u043e\u0441\u0442?\n\u0428\u0430\u04b3 \u043c\u0430\u0441\u0442\u0443 \u04b7\u0430\u04b3\u043e\u043d \u0445\u0430\u0440\u043e\u0431\u0443 \u0434\u0443\u0448\u043c\u0430\u043d \u043f\u0430\u0441\u0443 \u043f\u0435\u0448!\n\u041f\u0430\u0439\u0434\u043e\u0441\u0442, \u043a\u0438 \u0437-\u0438\u043d \u043c\u0438\u0451\u043d \u0447\u04e3 \u0431\u0430\u0440 \u0445\u043e\u04b3\u0430\u0434 \u0445\u043e\u0441\u0442?")
B.amo=new A.a("5fdeb1b3-fb0b-44a5-9f2b-ef19a7a46009","3ec91317-fcfe-4960-9ca0-fd87f3e96875","\u041c\u0430\u043d\u0435\u04b3 \u0434\u0430\u0440 \u043c\u0438\u0451\u043d \u0440\u043e\u0437 \u0431\u043e \u04b3\u0430\u0440 \u043a\u0430\u0441\u0435...","\u041c\u0430\u043d\u0435\u04b3 \u0434\u0430\u0440 \u043c\u0438\u0451\u043d \u0440\u043e\u0437 \u0431\u043e \u04b3\u0430\u0440 \u043a\u0430\u0441\u0435,\n\u041a\u0438 \u04b7\u043e\u0441\u0443\u0441 \u04b3\u0430\u043c\u043a\u043e\u0441\u0430 \u0434\u0438\u0434\u0430\u043c \u0431\u0430\u0441\u0435.")
B.abi=new A.a("87b9cbcf-0f33-4b25-8b71-7cc1c24c0c20","e9eed14e-8d54-4182-8d4e-731896fb30e0","\u0414\u0430\u0440 \u0441\u0430\u0440\u0438 \u049b\u0430\u0431\u0440\u0438 \u0442\u0443 \u0433\u0438\u0440\u044f\u0434 \u0430\u0437 \u04b7\u0443\u0434...","\u0414\u0430\u0440 \u0441\u0430\u0440\u0438 \u049b\u0430\u0431\u0440\u0438 \u0442\u0443 \u0433\u0438\u0440\u044f\u0434 \u0430\u0437 \u04b7\u0443\u0434\u043e\u0438\u04b3\u043e \u0431\u0430\u04b3\u043e\u0440,\n\u041d\u043e\u043b\u0430 \u0445\u0435\u0437\u0430\u0434 \u0430\u0437 \u0434\u0438\u043b\u0438 \u04b3\u0430\u0440 \u0441\u0430\u043d\u0433\u0438 \u0445\u043e\u043c\u04ef\u0448\u0438 \u04b2\u0438\u0441\u043e\u0440.\n\u041c\u0430\u043d \u0447\u0443 \u0433\u04ef\u044f\u043c, \u043a\u0438 \u0442\u0443 \u0445\u0443\u0434 \u0431\u043e\u0440\u0435 \u0431\u0430 \u04b3\u0430\u0441\u0440\u0430\u0442 \u0433\u0443\u0444\u0442\u0430\u04e3:\n\xab\u0427\u0430\u0448\u043c\u0438 \u043c\u0430\u043d \u0445\u043e\u04b3\u0430\u0434, \u043a\u0438 \u0431\u0438\u043d\u0430\u0434 \u043d\u0430\u0432\u0431\u0430\u04b3\u043e\u0440\u0438 \u0431\u0435\u0448\u0443\u043c\u043e\u0440\xbb.")
B.amh=new A.a("d027cd9f-94e8-4e9c-af49-e25404d99001","41c86281-0423-4553-91e8-5f8c298ed40f","\u041a\u0430\u0441\u0435, \u043a-\u04ef \u0431\u043e\u0432\u0430\u0440\u0438\u0438 \u0445\u0430\u043b\u049b\u0440\u043e \u0430\u0440\u0437\u0430\u043d...","\u041a\u0430\u0441\u0435, \u043a-\u04ef \u0431\u043e\u0432\u0430\u0440\u0438\u0438 \u0445\u0430\u043b\u049b\u0440\u043e \u0430\u0440\u0437\u0430\u043d\u0434\u0430 \u043c\u0435\u0433\u0430\u0440\u0434\u0430\u0434,\n\u0411\u0430 \u04b3\u0430\u0440 \u043a\u0430\u0441 \u0434\u04ef\u0441\u0442\u0440\u04ef, \u04b3\u0430\u0440 \u0445\u043e\u043d\u0430\u0440\u043e \u0437\u0435\u0431\u0430\u043d\u0434\u0430 \u043c\u0435\u0433\u0430\u0440\u0434\u0430\u0434.")
B.an4=new A.a("480500c5-d6c2-4f18-8c23-8b3adfd5119b","41c86281-0423-4553-91e8-5f8c298ed40f","\u0422\u0438\u0444\u043b \u043c\u043e\u043d\u0434\u0430\u043c \u0430\u0437 \u0442\u0443, \u043c\u043e\u0434\u0430\u0440, \u0440\u04ef\u0439\u0438...","\u0422\u0438\u0444\u043b \u043c\u043e\u043d\u0434\u0430\u043c \u0430\u0437 \u0442\u0443, \u043c\u043e\u0434\u0430\u0440, \u0440\u04ef\u0439\u0438 \u0442\u0443 \u0434\u0430\u0440 \u0451\u0434 \u043d\u0435\u0441\u0442,\n\u049a\u043e\u043c\u0430\u0442\u0438 \u0442\u0443, \u0447\u0430\u0448\u043c\u0438 \u0442\u0443, \u0430\u0431\u0440\u04ef\u0439\u0438 \u0442\u0443 \u0434\u0430\u0440 \u0451\u0434 \u043d\u0435\u0441\u0442.\n\u0414\u0430\u0440 \u0441\u0443\u0440\u043e\u0493\u0430\u0442 \u043c\u0435\u0437\u0430\u043d\u0430\u043c \u0445\u0443\u0434\u0440\u043e \u0431\u0430 \u04b3\u0430\u0440 \u044f\u043a \u043a\u04ef\u044e \u0434\u0430\u0440,\n\u0427\u0443\u043d\u043a\u0438 \u0442\u043e \u0438\u043c\u0440\u04ef\u0437, \u043c\u043e\u0434\u0430\u0440, \u043a\u04ef\u0439\u0438 \u0442\u0443 \u0434\u0430\u0440 \u0451\u0434 \u043d\u0435\u0441\u0442.")
B.ahc=new A.a("ae0cda5a-7c32-4fb9-bcc0-9ade23600c12","41c86281-0423-4553-91e8-5f8c298ed40f","\u0428\u0435\u044a\u0440 \u0433\u04ef\u044f\u043c, \u043e\u044f\u0434 \u0430\u0437 \u0448\u0435\u044a\u0440\u0430\u043c \u0441\u0430\u0434\u043e\u0439...","\u0428\u0435\u044a\u0440 \u0433\u04ef\u044f\u043c, \u043e\u044f\u0434 \u0430\u0437 \u0448\u0435\u044a\u0440\u0430\u043c \u0441\u0430\u0434\u043e\u0439\u0438 \u043c\u043e\u0434\u0430\u0440\u0430\u043c,\n\u0414\u0435\u04b3\u0430 \u0433\u04ef\u044f\u043c, \u0431\u0430\u0440 \u0441\u0430\u0440\u0430\u043c \u043e\u044f\u0434 \u04b3\u0430\u0432\u043e\u0439\u0438 \u043c\u043e\u0434\u0430\u0440\u0430\u043c.\n\u0421\u043e\u043b\u0445\u04ef\u0440\u0434\u0430 \u0433\u0430\u0440 \u0437\u0430\u043d\u0435 \u0440\u04ef\u0437\u0435 \u0434\u0443\u0447\u043e\u0440 \u043e\u044f\u0434 \u0431\u0430 \u043c\u0430\u043d,\n\u0413\u04ef\u044f\u043c\u0430\u0448, \u043a\u0438 \u0431\u043e\u0448, \u0442\u043e \u04b3\u0430\u0441\u0442\u0430\u043c, \u0431\u0430 \u04b7\u043e\u0439\u0438 \u043c\u043e\u0434\u0430\u0440\u0430\u043c!")
B.agq=new A.a("5c10adc3-8508-44b1-a06d-2278a50a7239","41c86281-0423-4553-91e8-5f8c298ed40f","\u0428\u0430\u0431\u0435, \u043a\u0438 \u0442\u043e \u0441\u0430\u04b3\u0430\u0440 \u0431\u0435\u0434\u043e\u0440 \u0431\u0443\u0434\u0430\u043c,","\u0428\u0430\u0431\u0435, \u043a\u0438 \u0442\u043e \u0441\u0430\u04b3\u0430\u0440 \u0431\u0435\u0434\u043e\u0440 \u0431\u0443\u0434\u0430\u043c,\n\u041c\u0443\u0448\u0430\u0432\u0432\u0430\u0448, \u0442\u0430\u043d\u0433\u0434\u0438\u043b, \u043d\u043e\u0447\u043e\u0440 \u0431\u0443\u0434\u0430\u043c.\n\u041d\u0430\u0445\u0443\u0444\u0442\u0430\u043c, \u0434\u043e\u0448\u0442\u0430\u043c \u0443\u043c\u043c\u0435\u0434\u0432\u043e\u0440\u04e3,\n\u0414\u0438\u043b\u0430\u043c\u0440\u043e \u043c\u0435\u0444\u0438\u0448\u043e\u0440\u0438\u0434 \u0438\u043d\u0442\u0438\u0437\u043e\u0440\u04e3.\n\u0413\u0438\u0440\u0438\u0444\u0442\u0430 \u0434\u0443\u0434\u0438 \u0442\u0430\u043c\u043c\u043e\u043a\u0443 \u0433\u0443\u043b\u04ef\u044f\u043c,\n\u0425\u0430\u043c\u0438\u0434\u0430 \u043c\u04ef\u0439\u0438 \u0441\u0430\u0440 \u0442\u043e \u0447\u0430\u0448\u043c\u0443 \u0440\u04ef\u044f\u043c.\n\u0417\u0430\u0434\u0430\u043c \u0433\u04ef\u0433\u0438\u0440\u0434, \u043a\u0430\u0440\u0434\u0430\u043c \u0431\u043e\u0437 \u0445\u043e\u043c\u04ef\u0448,\n\u041f\u0430\u043f\u0438\u0440\u043e\u0441 \u0434\u0430\u0440\u0433\u0438\u0440\u043e\u043d\u0434\u0430\u043d \u0440\u0430\u0444\u0442 \u0430\u0437 \u04b3\u0443\u0448,\n\u049a\u0430\u0434\u0443 \u0431\u0430\u0440 \u0445\u043e\u043d\u0430\u0440\u043e \u0433\u0430\u0448\u0442\u0430\u043c, \u043d\u0438\u0448\u0430\u0441\u0442\u0430\u043c,\n\u0413\u0438\u0440\u0438\u0444\u0442\u0430\u043c \u0445\u043e\u043c\u0430 \u0431\u043e \u043b\u0430\u0440\u0437\u0430\u043d\u0434\u0430 \u0434\u0430\u0441\u0442\u0430\u043c.\n\u0414\u0438\u043b\u0430\u043c \u043c\u0435\u0445\u043e\u0441\u0442, \u043a\u0438 \u0448\u0435\u044a\u0440\u0435 \u043d\u0430\u0432\u0438\u0441\u0430\u043c,\n\u041d\u0430\u043c\u043e\u044f\u043c \u0448\u0430\u0440\u04b3\u0438 \u0434\u043e\u0441\u0442\u043e\u043d\u0430\u043c, \u04b3\u0430\u0434\u0438\u0441\u0430\u043c.\n\u0410\u0433\u0430\u0440\u0447\u04e3 \u0445\u043e\u043d\u0430 \u043e\u0440\u043e\u043c \u0430\u0441\u0442 \u0434\u0430\u0440 \u0448\u0430\u0431,\n\u0411\u0430 \u0448\u043e\u0438\u0440 \u04b7\u043e\u0439\u0438 \u0438\u043b\u04b3\u043e\u043c \u0430\u0441\u0442 \u0434\u0430\u0440 \u0448\u0430\u0431.\n\u041d\u0438\u0448\u0430\u0441\u0442\u0430\u043c, \u043b\u0435\u043a \u0447\u0438\u0437\u0435 \u04b3\u0430\u043c \u043d\u0430\u0433\u0443\u0444\u0442\u0430\u043c,\n\u04b2\u0430\u043c\u0430 \u0445\u0443\u0444\u0442\u0430\u043d\u0434, \u0442\u0430\u043d\u04b3\u043e \u043c\u0430\u043d \u043d\u0430\u0445\u0443\u0444\u0442\u0430\u043c.\n\u0427\u0430\u0440\u043e, \u043a\u0438 \u0434\u043e\u0448\u0442\u0430\u043c \u0443\u043c\u043c\u0435\u0434\u0432\u043e\u0440\u04e3,\n\u0411\u0430 \u0441\u04ef\u0439\u0438 \u0440\u043e\u04b3 \u0447\u0430\u0448\u043c\u0438 \u0438\u043d\u0442\u0438\u0437\u043e\u0440\u04e3.\n\u0427\u04e3 \u0445\u043e\u043c\u04ef\u0448 \u0430\u0441\u0442 \u043c\u0430\u043d\u0437\u0438\u043b \u0434\u0430\u0440 \u0434\u0438\u043b\u0438 \u0448\u0430\u0431,\n\u0428\u0443\u0434\u0430 \u0433\u04ef\u0451, \u043a\u0438 \u0433\u0443\u043d\u0433\u0443 \u043a\u0430\u0440 \u0434\u0438\u043b\u0438 \u0448\u0430\u0431.\n\u041d\u0430\u043c\u0435\u043e\u043c\u0430\u0434 \u043d\u0430 \u043e\u0432\u043e\u0437\u0438 \u0445\u0443\u0440\u04ef\u0441\u0435,\n\u041d\u0430 \u0448\u0438\u0440\u0438\u043d \u0445\u0430\u043d\u0434\u0430\u0438 \u043e\u0448\u0438\u049b \u0430\u0440\u04ef\u0441\u0435.\n\u041d\u0430 \u0431\u043e\u043b\u0443 \u043f\u0430\u0440 \u043a\u0443\u0448\u043e\u0434\u0430\u043d\u04b3\u043e\u0438 \u043c\u0443\u0440\u0493\u043e\u043d,\n\u041d\u0430 \u0431\u043e \u04b3\u0430\u043c \u0445\u04ef\u0440\u0434\u0430\u043d\u0438 \u0448\u043e\u0445\u0438 \u0434\u0430\u0440\u0430\u0445\u0442\u043e\u043d.\n\u0424\u0430\u049b\u0430\u0442 \u0430\u0437 \u0431\u043e\u0493 \u043c\u0435\u043e\u043c\u0430\u0434 \u043d\u0430\u0441\u0438\u043c\u0435,\n\u041d\u0430\u0441\u0438\u043c\u0438 \u0430\u0442\u0440\u0431\u04ef, \u0434\u0438\u043b\u043a\u0430\u0448, \u04b3\u0430\u043b\u0438\u043c\u0435.\n\u0428\u0443\u043d\u0438\u0434\u0430\u043c \u043c\u0430\u043d \u0444\u0430\u049b\u0430\u0442 \u0434\u0430\u0440\u0440\u043e \u043a\u0443\u0448\u043e\u0434\u0430,\n\u041d\u0430\u0444\u0430\u0441\u0433\u0438\u0440\u0438\u0438 \u0430\u04b3\u043b\u0438 \u0445\u043e\u043d\u0430\u0432\u043e\u0434\u0430.\n\u0411\u0430 \u0441\u0430\u04b3\u043d\u0438 \u0431\u043e\u0493 \u04b7\u0430\u0441\u0442\u0430\u043c \u0447\u0443\u043d \u0448\u0430\u0440\u043e\u0440\u0430,\n\u041d\u0438\u0433\u043e\u04b3 \u043a\u0430\u0440\u0434\u0430\u043c \u0431\u0430 \u043d\u0443\u0440\u0430\u0444\u0448\u043e\u043d \u0441\u0438\u0442\u043e\u0440\u0430.\n\u04b2\u0430\u0432\u043e\u0438 \u0448\u0430\u0431 \u04b3\u0443\u0437\u0443\u0440\u0438 \u0440\u04ef\u04b3\u0443 \u04b7\u043e\u043d \u0431\u0443\u0434,\n\u0417\u0430\u043c\u0438\u043d \u0441\u0430\u0431\u0437\u0443 \u043c\u0443\u0441\u0430\u0444\u0444\u043e \u043e\u0441\u043c\u043e\u043d \u0431\u0443\u0434.\n\u041c\u0430\u04b3\u0438 \u0430\u043f\u0440\u0435\u043b, \u0434\u0430\u0440 \u0438\u0434\u0438 \u0431\u0430\u04b3\u043e\u0440\u04e3,\n\u0411\u0430 \u0433\u0443\u043b \u043b\u04ef\u044a\u043b\u04ef\u0438 \u0442\u0430\u0440 \u0431\u0430\u0445\u0448\u0438\u0434, \u043e\u0440\u0435.\n\u0413\u0443\u043b\u0438 \u0433\u0435\u043b\u043e\u0441 \u0434\u0430\u0440 \u0447\u0430\u043d\u0433\u0438 \u04b3\u0430\u0432\u043e \u0431\u0443\u0434,\n\u0411\u0430\u0440\u043e\u0438 \u04b3\u0430\u043c\u043b \u043e\u043b\u0443 \u0493\u0443\u043d\u0447\u0430\u0432\u043e \u0431\u0443\u0434.\n\u0411\u0443\u043d\u0430\u0444\u0448\u0430 \u0434\u0430\u0440 \u043b\u0430\u0431\u0438 \u04b7\u04ef \u043d\u043e\u0437 \u043c\u0435\u043a\u0430\u0440\u0434,\n\u0413\u0443\u043b\u0438 \u0441\u0430\u0434\u0431\u0430\u0440\u0433 \u0447\u0430\u0448\u043c\u0430\u0448 \u0431\u043e\u0437 \u043c\u0435\u043a\u0430\u0440\u0434.\n\u0427\u0430\u043a\u0438\u0434\u0430\u043d \u0434\u043e\u0448\u0442 \u0447\u0430\u043a-\u0447\u0430\u043a \u0448\u0438\u0440\u0430\u0438 \u0442\u043e\u043a,\n\u0422\u0430\u043f\u0438\u0434\u0430\u043d \u0434\u043e\u0448\u0442 \u0430\u0437 \u0433\u0430\u0440\u043c\u04e3 \u0434\u0438\u043b\u0438 \u0445\u043e\u043a.\n\u0414\u0430\u0440\u0430\u0445\u0442\u043e\u043d \u0434\u0430\u0440 \u0443\u043c\u0435\u0434\u0438 \u0431\u043e\u0440 \u0431\u0443\u0434\u0430\u043d\u0434,\n\u04b2\u0430\u043c\u0430 \u0434\u0430\u0440 \u043d\u0438\u043c\u0438 \u0448\u0430\u0431 \u043f\u0443\u0440\u043a\u043e\u0440 \u0431\u0443\u0434\u0430\u043d\u0434.\n\u04b2\u0430\u043c\u0430 \u043c\u043e\u043d\u0430\u043d\u0434\u0438 \u043c\u0430\u043d \u0431\u043e \u0438\u043d\u0442\u0438\u0437\u043e\u0440\u04e3,\n\u0492\u0430\u043d\u04e3 \u0431\u0443\u0434\u0430\u043d\u0434 \u0430\u0437 \u0431\u043e\u0434\u0438 \u0431\u0430\u04b3\u043e\u0440\u04e3.\n\u0428\u0443\u043c\u043e\u0440\u043e, \u2013 \u0431\u043e\u0440\u043e\u0440\u0430\u043d\u0434\u0430 \u0434\u0430\u0440\u0430\u0445\u0442\u043e\u043d,\n\u0428\u0443\u0434\u0430\u043c \u0447\u0443\u043d \u0433\u0430\u0432\u04b3\u0430\u0440\u0438 \u0447\u0430\u0448\u043c\u0430\u043c \u043d\u0438\u0433\u043e\u04b3\u0431\u043e\u043d.\n\u0428\u0438\u043d\u043e\u043d\u0434\u0430\u043c, \u043e\u0431 \u0434\u043e\u0434\u0430\u043c, \u043f\u0430\u0440\u0432\u0430\u0440\u0438\u0434\u0430\u043c,\n\u041d\u0430\u0445\u0443\u0441\u0442\u0438\u043d \u043c\u0435\u0432\u0430\u04b3\u043e\u0442\u043e\u043d\u0440\u043e \u0447\u0430\u0448\u0438\u0434\u0430\u043c.\n\u0428\u0443\u043c\u043e, \u0430\u0437 \u043d\u0430\u0432 \u04b3\u0430\u0432\u043e\u0438 \u0431\u043e\u0440 \u0434\u043e\u0440\u0435\u0434,\n\u0411\u0430 \u043e\u044f\u043d\u0434\u0430 \u0441\u0430\u043c\u0430\u0440\u0431\u0430\u0445\u0448 \u0438\u043d\u0442\u0438\u0437\u043e\u0440\u0435\u0434.\n\u0414\u0430\u0440 \u0438\u043d \u04b3\u0430\u043d\u0433\u043e\u043c \u043c\u043e\u043d\u0430\u043d\u0434\u0438 \u0448\u0443\u043c\u043e\u044f\u043c,\n\u0427\u0443\u043d\u0438\u043d \u0430\u0441\u0442\u0443 \u0447\u0443\u043d\u0438\u043d \u0434\u0430\u0440\u0434\u0430\u043c, \u0434\u0430\u0432\u043e\u044f\u043c.\n\u0411\u0430 \u0447\u0430\u0448\u043c\u043e\u043d\u0430\u043c \u0448\u0443\u0434\u0430\u043d\u0434 \u0438\u043d \u0434\u0430\u043c \u043d\u0430\u043c\u043e\u0451\u043d,\n\u0422\u0430\u0432\u0430\u043b\u043b\u0443\u0434\u0445\u043e\u043d\u0430\u0432\u0443 \u0434\u0443\u043d\u0451\u0438 \u0442\u0438\u0444\u043b\u043e\u043d.")
B.aqJ=new A.a("9b59e522-322c-455f-aa95-9cdf3f18641b","41c86281-0423-4553-91e8-5f8c298ed40f","\u0421\u0430\u04b3\u0430\u0440 \u0448\u0443\u0434, \u0448\u0430\u04b3\u0440 \u04b3\u0430\u043c \u043e\u043c\u0430\u0434 \u0431\u0430 \u0442\u0430...","\u0421\u0430\u04b3\u0430\u0440 \u0448\u0443\u0434, \u0448\u0430\u04b3\u0440 \u04b3\u0430\u043c \u043e\u043c\u0430\u0434 \u0431\u0430 \u0442\u0430\u04b3\u0440\u0438\u043a,\n\u041c\u0443\u043d\u0430\u0432\u0432\u0430\u0440 \u0448\u0443\u0434 \u0444\u0430\u0437\u043e\u0438 \u043a\u04ef\u04b3\u0438 \u0442\u043e\u04b7\u0438\u043a.\n\u0411\u0430 \u0442\u0430\u043d \u043f\u04ef\u0448\u0438\u0434\u0430 \u04b7\u0435\u043b\u0430\u043a, - \u04b7\u043e\u043c\u0430\u0438 \u0441\u0443\u0444\n\u0414\u0438\u0433\u0430\u0440 \u0442\u0430\u0448\u0432\u0438\u0448\u04b3\u043e\u0440\u043e \u043c\u043e\u043d\u0434\u0430 \u043c\u0430\u0432\u049b\u0443\u0444.\n\u0424\u0438\u0442\u043e\u0434\u0430\u043c \u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d\u0438 \u0441\u0435\u0440\u04b7\u0430\u043d\u04b7\u043e\u043b,\n\u0411\u0430 \u0434\u0443\u043d\u0451\u0438 \u043f\u0443\u0440 \u0430\u0437 \u0444\u0430\u0440\u0451\u0434\u0438 \u0430\u0442\u0444\u043e\u043b.\n\u0427\u04e3 \u0434\u0430\u0440 \u0445\u043e\u043d\u0430, \u0447\u04e3 \u0434\u0430\u0440 \u0440\u043e\u04b3\u0440\u0430\u0432 \u2013 \u043a\u0430\u0440\u0438\u0434\u043e\u0440,\n\u0411\u0430 \u0433\u04ef\u0448\u0430\u043c \u043c\u0435\u0440\u0430\u0441\u0438\u0434 \u043e\u0432\u043e\u0437\u0438 \u0431\u0438\u0441\u0451\u0440.\n\u042f\u043a\u0435 \u0444\u0430\u0440\u0451\u0434 \u043b\u04ef\u043b\u0430\u043a\u043f\u0435\u0447 \u043c\u0435\u0437\u0430\u0434,\n\u0414\u0438\u0433\u0430\u0440 \u043f\u043e\u0440\u043e \u0431\u0430 \u043f\u043e \u0431\u0435 \u04b3\u0435\u0447 \u043c\u0435\u0437\u0430\u0434.\n\u042f\u043a\u0435 \u0447\u0430\u0448\u043c\u043e\u043d\u0438 \u0445\u0443\u0434 \u043d\u0430\u043a\u0448\u043e\u0434\u0430 \u04b3\u043e\u043b\u043e,\n\u0492\u0438\u0437\u043e \u043c\u0435\u04b7\u0443\u0441\u0442 \u0432\u043e \u043a\u0430\u0440\u0434\u0430 \u0434\u0430\u04b3\u043e\u043d\u0440\u043e.\n\u0421\u0430\u0434\u043e\u0435, \u043a\u0438 \u0431\u0430 \u04b3\u0430\u0440 \u044f\u043a \u0442\u0438\u0444\u043b \u0445\u043e\u0441 \u0430\u0441\u0442,\n\u0411\u0430 \u043c\u043e\u0434\u0430\u0440 \u0437-\u0430\u0432\u0432\u0430\u043b\u0438\u043d \u0441\u043e\u0430\u0442 \u0448\u0438\u043d\u043e\u0441 \u0430\u0441\u0442.\n\u0427\u04e3 \u0441\u043e\u043d \u043d\u0430\u0448\u043d\u043e\u0441\u0430\u0434 \u043e\u0432\u043e\u0437\u0438 \u0434\u0438\u043b\u0430\u0448\u0440\u043e?\n\u0414\u0430\u0432\u043e\u043c\u0438 \u0443\u043c\u0440, \u043f\u0430\u0440\u0432\u043e\u0437\u0438 \u0434\u0438\u043b\u0430\u0448\u0440\u043e?\n\u0411\u0430 \u043c\u043e\u0434\u0430\u0440 \u043d\u0443\u0440\u0438 \u0447\u0430\u0448\u043c\u043e\u043d \u0430\u0441\u0442 \u0444\u0430\u0440\u0437\u0430\u043d\u0434,\n\u0414\u0430\u0432\u0430\u043d\u0434\u0430 \u0440\u0435\u0448\u0430 \u0434\u0430\u0440 \u04b7\u043e\u043d \u0430\u0441\u0442 \u0444\u0430\u0440\u0437\u0430\u043d\u0434.\n\u0413\u0438\u0440\u0438\u0444\u0442\u0430 \u0434\u043e\u044f \u0442\u0438\u0444\u043b\u0435\u0440\u043e \u0434\u0430\u0440 \u043e\u0493\u04ef\u0448,\n\u0411\u0430\u0440\u043e\u043c\u0430\u0434 \u0430\u0437 \u0434\u0430\u0440\u0435 \u043c\u0430\u0493\u0440\u0443\u0440, \u0445\u043e\u043c\u04ef\u0448.\n\u0410\u0433\u0430\u0440\u0447\u0438 \u0434\u043e\u044f \u04b3\u043e\u043b\u043e \u0445\u0443\u0434 \u04b7\u0430\u0432\u043e\u043d \u0431\u0443\u0434,\n\u0412\u0430\u043b\u0435\u043a\u0438\u043d \u043a\u04ef\u0434\u0430\u043a\u043e\u043d\u0440\u043e \u043c\u0435\u04b3\u0440\u0443\u0431\u043e\u043d \u0431\u0443\u0434.\n\u0420\u0430\u0441\u0430\u0434 \u0440\u04ef\u0437\u0435, \u043a\u0438 \u0445\u0443\u0434 \u0444\u0430\u0440\u0437\u0430\u043d\u0434 \u0431\u0438\u043d\u0430\u0434,\n\u0427\u0443 \u043c\u043e\u0434\u0430\u0440 \u043d\u0430\u0437\u0434\u0438 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u043e\u043d \u043d\u0438\u0448\u0438\u043d\u0430\u0434.\n\u0414\u0438\u043b\u0430\u0448 \u0445\u043e\u04b3\u0430\u0434, \u043a\u0438 \u0431\u043e\u0448\u0430\u0434 \u0448\u043e\u0434\u0443 \u0445\u0443\u0440\u0441\u0430\u043d\u0434,\n\u041d\u0430\u0431\u0438\u043d\u0430\u0434 \u04b3\u0435\u0447 \u0434\u0430\u0440\u0434\u0443 \u0434\u043e\u0493\u0438 \u0444\u0430\u0440\u0437\u0430\u043d\u0434.\n\u041d\u0430\u0437\u0430\u0440 \u043a\u0430\u0440\u0434\u0430\u043c \u0431\u0430 \u0442\u0438\u043b\u043b\u043e\u0440\u0430\u043d\u0433 \u043c\u04ef\u044f\u0448,\n\u0411\u0430 \u0447\u0430\u0448\u043c\u043e\u043d\u0438 \u043a\u0430\u0431\u0443\u0434\u0430\u0448, \u0441\u0443\u0440\u0445 \u0440\u04ef\u044f\u0448.\n\u0427\u0443\u043d\u0438\u043d \u0434\u0443\u0445\u0442\u0430\u0440, \u0447\u0443\u043d\u0438\u043d \u0441\u0438\u043c\u043e\u0438 \u0445\u0443\u0448\u0433\u0438\u043b,\n\u041a\u04e3 \u043c\u0435\u0434\u043e\u043d\u0430\u0434, \u043a\u0438\u0440\u043e \u0445\u0443\u0448 \u043a\u0430\u0440\u0434\u0430 \u0434\u0430\u0440 \u0434\u0438\u043b?\n\u0414\u0430\u0440 \u0438\u043d \u0445\u043e\u043d\u0430 \u2013 \u0442\u0430\u0432\u0430\u043b\u043b\u0443\u0434\u0433\u043e\u04b3\u0438 \u0438\u043d\u0441\u043e\u043d,\n\u041d\u0438\u0433\u0430\u04b3 \u043a\u0430\u0440\u0434\u0430\u043c \u0431\u0430 \u0440\u0430\u043d\u0433\u043e\u0440\u0430\u043d\u0433 \u0442\u0438\u0444\u043b\u043e\u043d.\n\u042f\u043a\u0435 \u0431\u0435 \u043c\u04ef\u0439 \u0431\u0443\u0434\u0443 \u0441\u0430\u043f-\u0441\u0430\u0444\u0435\u0434\u0430\u043a,\n\u0414\u0438\u0433\u0430\u0440 \u043c\u04ef\u0439\u0438 \u0441\u0438\u044f\u04b3 \u0431\u0443\u0434\u0443 \u043f\u0435\u0447-\u043f\u0435\u0447\u0430\u043a.\n\u042f\u043a\u0435 \u043e\u0440\u043e\u043c, \u0434\u0438\u0433\u0430\u0440 \u0431\u0435\u0441\u0430\u0440\u0430\u043d\u04b7\u043e\u043c,\n\u042f\u043a\u0435 \u0448\u0430\u043a\u043b\u0435 \u0433\u0438\u0440\u0438\u0444\u0442\u0430, \u0434\u0438\u0433\u0430\u0440\u0435 \u0445\u043e\u043c.\n\u0411\u0430 \u0445\u043e\u043d\u0430, \u0430\u0437 \u049b\u0430\u0444\u043e\u0438 \u044f\u043a \u0442\u0438\u0440\u0435\u0437\u0430,\n\u041d\u0438\u0433\u0430\u04b3 \u043c\u0435\u043a\u0430\u0440\u0434 \u043c\u0430\u0440\u0434\u0435 \u0431\u043e \u0441\u0438\u0442\u0435\u0437\u0430.\n\u0411\u0430 \u043a\u0438\u043d \u043c\u04ef\u0439\u0438 \u043b\u0430\u0431\u0430\u0448\u0440\u043e \u0442\u043e\u0431 \u043c\u0435\u0434\u043e\u0434,\n\u049a\u0430\u0441\u0430\u043c \u0431\u0430\u0440 \u0445\u0443\u043b\u049b\u0443 \u0431\u0430\u0440 \u043e\u0434\u043e\u0431 \u043c\u0435\u0434\u043e\u0434.\n\u041a\u0443\u0448\u043e\u0434\u0430 \u0447\u0430\u0448\u043c\u0440\u043e \u0447\u0443\u043d \u0448\u043e\u04b3\u043a\u043e\u0441\u0430,\n\u0417\u0430\u043d\u0430\u0448\u0440\u043e \u0442\u0430\u044a\u043d\u0430 \u043c\u0435\u0437\u0430\u0434 \u043e\u043d, \u0445\u0443\u043b\u043e\u0441\u0430.\n\u0411\u0430 \u043c\u0430\u043d \u0433\u0443\u0444\u0442\u0430\u043d\u0434, \u043a\u0438 \u04ef \u0430\u0437 \u0437\u0430\u043d \u049b\u0438\u043c\u043e\u0431 \u0430\u0441\u0442,\n\u0417\u0438 \u0434\u0443\u0445\u0442\u0430\u0440 \u0437\u043e\u0434\u0430\u043d\u0438 \u0437\u0430\u043d \u0434\u0430\u0440 \u0430\u0437\u043e\u0431 \u0430\u0441\u0442.\n\u041d\u0430\u043c\u0435\u0445\u043e\u04b3\u0430\u0434, \u043a\u0438 \u0431\u0438\u043d\u0430\u0434 \u0434\u0443\u0445\u0442\u0430\u0440\u0430\u0448\u0440\u043e,\n\u041c\u0443\u0431\u043e\u0440\u0430\u043a\u0431\u043e\u0434 \u0433\u04ef\u044f\u0434 \u043c\u043e\u0434\u0430\u0440\u0430\u0448\u0440\u043e.\n\u0411\u0430 \u0434\u0438\u043b \u0433\u0443\u0444\u0442\u0430\u043c, \u043a\u0438: \xab\u04b6\u043e\u04b3\u0438\u043b \u043c\u0430\u0440\u0434 \u0431\u0443\u0434\u0430\u0441\u0442,\n\u0422\u0430\u043d\u0438 \u043c\u043e\u0440\u043e \u043d\u0438\u0448\u0430\u0441\u0442\u0430 \u0433\u0430\u0440\u0434 \u0431\u0443\u0434\u0430\u0441\u0442\xbb.\n\u0411\u0430 \u04b7\u043e\u0439\u0438 \u04ef \u0441\u0430\u043d\u043e \u0433\u0443\u0444\u0442\u0430\u043c \u0445\u0443\u0434\u0438 \u043c\u0430\u043d,\n\u0411\u0430 \u0438\u043d \u043d\u0430\u0432\u0437\u043e\u0434 \u0434\u0443\u0445\u0442\u0430\u0440\u0447\u0430, \u0431\u0430 \u0438\u043d \u0437\u0430\u043d.\n\u0421\u0430\u043d\u043e \u0433\u0443\u0444\u0442\u0430\u043c \u0431\u0430 \u0437\u0430\u043d\u04b3\u043e\u0435, \u043a\u0438 \u0438\u043c\u0440\u04ef\u0437,\n\u0411\u0430 \u043a\u043e\u0440\u0438 \u043c\u0430\u043c\u043b\u0430\u043a\u0430\u0442 \u04b3\u0430\u0441\u0442\u0430\u043d\u0434 \u0434\u0438\u043b\u0441\u04ef\u0437.\n\u0421\u0430\u043d\u043e \u0433\u0443\u0444\u0442\u0430\u043c \u0431\u0430 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0438 \u04b7\u0438\u0433\u0430\u0440\u0431\u0430\u043d\u0434,\n\u0411\u0430 \u04b3\u0430\u0440 \u044f\u043a \u043c\u043e\u0434\u0430\u0440\u0438 \u0434\u043e\u0440\u043e\u0438 \u0444\u0430\u0440\u0437\u0430\u043d\u0434.\n\u042f\u049b\u0438\u043d \u0434\u043e\u0440\u0430\u043c, \u043a\u0438 \u0438\u043d \u0434\u0443\u0445\u0442\u0430\u0440\u0447\u0430\u0438 \u043d\u0430\u0432,\n\u0428\u0430\u0432\u0430\u0434 \u0444\u0430\u0440\u0434\u043e \u0431\u0430 \u043c\u043e\u0434\u0430\u0440\u04b3\u043e\u0448 \u043f\u0430\u0439\u0440\u0430\u0432.\n\u0410\u0437\u0438\u0437\u0438 \u0445\u0430\u043b\u049b, \u0434\u043e\u043d\u0438\u0448\u043c\u0430\u043d\u0434 \u0433\u0430\u0440\u0434\u0430\u0434,\n\u0411\u0430 \u043a\u043e\u0440\u0438 \u0441\u0443\u0434\u043e\u0432\u0430\u0440 \u0431\u0430\u043d\u0434 \u0433\u0430\u0440\u0434\u0430\u0434.\n\u0410\u0433\u0430\u0440 \u043c\u0430\u0440\u0434\u0435 \u0448\u0430\u0432\u0430\u0434 \u043f\u0430\u0439\u0434\u043e, \u043a\u0438 \u043e\u043d\u0440\u043e\n\u041a\u0443\u043d\u0430\u0434 \u0442\u0430\u04b3\u049b\u0438\u0440, \u0440\u0430\u043d\u04b7\u043e\u043d\u0430\u0434 \u0437\u0430\u043d\u043e\u043d\u0440\u043e.\n\u0427\u0443\u043d\u0438\u043d \u043d\u043e\u043c\u0430\u0440\u0434\u0440\u043e \u043d\u043e\u0434\u043e\u043d \u0448\u0443\u043c\u043e\u0440\u0430\u0434,\n\u0411\u0430 \u0434\u0430\u0440\u0451 \u0442\u0430\u0448\u043d\u0430 \u0431\u0443\u0440\u0434\u0430, \u0442\u0430\u0448\u043d\u0430 \u043e\u0440\u0430\u0434.\n\u0411\u0430 \u043c\u043e\u043c\u043e \u0434\u04ef\u0445\u0442\u0430\u043c \u0447\u0430\u0448\u043c\u043e\u043d\u0438 \u0445\u0443\u0434\u0440\u043e,\n\u0413\u0438\u0440\u0438\u0444\u0442\u0430\u043c \u0434\u0430\u0440 \u0448\u0438\u043a\u0430\u043d\u04b7\u0430 \u04b7\u043e\u043d\u0438 \u0445\u0443\u0434\u0440\u043e.\n\u0420\u0443\u0445\u0438 \u043c\u043e\u043c\u043e \u0431\u0430 \u0447\u0430\u0448\u043c \u043e\u0441\u0443\u0434\u0430 \u0431\u0438\u043d\u043c\u0443\u0434,\n\u041d\u0438\u0433\u043e\u04b3\u0435 \u043a\u0430\u0440\u0434\u0443 \u043b\u0430\u0431 \u0431\u043e \u0445\u0430\u043d\u0434\u0430 \u0431\u0438\u043a\u0448\u0443\u0434:\n\xab\u041f\u0430\u0434\u0430\u0440 \u0433\u0430\u0448\u0442\u0435\u0434 \u044f\u043a \u0442\u0438\u043b\u043b\u043e \u043f\u0438\u0441\u0430\u0440\u0440\u043e,\n\u041c\u0443\u0431\u043e\u0440\u0430\u043a\u0431\u043e\u0434 \u043c\u0435\u0433\u04ef\u044f\u043c \u043f\u0430\u0434\u0430\u0440\u0440\u043e.\n\u0421\u0430\u043b\u043e\u043c\u0430\u0442 \u043c\u043e\u0434\u0430\u0440\u0430\u0448, \u04b7\u043e\u043d\u0430\u0448 \u0440\u0430\u04b3\u043e \u0451\u0444\u0442,\n\u0411\u0430 \u0431\u0430\u0445\u0442\u0430\u0448 \u043a\u04ef\u0434\u0430\u043a\u0438 \u043e\u043b\u0430\u043c\u043f\u0430\u043d\u043e \u0451\u0444\u0442\xbb.\n\u041c\u0430\u043d \u0430\u0437 \u0448\u043e\u0434\u04e3 \u0437\u0438 \u04b7\u043e \u04b7\u0430\u0441\u0442\u0430\u043c, \u043f\u0430\u0440\u0438\u0434\u0430\u043c,\n\u0420\u0443\u0445\u0438 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0438 \u043d\u0430\u0432\u0437\u043e\u0434\u0430\u043c \u0431\u0438\u0434\u0438\u0434\u0430\u043c.\n\u041d\u0430\u0445\u0443\u0441\u0442\u0438\u043d \u0431\u043e\u0440 \u0431\u0438\u0448\u043d\u0438\u0434\u0430\u043c \u0441\u0430\u0434\u043e\u044f\u0448,\n\u0414\u0430\u0440\u0438 \u0434\u0438\u043b\u0440\u043e \u043a\u0443\u0448\u043e\u0434\u0430\u043c \u043c\u0430\u043d \u0431\u0430\u0440\u043e\u044f\u0448.\n\u0414\u0430\u04b3\u043e\u043d \u0432\u043e \u043a\u0430\u0440\u0434\u0430 \u043c\u0435\u04b7\u0443\u043d\u0431\u043e\u043d\u0434 \u043b\u0430\u0431\u0440\u043e,\n\u0411\u0430 \u0434\u0438\u043b \u043c\u0435\u043a\u0430\u0440\u0434 \u04b7\u043e \u0438\u0448\u049b\u0438 \u043d\u0430\u0441\u0430\u0431\u0440\u043e.\n\u041c\u0430\u0440\u0430\u043d\u04b7 \u0430\u0437 \u043c\u0430\u043d \u0442\u0443, \u044d\u0439 \u0434\u043e\u0434\u043e\u0438 \u0434\u0443\u0445\u0442\u0430\u0440,\n\u041a\u0438 \u0434\u043e\u0434\u0430\u043c \u043c\u0430\u043d \u0442\u0443\u0440\u043e \u0434\u0430\u0448\u043d\u043e\u043c \u044f\u043a\u0441\u0430\u0440.\n\u0422\u0443\u0440\u043e \u0434\u0443\u0445\u0442\u0430\u0440 \u043c\u0430\u0440\u043e \u0431\u043e\u0448\u0430\u0434 \u043f\u0438\u0441\u0430\u0440 \u0448\u0443\u0434,\n\u0411\u0430\u0440\u043e\u0438 \u043c\u043e\u0432\u0443 \u0442\u0443 \u044f\u043a \u0438\u0434 \u0441\u0430\u0440 \u0448\u0443\u0434.\n\u041a\u04e3 \u043c\u0435\u0434\u043e\u043d\u0430\u0434, \u043a\u0438 \u044f\u043a \u0440\u04ef\u0437\u0438 \u043c\u0443\u0441\u043e\u0438\u0434,\n\u049a\u0443\u0434\u043e\u0438 \u04b3\u0430\u043c\u0434\u0438\u0433\u0430\u0440 \u0445\u043e\u04b3\u0435\u043c \u0433\u0430\u0440\u0434\u0438\u0434.\n\u041f\u0438\u0441\u0430\u0440\u0440\u043e \u043f\u0435\u0448\u043a\u0430\u0448 \u043a\u0430\u0440\u0434\u0430\u043c \u0432\u0430\u0442\u0430\u043d\u0440\u043e,\n\u0414\u0438\u0451\u0440\u0438 \u0434\u0438\u043b\u043f\u0438\u0441\u0430\u043d\u0434\u0438 \u0445\u0435\u0448\u0442\u0430\u043d\u0440\u043e.\n\u0417\u0430\u043c\u0438\u043d\u0438 \u0441\u0430\u0431\u0437\u0440\u0430\u043d\u0433\u0438 \u0442\u043e\u04b7\u0438\u043a\u043e\u043d\u0440\u043e,\n\u0421\u0430\u0434\u043e\u0438 \u0440\u04ef\u0434\u04b3\u043e\u0438 \u0437\u0430\u0440\u0444\u0438\u0448\u043e\u043d\u0440\u043e.\n\u0427\u0430\u0440\u043e\u0433\u043e\u04b3\u043e\u043d\u0438 \u043f\u0443\u0440 \u0430\u0437 \u043c\u043e\u043b\u04b3\u043e\u0440\u043e,\n\u0421\u0430\u043e\u0434\u0430\u0442\u0431\u0430\u0445\u0448 \u043c\u043e\u04b3\u0443 \u0441\u043e\u043b\u04b3\u043e\u0440\u043e.\n\u0414\u0435\u04b3\u043e\u0442\u0443 \u0448\u0430\u04b3\u0440\u04b3\u043e\u0438 \u043d\u0430\u0432 \u0431\u0430 \u043d\u0430\u0432\u0440\u043e,\n\u0411\u0430 \u04b3\u0443\u0441\u043d \u0430\u0437 \u0431\u043e\u0493\u04b3\u043e \u0431\u0443\u0440\u0434\u0430 \u0433\u0430\u0440\u0430\u0432\u0440\u043e.\n\u0424\u0430\u0440\u043e\u0432\u043e\u043d\u043c\u0435\u04b3\u043d\u0430\u0442\u04e3, \u043d\u043e\u043d\u0443 \u043d\u0430\u043c\u0430\u043a\u0440\u043e,\n\u0421\u0443\u0440\u0443\u0434\u0438 \u0440\u0430\u0444\u0442\u0430 \u0442\u043e \u0430\u0432\u04b7\u0438 \u0444\u0430\u043b\u0430\u043a\u0440\u043e.\n\u0411\u0430 \u04ef \u043c\u0430\u043d \u04b3\u0430\u0434\u044f \u043a\u0430\u0440\u0434\u0430\u043c \u043c\u0430\u043d\u0437\u0438\u043b\u0430\u043c\u0440\u043e,\n\u0427\u0430\u0440\u043e\u0493\u0438 \u043d\u0443\u0440\u043f\u043e\u0448\u0438 \u043c\u0430\u04b3\u0444\u0438\u043b\u0430\u043c\u0440\u043e.\n\u0423\u043c\u0435\u0434\u0443 \u043e\u0440\u0437\u0443, \u043e\u043c\u043e\u043b\u0438 \u0445\u0443\u0434\u0440\u043e,\n\u041f\u0443\u0440 \u0430\u0437 \u0441\u0430\u044a\u044e \u04b7\u0430\u0434\u0430\u043b \u0438\u049b\u0431\u043e\u043b\u0438 \u0445\u0443\u0434\u0440\u043e.\n\u041d\u0430 \u0442\u0430\u043d\u04b3\u043e \u043a\u0430\u0440\u0434\u0430 \u043e\u043d\u0440\u043e \u0431\u0430\u0445\u0442 \u043e\u0493\u04ef\u0448,\n\u041d\u0430 \u0442\u0430\u043d\u04b3\u043e \u0437\u0438\u043d\u0434\u0430\u0433\u04e3 \u0431\u04ef\u0441\u0438\u0434 \u043f\u0443\u0440\u04b7\u04ef\u0448.\n\u04b2\u0430\u043d\u04ef\u0437 \u043e\u043d\u0440\u043e \u0434\u0443\u0447\u043e\u0440 \u043e\u044f\u0434 \u0437\u0430\u0434\u0443\u0445\u04ef\u0440\u0434,\n\u0411\u0430 \u04ef \u043e\u044f\u043d\u0434\u0430\u0440\u043e \u0431\u043e\u044f\u0434, \u043a\u0438 \u0431\u0438\u0441\u043f\u0443\u0440\u0434.\n\u041f\u0438\u0441\u0430\u0440\u04b7\u043e\u043d, \u0447\u0443\u043d \u043a\u0443\u0448\u043e\u04e3 \u0434\u0438\u0434\u0430\u0433\u043e\u043d\u0440\u043e,\n\u0411\u0430 \u0447\u0430\u0448\u043c\u0438 \u0445\u0435\u0448\u0442\u0430\u043d \u0431\u0438\u043d\u04e3 \u04b7\u0430\u04b3\u043e\u043d\u0440\u043e.\n\u0422\u0443 \u04b3\u0430\u043c \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0438 \u0428\u0430\u0440\u049b\u04e3, \u041e\u0441\u0438\u0451\u04e3,\n\u0412\u0430\u043b\u0435\u043a\u0438\u043d \u041e\u0441\u0438\u0451\u0438 \u043f\u0443\u0440\u0441\u0430\u0444\u043e\u04e3.\n\u0422\u0443 \u04b3\u043e\u043b\u043e, \u0445\u043e\u0431 \u043a\u0443\u043d \u0440\u043e\u04b3\u0430\u0442 \u043d\u0430\u0444\u0430\u0441 \u0433\u0438\u0440,\n\u0411\u0438\u0437\u0430\u043d \u0444\u0430\u0440\u0451\u0434\u04b3\u043e\u0432\u0443 \u043d\u04ef\u0448 \u043a\u0443\u043d \u0448\u0438\u0440!\n\u041c\u0430\u043d \u0430\u043a\u043d\u0443\u043d \u043c\u0435\u0440\u0430\u0432\u0430\u043c, \u043f\u043e\u0435\u0437\u0434 \u043e\u044f\u0434,\n\u041c\u0443\u043b\u043e\u049b\u043e\u0442\u0438 \u043d\u0430\u0432\u0435 \u0434\u0430\u0440 \u043f\u0435\u0448 \u0431\u043e\u044f\u0434.\n\u041c\u0443\u043b\u043e\u049b\u043e\u0442\u0438 \u043d\u0430\u0432\u0435 \u0431\u043e \u043f\u0438\u0440\u0430\u043c\u0430\u0440\u0434\u0435,\n\u0410\u0434\u0438\u0431\u0438 \u043e\u0437\u043c\u0443\u0434\u0430 \u04b3\u0430\u0440 \u043d\u0430\u0431\u0430\u0440\u0434\u0435.\n\u041a\u0443\u04b3\u0430\u043d\u0441\u043e\u043b\u0435, \u043a\u0438 \u0434\u0438\u0434\u0430 \u0434\u0443 \u0437\u0430\u043c\u043e\u043d\u0440\u043e,\n\u0492\u0430\u043c\u0443 \u0430\u043d\u0434\u0443\u04b3\u0443 \u0448\u043e\u0434\u0438\u0438 \u04b7\u0430\u04b3\u043e\u043d\u0440\u043e.\n\u041a\u0443\u04b3\u0430\u043d\u0441\u043e\u043b\u0435, \u043a\u0438 \u0434\u0438\u043b \u043f\u0443\u0440 \u0430\u0437 \u0443\u043c\u0435\u0434 \u0430\u0441\u0442,\n\u0420\u0430\u04b3\u0430\u0448 \u043c\u043e\u043d\u0430\u043d\u0434\u0438 \u043c\u04ef\u04b3\u043e\u044f\u0448 \u0441\u0430\u0444\u0435\u0434 \u0430\u0441\u0442.\n\u041a\u0443\u04b3\u0430\u043d\u0441\u043e\u043b\u0435, \u043a\u0438 \u0434\u043e\u043d\u0430\u0434 \u041e\u0441\u0438\u0451\u0440\u043e,\n\u0411\u0430 \u0433\u04ef\u0448\u043e\u044f\u043d\u0434\u0430 \u0430\u0437 \u04b3\u0430\u0440 \u0434\u0438\u043b \u0441\u0430\u0434\u043e\u0440\u043e.\n\u0421\u0430\u0434\u043e\u0438 \u041e\u0441\u0438\u0451\u0440\u043e \u0445\u0443\u0431 \u0434\u043e\u043d\u0430\u0434,\n\u0425\u0443\u0434 \u04ef\u0440\u043e \u041e\u0441\u0438\u0451 \u043c\u0430\u04b3\u0431\u0443\u0431 \u0445\u043e\u043d\u0430\u0434.")
B.acN=new A.a("d43417fd-ebd0-4e79-8a14-c051f3661f56","41c86281-0423-4553-91e8-5f8c298ed40f","\u041a\u04ef\u0434\u0430\u043a\u0435 \u043c\u0435\u0433\u0430\u0448\u0442 \u0431\u043e \u049b\u0443\u0442\u0442\u0438\u0438 \u0445\u0443\u0434,","\u041a\u04ef\u0434\u0430\u043a\u0435 \u043c\u0435\u0433\u0430\u0448\u0442 \u0431\u043e \u049b\u0443\u0442\u0442\u0438\u0438 \u0445\u0443\u0434,\n\u0414\u0430\u0440 \u0445\u0438\u0451\u0431\u043e\u043d\u0438 \u043b\u0430\u0431\u0438 \u0431\u0430\u04b3\u0440\u0438 \u043a\u0430\u0431\u0443\u0434.\n\u041c\u0435\u0442\u0430\u0432\u043e\u043d\u0438\u0441\u0442\u04e3, \u043a\u0438 \u0434\u0430\u0440 \u0447\u0430\u0448\u043c\u043e\u043d\u0438 \u04ef\n\u041f\u0430\u0439 \u0431\u0430\u0440\u04e3 \u0430\u0437 \u043c\u0430\u049b\u0441\u0430\u0434\u0438 \u043f\u0438\u043d\u04b3\u043e\u043d\u0438 \u04ef.\n\u041c\u0435\u0434\u0430\u0432\u0438\u0434 \u043e\u043d \u04b3\u0430\u0440 \u0442\u0430\u0440\u0430\u0444 \u0431\u043e \u04b7\u0443\u0441\u0442\u0443\u04b7\u04ef,\n\u0421\u04ef\u0439\u0438 \u04b3\u0430\u0440 \u044f\u043a \u0440\u0430\u04b3\u0433\u0443\u0437\u0430\u0440 \u043e\u0432\u0430\u0440\u0434\u0430 \u0440\u04ef.\n\u041e\u0433\u0430\u04b3\u04e3 \u043c\u0435\u0434\u043e\u0434 \u0441\u0438\u043c\u043e\u0438 \u043f\u0438\u0441\u0430\u0440,\n\u041a-\u043e\u043c\u0430\u0434\u0430\u0441\u0442 \u0438\u043d \u04b7\u043e \u0432\u0430\u0439 \u0430\u0437 \u043c\u0443\u043b\u043a\u0438 \u0434\u0438\u0433\u0430\u0440.\n\u04ee \u043d\u0430\u0440\u0435\u0437\u043e\u043d\u0434\u0430\u0430\u0441\u0442 \u0445\u0443\u043d\u0438 \u043d\u043e\u0444\u0438 \u0445\u0443\u0434 ,\n\u0414\u0430\u0440 \u04b3\u0430\u043c\u0438\u043d \u0448\u0430\u04b3\u0440\u0438 \u043b\u0430\u0431\u0438 \u0431\u0430\u04b3\u0440\u0438 \u043a\u0430\u0431\u0443\u0434.\n\u0413\u0430\u0448\u0442 \u043c\u0430\u044a\u043b\u0443\u043c\u0430\u043c, \u043a\u0438 \u0430\u0444\u0493\u043e\u043d\u0431\u0430\u0447\u0430\u0435\u0441\u0442,\n\u0421\u043e\u0434\u0430\u044e \u0433\u0443\u043c\u0440\u043e\u04b3\u0443 \u043d\u043e\u0434\u043e\u043d\u0431\u0430\u0447\u0430\u0435\u0441\u0442.\n\u0413\u0430\u0448\u0442 \u043c\u0430\u044a\u043b\u0443\u043c\u0430\u043c, \u043a\u0438 \u043c\u0435\u04b3\u043c\u043e\u043d \u043e\u043c\u0430\u0434\u0430\u0441\u0442,\n\u041c\u0435\u04b3\u043c\u043e\u043d \u0430\u0437 \u043c\u0443\u043b\u043a\u0438 \u0430\u0444\u0493\u043e\u043d \u043e\u043c\u0430\u0434\u0430\u0441\u0442.\n\u0413\u0443\u0444\u0442\u0430\u043c: \xab\u042d\u0439 \u0441\u0430\u0439\u0451\u04b3\u0438 \u04b3\u0438\u043d\u0434\u0438 \u043a\u043e\u0431\u0443\u043b\u04e3\xbb,\n\u041a\u04ef\u0434\u0430\u043a\u0438 \u0445\u0443\u0440\u0434\u0438\u044e \u0434\u0430\u0440 \u04b3\u0443\u043a\u043c\u0438 \u0433\u0443\u043b\u04e3.\n\u04b6\u0438\u0441\u043c\u0438 \u0445\u0443\u0440\u0434\u0430\u0442\u0440\u043e \u0431\u0430 \u043f\u0443\u0448\u0442\u0438 \u04b2\u0438\u043d\u0434\u0443\u043a\u04ef\u0448,\n\u041a\u04e3 \u04b3\u0430\u0432\u043e \u0434\u043e\u0434, \u0430\u0437 \u0447\u04e3 \u043c\u0435\u0433\u0430\u0440\u0434\u04e3 \u0445\u0430\u043c\u04ef\u0448?\n\u0401 \u0442\u0443\u0440\u043e \u0431\u0430\u0445\u0442\u0438 \u0441\u0438\u0451\u04b3\u0430\u0442 \u0440\u043e\u043d\u0434\u0430\u0430\u0441\u0442?\n\u0411\u043e\u0434\u0438 \u0430\u0444\u0493\u043e\u043d\u04e3 \u043c\u0430\u0433\u0430\u0440 \u043f\u0430\u0440\u0440\u043e\u043d\u0434\u0430\u0430\u0441\u0442?\n\u0401 \u043a\u0430\u0441\u0435 \u0433\u0443\u0444\u0442\u0430\u0442, \u043a\u0438 \u0434\u0430\u0440 \u04b2\u0438\u043d\u0434\u0443\u0441\u0442\u043e\u043d\n\u0420\u0438\u0437\u049b\u0438 \u0438\u043d\u0441\u043e\u043d \u0430\u0441\u0442 \u0447\u0443\u043d \u043e\u0431\u0438 \u0440\u0430\u0432\u043e\u043d?\n\u04b2\u0430\u0440 \u0447\u04e3 \u043c\u0435\u0445\u043e\u04b3\u04e3, \u0442\u0443 \u043f\u0430\u0439\u0434\u043e \u043c\u0435\u043a\u0443\u043d\u04e3,\n\u041d\u043e\u0437\u0443 \u043d\u0435\u044a\u043c\u0430\u0442\u04b3\u043e \u043c\u0443\u04b3\u0430\u0439\u0451 \u043c\u0435\u043a\u0443\u043d\u04e3.\n\u041c\u0435\u0440\u0430\u0432\u0430\u0434 \u0434\u0430\u0440 \u04b7\u04ef\u0439\u04b3\u043e\u044f\u0448 \u04b7\u043e\u0439\u0438 \u043e\u0431,\n\u0414\u0430\u0440 \u0442\u0430\u043c\u043e\u043c\u0438 \u0444\u0430\u0441\u043b\u04b3\u043e \u0448\u0438\u0440\u0443 \u0448\u0430\u0440\u043e\u0431.\n\u0411\u0430\u043b\u043a\u0438 \u043e\u0432\u0430\u0440\u0434\u04e3 \u0442\u0443 \u04b3\u0430\u043d\u0433\u043e\u043c\u0438 \u0441\u0430\u0444\u0430\u0440.\n\u04b6\u0430\u043d\u043d\u0430\u0442\u0438 \u0430\u0444\u0441\u043e\u043d\u0430\u0432\u0438\u0440\u043e \u0434\u0430\u0440 \u043d\u0430\u0437\u0430\u0440.\n\u0418\u043d \u0437\u0430\u043c\u0438\u043d \u043a\u0430\u0440\u0434\u0430\u0441\u0442 \u0430\u0437 \u0434\u0430\u0432\u0440\u0438 \u043a\u0443\u04b3\u0430\u043d,\n\u0424\u0438\u043a\u0440\u0438 \u043e\u043b\u0430\u043c\u0440\u043e \u0430\u0441\u0438\u0440\u0438 \u0445\u0435\u0448\u0442\u0430\u043d.\n\u0425\u0443\u0431 \u043c\u0435\u0434\u043e\u043d\u0430\u043c, \u043a\u0438 \u0441\u04ef\u0439\u0438 \u0438\u043d \u0434\u0438\u0451\u0440,\n\u041d-\u043e\u043c\u0430\u0434\u04e3, \u043c\u043e\u043d\u0430\u043d\u0434\u0438 \u049b\u0430\u0432\u043c\u0438 \u0441\u0443\u0434\u0445\u043e\u0440.\n\u041d-\u043e\u043c\u0430\u0434\u04e3, \u0442\u043e \u043a\u0438 \u04b7\u0430\u04b3\u043e\u043d\u0433\u0438\u0440\u04e3 \u043a\u0443\u043d\u04e3,\n\u0417\u0443\u043b\u043c\u0438 \u043d\u0430\u0432 \u0431\u0430\u0445\u0448\u0438\u044e \u04b7\u043e\u043d\u0433\u0438\u0440\u04e3 \u043a\u0443\u043d\u04e3!\n\u041d-\u043e\u043c\u0430\u0434\u04e3 \u0442\u043e \u0445\u0443\u043d\u0438 \u04b3\u0438\u043d\u0434\u0443\u0440\u043e \u0445\u04ef\u0440\u04e3,\n\u0411\u0430\u0445\u0442\u0438 \u0431\u0430\u0434 \u043e\u0440\u0438\u044e \u043d\u0430\u0444\u044a\u0438 \u0441\u0430\u0434 \u0431\u0430\u0440\u04e3.\n\u041e\u043c\u0430\u0434\u04e3 \u0451\u0431\u04e3 \u0442\u0443 \u043d\u043e\u043d\u0438 \u0445\u0435\u0448\u0440\u043e,\n\u0417\u0438\u043d\u0434\u0430 \u0434\u043e\u0440\u04e3 \u0445\u0443\u0440\u0434 \u04b7\u043e\u043d\u0438 \u0445\u0435\u0448\u0440\u043e.\n\u0413\u0443\u0448\u043d\u0430\u0433\u04e3 \u043f\u0430\u0440\u0442\u043e\u0444\u0442\u0430\u0442 \u0431\u0435\u0445\u0430\u0439\u0440\u0443 \u0445\u0443\u0448,\n\u0414\u0430\u0440 \u043f\u0430\u0441\u0438 \u043a\u04ef\u04b3\u0438 \u0431\u0430\u043b\u0430\u043d\u0434\u0438 \u04b2\u0438\u043d\u0434\u0443\u043a\u0443\u0448.\n\u042d\u0439 \u04b7\u0430\u04b3\u043e\u043d\u0433\u0430\u0440\u0434\u0438 \u04b7\u0430\u0432\u043e\u043d\u0438 \u043a\u043e\u0431\u0443\u043b\u04e3,\n\u041a\u04ef\u0434\u0430\u043a\u0438 \u0445\u0443\u0440\u0434\u0438\u044e \u0434\u0430\u0440 \u04b3\u0443\u043a\u043c\u0438 \u0433\u0443\u043b\u04e3.\n\u04b2\u0430\u043c \u043f\u0430\u0434\u0430\u0440, \u04b3\u0430\u043c \u043c\u043e\u0434\u0430\u0440\u0438 \u0431\u0435\u043a\u043e\u0440\u0438 \u0442\u0443,\n\u0427\u0430\u0448\u043c \u0431\u0430\u0441\u0442\u0430 \u0434\u0430\u0440 \u0440\u0430\u04b3\u0438 \u0431\u043e\u0437\u043e\u0440\u0438 \u0442\u0443.\n\u041c\u0438\u0441\u043b\u0438 \u0442\u0443, \u0441\u0430\u0439\u0451\u04b3\u0438 \u0445\u0443\u0440\u0434\u0438 \u043d\u043e\u043c\u0443\u0440\u043e\u0434,\n\u0414\u0430\u0440 \u04b7\u0430\u0432\u043e\u043d\u04e3 \u043c\u0430\u043d \u043d\u0430\u0434\u0438\u0434\u0430\u043c \u0440\u04ef\u0437\u0438 \u0448\u043e\u0434.\n\u041c\u0435\u0448\u0443\u043d\u0438\u0434\u0430\u043c \u0430\u0437 \u043f\u0430\u0434\u0430\u0440 \u0448\u0430\u0431\u04b3\u043e\u0438 \u0442\u043e\u0440,\n\u041c\u0438\u0441\u043b\u0438 \u0442\u0443 \u0430\u0444\u0441\u043e\u043d\u0430\u04b3\u043e\u0438 \u0431\u0435\u0448\u0443\u043c\u043e\u0440.\n\u04ee, \u0431\u0430 \u043c\u0430\u043d \u043c\u0435\u0433\u0443\u0444\u0442: \xab\u0414\u0430\u0440 \u0441\u0430\u043c\u0442\u0438 \u04b6\u0430\u043d\u0443\u0431,\n\u041a\u0438\u0448\u0432\u0430\u0440\u0435 \u0431\u0438\u0441\u0451\u0440 \u0437\u0435\u0431\u043e\u044f\u0441\u0442\u0443 \u0445\u0443\u0431.\n\u0421\u0443\u0440\u0430\u0442\u0438 \u043e\u043d \u043c\u0430\u043c\u043b\u0430\u043a\u0430\u0442 \u0434\u0438\u0433\u0430\u0440 \u0431\u0443\u0432\u0430\u0434,\n\u041e\u0431\u04b3\u043e\u044f\u0448 \u043d\u0443\u049b\u0440\u0430, \u0445\u043e\u043a\u0430\u0448 \u0437\u0430\u0440 \u0431\u0443\u0432\u0430\u0434.\n\u041f\u0430\u0441\u0442\u0442\u0430\u0440 \u04b3\u0430\u0440 \u0441\u043e\u043b \u0433\u0430\u0440\u0434\u0430\u0434 \u041e\u0444\u0442\u043e\u0431,\n\u042f\u043a \u049b\u0430\u0434\u0438 \u043d\u0430\u0439\u0437\u0430 \u0431\u0430 \u0440\u04ef\u0439\u0438 \u0445\u043e\u043a\u0443 \u043e\u0431\xbb.\n\u041c\u0430\u043d \u0430\u043a\u043d\u0443\u043d \u0430\u0437 \u043c\u0443\u043b\u043a\u0438 \u0445\u0443\u0440\u0440\u0430\u043c \u043e\u043c\u0430\u0434\u0430\u043c,\n\u0427\u0443\u043d \u0432\u0430\u043a\u0438\u043b\u0438 \u0445\u0430\u043b\u049b\u0438 \u0430\u044a\u0437\u0430\u043c \u043e\u043c\u0430\u0434\u0430\u043c.\n\u041e\u043c\u0430\u0434\u0430\u043c, \u0434\u0438\u0434\u0430\u043c \u0442\u0443\u0440\u043e \u0431\u043e \u0447\u0430\u0448\u043c\u0438 \u0445\u0443\u0434,\n\u0414\u0430\u0440 \u0445\u0438\u0451\u0431\u043e\u043d\u0438 \u043b\u0430\u0431\u0438 \u0431\u0430\u04b3\u0440\u0438 \u043a\u0430\u0431\u0443\u0434.\n\u041c\u0435\u0434\u0430\u0432\u04e3, \u0431\u043e \u0447\u0430\u0448\u043c\u0438 \u043f\u0443\u0440\u043d\u0430\u043c \u043c\u0435\u0434\u0430\u0432\u04e3,\n\u041f\u0435\u0448\u0438 \u043f\u043e\u0439\u0438 \u043d\u043e\u043a\u0430\u0441\u043e\u043d \u0445\u0430\u043c \u043c\u0435\u0448\u0430\u0432\u04e3.\n\u041c\u0435\u043a\u0443\u043d\u04e3 \u0431\u043e \u0440\u0430\u043d\u0433\u0443\u0431\u043e\u0440\u0438 \u0445\u0435\u0448 \u043f\u043e\u043a,\n\u041c\u04ef\u0437\u0430\u04b3\u043e\u0438 \u0431\u0430\u0445\u0442\u0434\u0443\u0437\u0434\u043e\u043d\u0440\u043e \u0437\u0438 \u0445\u043e\u043a.\n\u042d\u0439 \u04b7\u0430\u04b3\u043e\u043d\u0433\u0430\u0440\u0434\u0438 \u04b7\u0430\u0432\u043e\u043d\u0438 \u043a\u043e\u0431\u0443\u043b\u04e3,\n\u041a\u04ef\u0434\u0430\u043a\u0438 \u0445\u0443\u0440\u0434\u0438\u044e \u0434\u0430\u0440 \u04b3\u0443\u043a\u043c\u0438 \u0433\u0443\u043b\u04e3.\n\u04b2\u0430\u0439\u0444\u0430\u043c \u043e\u044f\u0434, \u043a\u0438 \u0442\u0443 \u0434\u0430\u0440 \u0438\u043d \u0441\u0438\u043d\u043d\u0443 \u0441\u043e\u043b,\n\u041c\u043e\u043d\u0434\u0430\u04e3 \u0431\u0435\u0431\u0430\u04b3\u0440\u0430 \u0430\u0437 \u0444\u0430\u0437\u043b\u0443 \u043a\u0430\u043c\u043e\u043b.\n\u0414\u0443\u0437\u0434\u0438 \u0431\u0430\u0445\u0442\u0438 \u0445\u0430\u043b\u049b\u04b3\u043e \u043c\u0438\u043d\u0431\u0430\u044a\u0434 \u0431\u043e\u0437,\n\u041f\u043e\u0439\u0438 \u0445\u0443\u0434\u0440\u043e \u0441\u04ef\u0439\u0438 \u0442\u0443 \u0441\u043e\u0437\u0430\u0434 \u0434\u0430\u0440\u043e\u0437.\n\u0425\u043e\u043a\u0438 \u043f\u043e\u044f\u0448\u0440\u043e \u043d\u0430\u0431\u043e\u044f\u0434 \u043f\u043e\u043a \u043a\u0430\u0440\u0434,\n\u041f\u043e\u043a \u0430\u0437 \u043e\u043d \u0431\u043e\u044f\u0434, \u043a\u0438 \u0430\u043a\u043d\u0443\u043d \u0445\u043e\u043a \u043a\u0430\u0440\u0434.")
B.aeC=new A.a("708be42e-a591-40b1-965d-73b8a602b739","41c86281-0423-4553-91e8-5f8c298ed40f","\u04b2\u0435\u04b7 \u0448\u0443\u043d\u0438\u0434\u04e3 \u0433\u0430\u043f\u0438 \u0441\u0430\u0434\u0441\u043e\u043b\u0430\u0440\u043e,","\u04b2\u0435\u04b7 \u0448\u0443\u043d\u0438\u0434\u04e3 \u0433\u0430\u043f\u0438 \u0441\u0430\u0434\u0441\u043e\u043b\u0430\u0440\u043e,\n\u049a\u0438\u0441\u0441\u0430\u0438 \u0434\u0435\u0440\u0438\u043d\u0430\u0438 \u0411\u0430\u043d\u0433\u043e\u043b\u0430\u0440\u043e\n?\n\u04b2\u0435\u04b7 \u0448\u0443\u043d\u0438\u0434\u04e3, \u043a\u0438 \u0440\u0443\u0445\u0438 \u043e\u0441\u043c\u043e\u043d\n\u04b6\u0438\u043b\u0432\u0430 \u043a\u0443\u043d\u0430\u0434 \u043b\u0430\u044a\u043b\u0438\u0441\u0438\u0444\u0430\u0442 \u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d?\n\u04b2\u0435\u04b7 \u0448\u0443\u043d\u0438\u0434\u04e3 \u0442\u0443, \u043a\u0438 \u0434\u0430\u0440 \u041e\u0444\u0442\u043e\u0431,\n\u041e\u0431 \u0447\u0443 \u0441\u0438\u043c\u043e\u0431 \u0445\u04ef\u0440\u0430\u0434 \u043f\u0435\u0447\u0443\u0442\u043e\u0431?\n\u04b2\u0435\u04b7 \u0448\u0443\u043d\u0438\u0434\u04e3 \u0442\u0443, \u043a\u0438 \u043a\u04ef\u04b3\u0438 \u0431\u0430\u043b\u0430\u043d\u0434\n\u0414\u0430\u0440 \u0441\u0430\u0440\u0438 \u0445\u0443\u0434 \u0447\u0430\u0442\u0440 \u043a\u0430\u0448\u0430\u0434 \u0430\u0437 \u043f\u0430\u0440\u0430\u043d\u0434\n?\n\u041e\u0431 \u0440\u0430\u0432\u0430\u0434 \u0442\u0430\u0433-\u0442\u0430\u0433\u0438 \u044f\u0445\u04b3\u043e\u0438 \u043f\u0438\u0440,\n\u041c\u0438\u0441\u043b\u0438 \u04b7\u0430\u0432\u043e\u04b3\u0438\u0440 \u0437\u0438 \u0434\u0438\u043b\u0438 \u04b3\u0430\u0440 \u0430\u0434\u0438\u0440.\n\u041b\u043e\u043b\u0430\u0432\u0443 \u0441\u0435\u0431\u0430\u0440\u0433\u0430 \u0431\u0430 \u0432\u0430\u049b\u0442\u0438 \u0441\u0430\u04b3\u0430\u0440\n\u04b2\u0430\u043b\u049b\u0430\u0431\u0430\u0433\u04ef\u0448\u0430\u043d\u0434 \u0437\u0438 \u043b\u04ef\u044a\u043b\u04ef\u0438 \u0442\u0430\u0440.\n\u04b2\u0435\u04b7 \u0448\u0443\u043d\u0438\u0434\u04e3, \u043a\u0438 \u0431\u0430\u043b\u0430\u043d\u0434 \u0430\u0437 \u0441\u0430\u04b3\u043e\u0431,\n\u0421\u0430\u0439\u0440\u043a\u0443\u043d\u043e\u043d \u043b\u043e\u043d\u0430 \u0433\u0443\u0437\u043e\u0440\u0430\u0434 \u0443\u049b\u043e\u0431.\n\u0418\u043d \u04b3\u0430\u043c\u0430\u0440\u043e \u0431\u0438\u043d\u04e3 \u0442\u0443 \u0434\u0430\u0440 \u04b2\u0438\u043d\u0434\u0443\u043a\u0443\u0448,\n\u0414\u0430\u0440 \u0441\u0430\u0440\u0438 \u043a\u04ef\u04b3\u0438 \u0431\u0430\u043b\u0430\u043d\u0434\u0438 \u043d\u0443\u049b\u0440\u0430\u043f\u04ef\u0448.\n\u0413\u0430\u0448\u0442\u0430 \u0434\u0430\u0440 \u0438\u043d \u04b7\u043e \u0432\u0430\u0442\u0430\u043d\u0438 \u04b7\u043e\u043d\u0432\u0430\u0440\u043e\u043d\n\u2013 \u0411\u043e\u0439\u0442\u0430\u0440\u0438\u043d \u0441\u0430\u0439\u0434\u0433\u0430\u04b3\u0435 \u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d.\n\u041d\u0430\u044a\u0440\u0430\u0438 \u0444\u0438\u043b \u043e\u044f\u0434\u0443 \u0431\u0430\u0431\u0440\u0443 \u043f\u0430\u043b\u0430\u043d\u0433,\n\u0421\u0430\u0432\u0442\u0438 \u0445\u0443\u0448\u0438 \u0431\u0443\u043b\u0431\u0443\u043b\u0430\u043a\u043e\u043d \u0440\u0430\u043d\u0433-\u0440\u0430\u043d\u0433.\n\u04b2\u0430\u0441\u0442 \u0437\u0430\u043c\u0438\u043d\u0438 \u0437\u0430\u04b3\u0438 \u043f\u0443\u0440 \u0430\u0437 \u043c\u0430\u0493\u043e\u043a\n,\n\u041a-\u0430\u0437 \u043d\u0430\u043c\u0438 \u04ef \u043c\u0435\u0448\u0430\u0432\u0430\u0434 \u043e\u0434\u0430\u043c \u04b3\u0430\u043b\u043e\u043a.\n\u041c\u0430\u0439\u043c\u0443\u043d\u0438 \u043f\u043e\u0441\u04ef\u0445\u0442\u0430, \u0434\u0443\u043c\u0441\u04ef\u0445\u0442\u0430,\n\u041a\u0438\u0440\u043c\u0438 \u0447\u0443 \u0433\u0430\u0432\u04b3\u0430\u0440 \u0431\u0430 \u0448\u0430\u0431 \u0430\u0444\u0440\u04ef\u0445\u0442\u0430.\n\u0418\u043d \u04b3\u0430\u043c\u0430 \u0434\u0430\u0440 \u0431\u0435\u0448\u0430\u0438 \u04b2\u0438\u043d\u0434\u0443\u0441\u0442\u043e\u043d,\n\u0412\u043e\u04b3\u0438\u043c\u0430\u043d\u043e\u043a\u0430\u043d\u0434 \u0431\u0430 \u043f\u0438\u0440\u0443 \u04b7\u0430\u0432\u043e\u043d.\n\u0413\u0430\u0440 \u0431\u0438\u0440\u0430\u0432\u04e3 \u0442\u0443 \u0431\u0430 \u0442\u0430\u043c\u043e\u0448\u043e\u0438 \u0431\u043e\u0493,\n\u041c\u0435\u043a\u0443\u043d\u04e3 \u0430\u0437 \u0431\u04ef\u0439 \u043c\u0443\u0430\u0442\u0442\u0430\u0440 \u0434\u0438\u043c\u043e\u0493.\n\u0418\u043d \u04b3\u0430\u043c\u0430 \u0434\u0430\u0440 \u0434\u043e\u043c\u0430\u043d\u0438 \u0413\u0430\u043d\u0433 \u0430\u0441\u0442, \u0413\u0430\u043d\u0433,\n\u049a\u0438\u0441\u0441\u0430\u0438 \u0448\u04ef\u0440\u0430\u0444\u043a\u0430\u043d\u0438 \u0413\u0430\u043d\u0433 \u0430\u0441\u0442, \u0413\u0430\u043d\u0433.\n\u041d\u0430\u049b\u043b \u043d\u0430\u043c\u043e\u044f\u043d\u0434, \u043a\u0438 \u0430\u0437 \u0492\u0430\u0440\u0431\u0438 \u0442\u043e\u0440,\n\u041a\u0430\u0440\u0434 \u0441\u0430\u0444\u0430\u0440 \u0431\u0430\u043d\u0434\u0430\u0438 \u043a\u0438\u0431\u0440\u0443 \u0432\u0438\u049b\u043e\u0440.\n\u0414\u0430\u0440 \u0431\u0430\u0440\u0438 \u0445\u0443\u0434 \u043a\u0430\u0440\u0434\u0430 \u043b\u0438\u0431\u043e\u0441\u0438 \u0441\u0430\u0444\u0435\u0434,\n\u04b6\u043e\u0439 \u0431\u0430 \u0434\u0438\u043b \u0434\u043e\u0434\u0430 \u0443\u043c\u0435\u0434\u0438 \u043f\u0430\u043b\u0438\u0434.\n\u049a\u0443\u0432\u0432\u0430\u0438 \u043f\u0443\u0440\u04b7\u043e\u0437\u0438\u0431\u0430\u0438 \u0438\u043d \u0434\u0438\u0451\u0440,\n\u041a\u0430\u0440\u0434 \u0434\u0438\u043b\u0438 \u043c\u0430\u0440\u0434\u0430\u043a\u0438 \u0493\u0430\u0440\u0431\u04e3 \u0448\u0438\u043a\u043e\u0440.\n\u0414\u0430\u0493\u0434\u0430\u0493\u0430\u0438 \u04ef \u0437\u0438 \u04b3\u0430\u0434 \u0430\u0444\u0437\u0443\u043d \u0431\u0443\u0432\u0430\u0434,\n\u0410\u0437 \u0445\u0438\u0440\u0430\u0434\u0438 \u043e\u0434\u0430\u043c\u04e3 \u0431\u0435\u0440\u0443\u043d \u0431\u0443\u0432\u0430\u0434.\n\u0414\u0430\u0440 \u0434\u0438\u043b\u0438 \u04ef \u04b3\u0435\u04b7 \u043d\u0430\u0434\u043e\u0440\u0430\u0434 \u0430\u0441\u0430\u0440,\n\u0425\u0443\u0431\u0438\u0438 \u0438\u043d \u043c\u0430\u043c\u043b\u0430\u043a\u0430\u0442\u0438 \u0445\u043e\u043a\u0437\u0430\u0440.\n\u0410\u0431\u0440\u0438 \u0431\u0430\u043b\u0430\u043d\u0434\u0438 \u0441\u0430\u0440\u0438 \u0438\u043d \u043a\u04ef\u04b3\u0438 \u043f\u0438\u0440,\n\u041b\u0430\u0437\u0437\u0430\u0442\u0438 \u043f\u0430\u0440\u0432\u043e\u0437\u0438 \u0443\u049b\u043e\u0431\u0438 \u0434\u0430\u043b\u0435\u0440.\n\u041c\u0435\u0440\u0430\u0432\u0430\u0434 \u0430\u0437 \u043f\u0430\u0439\u0440\u0430\u04b3\u0430\u0438 \u043a\u04ef\u0447\u0430\u0431\u043e\u0493,\n\u0417\u0438\u043d\u0430\u0442\u0438 \u043e\u043d \u0431\u043e\u0493 \u043d\u0430\u043a\u0430\u0440\u0434\u0430 \u0441\u0443\u0440\u043e\u0493.\n\u041c\u0435\u0433\u0443\u0437\u0430\u0440\u0430\u0434 \u0430\u0437 \u0431\u0430\u0440\u0438 \u0432\u0430\u0439\u0440\u043e\u043d\u0430\u04b3\u043e,\n\u041c\u0430\u0434\u0440\u0430\u0441\u0430\u044e \u043e\u0431\u0438\u0434\u0430\u044e \u0445\u043e\u043d\u0430\u04b3\u043e.\n\u041c\u0435\u0433\u0443\u0437\u0430\u0440\u0430\u0434 \u04ef \u043d\u0430\u043d\u0430\u043c\u0443\u0434\u0430 \u043d\u0430\u0437\u0430\u0440,\n\u0411\u043e \u04b3\u0430\u044f\u04b7\u043e\u043d\u0438 \u0434\u0438\u043b\u0443 \u0448\u0430\u0432\u049b\u0438 \u0431\u0430 \u0441\u0430\u0440.\n\u0418\u0448\u049b\u0438 \u0433\u0443\u043b\u0443 \u043d\u043e\u043b\u0430\u0438 \u0431\u0443\u043b\u0431\u0443\u043b \u0430\u0441\u0430\u0440,\n\u04b2\u0435\u04b7 \u043d\u0430\u0434\u043e\u0440\u0430\u043d\u0434 \u0431\u0430 \u0438\u043d \u0440\u0430\u04b3\u0433\u0443\u0437\u0430\u0440.\n\u041e\u043c\u0430\u0434\u0443 \u0431\u0430\u0440 \u0433\u0430\u0440\u0434\u0430\u043d\u0438 \u04b3\u0438\u043d\u0434\u0443 \u043d\u0438\u0448\u0430\u0441\u0442,\n\u04b2\u0430\u0440 \u0447\u04e3 \u043a\u0438 \u043c\u0435\u0445\u043e\u0441\u0442, \u0433\u0438\u0440\u0438\u0444\u0442 \u04ef \u0431\u0430 \u0434\u0430\u0441\u0442.\n\u041f\u04ef\u0441\u0442\u0438 \u0440\u04ef\u0431\u043e\u04b3\u0443 \u043f\u0430\u043b\u0430\u043d\u0433\u043e\u043d \u0433\u0438\u0440\u0438\u0444\u0442,\n\u04b2\u043e\u0441\u0438\u043b\u0438 \u0431\u0435\u0447\u043e\u0440\u0430\u0438 \u0434\u0435\u04b3\u049b\u043e\u043d \u0433\u0438\u0440\u0438\u0444\u0442.\n\u041f\u0430\u0445\u0442\u0430\u044e \u0430\u0431\u0440\u0435\u0448\u0438\u043c\u0443 \u0433\u0430\u043d\u0434\u0443\u043c \u0433\u0438\u0440\u0438\u0444\u0442,\n\u041d\u043e\u043d\u0438 \u0434\u0430\u04b3\u043e\u043d\u0438 \u04b3\u0430\u043c\u0430 \u043c\u0430\u0440\u0434\u0443\u043c \u0433\u0438\u0440\u0438\u0444\u0442.\n\u0428\u0438\u0440\u0430\u0438 \u0438\u043d \u0431\u043e\u0439\u0437\u0430\u043c\u0438\u043d\u0440\u043e \u043a\u0430\u0448\u0438\u0434,\n\u0425\u0443\u043d\u0438 \u0434\u0438\u043b\u0438 \u0445\u0430\u043b\u049b\u0438 \u0433\u0430\u0434\u043e\u0440\u043e \u043c\u0430\u043a\u0438\u0434.\n\u04b2\u0443\u043a\u043c\u0438 \u0432\u0430\u0439 \u0438\u043c\u0440\u04ef\u0437 \u0430\u0433\u0430\u0440\u0447\u04e3 \u0440\u0430\u0432\u043e\u0441\u0442,\n\u041f\u043e\u044f\u0438 \u0438\u043d \u04b3\u0443\u043a\u043c \u0432\u0430\u043b\u0435 \u0431\u0435\u0431\u0430\u049b\u043e\u0441\u0442!\n\u04b2\u0435\u04b7 \u043d\u0430\u0434\u0438\u0434\u04e3 \u0442\u0443 \u0447\u0443\u043d\u0438\u043d \u043c\u0430\u049b\u0431\u0430\u0440\u0430,\n\u049a\u0430\u0441\u0440\u0443 \u0431\u0438\u043d\u043e\u04b3\u043e\u0438 \u0430\u04b7\u0438\u0431\u0438 \u0441\u0430\u0440\u0430.\n\u0413\u0443\u043d\u0431\u0430\u0437\u0438 \u043e\u043d \u043c\u0430\u0434\u0440\u0430\u0441\u0430\u04b3\u043e\u0438 \u049b\u0430\u0434\u0438\u043c,\n\u0428\u0430\u044a\u0448\u0430\u0430\u0438 \u043e\u0431\u0438\u0434\u0430\u04b3\u043e\u0438 \u0430\u0437\u0438\u043c.\n\u041d\u0430\u049b\u0448\u0443 \u043d\u0438\u0433\u043e\u0440\u0438 \u0434\u0430\u0440\u0443 \u0434\u0430\u0440\u0432\u043e\u0437\u0430\u04b3\u043e,\n\u0422\u043e\u04b7\u043c\u0430\u04b3\u0430\u043b \u0440\u0430\u0444\u0442\u0430 \u0434\u0430\u0440 \u043e\u0432\u043e\u0437\u0430\u04b3\u043e.\n\u0414\u0438\u0434\u0430\u04e3 \u0434\u0430\u0440 \u0437\u0435\u0440\u0438 \u0437\u0430\u043c\u0438\u043d \u0437\u0438\u043d\u0430\u04b3\u043e,\n\u0421\u043e\u0444\u0442\u0430\u0440 \u0430\u0437 \u0447\u0435\u04b3\u0440\u0430\u0438 \u043e\u0438\u043d\u0430\u04b3\u043e?\n\u041c\u0435\u0432\u0430\u0438 \u0448\u0438\u0440\u0438\u043d\u0438 \u0431\u0430 \u043c\u043e\u043d\u0430\u043d\u0434\u0438 \u049b\u0430\u043d\u0434,\n\u0421\u043e\u044f\u0438 \u0431\u043e\u0493\u0443 \u0447\u0430\u043c\u0430\u043d\u0438 \u0434\u0438\u043b\u043f\u0438\u0441\u0430\u043d\u0434?\n\u0414\u0438\u0434\u0430\u04e3 \u043e\u0451 \u0442\u0443 \u0431\u0430 \u0447\u0430\u0448\u043c\u0430\u0442 \u0430\u0451\u043d,\n\u041c\u0443\u044a\u04b7\u0438\u0437\u0430\u0438 \u043a\u0438\u0448\u0432\u0430\u0440\u0438 \u04b2\u0438\u043d\u0434\u0443\u0441\u0442\u043e\u043d?\n\u04b2\u0435\u04b7 \u043c\u0430\u0433\u0430\u0440 \u0434\u0438\u0434\u0430\u04e3 \u0434\u0430\u0440 \u0443\u043c\u0440\u0438 \u0445\u0443\u0434,\n\u0411\u043e\u0493\u0438 \u043c\u0443\u0430\u043b\u043b\u0430\u049b \u0447\u0443 \u0433\u0438\u043b\u0435\u043c\u0438 \u043a\u0430\u0431\u0443\u0434?\n\u0421\u0430\u043d\u044a\u0430\u0442\u0438 \u0434\u0430\u0440 \u043d\u043e\u0437\u0443\u043a\u04e3 \u043d\u043e\u0437\u0443\u043a\u0442\u0430\u0440\u0435.\n\u0414\u0443\u0445\u0442\u0430\u0440\u0430\u043a\u043e\u043d\u0438 \u0431\u0430 \u043c\u0438\u0441\u043b\u0438 \u043f\u0430\u0440\u04e3?\n\u0421\u043e\u0445\u0442\u0430 \u0430\u0437 \u043d\u0443\u049b\u0440\u0430\u0432\u0443 \u0437\u0430\u0440 \u043a\u043e\u0441\u0430\u04b3\u043e,\n\u0414\u0443\u0440\u0440\u0443 \u0437\u0430\u0440 \u043e\u0432\u0435\u0445\u0442\u0430 \u0440\u0430\u049b\u049b\u043e\u0441\u0430\u04b3\u043e.\n\u041a\u04ef\u0447\u0430\u044e \u0431\u043e\u0437\u043e\u0440 \u043f\u0443\u0440 \u0430\u0437 \u043c\u043e\u0440\u0431\u043e\u0437,\n\u0424\u043e\u043b\u0431\u0438\u043d\u0443 \u043c\u0430\u0440\u0434\u0443\u043c\u0438 \u043c\u0430\u0439\u043c\u0443\u043d\u043d\u0430\u0432\u043e\u0437.\n\u0414\u0430\u0440 \u0442\u0430\u043b\u0430\u0431\u0438 \u043d\u043e\u043d \u0448\u0443\u0434\u0430 \u04b7\u0430\u043c\u044a\u0435 \u04b3\u0430\u043b\u043e\u043a,\n\u0425\u0430\u0441\u0442\u0430\u044e, \u0430\u0444\u0442\u043e\u0434\u0430 \u0433\u0443\u0440\u04ef\u04b3\u0435 \u0431\u0430 \u0445\u043e\u043a.\n\u0414\u0438\u0434\u0430 \u043c\u0430\u043d \u0438\u043d\u0440\u043e \u04b7\u0438\u0433\u0430\u0440\u0430\u043c \u043f\u043e\u0440\u0430 \u0448\u0443\u0434,\n\u0410\u0448\u043a \u0440\u0430\u0432\u043e\u043d \u0430\u0437 \u0431\u0430\u0440\u0438 \u0440\u0443\u0445\u0441\u043e\u0440\u0430 \u0448\u0443\u0434.\n\u0418\u043d \u04b3\u0430\u043c\u0430 \u0434\u0430\u0440 \u043a\u04ef\u0447\u0430\u0438 \u041a\u0430\u043b\u043a\u0443\u0442\u0442\u0430 \u0431\u0443\u0434,\n\u0428\u0430\u04b3\u0440\u0438 \u043f\u0443\u0440 \u0430\u0437 \u04b3\u0430\u0440\u0437\u0430\u0432\u0443 \u0441\u0430\u0444\u0441\u0430\u0442\u0442\u0430 \u0431\u0443\u0434.\n\u0413\u0430\u0440\u0447\u0438 \u0441\u0430\u0440\u0438 \u0445\u0430\u043b\u049b \u0448\u0443\u0434 \u0430\u0437 \u0493\u0430\u043c \u0441\u0430\u0444\u0435\u0434,\n\u041f\u0443\u0440 \u0431\u0443\u0432\u0430\u0434, \u0430\u043c\u043c\u043e \u0434\u0438\u043b\u0438 \u04ef \u0430\u0437 \u0443\u043c\u0435\u0434.\n\u041f\u0430\u0439\u043a\u0430\u0440\u0438 \u043e\u043d \u0433\u0430\u0440\u0447\u0438 \u0447\u0443 \u0445\u043e\u043a\u0438\u0441\u0442\u0430\u0440 \u0430\u0441\u0442,\n\u041b\u0435\u043a \u043d\u0438\u04b3\u043e\u043d \u0434\u0430\u0440 \u0434\u0438\u043b\u0438 \u04ef \u0430\u0445\u0433\u0430\u0440 \u0430\u0441\u0442.\n\u0413\u0430\u0440\u0447\u0438 \u0431\u0430 \u0493\u043e\u0440\u0430\u0442 \u0440\u0430\u0432\u0430\u0434 \u0438\u043d \u0441\u0430\u0440\u0437\u0430\u043c\u0438\u043d,\n\u0411\u043e\u0437 \u0434\u0430\u0440 \u043e\u043d \u0433\u0430\u043d\u04b7\u0438 \u0440\u0430\u0432\u043e\u043d\u0440\u043e \u0431\u0443\u0431\u0438\u043d.\n\u041c\u0435\u04b3\u043d\u0430\u0442\u0438 \u0434\u0435\u04b3\u049b\u043e\u043d\u043f\u0438\u0441\u0430\u0440\u0443 \u043a\u043e\u0440\u0433\u0430\u0440\n\u0410\u0437 \u04b3\u0430\u043c\u0430 \u0430\u0448\u0451\u0438 \u04b7\u0430\u04b3\u043e\u043d \u043c\u0443\u0444\u0442\u0442\u0430\u0440.\n\u0418\u043d \u043c\u0430\u0433\u0430\u0440 \u0430\u0444\u0441\u043e\u043d\u0430\u0438 \u0411\u0430\u043d\u0433\u043e\u043b\u0430 \u0430\u0441\u0442?\n\u049a\u0438\u0441\u0441\u0430\u0438 \u0431\u0430\u0434\u0431\u0430\u0445\u0442\u0438\u0438 \u0441\u0430\u0434\u0441\u043e\u043b\u0430 \u0430\u0441\u0442?\n\u041c\u0435\u0433\u0443\u0437\u0430\u0440\u0430\u0434 \u043c\u0430\u0493\u0440\u0438\u0431\u0438\u0438 \u0445\u0443\u0434\u043f\u0438\u0441\u0430\u043d\u0434,\n\u041a\u0430\u0440\u0434\u0430 \u0441\u0430\u0440\u0443 \u0431\u0438\u043d\u0438\u0438 \u0445\u0443\u0434\u0440\u043e \u0431\u0430\u043b\u0430\u043d\u0434.\n\u0411\u043e\u0437\u0438\u043a\u0443\u043d\u043e\u043d \u0447\u04ef\u0431-\u0430\u0441\u043e\u0440\u043e \u0431\u0430 \u0434\u0430\u0441\u0442,\n\u0428\u043e\u043c\u0443 \u0441\u0430\u04b3\u0430\u0440 \u0440\u043e\u04b3 \u0440\u0430\u0432\u0430\u0434 \u043c\u0438\u0441\u043b\u0438 \u043c\u0430\u0441\u0442.\n\u0411\u0430\u04b3\u0440\u0438 \u0447\u04e3 \u0438\u043d \u043c\u0430\u0493\u0440\u0438\u0431\u0438\u0438 \u0434\u0438\u043b\u0441\u0438\u0451\u04b3,\n\u041a\u0430\u0440\u0434\u0430 \u04b3\u0430\u0440\u0438\u0441\u043e\u043d\u0430 \u0431\u0430 \u041c\u0430\u0448\u0440\u0438\u049b \u043d\u0438\u0433\u043e\u04b3?\n\u0411\u0443\u0440\u0434 \u0434\u0438\u043b\u0430\u0448\u0440\u043e \u043c\u0430\u0433\u0430\u0440 \u0438\u043d \u0441\u0430\u0440\u0437\u0430\u043c\u0438\u043d,\n\u0411\u04ef\u0439\u0438 \u0445\u0443\u0448\u0438 \u0438\u043d \u0447\u0430\u043c\u0430\u043d\u0438 \u043d\u043e\u0437\u0430\u043d\u0438\u043d?\n\u0401 \u04b3\u0430\u0432\u0430\u0441\u0438 \u0434\u0438\u0434\u0430\u043d\u0438 \u0431\u04ef\u0437\u0438\u043d\u0430\u04b3\u043e,\n\u0401 \u0431\u0430 \u043a\u0430\u0444 \u043e\u0432\u0430\u0440\u0434\u0430\u043d\u0438 \u0433\u0430\u043d\u04b7\u0438\u043d\u0430\u04b3\u043e?\n\u041d\u0430\u049b\u043b \u043d\u0430\u043c\u043e\u044f\u043d\u0434, \u043a\u0438 \u0430\u0437 \u0493\u0430\u0440\u0431\u0438 \u0442\u043e\u0440,\n\u041a\u0430\u0440\u0434 \u0441\u0430\u0444\u0430\u0440 \u043e\u0434\u0430\u043c\u0438 \u0431\u0435\u043d\u0430\u043d\u0433\u0443 \u043e\u0440.\n\u041d\u043e\u043c \u0431\u0430\u0440\u043e\u0432\u0430\u0440\u0434 \u0431\u0430 \u0441\u0430\u043d\u0433\u0438\u043d\u0434\u0438\u043b\u04e3,\n\u0422\u0443\u0445\u043c\u0438 \u0441\u0438\u0442\u0430\u043c \u043a\u043e\u0448\u0442\u0430\u043d\u0443 \u04b7\u043e\u04b3\u0438\u043b\u04e3.\n\u0414\u0430\u0440 \u0434\u0438\u043b\u0438 \u04ef \u04b3\u0435\u0447 \u043d\u0430\u0434\u043e\u0440\u0430\u0434 \u0430\u0441\u0430\u0440,\n\u041d\u043e\u043b\u0430\u044e \u0444\u0430\u0440\u0451\u0434\u0438 \u043f\u0430\u0434\u0430\u0440 \u0451 \u043f\u0438\u0441\u0430\u0440.\n\u0417\u0438\u043d\u043d\u0430\u0442\u0438 \u0431\u043e\u0493\u0443 \u0447\u0430\u043c\u0430\u043d\u0438 \u0434\u0438\u043b\u0444\u0438\u0440\u0435\u0431,\n\u0420\u04ef\u0439\u0438 \u0433\u0443\u043b\u0443 \u0441\u0430\u0432\u0442\u0438 \u0445\u0443\u0448\u0438 \u0430\u043d\u0434\u0430\u043b\u0435\u0431.\n\u0411\u043e \u0441\u0430\u0440\u0438 \u043f\u0443\u0440\u0444\u0438\u0442\u043d\u0430\u044e \u0431\u043e \u043a\u0430\u0440\u0440\u0443\u0444\u0430\u0440,\n\u041c\u0435\u043a\u0443\u043d\u0430\u0434 \u0430\u0437 \u0431\u0430\u0439\u043d\u0438 \u0445\u0430\u043b\u043e\u0438\u049b \u0433\u0443\u0437\u0430\u0440.\n\u041c\u0435\u043a\u0443\u043d\u0430\u0434 \u0438\u043d \u0493\u0430\u0440\u0431\u0438\u0438 \u0440\u04ef\u0431\u0430\u04b3\u043c\u0438\u04b7\u043e\u0437\n\u0414\u0430\u0441\u0442\u0438 \u0442\u0430\u043c\u0430\u044a\u0440\u043e \u0441\u04ef\u0439\u0438 \u04b3\u0438\u043d\u0434\u0443 \u0434\u0430\u0440\u043e\u0437:\n\xab\u0414\u0443\u0440\u0440\u0438 \u0433\u0430\u0440\u043e\u043d\u0440\u043e \u0431\u0430 \u043a\u0430\u0444\u0438 \u043c\u0430\u043d \u0431\u0438\u043d\u0435\u04b3,\n\u0417\u0430\u0440 \u0431\u0438\u0434\u0435\u04b3\u0443 \u0437\u0430\u0440 \u0431\u0438\u0434\u0435\u04b3\u0443 \u0437\u0430\u0440 \u0431\u0438\u0434\u0435\u04b3\xbb.\n\u041c\u0435\u0433\u0443\u0437\u0430\u0440\u0430\u0434 \u0434\u0443\u0440\u0442\u0430\u0440 \u0430\u0437 \u0438\u0437\u0434\u0438\u04b3\u043e\u043c,\n\u0411\u0435 \u043d\u0430\u0437\u0430\u0440\u0438 \u0434\u0438\u049b\u049b\u0430\u0442\u0443 \u0431\u0435 \u044d\u04b3\u0442\u0438\u0440\u043e\u043c.\n\u0413\u043e\u04b3 \u043d\u0430\u043c\u043e\u0451\u043d \u0448\u0430\u0432\u0430\u0434 \u04ef \u0447\u0443\u043d \u0441\u0438\u043f\u043e\u04b3,\n\u0413\u043e\u04b3 \u0431\u0430 \u043c\u043e\u043d\u0430\u043d\u0434\u0438 \u0433\u0430\u0434\u043e\u0451\u043d\u0438 \u0440\u043e\u04b3.\n\u0413\u043e\u04b3 \u0447\u0443 \u044f\u043a \u0433\u0443\u0440\u0431\u0430\u0438 \u043f\u043e\u044f\u043d\u0434\u0430\u043c\u0443\u0448,\n\u0413\u043e\u04b3 \u0433\u0443\u0440\u0435\u0437\u0430\u043d\u0434\u0430 \u0447\u0443 \u043c\u0443\u0448\u0438 \u0445\u0430\u043c\u04ef\u0448.\n\u04b2\u0430\u0440 \u0447\u04e3 \u043a\u0438 \u043c\u0435\u0445\u043e\u0441\u0442 \u0434\u0430\u0440 \u0438\u043d \u0441\u0430\u0440\u0437\u0430\u043c\u0438\u043d,\n\u041f\u0443\u0440\u0440\u0430 \u0434\u0430\u0440\u043e\u0432\u0430\u0440\u0434 \u0431\u0430 \u0437\u0435\u0440\u0438 \u043d\u0438\u0433\u0438\u043d.\n\u041f\u04ef\u0441\u0442\u0438 \u0440\u04ef\u0431\u043e\u04b3\u0443 \u043f\u0430\u043b\u0430\u043d\u0433\u043e\u043d \u0433\u0438\u0440\u0438\u0444\u0442,\n\u04b2\u043e\u0441\u0438\u043b\u0438 \u0441\u0430\u0440\u043f\u0430\u043d\u04b7\u0430\u0438 \u0434\u0435\u04b3\u049b\u043e\u043d \u0433\u0438\u0440\u0438\u0444\u0442.\n\u041d\u0443\u049b\u0440\u0430\u0432\u0443 \u0442\u0438\u043b\u043b\u043e \u0437\u0438 \u0434\u0438\u043b\u0438 \u043a\u043e\u043d \u0433\u0438\u0440\u0438\u0444\u0442.\n\u0422\u043e\u049b\u0430\u0442\u0443 \u043e\u0440\u043e\u043c\u0438 \u0444\u0430\u049b\u0438\u0440\u043e\u043d \u0433\u0438\u0440\u0438\u0444\u0442.\n\u04b2\u0443\u043a\u043c\u0438 \u0432\u0430\u0439 \u0438\u043c\u0440\u04ef\u0437 \u0430\u0433\u0430\u0440\u0447\u0438 \u0440\u0430\u0432\u043e\u0441\u0442,\n\u041f\u043e\u044f\u0438 \u0438\u043d \u04b3\u0443\u043a\u043c \u0432\u0430\u043b\u0435 \u0431\u0435\u0431\u0430\u049b\u043e\u0441\u0442!\n\u0424\u0443\u0440\u0441\u0430\u0442\u0438 \u043e\u043d \u0430\u0441\u0442, \u043a\u0438 \u0438\u043d \xab\u043c\u0435\u04b3\u043c\u043e\u043d\xbb,\n\u0422\u0430\u0440\u043a \u043a\u0443\u043d\u0430\u0434 \u043a\u0438\u0448\u0432\u0430\u0440\u0438 \u04b2\u0438\u043d\u0434\u0443\u0441\u0442\u043e\u043d.\n\u0427\u0443\u043d\u043a\u0438 \u0434\u0430\u0440 \u0438\u043d \u043c\u0430\u043c\u043b\u0430\u043a\u0430\u0442 \u0438\u043d \u0437\u0430\u0440\u043f\u0430\u0440\u0430\u0441\u0442,\n\u04b2\u0435\u0447 \u0431\u0430 \u0447\u0438\u0437\u0438 \u0434\u0438\u0433\u0430\u0440\u0435 \u0434\u0438\u043b \u043d\u0430\u0431\u0430\u0441\u0442.\n\u0421\u0430\u0440 \u043d\u0430\u0437\u0430\u0434 \u0430\u0437 \u043c\u0430\u0493\u0440\u0438\u0431\u0438\u0438 \u0431\u0435\u043a\u0430\u0440\u0430\u043c,\n\u0427\u0438\u0437\u0438 \u0434\u0438\u0433\u0430\u0440 \u0493\u0430\u0439\u0440\u0438 \u04b7\u0430\u0444\u043e\u044e \u0441\u0438\u0442\u0430\u043c.\n\u0422\u0438\u0440 \u043d\u0430\u0437\u0430\u0434 \u043c\u0430\u0493\u0440\u0438\u0431\u0438\u0438 \u0434\u0438\u043b\u0441\u0438\u0451\u04b3,\n\u04b6\u0443\u0437 \u0431\u0430 \u0434\u0438\u043b\u0438 \u0445\u0430\u043b\u049b \u0434\u0430\u0440 \u0438\u043d \u0441\u0430\u0439\u0434\u0433\u043e\u04b3.\n\u0413\u0430\u0440\u0447\u0438 \u0434\u0443\u0441\u0430\u0434 \u0441\u043e\u043b \u0434\u0430\u0440 \u0438\u043d \u0445\u043e\u043d\u0430 \u043c\u043e\u043d\u0434,\n\u0411\u043e\u0437 \u0431\u0430 \u0438\u043d \u043e\u0438\u043b\u0430 \u0431\u0435\u0433\u043e\u043d\u0430 \u043c\u043e\u043d\u0434.\n\u04b2\u0443\u043a\u043c\u0438 \u0432\u0430\u0439 \u0438\u043c\u0440\u04ef\u0437 \u0430\u0433\u0430\u0440\u0447\u0438 \u0440\u0430\u0432\u043e\u0441\u0442,\n\u041f\u043e\u044f\u0438 \u0438\u043d \u04b3\u0443\u043a\u043c \u0432\u0430\u043b\u0435 \u0431\u0435\u0431\u0430\u049b\u043e\u0441\u0442!")
B.aq_=new A.a("6f3253d5-2595-4e0e-9841-249773d64979","41c86281-0423-4553-91e8-5f8c298ed40f","\u0414\u0443\u0445\u0442\u0430\u0440\u0438 \u04b3\u0438\u043d\u0434\u04e3 \u0430\u0434\u043e\u043b\u0430\u0442\u0445\u043e\u04b3 \u0448\u0443\u0434,","\u0414\u0443\u0445\u0442\u0430\u0440\u0438 \u04b3\u0438\u043d\u0434\u04e3 \u0430\u0434\u043e\u043b\u0430\u0442\u0445\u043e\u04b3 \u0448\u0443\u0434,\n\u0410\u0437 \u0431\u0430\u0434\u0443 \u043d\u0435\u043a\u0438 \u04b7\u0430\u04b3\u043e\u043d \u043e\u0433\u043e\u04b3 \u0448\u0443\u0434.\n\u04b6\u0443\u0441\u0442\u0443\u04b7\u04ef \u043c\u0435\u043a\u0430\u0440\u0434 \u043e\u043d \u0438\u043d\u0441\u043e\u0444\u0440\u043e,\n\u041e\u0441\u043c\u043e\u043d\u0438 \u0441\u043e\u0444\u0438 \u043a\u04ef\u04b3\u0438 \u049a\u043e\u0444\u0440\u043e.\n\u041e\u043b\u0430\u043c\u0438 \u0430\u0437 \u0448\u04ef\u0440\u0443 \u0493\u0430\u0432\u0493\u043e \u043f\u043e\u043a\u0440\u043e,\n\u0420\u04ef\u04b3\u043f\u0430\u0440\u0432\u0430\u0440, \u0442\u043e\u0437\u0430\u0432\u0443 \u0442\u0430\u0440 \u0445\u043e\u043a\u0440\u043e.\n\u0414\u04ef\u0441\u0442\u0438\u0440\u043e, \u0447\u0435\u04b3\u0440\u0430\u04b3\u043e\u0438 \u0431\u043e\u0437\u0440\u043e,\n\u0411\u043e\u043c\u0434\u043e\u0434\u0438 \u0440\u04ef\u0437\u0438 \u043d\u0435\u043a\u043e\u0493\u043e\u0437\u0440\u043e.\n\u0427\u0430\u0448\u043c\u0438 \u0430\u049b\u043b\u0438 \u0445\u0443\u0434 \u0431\u0430 \u043e\u043b\u0430\u043c \u0447\u0443\u043d \u043a\u0443\u0448\u043e\u0434,\n\u0410\u0437 \u04b7\u0430\u0444\u043e\u0431\u0438\u043d\u04e3 \u0431\u0430 \u0434\u043e\u0434 \u043e\u043c\u0430\u0434, \u0431\u0430 \u0434\u043e\u0434.\n\u0420\u04ef\u0439\u0438 \u043e\u043d \u043c\u0438\u0441\u043b\u0438 \u0433\u0443\u043b\u0438 \u043f\u0430\u0436\u043c\u0443\u0440\u0434\u0430 \u0448\u0443\u0434,\n\u0414\u0430\u0440 \u0434\u0430\u0440\u0443\u043d\u0438 \u0441\u0438\u043d\u0430 \u0434\u0438\u043b \u0430\u0444\u0448\u0443\u0440\u0434\u0430 \u0448\u0443\u0434.\n\u0420\u04ef\u0437 \u0430\u0437 \u0440\u04ef\u0437 \u043e\u0431 \u043c\u0435\u0448\u0443\u0434 \u043c\u0438\u0441\u043b\u0438 \u043c\u0443\u043c,\n\u0492\u0430\u043c \u0431\u0430 \u04ef \u043c\u0435\u043a\u0430\u0440\u0434 \u0447\u0443\u043d \u043e\u0442\u0430\u0448 \u04b3\u0443\u04b7\u0443\u043c.\n\u0427\u0443\u043d \u0431\u0430 \u0434\u0430\u0440 \u043c\u0435\u0431\u0430\u0441\u0442 \u0447\u0430\u0448\u043c\u0438 \u0438\u043d\u0442\u0438\u0437\u043e\u0440,\n\u0401\u0434 \u043c\u0435\u043a\u0430\u0440\u0434 \u0430\u0437 \u0441\u0443\u0445\u0430\u043d\u04b3\u043e\u0438 \u0422\u0430\u0433\u043e\u0440:\n\xab\u04b2\u0430\u0440 \u049b\u0430\u0434\u0430\u0440 \u0437\u0430\u043d\u04b7\u0438\u0440 \u0433\u0430\u0440\u0434\u0430\u0434 \u0442\u0430\u043d\u0433\u0442\u0430\u0440,\n\u0422\u043e\u0431 \u0432\u0430\u049b\u0442\u0438 \u043a\u0430\u0448\u043c\u0430\u043a\u0430\u0448 \u043d-\u043e\u0440\u0430\u0434 \u0434\u0438\u0433\u0430\u0440\xbb.\n\u0425\u0443\u0434 \u0431\u0430 \u0445\u0443\u0434 \u043c\u0435\u0445\u043e\u043d\u0434 \xab\u0411\u0430\u043d\u0434\u0438 \u043c\u043e\u0442\u0430\u0440\u0430\u043c\xbb:\n\xab\u041e\u0431\u0438 \u0413\u0430\u043d\u0433\u0430 \u043e\u0448\u0438\u049b\u0438 \u0445\u043e\u043a\u0438\u0441\u0442\u0430\u0440\u0430\u043c\xbb.\n\u041a\u04ef\u04b3\u0438 \u0441\u0430\u0431\u0440 \u0430\u043a\u043d\u0443\u043d \u0447\u0443 \u0432\u0443\u043b\u049b\u043e\u043d \u0433\u0430\u0448\u0442\u0430 \u0431\u0443\u0434,\n\u0427\u0430\u0448\u043c\u0438 \u0434\u0430\u0440\u0451\u0438 \u0445\u0443\u0440\u04ef\u0448\u043e\u043d \u0433\u0430\u0448\u0442\u0430 \u0431\u0443\u0434.\n\u0427\u0430\u043d\u0434 \u2013 \u0411\u0438\u0431\u0438\u0440\u043e \u0431\u0430 \u0445\u0443\u043d \u043e\u0493\u04ef\u0448\u0442\u0430 \u0434\u0438\u0434,\n\u0414\u0430\u0440 \u043c\u0443\u049b\u043e\u0431\u0438\u043b \u0434\u0443\u0448\u043c\u0430\u043d\u043e\u043d\u0440\u043e \u043a\u0443\u0448\u0442\u0430 \u0434\u0438\u0434.\n\u0425\u043e\u0441\u0442 \u0447\u0443\u043d \u0431\u043e\u0434\u0435, \u043a\u0438 \u043e\u044f\u0434 \u0430\u0437 \u0434\u0430\u0440\u0430,\n\u0414\u0430\u0440 \u0431\u0438\u0451\u0431\u043e\u043d \u043f\u0430\u04b3\u043d \u0433\u0430\u0440\u0434\u0430\u0434 \u044f\u043a\u0441\u0430\u0440\u0430.\n\u0410\u0437 \u0434\u0430\u043c\u0430\u0448 \u0440\u04ef\u0431\u0430\u0434 \u0445\u0430\u0441\u0443 \u0445\u043e\u0448\u043e\u043a\u0440\u043e,\n\u041f\u043e\u043a \u0441\u043e\u0437\u0430\u0434, \u043f\u043e\u043a \u0440\u04ef\u0439\u0438 \u0445\u043e\u043a\u0440\u043e.\n\u0414\u0443\u0445\u0442\u0430\u0440\u0438 \u04b3\u0438\u043d\u0434\u04e3 \u0430\u0434\u043e\u043b\u0430\u0442\u0445\u043e\u04b3 \u0448\u0443\u0434,\n\u0410\u0437 \u0431\u0430\u0434\u0443 \u043d\u0435\u043a\u0438 \u04b7\u0430\u04b3\u043e\u043d \u043e\u0433\u043e\u04b3 \u0448\u0443\u0434.\n\u0410\u0437 \u043d\u0438\u0448\u0430\u0441\u0442\u0430\u043d, \u0441\u0430\u0431\u0440 \u043a\u0430\u0440\u0434\u0430\u043d \u043e\u0440 \u043a\u0430\u0440\u0434,\n\u0425\u0435\u0448\u0440\u043e \u0434\u0430\u0440 \u043a\u04ef\u0447\u0430\u0432\u0443 \u0431\u043e\u0437\u043e\u0440 \u043a\u0430\u0440\u0434.\n\u041a\u0443\u043b\u0431\u0430\u0438 \u0432\u0430\u0439\u0440\u043e\u043d\u0430\u0440\u043e \u043f\u0430\u0440\u0442\u043e\u0444\u0442, \u0440\u0430\u0444\u0442,\n\u0411\u0430\u0445\u0442\u0438 \u043d\u043e\u043f\u0430\u0439\u0434\u043e\u0438 \u0445\u0443\u0434\u0440\u043e \u043a\u043e\u0444\u0442, \u0440\u0430\u0444\u0442.\n\u041a\u04ef\u0447\u0430\u0432\u0443 \u0431\u043e\u0437\u043e\u0440 \u043f\u0443\u0440 \u0431\u0443\u0434 \u0430\u0437 \u0433\u0430\u0434\u043e,\n\u0410\u0437 \u0433\u0430\u043f\u0438 \xab\u0431\u0430\u0445\u0448\u0438\u0448\u0443\xbb \u0430\u0437 \u0434\u0430\u0440\u0432\u0435\u0448\u04b3\u043e.\n\u0422\u0430\u0440\u043a \u043a\u0430\u0440\u0434\u0430 \u043e\u0434\u0430\u043c\u043e\u043d \u0411\u0430\u043d\u0433\u043e\u043b\u0430\u0440\u043e,\n\u04b2\u0430\u0432\u043b\u0438\u044e \u0433\u043e\u0432\u0443 \u0431\u0443\u0437\u0443 \u0431\u0443\u0437\u0493\u043e\u043b\u0430\u0440\u043e.\n\u04b2\u0438\u043d\u0434\u04e3 \u0430\u0437 \u0434\u0430\u0441\u0442\u0438 \u043c\u0443\u0441\u0443\u043b\u043c\u043e\u043d \u0434\u0430\u0440 \u0430\u0437\u043e\u0431,\n\u0425\u0443\u0434 \u043c\u0443\u0441\u0443\u043b\u043c\u043e\u043d \u0430\u0441\u0442 \u0431\u043e \u04b3\u043e\u043b\u0438 \u0445\u0430\u0440\u043e\u0431.\n\u042f\u043a \u04b3\u0430\u0432\u043e\u0432\u0443 \u044f\u043a \u0437\u0430\u043c\u0438\u043d\u0443 \u043e\u0431\u0440\u043e,\n\u042f\u043a \u043c\u0430\u043a\u043e\u043d, \u044f\u043a \u04b7\u043e\u0439\u0438 \u0445\u04ef\u0440\u0434\u0443 \u0445\u043e\u0431\u0440\u043e.\n\u042f\u043a \u0493\u0430\u043c\u0443 \u0430\u043d\u0434\u0443\u04b3\u0440\u043e, \u044f\u043a \u0434\u0430\u0440\u0434\u0440\u043e,\n\u042f\u043a \u0441\u0430\u0434\u043e\u0438 \u0434\u0438\u043b, \u044f\u043a \u043e\u04b3\u0438 \u0441\u0430\u0440\u0434\u0440\u043e.\n\u0492\u0430\u0439\u0440 \u2013 \u0431\u0435\u0432\u0438\u04b7\u0434\u043e\u043d \u0431\u0430 \u0434\u0443 \u0442\u0430\u049b\u0441\u0438\u043c \u043a\u0430\u0440\u0434,\n\u041c\u0430\u043c\u043b\u0430\u043a\u0430\u0442\u0440\u043e \u04b7\u043e\u0439\u0438 \u0445\u0430\u0432\u0444\u0443 \u0431\u0438\u043c \u043a\u0430\u0440\u0434.\n\u0414\u0443\u0445\u0442\u0430\u0440\u0438 \u04b3\u0438\u043d\u0434\u04e3 \u0431\u0430 \u04b3\u0430\u0440 \u0441\u04ef \u0447\u0430\u0448\u043c \u0434\u04ef\u0445\u0442,\n\u04b2\u0430\u0440 \u043d\u0438\u0433\u043e\u04b3\u0430\u0448 \u0447\u0443\u043d \u0448\u0430\u0444\u0430\u049b \u0430\u0444\u0440\u04ef\u0445\u0442, \u0441\u04ef\u0445\u0442.\n\u041c\u043e\u043d\u0434\u0430 \u0431\u0443\u0434 \u0445\u043e\u043c\u04ef\u0448 \u0442\u04ef\u043f\u0438 \xab\u0417\u0430\u043c\u0437\u0430\u043c\u0430\xbb,\n\u0413\u04ef\u0448\u0440\u043e \u043a\u0430\u0440 \u043a\u0430\u0440\u0434\u0430 \xab\u0421\u0443\u043b\u0442\u043e\u043d \u04b6\u0430\u043c\u04b7\u0430\u043c\u0430\xbb.\n\u0414\u0438\u0434 \u043e\u043d \u0442\u04ef\u0444\u043e\u043d\u0438 \u043c\u043e\u04b3\u0438 \u04b3\u0443\u0442\u0440\u043e,\n\u04b2\u0430\u043c \u043a\u0430\u0444\u0430\u043d, \u04b3\u0430\u043c \u0433\u04ef\u0440, \u04b3\u0430\u043c \u0442\u043e\u0431\u0443\u0442\u0440\u043e.\n\u0428\u0443\u0434 \u0431\u0430 \u0447\u0430\u0448\u043c\u0430\u0448 \u043c\u0438\u0441\u043b\u0438 \u0438\u0431\u043b\u0438\u0441\u0438 \u043f\u0430\u043b\u0438\u0434,\n\u0421\u043e\u044f\u0438 \u0493\u0430\u0444\u0441\u0438 \u041c\u0430\u0443\u043d\u0431\u0435\u0442\u0442\u0435\u043d \u043f\u0430\u0434\u0438\u0434.\n\u0414\u0443\u0445\u0442\u0430\u0440\u0438 \u04b3\u0438\u043d\u0434\u04e3 \u0430\u0434\u043e\u043b\u0430\u0442\u0445\u043e\u04b3 \u0448\u0443\u0434,\n\u0410\u0437 \u0431\u0430\u0434\u0443 \u043d\u0435\u043a\u0438 \u04b7\u0430\u04b3\u043e\u043d \u043e\u0433\u043e\u04b3 \u0448\u0443\u0434.\n\u041a\u0430\u0440\u0434 \u0430\u0437 \u041b\u043e\u04b3\u0443\u0440\u0438 \u043f\u0443\u0440\u0434\u0430\u04b3\u0448\u0430\u0442 \u0444\u0438\u0440\u043e\u0440,\n\u0427\u0443\u043d \u0440\u0430\u043c\u0438\u0434\u0430 \u0441\u0430\u0439\u0434 \u0441\u04ef\u0439\u0438 \u043a\u04ef\u04b3\u0441\u043e\u0440.\n\u041e\u0440\u0437\u0443\u0438 \u0433\u04ef\u0448\u0430\u0438 \u041a\u0430\u0448\u043c\u0438\u0440 \u043a\u0430\u0440\u0434,\n\u0428\u0438\u043a\u0432\u0430 \u0430\u0437 \u0431\u0435\u0440\u0430\u04b3\u043c\u0438\u0438 \u0442\u0430\u049b\u0434\u0438\u0440 \u043a\u0430\u0440\u0434.\n\u0425\u043e\u0441\u0442 \u0445\u0438\u043b\u0432\u0430\u0442\u0433\u043e\u04b3 \u0434\u0430\u0440 \u0432\u0430\u0439\u0440\u043e\u043d\u0430\u0435,\n\u0411\u0443\u0442\u043f\u0430\u0440\u0430\u0441\u0442\u0438\u044e \u0438\u0431\u043e\u0434\u0430\u0442\u0445\u043e\u043d\u0430\u0435.\n\u0425\u043e\u0441\u0442, \u043a\u0438 \u0434\u0438\u0433\u0430\u0440 \u043d\u0430\u0431\u0438\u043d\u0430\u0434 \u0440\u04ef\u0437\u0440\u043e,\n\u0427\u0435\u04b3\u0440\u0430\u0438 \u0431\u0430\u0434\u0445\u043e\u04b3\u0438 \u043e\u043b\u0430\u043c\u0441\u04ef\u0437\u0440\u043e.\n\u0425\u043e\u0441\u0442 \u043f\u04ef\u0448\u0430\u0434 \u0440\u04ef\u0439\u0440\u043e \u0430\u0437 \u041e\u0444\u0442\u043e\u0431,\n\u0427\u0443\u043d \u043c\u0430\u04b3\u0438 \u0430\u0444\u0442\u043e\u0434\u0430 \u0434\u0430\u0440 \u0437\u0435\u0440\u0438 \u0441\u0430\u04b3\u043e\u0431.\n\u041d\u0430\u0448\u043d\u0430\u0432\u0430\u0434 \u0431\u043e \u0433\u04ef\u0448 \u0444\u0430\u0440\u0451\u0434\u0438 \u043a\u0430\u0441\u0435,\n\u0492\u0438\u043d\u0433\u0430\u0441\u0438 \u0437\u0430\u043d\u0431\u04ef\u0440\u0443 \u043e\u0432\u043e\u0437\u0438 \u043a\u0430\u0441\u0435.\n\u0425\u043e\u0441\u0442, \u043a\u0438 \u043c\u0430\u04b3\u0444\u0443\u0437 \u0434\u043e\u0440\u0430\u0434 \u043d\u0430\u043d\u0433\u0440\u043e,\n\u0411\u0430\u0441\u0442\u0430 \u0434\u0430\u0440 \u0434\u0438\u043b \u0430\u0437 \u049b\u0430\u043d\u043e\u0430\u0442 \u0441\u0430\u043d\u0433\u0440\u043e.\n\u0420\u04ef \u043d\u0438\u04b3\u043e\u0434 \u0431\u0430\u0440 \u0428\u0438\u0432\u0430 \u0431\u043e \u0430\u04b7\u0437\u0443 \u043d\u0438\u0451\u0437,\n\u0411\u043e\u0448\u0430\u0434 \u043e\u043d \u0447\u0443\u043d \u0443\u0434 \u0434\u0430\u0440 \u0441\u04ef\u0437\u0443 \u0433\u0443\u0434\u043e\u0437.\n\u041c\u043e\u043d\u0434\u0430 \u0434\u0443\u0445\u0442\u0430\u0440 \u0434\u0430\u0441\u0442\u0440\u043e \u0431\u043e\u043b\u043e\u0438 \u0434\u0430\u0441\u0442,\n\u0414\u0430\u0440 \u0438\u0431\u043e\u0434\u0430\u0442\u0445\u043e\u043d\u0430 \u0447\u0430\u043d\u0434\u0438\u043d \u043c\u0430\u04b3 \u043d\u0438\u0448\u0430\u0441\u0442.\n\u0425\u0430\u043b\u049b\u0440\u043e \u043c\u0430\u0448\u04b3\u0443\u0440 \u043d\u0430\u049b\u043b\u0438 \u0442\u043e\u0437\u0430 \u0448\u0443\u0434,\n\u0427\u0443\u043d \u043c\u0443\u049b\u0430\u0434\u0434\u0430\u0441 \u0434\u0443\u0445\u0442\u0430\u0440\u0435 \u043e\u0432\u043e\u0437\u0430 \u0448\u0443\u0434.\n\u041a\u0430\u0440\u0434\u0430 \u0434\u0430\u0440 \u0431\u0430\u0440 \u043f\u04ef\u0441\u0442\u0438 \u0431\u0430\u0431\u0440\u0443 \u043f\u0430\u043b\u0430\u043d\u0433,\n\u0413\u043e\u04b3 \u0431\u0435\u0440\u0443\u043d \u0448\u0443\u0434 \u0431\u0430 \u0434\u0430\u0448\u0442\u0438 \u0441\u0430\u0431\u0437\u0440\u0430\u043d\u0433.\n\u0413\u043e\u04b3 \u043c\u0438\u0441\u043b\u0438 \u0441\u043e\u044f \u0434\u0430\u0440 \u0448\u0430\u0431\u04b3\u043e\u0438 \u0442\u043e\u0440,\n\u041c\u0443\u043b\u043a\u0440\u043e \u043c\u0435\u043a\u0430\u0440\u0434 \u043e\u043d \u0433\u0430\u0448\u0442\u0443\u0433\u0443\u0437\u043e\u0440.\n\u04b6\u0443\u0441\u0442\u0443\u04b7\u04ef \u043c\u0435\u043a\u0430\u0440\u0434 \u049b\u0443\u0442\u0438 \u043b\u043e\u044f\u043c\u0443\u0442,\n\u0422\u043e \u043a\u0430\u043c\u0435 \u043e\u0440\u043e\u043c \u0441\u043e\u0437\u0430\u0434 \u043d\u0430\u0444\u0441\u0438 \u0445\u0443\u0434.\n\u0410\u0437 \u0442\u0430\u043c\u043e\u0448\u043e \u0447\u0430\u0448\u043c \u043c\u0435\u043f\u04ef\u0448\u0438\u0434 \u043e\u043d,\n\u0427\u0443\u043d \u0434\u0438\u043b\u0438 \u0441\u0430\u04b3\u0440\u043e \u043d\u0430\u043c\u0435\u04b7\u04ef\u0448\u0438\u0434 \u043e\u043d.\n\u041b\u0435\u043a \u0434\u0443\u0437\u0434\u0438\u0434\u0430 \u0434\u0438\u043b\u0438 \u043e\u043d\u0440\u043e \u0431\u0430 \u0445\u0443\u0434,\n\u0417\u0438\u043d\u0430\u0442\u0438 \u041a\u0430\u0448\u043c\u0438\u0440 \u043c\u0430\u0444\u0442\u0443\u043d \u043c\u0435\u043d\u0430\u043c\u0443\u0434.\n\u0411\u043e\u0434 \u043c\u0435\u043e\u0432\u0430\u0440\u0434 \u0430\u0437 \xab\u0411\u043e\u0493\u0438 \u043d\u0430\u0441\u0438\u043c\xbb,\n\u0414\u0430\u0440 \u0441\u0430\u04b3\u0430\u0440\u0433\u043e\u04b3\u043e\u043d \u0434\u0438\u043c\u043e\u0493\u0430\u0448\u0440\u043e \u0448\u0430\u043c\u0438\u043c.\n\u0414\u0430\u0441\u0442\u0438 \u0440\u0430\u0441\u0441\u043e\u043c\u0438 \u0442\u0430\u0431\u0438\u0430\u0442 \u0434\u0438\u043b\u0440\u0430\u0431\u043e,\n\u0427\u0443\u043d \u0430\u0440\u04ef\u0441 \u043e\u0440\u043e\u0441\u0442\u0430 \u041a\u0430\u0448\u043c\u0438\u0440\u0440\u043e.\n\u041a\u04ef\u04b3\u0438 \u0431\u0430\u0440\u0444\u0438\u043d \u2013 \u043e\u0431\u0438 \u0448\u0438\u0440\u0438\u043d \u0434\u043e\u0440\u0430\u0434 \u043e\u043d,\n\u0427\u0430\u0448\u043c\u0430\u0432\u0443 \u0440\u04ef\u0434\u0438 \u0431\u0443\u043b\u04ef\u0440\u0438\u043d \u0434\u043e\u0440\u0430\u0434 \u043e\u043d.\n\u0410\u0431\u0440 \u0430\u0433\u0430\u0440 \u0430\u0437 \u043e\u0441\u043c\u043e\u043d \u0431\u043e\u0440\u043e\u043d \u0434\u0438\u04b3\u0430\u0434,\n\u0410\u0437 \u0437\u0430\u043c\u0438\u043d \u0433\u0443\u043b \u0448\u0430\u0434\u0434\u0430\u0438 \u043c\u0430\u0440\u04b7\u043e\u043d \u0434\u0438\u04b3\u0430\u0434.\n\u041e\u0441\u043c\u043e\u043d\u0430\u0448 \u0447\u0443\u043d \u0433\u0438\u043b\u0435\u043c\u0438 \u0440\u0430\u043d\u0433\u0430\u0435,\n\u0401 \u0431\u0430 \u043c\u0438\u0441\u043b\u0438 \u043b\u0430\u044a\u043b\u0438\u0438 \u043f\u0443\u0440\u0442\u0430\u043d\u0433\u0430\u0435.\n\u041f\u0430\u0441 \u0447\u04e3 \u0441\u043e\u043d \u0434\u0438\u043b\u0440\u043e \u043d\u0430\u0431\u0430\u043d\u0434\u0430\u0434 \u04b3\u0443\u0441\u043d\u0438 \u043e\u043d,\n\u0411\u043e \u04b3\u0430\u0437\u043e\u0440\u043e\u043d \u0448\u0430\u044a\u0448\u0430\u0430, \u0431\u0435 \u0440\u0435\u0441\u043c\u043e\u043d!\n\u041b\u0430\u044a\u043d\u0430\u0442 \u043e\u043d \u043a\u0430\u0441\u0440\u043e, \u043a\u0438 \u0441\u043e\u0437\u0430\u0434 \u0431\u043e \u0438\u0442\u043e\u0431,\n\u0418\u043d \u043b\u0430\u0442\u043e\u0444\u0430\u0442, \u0438\u043d \u0437\u0430\u0440\u043e\u0444\u0430\u0442\u0440\u043e \u0445\u0430\u0440\u043e\u0431!\n\u0414\u0443\u0445\u0442\u0430\u0440\u0438 \u04b3\u0438\u043d\u0434\u04e3 \u044f\u0440\u043e\u049b\u0438 \u04b7\u0430\u043d\u0433 \u0434\u0438\u0434,\n\u0412\u0430\u049b\u0442\u0438 \u0441\u0430\u0439\u0440\u0443 \u0433\u0430\u0448\u0442 \u0442\u04ef\u043f\u0443 \u0442\u0430\u043d\u043a \u0434\u0438\u0434.\n\u041b\u0430\u0448\u043a\u0430\u0440\u0438 \u0431\u0435\u0433\u043e\u043d\u0430 \u0434\u0430\u0440 \u043e\u043d \u04b7\u043e \u0448\u0443\u0434\u0430\u0441\u0442,\n\u0417\u0438\u043d\u0430\u0442\u0438 \u041a\u0430\u0448\u043c\u0438\u0440 \u0437\u0435\u0440\u0438 \u043f\u043e \u0448\u0443\u0434\u0430\u0441\u0442.\n\u0414\u0443\u0434\u0438 \u0442\u0430\u043d\u043a, \u0430\u0439\u0440\u043e\u043f\u043b\u0430\u043d, \u0434\u0443\u0434\u0438 \u043c\u0430\u0442\u043e\u0440,\n\u04b2\u0430\u043b\u049b\u0430 \u043c\u0435\u0437\u0430\u0434 \u0434\u0430\u0440 \u0444\u0430\u0437\u043e\u0438 \u0431\u0435\u0493\u0443\u0431\u043e\u0440.\n\u0414\u0443\u0445\u0442\u0430\u0440\u0438 \u04b3\u0438\u043d\u0434\u04e3 \u0431\u0430 \u0445\u0430\u0448\u043c \u043e\u043c\u0430\u0434, \u0431\u0430 \u0445\u0430\u0448\u043c,\n\u0411\u043e\u0437 \u0448\u0443\u0434 \u0447\u0443\u043d \u043c\u043e\u0448 \u043e\u043d\u0440\u043e \u04b3\u0430\u0440 \u0434\u0443 \u0447\u0430\u0448\u043c.\n\u0427\u0443\u043d \u043d\u0438\u0434\u043e, \u0447\u0443\u043d \u043e\u0433\u0430\u04b3\u04e3, \u04b3\u0430\u043c\u0447\u0443\u043d \u049b\u0430\u0441\u0430\u043c\n\u0418\u043d \u0441\u0443\u0440\u0443\u0434 \u043e\u043c\u0430\u0434 \u0431\u0430 \u0433\u04ef\u0448\u0430\u0448 \u0434\u0430\u043c \u0431\u0430 \u0434\u0430\u043c:\n\xab\u041b\u043e\u043b\u0430\u04b3\u043e \u0431\u0438\u0433\u0437\u043e\u0440, \u0434\u0430\u0440 \u041a\u0430\u0448\u043c\u0438\u0440\u0438 \u043c\u043e\n\u0414\u043e\u0438\u043c\u043e \u0431\u043e\u0448\u0430\u043d\u0434 \u0434\u0430\u0440 \u043d\u0430\u0448\u044a\u0443\u043d\u0430\u043c\u043e.\n\u041e\u0431\u04b3\u043e \u0431\u0438\u0433\u0437\u043e\u0440 \u04b7\u04ef\u0448\u0430\u043d\u0434\u0443 \u0434\u0430\u043c\u0430\u043d\u0434,\n\u0427\u0443\u043d \u0441\u0430\u0444\u0435\u0434\u04e3 \u0434\u0430\u0440 \u0443\u0444\u0443\u049b \u2013 \u0441\u0443\u0431\u04b3\u0438 \u0431\u0430\u043b\u0430\u043d\u0434.\n\u041c\u043e, \u0432\u0430\u043b\u0435 \u04b7\u043e\u043d\u0441\u0430\u0445\u0442 \u043c\u0430\u0440\u0434\u043e\u043d \u043c\u0435\u0440\u0430\u0441\u0435\u043c,\n\u041c\u0438\u0441\u043b\u0438 \u0441\u0430\u043d\u0433\u0438 \u043a\u04ef\u04b3\u0441\u043e\u0440\u043e\u043d \u043c\u0435\u0440\u0430\u0441\u0435\u043c.\n\u0422\u043e \u043a\u0438 \u0440\u04ef\u0437\u0438 \u0438\u043c\u0442\u0438\u04b3\u043e\u043d, \u0440\u04ef\u0437\u0438 \u04b7\u0438\u0434\u043e\u043b\n\u0425\u0430\u043c \u043d\u0430\u0441\u043e\u0437\u0430\u0434 \u049b\u043e\u043c\u0430\u0442\u0438 \u043c\u043e\u0440\u043e \u0448\u0430\u043c\u043e\u043b\xbb.\n\u0414\u0443\u0445\u0442\u0430\u0440\u0438 \u04b3\u0438\u043d\u0434\u04e3 \u0430\u0434\u043e\u043b\u0430\u0442\u0445\u043e\u04b3 \u0448\u0443\u0434,\n\u0410\u0437 \u0431\u0430\u0434\u0443 \u043d\u0435\u043a\u0438 \u04b7\u0430\u04b3\u043e\u043d \u043e\u0433\u043e\u04b3 \u0448\u0443\u0434.\n\u0411\u043e\u0437 \u0434\u0443\u043d\u0431\u043e\u043b\u0438 \u0440\u0430\u04b3\u0438 \u0434\u0438\u0433\u0430\u0440 \u0433\u0438\u0440\u0438\u0444\u0442,\n\u0420\u043e\u04b3\u0438 \u043e\u0434\u0430\u043c\u0433\u0430\u0440\u0434\u0438 \u0410\u043c\u0440\u0438\u0442\u0441\u0430\u0440 \u0433\u0438\u0440\u0438\u0444\u0442.\n\u0413\u0430\u0448\u0442 \u0434\u0430\u0440 \u0448\u0430\u04b3\u0440\u0443 \u0431\u0430 \u04b3\u0430\u0440 \u043a\u0430\u0441 \u0433\u04ef\u0448 \u043a\u0430\u0440\u0434,\n\u041b\u0430\u0431 \u0444\u0443\u0440\u04ef \u0431\u0430\u0441\u0442\u0443 \u043d\u0430\u0444\u0430\u0441 \u0445\u043e\u043c\u04ef\u0448 \u043a\u0430\u0440\u0434.\n\u0428\u0430\u04b3\u0440 \u0431\u0443\u0434, \u0430\u043c\u043c\u043e \u043f\u0443\u0440 \u0430\u0437 \u043e\u0432\u043e\u0437\u0438 \u0445\u0430\u043b\u049b,\n\u0410\u0437 \u0447\u0430\u043f\u0430\u043a\u04b3\u043e\u0438 \u0444\u0430\u043b\u0430\u043a\u0430\u043d\u0434\u043e\u0437\u0438 \u0445\u0430\u043b\u049b.\n\u0414\u0430\u0440 \u043c\u0438\u0451\u043d\u0438 \u043a\u04ef\u0447\u0430\u0432\u0443 \u0431\u043e\u0437\u043e\u0440\u04b3\u043e,\n\u0414\u0430\u0440 \u0434\u0430\u043c\u0438 \u0434\u0430\u0440, \u0434\u0430\u0440 \u0442\u0430\u0433\u0438 \u0434\u0435\u0432\u043e\u0440\u04b3\u043e.\n\u041e\u0434\u0430\u043c\u043e\u043d \u0434\u0430\u0440 \u043a\u043e\u0493\u0430\u0437 \u0438\u043c\u0437\u043e \u043c\u0435\u043a\u0443\u043d\u0430\u043d\u0434,\n\u0421\u0443\u043b\u04b3\u0440\u043e \u0442\u0430\u0448\u0432\u0438\u049b\u0443 \u0438\u043b\u049b\u043e \u043c\u0435\u043a\u0443\u043d\u0430\u043d\u0434.\n\xab\u0421\u0443\u043b\u04b3- \u043c\u0435\u0433\u0443\u0444\u0442\u0430\u043d\u0434, \u043a\u0438, - \u043e\u043c\u043e\u043b\u0438 \u043c\u043e\u0441\u0442,\n\u041d\u0430\u0432\u0431\u0430\u04b3\u043e\u0440\u0438 \u0447\u043e\u0440 \u0444\u0430\u0441\u043b\u0438 \u0441\u043e\u043b\u0438 \u043c\u043e\u0441\u0442.\n\u0421\u0443\u043b\u04b3 \u0438\u0441\u0442\u0438\u049b\u0431\u043e\u043b\u0438 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u043e\u043d \u0431\u0443\u0432\u0430\u0434,\n\u0425\u043e\u0442\u0438\u0440\u0438 \u04b7\u0430\u043c\u044a\u0438 \u043a\u04ef\u04b3\u0430\u043d\u0441\u043e\u043b\u043e\u043d \u0431\u0443\u0432\u0430\u0434.\n\u0421\u0443\u043b\u04b3 \u0431\u043e\u0448\u0430\u0434, \u0431\u0438\u0433\u0437\u0430\u0440\u0430\u0434 \u043d\u043e\u043d \u0431\u0435\u043c\u0430\u043b\u043e\u043b,\n\u0410\u0437 \u0433\u0443\u043b\u04ef\u0438 \u0445\u0430\u043b\u049b \u0434\u0430\u0440 \u04b3\u0430\u0440 \u0433\u0443\u043d\u0430 \u04b3\u043e\u043b.\n\u0410\u0434\u043b\u0440\u043e \u0431\u0430\u0440\u043f\u043e \u043a\u0443\u043d\u0430\u0434 \u043f\u0430\u0439\u043c\u043e\u043d\u0438 \u0441\u0443\u043b\u04b3,\n\u0411\u0430\u0445\u0442\u0440\u043e \u043f\u0430\u0440\u0432\u043e \u043a\u0443\u043d\u0430\u0434 \u0434\u0430\u0432\u0440\u043e\u043d\u0438 \u0441\u0443\u043b\u04b3\xbb.\n\u0414\u0443\u0445\u0442\u0430\u0440\u0438 \u04b3\u0438\u043d\u0434\u04e3 \u0431\u0430 \u0433\u0430\u043f\u04b3\u043e \u0433\u04ef\u0448 \u043a\u0430\u0440\u0434,\n\u041f\u0430\u0439\u043a\u0430\u0440\u0430\u0448 \u043b\u0430\u0440\u0437\u0438\u0434\u0443 \u0442\u043e\u0431\u0443 \u0442\u04ef\u0448 \u043a\u0430\u0440\u0434.\n\u041a\u04ef\u0447\u0430\u04b3\u043e\u0440\u043e \u0445\u04ef\u0440\u0434\u0430 \u043a\u0430\u0440\u0434 \u0430\u0437 \u0440\u0430\u0444\u0442\u0443\u043e,\n\u041c\u0435\u0448\u0443\u043d\u0438\u0434 \u0430\u0437 \u0445\u0430\u043b\u049b \u044f\u043a \u0433\u0443\u043d\u0430 \u043d\u0438\u0434\u043e.\n\u041c\u0435\u043d\u0430\u0432\u0438\u0441\u0430\u0434 \u043d\u043e\u043c\u0438 \u0445\u0443\u0434 \u0434\u0430\u0440 \u04b3\u0430\u0440 \u049b\u0430\u0434\u0430\u043c,\n\u04b2\u0430\u0440 \u044f\u043a\u0435 \u0431\u043e \u043d\u04ef\u0433\u0438 \u0430\u043d\u0433\u0443\u0448\u0442\u0443 \u049b\u0430\u043b\u0430\u043c.\n\u0422\u04ef\u0434\u0430\u0435\u0440\u043e \u043a\u0430\u043c-\u043a\u0430\u043c\u0430\u043a \u043d\u0430\u0437\u0434\u0438\u043a \u0448\u0443\u0434,\n\u0421\u0443\u043b\u04b3\u04b7\u04ef\u0440\u043e \u0430\u0437 \u043f\u0430\u0439\u0438 \u0442\u0430\u0431\u0440\u0438\u043a \u0448\u0443\u0434.\n\u0414\u0443\u0445\u0442\u0430\u0440\u0435, \u043a\u0438 \u0430\u0434\u043b\u0440\u043e \u0443\u043c\u043c\u0435\u0434 \u0434\u043e\u0448\u0442,\n\u0411\u043e \u049b\u0430\u043b\u0430\u043c \u0434\u0430\u0440 \u043a\u043e\u0493\u0430\u0437 \u0438\u043c\u0437\u043e\u0440\u043e \u0433\u0443\u0437\u043e\u0448\u0442.\n\u0414\u0443\u0445\u0442\u0430\u0440\u0438 \u04b3\u0438\u043d\u0434\u04e3 \u0430\u0434\u043e\u043b\u0430\u0442\u0445\u043e\u04b3 \u0448\u0443\u0434,\n\u041e\u043b\u0430\u043c \u0430\u0437 \u0442\u0430\u044a\u0440\u0438\u0445\u0438 \u043e\u043d \u043e\u0433\u043e\u04b3 \u0448\u0443\u0434.\n\u0410\u0437 \u0412\u0430\u0442\u0430\u043d, \u0430\u0437 \u0441\u0430\u0440\u0437\u0430\u043c\u0438\u043d\u0438 \u043c\u043e\u0434\u0430\u0440\u04e3,\n\u0420\u0430\u0444\u0442 \u0431\u0435\u0440\u0443\u043d, \u0434\u0438\u0434 \u043c\u0443\u043b\u043a\u0438 \u0434\u0438\u0433\u0430\u0440\u0435.\n\u0414\u0438\u0434 \u043a\u0438\u0448\u0432\u0430\u0440\u04b3\u043e\u0438 \u0433\u0443\u043d\u043e\u0433\u0443\u043d\u0438 \u0434\u0430\u04b3\u0440,\n\u0421\u0443\u043b\u04b3\u043f\u0430\u0440\u0432\u0430\u0440\u04b3\u043e\u0438 \u0440\u04ef\u0437\u0430\u0444\u0437\u0443\u043d\u0438 \u0434\u0430\u04b3\u0440.\n\u0414\u0430\u0440 \u0437\u0430\u0431\u043e\u043d, \u0434\u0430\u0440 \u0493\u043e\u044f, \u043c\u0430\u0437\u04b3\u0430\u0431 \u043c\u0443\u0445\u0442\u0430\u043b\u0438\u0444,\n\u0410\u0437 \u043f\u0430\u0439\u0438 \u0441\u0443\u043b\u04b3\u0430\u043d\u0434, \u0430\u043c\u043c\u043e \u04b3\u0430\u043c\u0440\u0430\u0434\u0438\u0444.\n\u0414\u0438\u0434 \u044f\u043a \u0440\u043e\u04b3\u0438 \u0441\u0430\u0444\u0435\u0434\u0438 \u0441\u0443\u043b\u04b3\u0440\u043e,\n\u049a\u0430\u043b\u044a\u0430\u0432\u0443 \u049b\u0443\u043b\u0444\u0443 \u043a\u0430\u043b\u0438\u0434\u0438 \u0441\u0443\u043b\u04b3\u0440\u043e.\n\u041a\u043e\u043d\u0433\u0440\u0435\u0441\u0441\u0438 \u0412\u0435\u043d\u0430 \u043e\u0493\u04ef\u0448\u0430\u0448 \u043d\u0430\u043c\u0443\u0434,\n\u0421\u0443\u043b\u04b3\u0440\u043e \u0447\u0443\u043d \u04b3\u0430\u043b\u049b\u0430 \u0431\u0430\u0440 \u0433\u04ef\u0448\u0430\u0448 \u043d\u0430\u043c\u0443\u0434.\n\u041c\u0438\u0441\u043b\u0438 \u044f\u043a \u0443\u043c\u043c\u0435\u0434\u0438 \u0434\u0435\u0440\u0438\u043d \u041c\u043e\u0441\u043a\u0432\u0430,\n\u041e\u0440\u0437\u0443\u0432\u0443 \u0445\u043e\u0431\u0438 \u0448\u0438\u0440\u0438\u043d \u041c\u043e\u0441\u043a\u0432\u0430.\n\u0422\u0430\u043a\u044f\u0433\u043e\u04b3\u0438 \u0441\u0443\u043b\u04b3\u04b7\u04ef\u0451\u043d \u041c\u043e\u0441\u043a\u0432\u0430,\n\u0418\u0442\u0442\u0438\u0444\u043e\u049b\u0438 \u0434\u04ef\u0441\u0442\u0434\u043e\u0440\u043e\u043d \u041c\u043e\u0441\u043a\u0432\u0430.\n\u0428\u0430\u04b3\u0440\u0438 \u0431\u0435\u043c\u043e\u043d\u0430\u043d\u0434\u0438 \u043f\u0443\u0440\u0448\u043e\u043d \u041c\u043e\u0441\u043a\u0432\u0430.\n\u04b6\u043e\u043d\u0438 \u0434\u0443\u043d\u0451, \u04b7\u043e\u043d\u0438 \u0438\u043d\u0441\u043e\u043d \u041c\u043e\u0441\u043a\u0432\u0430.\n\u041f\u043e\u0439\u0442\u0430\u0445\u0442\u0438 \u043c\u0443\u043b\u043a\u0438 \u0430\u044a\u0437\u0430\u043c \u041c\u043e\u0441\u043a\u0432\u0430,\n\u0414\u0430\u0440 \u0432\u0430\u0444\u043e\u0432\u0443 \u0430\u04b3\u0434 \u043c\u0430\u04b3\u043a\u0430\u043c \u041c\u043e\u0441\u043a\u0432\u0430.\n\u04b2\u0438\u043d\u0434\u0443\u0434\u0443\u0445\u0442\u0430\u0440\u0440\u043e \u0441\u0430\u043e\u0434\u0430\u0442\u043c\u0430\u043d\u0434 \u043a\u0430\u0440\u0434,\n\u041c\u0435\u04b3\u043c\u043e\u043d \u0431\u0438\u043d\u043c\u0443\u0434\u0430\u0432\u0443 \u0445\u0443\u0440\u0441\u0430\u043d\u0434 \u043a\u0430\u0440\u0434.\n\u0414\u0443\u0445\u0442\u0430\u0440\u0438 \u04b3\u0438\u043d\u0434\u04e3 \u0430\u0434\u043e\u043b\u0430\u0442\u0445\u043e\u04b3 \u0448\u0443\u0434,\n\u041e\u043b\u0430\u043c \u0430\u0437 \u0442\u0430\u044a\u0440\u0438\u0445\u0438 \u043e\u043d \u043e\u0433\u043e\u04b3 \u0448\u0443\u0434.")
B.acF=new A.a("aada288d-5560-47d4-aa16-b4fe8761ef27","10a9ad7d-fd0d-462f-8cb4-594a869f8229","\u041f\u0438\u0441\u0430\u0440, \u0440\u0430\u0432 \u049b\u0430\u0434\u0440\u0438 \u043c\u043e\u0434\u0430\u0440 \u0434\u043e\u043d, \u043a\u0438...","\u041f\u0438\u0441\u0430\u0440, \u0440\u0430\u0432 \u049b\u0430\u0434\u0440\u0438 \u043c\u043e\u0434\u0430\u0440 \u0434\u043e\u043d, \u043a\u0438 \u0434\u043e\u0438\u043c\n\u041a\u0430\u0448\u0430\u0434 \u0440\u0430\u043d\u04b7\u0438 \u043f\u0438\u0441\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0411\u0438\u0440\u0430\u0432, \u0431\u0435\u0448 \u0430\u0437 \u043f\u0430\u0434\u0430\u0440 \u0445\u043e\u04b3\u0430\u0448, \u043a\u0438 \u0445\u043e\u04b3\u0430\u0434\n\u0422\u0443\u0440\u043e \u0431\u0435\u0448 \u0430\u0437 \u043f\u0430\u0434\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0417\u0438 \u04b7\u043e\u043d \u043c\u0430\u04b3\u0431\u0443\u0431\u0442\u0430\u0440 \u0434\u043e\u0440\u0430\u0448, \u043a\u0438 \u0434\u043e\u0440\u0430\u0434\n\u0417\u0438 \u04b7\u043e\u043d \u043c\u0430\u04b3\u0431\u0443\u0431\u0442\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u041d\u0438\u0433\u0430\u04b3\u0434\u043e\u0440\u04e3 \u043a\u0443\u043d\u0430\u0434 \u043d\u0443\u04b3 \u043c\u043e\u04b3\u0443 \u043d\u0443\u04b3 \u0440\u04ef\u0437,\n\u0422\u0443\u0440\u043e, \u0447\u0443\u043d \u04b7\u043e\u043d \u0431\u0430 \u0431\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0410\u0437 \u0438\u043d \u043f\u0430\u04b3\u043b\u0443 \u0431\u0430 \u043e\u043d \u043f\u0430\u04b3\u043b\u0443 \u043d\u0430\u0493\u0430\u043b\u0442\u0430\u0434,\n\u0428\u0430\u0431 \u0430\u0437 \u0431\u0438\u043c\u0438 \u0445\u0430\u0442\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0411\u0430 \u0432\u0430\u049b\u0442\u0438 \u0437\u043e\u0434\u0430\u043d\u0438 \u0442\u0443 \u043c\u0430\u0440\u0433\u0438 \u0445\u0443\u0434\u0440\u043e\n\u0411\u0438\u0433\u0438\u0440\u0430\u0434 \u0434\u0430\u0440 \u043d\u0430\u0437\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0411\u0438\u0448\u04ef\u044f\u0434 \u043a\u0443\u04b3\u043d\u0430, \u043e\u0440\u043e\u044f\u0434 \u043d\u0430\u0432\u0430\u0442\u0440\u043e,\n\u0427\u0443 \u043a\u0430\u043c\u0442\u0430\u0440 \u043a\u043e\u0440\u0433\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0422\u0430\u043c\u0443\u0437\u0443 \u0434\u0430\u0439 \u0442\u0443\u0440\u043e \u0441\u043e\u0430\u0442 \u0431\u0430 \u0441\u043e\u0430\u0442\n\u041d\u0430\u043c\u043e\u044f\u0434 \u0445\u0443\u0448\u043a\u0443 \u0442\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0410\u0433\u0430\u0440 \u044f\u043a \u0430\u0442\u0441\u0430 \u043e\u044f\u0434 \u0430\u0437 \u0434\u0438\u043c\u043e\u0493\u0430\u0442\n\u041f\u0430\u0440\u0430\u0434 \u04b3\u0443\u0448\u0430\u0448 \u0437\u0438 \u0441\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0410\u0433\u0430\u0440 \u044f\u043a \u0441\u0443\u0440\u0444\u0430\u0435 \u0431\u0435\u04b7\u043e \u043d\u0430\u043c\u043e\u04e3\n\u0425\u04ef\u0440\u0430\u0434 \u0445\u0443\u043d\u0438 \u04b7\u0438\u0433\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0411\u0430\u0440\u043e\u0438 \u043e\u043d \u043a\u0438 \u0448\u0430\u0431 \u0440\u043e\u04b3\u0430\u0442 \u0431\u0438\u0445\u043e\u0431\u04e3\n\u041d\u0430\u0445\u043e\u0431\u0430\u0434 \u0442\u043e \u0441\u0430\u04b3\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0414\u0443 \u0441\u043e\u043b \u0430\u0437 \u0433\u0438\u0440\u044f\u0438 \u0440\u04ef\u0437\u0443 \u0448\u0430\u0431\u0438 \u0442\u0443\n\u041d\u0430\u0434\u043e\u0440\u0430\u0434 \u0445\u043e\u0431\u0443 \u0445\u04ef\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0427\u0443 \u0434\u0430\u043d\u0434\u043e\u043d \u043e\u0432\u0430\u0440\u04e3, \u0440\u0430\u043d\u04b7\u0443\u0440 \u0433\u0430\u0440\u0434\u04e3,\n\u041a\u0430\u0448\u0430\u0434 \u0440\u0430\u043d\u04b7\u0438 \u0434\u0438\u0433\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0421\u0438\u043f\u0430\u0441 \u0447\u0443\u043d \u043f\u043e \u0433\u0438\u0440\u0438\u0444\u0442\u04e3, \u0442\u043e \u043d\u0430\u044f\u0444\u0442\u04e3\n\u0425\u04ef\u0440\u0430\u0434 \u0493\u0430\u043c \u0431\u0435\u0448\u0442\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0422\u0443 \u0442\u043e \u044f\u043a \u043c\u0443\u0445\u0442\u0430\u0441\u0430\u0440 \u04b7\u043e\u043d\u0435 \u0431\u0438\u0433\u0438\u0440\u04e3\n\u041a\u0443\u043d\u0430\u0434 \u04b7\u043e\u043d \u043c\u0443\u0445\u0442\u0430\u0441\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0411\u0430 \u043c\u0430\u043a\u0442\u0430\u0431 \u0447\u0443\u043d \u0440\u0430\u0432\u04e3, \u0442\u043e \u0431\u043e\u0437\u0433\u0430\u0440\u0434\u04e3\n\u0411\u0443\u0432\u0430\u0434 \u0447\u0430\u0448\u043c\u0430\u0448 \u0431\u0430 \u0434\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0410\u0433\u0430\u0440 \u044f\u043a \u0440\u0443\u0431\u044a\u0438 \u0441\u043e\u0430\u0442 \u0434\u0435\u0440 \u043e\u04e3,\n\u0428\u0430\u0432\u0430\u0434 \u0430\u0437 \u0445\u0443\u0434 \u0431\u0430\u0434\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u041d\u0430\u0431\u0438\u043d\u0430\u0434 \u04b3\u0435\u04b7 \u043a\u0430\u0441 \u0437\u0430\u04b3\u043c\u0430\u0442 \u0431\u0430 \u0434\u0443\u043d\u0451\n\u0417\u0438 \u043c\u043e\u0434\u0430\u0440 \u0431\u0435\u0448\u0442\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.\n\u0422\u0430\u043c\u043e\u043c\u0438 \u04b3\u043e\u0441\u0438\u043b\u0430\u0448 \u0430\u0437 \u0443\u043c\u0440 \u0438\u043d \u0430\u0441\u0442,\n\u041a\u0438 \u0434\u043e\u0440\u0430\u0434 \u044f\u043a \u043f\u0438\u0441\u0430\u0440, \u0431\u0435\u0447\u043e\u0440\u0430 \u043c\u043e\u0434\u0430\u0440.")
B.abZ=new A.a("afff14cc-8867-487c-8905-b7c6d3b24f5f","10a9ad7d-fd0d-462f-8cb4-594a869f8229","\u0418\u0434\u0438 \u041d\u0430\u0432\u0440\u04ef\u0437 \u0430\u0432\u0432\u0430\u043b\u0438 \u0441\u043e\u043b \u0430\u0441\u0442,","\u0418\u0434\u0438 \u041d\u0430\u0432\u0440\u04ef\u0437 \u0430\u0432\u0432\u0430\u043b\u0438 \u0441\u043e\u043b \u0430\u0441\u0442,\n\u0420\u04ef\u0437\u0438 \u0430\u0439\u0448\u0443 \u043d\u0438\u0448\u043e\u0442\u0438 \u0430\u0442\u0444\u043e\u043b \u0430\u0441\u0442.\n\u04b2\u0430\u043c\u0430 \u043e\u043d \u0440\u04ef\u0437 \u0440\u0430\u0445\u0442\u0438 \u043d\u0430\u0432 \u043f\u04ef\u0448\u0430\u043d\u0434,\n\u0427\u043e\u044e \u0448\u0430\u0440\u0431\u0430\u0442 \u0431\u0430 \u0445\u0443\u0448\u0434\u0438\u043b\u04e3 \u043d\u04ef\u0448\u0430\u043d\u0434.\n\u041f\u0438\u0441\u0430\u0440\u0438 \u0445\u0443\u0431 \u0440\u04ef\u0437\u0438 \u0438\u0434 \u0430\u043d\u0434\u0430\u0440\n\u0420\u0430\u0432\u0430\u0434 \u0430\u0432\u0432\u0430\u043b \u0431\u0430 \u0445\u0438\u0434\u043c\u0430\u0442\u0438 \u043c\u043e\u0434\u0430\u0440.\n\u0414\u0430\u0441\u0442 \u0434\u0430\u0440 \u0433\u0430\u0440\u0434\u0430\u043d\u0430\u0448 \u043a\u0443\u043d\u0430\u0434 \u0447\u0443\u043d \u0442\u0430\u0432\u049b,\n\u0421\u0430\u0440\u0443 \u0434\u0430\u0441\u0442\u0430\u0448 \u0431\u0438\u0431\u04ef\u0441\u0430\u0434 \u0430\u0437 \u0441\u0430\u0440\u0438 \u0448\u0430\u0432\u049b.\n\u0413\u04ef\u044f\u043d\u0434: \xab\u0418\u043d \u0438\u0434\u0438 \u043d\u0430\u0432 \u043c\u0443\u0431\u043e\u0440\u0430\u043a \u0431\u043e\u0434,\n\u0421\u0430\u0434 \u0447\u0443\u043d\u0438\u043d \u0421\u043e\u043b\u0438 \u043d\u0430\u0432 \u0431\u0443\u0431\u0438\u043d\u04e3 \u0448\u043e\u0434! \xbb.\n\u0411\u0430\u044a\u0434 \u043e\u044f\u0434 \u0431\u0430 \u0434\u0430\u0441\u0442\u0431\u04ef\u0441\u0438 \u043f\u0430\u0434\u0430\u0440,\n\u0411\u04ef\u0441\u0430 \u0431\u0430\u0445\u0448\u0430\u0434 \u043f\u0430\u0434\u0430\u0440 \u0431\u0430 \u0440\u04ef\u0439\u0438 \u043f\u0438\u0441\u0430\u0440.\n\u041f\u0438\u0441\u0430\u0440\u0438 \u0431\u0430\u0434 \u0447\u0443 \u0440\u04ef\u0437\u0438 \u0438\u0434 \u0448\u0430\u0432\u0430\u0434,\n\u041c\u0430\u0432\u049b\u0435\u0438 \u0434\u0438\u0434\u0443 \u0431\u043e\u0437\u0434\u0438\u0434 \u0448\u0430\u0432\u0430\u0434.\n\u041d\u0430 \u043f\u0430\u0434\u0430\u0440 \u0434\u04ef\u0441\u0442 \u0434\u043e\u0440\u0430\u0434\u0430\u0448 \u043d\u0430 \u0430\u043c\u04ef,\n\u041d\u0430 \u043a\u0430\u0441\u0435 \u0438\u0434\u04e3 \u043e\u0432\u0430\u0440\u0430\u0434 \u0431\u0430\u0440\u0438 \u04ef.\n\u0418\u0434\u04e3 \u043e\u043d \u0440\u04ef\u0437 \u04b3\u0430\u049b\u049b\u0438 \u043e\u043d \u043f\u0438\u0441\u0430\u0440 \u0430\u0441\u0442,\n\u041a\u0438 \u043d\u0430\u04b7\u0438\u0431\u0443 \u0448\u0430\u0440\u0438\u0444\u0443 \u0431\u043e\u04b3\u0443\u043d\u0430\u0440 \u0430\u0441\u0442.")
