B.aaz=new A.a("4f6bd1c8-0060-41e1-b2c4-f28f9a111c40","a6dd1c54-753d-4a52-8e5b-5365b7908aa3","\u041c\u0430\u0448\u0430\u0432 \u0434\u0430\u0440 \u04b7\u0430\u0432\u043e\u043d\u04e3 \u0445\u0430\u0440\u0438\u0434\u043e\u0440\u0438 \u0433\u0430\u043d\u04b7...","\u041c\u0430\u0448\u0430\u0432 \u0434\u0430\u0440 \u04b7\u0430\u0432\u043e\u043d\u04e3 \u0445\u0430\u0440\u0438\u0434\u043e\u0440\u0438 \u0433\u0430\u043d\u04b7,\n\u0411\u0430 \u0431\u0435\u0440\u0430\u043d\u04b7 \u043a\u0430\u0441 \u04b3\u0435\u04b7 \u043c\u0430\u043d\u043c\u043e\u0439 \u0440\u0430\u043d\u04b7.")
B.ahY=new A.a("e77fe3da-d2ba-4c1f-b4ca-073ba250b5b1","a6dd1c54-753d-4a52-8e5b-5365b7908aa3","\u042f\u043a\u0435 \u043c\u0430\u0440\u0434 \u0431\u0443\u0434 \u0430\u043d\u0434\u0430\u0440 \u043e\u043d \u0440\u04ef\u0437\u0433\u043e\u0440","\u042f\u043a\u0435 \u043c\u0430\u0440\u0434 \u0431\u0443\u0434 \u0430\u043d\u0434\u0430\u0440 \u043e\u043d \u0440\u04ef\u0437\u0433\u043e\u0440\n\u0417\u0438 \u0434\u0430\u0448\u0442\u0438 \u0441\u0430\u0432\u043e\u0440\u043e\u043d\u0438 \u043d\u0430\u0439\u0437\u0430\u0433\u0443\u0437\u043e\u0440,\n\u0413\u0430\u0440\u043e\u043d\u043c\u043e\u044f \u04b3\u0430\u043c \u0448\u043e\u04b3\u0443 \u04b3\u0430\u043c \u043d\u0435\u043a\u043c\u0430\u0440\u0434,\n\u0417\u0438 \u0442\u0430\u0440\u0441\u0438 \u04b7\u0430\u04b3\u043e\u043d\u0434\u043e\u0440 \u0431\u043e \u0431\u043e\u0434\u0438 \u0441\u0430\u0440\u0434,\n\u041a\u0438 \u041c\u0430\u0440\u0434\u043e\u0441 \u043d\u043e\u043c\u0438 \u0433\u0430\u0440\u043e\u043d\u043c\u043e\u044f \u0431\u0443\u0434,\n\u0411\u0430 \u0434\u043e\u0434\u0443 \u0434\u0438\u04b3\u0438\u0448 \u0431\u0430\u0440\u0442\u0430\u0440\u0438\u043d\u043f\u043e\u044f \u0431\u0443\u0434...\n\u041f\u0438\u0441\u0430\u0440 \u0431\u0443\u0434 \u043c\u0430\u0440-\u043e\u043d \u043f\u043e\u043a\u0434\u0438\u043d\u0440\u043e \u044f\u043a\u0435,\n\u041a-\u0430\u0448 \u0430\u0437 \u043c\u0435\u04b3\u0440 \u0431\u0430\u04b3\u0440\u0430 \u043d\u0430\u0431\u0443\u0434 \u0430\u043d\u0434\u0430\u043a\u0435.\n\u04b6\u0430\u04b3\u043e\u043d\u04b7\u04ef\u0439\u0440\u043e \u043d\u043e\u043c \u0417\u0430\u04b3\u04b3\u043e\u043a \u0431\u0443\u0434,\n\u0414\u0430\u043b\u0435\u0440\u0443 \u0441\u0430\u0431\u0443\u043a\u0441\u043e\u0440\u0443 \u043d\u043e\u043f\u043e\u043a \u0431\u0443\u0434...\n\n\u0427\u0443\u043d\u043e\u043d \u0431\u0443\u0434, \u043a-\u0418\u0431\u043b\u0438\u0441 \u0440\u04ef\u0437\u0435 \u043f\u0430\u0433\u043e\u04b3\n\u0411\u0438\u0451\u043c\u0430\u0434 \u0431\u0430 \u0441\u043e\u043d\u0438 \u044f\u043a\u0435 \u043d\u0435\u043a\u0445\u043e\u04b3,\n\u0414\u0438\u043b\u0438 \u043c\u0435\u04b3\u0442\u0430\u0440 \u0430\u0437 \u0440\u043e\u04b3\u0438 \u043d\u0435\u043a\u04e3 \u0431\u0438\u0431\u0443\u0440\u0434,\n\u04b6\u0430\u0432\u043e\u043d \u0433\u04ef\u0448 \u0440\u0430\u0444\u0442\u043e\u0440\u0438 \u04ef\u0440\u043e \u0441\u0443\u043f\u0443\u0440\u0434.\n\u04b2\u0430\u043c\u043e\u043d\u043e \u0445\u0443\u0448 \u043e\u043c\u0430\u0434-\u0448 \u0433\u0443\u0444\u0442\u043e\u0440\u0438 \u04ef\u0439,\n\u041d\u0430\u0431\u0443\u0434 \u043e\u0433\u0430\u04b3 \u0430\u0437 \u0437\u0438\u0448\u0442 \u043a\u0438\u0440\u0434\u043e\u0440\u0438 \u04ef\u0439...\n\u0427\u0443 \u0418\u0431\u043b\u0438\u0441 \u0434\u043e\u043d\u0438\u0441\u0442, \u043a-\u04ef \u0434\u0438\u043b \u0431\u0438\u0434\u043e\u0434,\n\u0411\u0430\u0440 \u0430\u0444\u0441\u043e\u043d\u0430\u0430\u0448 \u0433\u0430\u0448\u0442 \u043d\u0430\u04b3\u043c\u043e\u0440 \u0448\u043e\u0434.\n\u0424\u0430\u0440\u043e\u0432\u043e\u043d \u0441\u0443\u0445\u0430\u043d \u0433\u0443\u0444\u0442 \u0437\u0435\u0431\u043e\u0432\u0443 \u043d\u0430\u0493\u0437,\n\u04b6\u0430\u0432\u043e\u043d\u0440\u043e \u0437\u0438 \u0434\u043e\u043d\u0438\u0448 \u0442\u0438\u04b3\u04e3 \u0431\u0443\u0434 \u043c\u0430\u0493\u0437.\n\u04b2\u0430\u043c\u0435\u0433\u0443\u0444\u0442: \xab\u0414\u043e\u0440\u0430\u043c \u0441\u0443\u0445\u0430\u043d\u04b3\u043e \u0431\u0430\u0441\u0435,\n\u041a\u0438 \u043e\u043d\u0440\u043e \u04b7\u0443\u0437 \u0430\u0437 \u043c\u0430\u043d \u043d\u0430\u0434\u043e\u043d\u0430\u0434 \u043a\u0430\u0441\u0435\xbb.\n\u04b6\u0430\u0432\u043e\u043d \u0433\u0443\u0444\u0442: \xab\u0411\u0430\u0440\u0433\u04ef\u0432\u0443 \u0447\u0430\u043d\u0434\u0438\u043d \u043c\u0430\u043f\u043e\u0439,\n\u0411\u0438\u0451\u043c\u04ef\u0437 \u043c\u043e\u0440\u043e \u0442\u0443, \u0430\u0439 \u043d\u0435\u043a\u0440\u043e\u0439\xbb.\n\u0411\u0430\u0434-\u04ef \u0433\u0443\u0444\u0442: \xab\u041f\u0430\u0439\u043c\u043e\u043d-\u0442 \u0445\u043e\u04b3\u0430\u043c \u043d\u0430\u0445\u0443\u0441\u0442,\n\u041f\u0430\u0441 \u043e\u043d \u0433\u0430\u04b3 \u0441\u0443\u0445\u0430\u043d \u0431\u0430\u0440\u043a\u0443\u0448\u043e\u044f\u043c \u0434\u0443\u0440\u0443\u0441\u0442\xbb.\n\u04b6\u0430\u0432\u043e\u043d \u043d\u0435\u043a\u0434\u0438\u043b \u0431\u0443\u0434, \u043f\u0430\u0439\u043c\u043e\u043d-\u0448 \u043a\u0430\u0440\u0434,\n\u0427\u0443\u043d\u043e\u043d \u043a-\u04ef \u0431\u0438\u0444\u0430\u0440\u043c\u0443\u0434, \u0441\u0430\u0432\u0433\u0430\u043d\u0434 \u0445(\u0432)\u0430\u0440\u0434,\n\u041a\u0438 \xab\u0420\u043e\u0437\u0438 \u0442\u0443 \u0431\u043e \u043a\u0430\u0441 \u043d\u0430\u0433\u04ef\u044f\u043c \u0437\u0438 \u0431\u0443\u043d,\n\u0417\u0438 \u0442\u0443 \u0431\u0438\u0448\u043d\u0430\u0432\u0430\u043c, \u04b3\u0430\u0440 \u0447\u04e3 \u0433\u04ef\u04e3 \u0441\u0443\u0445\u0443\u043d\xbb.\n\u0411\u0430\u0434-\u04ef \u0433\u0443\u0444\u0442: \xab\u04b6\u0443\u0437 \u0442\u0443 \u043a\u0430\u0441\u0435 \u0434\u0430\u0440 \u0441\u0430\u0440\u043e\u0439\n\u0427\u0430\u0440\u043e \u0431\u043e\u044f\u0434, \u0430\u0439 \u043d\u043e\u043c\u0432\u0430\u0440, \u043a\u0430\u0434\u0445\u0443\u0434\u043e\u0439?..\n\u0411\u0438\u0433\u0438\u0440 \u0438\u043d \u0441\u0430\u0440\u0438 \u043c\u043e\u044f \u0434\u0430\u0440\u0433\u043e\u04b3\u0438 \u04ef\u0439,\n\u0422\u0443\u0440\u043e \u0437\u0435\u0431\u0430\u0434 \u0430\u043d\u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d \u04b7\u043e\u04b3\u0438 \u04ef\u0439.\n\u0411\u0430\u0440 \u0438\u043d \u0433\u0443\u0444\u0442\u0430\u0438 \u043c\u0430\u043d \u0447\u0443 \u0434\u043e\u0440\u04e3 \u0432\u0430\u0444\u043e,\n\u04b6\u0430\u04b3\u043e\u043d\u0440\u043e \u0442\u0443 \u0431\u043e\u0448\u04e3 \u044f\u043a\u0435 \u043f\u043e\u0434\u0448\u043e\xbb.\n\u0427\u0443 \u0417\u0430\u04b3\u04b3\u043e\u043a \u0431\u0438\u0448\u043d\u0438\u0434, \u0430\u043d\u0434\u0435\u0448\u0430 \u043a\u0430\u0440\u0434,\n\u0417\u0438 \u0445\u0443\u043d\u0438 \u043f\u0430\u0434\u0430\u0440 \u0448\u0443\u0434 \u0434\u0438\u043b\u0430\u0448 \u043f\u0443\u0440 \u0437\u0438 \u0434\u0430\u0440\u0434.\n\u0411\u0430 \u0418\u0431\u043b\u0438\u0441 \u0433\u0443\u0444\u0442: \xab\u0418\u043d \u0441\u0430\u0437\u043e\u0432\u043e\u0440 \u043d\u0435\u0441\u0442,\n\u0414\u0438\u0433\u0430\u0440 \u0433\u04ef\u0439, \u043a-\u0438\u043d \u0430\u0437 \u0434\u0430\u0440\u0438 \u043a\u043e\u0440 \u043d\u0435\u0441\u0442\xbb...\n\n\u0411\u0430\u0434-\u04ef \u0433\u0443\u0444\u0442: \xab\u041c\u0430\u043d \u0447\u043e\u0440\u0430 \u0441\u043e\u0437\u0430\u043c \u0442\u0443\u0440\u043e,\n\u0411\u0430 \u0445\u0443\u0440\u0448\u0435\u0434 \u0441\u0430\u0440 \u0431\u0430\u0440\u0444\u0430\u0440\u043e\u0437\u0430\u043c \u0442\u0443\u0440\u043e.\n\u0422\u0443 \u0434\u0430\u0440 \u043a\u043e\u0440 \u0445\u043e\u043c\u04ef\u0448 \u043c\u0435\u0431\u043e\u0448\u0443 \u0431\u0430\u0441,\n\u041d\u0430\u0431\u043e\u044f\u0434 \u043c\u0430\u0440\u043e \u0451\u0440\u04e3 \u0430\u0437 \u04b3\u0435\u0447 \u043a\u0430\u0441\xbb.\n\u041c\u0430\u0440 \u043e\u043d \u043f\u043e\u0434\u0448\u043e\u0440\u043e - \u0434\u0430\u0440 \u0430\u043d\u0434\u0430\u0440 \u0441\u0430\u0440\u043e\u0439\n\u042f\u043a\u0435 \u0431\u04ef\u0441\u0442\u043e\u043d \u0431\u0443\u0434, \u0431\u0430\u0441 \u0434\u0438\u043b\u043a\u0443\u0448\u043e\u0439.\n\u0413\u0430\u0440\u043e\u043d\u043c\u043e\u044f \u0448\u0430\u0431\u0433\u0438\u0440 \u0431\u0430\u0440\u0445\u043e\u0441\u0442\u04e3,\n\u0417\u0438 \u0431\u0430\u04b3\u0440\u0438 \u043f\u0430\u0440\u0430\u0441\u0442\u0438\u0448 \u0431\u0438\u0451\u0440\u043e\u0441\u0442\u04e3.\n\u0411\u0430\u0440 \u043e\u043d \u0440\u043e\u0439\u0438 \u0432\u043e\u0436\u0443\u043d\u0430 \u0434\u0435\u0432\u0438 \u043d\u0430\u0436\u0430\u043d\u0434\n\u042f\u043a\u0435 \u0436\u0430\u0440\u0444 \u0447\u043e\u04b3\u0435 \u0431\u0430 \u0440\u0430\u04b3-\u0431\u0430\u0440 \u0431\u0438\u043a\u0430\u043d\u0434.\n\u041f\u0430\u0441 \u0418\u0431\u043b\u0438\u0441\u0438 \u0432\u043e\u0436\u0443\u043d\u0430 \u0438\u043d \u0436\u0430\u0440\u0444 \u0447\u043e\u04b3\n\u0411\u0430 \u0445\u043e\u0448\u043e\u043a \u043f\u04ef\u0448\u0438\u0434\u0443 \u0431\u0438\u0441\u043f\u0430\u0440\u0434 \u0440\u043e\u04b3.\n\u0428\u0430\u0431 \u043e\u043c\u0430\u0434, \u0441\u0443\u0438 \u0431\u043e\u0493 \u0431\u0438\u043d\u04b3\u043e\u0434 \u0440\u04ef\u0439\n\u0421\u0430\u0440\u0438 \u0442\u043e\u0437\u0438\u0451\u043d, \u043c\u0435\u04b3\u0442\u0430\u0440\u0438 \u043d\u043e\u043c\u04b7\u04ef\u0439.\n\u0427\u0443 \u043e\u043c\u0430\u0434 \u0431\u0430 \u043d\u0430\u0437\u0434\u0438\u043a\u0438 \u043e\u043d \u0436\u0430\u0440\u0444 \u0447\u043e\u04b3,\n\u042f\u043a\u043e\u044f\u043a \u043d\u0438\u0433\u0443\u043d \u0448\u0443\u0434 \u0441\u0430\u0440\u0438 \u0431\u0430\u0445\u0442\u0438 \u0448\u043e\u04b3...\n\u0424\u0443\u0440\u0443\u043c\u043e\u044f \u0417\u0430\u04b3\u04b3\u043e\u043a\u0438 \u0431\u0435\u0434\u043e\u0434\u0433\u0430\u0440\n\u0411\u0430\u0434-\u0438\u043d \u0447\u043e\u0440\u0430 \u0431\u0438\u0433\u0440\u0438\u0444\u0442 \u04b7\u043e\u04b3\u0438 \u043f\u0430\u0434\u0430\u0440.\n\u0427\u0443 \u0418\u0431\u043b\u0438\u0441 \u043f\u0430\u0439\u0432\u0430\u0441\u0442\u0430 \u0434\u0438\u0434\u04e3 \u0441\u0443\u0445\u0443\u043d,\n\u042f\u043a\u0435 \u0431\u0430\u043d\u0434\u0438 \u0434\u0438\u0433\u0430\u0440 \u043d\u0430\u0432 \u0430\u0444\u043a\u0430\u043d\u0434 \u0431\u0443\u043d...\n\u04b6\u0430\u0432\u043e\u043d\u0435 \u0431\u0430\u0440\u043e\u0440\u043e\u0441\u0442 \u0430\u0437 \u0445\u0435\u0448\u0442\u0430\u043d,\n\u0421\u0443\u0445\u0430\u043d\u0433\u04ef\u044e \u0431\u0438\u043d\u043e\u0434\u0438\u043b\u0443 \u043f\u043e\u043a\u0442\u0430\u043d...\n\u0411\u0430\u0434-\u04ef \u0433\u0443\u0444\u0442: \xab\u0413\u0430\u0440 \u0448\u043e\u04b3\u0440\u043e \u0434\u0430\u0440\u0445(\u0432)\u0430\u0440\u0430\u043c,\n\u042f\u043a\u0435 \u043d\u043e\u043c\u0432\u0430\u0440 \u043f\u043e\u043a \u0445\u043e\u043b\u0438\u0433\u0430\u0440\u0430\u043c.\n\u0427\u0443 \u0431\u0438\u0448\u043d\u0438\u0434 \u0417\u0430\u04b3\u04b3\u043e\u043a, \u0431\u0438\u043d\u0432\u043e\u0445\u0442\u0430\u0448,\n\u0417\u0438 \u0431\u0430\u04b3\u0440\u0438 \u0445\u0443\u0440\u0438\u0448 \u04b7\u043e\u0439\u0433\u0430\u04b3 \u0441\u043e\u0445\u0442\u0430\u0448.\n\u041a\u0430\u043b\u0438\u0434\u0438 \u0445\u0443\u0440\u0438\u0448\u0445\u043e\u043d\u0430\u0438 \u043f\u043e\u0434\u0448\u043e\n\u0411\u0430\u0434-\u04ef \u0434\u043e\u0434 \u0434\u0430\u0441\u0442\u0443\u0440\u0438 \u0444\u0430\u0440\u043c\u043e\u043d\u0440\u0430\u0432\u043e.\n\u0417\u0438 \u04b3\u0430\u0440 \u0433\u0443\u043d\u0430 \u0430\u0437 \u043c\u0443\u0440\u0493\u0443 \u0430\u0437 \u0447\u043e\u0440\u043f\u043e\u0439\n\u0425\u0443\u0440\u0438\u0448 \u043a\u0430\u0440\u0434\u0430 \u043e\u0432\u0430\u0440\u0434 \u044f\u043a-\u044f\u043a \u0431\u0430 \u04b7\u043e\u0439...\n\n\u0411\u0438\u0445\u0443\u0440\u0434\u0443 \u0431\u0430\u0440 \u04ef \u043e\u0444\u0430\u0440\u0438\u043d \u043a\u0430\u0440\u0434 \u0441\u0430\u0445\u0442,\n\u041c\u0430\u0437\u0430 \u0451\u0444\u0442 \u0437-\u043e\u043d \u0445\u0443\u0440\u0434\u0430\u043d\u0430\u0448 \u043d\u0435\u043a\u0431\u0430\u0445\u0442...\n\u0411\u0430 \u0440\u04ef\u0437\u0438 \u0447\u0430\u04b3\u043e\u0440\u0443\u043c \u0447\u0443 \u0431\u0438\u043d\u04b3\u043e\u0434 \u0445\u043e\u043d,\n\u0425\u0443\u0440\u0438\u0448 \u0441\u043e\u0445\u0442 \u0430\u0437 \u043f\u0443\u0448\u0442\u0438 \u0433\u043e\u0432\u0438 \u04b7\u0430\u0432\u043e\u043d...\n\u0427\u0443 \u0417\u0430\u04b3\u04b3\u043e\u043a \u0434\u0430\u0441\u0442 \u0430\u043d\u0434\u0430\u0440\u043e\u0432\u0430\u0440\u0434\u0443 \u0445(\u0432)\u0430\u0440\u0434,\n\u0428\u0438\u0433\u0438\u0444\u0442 \u043e\u043c\u0430\u0434\u0430\u0448 \u0437-\u043e\u043d \u04b3\u0443\u0448\u0438\u0432\u043e\u0440 \u043c\u0430\u0440\u0434.\n\u0411\u0430\u0434-\u04ef \u0433\u0443\u0444\u0442: \xab\u0411\u0438\u043d\u0433\u0430\u0440, \u043a\u0438 \u0442\u043e \u043e\u0440\u0437\u0443\u0439,\n\u0427\u04e3 \u0445\u043e\u04b3\u04e3, \u0431\u0438\u0445\u043e\u04b3, \u0430\u0437 \u043c\u0430\u043d, \u0430\u0439 \u043d\u0435\u043a\u0445\u04ef\u0439!\n\u0425\u0443\u0440\u0438\u0448\u0433\u0430\u0440 \u0431\u0430\u0434-\u04ef \u0433\u0443\u0444\u0442, \u043a - \xab\u0410\u0439 \u043f\u043e\u0434\u0448\u043e,\n\u04b2\u0430\u043c\u0435\u0448\u0430 \u0431\u0438\u0437\u04e3 \u0448\u043e\u0434\u0443 \u0444\u0430\u0440\u043c\u043e\u043d\u0440\u0430\u0432\u043e!\n\u041c\u0430\u0440\u043e \u0434\u0438\u043b \u0441\u0430\u0440\u043e\u0441\u0430\u0440 \u043f\u0443\u0440 \u0430\u0437 \u043c\u0435\u04b3\u0440\u0438 \u0442\u0443\u0441\u0442,\n\u04b2\u0430\u043c\u0430 \u0442\u04ef\u0448\u0430\u0438 \u04b7\u043e\u043d\u0430\u043c \u0430\u0437 \u0447\u0435\u04b3\u0440\u0438 \u0442\u0443\u0441\u0442.\n\u042f\u043a\u0435 \u04b3\u043e\u04b7\u0430\u0442 \u0430\u0441\u0442\u0430\u043c \u0437\u0438 \u043d\u0430\u0437\u0434\u0438\u043a\u0438 \u0448\u043e\u04b3\n\u0412-\u0430\u0433\u0430\u0440\u0447\u0438 \u043c\u0430\u0440\u043e \u043d\u0435\u0441\u0442 \u0438\u043d \u043f\u043e\u0439\u0433\u043e\u04b3,\n\u041a\u0438 \u0444\u0430\u0440\u043c\u043e\u043d \u0434\u0438\u04b3\u0430\u0434 \u0448\u043e\u04b3, \u0442\u043e \u043a\u0438\u0442\u0444\u0438 \u04ef\u0439\n\u0411\u0438\u0431\u04ef\u0441\u0430\u043c, \u0431\u0438\u043c\u043e\u043b\u0430\u043c \u0431\u0430\u0440 \u04ef \u0447\u0430\u0448\u043c\u0443 \u0440\u04ef\u0439\xbb.\n\u0427\u0443 \u0417\u0430\u04b3\u04b3\u043e\u043a \u0431\u0438\u0448\u043d\u0438\u0434 \u0433\u0443\u0444\u0442\u043e\u0440\u0438 \u04ef\u0439,\n\u041d\u0438\u04b3\u043e\u043d\u04e3 \u043d\u0430\u0434\u043e\u043d\u0438\u0441\u0442 \u0431\u043e\u0437\u043e\u0440\u0438 \u04ef\u0439.\n\u0411\u0430\u0434-\u04ef \u0433\u0443\u0444\u0442: - \xab\u0414\u043e\u0434\u0430\u043c \u043c\u0430\u043d \u0438\u043d \u043a\u043e\u043c\u0438 \u0442\u0443,\n\u0411\u0430\u043b\u0430\u043d\u0434\u04e3 \u0431\u0438\u0433\u0438\u0440\u0430\u0434 \u043c\u0430\u0433\u0430\u0440 \u043d\u043e\u043c\u0438 \u0442\u0443\xbb.\n\u0411\u0438\u0444\u0430\u0440\u043c\u0443\u0434, \u0442\u043e \u0434\u0435\u0432 \u0447\u0443\u043d \u04b7\u0443\u0444\u0442\u0438 \u04ef\n\u04b2\u0430\u043c\u0435 \u0431\u04ef\u0441\u0430\u0435 \u0434\u043e\u0434 \u0431\u0430\u0440 \u043a\u0438\u0444\u0442\u0438 \u04ef.\n\u0427\u0443 \u0431\u04ef\u0441\u0438\u0434\u0443 \u0448\u0443\u0434 \u0434\u0430\u0440 \u0437\u0430\u043c\u043e\u043d \u043d\u043e\u043f\u0430\u0434\u0438\u0434,\n\u041a\u0430\u0441 \u0430\u043d\u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d \u0438\u043d \u0448\u0438\u0433\u0438\u0444\u0442\u04e3 \u043d\u0430\u0434\u0438\u0434.\n\u0414\u0443 \u043c\u043e\u0440\u0438 \u0441\u0438\u0451\u04b3 \u0430\u0437 \u0434\u0443 \u043a\u0438\u0442\u0444\u0430\u0448 \u0431\u0438\u0440\u0443\u0441\u0442,\n\u0492\u0430\u043c\u04e3 \u0433\u0430\u0448\u0442\u0443 \u0430\u0437 \u04b3\u0430\u0440 \u0441\u0443\u0435 \u0447\u043e\u0440\u0430 \u04b7\u0443\u0441\u0442.\n\u0421\u0430\u0440\u0430\u043d\u04b7\u043e\u043c \u0431\u0438\u0431\u0440\u0438\u0434 \u04b3\u0430\u0440 \u0434\u0443 \u0437\u0438 \u043a\u0438\u0444\u0442,\n\u0421\u0430\u0437\u0430\u0434, \u0433\u0430\u0440 \u0431\u0438\u043c\u043e\u043d\u04e3 \u0430\u0437 \u0438\u043d \u0434\u0430\u0440 \u0448\u0438\u0433\u0438\u0444\u0442.\n\u0427\u0443 \u0448\u043e\u0445\u0438 \u0434\u0430\u0440\u0430\u0445\u0442 \u043e\u043d \u0434\u0443 \u043c\u043e\u0440\u0438 \u0441\u0438\u0451\u04b3\n\u0411\u0430\u0440\u043e\u043c\u0430\u0434 \u0434\u0438\u0433\u0430\u0440\u0431\u043e\u0440\u0430 \u0430\u0437 \u043a\u0438\u0442\u0444\u0438 \u0448\u043e\u04b3.\n\u041f\u0438\u0437\u0438\u0448\u043a\u043e\u043d\u0438 \u0444\u0430\u0440\u0437\u043e\u043d\u0430 \u0433\u0438\u0440\u0434 \u043e\u043c\u0430\u0434\u0430\u043d\u0434,\n\n\u04b2\u0430\u043c\u0430 \u044f\u043a \u0431\u0430 \u044f\u043a \u0434\u043e\u0441\u0442\u043e\u043d\u04b3\u043e \u0437\u0430\u0434\u0430\u043d\u0434.\n\u0417\u0438 \u04b3\u0430\u0440 \u0433\u0443\u043d\u0430 \u043d\u0430\u0439\u0440\u0430\u043d\u0433\u04b3\u043e \u0441\u043e\u0445\u0442\u0430\u043d\u0434,\n\u041c\u0430\u0440\u043e\u043d \u0434\u0430\u0440\u0434\u0440\u043e \u0447\u043e\u0440\u0430 \u043d\u0430\u0448\u043d\u043e\u0445\u0442\u0430\u043d\u0434.\n\u0411\u0430 \u0441\u043e\u043d\u0438 \u043f\u0438\u0437\u0438\u0448\u043a\u0435 \u043f\u0430\u0441 \u0418\u0431\u043b\u0438\u0441 \u0442\u0430\u0444\u0442\n\u0411\u0430 \u0444\u0430\u0440\u0437\u043e\u043d\u0430\u0433\u04e3 \u043d\u0430\u0437\u0434\u0438 \u0417\u0430\u04b3\u04b3\u043e\u043a \u0440\u0430\u0444\u0442.\n\u0411\u0430\u0434-\u04ef \u0433\u0443\u0444\u0442, \u043a- \xab\u0418\u043d \u0431\u0443\u0434\u0430\u043d\u04e3 \u043a\u043e\u0440 \u0431\u0443\u0434,\n\u0411\u0438\u043c\u043e\u043d, \u0442\u043e \u0447\u04e3 \u043c\u043e\u043d\u0430\u0434, \u043d\u0430\u0431\u043e\u044f\u0434 \u0434\u0443\u0440\u0443\u0434.\n\u0425\u0443\u0440\u0438\u0448 \u0441\u043e\u0437\u0443 \u043e\u0440\u043e\u043c\u0438\u044f\u0448 \u0434\u0435\u04b3, \u0431\u0430 \u0445(\u0432)\u0430\u0440\u0434,\n\u041d\u0430\u0448\u043e\u044f\u0434 \u04b7\u0443\u0437 \u0438\u043d \u0447\u043e\u0440\u0430\u0435 \u043d\u0438\u0437 \u043a\u0430\u0440\u0434.\n\u0411\u0430 \u04b7\u0443\u0437 \u043c\u0430\u0493\u0437\u0438 \u043c\u0430\u0440\u0434\u0443\u043c \u043c\u0430\u0434\u0435\u04b3\u0448\u043e\u043d \u0445(\u0432)\u0430\u0440\u0438\u0448,\n\u041c\u0430\u0433\u0430\u0440 \u0445\u0443\u0434 \u0431\u0438\u043c\u0438\u0440\u0430\u043d\u0434 \u0430\u0437 \u0438\u043d \u043f\u0430\u0440\u0432\u0430\u0440\u0438\u0448\xbb.\n\u041d\u0438\u0433\u0430\u0440 \u043d\u0430\u0440\u0440\u0430\u0434\u0435\u0432 \u0430\u043d\u0434\u0430\u0440 \u0438\u043d \u04b7\u0443\u0441\u0442\u0443\u04b7\u04ef,\n\u0427\u04e3 \u04b7\u0443\u0441\u0442\u0443 \u0447\u04e3 \u0434\u0438\u0434 \u0430\u043d\u0434\u0430\u0440 \u0438\u043d \u0433\u0443\u0444\u0442\u0443\u0433\u04ef.\n\u041c\u0430\u0433\u0430\u0440 \u0442\u043e \u044f\u043a\u0435 \u0447\u043e\u0440\u0430 \u0441\u043e\u0437\u0430\u0434 \u043d\u0438\u04b3\u043e\u043d,\n\u041a\u0438 \u043f\u0430\u0440\u0434\u0430\u0445\u0442\u0430 \u043c\u043e\u043d\u0430\u0434 \u0437\u0438 \u043c\u0430\u0440\u0434\u0443\u043c \u04b7\u0430\u04b3\u043e\u043d...\n\u0427\u0443 \u0417\u0430\u04b3\u04b3\u043e\u043a \u0431\u0430\u0440 \u0442\u0430\u0445\u0442 \u0448\u0443\u0434 \u0448\u0430\u04b3\u0440\u0451\u0440,\n\u0411\u0430\u0440 \u04ef \u0441\u043e\u043b\u0438\u0451\u043d \u0430\u043d\u04b7\u0443\u043c\u0430\u043d \u0448\u0443\u0434 \u04b3\u0430\u0437\u043e\u0440.\n\u04b2\u0443\u043d\u0430\u0440 \u0445\u043e\u0440 \u0448\u0443\u0434, \u04b7\u043e\u0434\u0443\u04e3 \u0430\u0440\u04b7\u043c\u0430\u043d\u0434,\n\u041d\u0438\u04b3\u043e\u043d \u0440\u043e\u0441\u0442\u04e3, \u043e\u0448\u043a\u043e\u0440\u043e \u0433\u0430\u0437\u0430\u043d\u0434.\n\u0428\u0443\u0434\u0430 \u0431\u0430\u0440 \u0431\u0430\u0434\u04e3 \u0434\u0430\u0441\u0442\u0438 \u0434\u0435\u0432\u043e\u043d \u0434\u0430\u0440\u043e\u0437,\n\u0417\u0438 \u043d\u0435\u043a\u04e3 \u043d\u0430\u0431\u0443\u0434\u04e3 \u0441\u0443\u0445\u0430\u043d \u04b7\u0443\u0437 \u0431\u0430 \u0440\u043e\u0437...\n\u041d\u0430\u0434\u043e\u043d\u0438\u0441\u0442 \u0445\u0443\u0434 \u04b7\u0443\u0437 \u0431\u0430\u0434 \u043e\u043c\u04ef\u0445\u0442\u0430\u043d,\n\u04b6\u0443\u0437 \u0430\u0437 \u043a\u0443\u0448\u0442\u0430\u043d\u0443 \u0493\u043e\u0440\u0430\u0442\u0443 \u0441\u04ef\u0445\u0442\u0430\u043d.\n\u0427\u0443\u043d\u043e\u043d \u0431\u0443\u0434, \u043a\u0438 \u04b3\u0430\u0440 \u0448\u0430\u0431 \u0434\u0443 \u043c\u0430\u0440\u0434\u0438 \u04b7\u0430\u0432\u043e\u043d\n\u0427\u0438 \u043a\u0435\u04b3\u0442\u0430\u0440, \u0447\u0438 \u0430\u0437 \u0442\u0443\u0445\u043c\u0430\u0438 \u043f\u0430\u04b3\u043b\u0430\u0432\u043e\u043d,\n\u0425\u0443\u0440\u0438\u0448\u0433\u0430\u0440 \u0431\u0438\u0431\u0443\u0440\u0434\u04e3 \u0430\u0437 \u0430\u0439\u0432\u043e\u043d\u0438 \u0448\u043e\u04b3\n\u0412-\u0430\u0437 \u04ef \u0441\u043e\u0445\u0442\u04e3 \u0440\u043e\u04b3\u0438 \u0434\u0430\u0440\u043c\u043e\u043d\u0438 \u0448\u043e\u04b3.\n\u0411\u0438\u043a\u0443\u0448\u0442\u0438\u044e \u043c\u0430\u0493\u0437\u0430\u0448 \u0431\u0443\u0440\u0443\u043d \u043e\u0445\u0442\u04e3,\n\u041c\u0430\u0440\u043e\u043d \u0430\u0436\u0434\u0430\u04b3\u043e\u0440\u043e \u0445\u0443\u0440\u0438\u0448 \u0441\u043e\u0445\u0442\u04e3.\n\n\u0427\u0443\u043d\u043e\u043d \u0431\u0443\u0434, \u043a\u0438 \u044f\u043a \u0440\u04ef\u0437 \u0431\u0430\u0440 \u0442\u0430\u0445\u0442\u0438 \u043e\u04b7\n\u041d\u0438\u04b3\u043e\u0434\u0430 \u0431\u0430 \u0441\u0430\u0440-\u0431\u0430\u0440 \u0437\u0438 \u043f\u0438\u0440\u04ef\u0437\u0430 \u0442\u043e\u04b7,\n\u0417\u0438 \u04b3\u0430\u0440 \u043a\u0438\u0448\u0432\u0430\u0440\u0435 \u043c\u0435\u04b3\u0442\u0430\u0440\u043e\u043d\u0440\u043e \u0431\u0438\u0445\u043e\u0441\u0442,\n\u041a\u0438 \u0434\u0430\u0440 \u043f\u043e\u0434\u0448\u043e\u04b3\u04e3 \u043a\u0443\u043d\u0430\u0434 \u043f\u0443\u0448\u0442 \u0440\u043e\u0441\u0442.\n\u0410\u0437 \u043e\u043d \u043f\u0430\u0441 \u0447\u0443\u043d\u0438\u043d \u0433\u0443\u0444\u0442 \u0431\u043e \u043c\u04ef\u0431\u0430\u0434\u043e\u043d\n\u041a\u0438 \xab\u0410\u0439 \u043f\u0443\u0440\u04b3\u0443\u043d\u0430\u0440, \u043d\u043e\u043c\u0432\u0430\u0440 \u0431\u0438\u0445\u0440\u0430\u0434\u043e\u043d!\n\u042f\u043a\u0435 \u043c\u0430\u04b3\u0437\u0430\u0440 \u0430\u043a\u043d\u0443\u043d \u0431\u0438\u0431\u043e\u044f\u0434 \u043d\u0430\u0431\u0438\u0448\u0442,\n\u041a\u0438 \u04b7\u0443\u0437 \u0442\u0443\u0445\u043c\u0438 \u043d\u0435\u043a\u04e3 \u0441\u0438\u043f\u0430\u04b3\u0431\u0430\u0434 \u043d\u0430\u043a\u0438\u0448\u0442\xbb.\n\u0417\u0438 \u0431\u0438\u043c\u0438 \u0441\u0438\u043f\u0430\u04b3\u0431\u0430\u0434 \u04b3\u0430\u043c\u0430 \u0440\u043e\u0441\u0442\u043e\u043d\n\u0411\u0430\u0434-\u043e\u043d \u043a\u043e\u0440 \u0433\u0430\u0448\u0442\u0430\u043d\u0434 \u04b3\u0430\u043c\u0434\u043e\u0441\u0442\u043e\u043d\xbb.\n\u0414\u0430\u0440 \u043e\u043d \u043c\u0430\u04b3\u0437\u0430\u0440\u0438 \u0430\u0436\u0434\u0430\u04b3\u043e \u043d\u043e\u0433\u0443\u0437\u0438\u0440\n\u0413\u0443\u0432\u043e\u04b3\u04e3 \u043d\u0430\u0432\u0438\u0448\u0442\u0430\u043d\u0434 \u0431\u0430\u0440\u043d\u043e\u0432\u0443 \u043f\u0438\u0440...\n\u0421\u0438\u0442\u0430\u043c\u0434\u0438\u0434\u0430\u0440\u043e \u043f\u0435\u0448\u0438 \u04ef \u0445\u043e\u043d\u0434\u0430\u043d\u0434,\n\u0411\u0430\u0440\u0438 \u043d\u043e\u043c\u0434\u043e\u0440\u043e\u043d-\u0448 \u0431\u0438\u043d\u0448\u043e\u043d\u0434\u0430\u043d\u0434.\n\u0411\u0430\u0434-\u04ef \u0433\u0443\u0444\u0442 \u043c\u0435\u04b3\u0442\u0430\u0440 \u0431\u0430 \u0440\u04ef\u0438 \u0434\u0438\u0436\u0430\u043c,\n\u041a\u0438 \xab\u0411\u0430\u0440\u0433\u04ef\u0439, \u0442\u043e \u0430\u0437 \u043a\u04e3 \u0434\u0438\u0434\u04e3 \u0441\u0438\u0442\u0430\u043c?\xbb\n\u0425\u0443\u0440\u04ef\u0448\u0438\u0434\u0443 \u0437\u0430\u0434 \u0434\u0430\u0441\u0442 \u0431\u0430\u0440 \u0441\u0430\u0440 \u0437\u0438 \u0448\u043e\u04b3,\n\u041a\u0438 \xab\u0428\u043e\u04b3\u043e, \u043c\u0430\u043d\u0430\u043c \u041a\u043e\u0432\u0430\u0438 \u0434\u043e\u0434\u0445\u043e\u04b3!\n\u0411\u0438\u0434\u0435\u04b3 \u0434\u043e\u0434\u0438 \u043c\u0430\u043d, \u043e\u043c\u0430\u0434\u0430\u0441\u0442\u0430\u043c \u0434\u0430\u0432\u043e\u043d,\n\u04b2\u0430\u043c\u0435\u043d\u043e\u043b\u0430\u043c \u0430\u0437 \u0442\u0443 \u0431\u0430 \u0440\u0430\u043d\u04b7\u0438 \u0440\u0430\u0432\u043e\u043d.\n\u0417\u0438 \u0442\u0443 \u0431\u0430\u0440 \u043c\u0430\u043d \u043e\u043c\u0430\u0434 \u0441\u0438\u0442\u0430\u043c \u0431\u0435\u0448\u0442\u0430\u0440,\n\u0417\u0430\u043d\u04e3 \u04b3\u0430\u0440 \u0437\u0430\u043c\u043e\u043d \u0431\u0430\u0440 \u0434\u0438\u043b\u0430\u043c \u043d\u0435\u0448\u0442\u0430\u0440.\n\u0421\u0438\u0442\u0430\u043c \u0433\u0430\u0440 \u043d\u0430\u0434\u043e\u0440\u04e3 \u0442\u0443 \u0431\u0430\u0440 \u043c\u0430\u043d \u0440\u0430\u0432\u043e,\n\u0411\u0430 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0438 \u043c\u0430\u043d \u0434\u0430\u0441\u0442 \u0431\u0443\u0440\u0434\u0430\u043d \u0447\u0430\u0440\u043e?\n\u041c\u0430\u0440\u043e \u0431\u0443\u0434 \u04b3\u0430\u0436\u0434\u0430\u04b3 \u043f\u0438\u0441\u0430\u0440 \u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d,\n\u0410\u0437 \u044d\u0448\u043e\u043d \u044f\u043a\u0435 \u043c\u043e\u043d\u0434\u0430\u0430\u0441\u0442 \u0438\u043d \u0437\u0430\u043c\u043e\u043d.\n\u0411\u0438\u0431\u0430\u0445\u0448\u043e\u0432\u0443 \u0431\u0430\u0440 \u043c\u0430\u043d \u044f\u043a\u0435 \u0434\u0430\u0440\u043d\u0438\u0433\u0430\u0440,\n\u041a\u0438 \u0441\u04ef\u0437\u043e\u043d \u0448\u0430\u0432\u0430\u0434 \u04b3\u0430\u0440 \u0437\u0430\u043c\u043e\u043d\u0430\u043c \u04b7\u0438\u0433\u0430\u0440.\n\u0428\u0430\u04b3\u043e, \u043c\u0430\u043d \u0447\u04e3 \u043a\u0430\u0440\u0434\u0430\u043c, \u044f\u043a\u0435 \u0431\u043e\u0437\u0433\u04ef\u0439\n\n\u0412-\u0430\u0433\u0430\u0440 \u0431\u0435\u0433\u0443\u043d\u043e\u04b3\u0430\u043c, \u0431\u0430\u04b3\u043e\u043d\u0430 \u043c\u0430\u04b7\u04ef\u0439.\n\u0411\u0430 \u04b3\u043e\u043b\u0438 \u043c\u0430\u043d, \u0430\u0439 \u0442\u043e\u04b7\u0432\u0430\u0440, \u0434\u0430\u0440\u043d\u0438\u0433\u0430\u0440,\n\u041c\u0430\u044f\u0444\u0437\u043e\u0439 \u0431\u0430\u0440 \u0445\u0435\u0448\u0442\u0430\u043d \u0434\u0430\u0440\u0434\u0438 \u0441\u0430\u0440...\n\u04b6\u0430\u0432\u043e\u043d\u04e3 \u043d\u0430\u043c\u043e\u043d\u0434\u0430\u0441\u0442\u0443 \u0444\u0430\u0440\u0437\u0430\u043d\u0434 \u043d\u0435\u0441\u0442,\n\u0411\u0430 \u0433\u0435\u0442\u04e3 \u0447\u0443 \u0444\u0430\u0440\u0437\u0430\u043d\u0434 \u043f\u0430\u0439\u0432\u0430\u043d\u0434 \u043d\u0435\u0441\u0442...\n\u042f\u043a\u0435 \u0431\u0435\u0437\u0438\u0451\u043d \u043c\u0430\u0440\u0434\u0438 \u043e\u04b3\u0430\u043d\u0433\u0430\u0440\u0430\u043c,\n\u0417\u0438 \u0448\u043e\u04b3 \u043e\u0442\u0430\u0448 \u043e\u044f\u0434 \u04b3\u0430\u043c\u0435 \u0431\u0430\u0440 \u0441\u0430\u0440\u0430\u043c\xbb.\n\u0421\u0438\u043f\u0430\u04b3\u0431\u0430\u0434 \u0431\u0430 \u0433\u0443\u0444\u0442\u043e\u0440\u0438 \u04ef \u0431\u0438\u043d\u0433\u0430\u0440\u0438\u0434,\n\u0428\u0438\u0433\u0438\u0444\u0442 \u043e\u043c\u0430\u0434\u0430\u0448, \u043a-\u043e\u043d \u0441\u0443\u0445\u0430\u043d\u04b3\u043e \u0448\u0443\u043d\u0438\u0434.\n\u0411\u0430\u0434-\u04ef \u0431\u043e\u0437\u0434\u043e\u0434\u0430\u043d\u0434 \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0438 \u04ef\u0439,\n\u0411\u0430 \u0445\u0443\u0431\u04e3 \u0431\u0438\u04b7\u0443\u0441\u0442\u0430\u043d\u0434 \u043f\u0430\u0439\u0432\u0430\u043d\u0434\u0438 \u04ef\u0439.\n\u0411\u0438\u0444\u0430\u0440\u043c\u0443\u0434 \u043f\u0430\u0441 \u041a\u043e\u0432\u0430\u0440\u043e \u043f\u043e\u0434\u0448\u043e\u04b3,\n\u041a\u0438 \u0431\u043e\u0448\u0430\u0434 \u0431\u0430\u0434-\u043e\u043d \u043c\u0430\u04b3\u0437\u0430\u0440 \u04ef\u0440\u043e \u0433\u0443\u0432\u043e\u04b3.\n\u0427\u0443 \u0431\u0430\u0440\u0445\u043e\u043d\u0434 \u041a\u043e\u0432\u0430 \u04b3\u0430\u043c\u0430 \u043c\u0430\u04b3\u0437\u0430\u0440\u0430\u0448,\n\u0421\u0430\u0431\u0443\u043a \u0441\u04ef\u0438 \u043f\u0438\u0440\u043e\u043d\u0438 \u043e\u043d \u043a\u0438\u0448\u0432\u0430\u0440\u0430\u0448\n\u0425\u0443\u0440\u04ef\u0448\u0438\u0434, \u043a- \xab\u0410\u0439 \u043f\u043e\u0439\u043c\u0430\u0440\u0434\u043e\u043d\u0438 \u0434\u0435\u0432,\n\u0411\u0443\u0440\u0438\u0434\u0430 \u0434\u0438\u043b \u0430\u0437 \u0442\u0430\u0440\u0441\u0438 \u043a\u0430\u0439\u04b3\u043e\u043d\u0445\u0438\u0434\u0435\u0432,\n\u041d\u0430\u0431\u043e\u0448\u0430\u0434 \u0431\u0430\u0434-\u0438\u043d \u043c\u0430\u04b3\u0437\u0430\u0440-\u0430\u043d\u0434\u0430\u0440 \u0433\u0443\u0432\u043e\u04b3,\n\u041d\u0430 \u04b3\u0430\u0440\u0433\u0438\u0437 \u0431\u0430\u0440\u0430\u043d\u0434\u0435\u0448\u0430\u043c \u0430\u0437 \u043f\u043e\u0434\u0448\u043e\u04b3\xbb.\n\u0425\u0443\u0440\u04ef\u0448\u0438\u0434\u0443 \u0431\u0430\u0440\u04b7\u0430\u0441\u0442 \u043b\u0430\u0440\u0437\u043e\u043d \u0437\u0438 \u04b7\u043e\u0439,\n\u0411\u0438\u0434\u0430\u0440\u0440\u0438\u0434\u0443 \u0431\u0438\u0441\u043f\u0430\u0440\u0434 \u043c\u0430\u04b3\u0437\u0430\u0440 \u0431\u0430 \u043f\u043e\u0439.\n\u0413\u0430\u0440\u043e\u043d\u043c\u043e\u044f \u0444\u0430\u0440\u0437\u0430\u043d\u0434\u0438 \u04ef \u043f\u0435\u0448\u0438 \u04ef\u0439,\n\u0410\u0437 \u0430\u0439\u0432\u043e\u043d \u0431\u0443\u0440\u0443\u043d \u0448\u0443\u0434 \u0445\u0443\u0440\u04ef\u0448\u043e\u043d \u0431\u0430 \u043a\u04ef\u0439...\n\u0427\u0443 \u041a\u043e\u0432\u0430 \u0431\u0443\u0440\u0443\u043d \u043e\u043c\u0430\u0434 \u0430\u0437 \u043f\u0435\u0448\u0438 \u0448\u043e\u04b3,\n\u0411\u0430\u0440 \u04ef \u0430\u043d\u04b7\u0443\u043c\u0430\u043d \u0433\u0430\u0448\u0442 \u0431\u043e\u0437\u043e\u0440\u0433\u043e\u04b3.\n\u04b2\u0430\u043c\u0435 \u0431\u0430\u0440\u0445\u0443\u0440\u04ef\u0448\u0438\u0434\u0443 \u0444\u0430\u0440\u0451\u0434 \u0445\u043e\u043d\u0434,\n\u04b6\u0430\u04b3\u043e\u043d\u0440\u043e \u0441\u0430\u0440\u043e\u0441\u0430\u0440 \u0441\u0443\u0438 \u0434\u043e\u0434 \u0445\u043e\u043d\u0434.\n\u0410\u0437 \u043e\u043d \u0447\u0430\u0440\u043c, \u043a-\u043e\u04b3\u0430\u043d\u0433\u0430\u0440\u043e\u043d \u043f\u0443\u0448\u0442\u0438 \u043f\u043e\u0439\n\u0411\u0438\u043f\u04ef\u0448\u0430\u043d\u0434 \u04b3\u0430\u043d\u0433\u043e\u043c\u0438 \u0437\u0430\u0445\u043c\u0438 \u0434\u0430\u0440\u043e\u0439,\n\u04b2\u0430\u043c\u043e\u043d \u041a\u043e\u0432\u0430 \u043e\u043d \u0431\u0430\u0440 \u0441\u0430\u0440\u0438 \u043d\u0430\u0439\u0437\u0430 \u043a\u0430\u0440\u0434,\n\u04b2\u0430\u043c\u043e\u043d \u0433\u0430\u04b3 \u0437\u0438 \u0431\u043e\u0437\u043e\u0440 \u0431\u0430\u0440\u0445\u043e\u0441\u0442 \u0433\u0430\u0440\u0434...\n\u04b2\u0430\u043c\u0435\u0440\u0430\u0444\u0442 \u043f\u0435\u0448-\u0430\u043d\u0434\u0430\u0440 \u043e\u043d \u043c\u0430\u0440\u0434\u0438 \u0433\u0443\u0440\u0434,\n\u0421\u0438\u043f\u043e\u04b3\u0435 \u0431\u0430\u0440 \u04ef \u0430\u043d\u04b7\u0443\u043c\u0430\u043d \u0448\u0443\u0434, \u043d\u0430 \u0445\u0443\u0440\u0434..\n\n\u0411\u0430 \u04b3\u0430\u0440 \u0431\u043e\u043c\u0443 \u0434\u0430\u0440 \u043c\u0430\u0440\u0434\u0443\u043c\u0438 \u0448\u0430\u04b3\u0440 \u0431\u0443\u0434,\n\u041a\u0430\u0441\u0435, \u043a-\u0430\u0448 \u0437\u0438 \u04b7\u0430\u043d\u0433\u043e\u0432\u0430\u0440\u04e3 \u0431\u0430\u04b3\u0440 \u0431\u0443\u0434...\n\u0417\u0438 \u0434\u0435\u0432\u043e\u0440\u04b3\u043e \u0445\u0438\u0448\u0442\u0443 \u0430\u0437 \u0431\u043e\u043c \u0441\u0430\u043d\u0433,\n\u0411\u0430 \u043a\u04ef\u0439-\u0430\u043d\u0434\u0430\u0440\u0443\u043d \u0442\u0435\u0493\u0443 \u0442\u0438\u0440\u0438 \u0445\u0430\u0434\u0430\u043d\u0433\n\u0411\u0438\u0431\u043e\u0440\u0438\u0434 \u0447\u0443\u043d \u0436\u043e\u043b\u0430 \u0437-\u0430\u0431\u0440\u0438 \u0441\u0438\u0451\u04b3,\n\u041a\u0430\u0441\u0435\u0440\u043e \u043d\u0430\u0431\u0443\u0434 \u0431\u0430\u0440 \u0437\u0430\u043c\u0438\u043d \u04b7\u043e\u0439\u0433\u043e\u04b3.\n\u0421\u0438\u043f\u043e\u04b3\u0438\u044e \u0448\u0430\u04b3\u0440\u04e3 \u0431\u0430 \u043a\u0438\u0440\u0434\u043e\u0440\u0438 \u043a\u04ef\u04b3\n\u0421\u0430\u0440\u043e\u0441\u0430\u0440 \u0431\u0430 \u04b7\u0430\u043d\u0433-\u0430\u043d\u0434\u0430\u0440\u0443\u043d \u04b3\u0430\u043c\u0433\u0443\u0440\u04ef\u04b3.\n\u0410\u0437 \u043e\u043d \u0448\u0430\u04b3\u0440\u0438 \u0440\u0430\u0432\u0448\u0430\u043d \u044f\u043a\u0435 \u0442\u0438\u0440\u0430 \u0433\u0430\u0440\u0434\n\u0411\u0430\u0440\u043e\u043c\u0430\u0434, \u043a\u0438 \u0445\u0443\u0440\u0448\u0435\u0434 \u0448\u0443\u0434 \u043b\u043e\u04b7\u0432\u0430\u0440\u0434.\n\u0411\u0438\u0431\u0443\u0440\u0434\u0430\u043d\u0434 \u0417\u0430\u04b3\u04b3\u043e\u043a\u0440\u043e \u0431\u0430\u0441\u0442\u0430 \u0445\u043e\u0440,\n\u0411\u0430 \u043f\u0443\u0448\u0442\u0438 \u04b3\u0430\u044e\u043d\u0435 \u0431\u0430\u0440\u0430\u0444\u043a\u0430\u043d\u0434\u0430 \u0437\u043e\u0440...\n\u0411\u0438\u0451\u0432\u0430\u0440\u0434 \u0417\u0430\u04b3\u04b3\u043e\u043a\u0440\u043e \u0447\u0443\u043d \u043d\u0430\u0432\u0430\u043d\u0434,\n\u0411\u0430 \u043a\u04ef\u04b3\u0438 \u0414\u0430\u043c\u043e\u0432\u0430\u043d\u0434 \u043a\u0430\u0440\u0434\u0430\u0448 \u0431\u0430 \u0431\u0430\u043d\u0434.\n\u0424\u0443\u0440\u0443 \u0431\u0430\u0441\u0442 \u0434\u0430\u0441\u0442\u0430\u0448 \u0431\u0430\u0434-\u043e\u043d \u043a\u04ef\u04b3 \u0431\u043e\u0437,\n\u0411\u0430\u0434-\u043e\u043d, \u0442\u043e \u0431\u0438\u043c\u043e\u043d\u0430\u0434 \u0431\u0430 \u0441\u0430\u0445\u0442\u04e3 \u0434\u0430\u0440\u043e\u0437.\n\u0411\u0438\u043c\u043e\u043d\u0434 \u04ef \u0431\u0430\u0440 \u0438\u043d \u0433\u0443\u043d\u0430 \u043e\u0432\u0435\u0445\u0442\u0430\n\u0412-\u0430\u0437 \u04ef \u0445\u0443\u043d\u0438 \u0434\u0438\u043b \u0431\u0430\u0440 \u0437\u0430\u043c\u0438\u043d \u0440\u0435\u0445\u0442\u0430.\n\u0411\u0438\u0451, \u0442\u043e \u04b7\u0430\u04b3\u043e\u043d\u0440\u043e \u0431\u0430 \u0431\u0430\u0434 \u043d\u0430\u0441\u043f\u0430\u0440\u0435\u043c,\n\u0411\u0430 \u043a\u04ef\u0448\u0438\u0448 \u04b3\u0430\u043c\u0430 \u0434\u0430\u0441\u0442\u0438 \u043d\u0435\u043a\u04e3 \u0431\u0430\u0440\u0435\u043c.\n\u041d\u0430\u0431\u043e\u0448\u0430\u0434 \u04b3\u0430\u043c\u0435 \u043d\u0435\u043a\u0443 \u0431\u0430\u0434 \u043f\u043e\u0439\u0434\u043e\u0440,\n\u04b2\u0430\u043c\u043e\u043d \u0431\u0435\u04b3, \u043a\u0438 \u043d\u0435\u043a\u04e3 \u0431\u0443\u0432\u0430\u0434 \u0451\u0434\u0433\u043e\u0440.")
B.adY=new A.a("eb5fcee6-90ca-49d9-abe6-f02381f1beaa","3ec91317-fcfe-4960-9ca0-fd87f3e96875","\u04b2\u0438\u043d\u043d\u043e\u0441\u0442 \u043e\u043d, \u043a\u0438 \u043d\u043e\u0445\u0443\u043d\u0438 \u0434\u0438\u043b\u0431\u0430\u043d\u0434 ...","\u04b2\u0438\u043d\u043d\u043e\u0441\u0442 \u043e\u043d, \u043a\u0438 \u043d\u043e\u0445\u0443\u043d\u0438 \u0434\u0438\u043b\u0431\u0430\u043d\u0434 \u0440\u0438\u0448\u0442\u0430\u04e3,\n\u0401 \u0445\u0443\u043d\u0438 \u0431\u0435\u0434\u0438\u043b\u0435\u0441\u0442, \u043a\u0438 \u0434\u0430\u0440 \u0431\u0430\u043d\u0434 \u043a\u0443\u0448\u0442\u0430\u04e3?\n\u041c\u0430\u043d \u043e\u0434\u0430\u043c\u04e3 \u0431\u0430 \u043b\u0443\u0442\u0444\u0438 \u0442\u0443 \u0434\u0438\u0433\u0430\u0440 \u043d\u0430\u0434\u0438\u0434\u0430\u0430\u043c,\n\u0418\u043d \u0441\u0443\u0440\u0430\u0442\u0443 \u0441\u0438\u0444\u0430\u0442, \u043a\u0438 \u0442\u0443 \u0434\u043e\u0440\u04e3, \u0444\u0430\u0440\u0438\u0448\u0442\u0430\u04e3.\n\u0412- \u0438\u043d \u0442\u0443\u0440\u0444\u0430\u0442\u0430\u0440, \u043a\u0438 \u0442\u043e \u0434\u0438\u043b\u0438 \u043c\u0430\u043d \u0434\u0430\u0440\u043c\u0430\u043d\u0434\u0438 \u0442\u0443\u0441\u0442,\n\u04b2\u043e\u0437\u0438\u0440 \u043d\u0430\u0431\u0443\u0434\u0430 \u044f\u043a \u0434\u0430\u043c\u0443 \u0493\u043e\u0438\u0431 \u043d\u0430\u0433\u0430\u0448\u0442\u0430\u04e3.\n\u0414\u0430\u0440 \u04b3\u0435\u04b7 \u04b3\u0430\u043b\u049b\u0430 \u043d\u0435\u0441\u0442, \u043a\u0438 \u0451\u0434\u0430\u0442 \u043d\u0430\u043c\u0435\u0440\u0430\u0432\u0430\u0434,\n\u0414\u0430\u0440 \u04b3\u0435\u04b7 \u0431\u0443\u049b\u044a\u0430 \u043d\u0435\u0441\u0442, \u043a\u0438 \u0442\u0443\u0445\u043c\u0435 \u043d\u0430\u043a\u0438\u0448\u0442\u0430\u04e3.\n\u041c\u043e \u0434\u0430\u0444\u0442\u0430\u0440 \u0430\u0437 \u04b3\u0438\u043a\u043e\u044f\u0442\u0438 \u0438\u0448\u049b\u0430\u0442 \u043d\u0430\u0431\u0438\u0448\u0442\u0430\u0435\u043c,\n\u0422\u0443 \u0441\u0430\u043d\u0433\u0434\u0438\u043b, \u04b3\u0438\u043a\u043e\u044f\u0442\u0438 \u043c\u043e \u0434\u0430\u0440 \u043d\u0430\u0431\u0438\u0448\u0442\u0430\u04e3.\n\u0417\u0435\u0431\u0443 \u0444\u0438\u0440\u0435\u0431 \u043e\u0434\u0430\u043c\u0438\u0451\u043d\u0440\u043e \u04b3\u0438\u043a\u043e\u044f\u0442\u0435\u0441\u0442,\n\u04b2\u0443\u0440\u04e3 \u043c\u0430\u0433\u0430\u0440, \u043d\u0430 \u0430\u0437 \u0433\u0438\u043b\u0438 \u043e\u0434\u0430\u043c \u0441\u0438\u0440\u0438\u0448\u0442\u0430\u04e3?\n\u0410\u0437 \u0430\u043d\u0431\u0430\u0440\u0443 \u0431\u0443\u043d\u0430\u0444\u0448\u0430\u0438 \u0442\u0430\u0440 \u0431\u0430\u0440\u0442\u0430\u0440 \u043e\u043c\u0430\u0434\u0430\u0441\u0442,\n\u041e\u043d \u043c\u04ef\u0439\u0438 \u043c\u0443\u0448\u043a\u0431\u04ef\u0439, \u043a\u0438 \u0434\u0430\u0440 \u043f\u043e\u0439 \u04b3\u0438\u0448\u0442\u0430\u04e3.\n\u041c\u0430\u043d \u0434\u0430\u0440 \u0431\u0430\u0451\u043d\u0438 \u0432\u0430\u0444\u0438 \u0442\u0443 \u04b3\u0430\u0439\u0440\u043e\u043d \u0431\u0438\u043c\u043e\u043d\u0434\u0430\u0430\u043c,\n\u04b2\u0430\u0434\u0434\u0435\u0441\u0442 \u04b3\u0443\u0441\u043d\u043d\u043e\u0432\u0443 \u0442\u0443 \u0430\u0437 \u04b3\u0430\u0434 \u0433\u0443\u0437\u0430\u0448\u0442\u0430\u04e3.\n\u0421\u0430\u0440 \u043c\u0435\u043d\u0438\u04b3\u0430\u043d\u0434 \u043f\u0435\u0448\u0438 \u0445\u0430\u0442\u0430\u0442 \u043e\u0440\u0438\u0444\u043e\u043d\u0438 \u0424\u043e\u0440\u0441,\n\u0411\u0430\u0439\u0442\u0435 \u043c\u0430\u0433\u0430\u0440 \u0437\u0438 \u0433\u0443\u0444\u0442\u0430\u0438 \u0421\u0430\u044a\u0434\u04e3 \u043d\u0430\u0431\u0438\u0433\u0442\u0430\u04e3.")
B.a5l=new A.a("c6bac26d-db1a-4553-87fd-b126ebaac187","3537f811-9658-4f9b-a29b-6311e802e60e","\u0410\u0439 \u043e\u0442\u0430\u0448\u0438 \u0445\u0438\u0440\u043c\u0430\u043d\u0438 \u0493\u0430\u0440\u0438\u0431\u043e\u043d,","\u0410\u0439 \u043e\u0442\u0430\u0448\u0438 \u0445\u0438\u0440\u043c\u0430\u043d\u0438 \u0493\u0430\u0440\u0438\u0431\u043e\u043d,\n\u0411\u0438\u043d\u0448\u0438\u043d, \u043a\u0438 \u04b3\u0430\u0437\u043e\u0440 \u0444\u0438\u0442\u043d\u0430 \u0431\u0430\u0440\u0445\u043e\u0441\u0442.\n\u0411\u043e\u043b\u043e\u0438 \u0447\u0443\u043d\u0438\u043d \u0430\u0433\u0430\u0440 \u0434\u0430\u0440 \u0438\u0441\u043b\u043e\u043c\n\u0413\u04ef\u044f\u043d\u0434, \u043a\u0438 \u04b3\u0430\u0441\u0442, \u0437\u0435\u0440\u0443 \u0431\u043e\u043b\u043e\u0441\u0442.")
B.adk=new A.a("6cf49887-ff17-4f64-9599-914c183829cf","3537f811-9658-4f9b-a29b-6311e802e60e","\u0422\u043e \u0442\u0430\u0432\u043e\u043d\u04e3, \u043c\u0430\u043a\u0430\u0448 \u0437\u0438 \u043c\u0430\u0440\u0434\u04e3 \u0434\u0430\u0441\u0442...","\u0422\u043e \u0442\u0430\u0432\u043e\u043d\u04e3, \u043c\u0430\u043a\u0430\u0448 \u0437\u0438 \u043c\u0430\u0440\u0434\u04e3 \u0434\u0430\u0441\u0442,\n\u041a\u0438 \u0431\u0430 \u0441\u0443\u0441\u0442\u04e3 \u043a\u0430\u0441\u0435 \u0437\u0438 \u043c\u0430\u0440\u0433 \u043d\u0430\u04b7\u0430\u0441\u0442.\n\u04b2\u0430\u0440 \u043a\u04e3 \u04ef\u0440\u043e \u0431\u0430\u043b\u0430\u043d\u0434 \u043c\u0430\u0440\u0434\u04e3 \u043a\u0430\u0440\u0434,\n\u0422\u043e \u0431\u0430 \u0440\u04ef\u0437\u0438 \u0430\u04b7\u0430\u043b \u043d\u0430\u0433\u0430\u0440\u0434\u0430\u0434 \u043f\u0430\u0441\u0442.\n\u0421\u0430\u0440 \u0444\u0443\u0440\u043e\u0440\u0430\u0434 \u0447\u0443 \u0442\u0438\u0440 \u0434\u0430\u0440 \u043c\u0430\u0440\u0434\u04e3,\n\u041a\u0438 \u043c\u0438\u0451\u043d \u04b7\u0430\u043d\u0433\u0440\u043e \u0447\u0443 \u043d\u0430\u0439\u0437\u0430 \u0431\u0438\u0431\u0430\u0441\u0442.")
B.a5Y=new A.a("30c445f5-b020-4f3f-b7f5-a02605506558","3537f811-9658-4f9b-a29b-6311e802e60e","\u0410\u0439 \u0431\u0430\u0441\u0435 \u0440\u0430\u0437\u043c\u0433\u043e\u04b3\u0438 \u0447\u0443\u043d \u0434\u04ef\u0437\u0430\u0445,","\u0410\u0439 \u0431\u0430\u0441\u0435 \u0440\u0430\u0437\u043c\u0433\u043e\u04b3\u0438 \u0447\u0443\u043d \u0434\u04ef\u0437\u0430\u0445,\n\u041a\u0438 \u049b\u0430\u0437\u043e \u0430\u043d\u0434\u0430\u0440 \u04ef \u0434\u0443\u0440\u0443\u0441\u0442 \u043d\u0430\u0440\u0430\u0441\u0442,\n\u041d\u0430\u0439\u0437\u0430, \u0447\u0443 \u04b3\u0430\u043c\u043b\u0430 \u0445\u043e\u0441\u0442\u0430\u043c \u0431\u0443\u0440\u0434\u0430\u043d,\n\u0413\u0430\u0448\u0442\u0430 \u043f\u0435\u0447\u043e\u043d \u043c\u0430\u0440\u043e \u0447\u0443 \u043c\u043e\u0440 \u0431\u0430 \u0434\u0430\u0441\u0442.\n\u0413\u0443\u0444\u0442\u0430\u043c, \u0430\u0439 \u043c\u043e\u04b3\u0438 \u043c\u0430\u0440\u0434\u0438 \u0440\u043e\u0441\u0442\u0433\u0430\u0440\u043e\u0439,\n\u041a\u0438 \u0431\u0430\u0441\u0435 \u0434\u0438\u043b \u0431\u0430 \u0442\u0443 \u0431\u0438\u0445\u043e\u04b3\u0430\u043c, \u04b3\u0430\u0441\u0442.")
B.aki=new A.a("1df46a84-d7f8-4035-b7a3-2e25d16ade10","3537f811-9658-4f9b-a29b-6311e802e60e","\u041c\u0430\u0440\u043e \u043c\u043e\u043c\u0438 \u043c\u0430\u043d \u043d\u043e\u043c \u043c\u0430\u0440\u0433\u0438 \u0442\u0443 \u043a\u0430\u0440...","\u041c\u0430\u0440\u043e \u043c\u043e\u043c\u0438 \u043c\u0430\u043d \u043d\u043e\u043c \u043c\u0430\u0440\u0433\u0438 \u0442\u0443 \u043a\u0430\u0440\u0434,\n\u0417\u0430\u043c\u043e\u043d\u0430 \u043c\u0430\u0440\u043e \u043f\u0443\u0442\u043a\u0438 \u0442\u0430\u0440\u043a\u0438 \u0442\u0443 \u043a\u0430\u0440\u0434.\n\u04b2\u0430\u043c \u0430\u043a\u043d\u0443\u043d \u0431\u0430 \u0445\u043e\u043a \u0430\u043d\u0434\u0430\u0440\u043e\u0440\u0430\u043c \u0441\u0430\u0440\u0430\u0442,\n\u0411\u0438\u0441\u04ef\u0437\u0430\u043c \u0434\u0438\u043b\u0438 \u043c\u0435\u04b3\u0440\u0443\u0431\u043e\u043d \u043c\u043e\u0434\u0430\u0440\u0430\u0442!")
B.akQ=new A.a("b31d9a86-0091-4ed0-8532-03f3fa681ffc","3537f811-9658-4f9b-a29b-6311e802e60e","\u0410\u0433\u0430\u0440 \u0447\u0430\u0440\u0445 \u0431\u043e \u043c\u0430\u043d \u0431\u0430\u0440\u043e\u0440\u0430\u0434 \u0445\u0443\u0440\u04ef\u0448...","\u0410\u0433\u0430\u0440 \u0447\u0430\u0440\u0445 \u0431\u043e \u043c\u0430\u043d \u0431\u0430\u0440\u043e\u0440\u0430\u0434 \u0445\u0443\u0440\u04ef\u0448,\n\u0411\u0430 \u0433\u0443\u0440\u0437\u0438 \u0433\u0430\u0440\u043e\u043d\u0430\u0448 \u0431\u0438\u043c\u043e\u043b\u0430\u043c \u0434\u0443 \u0433\u04ef\u0448.\n\u0411\u0430 \u0433\u0443\u0440\u0437\u0438 \u0433\u0430\u0440\u043e\u043d \u0431\u0438\u0448\u043a\u0430\u043d\u0430\u043c \u043f\u0430\u0439\u043a\u0430\u0440\u0430\u0448,\n\u0411\u0430 \u043d\u0430\u0439\u0437\u0430 \u0440\u0430\u0431\u043e\u044f\u043c \u04b3\u0430\u043c\u0430 \u0430\u0445\u0442\u0430\u0440\u0430\u0448.")
B.ac2=new A.a("233b4811-7b2f-4015-8a1b-9dd65a581b3d","3537f811-9658-4f9b-a29b-6311e802e60e","\u0411\u0438\u0437\u04e3 \u0448\u043e\u0434\u043c\u043e\u043d, \u0430\u0439 \u043f\u0430\u0440\u0438\u0447\u0435\u04b3\u0440\u0430 \u0445\u043e\u04b3\u0430...","\u0411\u0438\u0437\u04e3 \u0448\u043e\u0434\u043c\u043e\u043d, \u0430\u0439 \u043f\u0430\u0440\u0438\u0447\u0435\u04b3\u0440\u0430 \u0445\u043e\u04b3\u0430\u0440!\n\u041a\u0438 \u0438\u043d\u0430\u043a \u0431\u0430 \u0442\u0430\u0432\u0444\u0438\u049b\u0438 \u0434\u0438\u0434\u043e\u0440\u0438 \u0434\u043e\u0432\u0430\u0440\n\u0420\u0430\u0431\u0443\u0434\u0430\u043c \u0437\u0438 \u0437\u0438\u043d \u0434\u0443\u0448\u043c\u0430\u043d\u043e\u043d\u0440\u043e \u0431\u0430 \u043d\u0430\u0439\u0437\u0430,\n\u0411\u0430\u0434-\u043e\u043d \u0441\u043e\u043d \u043a\u0438 \u0434\u043e\u043d\u0430 \u0440\u0430\u0431\u043e\u044f\u0434 \u043a\u0430\u0431\u04ef\u0442\u0430\u0440.\n\u0411\u0430 \u043d\u043e\u043c\u0443\u0441\u0438 \u0442\u0443 \u049b\u0430\u0441\u0434 \u043a\u0430\u0440\u0434\u0430\u043d\u0434 \u0445\u0430\u0441\u043c\u043e\u043d,\n\u0417\u0438 \u0442\u0435\u0493\u0438 \u043c\u0430\u043d \u0430\u043a\u043d\u0443\u043d \u0431\u0438\u0434\u0438\u0434\u0430\u043d\u0434 \u043a\u0430\u0439\u0444\u0430\u0440.\n\u041a\u0443\u043b\u0430\u04b3 \u043c\u0430\u0440\u0434\u0440\u043e \u0431\u0430\u04b3\u0440\u0438 \u043d\u043e\u043c\u0443\u0441 \u0431\u043e\u044f\u0434,\n\u0427\u0443 \u043d\u043e\u043c\u0443\u0441 \u043d\u0435, \u0447\u0438 \u043a\u0443\u043b\u043e\u04b3\u0443 \u0447\u0438 \u043c\u0438\u044a\u04b7\u0430\u0440.\n\u0422\u0430\u043c\u0430\u044a \u043a\u0430\u0440\u0434 \u04b3\u0430\u0440 \u043a\u0430\u0441 \u0431\u0430 \u043d\u043e\u043c\u0443\u0441\u0438 \u043c\u0430\u0440\u0434\u0443\u043c,\n\u04b2\u0430\u043b\u043e\u043b \u0430\u0441\u0442, \u0444\u0430\u0440\u043c\u0443\u0434 \u0445\u0443\u043d\u0430\u0448 \u041f\u0430\u044f\u043c\u0431\u0430\u0440.")
B.a71=new A.a("66f932c5-5c36-4ba6-b479-87b2b61e9e20","3537f811-9658-4f9b-a29b-6311e802e60e","\u0411\u0430\u0441 \u0445\u0443\u043d, \u043a\u0438 \u0431\u0430 \u0442\u0435\u0493\u0438 \u0493\u0430\u043c\u0437\u0430\u0433\u043e\u043d \u0440...","\u0411\u0430\u0441 \u0445\u0443\u043d, \u043a\u0438 \u0431\u0430 \u0442\u0435\u0493\u0438 \u0493\u0430\u043c\u0437\u0430\u0433\u043e\u043d \u0440\u0435\u0445\u0442\u0430\u04e3,\n\u0411\u0430\u0441 \u0434\u0438\u043b, \u043a\u0438 \u0431\u0430 \u0442\u043e\u0440\u0438 \u0437\u0443\u043b\u0444 \u043e\u0432\u0435\u0445\u0442\u0430\u04e3.\n\u0411\u043e\u0440\u043e\u043d\u0438 \u0434\u0443\u0441\u0430\u0434\u0441\u043e\u043b\u0430 \u0444\u0443\u0440\u0443 \u043d\u0430\u043d\u0448\u043e\u043d\u0430\u0434,\n\u0418\u043d \u0433\u0430\u0440\u0434\u0438 \u0431\u0430\u043b\u043e\u04b3\u043e, \u043a\u0438 \u0442\u0443 \u0430\u043d\u0433\u0435\u0445\u0442\u0430\u04e3.")
B.ae_=new A.a("d438e3e9-79e4-4599-928e-0841b1450508","3537f811-9658-4f9b-a29b-6311e802e60e","\u0411\u0438\u043d\u043e\u043b\u0435\u0434, \u0430\u0439 \u0434\u04ef\u0441\u0442\u043e\u043d\u0443 \u0431\u0438\u0433\u0438\u0440\u0439\u0435\u0434","\u0411\u0438\u043d\u043e\u043b\u0435\u0434, \u0430\u0439 \u0434\u04ef\u0441\u0442\u043e\u043d\u0443 \u0431\u0438\u0433\u0438\u0440\u0439\u0435\u0434\n\u0411\u0430\u0440 \u043e\u043d \u0442\u0430\u043b\u044a\u0430\u0442\u0438 \u0445\u0443\u0431\u0443 \u0444\u0430\u0440\u0440\u0438 \u043a\u0430\u0451\u043d\u04e3!\n\u0411\u0438\u0445\u0430\u043d\u0434, \u0430\u0439 \u0431\u0430\u0434\u0430\u043d\u0434\u0435\u0448, \u0431\u0430\u044a\u0434 \u0430\u0437 \u0432\u0430\u0444\u043e\u0442\u0430\u0448,\n\u0417\u0438 \u0447\u0430\u043d\u0433\u043e\u043b\u0438 \u043c\u0430\u0440\u0433 \u0430\u0440 \u0431\u0438\u0440\u0430\u0441\u0442\u0430\u043d \u0442\u0430\u0432\u043e\u043d\u04e3.\n\u0427\u04e3 \u0448\u043e\u0434\u04e3 \u0431\u0430 \u043c\u0430\u0440\u0433\u0430\u0448, \u043a\u0438 \u043e\u0445\u0438\u0440 \u0442\u0443\u0440\u043e \u04b3\u0430\u043c\n\u0414\u0438\u04b3\u0430\u0434 \u0434\u0430\u0432\u0440\u0438 \u0433\u0430\u0440\u0434\u0443\u043d \u0430\u0437 \u0438\u043d \u0434\u04ef\u0441\u0442\u0433\u043e\u043d\u04e3!")
B.aiV=new A.a("55256d68-07b5-4b28-9ecf-86845d5e241e","3537f811-9658-4f9b-a29b-6311e802e60e","\u0414\u0430\u0440 \u0448\u0435\u044a\u0440 \u0441\u0435 \u0442\u0430\u043d \u043f\u0430\u044f\u043c\u0431\u0430\u0440\u043e\u043d\u0430\u043d\u0434, ...","\u0414\u0430\u0440 \u0448\u0435\u044a\u0440 \u0441\u0435 \u0442\u0430\u043d \u043f\u0430\u044f\u043c\u0431\u0430\u0440\u043e\u043d\u0430\u043d\u0434, \u04b2\u0430\u0440\u0447\u0430\u043d\u0434 \u043a\u0438 \xab\u043b\u043e \u043d\u0430\u0431\u0438\u044f \u0431\u0430\u044a\u0434\u04e3\xbb:\n\u0410\u0432\u0441\u043e\u0444\u0443 \u049b\u0430\u0441\u0438\u0434\u0430\u0432\u0443 \u0493\u0430\u0437\u0430\u043b\u0440\u043e \u0424\u0438\u0440\u0434\u0430\u0432\u0441\u0438\u044e \u0410\u043d\u0432\u0430\u0440\u0438\u044e \u0421\u0430\u044a\u0434\u04e3.")
B.aqz=new A.a("0ea3bb5b-518c-40e3-b5a4-e382c21e3262","b5252e27-e6c6-401e-aca9-5fec3da36b65","\u0414\u0438\u0436\u0435","\u0414\u0438\u0436\u0435\n75\n\u0431\u0443\u0434, \u043a-\u0430\u0448 \u0445\u043e\u043d\u0434\u0430\u043d\u0434\u04e3 \u0421\u0430\u043f\u0435\u0434,\n\u0411\u0430\u0434-\u043e\u043d \u0434\u0438\u0436 \u0431\u0443\u0434 \u044d\u0440\u043e\u043d\u0438\u0451\u043d\u0440\u043e \u0443\u043c\u0435\u0434.\n\u041d\u0438\u0433\u0430\u04b3\u0431\u043e\u043d\u0438 \u0434\u0438\u0436 \u0440\u0430\u0437\u043c\u0434\u0438\u0434\u0430 \u04b2\u0430\u04b7\u0438\u0440,\n\u041a\u0438 \u0431\u043e \u0437\u04ef\u0440\u0438 \u0434\u0438\u043b \u0431\u0443\u0434\u0443 \u0431\u043e \u0433\u0443\u0440\u0437\u0443 \u0442\u0438\u0440.\n\u04b2\u0430\u043d\u04ef\u0437 \u043e\u043d \u0437\u0430\u043c\u043e\u043d \u0413\u0430\u0436\u0434\u0430\u04b3\u0430\u043c \u0445\u0443\u0440\u0434 \u0431\u0443\u0434,\n\u0411\u0430 \u0445\u0443\u0440\u0434\u04e3 \u0433\u0430\u0440\u043e\u044f\u043d\u0434\u0430\u0432\u0443 \u0433\u0443\u0440\u0434 \u0431\u0443\u0434.\n\u042f\u043a\u0435 \u0434\u0443\u0445\u0442\u0430\u0440\u0430\u0448 \u0431\u0443\u0434 \u0433\u0443\u0440\u0434\u0443 \u0441\u0430\u0432\u043e\u0440,\n\u0411\u0430\u0434\u0430\u043d\u0434\u0435\u0448\u0443 \u0433\u0430\u0440\u0434\u0430\u043d\u043a\u0430\u0448\u0443 \u043d\u043e\u043c\u0434\u043e\u0440.\n\u0427\u0443 \u0421\u0443\u04b3\u0440\u043e\u0431 \u043d\u0430\u0437\u0434\u0438\u043a\u0438 \u043e\u043d \u0434\u0438\u0436 \u0440\u0430\u0441\u0438\u0434,\n\u04b2\u0430\u04b7\u0438\u0440\u0438 \u0434\u0438\u043b\u043e\u0432\u0430\u0440 \u043c\u0430\u0440 \u04ef\u0440\u043e \u0431\u0438\u0434\u0438\u0434.\n\u041d\u0438\u0448\u0430\u0441\u0442 \u0430\u0437 \u0431\u0430\u0440\u0438 \u0431\u043e\u0434\u043f\u043e\u0435\n76\n\u0447\u0443 \u0433\u0430\u0440\u0434,\n\u0417\u0438 \u0434\u0438\u0436 \u0440\u0430\u0444\u0442 \u043f\u04ef\u0451\u043d \u0431\u0430 \u0434\u0430\u0448\u0442\u0438 \u043d\u0430\u0431\u0430\u0440\u0434.\n\u0427\u0443 \u0421\u0443\u04b3\u0440\u043e\u0431\u0438 \u04b7\u0430\u043d\u0433\u043e\u0432\u0430\u0440 \u04ef\u0440\u043e \u0431\u0438\u0434\u0438\u0434,\n\u0411\u0430\u0440\u043e\u0448\u0443\u0444\u0442\u0443 \u0448\u0430\u043c\u0448\u0435\u0440\u0438 \u043a\u0438\u043d \u0431\u0430\u0440\u043a\u0430\u0448\u0438\u0434.\n\u0417\u0438 \u043b\u0430\u0448\u043a\u0430\u0440 \u0431\u0443\u0440\u0443\u043d \u0442\u043e\u0445\u0442 \u0431\u0430\u0440 \u0441\u043e\u043d\u0438 \u0431\u043e\u0434,\n\u0427\u0443\u043d\u0438\u043d \u0433\u0443\u0444\u0442, \u043a - \xab\u0410\u0439 \u0434\u043e\u0434\u0430 \u04b7\u043e\u043d\u0430\u0442 \u0431\u0430 \u0431\u043e\u0434!\n\u0422\u0443 \u0442\u0430\u043d\u04b3\u043e \u0431\u0430 \u04b7\u0430\u043d\u0433 \u043e\u043c\u0430\u0434\u04e3 \u0445\u0438\u0440\u0430-\u0445\u0438\u0440,\n\u041a\u0443\u043d\u0443\u043d \u043f\u043e\u0439 \u0434\u043e\u0440\u0443 \u0438\u043d\u043e\u043d \u0441\u0430\u0445\u0442 \u0433\u0438\u0440!\n\u0427\u04e3 \u043c\u0430\u0440\u0434\u0438\u044e \u043d\u043e\u043c\u0443 \u043d\u0430\u0436\u043e\u0434\u0438 \u0442\u0443 \u0447\u0438\u0441\u0442,\n\u041a\u0438 \u0437\u043e\u044f\u043d\u0434\u0430\u0440\u043e \u0431\u0430\u0440 \u0442\u0443 \u0431\u043e\u044f\u0434 \u0433\u0438\u0440\u0438\u0441\u0442?\xbb\n\u04b2\u0430\u04b7\u0438\u0440\u0430\u0448 \u0447\u0443\u043d\u0438\u043d \u0434\u043e\u0434 \u043f\u043e\u0441\u0443\u0445, \u043a\u0438 \xab\u0411\u0430\u0441!\n\u0411\u0430 \u04b7\u0430\u043d\u0433\u0430\u0442 \u043d\u0430\u0431\u043e\u044f\u0434 \u043c\u0430\u0440\u043e \u0451\u0440 \u043a\u0430\u0441.\n\u04b2\u0430\u04b7\u0438\u0440\u0438 \u0434\u0430\u043b\u0435\u0440\u0438 \u0441\u0438\u043f\u0430\u04b3\u0431\u0430\u0434 \u043c\u0430\u043d\u0430\u043c!\n\u04b2\u0430\u043c \u0430\u043a\u043d\u0443\u043d \u0441\u0430\u0440\u0430\u0442\u0440\u043e \u0437\u0438 \u0442\u0430\u043d \u0431\u0430\u0440\u043a\u0430\u043d\u0430\u043c.\n\u0424\u0438\u0440\u0438\u0441\u0442\u0430\u043c \u0431\u0430 \u043d\u0430\u0437\u0434\u0438\u043a\u0438 \u0448\u043e\u04b3\u0438 \u04b7\u0430\u04b3\u043e\u043d,\n\u0422\u0430\u043d\u0430\u0442\u0440\u043e \u043a\u0430\u043d\u0430\u0434 \u043a\u0430\u0440\u0433\u0430\u0441 \u0430\u043d\u0434\u0430\u0440 \u043d\u0438\u04b3\u043e\u043d\xbb.\n\u0411\u0438\u0445\u0430\u043d\u0434\u0438\u0434 \u0421\u0443\u04b3\u0440\u043e\u0431, \u043a-\u0438\u043d \u0433\u0443\u0444\u0442\u0443\u0433\u04ef\u0439\n\u0411\u0430 \u0433\u04ef\u0448 \u043e\u043c\u0430\u0434\u0430\u0448, \u0442\u0435\u0437 \u0431\u0438\u043d\u04b3\u043e\u0434 \u0440\u04ef\u0439.\n\u0421\u0430\u0431\u0443\u043a \u043d\u0430\u0439\u0437\u0430 \u0431\u0430\u0440 \u043d\u0430\u0439\u0437\u0430 \u0430\u043d\u0434\u043e\u0445\u0442\u0430\u043d\u0434,\n\u041a\u0438 \u0430\u0437 \u044f\u043a\u0434\u0438\u0433\u0430\u0440 \u0431\u043e\u0437\u043d\u0430\u0448\u043d\u043e\u0445\u0442\u0430\u043d\u0434.\n\u0427\u0443 \u043e\u0442\u0430\u0448 \u0431\u0438\u0451\u043c\u0430\u0434 \u0433\u0430\u0432\u0438 \u043f\u0438\u043b\u0437\u04ef\u0440,\n\u0427\u0443 \u043a\u04ef\u04b3\u0435 \u0440\u0430\u0432\u043e\u043d \u043a\u0430\u0440\u0434 \u0430\u0437 \u04b7\u043e \u0441\u0443\u0442\u0443\u0440.\n\u042f\u043a\u0435 \u043d\u0430\u0439\u0437\u0430 \u0437\u0430\u0434 \u0431\u0430\u0440 \u043c\u0438\u0451\u043d\u0430\u0448 \u04b2\u0430\u04b7\u0438\u0440,\n\u041d\u0430\u0451\u043c\u0430\u0434 \u0441\u0438\u043d\u043e\u043d \u0430\u043d\u0434\u0430\u0440 \u04ef \u04b7\u043e\u0439\u0433\u0438\u0440.\n\n75\n\u0434\u0438\u0436 \u2013 \u049b\u0430\u043b\u044a\u0430.\n76\n\u0431\u043e\u0434\u043f\u043e\u0439 \u2013 \u043a\u0438\u043d\u043e\u044f \u0430\u0437 \u0430\u0441\u043f\u0438 \u0442\u043e\u0437\u04e3.\n\n\n## 42 (Page 42)\n\n\u0421\u0438\u043d\u043e\u043d \u0431\u043e\u0437\u043f\u0430\u0441 \u043a\u0430\u0440\u0434 \u0421\u0443\u04b3\u0440\u043e\u0431\u0438 \u0448\u0435\u0440,\n\u0411\u0443\u043d\u0438 \u043d\u0430\u0439\u0437\u0430 \u0437\u0430\u0434 \u0431\u0430\u0440 \u043c\u0438\u0451\u043d\u0430\u0448 \u0434\u0430\u043b\u0435\u0440.\n\u0417\u0438 \u0437\u0438\u043d \u0431\u0430\u0440\u0433\u0438\u0440\u0438\u0444\u0442\u0430\u0448 \u0431\u0430 \u043a\u0438\u0440\u0434\u043e\u0440\u0438 \u0431\u043e\u0434,\n\u041d\u0430\u0451\u043c\u0430\u0434 \u04b3\u0430\u043c\u0435 \u0437-\u04ef \u0431\u0430 \u0434\u0438\u043b-\u0434\u0430\u0440-\u0448 \u0451\u0434.\n\u0411\u0438\u0437\u0430\u0434 \u0431\u0430\u0440 \u0437\u0430\u043c\u0438\u043d\u0430\u0448 \u0447\u0443 \u044f\u043a \u043b\u0430\u0445\u0442\u0438 \u043a\u04ef\u04b3,\n\u0411\u0430 \u04b7\u043e\u043d\u0443 \u0434\u0438\u043b\u0430\u0448 \u0430\u043d\u0434\u0430\u0440\u043e\u043c\u0430\u0434 \u0441\u0443\u0442\u04ef\u04b3.\n\u0417\u0438 \u0430\u0441\u043f \u0430\u043d\u0434\u0430\u0440\u043e\u043c\u0430\u0434, \u043d\u0438\u0448\u0430\u0441\u0442 \u0430\u0437 \u0431\u0430\u0440\u0430\u0448,\n\u04b2\u0430\u043c\u0435\u0445\u043e\u0441\u0442 \u0430\u0437 \u0442\u0430\u043d \u0431\u0443\u0440\u0438\u0434\u0430\u043d \u0441\u0430\u0440\u0430\u0448.\n\u0411\u0438\u043f\u0435\u0447\u0438\u0434\u0443 \u0431\u0430\u0440\u0433\u0430\u0448\u0442 \u0431\u0430\u0440 \u0434\u0430\u0441\u0442\u0438 \u0440\u043e\u0441\u0442,\n\u0492\u0430\u043c\u04e3 \u0448\u0443\u0434, \u0437\u0438 \u0421\u0443\u04b3\u0440\u043e\u0431 \u0437\u0438\u043d\u04b3\u043e\u0440 \u0445\u043e\u0441\u0442\n77\n.\n\u0420\u0430\u04b3\u043e \u043a\u0430\u0440\u0434 \u0437-\u04ef \u04b7\u0430\u043d\u0433\u0443 \u0437\u0438\u043d\u04b3\u043e\u0440 \u0434\u043e\u0434,\n\u0427\u0443 \u0445\u0443\u0448\u043d\u0443\u0434 \u0448\u0443\u0434, \u043f\u0430\u043d\u0434\u0438 \u0431\u0438\u0441\u0451\u0440 \u0434\u043e\u0434.\n\u0411\u0438\u0431\u0430\u0441\u0442\u0430\u0448 \u0431\u0430 \u0431\u0430\u043d\u0434 \u043e\u043d \u0433\u0430\u04b3\u0435 \u04b7\u0430\u043d\u0433\u04b7\u04ef\u0439,\n\u0411\u0430 \u043d\u0430\u0437\u0434\u0438\u043a\u0438 \u04b2\u0443\u043c\u043e\u043d \u0444\u0438\u0440\u0438\u0441\u0442\u043e\u0434 \u04ef\u0439.\n\u0411\u0430 \u0434\u0438\u0436 \u04b3\u0430\u043c\u0447\u0443 \u043e\u0433\u0430\u04b3 \u0448\u0443\u0434\u0430\u043d\u0434 \u0430\u0437 \u04b2\u0430\u04b7\u0438\u0440,\n\u041a\u0438 \u04ef\u0440\u043e \u0433\u0438\u0440\u0438\u0444\u0442\u0430\u043d\u0434\u0443 \u0431\u0443\u0440\u0434\u0430\u043d\u0434 \u0430\u0441\u0438\u0440.\n\u0425\u0443\u0440\u04ef\u0448 \u043e\u043c\u0430\u0434\u0443 \u043d\u043e\u043b\u0430\u0438 \u043c\u0430\u0440\u0434\u0443 \u0437\u0430\u043d,\n\u041a\u0438 \u0433\u0443\u043c \u0448\u0443\u0434 \u04b2\u0430\u04b7\u0438\u0440 \u0430\u043d\u0434\u0430\u0440 \u043e\u043d \u0430\u043d\u04b7\u0443\u043c\u0430\u043d!")
B.amB=new A.a("3b6174d5-ac40-41af-b29a-98da1758c2aa","b5252e27-e6c6-401e-aca9-5fec3da36b65","\u0427\u0443 \u043e\u0433\u043e\u04b3 \u0448\u0443\u0434 \u0434\u0443\u0445\u0442\u0430\u0440\u0438 \u0413\u0430\u0436\u0434\u0430\u04b3\u0430\u043c,","\u0427\u0443 \u043e\u0433\u043e\u04b3 \u0448\u0443\u0434 \u0434\u0443\u0445\u0442\u0430\u0440\u0438 \u0413\u0430\u0436\u0434\u0430\u04b3\u0430\u043c,\n\u041a\u0438 \u0441\u043e\u043b\u043e\u0440\u0438 \u043e\u043d \u0430\u043d\u04b7\u0443\u043c\u0430\u043d \u0433\u0430\u0448\u0442 \u043a\u0430\u043c,\n\u0492\u0430\u043c\u0438\u043d \u0433\u0430\u0448\u0442\u0443 \u0431\u0430\u0440\u0437\u0430\u0434 \u0445\u0443\u0440\u04ef\u0448\u0435 \u0431\u0430\u0434\u0430\u0440\u0434,\n\u0411\u0430\u0440\u043e\u0432\u0430\u0440\u0434 \u0430\u0437 \u0434\u0438\u043b \u044f\u043a\u0435 \u0431\u043e\u0434\u0438 \u0441\u0430\u0440\u0434.\n\u0417\u0430\u043d\u0435 \u0431\u0443\u0434 \u0431\u0430\u0440 \u0441\u043e\u043d\u0438 \u0433\u0443\u0440\u0434\u0435 \u0441\u0430\u0432\u043e\u0440,\n\u04b2\u0430\u043c\u0435\u0448\u0430 \u0431\u0430 \u04b7\u0430\u043d\u0433-\u0430\u043d\u0434\u0430\u0440\u0443\u043d \u043d\u043e\u043c\u0434\u043e\u0440,\n\u041a\u0443\u04b7\u043e \u043d\u043e\u043c\u0438 \u04ef \u0431\u0443\u0434 \u0413\u0443\u0440\u0434\u043e\u0444\u0430\u0440\u0438\u0434,\n\u041a\u0438 \u0447\u0443\u043d \u04ef \u0431\u0430 \u04b7\u0430\u043d\u0433-\u0430\u043d\u0434\u0430\u0440\u0443\u043d \u043a\u0430\u0441 \u043d\u0430\u0434\u0438\u0434.\n\u0427\u0443\u043d\u043e\u043d \u043d\u0430\u043d\u0433\u0430\u0448 \u043e\u043c\u0430\u0434 \u0437\u0438 \u043a\u043e\u0440\u0438 \u04b2\u0430\u04b7\u0438\u0440,\n\u041a\u0438 \u0448\u0443\u0434 \u043b\u043e\u043b\u0430\u0431\u0430\u0440\u0433\u0430\u0448 \u0431\u0430 \u043a\u0438\u0440\u0434\u043e\u0440\u0438 \u0445\u0438\u0440.\n\u0411\u0438\u043f\u04ef\u0448\u0438\u0434 \u0434\u0438\u0440\u044a\u0438 \u0441\u0430\u0432\u043e\u0440\u043e\u043d \u0431\u0430 \u04b7\u0430\u043d\u0433,\n\u041d\u0430\u0431\u0443\u0434 \u0430\u043d\u0434\u0430\u0440 \u043e\u043d \u043a\u043e\u0440 \u04b7\u043e\u0438 \u0434\u0438\u0440\u0430\u043d\u0433.\n\u041d\u0438\u04b3\u043e\u043d \u043a\u0430\u0440\u0434 \u0433\u0435\u0441\u04ef \u0431\u0430 \u0437\u0435\u0440\u0438 \u0437\u0438\u0440\u0435\u04b3,\n\u0411\u0438\u0437\u0430\u0434 \u0431\u0430\u0440 \u0441\u0430\u0440\u0438 \u0442\u0430\u0440\u043a\u0438 \u0440\u0443\u043c\u04e3 \u0433\u0438\u0440\u0435\u04b3.\n\u0424\u0443\u0440\u0443\u0434 \u043e\u043c\u0430\u0434 \u0430\u0437 \u0434\u0438\u0436 \u0431\u0430 \u043a\u0438\u0440\u0434\u043e\u0440\u0438 \u0448\u0435\u0440,\n\u041a\u0430\u043c\u0430\u0440 \u0431\u0430\u0440 \u043c\u0438\u0451\u043d, \u0431\u043e\u0434\u043f\u043e\u0435 \u0431\u0430 \u0437\u0435\u0440.\n\n77\n\u0437\u0438\u043d\u04b3\u043e\u0440 \u0445\u043e\u0441\u0442\u0430\u043d \u2013 \u0443\u0437\u0440\u0445\u043e\u04b3\u04e3 \u043a\u0430\u0440\u0434\u0430\u043d.\n\n\n## 43 (Page 43)\n\n\u0411\u0430 \u043f\u0435\u0448\u0438 \u0441\u0438\u043f\u043e\u04b3 \u0430\u043d\u0434\u0430\u0440\u043e\u043c\u0430\u0434 \u0447\u0443 \u0433\u0430\u0440\u0434,\n\u0427\u0443 \u0440\u0430\u044a\u0434\u0438 \u0445\u0443\u0440\u04ef\u0448\u043e\u043d \u044f\u043a\u0435 \u0432\u0430\u0439\u043b\u0430 \u043a\u0430\u0440\u0434,\n\u041a\u0438 \u0433\u0443\u0440\u0434\u043e\u043d \u043a\u0430\u0434\u043e\u043c\u0430\u043d\u0434\u0443 \u0441\u043e\u043b\u043e\u0440 \u043a\u0438\u0441\u0442?\n\u0417\u0438 \u0440\u0430\u0437\u043c\u043e\u0432\u0430\u0440\u043e\u043d \u04b7\u0430\u043d\u0433\u0440\u043e \u0451\u0440 \u043a\u0438\u0441\u0442?\n\u041a\u0438 \u0431\u0430\u0440 \u043c\u0430\u043d \u044f\u043a\u0435 \u043e\u0437\u043c\u0443\u043d\u0440\u043e \u0431\u0430 \u04b7\u0430\u043d\u0433\n\u0411\u0438\u0433\u0430\u0440\u0434\u0430\u0434 \u0431\u0430 \u0441\u043e\u043d\u0438 \u0434\u0438\u043b\u043e\u0432\u0430\u0440 \u043d\u0430\u04b3\u0430\u043d\u0433.\n\u0417\u0438 \u04b7\u0430\u043d\u0433\u043e\u0432\u0430\u0440\u043e\u043d \u043b\u0430\u0448\u043a\u0430\u0440\u0438 \u0441\u0430\u0440\u0444\u0430\u0440\u043e\u0437\n\u041c\u0430\u0440 \u04ef\u0440\u043e \u043d\u0430\u0451\u043c\u0430\u0434 \u043a\u0430\u0441\u0435 \u043f\u0435\u0448\u0431\u043e\u0437.\n\u0427\u0443 \u0421\u0443\u04b3\u0440\u043e\u0431\u0438 \u0448\u0435\u0440\u0430\u0432\u0436\u0430\u043d\n78\n\u04ef\u0440\u043e \u0431\u0438\u0434\u0438\u0434,\n\u0411\u0438\u0445\u0430\u043d\u0434\u0438\u0434\u0443 \u043b\u0430\u0431\u0440\u043e \u0431\u0430 \u0434\u0430\u043d\u0434\u043e\u043d \u0433\u0430\u0437\u0438\u0434.\n\u0427\u0443\u043d\u0438\u043d \u0433\u0443\u0444\u0442, \u043a-\u043e\u043c\u0430\u0434 \u0434\u0438\u0433\u0430\u0440\u0431\u043e\u0440\u0430 \u0433\u04ef\u0440\n\u0411\u0430 \u0434\u043e\u043c\u0438 \u0445\u0443\u0434\u043e\u0432\u0430\u043d\u0434\u0438 \u0448\u0430\u043c\u0448\u0435\u0440\u0443 \u0437\u04ef\u0440.\n\u0411\u0438\u043f\u04ef\u0448\u0438\u0434 \u0445\u0430\u0444\u0442\u043e\u043d\u0443 \u0431\u0430\u0440 \u0441\u0430\u0440 \u043d\u0438\u04b3\u043e\u0434\n\u042f\u043a\u0435 \u0442\u0430\u0440\u043a\u0438 \u0447\u0438\u043d\u04e3 \u0431\u0430 \u043a\u0438\u0440\u0434\u043e\u0440\u0438 \u0431\u043e\u0434.\n\u0411\u0438\u0451\u043c\u0430\u0434 \u0434\u0430\u043c\u043e\u043d \u043f\u0435\u0448\u0438 \u0413\u0443\u0440\u0434\u043e\u0444\u0430\u0440\u0438\u0434,\n\u0428\u0435\u0440\u0430\u0432\u0436\u0430\u043d - \u0434\u0430\u043b\u0435\u0440, \u0448\u0435\u0440\u0430\u0444\u043a\u0430\u043d.\n\u0427\u0443 \u0434\u0443\u0445\u0442\u0438 \u043a\u0430\u043c\u0430\u043d\u0434\u0430\u0444\u043a\u0430\u043d \u04ef\u0440\u043e \u0431\u0438\u0434\u0438\u0434.\n\u041a\u0430\u043c\u043e\u043d\u0440\u043e \u0431\u0430 \u0437\u0435\u04b3 \u043a\u0430\u0440\u0434\u0443 \u0431\u0438\u043a\u0448\u043e\u0434 \u0431\u0430\u0440,\n\u041d\u0430\u0431\u0443\u0434 \u043c\u0443\u0440\u0493\u0440\u043e \u043f\u0435\u0448\u0438 \u0442\u0438\u0440\u0430\u0448 \u0433\u0443\u0437\u0430\u0440.\n\u0411\u0430 \u0421\u0443\u04b3\u0440\u043e\u0431-\u0431\u0430\u0440 \u0442\u0438\u0440\u0431\u043e\u0440\u043e\u043d \u0433\u0438\u0440\u0438\u0444\u0442,\n\u0427\u0430\u043f\u0443 \u0440\u043e\u0441\u0442 \u04b7\u0430\u043d\u0433\u0438 \u0441\u0430\u0432\u043e\u0440\u043e\u043d \u0433\u0438\u0440\u0438\u0444\u0442.\n\u041d\u0438\u0433\u0430\u04b3 \u043a\u0430\u0440\u0434 \u0421\u0443\u04b3\u0440\u043e\u0431\u0443 \u043e\u043c\u0430\u0434-\u0448 \u043d\u0430\u043d\u0433,\n\u0411\u0430\u0440\u043e\u0448\u0443\u0444\u0442\u0443 \u0442\u0435\u0437 \u0430\u043d\u0434\u0430\u0440\u043e\u043c\u0430\u0434 \u0431\u0430 \u04b7\u0430\u043d\u0433.\n\u0418\u043d\u043e\u043d \u0431\u0430\u0440\u0433\u0438\u0440\u043e\u0438\u0434\u0443 \u0431\u0430\u0440\u0434\u043e\u0448\u0442 \u0430\u0441\u043f,\n\u0411\u0438\u0451\u043c\u0430\u0434 \u0431\u0430 \u043a\u0438\u0440\u0434\u043e\u0440\u0438 \u041e\u0437\u0430\u0440\u0433\u0443\u0448\u0430\u0441\u043f.\n\u0411\u0430 \u0434\u0430\u0441\u0442-\u0430\u043d\u0434\u0430\u0440\u0443\u043d \u043d\u0430\u0439\u0437\u0430\u0438 \u04b7\u043e\u043d\u0441\u0438\u0442\u043e\u043d\n\u041f\u0430\u0441\u0438 \u043f\u0443\u0448\u0442\u0438 \u0445\u0443\u0434 \u043a\u0430\u0440\u0434\u0430\u0448 \u043e\u043d \u0433\u0430\u04b3 \u0441\u0438\u043d\u043e\u043d.\n\u0411\u0438\u0437\u0430\u0434 \u0431\u0430\u0440 \u043a\u0430\u043c\u0430\u0440\u0431\u0430\u043d\u0434\u0438 \u0413\u0443\u0440\u0434\u043e\u0444\u0430\u0440\u0438\u0434,\n\u0417\u0438\u0440\u0435\u04b3 \u0431\u0430\u0440 \u0442\u0430\u043d\u0430\u0448 \u044f\u043a \u0431\u0430 \u044f\u043a \u0431\u0430\u0440\u0434\u0430\u0440\u0438\u0434.\n\u0417\u0438 \u0437\u0438\u043d \u0431\u0430\u0440\u0433\u0438\u0440\u0438\u0444\u0442\u0430\u0448 \u0431\u0430 \u043a\u0438\u0440\u0434\u043e\u0440\u0438 \u0433\u04ef\u0439,\n\u041a\u0438 \u0447\u0430\u0432\u0433\u043e\u043d \u0437\u0438 \u0431\u043e\u0434 \u0430\u043d\u0434\u0430\u0440\u043e\u044f\u0434 \u0431\u0430\u0440 \u04ef\u0439.\n\u0427\u0443 \u0431\u0430\u0440 \u0437\u0438\u043d \u0431\u0438\u043f\u0435\u0447\u0438\u0434 \u0413\u0443\u0440\u0434\u043e\u0444\u0430\u0440\u0438\u0434,\n\u042f\u043a\u0435 \u0442\u0435\u0493\u0438 \u0442\u0435\u0437 \u0430\u0437 \u043c\u0438\u0451\u043d \u0431\u0430\u0440\u043a\u0430\u0448\u0438\u0434.\n\u0411\u0438\u0437\u0430\u0434, \u043d\u0430\u0439\u0437\u0430\u0438 \u04ef \u0431\u0430 \u0434\u0443 \u043d\u0438\u043c \u043a\u0430\u0440\u0434,\n\u041d\u0438\u0448\u0430\u0441\u0442 \u0430\u0437 \u0431\u0430\u0440\u0438 \u0437\u0438\u043d\u0443 \u0431\u0430\u0440\u0445\u043e\u0441\u0442 \u0433\u0430\u0440\u0434.\n\n78\n\u0448\u0435\u0440\u0430\u0432\u0436\u0430\u043d \u2013 \u0434\u0430\u043b\u0435\u0440, \u0448\u0435\u0440\u0430\u0444\u043a\u0430\u043d.\n\n\n## 44 (Page 44)\n\n\u0411\u0430 \u043e\u0432\u0430\u0440\u0434\n79\n\u0431\u043e \u04ef \u0431\u0430\u0441\u0430\u043d\u0434\u0430 \u043d\u0430\u0431\u0443\u0434,\n\u0411\u0438\u0442\u043e\u0431\u0438\u0434 \u0430\u0437 \u04ef \u0440\u04ef\u0439, \u0431\u0430\u0440\u0433\u0430\u0448\u0442 \u0437\u0443\u0434.\n\u0421\u0438\u043f\u0430\u04b3\u0431\u0430\u0434 \u0438\u043d\u043e\u043d \u0430\u0436\u0434\u0430\u04b3\u043e\u0440\u043e \u0441\u0443\u043f\u0443\u0440\u0434,\n\u0411\u0430 \u0445\u0430\u0448\u043c \u0430\u0437 \u04b7\u0430\u04b3\u043e\u043d \u0440\u04ef\u0448\u043d\u043e\u04e3 \u0431\u0438\u0431\u0443\u0440\u0434.\n\u0427\u0443 \u043e\u043c\u0430\u0434 \u0445\u0443\u0440\u04ef\u0448\u043e\u043d \u0431\u0430 \u0442\u0430\u043d\u0433-\u0430\u043d\u0434\u0430\u0440\u0430\u0448,\n\u0411\u0438\u04b7\u0443\u043d\u0431\u0438\u0434\u0443 \u0431\u0430\u0440\u0434\u043e\u0448\u0442 \u0445\u04ef\u0434 \u0430\u0437 \u0441\u0430\u0440\u0430\u0448.\n\u0420\u0430\u04b3\u043e \u0448\u0443\u0434 \u0437\u0438 \u0431\u0430\u043d\u0434\u0438 \u0437\u0438\u0440\u0435\u04b3 \u043c\u04ef\u0439\u0438 \u04ef\u0439,\n\u0414\u0443\u0440\u0430\u0445\u0448\u043e\u043d \u0447\u0443 \u0445\u0443\u0440\u0448\u0435\u0434 \u0448\u0443\u0434 \u0440\u04ef\u0439\u0438 \u04ef\u0439.\n\u0411\u0438\u0434\u043e\u043d\u0438\u0441\u0442 \u0421\u0443\u04b3\u0440\u043e\u0431, \u043a-\u04ef \u0434\u0443\u0445\u0442\u0430\u0440 \u0430\u0441\u0442,\n\u0421\u0430\u0440\u0438 \u043c\u04ef\u0439\u0438 \u04ef \u0430\u0437 \u0434\u0443\u0440\u0438 \u0430\u0444\u0441\u0430\u0440 \u0430\u0441\u0442.\n\u0428\u0438\u0433\u0438\u0444\u0442 \u043e\u043c\u0430\u0434\u0430\u0448, \u0433\u0443\u0444\u0442:\n\xab\u0410\u0437 \u044d\u0440\u043e\u043d\u0441\u0438\u043f\u043e\u04b3 \u0427\u0443\u043d\u0438\u043d \u0434\u0443\u0445\u0442\u0430\u0440 \u043e\u044f\u0434 \u0431\u0430 \u043e\u0432\u0430\u0440\u0434\u0433\u043e\u04b3?!\n\u0421\u0430\u0432\u043e\u0440\u043e\u043d\u0438 \u04b7\u0430\u043d\u0433\u04e3 \u0431\u0430 \u0440\u04ef\u0437\u0438 \u043d\u0430\u0431\u0430\u0440\u0434\n\u04b2\u0430\u043c\u043e\u043d\u043e \u0431\u0430 \u0431\u0430\u0440 \u0430\u043d\u0434\u0430\u0440\u043e\u0440\u0430\u043d\u0434 \u0433\u0430\u0440\u0434\xbb.\n\u0417\u0438 \u0444\u0438\u0442\u0440\u043e\u043a\n80\n\u0431\u0438\u043a\u0448\u043e\u0434 \u043f\u0435\u0447\u043e\u043d \u043a\u0430\u043c\u0430\u043d\u0434,\n\u0411\u0438\u044f\u043d\u0434\u043e\u0445\u0442, \u043e\u043c\u0430\u0434 \u043c\u0438\u0451\u043d\u0430\u0448 \u0431\u0430 \u0431\u0430\u043d\u0434.\n\u0411\u0430\u0434-\u04ef \u0433\u0443\u0444\u0442, \u043a - \xab\u0410\u0437 \u043c\u0430\u043d \u0440\u0430\u04b3\u043e\u04e3 \u043c\u0430\u04b7\u04ef\u0439!\n\u0427\u0430\u0440\u043e \u04b7\u0430\u043d\u0433 \u04b7\u04ef\u04e3 \u0442\u0443, \u0430\u0439 \u043c\u043e\u04b3\u0440\u04ef\u0439!\n\u041d\u0430\u0451\u043c\u0430\u0434 \u0431\u0430 \u0434\u043e\u043c\u0430\u043c \u0431\u0430 \u0441\u043e\u043d\u0438 \u0442\u0443 \u0433\u04ef\u0440,\n\u0417\u0438 \u0447\u0430\u043d\u0433\u0430\u043c \u0440\u0430\u04b3\u043e\u04e3 \u043d\u0430\u0451\u0431\u04e3, \u043c\u0430\u0448\u04ef\u0440!\xbb\n\u041a\u0443\u0448\u043e\u0434\u0430\u0448 \u0440\u0443\u0445 \u043e\u043d \u0433\u043e\u04b3 \u0413\u0443\u0440\u0434\u043e\u0444\u0430\u0440\u0438\u0434,\n\u041c\u0430\u0440 \u043e\u043d\u0440\u043e \u04b7\u0443\u0437 \u0438\u043d \u04b3\u0435\u04b7 \u0447\u043e\u0440\u0430 \u043d\u0430\u0434\u0438\u0434.\n\u0411\u0430\u0434-\u04ef \u0440\u04ef\u0439 \u0431\u0438\u043d\u043c\u0443\u0434\u0443 \u0433\u0443\u0444\u0442: \xab\u0410\u0439 \u0434\u0430\u043b\u0435\u0440,\n\u041c\u0438\u0451\u043d\u0438 \u0434\u0430\u043b\u0435\u0440\u043e\u043d \u0431\u0430 \u043a\u0438\u0440\u0434\u043e\u0440\u0438 \u0448\u0435\u0440,\n\u0414\u0443 \u043b\u0430\u0448\u043a\u0430\u0440 \u043d\u0430\u0437\u043e\u0440\u0430 \u0431\u0430\u0440 \u0438\u043d \u04b7\u0430\u043d\u0433\u0438 \u043c\u043e,\n\u0411\u0430\u0434-\u0438\u043d \u0433\u0443\u0440\u0437\u0443 \u0448\u0430\u043c\u0448\u0435\u0440\u0443 \u043e\u04b3\u0430\u043d\u0433\u0438 \u043c\u043e.\n\u041a\u0443\u043d\u0443\u043d \u043c\u0430\u043d \u043a\u0443\u0448\u043e\u0434\u0430 \u0447\u0443\u043d\u0438\u043d \u0440\u04ef\u044e \u043c\u04ef\u0439,\n\u0421\u0438\u043f\u043e\u04b3 \u0430\u0437 \u0442\u0443 \u0433\u0430\u0440\u0434\u0430\u0434 \u043f\u0443\u0440 \u0430\u0437 \u0433\u0443\u0444\u0442\u0443\u0433\u04ef\u0439,\n\u041a\u0438 \u0431\u043e \u0434\u0443\u0445\u0442\u0430\u0440\u0435 \u04ef \u0431\u0430 \u0434\u0430\u0448\u0442\u0438 \u043d\u0430\u0431\u0430\u0440\u0434\n\u0411\u0430\u0434-\u0438\u043d \u0441\u043e\u043d \u0431\u0430 \u0430\u0431\u0440 \u0430\u043d\u0434\u0430\u0440\u043e\u0432\u0430\u0440\u0434 \u0433\u0430\u0440\u0434.\n\u041d\u0430\u0431\u043e\u044f\u0434, \u043a\u0438 \u0447\u0430\u043d\u0434\u0438\u043d \u0434\u0438\u0440\u0430\u043d\u0433 \u043e\u0432\u0430\u0440\u0430\u0434,\n\u041a-\u0430\u0437 \u0438\u043d \u0440\u0430\u0437\u043c \u0431\u0430\u0440 \u0445\u0435\u0448 \u043d\u0430\u043d\u0433 \u043e\u0432\u0430\u0440\u0430\u0434.\n\u041d\u0438\u04b3\u043e\u043d\u04e3 \u0431\u0438\u0441\u043e\u0437\u0435\u043c, \u0431\u0435\u04b3\u0442\u0430\u0440 \u0431\u0443\u0432\u0430\u0434,\n\u0425\u0438\u0440\u0430\u0434 \u0434\u043e\u0448\u0442\u0430\u043d \u043a\u043e\u0440\u0438 \u043c\u0435\u04b3\u0442\u0430\u0440 \u0431\u0443\u0432\u0430\u0434.\n\n79\n\u043e\u0432\u0430\u0440\u0434 \u2013 \u04b7\u0430\u043d\u0433, \u0440\u0430\u0437\u043c.\n80\n\u0444\u0438\u0442\u0440\u043e\u043a \u2013 \u0442\u0430\u0441\u043c\u0430\u0438 \u0447\u0430\u0440\u043c\u0438\u043d, \u043a\u0438 \u0431\u0430\u0440\u043e\u0438 \u0431\u0430\u0441\u0442\u0430\u043d\u0438 \u0448\u0438\u043a\u043e\u0440 \u0432\u0430 \u0447\u0438\u0437\u04b3\u043e\u0438 \u0434\u0438\u0433\u0430\u0440 \u0430\u0437 \u0440\u043e\u0441\u0442\u0443\n\u0447\u0430\u043f \u0432\u0430 \u0451 \u0430\u0437 \u043f\u0430\u0441\u0443 \u043f\u0435\u0448\u0438 \u0437\u0438\u043d\u0438 \u0430\u0441\u043f \u043c\u0435\u043e\u0432\u0435\u0437\u0430\u043d\u0434.\n\n\n## 45 (Page 45)\n\n\u0417\u0438 \u0431\u0430\u04b3\u0440\u0438 \u043c\u0430\u043d \u043e\u04b3\u0443 \u0437\u0438 \u04b3\u0430\u0440 \u0441\u04ef \u043c\u0430\u0445\u043e\u04b3,\n\u041c\u0438\u0451\u043d\u0438 \u0434\u0443 \u0441\u0430\u0444 \u0431\u0430\u0440\u043a\u0430\u0448\u0438\u0434\u0430 \u0441\u0438\u043f\u043e\u04b3!\n\u041a\u0443\u043d\u0443\u043d \u043b\u0430\u0448\u043a\u0430\u0440\u0443 \u0434\u0438\u0436 \u0431\u0430 \u0444\u0430\u0440\u043c\u043e\u043d\u0438 \u0442\u0443\u0441\u0442,\n\u041d\u0430\u0431\u043e\u044f\u0434 \u0431\u0430\u0434-\u0438\u043d \u043e\u0448\u0442\u04e3 \u04b7\u0430\u043d\u0433 \u04b7\u0443\u0441\u0442.\n\u0414\u0438\u0436\u0443 \u0433\u0430\u043d\u04b7\u0443 \u0434\u0438\u0436\u0431\u043e\u043d \u0441\u0430\u0440\u043e\u0441\u0430\u0440 \u0442\u0443\u0440\u043e\u0441\u0442,\n\u0427\u0443 \u043e\u04e3 \u0447\u0443\u043d\u043e\u043d, \u043a-\u0430\u0442 \u043c\u0443\u0440\u043e\u0434\u0443 \u04b3\u0430\u0432\u043e\u0441\u0442\xbb.\n\u0427\u0443 \u0440\u0443\u0445\u0441\u043e\u0440 \u0431\u0438\u043d\u043c\u0443\u0434 \u0421\u0443\u04b3\u0440\u043e\u0431\u0440\u043e,\n\u0417\u0438 \u0445\u0443\u0448\u0448\u043e\u0431 \u0431\u0438\u043a\u0448\u0443\u0434 \u0443\u043d\u043d\u043e\u0431\u0440\u043e\n81\n.\n\u042f\u043a\u0435 \u0431\u04ef\u0441\u0442\u043e\u043d \u0431\u0443\u0434 \u0430\u043d\u0434\u0430\u0440 \u0431\u0438\u04b3\u0438\u0448\u0442,\n\u0411\u0430 \u0431\u043e\u043b\u043e\u0438 \u04ef \u0441\u0430\u0440\u0432 \u0434\u0435\u04b3\u049b\u043e\u043d \u043d\u0430\u043a\u0438\u0448\u0442.\n\u0414\u0443 \u0447\u0430\u0448\u043c\u0430\u0448 \u0433\u0430\u0432\u0430\u0437\u043d\u0443 \u0434\u0443 \u0430\u0431\u0440\u04ef \u043a\u0430\u043c\u043e\u043d,\n\u0422\u0443 \u0433\u0443\u0444\u0442\u04e3 \u04b3\u0430\u043c\u0435 \u0431\u0438\u0448\u043a\u0443\u0444\u0430\u0434 \u04b3\u0430\u0440 \u0437\u0430\u043c\u043e\u043d.\n\u0411\u0430\u0434-\u04ef \u0433\u0443\u0444\u0442: \xab3-\u0438\u043d \u0433\u0443\u0444\u0442\u0430 \u0430\u043a\u043d\u0443\u043d \u043c\u0430\u0433\u0430\u0440\u0434,\n\u041a\u0438 \u0434\u0438\u0434\u04e3 \u043c\u0430\u0440\u043e \u0440\u04ef\u0437\u0433\u043e\u0440\u0438 \u043d\u0430\u0431\u0430\u0440\u0434.\n\u0411\u0430\u0434-\u043e\u043d \u0431\u043e\u0440\u0430\u0438 \u0434\u0438\u0436 \u0434\u0438\u043b \u0430\u043d\u0434\u0430\u0440\u043c\u0430\u0431\u0430\u043d\u0434,\n\u041a\u0438 \u043e\u043d \u043d\u0435\u0441\u0442 \u0431\u0430\u0440\u0442\u0430\u0440 \u0437\u0438 \u0447\u0430\u0440\u0445\u0438 \u0431\u0430\u043b\u0430\u043d\u0434.\n\u0411\u0430 \u043f\u043e\u0439 \u043e\u0432\u0430\u0440\u0430\u0434 \u0437\u0430\u0445\u043c\u0438 \u043a\u04ef\u043f\u043e\u043b\u0438 \u043c\u0430\u043d,\n\u041d\u0430\u0440\u043e\u043d\u0430\u0434 \u043a\u0430\u0441\u0435 \u043d\u0430\u0439\u0437\u0430 \u0431\u0430\u0440 \u0451\u043b\u0438 \u043c\u0430\u043d\xbb.\n\u0418\u043d\u043e\u043d\u0440\u043e \u0431\u0438\u043f\u0435\u0447\u0438\u0434 \u0413\u0443\u0440\u0434\u043e\u0444\u0430\u0440\u0438\u0434,\n\u0421\u0430\u043c\u0430\u043d\u0434\u0438 \u0441\u0430\u0440\u0430\u0444\u0440\u043e\u0437 \u0431\u0430\u0440 \u0434\u0438\u0436 \u043a\u0430\u0448\u0438\u0434.\n\u04b2\u0430\u043c\u0435\u0440\u0430\u0444\u0442 \u0421\u0443\u04b3\u0440\u043e\u0431 \u0431\u043e \u04ef \u0431\u0430 \u04b3\u0430\u043c,\n\u0411\u0438\u0451\u043c\u0430\u0434 \u0431\u0430 \u0434\u0430\u0440\u0433\u043e\u04b3\u0438 \u0434\u0438\u0436 \u0413\u0430\u0436\u0434\u0430\u04b3\u0430\u043c.\n\u0414\u0430\u0440\u0438 \u0434\u0438\u0436 \u043a\u0443\u0448\u043e\u0434\u0430\u043d\u0434\u0443 \u0413\u0443\u0440\u0434\u043e\u0444\u0430\u0440\u0438\u0434\n\u0422\u0430\u043d\u0438 \u0431\u0430\u0441\u0442\u0430\u0432\u0443 \u0445\u0430\u0441\u0442\u0430 \u0431\u0430\u0440 \u0434\u0438\u0436 \u043a\u0430\u0448\u0438\u0434.\n\u0414\u0430\u0440\u0438 \u0434\u0438\u0436 \u0431\u0438\u0431\u0430\u0441\u0442\u0430\u043d\u0434\u0443 \u0493\u0430\u043c\u0433\u0438\u043d \u0448\u0443\u0434\u0430\u043d\u0434,\n\u041f\u0443\u0440 \u0430\u0437 \u0493\u0430\u043c \u0434\u0438\u043b\u0443 \u0434\u0438\u0434\u0430 \u0445\u0443\u043d\u0438\u043d \u0448\u0443\u0434\u0430\u043d\u0434.\n\u0410\u0437 \u043e\u0437\u043e\u0440\u0438 \u0413\u0443\u0440\u0434\u043e\u0444\u0430\u0440\u0438\u0434\u0443 \u04b2\u0430\u04b7\u0438\u0440\n\u041f\u0443\u0440 \u0430\u0437 \u0434\u0430\u0440\u0434 \u0431\u0443\u0434\u0430\u043d\u0434 \u0431\u0430\u0440\u043d\u043e\u0432\u0443 \u043f\u0438\u0440.\n\u0411\u0438\u0433\u0443\u0444\u0442\u0430\u0448, \u043a\u0438 \xab\u0410\u0439 \u043d\u0435\u043a\u0434\u0438\u043b, \u0448\u0435\u0440\u0437\u0430\u043d!\n\u041f\u0443\u0440 \u0430\u0437 \u0493\u0430\u043c \u0431\u0443\u0434 \u0430\u0437 \u0442\u0443 \u0434\u0438\u043b\u0438 \u0430\u043d\u04b7\u0443\u043c\u0430\u043d,\n\u041a\u0438 \u04b3\u0430\u0440 \u0440\u0430\u0437\u043c \u04b7\u0443\u0441\u0442\u04e3, \u04b3\u0430\u043c \u0430\u0444\u0441\u0443\u043d\u0443 \u0440\u0430\u043d\u0433,\n\u041d\u0430\u0451\u043c\u0430\u0434 \u0437\u0438 \u043a\u043e\u0440\u0438 \u0442\u0443 \u0431\u0430\u0440 \u0434\u0443\u0434\u0430\n82\n\u043d\u0430\u043d\u0433.\n\u0421\u0438\u043f\u043e\u0441 \u0430\u0437 \u0425\u0443\u0434\u043e\u0432\u0430\u043d\u0434\u0438 \u0447\u0430\u0440\u0445\u0438 \u0431\u0430\u043b\u0430\u043d\u0434,\n\u041a\u0438 \u043d-\u043e\u043c\u0430\u0434 \u0431\u0430 \u04b7\u043e\u043d\u0430\u0442 \u0437\u0438 \u0434\u0443\u0448\u043c\u0430\u043d \u0433\u0430\u0437\u0430\u043d\u0434\xbb.\n\u0411\u0438\u0445\u0430\u043d\u0434\u0438\u0434 \u0431\u0438\u0441\u0451\u0440 \u0413\u0443\u0440\u0434\u043e\u0444\u0430\u0440\u0438\u0434,\n\n81\n\u0443\u043d\u043d\u043e\u0431 \u2013 \u0447\u0435\u043b\u043e\u043d, \u043a\u0438\u043d\u043e\u044f \u0430\u0437 \u043b\u0430\u0431\u0438 \u0441\u0443\u0440\u0445.\n82\n\u0434\u0443\u0434\u0430 \u2013 \u0442\u0430\u0431\u043e\u0440.\n\n\n## 46 (Page 46)\n\n\u0411\u0430 \u0431\u043e\u0440\u0430\n83\n\u0431\u0430\u0440\u043e\u043c\u0430\u0434, \u0441\u0438\u043f\u0430\u04b3 \u0431\u0438\u043d\u0433\u0430\u0440\u0438\u0434.\n\u0427\u0443 \u0421\u0443\u04b3\u0440\u043e\u0431\u0440\u043e \u0434\u0438\u0434 \u0431\u0430\u0440 \u043f\u0443\u0448\u0442\u0438 \u0437\u0438\u043d,\n\u0427\u0443\u043d\u0438\u043d \u0433\u0443\u0444\u0442, \u043a- \xab\u0410\u0439 \u0433\u0443\u0440\u0434\u0438 \u0422\u0443\u0440\u043e\u043d\u0437\u0430\u043c\u0438\u043d!\n\u0427\u0430\u0440\u043e \u0440\u0430\u043d\u04b7\u0430 \u0433\u0430\u0448\u0442\u04e3 \u0447\u0443\u043d\u0438\u043d? \u0411\u043e\u0437\u0433\u0430\u0440\u0434,\n\u04b2\u0430\u043c \u0430\u0437 \u043e\u043c\u0430\u0434\u0430\u043d, \u04b3\u0430\u043c \u0437\u0438 \u0434\u0430\u0448\u0442\u0438 \u043d\u0430\u0431\u0430\u0440\u0434\xbb.\n\u0411\u0430\u0434-\u04ef \u0433\u0443\u0444\u0442 \u0421\u0443\u04b3\u0440\u043e\u0431, \u043a - \xab\u0410\u0439 \u0445\u0443\u0431\u0447\u0435\u04b3\u0440!\n\u0411\u0430 \u0442\u043e\u04b7\u0443 \u0431\u0430 \u0442\u0430\u0445\u0442\u0443 \u0431\u0430 \u043c\u043e\u04b3\u0443 \u0431\u0430 \u043c\u0435\u04b3\u0440,\n\u041a\u0438 \u0438\u043d \u0431\u043e\u0440\u0430 \u0431\u0430\u0440 \u0445\u043e\u043a \u043f\u0430\u0441\u0442 \u043e\u0432\u0430\u0440\u0430\u043c,\n\u0422\u0443\u0440\u043e, \u0430\u0439 \u0441\u0438\u0442\u0430\u043c\u0433\u0430\u0440, \u0431\u0430 \u0434\u0430\u0441\u0442 \u043e\u0432\u0430\u0440\u0430\u043c!\n\u0427\u0443 \u0431\u0435\u0447\u043e\u0440\u0430 \u0433\u0430\u0440\u0434\u0438\u044e \u043f\u0435\u0447\u043e\u043d \u0448\u0430\u0432\u04e3,\n\u0417\u0438 \u0433\u0443\u0444\u0442\u043e\u0440\u0438 \u04b3\u0430\u0440\u0437\u0430 \u043f\u0443\u0448\u0430\u0439\u043c\u043e\u043d \u0448\u0430\u0432\u04e3.\n\u041f\u0443\u0448\u0430\u0439\u043c\u043e\u043d\u04e3 \u043e\u043d \u0433\u0430\u04b3 \u043d\u0430\u0434\u043e\u0440\u0430\u0434-\u0442 \u0441\u0443\u0434,\n\u0427\u0443 \u0433\u0430\u0440\u0434\u0443\u043d\u0438 \u0433\u0430\u0440\u0434\u043e\u043d \u043a\u0443\u043b\u043e\u04b3\u0430\u0442 \u0440\u0430\u0431\u0443\u0434.\n\u041a\u0443\u04b7\u043e \u0440\u0430\u0444\u0442 \u043f\u0430\u0439\u043c\u043e\u043d, \u043a\u0438 \u043a\u0430\u0440\u0434\u04e3 \u043f\u0430\u0434\u0438\u0434?!\xbb\n\u0427\u0443 \u0431\u0438\u0448\u043d\u0438\u0434 \u0433\u0443\u0444\u0442\u043e\u0440 \u0413\u0443\u0440\u0434\u043e\u0444\u0430\u0440\u0438\u0434,\n\u0411\u0438\u0445\u0430\u043d\u0434\u0438\u0434\u0443 \u043e\u043d \u0433\u0430\u04b3 \u0431\u0430 \u0430\u0444\u0441\u0443\u043d \u0431\u0438\u0433\u0443\u0444\u0442,\n\u041a\u0438 \xab\u0422\u0443\u0440\u043a\u043e\u043d \u0437\u0438 \u042d\u0440\u043e\u043d \u043d\u0430\u0451\u0431\u0430\u043d\u0434 \u04b7\u0443\u0444\u0442.\n\u0427\u0443\u043d\u043e\u043d \u0440\u0430\u0444\u0442, \u0440\u04ef\u0437\u04e3 \u043d\u0430\u0431\u0443\u0434\u0430\u0442 \u0437\u0438 \u043c\u0430\u043d,\n\u0411\u0430\u0434-\u0438\u043d \u0434\u0430\u0440\u0434 \u0493\u0430\u043c\u0433\u0438\u043d \u043c\u0430\u043a\u0443\u043d \u0445\u0435\u0448\u0442\u0430\u043d!\n\u04b2\u0430\u043c\u043e\u043d\u043e, \u043a\u0438 \u0442\u0443 \u0445\u0443\u0434 \u0437\u0438 \u0442\u0443\u0440\u043a\u043e\u043d \u043d\u0430\u04e3,\n\u041a\u0438 \u04b7\u0443\u0437 \u0431-\u043e\u0444\u0430\u0440\u0438\u043d\u0438 \u0431\u0443\u0437\u0443\u0440\u0433\u043e\u043d \u043d\u0430\u04e3.\n\u0411\u0430\u0434-\u0438\u043d \u0437\u04ef\u0440\u0443 \u0438\u043d \u0431\u043e\u0437\u0443\u044e \u043a\u0438\u0442\u0444\u0443 \u0451\u043b\n\u041d\u0430\u0434\u043e\u0440\u04e3 \u043a\u0430\u0441 \u0430\u0437 \u043f\u0430\u04b3\u043b\u0430\u0432\u043e\u043d\u043e\u043d \u04b3\u0430\u043c\u043e\u043b.\n\u0412\u0430\u043b\u0435\u043a\u0438\u043d \u0447\u0443 \u043e\u0433\u043e\u04b3\u04e3 \u043e\u044f\u0434 \u0431\u0430 \u0448\u043e\u04b3,\n\u041a\u0438 \u043e\u0432\u0430\u0440\u0434 \u0433\u0443\u0440\u0434\u0435 \u0437\u0438 \u0422\u0443\u0440\u043e\u043d \u0441\u0438\u043f\u043e\u04b3,\n\u0428\u0430\u04b3\u0430\u043d\u0448\u043e\u04b3\u0443 \u0420\u0443\u0441\u0442\u0430\u043c \u0431\u0438\u04b7\u0443\u043d\u0431\u0430\u0434 \u0437\u0438 \u04b7\u043e\u0439,\n\u0428\u0443\u043c\u043e \u0431\u043e \u0422\u0430\u04b3\u0430\u043c\u0442\u0430\u043d \u043d\u0430\u0434\u043e\u0440\u0435\u0434 \u043f\u043e\u0439.\n\u041d\u0430\u043c\u043e\u043d\u0430\u0434 \u044f\u043a\u0435 \u0437\u0438\u043d\u0434\u0430 \u0430\u0437 \u043b\u0430\u0448\u043a\u0430\u0440\u0430\u0442,\n\u041d\u0430\u0434\u043e\u043d\u0430\u043c, \u0447\u04e3 \u043e\u044f\u0434 \u0437\u0438 \u0431\u0430\u0434 \u0431\u0430\u0440 \u0441\u0430\u0440\u0430\u0442.\n\u0414\u0430\u0440\u0435\u0493 \u043e\u044f\u0434\u0430\u043c, \u043a-\u0438\u043d\u0447\u0443\u043d\u0438\u043d \u0451\u043b\u0443 \u0441\u0443\u0444\u0442\n\u04b2\u0430\u043c\u0435 \u0430\u0437 \u043f\u0430\u043b\u0430\u043d\u0433\u043e\u043d \u0431\u0438\u0431\u043e\u044f\u0434 \u043d\u0443\u04b3\u0443\u0444\u0442...\n\u0422\u0443\u0440\u043e \u0431\u0435\u04b3\u0442\u0430\u0440 \u043e\u044f\u0434, \u043a\u0438 \u0444\u0430\u0440\u043c\u043e\u043d \u043a\u0443\u043d\u04e3,\n\u0420\u0443\u0445\u0438 \u043d\u043e\u043c\u0432\u0430\u0440 \u0441\u04ef\u0438 \u0422\u0443\u0440\u043e\u043d \u043a\u0443\u043d\u04e3\xbb.\n\u0427\u0443 \u0431\u0438\u0448\u043d\u0438\u0434 \u0421\u0443\u04b3\u0440\u043e\u0431, \u043d\u0430\u043d\u0433 \u043e\u043c\u0430\u0434\u0430\u0448,\n\u041a\u0438 \u043e\u0441\u043e\u043d \u04b3\u0430\u043c\u0435 \u0434\u0438\u0436 \u0431\u0430 \u0447\u0430\u043d\u0433 \u043e\u043c\u0430\u0434\u0430\u0448.\n\n83\n\u0431\u043e\u0440\u0430 \u2013 \u049b\u0430\u043b\u044a\u0430.\n\n\n## 47 (Page 47)\n\n\u0411\u0430 \u0437\u0435\u0440\u0438 \u0434\u0438\u0436-\u0430\u043d\u0434\u0430\u0440 \u044f\u043a\u0435 \u04b7\u043e\u0439 \u0431\u0443\u0434,\n\u041a\u0443\u04b7\u043e \u0434\u0438\u0436 \u0431\u0430\u0434-\u043e\u043d \u04b7\u043e\u0439 \u0431\u0430\u0440\u043f\u043e\u0439 \u0431\u0443\u0434.\n\u0411\u0430 \u0442\u043e\u0440\u043e\u04b7 \u0434\u043e\u0434 \u043e\u043d \u04b3\u0430\u043c\u0430 \u0431\u0443\u043c\u0443 \u0440\u0443\u0441\u0442,\n\u0411\u0430 \u044f\u043a\u0431\u043e\u0440\u0430\u0433\u04e3 \u0434\u0430\u0441\u0442\u0438 \u0431\u0430\u0434\u0440\u043e \u0431\u0438\u0448\u0443\u0441\u0442.\n\u0427\u0443\u043d\u0438\u043d \u0433\u0443\u0444\u0442, \u043a- \xab\u0418\u043c\u0440\u04ef\u0437 \u0431\u0435\u0433\u043e\u04b3 \u0433\u0430\u0448\u0442,\n\u0417\u0438 \u043f\u0430\u0439\u043a\u043e\u0440\u0438 \u043c\u043e \u0434\u0430\u0441\u0442 \u043a\u04ef\u0442\u043e\u04b3 \u0433\u0430\u0448\u0442.\n\u0411\u0430\u0440\u043e\u0440\u0435\u043c \u0448\u0430\u0431\u0433\u0438\u0440 \u0430\u0437 \u0438\u043d \u0431\u043e\u0440\u0430 \u0433\u0430\u0440\u0434,\n\u041d\u0438\u04b3\u0435\u043c \u0430\u043d\u0434\u0430\u0440 \u0438\u043d \u04b7\u043e\u0439 \u0448\u04ef\u0440\u0438 \u043d\u0430\u0431\u0430\u0440\u0434\xbb.\n\u0427\u0443 \u0433\u0443\u0444\u0442 \u0438\u043d, \u0438\u043d\u043e\u043d\u0440\u043e \u0431\u0438\u0442\u043e\u0431\u0438\u0434\u0443 \u0440\u0430\u0444\u0442,\n\u0421\u0443\u0438 \u04b7\u043e\u0438 \u0445\u0443\u0434 \u0440\u043e\u04b3\u0440\u043e \u0431\u0430\u0440\u0433\u0438\u0440\u0438\u0444\u0442.")
B.aeN=new A.a("2f6a8092-8821-462f-af5c-ecd573853cd0","b5252e27-e6c6-401e-aca9-5fec3da36b65","\u0410\u0433\u0430\u0440 \u0434\u0443 \u0431\u0430\u0440\u043e\u0434\u0430\u0440 \u043d\u0438\u04b3\u0430\u0434 \u043f\u0443\u0448\u0442- \u043f\u0443...","\u0410\u0433\u0430\u0440 \u0434\u0443 \u0431\u0430\u0440\u043e\u0434\u0430\u0440 \u043d\u0438\u04b3\u0430\u0434 \u043f\u0443\u0448\u0442- \u043f\u0443\u0448\u0442,\n\u0422\u0430\u043d\u0438 \u043a\u04ef\u04b3\u0440\u043e \u0445\u043e\u043a \u043c\u043e\u043b\u0430\u0434 \u0431\u0430 \u043c\u0443\u0448\u0442.\n***\n\u0411\u0443\u0437\u0443\u0440\u0433\u04e3 \u0441\u0430\u0440\u043e\u0441\u0430\u0440 \u0431\u0430 \u0433\u0443\u0444\u0442\u043e\u0440 \u043d\u0435\u0441\u0442,\n\u0414\u0443\u0441\u0430\u0434 \u0433\u0443\u0444\u0442\u0430 \u0447\u0443\u043d \u043d\u0438\u043c\u0438 \u043a\u0438\u0440\u0434\u043e\u0440 \u043d\u0435\u0441\u0442.\n***\n\u0427\u0443 \u043d\u0435\u043a\u04e3 \u043a\u0443\u043d\u0430\u0434 \u043a\u0430\u0441, \u0442\u0443 \u043f\u043e\u0434\u043e\u0448 \u043a\u0443\u043d\n\u0412-\u0430\u0433\u0430\u0440 \u0431\u0430\u0434 \u043a\u0443\u043d\u0430\u0434, \u043d\u0438\u0437 \u043f\u0430\u0440\u0445\u043e\u0448 \u043a\u0443\u043d.\n\n\n## 48 (Page 48)\n\n***\n\u0411\u0430 \u0440\u0430\u043d\u04b7-\u0430\u043d\u0434\u0430\u0440 \u0430\u0441\u0442, \u0430\u0439 \u0445\u0438\u0440\u0430\u0434\u043c\u0430\u043d\u0434, \u0433\u0430\u043d\u04b7,\n\u041d\u0430\u0451\u0431\u0430\u0434 \u043a\u0430\u0441\u0435 \u0433\u0430\u043d\u04b7, \u043d\u043e\u0431\u0443\u0440\u0434\u0430 \u0440\u0430\u043d\u04b7.\n***\n\u04b6\u0430\u0432\u043e\u043d\u043c\u0430\u0440\u0434\u0438\u044e \u0440\u043e\u0441\u0442\u04e3 \u043f\u0435\u0448\u0430 \u043a\u0443\u043d,\n\u04b2\u0430\u043c\u0430 \u043d\u0435\u043a\u0443\u04e3 \u0430\u043d\u0434\u0430\u0440 \u0430\u043d\u0434\u0435\u0448\u0430 \u043a\u0443\u043d.\n\u0411\u0438\u0431\u0430\u0445\u0448\u0443 \u0431\u0438\u0445\u0443\u0440, \u0442\u043e \u0442\u0430\u0432\u043e\u043d\u04e3, \u0434\u0438\u0440\u0430\u043c,\n\u041a\u0438 \u04b7\u0443\u0437 \u0438\u043d \u0434\u0438\u0433\u0430\u0440 \u04b7\u0443\u043c\u043b\u0430 \u0434\u0430\u0440\u0434 \u0430\u0441\u0442\u0443 \u0493\u0430\u043c.\n***\n\u0411\u0430 \u04b3\u0430\u0440 \u043a\u043e\u0440 - \u0434\u0430\u0440 \u043f\u0435\u0448\u0430 \u043a\u0443\u043d \u0440\u043e\u0441\u0442\u04e3,\n\u0427\u0443 \u0445\u043e\u04b3\u04e3, \u043a\u0438 \u043d\u0430\u0433\u0437\u043e\u044f\u0434\u0430\u0442 \u043a\u043e\u0441\u0442\u04e3.\n\u041c\u0430\u043a\u0443\u043d \u0434\u04ef\u0441\u0442\u04e3 \u0431\u043e \u0434\u0443\u0440\u04ef\u0493\u043e\u0437\u043c\u043e\u0439,\n\u04b2\u0430\u043c\u043e\u043d \u043d\u0438\u0437 \u0431\u043e \u043c\u0430\u0440\u0434\u0438 \u043d\u043e\u043f\u043e\u043a\u0440\u043e\u0439.\n***\n\u0417\u0438 \u0433\u0435\u0442\u04e3 \u0434\u0443 \u0447\u0438\u0437 \u0430\u0441\u0442 \u04b7\u043e\u0432\u0438\u0434\u0443 \u0431\u0430\u0441,\n\u0414\u0438\u0433\u0430\u0440 \u04b3\u0430\u0440 \u0447\u04e3 \u0431\u043e\u0448\u0430\u0434, \u043d\u0430\u043c\u043e\u043d\u0430\u0434 \u0431\u0430 \u043a\u0430\u0441.\n\u0421\u0443\u0445\u0430\u043d \u0433\u0443\u0444\u0442\u0430\u043d\u0438 \u043d\u0430\u0493\u0437\u0443 \u043a\u0438\u0440\u0434\u043e\u0440\u0438 \u043d\u0435\u043a\n\u0411\u0438\u043c\u043e\u043d\u0430\u0434 \u0447\u0443\u043d\u043e\u043d, \u0442\u043e \u04b7\u0430\u04b3\u043e\u043d \u0430\u0441\u0442, \u0440\u0435\u043a\n84\n.\n\u04b2\u0430\u043c\u0430 \u0441\u0430\u0440 \u0431\u0430 \u0441\u0430\u0440 \u0442\u0430\u043d \u0431\u0430 \u043a\u0443\u0448\u0442\u0430\u043d \u0434\u0438\u04b3\u0435\u043c,\n\u0410\u0437 \u043e\u043d \u0431\u0435\u04b3 \u043a\u0438 \u043a\u0438\u0448\u0432\u0430\u0440 \u0431\u0430 \u0434\u0443\u0448\u043c\u0430\u043d \u0434\u0438\u04b3\u0435\u043c.\n***\n\u0411\u0430 \u0433\u0435\u0442\u04e3 \u043d\u0430\u043c\u043e\u043d\u0430\u0434 \u0431\u0430 \u04b7\u0443\u0437 \u043d\u043e\u043c\u0438 \u043d\u0435\u043a,\n\u04b2\u0430\u0440 \u043e\u043d \u043a\u0430\u0441, \u043a\u0438 \u0445\u043e\u04b3\u0430\u0434 \u0441\u0430\u0440\u0430\u043d\u04b7\u043e\u043c\u0438 \u043d\u0435\u043a.\n\u041a\u0430\u0441\u0435, \u043a-\u04ef \u04b7\u0430\u04b3\u043e\u043d\u0440\u043e \u0431\u0443\u0432\u0430\u0434 \u0445\u043e\u0441\u0442\u043e\u0440,\n\u0412\u0430\u0440\u043e \u0434\u043e\u043d\u0438\u0448 \u043e\u044f\u0434, \u043d\u0430 \u0433\u0430\u0432\u04b3\u0430\u0440 \u0431\u0430 \u043a\u043e\u0440.\n\u04b2\u0443\u043d\u0430\u0440\u043c\u0430\u043d\u0434\u0440\u043e \u0448\u043e\u0434\u0443 \u043d\u0430\u0437\u0434\u0438\u043a \u0434\u043e\u0440,\n\u04b6\u0430\u04b3\u043e\u043d \u0431\u0430\u0440 \u0431\u0430\u0434\u0430\u043d\u0434\u0435\u0448 \u0442\u043e\u0440\u0438\u043a \u0434\u043e\u0440,\n***\n\u0427\u0443 \u0434\u04e3\n85\n\u0440\u0430\u0444\u0442\u0443 \u0444\u0430\u0440\u0434\u043e \u043d\u0430\u0451\u044f\u0434 \u0431\u0430 \u043f\u0435\u0448,\n\u041c\u0430\u0434\u0435\u04b3 \u0445\u0438\u0440\u0430 \u0431\u0430\u0440 \u0431\u043e\u0434 \u0430\u0432\u049b\u043e\u0442\u0438\n86\n\u0445\u0435\u0448.\n***\n\u0425\u0438\u0440\u0430\u0434\u043c\u0430\u043d\u0434\u0438\u044e \u043f\u0435\u0448\u0431\u0438\u043d\u04e3 \u043a\u0443\u043d\u04e3,\n\u0422\u0430\u0432\u043e\u043d\u043e\u0438\u044e \u043f\u043e\u043a\u0434\u0438\u043d\u04e3 \u043a\u0443\u043d\u04e3.\n***\n\n84\n\u0440\u0435\u043a \u2013 \u043d\u0435\u043a\u0431\u0430\u0445\u0442, \u043d\u0435\u043a.\n85\n\u0434\u04e3 \u2013 \u0434\u0438\u0440\u04ef\u0437, \u0440\u04ef\u0437\u0438 \u0433\u0443\u0437\u0430\u0448\u0442\u0430.\n86\n\u0430\u0432\u049b\u043e\u0442 \u2013 \u04b7\u0430\u043c\u044a\u0438 \u0432\u0430\u049b\u0442, \u0432\u0430\u049b\u0442\u04b3\u043e.\n\n\n## 49 (Page 49)\n\n\u041c\u0430\u0440 \u043e\u043d\u0440\u043e, \u043a\u0438 \u0434\u043e\u043d\u0438\u0448 \u0431\u0443\u0432\u0430\u0434, \u0442\u04ef\u0448\u0430 \u0431\u0443\u0440\u0434,\n\u0411\u0438\u043c\u0438\u0440\u0430\u0434 \u0442\u0430\u043d\u0430\u0448, \u043d\u043e\u043c \u04b3\u0430\u0440\u0433\u0438\u0437 \u043d\u0430\u043c\u0443\u0440\u0434.\n***\n\u04b2\u0430\u043c\u0430 \u0441\u0430\u0440 \u0431\u0430 \u0441\u0430\u0440 \u0434\u0430\u0441\u0442\u0438 \u043d\u0435\u043a\u04e3 \u0431\u0430\u0440\u0435\u0434,\n\u04b6\u0430\u04b3\u043e\u043d\u0438 \u04b7\u0430\u04b3\u043e\u043d\u0440\u043e \u0431\u0430 \u0431\u0430\u0434 \u043c\u0430\u0441\u043f\u0430\u0440\u0435\u0434.\n\u0411\u0438\u043c\u043e\u043d\u0430\u0434 \u0434\u0443\u0442\u043e \u04b7\u043e\u0432\u0438\u0434\u043e\u043d \u044f\u043a \u0433\u0443\u04b3\u0430\u0440,\n\u04b2\u0443\u043d\u0430\u0440\u043c\u0430\u043d\u0434\u0438\u044e \u0434\u043e\u043d\u0438\u0448\u0443 \u0434\u043e\u0434\u0433\u0430\u0440.\n***\n\u041d\u0430\u0431\u043e\u0448\u0430\u0434 \u043a\u0430\u0441\u0435 \u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d \u043f\u043e\u0439\u0434\u043e\u0440,\n\u04b2\u0430\u043c\u0430 \u043d\u043e\u043c\u0438 \u043d\u0435\u043a\u04ef \u0431\u0443\u0432\u0430\u0434 \u0451\u0434\u0433\u043e\u0440.\n***\n\u0411\u0430 \u043d\u043e\u043f\u043e\u043a\u0437\u043e\u0434\u0430 \u043c\u0430\u0434\u043e\u0440\u0435\u0434 \u0443\u043c\u0435\u0434,\n\u041a\u0438 \u0437\u0430\u043d\u0433\u04e3 \u043d\u0430\u0433\u0430\u0440\u0434\u0430\u0434 \u0431\u0430 \u0448\u0443\u0441\u0442\u0430\u043d \u0441\u0430\u043f\u0435\u0434.\n\u0417\u0438 \u0431\u0430\u0434\u0430\u0441\u043b \u0447\u0430\u0448\u043c\u0438 \u0431\u0435\u04b3\u04e3 \u0434\u043e\u0448\u0442\u0430\u043d\n\u0411\u0443\u0432\u0430\u0434 \u0445\u043e\u043a \u0434\u0430\u0440 \u0434\u0438\u0434\u0430 \u0430\u043d\u0431\u043e\u0448\u0442\u0430\u043d.\n***\n\u041f\u0430\u0434\u0430\u0440 \u0447\u0443\u043d \u0431\u0430 \u0444\u0430\u0440\u0437\u0430\u043d\u0434 \u043c\u043e\u043d\u0430\u0434 \u04b7\u0430\u04b3\u043e\u043d,\n\u041a\u0443\u043d\u0430\u0434 \u043e\u0448\u043a\u043e\u0440\u043e \u0431\u0430\u0440 \u04ef-\u0431\u0430\u0440 \u043d\u0438\u04b3\u043e\u043d.\n\u0413\u0430\u0440 \u04ef \u0431\u0438\u0444\u043a\u0430\u043d\u0430\u0434 \u0444\u0430\u0440\u0440\u0443 \u043d\u043e\u043c\u0438 \u043f\u0430\u0434\u0430\u0440,\n\u0422\u0443 \u0431\u0435\u0433\u043e\u043d\u0430 \u0445\u043e\u043d\u0430\u0448, \u043c\u0430\u0445\u043e\u043d\u0430\u0448 \u043f\u0438\u0441\u0430\u0440.\n\u0422\u0443 \u0447\u0430\u043d\u0434\u043e\u043d \u043a\u0438 \u0431\u043e\u0448\u04e3, \u0441\u0443\u0445\u0430\u043d\u0433\u04ef\u0439 \u0431\u043e\u0448,\n\u0425\u0438\u0440\u0430\u0434\u043c\u0430\u043d\u0434 \u0431\u043e\u0448\u0443 \u04b7\u0430\u04b3\u043e\u043d\u04b7\u04ef\u0439 \u0431\u043e\u0448.\n\u041d\u0438\u0433\u0430\u0440, \u0442\u043e \u0447\u04e3 \u043a\u043e\u0440\u04e3, \u04b3\u0430\u043c\u043e\u043d \u0431\u0438\u0434\u0440\u0430\u0432\u04e3,\n\u0421\u0443\u0445\u0430\u043d \u04b3\u0430\u0440 \u0447\u04e3 \u0433\u04ef\u04e3, \u04b3\u0430\u043c\u043e\u043d \u0431\u0438\u0448\u043d\u0430\u0432\u04e3.\n***\n\u0425\u0438\u0440\u0430\u0434 \u043c\u043e\u044f\u0438 \u04b7\u043e\u0432\u0438\u0434\u043e\u043d\u04e3 \u0431\u0443\u0432\u0430\u0434,\n\u0425\u0438\u0440\u0430\u0434 \u043f\u043e\u044f\u0438 \u0437\u0438\u043d\u0434\u0430\u0433\u043e\u043d\u04e3 \u0431\u0443\u0432\u0430\u0434.\n\u041c\u0430\u0431\u043e\u0448\u0435\u0434 \u0433\u0443\u0441\u0442\u043e\u0445 \u0431\u043e \u0438\u043d \u04b7\u0430\u04b3\u043e\u043d,\n\u041a\u0438 \u04ef \u0442\u0438\u0440\u0430\u0433\u04e3 \u0434\u043e\u0440\u0430\u0434 \u0430\u043d\u0434\u0430\u0440 \u043d\u0438\u04b3\u043e\u043d.\n\u04b6\u0430\u04b3\u043e\u043d \u0451\u0434\u0433\u043e\u0440 \u0430\u0441\u0442\u0443 \u043c\u043e \u0440\u0430\u0444\u0442\u0430\u043d\u04e3,\n\u0411\u0430 \u043c\u0430\u0440\u0434\u0443\u043c \u043d\u0430\u043c\u043e\u043d\u0430\u0434 \u0431\u0430 \u04b7\u0443\u0437 \u043c\u0443\u0440\u0434\u0430\u043d\u04e3.\n***\n\u0411\u0430 \u0430\u043d\u0431\u0430\u0440\u0444\u0443\u0440\u04ef\u0448\u043e\u043d \u0430\u0433\u0430\u0440 \u0431\u0438\u0433\u0437\u0430\u0440\u04e3,\n\u0428\u0430\u0432\u0430\u0434 \u04b7\u043e\u043c\u0430\u0438 \u0442\u0443 \u04b3\u0430\u043c\u0430 \u0430\u043d\u0431\u0430\u0440\u04e3.\n\u0412-\u0430\u0433\u0430\u0440 \u0431\u0438\u0433\u0437\u0430\u0440\u04e3 \u0441\u04ef\u0438 \u0430\u043d\u0433\u0438\u0448\u0442\u0433\u0430\u0440,\n\u0410\u0437 \u04ef \u04b7\u0443\u0437 \u0441\u0438\u0451\u04b3\u04e3 \u043d\u0430\u0431\u0438\u043d\u04e3 \u0430\u0441\u0430\u0440.\n***\n\n\n## 50 (Page 50)\n\n\u0425\u0438\u0440\u0430\u0434\u043c\u0430\u043d\u0434 \u0431\u043e\u0448\u0443 \u0431\u0435\u043e\u0437\u043e\u0440 \u0431\u043e\u0448,\n\u04b2\u0430\u043c\u0435\u0448\u0430 \u0437\u0430\u0431\u043e\u043d\u0440\u043e \u043d\u0438\u0433\u0430\u04b3\u0434\u043e\u0440 \u0431\u043e\u0448.\n\u041d\u0438\u0451\u0433\u043e\u043d\u0438 \u043c\u043e \u043d\u043e\u043c\u0434\u043e\u0440\u043e\u043d \u0431\u0443\u0434\u0430\u043d\u0434,\n\u0411\u0430 \u0434\u0430\u04b3\u0440-\u0430\u043d\u0434\u0430\u0440\u0443\u043d \u0442\u043e\u04b7\u0434\u043e\u0440\u043e\u043d \u0431\u0443\u0434\u0430\u043d\u0434.\n\u041d\u0430\u0431\u0430\u0440\u0434\u043e\u0448\u0442\u0430\u043d\u0434 \u0430\u0437 \u043a\u0430\u0441\u0435 \u0441\u0430\u0440\u043a\u0430\u0448\u04e3\n\u0411\u0430 \u0442\u0435\u0437\u0438\u044e \u0442\u0443\u043d\u0434\u0438\u044e \u0431\u0435\u0434\u043e\u043d\u0438\u0448\u04e3.\n***\n\u041c\u0430\u0451\u0437\u043e\u0440 \u043c\u04ef\u0440\u0435, \u043a\u0438 \u0434\u043e\u043d\u0430\u043a\u0430\u0448 \u0430\u0441\u0442,\n\u041a\u0438 \u04b7\u043e\u043d \u0434\u043e\u0440\u0430\u0434\u0443 \u04b7\u043e\u043d\u0438 \u0448\u0438\u0440\u0438\u043d \u0445(\u0432)\u0430\u0448 \u0430\u0441\u0442.\n***\n\u0427\u0443 \u043f\u0430\u0439\u043c\u043e\u043d\u0438 \u043e\u0437\u043e\u0434\u0430\u0433\u043e\u043d \u0431\u0438\u0448\u043a\u0430\u043d\u04e3,\n\u041d\u0438\u0448\u043e\u043d\u0438 \u0431\u0443\u0437\u0443\u0440\u0433\u04e3 \u0431\u0430 \u0445\u043e\u043a \u0430\u0444\u0433\u0430\u043d\u04e3.\n\u041d\u0430\u0434\u043e\u043d\u04e3, \u043a\u0438 \u043c\u0430\u0440\u0434\u043e\u043d\u0438 \u043f\u0430\u0439\u043c\u043e\u043d\u0448\u0438\u043a\u0430\u043d\n\u0421\u0438\u0442\u0443\u0434\u0430 \u043d\u0430\u0431\u043e\u0448\u0430\u043d\u0434 \u0434\u0430\u0440 \u0430\u043d\u04b7\u0443\u043c\u0430\u043d.\n***\n\u0411\u0438\u0451, \u0442\u043e \u04b7\u0430\u04b3\u043e\u043d\u0440\u043e \u0431\u0430 \u0431\u0430\u0434 \u043d\u0430\u0441\u043f\u0430\u0440\u0435\u043c,\n\u0411\u0430 \u043a\u04ef\u0448\u0438\u0448 \u04b3\u0430\u043c\u0430 \u0434\u0430\u0441\u0442\u0438 \u043d\u0435\u043a\u04e3 \u0431\u0430\u0440\u0435\u043c.\n\u041d\u0430\u0431\u043e\u0448\u0430\u0434 \u04b3\u0430\u043c\u0435 \u043d\u0435\u043a\u0443 \u0431\u0430\u0434 \u043f\u043e\u0439\u0434\u043e\u0440,\n\u04b2\u0430\u043c\u043e\u043d \u0431\u0435\u04b3, \u043a\u0438 \u043d\u0435\u043a\u04e3 \u0431\u0443\u0432\u0430\u0434 \u0451\u0434\u0433\u043e\u0440.")
