B.ail=new A.a("de539acd-29cf-480f-8053-44218bb92b8c","5633556b-df45-4cab-83dc-760016db1ef2","\u041c\u0443\u0440\u0493\u0438 \u0431\u0435\u0431\u043e\u043b\u0443\u043f\u0430\u0440\u0435 \u0434\u0438\u0434\u0430\u043c, \u0434\u0438\u043b\u0430\u043c ...","\u041c\u0443\u0440\u0493\u0438 \u0431\u0435\u0431\u043e\u043b\u0443\u043f\u0430\u0440\u0435 \u0434\u0438\u0434\u0430\u043c, \u0434\u0438\u043b\u0430\u043c \u043e\u043c\u0430\u0434 \u0431\u0430 \u0451\u0434,\n\u041d\u043e\u043b\u0430\u0438 \u04b7\u0443\u0493\u0437\u0435 \u0448\u0443\u043d\u0438\u0434\u0430\u043c, \u043c\u0430\u043d\u0437\u0438\u043b\u0430\u043c \u043e\u043c\u0430\u0434 \u0431\u0430 \u0451\u0434.\n\u0410\u0437 \u0444\u0438\u0440\u0435\u0431\u0443 \u0432\u0430\u044a\u0434\u0430\u04b3\u043e\u0438 \u04ef \u0448\u0443\u0434\u0430\u043c \u0440\u043e\u0437\u04e3 \u0431\u0430 \u043c\u0430\u0440\u0433,\n\u0428\u0430\u0431 \u04b3\u0430\u043c\u0430 \u0448\u0430\u0431 \u0434\u0430\u0441\u0442\u0443 \u0442\u0435\u0493\u0438 \u049b\u043e\u0442\u0438\u043b\u0430\u043c \u043e\u043c\u0430\u0434 \u0431\u0430 \u0451\u0434.\n\u0414\u0430\u0440 \u0442\u0430\u043b\u043e\u0448\u0438 \u0431\u0430\u04b3\u0440 \u0447\u0443\u043d \u0433\u0438\u0440\u0434\u043e\u0431 \u0441\u0430\u0440\u0433\u0430\u0440\u0434\u043e\u043d \u0448\u0443\u0434\u0430\u043c,\n\u04b2\u0430\u0441\u0440\u0430\u0442\u0438 \u043b\u0430\u0431\u04b3\u043e\u0438 \u0445\u0443\u0448\u043a\u0438 \u0441\u043e\u04b3\u0438\u043b\u0430\u043c \u043e\u043c\u0430\u0434 \u0431\u0430 \u0451\u0434.\n\u0421\u0430\u0440 \u043d\u0430\u0437\u0430\u0434 \u0430\u0437 \u043a\u0438\u0448\u0442\u0437\u043e\u0440\u0438 \u0443\u043c\u0440\u0438 \u043c\u0430\u043d \u0493\u0430\u0439\u0440 \u0430\u0437 \u0441\u0438\u043f\u0430\u043d\u0434,\n\u0421\u04ef\u0445\u0442\u0430\u043c, \u0447\u0443\u043d \u043c\u0430\u0437\u0440\u0430\u0438 \u0431\u0435\u04b3\u043e\u0441\u0438\u043b\u0430\u043c \u043e\u043c\u0430\u0434 \u0431\u0430 \u0451\u0434.\n\u0421\u0430\u0439\u0439\u0438\u0434\u043e, \u0434\u0438\u0434\u0430\u043c \u0431\u0430 \u0445\u043e\u043a \u0430\u0444\u0442\u043e\u0434\u0430 \u0431\u0430\u0440\u0433\u0438 \u043b\u043e\u043b\u0430\u0440\u043e,\n\u0422\u0435\u0493\u0438\u043d\u043e\u04b3\u0430\u049b\u0445\u0443\u0440\u0434\u0430 \u0441\u0430\u0439\u0434\u0438 \u0431\u0438\u0441\u043c\u0438\u043b\u0430\u043c \u043e\u043c\u0430\u0434 \u0431\u0430 \u0451\u0434.")
B.aks=new A.a("d5ccec68-bfda-4cea-be8a-f0d26d052032","5633556b-df45-4cab-83dc-760016db1ef2","\u041e\u043c\u0430\u0434 \u0431\u0430\u04b3\u043e\u0440\u0443 \u0441\u0430\u0439\u0440\u0438 \u0433\u0443\u043b\u0438\u0441\u0442\u043e\u043d \u0493\u0430\u043d...","\u041e\u043c\u0430\u0434 \u0431\u0430\u04b3\u043e\u0440\u0443 \u0441\u0430\u0439\u0440\u0438 \u0433\u0443\u043b\u0438\u0441\u0442\u043e\u043d \u0493\u0430\u043d\u0438\u043c\u0430\u0442 \u0430\u0441\u0442,\n\u0411\u0430\u0437\u043c\u0438 \u0432\u0438\u0441\u043e\u043b\u0438 \u0493\u0443\u043d\u0447\u0430\u0438 \u0445\u0430\u043d\u0434\u043e\u043d \u0493\u0430\u043d\u0438\u043c\u0430\u0442 \u0430\u0441\u0442.\n\u0411\u043e \u049b\u043e\u043c\u0430\u0442\u0438 \u0445\u0430\u043c\u0438\u0434\u0430 \u0440\u0430\u0432\u0430\u043c \u0441\u04ef\u0439\u0438 \u0431\u04ef\u0441\u0442\u043e\u043d,\n\u041d\u0430\u0437\u0437\u043e\u0440\u0430\u0438 \u0431\u0443\u043d\u0430\u0444\u0448\u0430\u0432\u0443 \u0440\u0430\u0439\u04b3\u043e\u043d \u0493\u0430\u043d\u0438\u043c\u0430\u0442 \u0430\u0441\u0442.\n\u0410\u0439 \u0431\u043e\u0493\u0431\u043e\u043d, \u0437\u0438 \u0431\u043e\u0493 \u0431\u0430 \u0431\u0435\u0440\u0443\u043d \u0447\u04e3 \u043c\u0435\u0440\u0430\u0432\u04e3?\n\u0411\u0443\u0434\u0430\u043d \u0431\u0430 \u043f\u043e\u0439\u0438 \u0441\u0430\u0440\u0432\u0438 \u0445\u0438\u0440\u043e\u043c\u043e\u043d \u0493\u0430\u043d\u0438\u043c\u0430\u0442 \u0430\u0441\u0442.\n\u0410\u0439 \u0493\u0443\u043d\u0447\u0430, \u0441\u0430\u0440 \u0437\u0438 \u04b7\u0430\u0439\u0431 \u0431\u0430 \u0434\u0435\u0432\u043e\u043d\u0430\u0433\u04e3 \u0431\u0430\u0440\u043e\u0440,\n\u042f\u043a\u0447\u0430\u043d\u0434 \u0440\u04ef\u0437 \u0447\u043e\u043a\u0438 \u0433\u0438\u0440\u0435\u0431\u043e\u043d \u0493\u0430\u043d\u0438\u043c\u0430\u0442 \u0430\u0441\u0442.\n\u041f\u0430\u04b3\u043b\u0443\u0438 \u0445\u0443\u0434 \u0437\u0438 \u0445\u043e\u043a\u0438 \u0447\u0430\u043c\u0430\u043d \u0431\u0430\u0440\u043d\u0430\u043c\u0435\u043a\u0430\u0448\u0430\u043c,\n\u0427\u0443\u043d \u0441\u043e\u044f \u0445\u043e\u0431\u0438 \u0437\u0435\u0440\u0438 \u0434\u0430\u0440\u0430\u0445\u0442\u043e\u043d \u0493\u0430\u043d\u0438\u043c\u0430\u0442 \u0430\u0441\u0442.\n\u0410\u0439 \u0421\u0430\u0439\u0439\u0438\u0434\u043e, \u0447\u0443 \u0431\u043e\u0434 \u0431\u0430 \u04b3\u0430\u0440 \u04b7\u043e\u043d\u0438\u0431\u0435 \u043c\u0430\u0440\u0430\u0432,\n\u0411\u0430\u0440 \u0433\u0438\u0440\u0434\u0438 \u0445\u0435\u0448 \u0433\u0430\u0440\u0434, \u043a\u0438 \u0434\u0430\u0432\u0440\u043e\u043d \u0493\u0430\u043d\u0438\u043c\u0430\u0442 \u0430\u0441\u0442.")
B.agI=new A.a("7afdba27-c461-4722-8558-f91e648d88b4","5633556b-df45-4cab-83dc-760016db1ef2","... \u041c\u0435\u0445\u043e\u04b3\u0430\u043c, \u0430\u0437 \u0432\u0443\u04b3\u0443\u0448 \u0437\u0430\u043c\u043e\u043d\u0435 \u0441...","... \u041c\u0435\u0445\u043e\u04b3\u0430\u043c, \u0430\u0437 \u0432\u0443\u04b3\u0443\u0448 \u0437\u0430\u043c\u043e\u043d\u0435 \u0441\u0443\u0445\u0430\u043d \u043a\u0443\u043d\u0430\u043c,\n\u0414\u0430\u0444\u044a\u0438 \u043c\u0430\u043b\u043e\u043b \u0442\u043e \u0448\u0430\u0432\u0430\u0434 \u0430\u0437 \u0442\u0430\u0431\u044a\u0438 \u043c\u0430\u0440\u0434\u0443\u043c\u043e\u043d,\n\u0420\u04ef\u0437\u0435 \u043c\u0430\u043d\u0438 \u0493\u0430\u0440\u0438\u0431 \u0434\u0430\u0440 \u0430\u0439\u0451\u043c\u0438 \u043d\u0430\u0432\u0431\u0430\u04b3\u043e\u0440\n\u0410\u0437 \u043a\u0443\u043d\u04b7\u0438 \u0445\u043e\u043d\u0430 \u04b7\u043e\u043d\u0438\u0431\u0438 \u0441\u0430\u04b3\u0440\u043e \u0448\u0443\u0434\u0430\u043c \u0440\u0430\u0432\u043e\u043d.\n\u0414\u0438\u0434\u0430\u043c, \u043d\u0438\u0448\u0430\u0441\u0442\u0430 \u0431\u0430\u0440 \u0434\u0430\u0440\u0438 \u0441\u04ef\u0440\u043e\u0445 \u043c\u0443\u0448\u0430\u043a\u0435,\n\u041c\u0435\u043a\u0430\u0440\u0434 \u0445\u0443\u0434 \u0431\u0430 \u0445\u0443\u0434 \u0441\u0438\u0444\u0430\u0442\u0438 \u0445\u0435\u0448\u0440\u043e \u0431\u0430\u0451\u043d...")
B.ady=new A.a("265c2ad3-e990-437d-9a2d-fbcb435ae7a7","a74ea72d-864f-4c25-b42e-95435794a42d","\u041f\u043e\u0440\u0447\u0430\u04b3\u043e \u0430\u0437 \u049b\u0438\u0441\u0441\u0430\u0438 \xab\u041e\u0434\u0430\u043c\u043e\u043d\u0438 \u049b\u0443\u04b3...","\u041f\u043e\u0440\u0447\u0430\u04b3\u043e \u0430\u0437 \u049b\u0438\u0441\u0441\u0430\u0438 \xab\u041e\u0434\u0430\u043c\u043e\u043d\u0438 \u049b\u0443\u04b3\u043d\u0430\xbb")
B.alH=new A.a("17b9fdcb-94e8-4804-8aff-da52893a4067","ea3b9aa8-b892-4128-88bc-07e7946bf584","\u049a\u0430\u0441\u0441\u043e\u0431\u0440\u043e \u0437\u0438 \u0445\u0443\u043d\u0438 \u043c\u0430\u043d\u0430\u0448 \u0442\u0435\u0493 \u0441\u0443\u0440...","\u049a\u0430\u0441\u0441\u043e\u0431\u0440\u043e \u0437\u0438 \u0445\u0443\u043d\u0438 \u043c\u0430\u043d\u0430\u0448 \u0442\u0435\u0493 \u0441\u0443\u0440\u0445\u0440\u04ef\u0441\u0442,\n\u0411\u043e\u0448\u0430\u0434 \u043a\u0430\u043d\u043e\u0440\u0430\u0430\u0448 \u0447\u0443 \u0445\u0438\u0451\u0431\u043e\u043d\u0438 \u0430\u0440\u0493\u0430\u0432\u043e\u043d.\n\u0421\u0438\u043c\u0438\u043d\u0431\u0430\u0440\u043e\u043d \u043a\u0430\u0431\u043e\u0431\u0438 \u0434\u0438\u043b\u0443 \u0433\u0443\u0440\u0434\u0430\u0438 \u043c\u0430\u043d\u0430\u043d\u0434,\n\u041f\u0430\u0439\u0432\u0430\u0441\u0442\u0430 \u0430\u0441\u0442 \u0440\u0430\u0432\u0493\u0430\u043d\u0438 \u043c\u0430\u043d \u0448\u0430\u044a\u043d\u0438 \u0434\u0435\u0433\u0434\u043e\u043d\xbb.\n\u0427\u0443\u043d \u0438\u043d \u043c\u0443\u0431\u043e\u04b3\u0438\u0441\u0430 \u0431\u0430 \u0431\u0438\u0451\u0431\u043e\u043d \u0444\u0430\u0441\u043e\u043d\u0430 \u0448\u0443\u0434,\n\u0425\u0443\u0434\u0440\u043e \u0440\u0430\u0441\u043e\u043d\u0434 \u0433\u0443\u0440\u0433 \u0431\u0430\u0434-\u044d\u0448\u043e\u043d \u0434\u0430\u0432\u043e\u043d-\u0434\u0430\u0432\u043e\u043d.\n\u0411\u0430\u0440 \u0433\u04ef\u0441\u0444\u0430\u043d\u0434 \u0433\u0443\u0444\u0442: - \xab\u0414\u0438\u043b\u0443 \u0433\u0443\u0440\u0434\u0430\u0438 \u0442\u0443 \u0447\u0438\u0441\u0442?\n\u0427\u0443\u043d \u0430\u0441\u0442, \u0440\u04ef\u0434\u0430\u04b3\u043e\u0438 \u0442\u0443 \u0440\u0435\u0437\u0430\u043c \u0431\u0430 \u044f\u043a \u0437\u0430\u043c\u043e\u043d?!\n\u0413\u043e\u04b3\u0435 \u0431\u0430 \u0437\u0435\u0440\u0438 \u043f\u0443\u0448\u0442\u0430 \u043d\u0438\u04b3\u043e\u043d \u0433\u0430\u0440\u0434\u04e3 \u0430\u0437 \u0433\u0430\u043b\u0430,\n\u0421\u043e\u0437\u0430\u0434 \u0431\u0430 \u0441\u043e\u04b3\u0438\u0431\u0438 \u0442\u0443 \u043c\u0430\u0440\u043e \u043a\u0443\u0448\u0442\u0430\u043d\u04e3 \u0448\u0443\u0431\u043e\u043d.\n\u0414\u043e\u0438\u043c \u0434\u0430\u04b3\u043e\u043d \u0431\u0430 \u0440\u0430\u0432\u0493\u0430\u043d\u0438 \u0442\u0443 \u0447\u0430\u0440\u0431 \u043c\u0435\u043a\u0443\u043d\u0430\u043c,\n\u0425\u0443\u0434 \u0433\u04ef, \u0431\u0430 \u043f\u0435\u0448\u0438 \u04b7\u0430\u043d\u0433\u0438 \u04b3\u0430\u0440\u0438\u0444\u043e\u043d \u0442\u0443\u0440\u043e \u0447\u04e3 \u0448\u043e\u043d?\n\u0410\u04b3\u0432\u043e\u043b\u0438 \u043c\u0430\u043d \u0447\u0443 \u0448\u0430\u043c\u044a \u0431\u0430 \u04b3\u0430\u0440 \u0431\u0430\u0437\u043c \u0440\u0430\u0432\u0448\u0430\u043d \u0430\u0441\u0442,\n\u0414\u0430\u0440 \u043f\u0435\u0448\u0438 \u0445\u0430\u043b\u049b \u043d\u0435\u0441\u0442 \u043c\u0430\u0440\u043e \u04b3\u043e\u04b7\u0430\u0442\u0438 \u0431\u0430\u0451\u043d.\n\u0414\u0430\u0440 \u0445\u043e\u0431\u0438 \u0445\u0435\u0448 \u04b3\u0430\u0440 \u043a\u04e3 \u0431\u0438\u0431\u0438\u043d\u0430\u0434 \u0448\u0430\u0431\u0435 \u043c\u0430\u0440\u043e,\n\u0413\u0430\u0440\u0434\u0430\u0434 \u0437\u0438 \u044e\u043c\u043d\u0438 \u043c\u0430\u043d \u04b3\u0430\u043c\u0430\u0438 \u0440\u04ef\u0437 \u0448\u043e\u0434\u043c\u043e\u043d.\n\u0413\u043e\u0432\u0438 \u0437\u0430\u043c\u0438\u043d \u0447\u0443 \u0434\u0430\u0440 \u043d\u0430\u0437\u0430\u0440\u0430\u043c \u04b7\u0438\u043b\u0432\u0430\u0433\u0430\u0440 \u0448\u0430\u0432\u0430\u0434,\n\u0421\u043e\u0437\u0430\u043c \u0431\u0430 \u044f\u043a \u0438\u0448\u043e\u0440\u0430 \u04b7\u0443\u0434\u043e \u0440\u043e\u043d\u0438 \u04ef \u0437\u0438 \u0440\u043e\u043d\xbb.\n\u0414\u0430\u0440 \u0433\u04ef\u0448\u0438 \u0433\u043e\u0432 \u0431\u043e\u0434 \u0440\u0430\u0441\u043e\u043d\u0438\u0434 \u0438\u043d \u0445\u0430\u0431\u0430\u0440,\n\u0424\u0430\u0440\u0451\u0434 \u043a\u0430\u0440\u0434\u0443 \u0433\u0443\u0444\u0442: - \xab\u0427\u04e3 \u0433\u0443\u0444\u0442\u04e3? \u0411\u0438\u0433\u04ef \u04b3\u0430\u043c\u043e\u043d!\n\u04b2\u0430\u0440 \u04b7\u043e \u043a\u0438 \u0434\u0438\u0434\u0430\u04e3 \u0442\u0443 \u043c\u0430\u0440\u043e, \u0433\u0430\u0448\u0442\u0430\u04e3 \u0434\u0443\u0448\u043e\u0445,\n\u0411\u043e\u0432\u0430\u0440 \u043d\u0430\u043c\u0435\u043a\u0443\u043d\u04e3, \u0431\u0438\u043a\u0443\u043d \u0438\u043c\u0440\u04ef\u0437 \u0438\u043c\u0442\u0438\u04b3\u043e\u043d.\n\u0413\u0443\u0440\u0433\u04e3, \u0432\u0430\u043b\u0435\u043a \u049b\u0430\u0442\u0440\u0430\u0438 \u0431\u043e\u0440\u043e\u043d \u043d\u0430\u0434\u0438\u0434\u0430\u04e3,\n\u041d\u0430\u0448\u043d\u0438\u0434\u0430\u0430\u0441\u0442 \u0433\u04ef\u0448\u0438 \u0442\u0443 \u043e\u0432\u043e\u0437\u0430\u0438 \u0441\u0430\u0433\u043e\u043d.\n\u0413\u0430\u04b3 \u0441\u0443\u043b\u04b3 \u043c\u0435\u043a\u0443\u043d\u04e3 \u0442\u0443 \u0431\u0430 \u0447\u04ef\u043f\u043e\u043d\u0443 \u0433\u043e\u04b3 \u04b7\u0430\u043d\u0433,\n\u0413\u0443\u0440\u0433\u043e\u0448\u0442\u0438\u0441\u0442 \u043a\u043e\u0440\u0438 \u0442\u0443 \u043f\u0430\u0439\u0432\u0430\u0441\u0442\u0430 \u0431\u043e \u0448\u0443\u0431\u043e\u043d.\n\u0428\u0430\u0431 \u0442\u043e \u0431\u0430 \u0440\u04ef\u0437 \u0434\u04ef\u0445\u0442\u0430\u0430\u043c \u0447\u0430\u0448\u043c \u0431\u0430\u0440 \u0437\u0430\u043c\u0438\u043d,\n\u0410\u0437 \u043c\u0430\u043d \u043d\u0430\u0433\u0430\u0448\u0442\u0430 \u04b3\u0435\u04b7 \u043a\u0430\u0441 \u043e\u0437\u0443\u0440\u0434\u0430 \u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d.\n\u0413\u043e\u04b3\u0435 \u0431\u0430 \u0433\u0438\u0440\u0434\u0438 \u0445\u0438\u0440\u043c\u0430\u043d\u0438 \u0434\u0435\u04b3\u049b\u043e\u043d \u0448\u0430\u0432\u0430\u043c \u0431\u0430 \u0447\u0430\u0440\u0445,\n\u0413\u043e\u04b3\u0435 \u0431\u0430 \u0445\u0430\u043b\u049b \u0448\u0438\u0440 \u0434\u0438\u04b3\u0430\u043c \u04b3\u0430\u043c\u0447\u0443 \u043c\u043e\u0434\u0430\u0440\u043e\u043d.\n\u0410\u04b7\u0434\u043e\u0434\u0438 \u043c\u0430\u043d \u0431\u0430 \u041e\u0434\u0430\u043c\u0443 \u04b2\u0430\u0432\u0432\u043e \u0431\u0430\u0440\u043e\u0431\u0430\u0440 \u0430\u0441\u0442,\n\u042f\u044a\u043d\u0435, \u043c\u0430\u0440\u043e\u0441\u0442 \u0433\u043e\u0432\u0438 \u0437\u0430\u043c\u0438\u043d \u0430\u0437 \u0431\u0430\u0440\u043e\u0434\u0430\u0440\u043e\u043d\xbb.\n\u0423\u0448\u0442\u0443\u0440 \u0448\u0443\u043d\u0438\u0434\u0443 \u0433\u0443\u0444\u0442, \u043a\u0438: - \xab\u0413\u04ef\u0441\u043e\u043b\u0430\u04e3 \u04b3\u0430\u043d\u04ef\u0437,\n\u0411\u0435\u0440\u0443\u043d \u043d\u0430\u043a\u0430\u0440\u0434\u0430\u04e3 \u0441\u0430\u0440\u0438 \u0445\u0443\u0434\u0440\u043e \u0437\u0438 \u043a\u043e\u04b3\u0434\u043e\u043d.\n\u041e\u0431\u043e\u0438 \u0442\u0443 \u0431\u0430 \u04b3\u0435\u04b7 \u049b\u0430\u0442\u043e\u0440\u0435 \u043d\u0430\u0431\u0443\u0434\u0430\u0430\u043d\u0434,\n\u041e\u0432\u0430\u0440\u0434\u0430\u04e3 \u0431\u0430 \u0437\u04ef\u0440 \u0442\u0443 \u0445\u0443\u0434\u0440\u043e \u0434\u0430\u0440 \u0438\u043d \u043c\u0438\u0451\u043d.\n\u042f\u043a \u0440\u0430\u04b3 \u0431\u0430 \u043f\u0443\u0448\u0442\u0443 \u043f\u0430\u04b3\u043b\u0443\u0438 \u0445\u0443\u0434 \u04b3\u0430\u043c \u043d\u0438\u0433\u043e\u04b3 \u043a\u0443\u043d,\n\u0410\u0437 \u0445\u043e\u0442\u0438\u0440\u0438 \u0442\u0443 \u0440\u0430\u0444\u0442\u0430 \u043c\u0430\u0433\u0430\u0440 \u0447\u04ef\u0431\u0438 \u0433\u043e\u0432\u0440\u043e\u043d?\n\u0411\u0430\u0440 \u0433\u0430\u0440\u0434\u0430\u043d\u0430\u0442 \u0437\u0430\u043d\u0430\u043d\u0434 \u0447\u0443 \u0434\u0443\u0437\u0434 \u0430\u0439\u0440\u0438\u0438 \u0434\u0443\u0448\u043e\u0445,\n\u0410\u0437 \u043a\u043e\u04b3\u0434\u043e\u043d \u0431\u0430\u0440\u0430\u043d\u0434 \u0441\u0443\u0439\u0438 \u0434\u0430\u0448\u0442 \u043a\u0430\u0448-\u043a\u0430\u0448\u043e\u043d...\n\u041f\u0430\u0439\u0432\u0430\u0441\u0442\u0430 \u0445\u043e\u0440 \u043c\u0435\u0445\u0443\u0440\u0430\u043c\u0443 \u0431\u043e\u0440 \u043c\u0435\u043a\u0430\u0448\u0430\u043c,\n\u04b2\u0430\u0440\u0433\u0438\u0437 \u043d\u0430\u0433\u0430\u0448\u0442\u0430 \u0445\u043e\u0442\u0438\u0440\u0430\u043c \u0430\u0437 \u0441\u043e\u0440\u0431\u043e\u043d \u0433\u0430\u0440\u043e\u043d.\n\u04b2\u0430\u0440 \u04b7\u043e  \u043a\u0438 \u0431\u0443\u0434\u0430\u0430\u043c, \u0431\u0430 \u0434\u0443 \u0437\u043e\u043d\u0443 \u043d\u0438\u0448\u0430\u0441\u0442\u0430\u0430\u043c,\n\u0414\u0430\u0440 \u0431\u0430\u0440 \u043a\u0430\u0448\u0438\u0434\u0430 \u04b7\u043e\u043c\u0430\u0438 \u043c\u0430\u043b\u043b\u0430 \u0447\u0443 \u0441\u04ef\u0444\u0438\u0451\u043d\xbb.\n\u041e\u0432\u043e\u0437\u0438 \u0433\u0438\u0440\u0443\u0434\u043e\u0440\u0438 \u0448\u0443\u0442\u0443\u0440 \u0447\u0443\u043d \u0431\u0430\u043b\u0430\u043d\u0434 \u0448\u0443\u0434,\n\u0414\u0430\u0440\u04b3\u043e\u043b \u0441\u0430\u043d\u0433\u043f\u0443\u0448\u0442 \u0431\u0438\u0451\u043c\u0430\u0434 \u0442\u0430\u043f\u043e\u043d-\u0442\u0430\u043f\u043e\u043d.\n\u0414\u0430\u0440 \u043f\u0443\u0448\u0442 \u0447\u043e\u0440 \u043e\u0438\u043d\u0430, \u0434\u0430\u0440 \u043f\u0435\u0448\u0438 \u0440\u04ef \u0441\u0438\u043f\u0430\u0440,\n\u0411\u0430\u0440 \u0434\u0430\u0441\u0442 \u0441\u0430\u043d\u0433, \u0431\u0430\u0440\u0437\u0430\u0434\u0430 \u0434\u043e\u043c\u0430\u043d \u0447\u0443 \u04b7\u0443\u043c\u0440\u0438\u0451\u043d.\n\u0410\u0437 \u0441\u0430\u043d\u0433 \u0440\u0430\u0444\u0442\u0430 - \u0440\u0430\u0444\u0442\u0430 \u0447\u0443 \u043e\u0442\u0430\u0448 \u0437\u0430\u0431\u043e\u043d\u0430 \u0437\u0430\u0434,\n\u041e\u0493\u043e\u0437\u0438 \u0433\u0443\u0444\u0442\u0443\u0433\u04ef\u0439 \u0431\u0438\u0433\u0443\u0444\u0442: - \xab\u0410\u0439 \u0441\u0430\u0431\u0443\u043a\u044a\u0438\u043d\u043e\u043d!\n\u041a\u0443\u043d\u04b7\u043e\u0440\u0430 \u0434\u0438\u0434\u0430\u04e3 \u043c\u0430\u0433\u0430\u0440 \u0438\u043c\u0448\u0430\u0431 \u0431\u0430 \u0445\u043e\u0431\u0438 \u0445\u0435\u0448?\n\u0401 \u0433\u043e\u0432 \u0433\u0430\u0448\u0442\u0430\u04e3 \u0431\u0430 \u0445\u0430\u0451\u043b\u0438 \u04b7\u0443\u0432\u043e\u0437\u0440\u043e\u043d?\n\u0414\u0430\u0440 \u0443\u043c\u0440\u0438 \u0445\u0435\u0448 \u043c\u0438\u0441\u043b\u0438 \u0442\u0443 \u043b\u0443\u044a\u0431\u0430\u0442 \u043d\u0430\u0434\u0438\u0434\u0430\u0430\u043c,\n\u041a\u04ef\u0442\u043e\u04b3\u0430\u049b\u043b\u0443 \u043f\u043e\u0439\u0434\u0430\u0440\u043e\u0437\u0443 \u0448\u0438\u043a\u0430\u043c\u043a\u0430\u043b\u043e\u043d.\n\u0414\u0430\u0440 \u0437\u0435\u0440\u0438 \u0431\u043e\u0440 \u043d\u043e\u043b\u0430\u043a\u0443\u043d\u043e\u043d \u0445\u043e\u0431 \u043c\u0435\u0440\u0430\u0432\u04e3,\n\u0425\u0435\u0437\u04e3 \u0437\u0438 \u04b7\u043e\u0439 \u04b3\u0430\u043c\u0447\u0443 \u0437\u0430\u0438\u0444\u043e\u043d\u0438 \u043f\u043e\u0433\u0430\u0440\u043e\u043d.\n\u0414\u0430\u043d\u0434\u043e\u043d\u0438 \u0442\u0443 \u0441\u0430\u0440\u043e\u0441\u0430\u0440 \u0430\u0433\u0430\u0440 \u0431\u0438\u0448\u043a\u0430\u043d\u0430\u043c, \u0440\u0430\u0432\u043e\u0441\u0442,\n\u04b2\u0430\u0440\u0433\u0438\u0437 \u0442\u0443\u0440\u043e \u043a\u0430\u0441\u0435 \u043d\u0430\u0437\u0430\u0434\u0430 \u0441\u0430\u043d\u0433 \u0431\u0430\u0440 \u0434\u0430\u04b3\u043e\u043d.\n\u041c\u0430\u044a\u043b\u0443\u043c \u0448\u0443\u0434, \u0431\u0430 \u0434\u0430\u04b3\u0440 \u0448\u0443\u0442\u0443\u0440\u0434\u0438\u043b \u0442\u0443 \u0431\u0443\u0434\u0430\u04e3,\n\u0411\u043e\u0448\u0430\u0434 \u04b3\u0430\u043c\u0435\u0448\u0430 \u0447\u0430\u0448\u043c\u0438 \u0442\u0443 \u0431\u0430\u0440 \u0434\u0430\u0441\u0442\u0438 \u0441\u043e\u0440\u0431\u043e\u043d.\n\u0410\u0437 \u0444\u043e\u049b\u0430 \u0440\u04ef\u0437\u0443 \u0448\u0430\u0431 \u0431\u0430 \u0448\u0438\u043a\u0430\u043c \u0441\u0430\u043d\u0433 \u0431\u0430\u0441\u0442\u0430\u0430\u043c,\n\u0414\u043e\u043d\u0430\u043d\u0434 \u0445\u0430\u043b\u049b, \u0434\u0430\u0440 \u0431\u0430\u0493\u0430\u043b\u0430\u043c \u04b3\u0430\u0441\u0442 \u0442\u043e\u04b3\u0438 \u043d\u043e\u043d.\n\u0414\u0430\u0440 \u0433\u04ef\u0448\u0430\u0435 \u043d\u0438\u0448\u0430\u0441\u0442\u0430\u0430\u043c\u0443 \u0445\u043e\u043a \u043c\u0435\u0445\u0443\u0440\u0430\u043c,\n\u0411\u0438\u0433\u0437\u0430\u0448\u0442\u0430\u0430\u043c \u0431\u0430 \u0447\u0438\u043b\u043b\u0430\u043d\u0438\u0448\u0438\u043d\u04e3 \u0437\u0438 \u0437\u043e\u04b3\u0438\u0434\u043e\u043d.\n\u0420\u04ef\u0437\u0435, \u043a\u0438 \u043e\u0444\u0442\u043e\u0431 \u0431\u0430 \u0433\u0430\u0440\u043c\u04e3 \u0448\u0430\u0432\u0430\u0434 \u0430\u043b\u0430\u043c,\n\u041e\u043d \u0440\u04ef\u0437 \u044d\u04b3\u0442\u0438\u0451\u04b7 \u043d\u0430\u0434\u043e\u0440\u0430\u043c \u0431\u0430 \u0441\u043e\u044f\u0431\u043e\u043d\xbb.\n\u0411\u0430\u0440 \u0433\u04ef\u0448\u0438 \u0445\u043e\u0440\u043f\u0443\u0448\u0442 \u0447\u0443 \u0438\u043d \u043c\u043e\u04b7\u0430\u0440\u043e \u0440\u0430\u0441\u0438\u0434,\n\u04b2\u0430\u0440 \u043c\u04ef\u0439 \u0433\u0430\u0448\u0442 \u0431\u0430\u0440 \u0442\u0430\u043d\u0438 \u04ef \u043d\u0435\u0448\u0438 \u0445\u0443\u043d\u0444\u0438\u0448\u043e\u043d.\n\u0427\u0443\u043d \u043c\u04ef\u0440 \u043d\u0430\u0440\u043c - \u043d\u0430\u0440\u043c \u049b\u0430\u0434\u0430\u043c\u0440\u043e \u0431\u0430 \u0440\u0430\u04b3 \u043d\u0438\u04b3\u043e\u0434,\n\u041f\u0430\u04b3\u043b\u0443\u0438 \u0441\u0430\u043d\u0433\u043f\u0443\u0448\u0442 \u043d\u0438\u0448\u0430\u0441\u0442\u0443 \u0431\u0438\u0433\u0443\u0444\u0442: - \xab\u04b2\u043e\u043d!\n\u0411\u0430\u0440 \u0433\u0438\u0440\u0434\u0438 \u0445\u0435\u0448 \u043c\u0430\u044a\u0440\u0430\u043a\u0430\u0435 \u04b7\u0430\u043c\u044a \u043a\u0430\u0440\u0434\u0430\u04e3,\n\u0414\u043e\u0440\u04e3 \u0431\u0430 \u043f\u0443\u0448\u0442 \u0441\u0430\u043d\u0434\u0430\u043b\u0438\u0435 \u04b3\u0430\u043c\u0447\u0443 \u049b\u0438\u0441\u0441\u0430\u0445\u043e\u043d.\n\u0423\u044a\u04b7\u0443\u0431\u0430\u0432\u043e\u0440 \u0434\u0430\u0440 \u0442\u0430\u04b3\u0438 \u0441\u0430\u043d\u0434\u0443\u049b \u04b7\u043e \u0448\u0430\u0432\u04e3,\n\u0410\u0439\u0451\u0440\u0438 \u043a\u043e\u0441\u0430\u043f\u0443\u0448\u0442 \u0442\u0443\u0440\u043e \u0430\u0437 \u043c\u0443\u0441\u043e\u04b3\u0438\u0431\u043e\u043d.\n\u0421\u0430\u04b3\u0440\u043e\u0438\u0451\u043d \u0437\u0438 \u043a\u043e\u0441\u0430\u0438 \u0447\u04ef\u0431\u0438\u043d\u0438 \u0442\u0443 \u0431\u0430 \u0442\u0430\u043d\u0433,\n\u0418\u0441\u049b\u043e\u0442\u0438\u0451\u043d\u0443 \u043a\u043e\u0441\u0430\u0433\u0430\u0440\u043e\u043d \u0430\u0437 \u0442\u0443 \u0434\u0430\u0440 \u0444\u0438\u0493\u043e\u043d.\n\u04b2\u0430\u0440\u0433\u0438\u0437 \u043d\u0430\u0434\u0438\u0434\u0430\u0430\u043c \u0431\u0430 \u0431\u0430\u0440\u0430\u0442 \u04b7\u043e\u043c\u0430\u0438 \u0434\u0443\u0440\u0443\u0441\u0442,\n\u0414\u043e\u043c\u043e\u043d\u0438 \u0442\u0443 \u04b3\u0430\u043c\u043e\u043d\u0443 \u0433\u0438\u0440\u0435\u0431\u043e\u043d\u0438 \u0442\u0443 \u04b3\u0430\u043c\u043e\u043d.\n\u0410\u0437 \u0434\u0438\u0434\u0430\u043d\u0438 \u0442\u0443 \u0441\u0443\u04b3\u0431\u0430\u0442\u0438 \u0438\u043d \u049b\u0430\u0432\u043c \u0448\u0443\u0434 \u0445\u0443\u043d\u0443\u043a,\n\u0410\u0439 \u0431\u0430\u0434\u043d\u0430\u043c\u043e\u0439, \u0445\u0435\u0437\u0443 \u0431\u0438\u0440\u0430\u0432 \u0437\u0443\u0434 \u0430\u0437 \u043c\u0438\u0451\u043d!\n\u041c\u0430\u043d \u0443\u043c\u0440\u0438 \u0445\u0443\u0434 \u0431\u0430 \u0445\u043e\u0440\u043a\u0430\u0448\u04e3 \u0441\u0430\u0440\u0444 \u043a\u0430\u0440\u0434\u0430\u0430\u043c,\n\u0417-\u043e\u043d \u0432\u0430\u04b7\u04b3 \u0433\u0430\u0440\u043c\u0440\u04ef\u0439 \u043d\u0430\u043c\u043e\u044f\u043c \u0431\u0430 \u043c\u0430\u0440\u0434\u0443\u043c\u043e\u043d.\n\u041f\u0435\u0440\u043e\u04b3\u0430\u043d\u0435 \u0431\u0430 \u0441\u04ef\u0437\u0430\u043d\u0438 \u0445\u0443\u0434 \u0431\u0430\u0445\u044f \u043a\u0430\u0440\u0434\u0430\u0430\u043c,\n\u0414\u043e\u0440\u0430\u043c \u0431\u0430 \u0434\u04ef\u0448 \u04b7\u043e\u043c\u0430\u0438 \u0448\u043e\u0434\u04e3 \u0447\u0443 \u04b3\u043e\u04b7\u0438\u0451\u043d.\n\u0411\u043e\u0448\u0430\u0434 \u04b3\u0430\u043c\u0435\u0448\u0430 \u0434\u0430\u0440 \u0448\u0430\u0431\u0438 \u043c\u0430\u04b3\u0442\u043e\u0431 \u0445\u043e\u0431\u0438 \u043c\u0430\u043d,\n\u0411\u043e\u043b\u0438\u043d\u0443 \u0431\u0438\u0441\u0442\u0430\u0440\u0430\u043c \u04b3\u0430\u043c\u0430 \u0445\u043e\u0440\u0435\u0441\u0442 \u043f\u0430\u0440\u043d\u0438\u0451\u043d\xbb.\n\u041e\u04b3\u0430\u043d\u0433\u0438 \u0445\u043e\u0440\u043f\u0443\u0448\u0442 \u0447\u0443 \u0440\u04ef\u0431\u043e\u04b3 \u0433\u04ef\u0448 \u043a\u0430\u0440\u0434,\n\u0410\u0437 \u0448\u0438\u0434\u0434\u0430\u0442\u0435 \u043a\u0438 \u0434\u043e\u0448\u0442, \u0440\u0430\u0432\u043e\u043d \u0433\u0430\u0448\u0442 \u0434\u0443\u043c\u0437\u0430\u043d\u043e\u043d.\n\u0424\u0430\u0440\u0451\u0434 \u043a\u0430\u0440\u0434\u0443 \u0433\u0443\u0444\u0442: - \xab\u041c\u0430\u0440\u043e \u0434\u0443\u0440 \u0434\u0438\u0434\u0430\u04e3?\n\u0418\u043c\u0440\u04ef\u0437 \u04b3\u0430\u043c\u0447\u0443 \u0445\u043e\u0440 \u0431\u0430\u0440\u043e\u0432\u0430\u0440\u0434\u0430\u04e3 \u0437\u0430\u0431\u043e\u043d.\n\u0414\u043e\u0440\u04e3 \u0431\u0430 \u0445\u0443\u0434 \u0493\u0443\u0440\u0443\u0440 \u0447\u0443 \u043f\u0438\u0440\u043e\u043d\u0438 \u0445\u043e\u0440\u043a\u0430\u0448,\n\u041e\u0442\u0430\u0448 \u0437\u0430\u043d\u0430\u043c, \u043a\u0438 \u0434\u0443\u0434 \u0431\u0430\u0440\u043e\u044f\u0434 \u0442\u0443\u0440\u043e \u0437\u0438 \u04b7\u043e\u043d!\n\u0410\u0437 \u04b7\u0443\u043d\u0431\u0438\u0448\u0438 \u0442\u0443 \u0434\u0430\u0440 \u04b3\u0430\u0440\u0430\u043a\u0430\u0442 \u0431\u0443\u0442\u0442\u0430\u04b3\u043e\u0438 \u0445\u043e\u0440,\n\u041f\u0430\u0439\u0432\u0430\u0441\u0442\u0430 \u0445\u0443\u0440\u0434\u0443 \u0440\u0435\u0437\u0430\u0438 \u043c\u0430\u043d \u0430\u0437 \u0442\u0443 \u0434\u0430\u0440 \u0433\u0443\u043c\u043e\u043d.\n\u0413\u0430\u0440 \u0431\u0438\u043d\u0438\u0438 \u0442\u0443 \u043a\u0430\u043d\u0434\u0430, \u0431\u0430 \u0434\u0430\u0441\u0442\u0430\u0442 \u0434\u0438\u04b3\u0430\u043c, \u0440\u0430\u0432\u043e\u0441\u0442,\n\u0422\u043e \u043f\u0435\u0448\u0438 \u0445\u0430\u043b\u049b \u0441\u0430\u0440 \u043d\u0430\u0431\u0430\u0440\u043e\u0440\u04e3 \u0431\u0430 \u0438\u043d\u0443 \u043e\u043d.\n\u041c\u0430\u043d \u043c\u0443\u0434\u0434\u0430\u0442\u0435\u0441\u0442, \u0445\u043e\u043d\u0430 \u0434\u0430\u0440 \u0438\u043d \u0434\u0430\u0448\u0442 \u043a\u0430\u0440\u0434\u0430\u0430\u043c,\n\u041d\u0430\u043a\u0448\u043e\u0434\u0430\u0430\u043c \u0431\u0430 \u04b3\u0435\u04b7 \u043a\u0430\u0441 \u0430\u0437 \u0445\u0435\u0448 \u0434\u043e\u0441\u0442\u043e\u043d.\n\u041f\u0430\u04b3\u043b\u0443 \u0431\u0430 \u043e\u0444\u0442\u043e\u0431 \u0437\u0430\u043d\u0430\u0434 \u043f\u04ef\u0441\u0442\u0438\u043d\u0438 \u043c\u0430\u043d,\n\u0414\u043e\u0440\u0430\u043d\u0434 \u043e\u0440\u0437\u0443\u0438 \u043c\u0430\u0440\u043e \u043f\u0438\u0440 \u0442\u043e \u04b7\u0430\u0432\u043e\u043d.\n\u0428\u0430\u0431\u04b3\u043e\u0438 \u0434\u0430\u0439 \u0431\u0430 \u0432\u043e\u0441\u0438\u0442\u0430\u0438 \u043f\u04ef\u0441\u0442 \u043c\u0435\u043a\u0430\u0448\u0430\u043c\n\u0422\u043e \u0441\u0443\u0431\u04b3 \u04b3\u0430\u043c\u0447\u0443 \u043c\u0430\u0493\u0437 \u0434\u0430\u0440 \u043e\u0493\u04ef\u0448 \u0434\u0438\u043b\u0431\u0430\u0440\u043e\u043d.\n\u041e\u0440\u0435, \u0425\u0443\u0434\u043e\u0439\u0440\u043e\u0441\u0442 \u0431\u0430 \u04b3\u0430\u0440 \u043f\u04ef\u0441\u0442 \u0434\u04ef\u0441\u0442\u0435,\n\u04b2\u0430\u0441\u0442 \u0438\u043d \u043c\u0430\u0441\u0430\u043b \u0447\u0443 \u0433\u0430\u043d\u04b7 \u0434\u0430\u0440 \u0430\u0439\u0451\u043c \u0448\u043e\u0439\u0433\u043e\u043d.\n\u0413\u043e\u04b3\u0435 \u043a\u0438 \u0440\u04ef\u0431\u0430\u0440\u04ef\u0439 \u0448\u0430\u0432\u0430\u0434 \u0434\u0443\u0448\u043c\u0430\u043d\u0435 \u043c\u0430\u0440\u043e,\n\u0401\u0431\u0430\u043c \u0437\u0438 \u0440\u04ef\u0438 \u0430\u049b\u043b\u0438 \u0445\u0443\u0434 \u0430\u0437 \u0434\u0430\u0441\u0442\u0438 \u0432\u0430\u0439 \u0430\u043c\u043e\u043d.\n\u0425\u0430\u0440\u0433\u04ef\u0448 \u0441\u0430\u0440 \u0431\u0430 \u0445\u043e\u0431\u0438 \u0444\u0430\u0440\u043e\u0493\u0430\u0442 \u043d\u0438\u04b3\u043e\u0434\u0430 \u0431\u0443\u0434,\n\u0411\u0435\u0434\u043e\u0440 \u0433\u0430\u0448\u0442\u0443 \u0433\u0443\u0444\u0442 \u0431\u0430 \u0440\u04ef\u0431\u043e\u04b3 \u043e\u043d \u0437\u0430\u043c\u043e\u043d:\n\xab\u042f\u043a \u0437\u0430\u0440\u0440\u0430 \u0430\u049b\u043b\u0443 \u04b3\u0443\u0448 \u0430\u0433\u0430\u0440 \u0434\u043e\u0448\u0442\u04e3 \u0431\u0430 \u0441\u0430\u0440,\n\u04b2\u0430\u0440\u0433\u0438\u0437 \u0437\u0438 \u0445\u043e\u043d\u0430 \u043f\u043e \u043d\u0430\u043d\u0438\u04b3\u043e\u0434\u04e3 \u0431\u0430\u0440 \u043e\u0441\u0442\u043e\u043d.\n\u0428\u0430\u0431\u04b3\u043e \u0440\u0430\u0432\u04e3 \u0447\u0443 \u0434\u0443\u0437\u0434 \u0431\u0430 \u0441\u04ef\u0438 \u043c\u0430\u04b3\u0430\u043b\u043b\u0430\u04b3\u043e,\n\u0427\u0430\u0448\u043c\u043e\u043d\u0438 \u0445\u0443\u0434 \u0447\u0430\u0440\u043e\u0493 \u043a\u0443\u043d\u04e3 \u0431\u0430\u04b3\u0440\u0438 \u043c\u043e\u043a\u0438\u0451\u043d.\n\u0411\u0438\u0441\u0451\u0440 \u0437\u0438\u043d\u0434\u0430-\u0437\u0438\u043d\u0434\u0430 \u0442\u0443\u0440\u043e \u043f\u04ef\u0441\u0442 \u043a\u0430\u043d\u0434\u0430\u0430\u043d\u0434,\n\u0410\u0444\u043a\u0430\u043d\u0434\u0430\u0430\u043d\u0434 \u043c\u0443\u0440\u0434\u0430\u0438 \u0442\u0443 \u043f\u0430\u04b3\u043b\u0443\u0438 \u0441\u0430\u0433\u043e\u043d.\n\u0411\u0430\u0440 \u04b3\u0430\u0440 \u043a\u0430\u0441\u0438 \u0444\u0430\u049b\u0438\u0440 \u043c\u0443\u044f\u0441\u0441\u0430\u0440 \u043d\u0430\u043c\u0435\u0448\u0430\u0432\u0430\u043c,\n\u04b6\u043e\u043d \u043c\u0435\u0434\u0438\u04b3\u0430\u043d\u0434 \u0434\u0430\u0440 \u0442\u0430\u043b\u0430\u0431\u0430\u043c \u043c\u0430\u0440\u0434\u0443\u043c\u0438 \u043a\u0430\u043b\u043e\u043d.\n\u041c\u043e\u043b\u0430\u043d\u0434 \u0430\u0433\u0430\u0440 \u0431\u0430 \u043f\u0430\u0439\u043a\u0430\u0440\u0438 \u0445\u0443\u0434 \u0440\u0430\u0432\u0493\u0430\u043d\u0438 \u043c\u0430\u0440\u043e,\n\u0411\u0435\u0448\u0430\u043a\u043a\u0443 \u0448\u0443\u0431\u04b3\u0430, \u0434\u0430\u0444\u044a \u043a\u0443\u043d\u0430\u0434 \u0434\u0430\u0440\u0434\u0438 \u0443\u0441\u0442\u0443\u0445\u043e\u043d.\n\u0413\u043e\u04b3\u0435 \u043a\u0438 \u043c\u0430\u043d \u0431\u0430 \u043e\u0434\u0430\u043c\u0438\u0451\u043d \u0440\u043e\u043c \u043c\u0435\u0448\u0430\u0432\u0430\u043c,\n\u041f\u0430\u0439\u0432\u0430\u0441\u0442\u0430 \u0443\u043c\u0440\u0438 \u0445\u0435\u0448 \u043a\u0443\u043d\u0430\u043c \u0441\u0430\u0440\u0444\u0438 \u043e\u043d \u043c\u0430\u043a\u043e\u043d\xbb.\n\u0425\u0430\u0440\u0433\u04ef\u0448 \u0447\u0443\u043d \u04b3\u0438\u043a\u043e\u044f\u0438 \u0445\u0443\u0434\u0440\u043e \u0442\u0430\u043c\u043e\u043c \u043a\u0430\u0440\u0434,\n\u041c\u0430\u0439\u043c\u0443\u043d \u0448\u0443\u043d\u0438\u0434\u0443 \u043f\u0430\u04b3\u043b\u0443\u044f\u0448 \u043e\u043c\u0430\u0434 \u043d\u0430\u0444\u0430\u0441\u0437\u0430\u043d\u043e\u043d.\n\u0413\u0443\u0444\u0442: - \xab\u0410\u0439 \u0434\u0430\u0440\u043e\u0437\u0433\u04ef\u0448, \u0447\u0430\u0440\u043e \u043b\u043e\u0444 \u043c\u0435\u0437\u0430\u043d\u04e3?\n\u0417-\u043e\u0434\u0430\u043c\u0433\u0430\u0440\u04e3 \u043d\u0430 \u04b3\u0430\u0441\u0442 \u0442\u0443\u0440\u043e \u043d\u043e\u043c\u0443 \u043d\u0430 \u043d\u0438\u0448\u043e\u043d!\n\u0427\u0443\u043d \u043c\u0443\u0448\u0438 \u0434\u0443\u043c\u0431\u0443\u0440\u0438\u0434\u0430 \u043d\u0430\u043c\u043e\u04e3 \u0431\u0430 \u0447\u0430\u0448\u043c\u0438 \u043c\u0430\u043d,\n\u0401 \u0431\u0430\u0447\u0447\u0430\u0438 \u0431\u0443\u0437\u0435, \u043a\u0438 \u0431\u0443\u0432\u0430\u0434 \u04b3\u0430\u0440 \u0442\u0430\u0440\u0430\u0444 \u0434\u0430\u0432\u043e\u043d.\n\u0417\u0438\u043d \u0434\u043e\u0448\u0442\u04e3 \u0431\u0430 \u043f\u0443\u0448\u0442, \u0442\u0443\u0440\u043e \u043c\u0435\u0448\u0443\u0434\u0430\u043c \u0441\u0430\u0432\u043e\u0440,\n\u04b2\u0430\u0441\u0442\u04e3 \u0431\u0430 \u043f\u0435\u0448\u0438 \u043c\u0430\u043d \u0442\u0443 \u04b3\u0430\u043c \u0430\u0437 \u04b7\u0443\u043c\u043b\u0430\u0438 \u0445\u0430\u0440\u043e\u043d.\n\u0411\u0438\u043a\u0448\u043e \u0437\u0438 \u0445\u043e\u0431 \u0447\u0430\u0448\u043c\u0443 \u0441\u0430\u0440\u0438 \u0445\u0443\u0434 \u0431\u0430\u043b\u0430\u043d\u0434 \u043a\u0443\u043d,\n\u0414\u0430\u0440 \u0434\u0430\u0441\u0442\u0443 \u043f\u043e\u0438 \u043c\u0430\u043d \u043d\u0430\u0437\u0430\u0440\u0438 \u0445\u0435\u0448\u0440\u043e \u0431\u0438\u043c\u043e\u043d.\n\u042f\u044a\u043d\u0435, \u043a\u0438 \u043d\u0435\u0441\u0442 \u0441\u0443\u0440\u0430\u0442\u0438 \u043c\u0430\u043d \u043a\u0430\u043c \u0437\u0438 \u043e\u0434\u0430\u043c\u04e3,\n\u0410\u043c\u043c\u043e \u043a\u0430\u0448\u0438\u0434\u0430\u0430\u043c \u049b\u0430\u0434\u0430\u043c\u0438 \u0445\u0443\u0434 \u0430\u0437 \u043e\u043d \u043c\u0438\u0451\u043d.\n\u041d\u0430\u0448\u0432\u0443\u043d\u0430\u043c\u043e\u0438 \u043c\u0430\u043d \u0448\u0443\u0434\u0430 \u0434\u0430\u0440 \u043a\u04ef\u04b3\u0441\u043e\u0440\u0438 \u04b2\u0438\u043d\u0434,\n\u0410\u0441\u043b\u0438 \u043c\u0430\u043d \u0430\u0437 \u0424\u0430\u0440\u0430\u043d\u0433\u0443 \u043c\u0430\u0440\u043e \u043d\u043e\u043c \u043a\u043e\u0440\u0434\u043e\u043d.\n\u04b2\u0430\u0440 \u04b7\u043e \u043a\u0438 \u0431\u0435\u0448\u0430\u0435\u0441\u0442, \u0434\u0430\u0440 \u04ef \u0441\u0430\u0439\u0440 \u043c\u0435\u043a\u0443\u043d\u0430\u043c,\n\u04b2\u0430\u0441\u0442\u0430\u043c \u0431\u0430 \u0433\u0438\u0440\u0434\u0443 \u0433\u04ef\u0448\u0430\u0438 \u04ef \u04b3\u0430\u043c\u0447\u0443 \u0431\u043e\u0493\u0431\u043e\u043d.\n\u0410\u0437 \u043c\u0435\u0432\u0430\u04b3\u043e \u0431\u0430 \u043f\u0430\u04b3\u043b\u0443\u0438 \u0445\u0443\u0434 \u043f\u0430\u04b3\u043d \u043a\u0430\u0440\u0434\u0430\u0430\u043c,\n\u0413\u043e\u04b3\u0435 \u0437\u0438 \u0442\u0443\u0440\u0448\u0443 \u0433\u043e\u04b3 \u0437\u0438 \u0448\u0438\u0440\u0438\u043d\u0443 \u043d\u043e\u0440\u0434\u043e\u043d\xbb.\n\u041e\u04b3\u0443 \u0440\u0430\u0441\u0438\u0434\u0443 \u0433\u0430\u0448\u0442 \u0431\u0430 \u04ef \u0440\u04ef \u0431\u0430 \u0440\u04ef\u0432\u0443 \u0433\u0443\u0444\u0442:\n\xab\u041a\u0430\u043c \u0434\u0438\u0434\u0430\u0435\u043c \u043e\u0434\u0430\u043c\u0438 \u0434\u0443\u043c\u0434\u043e\u0440 \u0434\u0430\u0440 \u04b7\u0430\u04b3\u043e\u043d.\n\u041e\u0434\u0430\u043c \u043a\u0430\u0441\u0435 \u0431\u0430 \u0441\u0443\u0440\u0430\u0442\u0438 \u043e\u0434\u0430\u043c \u043d\u0430\u043c\u0435\u0440\u0430\u0441\u0430\u0434,\n\u0411\u0435 \u043c\u0430\u0493\u0437 \u044d\u044a\u0442\u0438\u0431\u043e\u0440 \u043a\u0443\u04b7\u043e \u0434\u043e\u0440\u0430\u0434 \u0443\u0441\u0442\u0443\u0445\u043e\u043d?\n\u0413\u043e\u04b3\u0435 \u0437\u0438 \u0441\u04ef\u0438 \u0448\u0430\u04b3\u0440 \u0442\u0443\u0440\u043e \u0443\u0444\u0442\u0430\u0434 \u0433\u0443\u0437\u0430\u0440,\n\u0413\u0430\u0440\u0434\u04e3 \u0442\u0443 \u043f\u043e\u0439\u043a\u043e\u0440 \u0431\u0430 \u0430\u0440\u0431\u043e\u0431\u0438 \u043b\u04ef\u043b\u0438\u0451\u043d.\n\u0414\u0430\u0440 \u043f\u0435\u0448\u0438 \u0445\u0430\u043b\u049b \u043c\u0430\u0441\u0445\u0430\u0440\u0430\u0433\u04e3 \u043f\u0435\u0448\u0430 \u043c\u0435\u043a\u0443\u043d\u04e3,\n\u0422\u0438\u0444\u043b\u043e\u043d \u0431\u0430 \u043a\u04ef\u0447\u0430\u04b3\u043e \u0437\u0438 \u049b\u0430\u0444\u043e\u0438 \u0442\u0443 \u043a\u0430\u0444\u0437\u0430\u043d\u043e\u043d.\n\u0413\u0430\u04b3 \u043d\u0430\u0439\u043d\u0430\u0432\u043e\u0437\u0443 \u0433\u043e\u04b3 \u0448\u0443\u0431\u043e\u043d\u04e3, \u0433\u0430\u04b3\u0435 \u0433\u0430\u0434\u043e,\n\u0413\u043e\u04b3\u0435 \u0430\u0441\u043e\u0431\u0430\u0434\u0430\u0441\u0442 \u0448\u0430\u0432\u04e3 \u0430\u0437 \u044f\u0441\u043e\u0432\u0443\u043b\u043e\u043d.\n\u0414\u0430\u0440 \u0434\u0430\u04b3\u0440 \u0430\u0433\u0430\u0440\u0447\u0438 \u0441\u0443\u0440\u0430\u0442\u0438 \u043c\u0430\u043d \u043d\u0435\u0441\u0442 \u043e\u0434\u0430\u043c\u04e3,\n\u041b\u0435\u043a\u0438\u043d \u043c\u0430\u0440\u043e\u0441\u0442 \u0441\u0443\u0440\u0430\u0442\u0438 \u043d\u0435\u043a\u04ef \u0447\u0443 \u0434\u0438\u043b\u0431\u0430\u0440\u043e\u043d.\n\u0427\u0430\u0448\u043c\u0430\u043c \u0431\u0443\u0432\u0430\u0434 \u0437\u0438 \u0493\u0430\u043c\u0437\u0430\u0438 \u041b\u0430\u0439\u043b\u04e3 \u0431\u0430\u0440\u0430\u043d\u0434\u0430\u0442\u0430\u0440,\n\u0414\u0435\u0432\u043e\u043d\u0430\u0438 \u043c\u0430\u043d\u0430\u043d\u0434 \u0447\u0443 \u041c\u0430\u04b7\u043d\u0443\u043d \u043f\u0430\u0440\u0438\u0432\u0430\u0448\u043e\u043d.\n\u0413\u0430\u0440\u0434\u0430\u0434 \u0437\u0438 \u0431\u04ef\u0438 \u043c\u0443\u0448\u043a \u043c\u0443\u0430\u0442\u0442\u0430\u0440 \u0434\u0438\u043c\u043e\u0493\u04b3\u043e,\n\u0411\u0430\u0440 \u04b3\u0430\u0440 \u0442\u0430\u0440\u0430\u0444, \u043a\u0438 \u0440\u04ef\u0439 \u043d\u0438\u04b3\u0430\u043c \u04b3\u0430\u043c\u0447\u0443 \u043d\u0430\u0432\u0445\u0430\u0442\u043e\u043d.\n\u0413\u043e\u04b3\u0435 \u043a\u0438 \u04b3\u0430\u043c\u0447\u0443 \u0431\u043e\u0434 \u0448\u0430\u0432\u0430\u043c \u0434\u0430\u0440 \u0434\u0430\u0432\u0430\u043d\u0434\u0430\u0433\u04e3,\n\u0411\u0430\u0440\u049b\u0438 \u0441\u0438\u0442\u0435\u0437\u0430\u043a\u043e\u0440 \u043d\u0430\u0451\u0431\u0430\u0434 \u0437\u0438 \u043c\u0430\u043d \u043d\u0438\u0448\u043e\u043d\xbb.\n\u0417-\u0438\u043d \u0433\u0443\u0444\u0442\u0443\u0433\u04ef \u043f\u0430\u043b\u0430\u043d\u0433 \u0434\u0430\u0440\u043e\u043c\u0430\u0434 \u0431\u0430 \u04b7\u0430\u0441\u0442\u0443\u0445\u0435\u0437,\n\u0425\u0443\u0434\u0440\u043e \u0440\u0430\u0441\u043e\u043d\u0434 \u0434\u0430\u0440 \u043f\u0430\u0441\u0438 \u043e\u04b3\u0443 \u04b3\u0430\u043c\u043e\u043d \u0437\u0430\u043c\u043e\u043d.\n\u0413\u0443\u0444\u0442: - \xab\u0410\u0439 \u0433\u0443\u0440\u0435\u0437\u043f\u043e\u0439, \u0437\u0438 \u04b7\u0430\u043d\u0433\u0430\u043c \u043a\u0443\u04b7\u043e \u0440\u0430\u0432\u04e3?\n\u0411\u043e \u043c\u0430\u043d \u043c\u0430\u0441\u043e\u0437 \u04b7\u0438\u043b\u0432\u0430\u0433\u0430\u0440\u04e3 \u04b3\u0430\u043c\u0447\u0443 \u0434\u0443\u0445\u0442\u0430\u0440\u043e\u043d!\n\u041d\u043e\u0444\u0438 \u0442\u0443\u0440\u043e \u0431\u0430 \u043a\u043e\u043c\u0438 \u04b3\u0430\u0440\u0438\u0444\u043e\u043d \u0431\u0443\u0440\u0438\u0434\u0430\u0430\u043d\u0434,\n\u0411\u043e\u0448\u0430\u043d\u0434 \u0445\u043e\u043d\u0430\u0432\u043e\u0434\u0430\u0438 \u043c\u0430\u043d \u0430\u0437 \u0442\u0443 \u043a\u043e\u043c\u0440\u043e\u043d.\n\u0413\u0430\u0440 \u0431\u0430\u0440 \u0441\u0430\u0440\u0438 \u0442\u0443 \u0441\u043e\u044f\u0438 \u043a\u0430\u043b\u0445\u043e\u0434 \u0443\u0444\u0442\u0430\u0434,\n\u0414\u0430\u0440 \u0437\u0435\u0440\u0438 \u043f\u043e\u0439 \u0445\u043e\u0431 \u0440\u0430\u0432\u04e3 \u04b3\u0430\u043c\u0447\u0443 \u043c\u043e\u043a\u0438\u0451\u043d.\n\u042f\u044a\u043d\u0435, \u043a\u0438 \u043c\u0430\u043d \u0431\u0430 \u0445\u0443\u043d\u0438 \u0442\u0443 \u0438\u043c\u0440\u04ef\u0437 \u0442\u0430\u0448\u043d\u0430\u0430\u043c,\n\u0410\u0437 \u0440\u043e\u04b3\u0438 \u0442\u0430\u0448\u043d\u0430\u0433\u04e3 \u0431\u0430 \u043b\u0430\u0431\u0438 \u043c\u0430\u043d \u0440\u0430\u0441\u0438\u0434\u0430 \u04b7\u043e\u043d.\n\u0410\u0437 \u049b\u0430\u04b3\u0440 \u0430\u0433\u0430\u0440 \u0431\u0430 \u0445\u043e\u043a \u0437\u0430\u043d\u0430\u043c \u0447\u0430\u043d\u0433\u0438 \u0445\u0435\u0448\u0440\u043e,\n\u0427\u0430\u043d\u0433\u0443 \u0493\u0443\u0431\u043e\u0440 \u0442\u0438\u0440\u0430 \u043a\u0443\u043d\u0430\u0434 \u0440\u04ef\u0438 \u043e\u0441\u043c\u043e\u043d.\n\u0410\u0437 \u0441\u0438\u043b\u0438\u044f\u043c \u043a\u0430\u0431\u0443\u0434 \u0431\u0443\u0432\u0430\u0434 \u0440\u04ef\u0438 \u0444\u0438\u043b\u0438 \u0447\u0430\u0440\u0445,\n\u0410\u043a\u0441\u0438 \u0434\u0443\u043c\u0438 \u043c\u0430\u043d \u0430\u0441\u0442, \u043a\u0438 \u0433\u04ef\u044f\u043d\u0434 \u041a\u0430\u04b3\u043a\u0430\u0448\u043e\u043d\xbb.\n\u041e\u0448\u0443\u0444\u0442\u0430 \u0433\u0430\u0448\u0442 \u0444\u0438\u043b\u0443 \u0440\u0430\u0432\u043e\u043d \u0448\u0443\u0434 \u0441\u0443\u0438 \u043f\u0430\u043b\u0430\u043d\u0433,\n\u0414\u0430\u043d\u0434\u043e\u043d \u0431\u0430 \u044f\u043a\u0434\u0438\u0433\u0430\u0440 \u0437\u0430\u0434\u0430 \u04b3\u0430\u043c\u0447\u0443\u043d \u043c\u0443\u0431\u043e\u0440\u0438\u0437\u043e\u043d.\n\u0414\u0443\u043c \u0445\u043e\u0434\u0430 \u043a\u0430\u0440\u0434\u0430 \u043e\u043c\u0430\u0434\u0443 \u0445\u043e\u0431\u043e\u043d\u0434 \u0433\u04ef\u0448\u0440\u043e,\n\u0425\u0430\u0440\u0442\u0443\u043c \u0431\u0430\u0440 \u0437\u0430\u043c\u0438\u043d \u0437\u0430\u0434\u0443 \u0433\u0443\u0444\u0442: - \xab\u0410\u0439 \u0430\u043b\u043e\u0447\u0430\u043f\u043e\u043d!\n\u0410\u0437 \u043d\u043e\u0445\u0443\u043d\u0438 \u043f\u0430\u043b\u0430\u043d\u0433 \u0447\u04e3 \u043d\u0443\u049b\u0441\u043e\u043d \u0431\u0430 \u043f\u043e\u0438 \u0444\u0438\u043b?\n\u0422\u043e\u04b7\u0438 \u0445\u0443\u0440\u04ef\u0441\u0440\u043e \u0447\u04e3 \u0493\u0430\u043c \u0430\u0437 \u043d\u04ef\u043b\u0438 \u043c\u043e\u043a\u0438\u0451\u043d?\n\u0422\u0443\u043d\u0434\u04e3 \u043c\u0430\u043a\u0443\u043d, \u043a\u0438 \u0447\u0430\u0440\u043c\u0438 \u0442\u0443 \u0431\u0438\u0441\u0451\u0440 \u0434\u0438\u0434\u0430\u0430\u043c\n\u0427\u0443\u043d \u0442\u0430\u0445\u0442\u0430\u043f\u04ef\u0441\u0442 \u0434\u0430\u0440 \u0442\u0430\u04b3\u0438 \u043f\u043e\u0438 \u049b\u0430\u043b\u0430\u043d\u0434\u0430\u0440\u043e\u043d.\n\u0413\u04ef\u04e3, \u043a\u0438 \u04b3\u0435\u04b7 \u043a\u0430\u0441 \u043d\u0430\u0431\u0443\u0432\u0430\u0434 \u0434\u0430\u0440 \u0431\u0430\u0440\u043e\u0431\u0430\u0440\u0430\u043c,\n\u0414\u0430\u0440 \u04b3\u0430\u0440 \u043a\u0430\u043d\u043e\u0440 \u04b3\u0430\u0441\u0442 \u043c\u0430\u0440\u043e \u0447\u0443\u043d \u0442\u0443 \u0447\u043e\u043a\u0430\u0440\u043e\u043d.\n\u0414\u0430\u0440 \u0440\u04ef\u0437\u0438 \u04b7\u0430\u043d\u0433 \u0437\u0435\u0440\u0438 \u0430\u043b\u0430\u043c \u043f\u043e \u0441\u0443\u0442\u0443\u043d \u043a\u0443\u043d\u0430\u043c,\n\u0411\u043e\u0448\u0430\u043c \u0431\u0430\u0440 \u043e\u0441\u0442\u043e\u043d\u0438 \u0434\u0430\u0440\u0438 \u0444\u0430\u0442\u04b3 \u043f\u0443\u0448\u0442\u0431\u043e\u043d...\n\u0427\u0443\u043d \u0442\u0435\u0493\u0438 \u043e\u0431\u0434\u043e\u0440 \u0441\u0430\u0440\u043e\u043f\u043e\u0439 \u04b7\u0430\u0432\u04b3\u0430\u0440\u0430\u043c,\n\u0414\u0430\u043d\u0434\u043e\u043d\u0438 \u043c\u0430\u043d \u0440\u0430\u0432\u043e\u0441\u0442, \u043a\u0438 \u0441\u043e\u0437\u0430\u043d\u0434 \u0437\u0430\u0440\u043d\u0438\u0448\u043e\u043d.\n\u0414\u0430\u0440 \u043f\u0443\u0448\u0442\u0438 \u043c\u0430\u043d \u043d\u0438\u04b3\u0430\u043d\u0434 \u0430\u0433\u0430\u0440 \u043a\u04ef\u04b3\u0438 \u049a\u043e\u0444\u0440\u043e,\n\u041c\u043e\u043d\u0430\u043d\u0434\u0438 \u0431\u0430\u0440\u0433\u0438 \u043a\u043e\u04b3 \u043d\u0430\u0451\u044f\u0434 \u043c\u0430\u0440\u043e \u0433\u0430\u0440\u043e\u043d.\n\u0425\u0430\u0440\u0442\u0443\u043c\u0438 \u043c\u0430\u043d \u0447\u0443 \u0433\u0443\u0440\u0437 \u0431\u0443\u0432\u0430\u0434 \u0432\u0430\u049b\u0442\u0438 \u0433\u0438\u0440\u0443\u0434\u043e\u0440,\n\u04b2\u0430\u0440 \u043c\u04ef\u0438 \u043c\u0430\u043d \u0431\u0430 \u0442\u0443\u043d\u0434\u0438\u0432\u0443 \u0442\u0435\u0437\u04e3 \u0431\u0443\u0432\u0430\u0434 \u0441\u0438\u043d\u043e\u043d.\n\u0423\u043c\u0440\u0430\u043c \u04b3\u0430\u0437\u043e\u0440 \u0441\u043e\u043b \u0431\u0443\u0432\u0430\u0434 \u0434\u0430\u0440 \u043c\u0438\u0451\u043d\u0438 \u0445\u0430\u043b\u049b,\n\u041a\u0430\u043c \u043d\u0435\u0441\u0442 \u0437\u0438\u043d\u0434\u0430\u0433\u043e\u043d\u0438\u044f\u043c \u0430\u0437 \u0443\u043c\u0440\u0438 \u04b7\u043e\u0432\u0438\u0434\u043e\u043d.\n\u0411\u0443\u0437\u0440\u0443\u0433\u0442\u0430\u0440\u0435 \u0437\u0438 \u043c\u0430\u043d \u043d\u0430\u0431\u0443\u0432\u0430\u0434 \u0434\u0430\u0440 \u043c\u0438\u0451\u043d\u0438 \u049b\u0430\u0432\u043c,\n\u0418\u043c\u0440\u04ef\u0437 \u0437\u0438\u043d\u0434\u0430\u0444\u0438\u043b \u043c\u0430\u0440\u043e \u0433\u0443\u0444\u0442\u0430 \u043c\u0435\u0442\u0430\u0432\u043e\u043d\xbb.\n\u041a\u0430\u0440\u043a \u0438\u043d \u0441\u0443\u0445\u0430\u043d \u0437\u0438 \u0444\u0438\u043b \u0448\u0443\u043d\u0438\u0434\u0443 \u049b\u0430\u0434\u0430\u043c \u043d\u0438\u04b3\u043e\u0434,\n\u0421\u0430\u0440 \u0442\u043e \u0431\u0430 \u043f\u043e\u0439 \u0447\u0438\u043d\u0443 \u0433\u0438\u0440\u0435\u04b3 \u043a\u0430\u0440\u0434\u0430 \u0430\u0431\u0440\u0443\u0432\u043e\u043d.\n\u0414\u0430\u0440 \u043f\u0443\u0448\u0442\u0443 \u043f\u0430\u04b3\u043b\u0443\u044f\u0448 \u0445\u0430\u043b\u0430\u0435 \u0437\u0430\u0434 \u0431\u0430 \u0448\u043e\u0445\u0443 \u0433\u0443\u0444\u0442:\n- \xab\u0410\u0439 \u0442\u0430\u043d\u0433\u0447\u0430\u0448\u043c, \u04b3\u0430\u0440\u0444 \u043c\u0430\u0433\u04ef \u0438\u043d \u04b3\u0430\u043c\u0430 \u043a\u0430\u043b\u043e\u043d!\n\u0410\u0437 \u0444\u0438\u043b\u043c\u043e\u0442\u0438 \u04b3\u043e\u0434\u0438\u0441\u0430 \u0493\u043e\u0444\u0438\u043b \u043d\u0438\u0448\u0430\u0441\u0442\u0430\u04e3,\n\u0414\u043e\u0440\u04e3 \u0442\u0443 \u044d\u044a\u0442\u0438\u043c\u043e\u0434 \u0431\u0430 \u0443\u043c\u0440\u0438 \u0441\u0430\u0431\u0443\u043a\u044a\u0438\u043d\u043e\u043d.\n\u0425\u0430\u0440\u0442\u0443\u043c \u043d\u0435\u0441\u0442 \u043e\u043d, \u043a\u0438 \u0431\u0430 \u04ef \u0444\u0430\u0445\u0440 \u043c\u0435\u043a\u0443\u043d\u04e3,\n\u0410\u043d\u0434\u043e\u0445\u0442\u0430 \u0431\u0430 \u0431\u0438\u043d\u0438\u044f\u0442 \u0430\u0439\u0451\u043c \u0440\u0435\u0441\u043c\u043e\u043d...\n\u0425\u0430\u0442 \u043c\u0435\u043a\u0430\u0448\u04e3 \u0431\u0430 \u0431\u0438\u043d\u0438\u0438 \u0445\u0443\u0434 \u043a\u04ef\u0447\u0430\u04b3\u043e\u0438 \u0448\u0430\u04b3\u0440,\n\u0410\u0437 \u043f\u0443\u0448\u0442\u0443 \u043f\u0430\u04b3\u043b\u0443\u0438 \u0442\u0443 \u0493\u0443\u043b\u043e\u043c\u043e\u043d \u0441\u0430\u0432\u043e\u0434\u0445\u043e\u043d...\n\u0420\u04ef\u0437\u0438 \u043c\u0430\u0441\u043e\u0444 \u0441\u0438\u043d\u0430\u0438 \u0445\u0443\u0434 \u043c\u0435\u043a\u0443\u043d\u0430\u043c \u0441\u0438\u043f\u0430\u0440,\n\u0413\u0430\u0440\u0434\u0430\u043d\u0434 \u0440\u04ef\u0431\u0430\u0440\u04ef\u0439 \u0437\u0438 \u043f\u0443\u0448\u0442\u0430\u043c \u0434\u0438\u043b\u043e\u0432\u0430\u0440\u043e\u043d.\n\u0425\u043e\u04b3\u0430\u043c, \u043a\u0438 \u04b3\u0430\u043c\u043b\u0430 \u0434\u0430\u0440 \u0441\u0430\u0444\u0438 \u043f\u0438\u0440\u0443 \u04b7\u0430\u0432\u043e\u043d \u043a\u0443\u043d\u0430\u043c,\n\u0414\u0430\u0440 \u0434\u0438\u043b \u043c\u0430\u0440\u043e \u043d\u0430 \u0431\u0438\u043c \u0437\u0438 \u0442\u0438\u0440\u0443 \u043d\u0430 \u0430\u0437 \u043a\u0430\u043c\u043e\u043d.\n\u0425\u043e\u0441\u0438\u044f\u0442\u0438 \u0430\u04b7\u0438\u0431 \u0431\u0430 \u0448\u043e\u0445\u0430\u043c \u043d\u0430\u0432\u0438\u0448\u0442\u0430\u0430\u043d\u0434.\n\u04b2\u0430\u0440 \u043a\u0430\u0441 \u043d\u0438\u0433\u043e\u04b3 \u0434\u043e\u0448\u0442, \u0433\u0443\u0440\u0435\u0437\u0430\u043d\u0434 \u04b7\u0438\u043d\u043d\u0438\u0451\u043d\xbb.\n\u0428\u0435\u0440 \u0430\u0437 \u043a\u0430\u043c\u0438\u043d \u0431\u0430\u0440\u043e\u043c\u0430\u0434\u0443 \u043e\u043c\u0430\u0434, \u0431\u0430 \u043a\u0430\u0440\u043a \u0433\u0443\u0444\u0442:\n\u2013 \xab\u0410\u0439 \u0448\u043e\u0445\u043d\u043e\u0448\u0438\u043a\u0430\u0441\u0442\u0430, \u0431\u0438\u043a\u0430\u0448 \u043f\u043e\u0439 \u0430\u0437 \u043c\u0438\u0451\u043d!\n\u0411\u043e \u04b3\u0430\u0440 \u043a\u04e3 \u043c\u043e\u043d\u0434\u0430 \u0448\u043e\u0445 \u0431\u0430 \u0448\u043e\u0445 \u0438\u0441\u0442\u043e\u0434\u0430\u04e3,\n\u0410\u0437\u0431\u0430\u0441\u043a\u0438 \u0434\u0430\u0440 \u043a\u0430\u043d\u043e\u0440\u0438 \u0431\u0438\u0451\u0431\u043e\u043d \u0448\u0443\u0434\u04e3 \u043a\u0430\u043b\u043e\u043d.\n\u0410\u0439 \u0441\u0430\u0445\u0442\u0440\u04ef\u0439\u0438 \u0441\u0443\u0441\u0442\u049b\u0430\u0434\u0430\u043c, \u0447\u043e\u0431\u0443\u043a\u04e3 \u043c\u0430\u043a\u0443\u043d,\n\u04b2\u0430\u0441\u0442\u04e3 \u0442\u0443 \u043f\u0435\u0448 \u044f\u043a \u049b\u0430\u0434\u0430\u043c \u0430\u0437 \u0433\u043e\u0432\u0438 \u043f\u043e\u0434\u0430\u0431\u043e\u043d.\n\u0422\u0438\u0444\u043b\u043e\u043d\u0430\u0442 \u0430\u0437 \u0437\u0430\u0431\u043e\u043d\u0438 \u0442\u0443 \u043f\u0430\u0440\u04b3\u0435\u0437 \u043c\u0435\u043a\u0443\u043d\u0430\u043d\u0434,\n\u0411\u043e\u0448\u04e3 \u0442\u0443 \u0434\u0430\u0440 \u043c\u0438\u0451\u043d\u0430\u0438 \u0438\u043d \u049b\u0430\u0432\u043c \u0431\u0430\u0434\u0437\u0430\u0431\u043e\u043d...\n\u0410\u04b7\u0434\u043e\u0434\u0438 \u043c\u0430\u043d \u0431\u0430 \u0448\u0435\u0440\u0438 \u0425\u0443\u0434\u043e \u0434\u0430\u0441\u0442 \u0434\u043e\u0434\u0430\u0430\u043d\u0434,\n\u0410\u0437 \u0447\u0430\u043d\u0433\u0438 \u043c\u0430\u043d \u0432\u0430\u0433\u0430\u0440\u043d\u0430 \u043a\u04e3 \u043c\u0435\u0451\u0444\u0442\u04e3 \u0430\u043c\u043e\u043d?\n\u04b2\u0430\u0440\u0433\u0438\u0437 \u0448\u0438\u043a\u043e\u0440\u0438\u0438 \u0434\u0438\u0433\u0430\u0440\u0435\u0440\u043e \u043d\u0430\u0445\u04ef\u0440\u0434\u0430\u0430\u043c,\n\u042f\u043a \u0440\u0430\u04b3 \u0431\u0430 \u0445\u0443\u043d\u0438 \u043c\u0443\u0440\u0434\u0430 \u043d\u0430\u0451\u043b\u0443\u0434\u0430\u0430\u043c \u0434\u0430\u04b3\u043e\u043d.\n\u0414\u0430\u0440 \u0431\u0435\u0448\u0430\u0435, \u043a\u0438 \u043c\u0435\u0440\u0430\u0432\u0430\u043c\u0443 \u043c\u0435\u043a\u0443\u043d\u0430\u043c \u049b\u0430\u0440\u043e\u0440,\n\u0411\u0435\u0440\u0443\u043d \u0437\u0438 \u049b\u0430\u04b3\u0442\u0441\u043e\u043b \u0448\u0430\u0432\u0430\u043d\u0434 \u0430\u04b3\u043b\u0438 \u043e\u043d \u043c\u0430\u043a\u043e\u043d.\n\u0411\u043e \u04b3\u0430\u0440 \u043a\u04e3 \u0431\u0438\u043d\u0433\u0430\u0440\u0430\u043c, \u04b7\u0438\u0433\u0430\u0440\u0430\u0448 \u043e\u0431 \u043c\u0435\u0448\u0430\u0432\u0430\u0434,\n\u0410\u0437 \u043c\u04ef\u0440 \u043a\u0430\u043c\u0442\u0430\u0440\u0430\u043d\u0434 \u0431\u0430 \u0447\u0430\u0448\u043c\u0430\u043c \u0431\u0430\u04b3\u043e\u0434\u0443\u0440\u043e\u043d\xbb.\n\u0414\u0430\u0440 \u0444\u0438\u043a\u0440\u0438 \u0434\u043e\u043d\u0430 \u043c\u04ef\u0440\u0447\u0430\u0435 \u0431\u0443\u0434 \u0434\u0430\u0440\u0433\u0443\u0437\u0430\u0440,\n\u041e\u043c\u0430\u0434 \u0431\u0430 \u0448\u0435\u0440\u0443 \u0433\u0443\u0444\u0442, \u043a\u0438 - \xab\u0410\u0439 \u0420\u0443\u0441\u0442\u0430\u043c\u0438 \u0437\u0430\u043c\u043e\u043d!\n\u0410\u0437 \u0438\u0442\u0442\u0438\u0444\u043e\u049b\u0438 \u043c\u04ef\u0440\u0447\u0430\u0433\u043e\u043d \u0493\u043e\u0444\u0438\u043b\u04e3 \u043c\u0430\u0433\u0430\u0440\n\u0412-\u0430\u0440\u043d\u0430 \u0447\u0430\u0440\u043e \u04b3\u0430\u049b\u0438\u0440 \u0448\u0443\u043c\u043e\u0440\u0438\u0432\u0443 \u043d\u043e\u0442\u0430\u0432\u043e\u043d?\n\u0425\u04ef\u0440\u043e\u043a\u0438 \u0430\u04b3\u043b\u0438 \u0431\u0430\u0439\u0442\u0438 \u043c\u0430\u043d \u0430\u0441\u0442 \u0430\u0437 \u043d\u0438\u0442\u043e\u04b7\u0438 \u0442\u0443,\n\u0414\u043e\u0438\u043c \u043f\u0443\u0440 \u0430\u0441\u0442 \u0445\u043e\u043d\u0430\u0430\u043c \u0430\u0437 \u0448\u0435\u0440\u0431\u0430\u0447\u0447\u0430\u0433\u043e\u043d.\n\u0422\u0438\u0444\u043b\u043e\u043d\u0438 \u0448\u0438\u0440\u043c\u0430\u0441\u0442\u0438 \u043c\u0430\u043d \u0438\u043c\u0440\u04ef\u0437 \u0448\u0435\u0440\u0433\u0438\u0440,\n\u0425\u0435\u0448\u043e\u043d\u0438 \u043d\u043e\u0442\u0430\u0432\u043e\u043d\u0438 \u043c\u0430\u043d\u0430\u043d\u0434 \u0430\u0437 \u0442\u0443 \u043a\u043e\u043c\u0440\u043e\u043d.\n\u041c\u04ef\u0440\u0435 \u0448\u0443\u043d\u0438\u0434\u0430\u04e3, \u043a\u0438 \u0421\u0443\u043b\u0430\u0439\u043c\u043e\u043d\u0438 \u0432\u0430\u049b\u0442\u0440\u043e\n\u0411\u0430\u0440 \u0430\u04b3\u0434\u0438 \u0445\u0443\u0434 \u0431\u0430 \u0440\u043e\u043d\u0438 \u043c\u0430\u043b\u0430\u0445 \u043a\u0430\u0440\u0434\u0430 \u043c\u0435\u04b3\u043c\u043e\u043d?\n\u0418\u043d \u0440\u0443\u0442\u0431\u0430 \u0448\u0443\u0434 \u043c\u0443\u044f\u0441\u0441\u0430\u0440\u0438 \u04ef \u0430\u0437 \u0448\u0438\u043a\u0430\u0441\u0442\u0430\u0433\u04e3\n\u0412-\u0430\u0440\u043d\u0430 \u0447\u04e3 \u04b3\u0430\u0434\u0434\u0438 \u043c\u04ef\u0440\u0447\u0430\u0432\u0443 \u043b\u0430\u0448\u043a\u0430\u0440\u0438 \u0433\u0430\u0440\u043e\u043d?\xbb\n\u0427\u0443\u043d \u0430\u0437 \u0437\u0430\u0431\u043e\u043d\u0438 \u043c\u04ef\u0440\u0447\u0430 \u0438\u043d \u04b3\u0430\u0440\u0444 \u0448\u0443\u0434 \u0431\u0430\u043b\u0430\u043d\u0434,\n\u0422\u0430\u0441\u043b\u0438\u043c \u043a\u0430\u0440\u0434\u0430-\u043a\u0430\u0440\u0434\u0430 \u0440\u0430\u0441\u0438\u0434\u0430\u043d\u0434 \u0432\u0430\u04b3\u0448\u0438\u0451\u043d...")
