B.atp=new A.P("3395b10b-6cbe-4580-bcd0-1a8197908607","\u0410\u0431\u0443\u0430\u0431\u0434\u0443\u043b\u043b\u043e\u04b3\u0438 \u0420\u04ef\u0434\u0430\u043a\u04e3","858 \u2013 941. \u0410\u0431\u0443\u0430\u0431\u0434\u0443\u043b\u043b\u043e\u04b3\u0438 \u0420\u04ef\u0434\u0430\u043a\u0438\u0440\u043e \u04b3\u0430\u043c\u0430\u0441\u0440\u043e\u043d\u0430\u0448 \u0432\u0430 \u0430\u0434\u0438\u0431\u043e\u043d\u0438 \u0430\u0441\u0440\u04b3\u043e\u0438 \u0431\u0430\u044a\u0434\u04e3 \u04b3\u0430\u043c\u0447\u0443\u043d \xab\u041e\u0434\u0430\u043c\u0443\u0448\u0448\u0443\u0430\u0440\u043e\xbb, \xab\u0443\u0441\u0442\u043e\u0434\xbb, \xab\u0441\u0430\u0440\u0438 \u0448\u043e\u0438\u0440\u043e\u043d\xbb \u0432\u0430 \xab\u0441\u043e\u04b3\u0438\u0431\u049b\u0438\u0440\u043e\u043d\u0438 \u0448\u043e\u0438\u0440\u04e3\xbb \u044d\u044a\u0442\u0438\u0440\u043e\u0444 \u0434\u043e\u0448\u0442\u0430\u043d\u0434. \u0412\u0430\u0439 \u0434\u0430\u0440 \u04b3\u0430\u0448\u0442\u0441\u043e\u043b\u0430\u0433\u0438\u0430\u0448 \u0431\u0430 \u0433\u0443\u0444\u0442\u0430\u043d\u0438 \u0448\u0435\u044a\u0440 \u043e\u0493\u043e\u0437 \u043d\u0430\u043c\u0443\u0434\u0430, \u043e\u0432\u043e\u0437\u0438 \u0445\u0443\u0448 \u0432\u0430 \u0434\u0438\u043b\u043a\u0430\u0448\u0435 \u0434\u043e\u0448\u0442\u0430\u0430\u0441\u0442. \u0417\u043e\u0434\u0433\u043e\u04b3\u0430\u0448 \u041f\u0430\u043d\u04b7\u0440\u04ef\u0434 (\u0432\u043e\u049b\u0435\u044a \u0434\u0430\u0440 \u043d\u043e\u04b3\u0438\u044f\u0438 \u043a\u0443\u043d\u0443\u043d\u0438\u0438 \u041f\u0430\u043d\u04b7\u0430\u043a\u0435\u043d\u0442\u0438 \u0432\u0438\u043b\u043e\u044f\u0442\u0438 \u0421\u0443\u0493\u0434). \u0414\u0430\u0440 \u0434\u0430\u0440\u0431\u043e\u0440\u0438 \u0421\u043e\u043c\u043e\u043d\u0438\u0451\u043d \u0431\u0443\u0437\u0443\u0440\u0433\u0438\u044e \u043d\u0435\u044a\u043c\u0430\u0442 \u0451\u0444\u0442\u0430\u0430\u0441\u0442. \u0425\u0438\u0434\u043c\u0430\u0442\u0438 \u0431\u0443\u0437\u0443\u0440\u0433\u0438 \u0438\u043d \u0448\u043e\u0438\u0440 \u0434\u0430\u0440 \u0430\u0434\u0430\u0431\u0438\u0451\u0442\u0438 \u0442\u043e\u04b7\u0438\u043a \u0434\u0430\u0440 \u043e\u043d \u0430\u0441\u0442, \u043a\u0438 \u0448\u0435\u044a\u0440\u0440\u043e \u04b3\u0430\u043c \u0430\u0437 \u04b7\u0438\u04b3\u0430\u0442\u0438 \u043b\u0430\u0444\u0437 \u0432\u0430 \u04b3\u0430\u043c \u043c\u0430\u044a\u043d\u04e3 \u0431\u0430 \u04b3\u0430\u0434\u0434\u0438 \u043a\u0430\u043c\u043e\u043b\u0443 \u04b7\u0430\u043c\u043e\u043b \u0440\u0430\u0441\u043e\u043d\u0434 \u0432\u0430 \u043f\u0430\u0434\u0430\u0440\u0438 \u0430\u0434\u0430\u0431\u0438\u0451\u0442\u0438 \u0444\u043e\u0440\u0441\u0438\u0438 \u0434\u0430\u0440\u04e3 \u0451 \u0431\u0443\u043d\u0451\u0434\u0433\u0443\u0437\u043e\u0440\u0438 \u043e\u043d \u043c\u0435\u0448\u0443\u043c\u043e\u0440\u0430\u043d\u0434. \u041c\u0435\u0440\u043e\u0441\u0438 \u0431\u043e\u049b\u0438\u043c\u043e\u043d\u0434\u0430\u0438 \u04ef \u0431\u0430 \u0438\u0441\u0442\u0438\u0441\u043d\u043e\u0438 \u0447\u0430\u043d\u0434 \u049b\u0430\u0441\u0438\u0434\u0430, \u0493\u0430\u0437\u0430\u043b, \u0440\u0443\u0431\u043e\u04e3 \u0432\u0430 \u049b\u0438\u0442\u044a\u0430, \u0430\u0441\u043e\u0441\u0430\u043d \u0430\u0437 \u0431\u0430\u0439\u0442\u0443 \u043c\u0438\u0441\u0440\u0430\u044a\u04b3\u043e\u0438 \u043f\u0430\u0440\u043e\u043a\u0430\u043d\u0434\u0430 \u0438\u0431\u043e\u0440\u0430\u0442 \u043c\u0435\u0431\u043e\u0448\u0430\u043d\u0434.")
B.at8=new A.P("b0133115-7ead-4ec8-bc6d-115f4540bdb2","\u0414\u0430\u049b\u0438\u049b\u04e3 (\u0410\u0431\u0443\u043c\u0430\u043d\u0441\u0443\u0440 \u041c\u0443\u04b3\u0430\u043c\u043c\u0430\u0434 \u0431\u0438\u043d\u043d\u0438 \u0410\u04b3\u043c\u0430\u0434\u0438 \u0414\u0430\u049b\u0438\u049b\u04e3)","\u0422\u0430\u0445\u043c\u0438\u043d\u0430\u043d 929/30 \u2013 977/978. \u0410\u0431\u0443\u043c\u0430\u043d\u0441\u0443\u0440 \u041c\u0443\u04b3\u0430\u043c\u043c\u0430\u0434 \u0431\u0438\u043d\u043d\u0438 \u0410\u04b3\u043c\u0430\u0434\u0438 \u0414\u0430\u049b\u0438\u049b\u04e3 \u0430\u0437 \u04b3\u0430\u043c\u0430\u0441\u0440\u043e\u043d\u0438 \u043d\u043e\u043c\u0434\u043e\u0440\u0438 \u0410\u0431\u0443\u0430\u0431\u0434\u0443\u043b\u043b\u043e\u04b3\u0438 \u0420\u04ef\u0434\u0430\u043a\u04e3, \u0431\u0443\u043d\u0451\u0434\u0433\u0443\u0437\u043e\u0440\u0438 \u0430\u0434\u0430\u0431\u0438\u0451\u0442\u0438 \u0444\u043e\u0440\u0441\u0438\u0438 \u0434\u0430\u0440\u04e3 \u0431\u0443\u0434\u0430, \u0442\u0430\u0445\u043c\u0438\u043d\u0430\u043d \u0434\u0430\u0440 \u043c\u0438\u0451\u043d\u0430\u04b3\u043e\u0438 \u043d\u0438\u043c\u0430\u0438 \u0430\u0432\u0432\u0430\u043b\u0438 \u0430\u0441\u0440\u0438 \u0425 \u0434\u0430\u0440 \u0411\u0430\u043b\u0445 \u0431\u0430 \u0434\u0443\u043d\u0451 \u043e\u043c\u0430\u0434\u0430\u0430\u0441\u0442. \u0414\u0430\u049b\u0438\u049b\u04e3 \u043f\u0435\u0448 \u0430\u0437 \u043e\u043d \u043a\u0438 \u0431\u0430 \u043f\u043e\u0439\u0442\u0430\u0445\u0442\u0438 \u0421\u043e\u043c\u043e\u043d\u0438\u0451\u043d \u0431\u0430 \u0411\u0443\u0445\u043e\u0440\u043e \u0431\u0438\u043e\u044f\u0434, \u0437\u0430\u043c\u043e\u043d\u0435 \u0434\u0430\u0440 \u0434\u0430\u0440\u0431\u043e\u0440\u0438 \u0432\u043e\u043b\u0438\u0451\u043d\u0438 \u043e\u043d\u043e\u043d \u0434\u0430\u0440 \u0427\u0430\u0493\u043e\u043d\u0438\u0451\u043d \u0445\u0438\u0434\u043c\u0430\u0442 \u043a\u0430\u0440\u0434\u0430\u0430\u0441\u0442. \u0411\u043e \u0445\u043e\u04b3\u0438\u0448\u0438 \u041d\u0443\u04b3 \u0431\u0438\u043d\u043d\u0438 \u041c\u0430\u043d\u0441\u0443\u0440\u0438 \u0421\u043e\u043c\u043e\u043d\u04e3 \u0431\u0430 \u043d\u0430\u0432\u0438\u0448\u0442\u0430\u043d\u0438 \xab\u0428\u043e\u04b3\u043d\u043e\u043c\u0430\xbb \u043e\u0493\u043e\u0437 \u043a\u0430\u0440\u0434\u0430, \u0442\u043e \u043f\u043e\u0451\u043d\u0438 \u0443\u043c\u0440\u0438 \u043a\u04ef\u0442\u043e\u04b3\u0430\u0448 \u0442\u0430\u0432\u043e\u043d\u0438\u0441\u0442 \u0442\u0430\u043d\u04b3\u043e \u0434\u043e\u0441\u0442\u043e\u043d\u0438 \xab\u0413\u0443\u0448\u0442\u043e\u0441\u043f\xbb-\u0440\u043e \u0434\u0430\u0440 \u04b3\u0443\u0434\u0443\u0434\u0438 1000 \u0431\u0430\u0439\u0442 \u0431\u0430 \u043d\u0430\u0437\u043c \u0434\u0430\u0440\u043e\u0440\u0430\u0434 (\u0431\u0430\u044a\u0437\u0430\u043d \xab\u0413\u0443\u0448\u0442\u043e\u0441\u043f\u043d\u043e\u043c\u0430\xbb \u0433\u04ef\u044f\u043d\u0434). \u0421\u0430\u043d\u0430\u0438 \u049b\u0430\u0442\u043b\u0438 \u0414\u0430\u049b\u0438\u049b\u04e3 \u0442\u0430\u0445\u043c\u0438\u043d\u0430\u043d \u0441\u043e\u043b\u0438 977-978 \u043c\u0435\u0431\u043e\u0448\u0430\u0434.")
B.auG=new A.P("a6dd1c54-753d-4a52-8e5b-5365b7908aa3","\u0410\u0431\u0443\u043b\u049b\u043e\u0441\u0438\u043c\u0438 \u0424\u0438\u0440\u0434\u0430\u0432\u0441\u04e3","940 \u2013 \u0431\u0430\u0439\u043d\u0438 \u0441\u043e\u043b\u04b3\u043e\u0438 1009-1020. \u0410\u0431\u0443\u043b\u049b\u043e\u0441\u0438\u043c\u0438 \u0424\u0438\u0440\u0434\u0430\u0432\u0441\u04e3 \u0433\u04ef\u044f\u043d\u0434\u0430\u0438 \u043d\u043e\u043c\u0438\u0442\u0430\u0440\u0438\u043d \u04b3\u0430\u043c\u043e\u0441\u0430\u0438 \u043c\u0438\u043b\u043b\u0438\u0438 \u049b\u0430\u0432\u043c\u04b3\u043e\u0438 \u044d\u0440\u043e\u043d\u0438\u043d\u0430\u0436\u043e\u0434 \xab\u0428\u043e\u04b3\u043d\u043e\u043c\u0430\xbb \u043c\u0435\u0431\u043e\u0448\u0430\u0434. \u0414\u0430\u0440 \u0441\u043e\u043b\u0438 940 \u043c\u0438\u043b\u043e\u0434\u04e3 \u0434\u0430\u0440 \u0434\u0435\u04b3\u0430\u0438 \u041f\u043e\u0436\u0438 \u0422\u04ef\u0441 (\u0434\u0430\u0440 \u043d\u0430\u0437\u0434\u0438\u043a\u0438\u04b3\u043e\u0438 \u0448\u0430\u04b3\u0440\u0438 \u041c\u0430\u0448\u04b3\u0430\u0434\u0438 \u042d\u0440\u043e\u043d) \u0431\u0430 \u0434\u0443\u043d\u0451 \u043e\u043c\u0430\u0434\u0430\u0430\u0441\u0442. \u0424\u0438\u0440\u0434\u0430\u0432\u0441\u04e3 \u0430\u0437 \u0434\u0435\u04b3\u049b\u043e\u043d\u0437\u043e\u0434\u0430\u0433\u043e\u043d\u0438 \u0437\u0430\u043c\u043e\u043d\u0430\u0448 \u0431\u0443\u0434 (\u0434\u0430\u0440 \u043e\u043d \u0430\u0441\u0440 \u043a\u0430\u043b\u043e\u043d\u0438 \u0440\u0443\u0441\u0442\u043e \u0451 \u0440\u0430\u0438\u0441\u0438 \u0437\u0430\u043c\u0438\u043d\u0434\u043e\u0440\u043e\u043d\u0440\u043e \xab\u0434\u0435\u04b3\u049b\u043e\u043d\xbb \u043c\u0435\u0433\u0443\u0444\u0442\u0430\u043d\u0434). \u04ee \u0434\u0430\u0440 \u0447\u0438\u043b\u0441\u043e\u043b\u0430\u0433\u04e3 \u0431\u0430 \u043d\u0430\u0432\u0438\u0448\u0442\u0430\u043d\u0438 \xab\u0428\u043e\u04b3\u043d\u043e\u043c\u0430\xbb \u0431\u0430\u0440 \u0430\u0441\u043e\u0441\u0438 \u0434\u0430\u0444\u0442\u0430\u0440\u0438 \u043c\u0430\u043d\u0441\u0443\u0440\u0438 \u0410\u0431\u0443\u043c\u0430\u043d\u0441\u0443\u0440\u04e3 \u043e\u0493\u043e\u0437 \u043d\u0430\u043c\u0443\u0434\u0430, \u043e\u043d\u0440\u043e \u0431\u0430\u044a\u0434 \u0430\u0437 \u0441\u04e3 \u0441\u043e\u043b, \u044f\u044a\u043d\u0435 \u0434\u0430\u0440 \u04b3\u0430\u0444\u0442\u043e\u0434\u0441\u043e\u043b\u0430\u0433\u0438\u0430\u0448, \u0434\u0430\u0440 \u0441\u043e\u043b\u0438 1010 \u0431\u0430 \u043f\u043e\u0451\u043d \u0440\u0430\u0441\u043e\u043d\u0438\u0434\u0430\u0430\u0441\u0442.")
